import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export type Mood = 'Happy' | 'Sad' | 'Angry' | 'Tired' | null;

export interface User {
  displayName: string;
  username: string;
  email: string;
  followers: string[];
  following: string[];
  posts: Post[];
  reposts: Post[];
  moodHistory: { date: string, mood: Mood }[];
  profilePic?: string;
}

export interface Post {
  id: string;
  author: string;
  content: string;
  hearts: number;
  comments: Comment[];
  timestamp: number;
  isRepost?: boolean;
  originalAuthor?: string;
}

export interface Comment {
  id: string;
  author: string;
  text: string;
  replies: Comment[];
}

export type Section = 'Home' | 'Mood' | 'Zodiac' | 'CityHall' | 'Profile' | 'Settings';

export interface ZodiacInfo {
  name: string;
  dates: string;
  description: string;
  history: string;
}

import { GoogleGenAI, Type } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const getPsychiatristResponse = async (message: string) => {
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: message,
    config: {
      systemInstruction: "You are Dr. Mood, a compassionate and expert psychiatrist. You provide helpful advice for mental well-being while maintaining a professional yet friendly tone. Always prioritize safety and suggest professional help if serious issues arise.",
    }
  });
  return response.text;
};

export const getNutritionistResponse = async (message: string) => {
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: message,
    config: {
      systemInstruction: "You are Dr. Health, a professional nutritionist and dietitian. You guide users on meal plans, healthy eating habits, and overall wellness. Focus on science-backed nutrition advice.",
    }
  });
  return response.text;
};

export const getTellerResponse = async (question: string) => {
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Predict the answer to this question in a mystical way: ${question}`,
    config: {
      systemInstruction: "You are a mystical fortune teller. Your answers are short, poetic, and slightly mysterious.",
    }
  });
  return response.text;
};

export const getHoroscope = async (sign: string) => {
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Provide a daily horoscope for ${sign} today.`,
    config: {
      systemInstruction: "You are an expert astrologer. Provide a 3-sentence horoscope that is encouraging and insightful.",
    }
  });
  return response.text;
};

export const getLovePrediction = async (sign1: string, sign2: string) => {
    const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Predict love compatibility between ${sign1} and ${sign2}. Return only a JSON object with 'percentage' (0-100) and 'reason' (short string).`,
        config: {
            responseMimeType: "application/json",
            responseSchema: {
                type: Type.OBJECT,
                properties: {
                    percentage: { type: Type.NUMBER },
                    reason: { type: Type.STRING }
                },
                required: ['percentage', 'reason']
            }
        }
    });
    return JSON.parse(response.text);
}

import React, { useState, useEffect, useCallback } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { 
  Home as HomeIcon, 
  Smile, 
  Moon, 
  Building2, 
  User as UserIcon, 
  Settings as SettingsIcon,
  LogOut,
  Trash2,
  Heart,
  MessageCircle,
  Repeat,
  Send,
  UserPlus
} from 'lucide-react';

import { User, Mood, Section, Post, Comment } from './types';
import Sidebar from './components/Sidebar';
import MoodCheckIn from './components/MoodCheckIn';
import HomeSection from './sections/HomeSection';
import MoodSection from './sections/MoodSection';
import ZodiacSection from './sections/ZodiacSection';
import CityHallSection from './sections/CityHallSection';
import ProfileSection from './sections/ProfileSection';
import SettingsSection from './sections/SettingsSection';
import AuthScreen from './sections/AuthScreen';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [activeSection, setActiveSection] = useState<Section>('Home');
  const [isMoodModalOpen, setIsMoodModalOpen] = useState(false);
  const [isDarkMode, setIsDarkMode] = useState(false);
  const [allPosts, setAllPosts] = useState<Post[]>([]);

  // Load from localStorage on mount
  useEffect(() => {
    const savedUser = localStorage.getItem('moodCity_user');
    const savedPosts = localStorage.getItem('moodCity_posts');
    const savedTheme = localStorage.getItem('moodCity_theme');

    if (savedUser) setCurrentUser(JSON.parse(savedUser));
    if (savedPosts) setAllPosts(JSON.parse(savedPosts));
    if (savedTheme === 'dark') setIsDarkMode(true);
  }, []);

  // Save on changes
  useEffect(() => {
    if (currentUser) {
      localStorage.setItem('moodCity_user', JSON.stringify(currentUser));
    }
    localStorage.setItem('moodCity_posts', JSON.stringify(allPosts));
    localStorage.setItem('moodCity_theme', isDarkMode ? 'dark' : 'light');
  }, [currentUser, allPosts, isDarkMode]);

  const handleLogin = (user: User) => {
    setCurrentUser(user);
    const today = new Date().toDateString();
    const hasCheckedMood = user.moodHistory.some(m => m.date === today);
    if (!hasCheckedMood) {
      setIsMoodModalOpen(true);
    }
  };

  const handleLogout = () => {
    setCurrentUser(null);
    setActiveSection('Home');
  };

  const handleDeleteAccount = () => {
    if (window.confirm("Are you sure you want to leave the city permanently? This cannot be undone.")) {
      setCurrentUser(null);
      localStorage.removeItem('moodCity_user');
      alert("Account deleted. Farewell, citizen.");
    }
  };

  const submitMood = (mood: Mood) => {
    if (!currentUser) return;
    const updatedUser = {
      ...currentUser,
      moodHistory: [...currentUser.moodHistory, { date: new Date().toDateString(), mood }]
    };
    setCurrentUser(updatedUser);
    setIsMoodModalOpen(false);
  };

  const addPost = (content: string) => {
    if (!currentUser) return;
    const newPost: Post = {
      id: Math.random().toString(36).substr(2, 9),
      author: currentUser.username,
      content,
      hearts: 0,
      comments: [],
      timestamp: Date.now()
    };
    setAllPosts([newPost, ...allPosts]);
  };

  const toggleHeart = (postId: string) => {
    setAllPosts(prev => prev.map(p => {
      if (p.id === postId) {
        // Toggle logic (simplified: just adding/subtracting 1)
        return { ...p, hearts: p.hearts + 1 }; // Real apps track which user hearted
      }
      return p;
    }));
  };

  const addComment = (postId: string, text: string) => {
    if (!currentUser) return;
    setAllPosts(prev => prev.map(p => {
      if (p.id === postId) {
        const newComment: Comment = {
          id: Math.random().toString(36).substr(2, 9),
          author: currentUser.username,
          text,
          replies: []
        };
        return { ...p, comments: [...p.comments, newComment] };
      }
      return p;
    }));
  };

  const repost = (post: Post) => {
    if (!currentUser) return;
    const newRepost: Post = {
      ...post,
      id: Math.random().toString(36).substr(2, 9),
      isRepost: true,
      originalAuthor: post.author,
      author: currentUser.username,
      timestamp: Date.now()
    };
    setAllPosts([newRepost, ...allPosts]);
    setCurrentUser({
      ...currentUser,
      reposts: [newRepost, ...currentUser.reposts]
    });
  };

  const updateProfile = (displayName: string, username: string) => {
    if (!currentUser) return;
    setCurrentUser({ ...currentUser, displayName, username });
  };

  if (!currentUser) {
    return <AuthScreen onLogin={handleLogin} />;
  }

  return (
    <div className={`min-h-screen ${isDarkMode ? 'bg-slate-900 text-white' : 'bg-gray-50 text-slate-900'} transition-colors duration-300`}>
      <AnimatePresence>
        {isMoodModalOpen && (
          <MoodCheckIn onSubmit={submitMood} isDarkMode={isDarkMode} />
        )}
      </AnimatePresence>

      <div className="flex flex-col md:flex-row min-h-screen">
        <Sidebar 
          activeSection={activeSection} 
          onNavigate={setActiveSection} 
          isDarkMode={isDarkMode}
        />

        <main className="flex-1 p-4 md:p-8 pt-20 md:pt-8 overflow-y-auto">
          <motion.div
            key={activeSection}
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -20 }}
            transition={{ type: "spring", stiffness: 100 }}
            className="max-w-5xl mx-auto"
          >
            {activeSection === 'Home' && (
              <HomeSection user={currentUser} posts={allPosts} isDarkMode={isDarkMode} />
            )}
            {activeSection === 'Mood' && (
              <MoodSection 
                user={currentUser} 
                posts={allPosts} 
                onPost={addPost} 
                onHeart={toggleHeart} 
                onComment={addComment}
                onRepost={repost}
                isDarkMode={isDarkMode}
              />
            )}
            {activeSection === 'Zodiac' && (
              <ZodiacSection isDarkMode={isDarkMode} />
            )}
            {activeSection === 'CityHall' && (
              <CityHallSection isDarkMode={isDarkMode} />
            )}
            {activeSection === 'Profile' && (
              <ProfileSection 
                user={currentUser} 
                allPosts={allPosts} 
                isDarkMode={isDarkMode}
                onEditProfile={updateProfile}
              />
            )}
            {activeSection === 'Settings' && (
              <SettingsSection 
                isDarkMode={isDarkMode} 
                onToggleDarkMode={() => setIsDarkMode(!isDarkMode)}
                onLogout={handleLogout}
                onDelete={handleDeleteAccount}
                user={currentUser}
                onEditProfile={updateProfile}
              />
            )}
          </motion.div>
        </main>
      </div>
    </div>
  );
};

export default App;

