import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { Heart, MessageCircle, Repeat, Send, Search, UserPlus, Brain, Sparkles, Wind } from 'lucide-react';
import { User, Post, Section } from '../types';
import { getTellerResponse } from '../services/geminiService';

interface MoodSectionProps {
  user: User;
  posts: Post[];
  onPost: (content: string) => void;
  onHeart: (postId: string) => void;
  onComment: (postId: string, text: string) => void;
  onRepost: (post: Post) => void;
  isDarkMode: boolean;
}

type MoodSubTab = 'Express' | 'Teller' | 'Quiz' | 'Meditation';

const MoodSection: React.FC<MoodSectionProps> = ({ user, posts, onPost, onHeart, onComment, onRepost, isDarkMode }) => {
  const [subTab, setSubTab] = useState<MoodSubTab>('Express');
  const [postContent, setPostContent] = useState('');
  const [tellerQuestion, setTellerQuestion] = useState('');
  const [tellerAnswer, setTellerAnswer] = useState('');
  const [isTellerLoading, setIsTellerLoading] = useState(false);

  const handlePost = () => {
    if (!postContent.trim()) return;
    onPost(postContent);
    setPostContent('');
  };

  const handleTeller = async () => {
    if (!tellerQuestion.trim()) return;
    setIsTellerLoading(true);
    try {
      const res = await getTellerResponse(tellerQuestion);
      setTellerAnswer(res || "The stars are silent right now...");
    } catch (e) {
      setTellerAnswer("A cloud obscures my vision.");
    } finally {
      setIsTellerLoading(false);
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex gap-2 overflow-x-auto pb-2 scrollbar-hide">
        {['Express', 'Teller', 'Quiz', 'Meditation'].map((tab) => (
          <button
            key={tab}
            onClick={() => setSubTab(tab as MoodSubTab)}
            className={`px-6 py-2 rounded-full font-bold transition-all ${subTab === tab ? 'bg-[#46178f] text-white scale-105 shadow-md' : 'bg-gray-200 dark:bg-slate-700 opacity-70'}`}
          >
            {tab}
          </button>
        ))}
      </div>

      {subTab === 'Express' && (
        <div className="space-y-6">
          <div className={`p-6 rounded-3xl ${isDarkMode ? 'bg-slate-800' : 'bg-white'} shadow-xl`}>
            <textarea
              value={postContent}
              onChange={(e) => setPostContent(e.target.value)}
              placeholder="What's on your mind today, citizen?"
              className={`w-full p-4 rounded-xl border-2 focus:border-[#46178f] outline-none transition-all ${isDarkMode ? 'bg-slate-700 border-slate-600' : 'bg-gray-50 border-gray-100'}`}
              rows={3}
            />
            <div className="flex justify-end mt-4">
              <button 
                onClick={handlePost}
                className="kahoot-button-blue px-8 py-2 text-white rounded-xl font-bold flex items-center gap-2"
              >
                <Send size={18} /> Express It
              </button>
            </div>
          </div>

          <div className="space-y-4">
            {posts.map(post => (
              <motion.div 
                layout
                key={post.id} 
                className={`p-6 rounded-3xl ${isDarkMode ? 'bg-slate-800' : 'bg-white'} shadow-md border-b-4 border-gray-200 dark:border-slate-700`}
              >
                <div className="flex items-center justify-between mb-4">
                  <div className="flex items-center gap-3">
                    <div className="w-10 h-10 rounded-full bg-slate-300"></div>
                    <div>
                      <h4 className="font-bold">@{post.author}</h4>
                      {post.isRepost && <p className="text-xs opacity-50 flex items-center gap-1"><Repeat size={10}/> Reposted from @{post.originalAuthor}</p>}
                    </div>
                  </div>
                  <button className="text-[#1368ce] font-bold text-sm flex items-center gap-1 hover:underline">
                    <UserPlus size={16}/> Follow
                  </button>
                </div>
                <p className="text-lg mb-6 leading-relaxed">{post.content}</p>
                <div className="flex items-center gap-6 pt-4 border-t border-gray-100 dark:border-slate-700">
                  <button onClick={() => onHeart(post.id)} className="flex items-center gap-2 text-red-500 font-bold group">
                    <Heart size={20} className="group-hover:fill-red-500 transition-colors" /> {post.hearts}
                  </button>
                  <button className="flex items-center gap-2 text-blue-500 font-bold">
                    <MessageCircle size={20} /> {post.comments.length}
                  </button>
                  <button onClick={() => onRepost(post)} className="flex items-center gap-2 text-green-500 font-bold">
                    <Repeat size={20} /> Repost
                  </button>
                </div>
              </motion.div>
            ))}
          </div>
        </div>
      )}

      {subTab === 'Teller' && (
        <div className={`p-10 rounded-3xl text-center bg-gradient-to-b from-[#46178f] to-[#1368ce] text-white shadow-2xl`}>
          <Sparkles className="mx-auto mb-6 text-yellow-400" size={60} />
          <h2 className="text-4xl font-black mb-4">THE MYSTIC TELLER</h2>
          <p className="mb-8 opacity-80 text-lg">Ask any question and let the cosmos reveal your destiny.</p>

          <div className="max-w-xl mx-auto space-y-4">
            <input 
              type="text" 
              value={tellerQuestion}
              onChange={(e) => setTellerQuestion(e.target.value)}
              placeholder="Will I find my soulmate this week?"
              className="w-full p-4 rounded-2xl text-slate-900 font-bold text-center focus:outline-none focus:ring-4 ring-yellow-400"
            />
            <button 
              disabled={isTellerLoading}
              onClick={handleTeller}
              className={`w-full p-4 rounded-2xl kahoot-button-yellow text-white font-black text-xl transition-all ${isTellerLoading ? 'opacity-50 animate-pulse' : ''}`}
            >
              {isTellerLoading ? 'CONSULTING ORACLE...' : 'PREDICT MY FATE'}
            </button>
          </div>

          {tellerAnswer && (
            <motion.div 
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              className="mt-12 p-8 bg-white/10 backdrop-blur-md rounded-3xl border border-white/20"
            >
              <p className="text-2xl font-bold italic">"{tellerAnswer}"</p>
            </motion.div>
          )}
        </div>
      )}

      {subTab === 'Quiz' && (
        <div className={`p-8 rounded-3xl ${isDarkMode ? 'bg-slate-800' : 'bg-white'} shadow-xl text-center`}>
          <Brain className="mx-auto mb-6 text-[#26890c]" size={60} />
          <h2 className="text-3xl font-black mb-4 uppercase tracking-tighter">MOOD QUEST</h2>
          <p className="mb-10 opacity-70">Answer a series of questions to uncover your hidden emotional state!</p>

          <div className="max-w-md mx-auto p-10 border-4 border-dashed border-[#26890c] rounded-3xl">
             <h4 className="text-2xl font-bold mb-6">Ready to start?</h4>
             <button className="kahoot-button-green w-full py-4 rounded-2xl text-white font-black text-xl">
               BEGIN QUIZ
             </button>
          </div>
        </div>
      )}

      {subTab === 'Meditation' && (
        <div className={`p-8 rounded-3xl ${isDarkMode ? 'bg-slate-800' : 'bg-white'} shadow-xl text-center`}>
          <Wind className="mx-auto mb-6 text-blue-400" size={60} />
          <h2 className="text-3xl font-black mb-4 uppercase tracking-tighter">Inner Peace</h2>
          <p className="mb-10 opacity-70">Take a moment to breathe and reflect on words of wisdom.</p>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6 text-left">
            <div className="p-8 rounded-3xl bg-blue-50 dark:bg-slate-700 border-2 border-blue-200 dark:border-slate-600">
               <h5 className="font-bold text-blue-500 mb-2 uppercase text-xs">BREATH WORK</h5>
               <p className="font-bold text-xl mb-4">4-7-8 Technique</p>
               <button className="kahoot-button-blue px-6 py-2 text-white rounded-xl font-bold">START TIMER</button>
            </div>
            <div className="p-8 rounded-3xl bg-purple-50 dark:bg-slate-700 border-2 border-purple-200 dark:border-slate-600">
               <h5 className="font-bold text-purple-500 mb-2 uppercase text-xs">WORDS OF WISDOM</h5>
               <p className="font-bold text-lg italic">"Your mind is like water. When it is agitated, it becomes difficult to see. But if you allow it to settle, the answer becomes clear."</p>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default MoodSection;

import React, { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import { Heart, Star, Book, Zap, Calendar } from 'lucide-react';
import { ZODIACS } from '../constants';
import { getHoroscope, getLovePrediction } from '../services/geminiService';

interface ZodiacSectionProps {
  isDarkMode: boolean;
}

type ZodiacTab = 'LoveMatcher' | 'Horoscope' | 'Almanac' | 'LuckyDay';

const ZodiacSection: React.FC<ZodiacSectionProps> = ({ isDarkMode }) => {
  const [tab, setTab] = useState<ZodiacTab>('LoveMatcher');
  const [sign1, setSign1] = useState('Aries');
  const [sign2, setSign2] = useState('Leo');
  const [matchResult, setMatchResult] = useState<{ percentage: number, reason: string } | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [horoscope, setHoroscope] = useState<{ sign: string, text: string } | null>(null);
  const [selectedAlmanac, setSelectedAlmanac] = useState(ZODIACS[0]);

  const handleMatch = async () => {
    setIsLoading(true);
    try {
      const result = await getLovePrediction(sign1, sign2);
      setMatchResult(result);
    } catch (e) {
      setMatchResult({ percentage: 75, reason: "The cosmos is a bit cloudy, but things look hopeful!" });
    } finally {
      setIsLoading(false);
    }
  };

  const handleHoroscope = async (sign: string) => {
    setIsLoading(true);
    try {
      // Check localStorage for today's lock
      const today = new Date().toDateString();
      const saved = localStorage.getItem(`horoscope_${sign}_${today}`);
      if (saved) {
        setHoroscope({ sign, text: saved });
      } else {
        const res = await getHoroscope(sign);
        localStorage.setItem(`horoscope_${sign}_${today}`, res || '');
        setHoroscope({ sign, text: res || 'Consulting stars...' });
      }
    } catch (e) {
      setHoroscope({ sign, text: "A mercury retrograde has blocked the transmission." });
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex gap-2 overflow-x-auto pb-2 scrollbar-hide">
        {['LoveMatcher', 'Horoscope', 'Almanac', 'LuckyDay'].map((t) => (
          <button
            key={t}
            onClick={() => setTab(t as ZodiacTab)}
            className={`px-6 py-2 rounded-full font-bold transition-all whitespace-nowrap ${tab === t ? 'bg-[#26890c] text-white scale-105 shadow-md' : 'bg-gray-200 dark:bg-slate-700 opacity-70'}`}
          >
            {t.replace(/([A-Z])/g, ' $1').trim()}
          </button>
        ))}
      </div>

      {tab === 'LoveMatcher' && (
        <div className={`p-8 rounded-3xl ${isDarkMode ? 'bg-slate-800' : 'bg-white'} shadow-xl text-center`}>
          <Heart className="mx-auto mb-6 text-red-500 animate-pulse" size={60} />
          <h2 className="text-3xl font-black mb-8">LOVE MATCHER</h2>

          <div className="flex flex-col md:flex-row items-center justify-center gap-8 mb-10">
            <div className="space-y-2">
              <label className="text-xs font-bold uppercase opacity-50">Person A</label>
              <select 
                value={sign1}
                onChange={(e) => setSign1(e.target.value)}
                className={`p-4 rounded-xl font-bold border-2 ${isDarkMode ? 'bg-slate-700 border-slate-600' : 'bg-gray-50 border-gray-100'}`}
              >
                {ZODIACS.map(z => <option key={z.name} value={z.name}>{z.name}</option>)}
              </select>
            </div>
            <div className="text-4xl font-black text-red-500">+</div>
            <div className="space-y-2">
              <label className="text-xs font-bold uppercase opacity-50">Person B</label>
              <select 
                value={sign2}
                onChange={(e) => setSign2(e.target.value)}
                className={`p-4 rounded-xl font-bold border-2 ${isDarkMode ? 'bg-slate-700 border-slate-600' : 'bg-gray-50 border-gray-100'}`}
              >
                {ZODIACS.map(z => <option key={z.name} value={z.name}>{z.name}</option>)}
              </select>
            </div>
          </div>

          <button 
            disabled={isLoading}
            onClick={handleMatch}
            className={`kahoot-button-red px-10 py-4 rounded-2xl text-white font-black text-xl mb-10 ${isLoading ? 'opacity-50' : ''}`}
          >
            {isLoading ? 'MATCHING...' : 'CHECK COMPATIBILITY'}
          </button>

          {matchResult && (
            <motion.div 
              initial={{ scale: 0.9, opacity: 0 }}
              animate={{ scale: 1, opacity: 1 }}
              className="p-8 rounded-3xl border-4 border-[#e21b3c] bg-[#e21b3c]/5"
            >
              <p className="text-6xl font-black text-[#e21b3c] mb-2">{matchResult.percentage}%</p>
              <p className="text-xl font-bold italic">"{matchResult.reason}"</p>
            </motion.div>
          )}
        </div>
      )}

      {tab === 'Horoscope' && (
        <div className={`p-8 rounded-3xl ${isDarkMode ? 'bg-slate-800' : 'bg-white'} shadow-xl`}>
          <Star className="mx-auto mb-6 text-yellow-400" size={60} />
          <h2 className="text-3xl font-black text-center mb-8">DAILY HOROSCOPE</h2>
          <div className="grid grid-cols-3 md:grid-cols-4 lg:grid-cols-6 gap-3 mb-10">
            {ZODIACS.map(z => (
              <button
                key={z.name}
                onClick={() => handleHoroscope(z.name)}
                className={`p-3 rounded-xl border-2 font-bold text-sm transition-all hover:border-[#ffa602] ${horoscope?.sign === z.name ? 'border-[#ffa602] bg-[#ffa602]/10' : 'border-transparent bg-gray-100 dark:bg-slate-700'}`}
              >
                {z.name}
              </button>
            ))}
          </div>

          {horoscope && (
            <motion.div 
              initial={{ opacity: 0, x: -20 }}
              animate={{ opacity: 1, x: 0 }}
              className="p-8 rounded-3xl bg-yellow-50 dark:bg-slate-700 border-2 border-yellow-200 dark:border-slate-600 relative overflow-hidden"
            >
              <div className="absolute top-0 right-0 p-4 opacity-10">
                <Star size={100} />
              </div>
              <h4 className="text-2xl font-black text-[#ffa602] mb-2">{horoscope.sign.toUpperCase()}</h4>
              <p className="text-xs font-bold opacity-50 mb-4 uppercase">Prediction for {new Date().toDateString()}</p>
              <p className="text-lg font-semibold leading-relaxed relative z-10">{horoscope.text}</p>
              <div className="mt-6 text-xs italic font-bold text-[#ffa602] border-t border-yellow-200 dark:border-slate-600 pt-4">
                LOCKED UNTIL MIDNIGHT
              </div>
            </motion.div>
          )}
        </div>
      )}

      {tab === 'Almanac' && (
        <div className={`p-8 rounded-3xl ${isDarkMode ? 'bg-slate-800' : 'bg-white'} shadow-xl`}>
          <Book className="mx-auto mb-6 text-[#1368ce]" size={60} />
          <h2 className="text-3xl font-black text-center mb-8">ZODIAC ALMANAC</h2>

          <div className="flex flex-col md:flex-row gap-8">
            <div className="w-full md:w-1/3 space-y-2 h-[400px] overflow-y-auto pr-2 custom-scrollbar">
              {ZODIACS.map(z => (
                <button
                  key={z.name}
                  onClick={() => setSelectedAlmanac(z)}
                  className={`w-full p-4 rounded-xl text-left font-bold transition-all ${selectedAlmanac.name === z.name ? 'bg-[#1368ce] text-white' : 'bg-gray-100 dark:bg-slate-700 hover:bg-gray-200'}`}
                >
                  {z.name}
                </button>
              ))}
            </div>
            <div className="flex-1 p-8 rounded-3xl border-2 border-gray-100 dark:border-slate-700">
               <h3 className="text-4xl font-black text-[#1368ce] mb-2">{selectedAlmanac.name}</h3>
               <p className="text-lg font-bold opacity-70 mb-6">{selectedAlmanac.dates}</p>
               <div className="space-y-6">
                 <div>
                   <h5 className="font-black text-xs uppercase tracking-widest opacity-50 mb-1">Traits</h5>
                   <p className="text-lg">{selectedAlmanac.description}</p>
                 </div>
                 <div>
                   <h5 className="font-black text-xs uppercase tracking-widest opacity-50 mb-1">Ancient Lore</h5>
                   <p className="text-lg italic leading-relaxed">{selectedAlmanac.history}</p>
                 </div>
               </div>
            </div>
          </div>
        </div>
      )}

      {tab === 'LuckyDay' && (
        <div className={`p-8 rounded-3xl ${isDarkMode ? 'bg-slate-800' : 'bg-white'} shadow-xl text-center`}>
          <Zap className="mx-auto mb-6 text-purple-500" size={60} />
          <h2 className="text-3xl font-black mb-8">LUCKY DAY PREDICTOR</h2>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6 max-w-2xl mx-auto">
            <div className="p-8 rounded-3xl bg-purple-500 text-white shadow-lg">
               <h4 className="text-xs font-black uppercase tracking-widest mb-4">Lucky Color</h4>
               <div className="w-16 h-16 rounded-full bg-yellow-400 mx-auto mb-4 border-4 border-white"></div>
               <p className="text-3xl font-black">SUNFLOWER</p>
            </div>
            <div className={`p-8 rounded-3xl ${isDarkMode ? 'bg-slate-700' : 'bg-gray-100'} shadow-lg border-2 border-purple-500`}>
               <h4 className="text-xs font-black uppercase tracking-widest mb-4">Lucky Number</h4>
               <p className="text-7xl font-black text-purple-500">42</p>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default ZodiacSection;

import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { Brain, HeartPulse, Send, Stethoscope, Carrot } from 'lucide-react';
import { getPsychiatristResponse, getNutritionistResponse } from '../services/geminiService';

interface CityHallSectionProps {
  isDarkMode: boolean;
}

const CityHallSection: React.FC<CityHallSectionProps> = ({ isDarkMode }) => {
  const [activeDr, setActiveDr] = useState<'Mood' | 'Health'>('Mood');
  const [moodChat, setMoodChat] = useState<{ role: 'user' | 'bot', text: string }[]>([]);
  const [healthChat, setHealthChat] = useState<{ role: 'user' | 'bot', text: string }[]>([]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  const handleSend = async () => {
    if (!input.trim() || isLoading) return;
    const userMsg = input;
    setInput('');
    setIsLoading(true);

    if (activeDr === 'Mood') {
      setMoodChat(prev => [...prev, { role: 'user', text: userMsg }]);
      const res = await getPsychiatristResponse(userMsg);
      setMoodChat(prev => [...prev, { role: 'bot', text: res || 'I am here for you.' }]);
    } else {
      setHealthChat(prev => [...prev, { role: 'user', text: userMsg }]);
      const res = await getNutritionistResponse(userMsg);
      setHealthChat(prev => [...prev, { role: 'bot', text: res || 'Eat well, live well.' }]);
    }
    setIsLoading(false);
  };

  const currentChat = activeDr === 'Mood' ? moodChat : healthChat;

  return (
    <div className="flex flex-col h-[80vh] gap-6">
      <div className="flex gap-4">
        <button 
          onClick={() => setActiveDr('Mood')}
          className={`flex-1 p-6 rounded-3xl font-black text-xl flex items-center justify-center gap-3 transition-all ${activeDr === 'Mood' ? 'kahoot-button-purple text-white scale-105' : 'bg-gray-200 dark:bg-slate-700 opacity-60'}`}
        >
          <Brain size={28} /> DR. MOOD
        </button>
        <button 
          onClick={() => setActiveDr('Health')}
          className={`flex-1 p-6 rounded-3xl font-black text-xl flex items-center justify-center gap-3 transition-all ${activeDr === 'Health' ? 'kahoot-button-green text-white scale-105' : 'bg-gray-200 dark:bg-slate-700 opacity-60'}`}
        >
          <HeartPulse size={28} /> DR. HEALTH
        </button>
      </div>

      <div className={`flex-1 flex flex-col rounded-3xl ${isDarkMode ? 'bg-slate-800' : 'bg-white'} shadow-2xl overflow-hidden border-4 border-gray-100 dark:border-slate-700`}>
        <div className={`p-4 border-b ${isDarkMode ? 'bg-slate-700/50 border-slate-700' : 'bg-gray-50 border-gray-100'} flex items-center gap-3`}>
          {activeDr === 'Mood' ? <Stethoscope className="text-purple-500" /> : <Carrot className="text-green-500" />}
          <h3 className="font-black italic uppercase">
            Consulting with {activeDr === 'Mood' ? 'Dr. Mood (Psychiatrist)' : 'Dr. Health (Nutritionist)'}
          </h3>
        </div>

        <div className="flex-1 overflow-y-auto p-6 space-y-4 custom-scrollbar">
          {currentChat.length === 0 && (
            <div className="h-full flex flex-col items-center justify-center text-center opacity-40">
              <p className="text-xl font-bold">Start a conversation with {activeDr === 'Mood' ? 'Dr. Mood' : 'Dr. Health'}</p>
              <p className="text-sm">They are here to help you live your best life in Mood City.</p>
            </div>
          )}
          {currentChat.map((msg, i) => (
            <div key={i} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
              <div className={`max-w-[80%] p-4 rounded-2xl font-semibold shadow-sm ${msg.role === 'user' ? 'bg-[#1368ce] text-white rounded-tr-none' : 'bg-gray-100 dark:bg-slate-700 text-slate-800 dark:text-white rounded-tl-none border-b-2 border-gray-200 dark:border-slate-600'}`}>
                {msg.text}
              </div>
            </div>
          ))}
          {isLoading && (
            <div className="flex justify-start">
              <div className="bg-gray-100 dark:bg-slate-700 p-4 rounded-2xl animate-pulse font-bold text-xs">
                {activeDr} is thinking...
              </div>
            </div>
          )}
        </div>

        <div className={`p-4 border-t ${isDarkMode ? 'border-slate-700 bg-slate-800' : 'border-gray-100 bg-white'}`}>
          <div className="flex gap-2">
            <input 
              type="text" 
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && handleSend()}
              placeholder={`Ask Dr. ${activeDr} anything...`}
              className={`flex-1 p-4 rounded-xl border-2 outline-none focus:border-[#46178f] font-bold ${isDarkMode ? 'bg-slate-700 border-slate-600 text-white' : 'bg-gray-50 border-gray-100 text-slate-900'}`}
            />
            <button 
              onClick={handleSend}
              className={`kahoot-button p-4 rounded-xl text-white ${activeDr === 'Mood' ? 'bg-[#46178f]' : 'bg-[#26890c]'}`}
            >
              <Send size={24} />
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default CityHallSection;

import React, { useState } from 'react';
import { User, Post } from '../types';
import { Edit, Heart, MessageCircle, Repeat, Grid, Bookmark, PieChart } from 'lucide-react';

interface ProfileSectionProps {
  user: User;
  allPosts: Post[];
  isDarkMode: boolean;
  onEditProfile: (displayName: string, username: string) => void;
}

const ProfileSection: React.FC<ProfileSectionProps> = ({ user, allPosts, isDarkMode, onEditProfile }) => {
  const [isEditing, setIsEditing] = useState(false);
  const [displayName, setDisplayName] = useState(user.displayName);
  const [username, setUsername] = useState(user.username);
  const [activeTab, setActiveTab] = useState<'Posts' | 'Reposts' | 'Stats'>('Posts');

  const myPosts = allPosts.filter(p => p.author === user.username && !p.isRepost);
  const myReposts = allPosts.filter(p => p.author === user.username && p.isRepost);

  const handleSave = () => {
    onEditProfile(displayName, username);
    setIsEditing(false);
  };

  return (
    <div className="space-y-8">
      <div className={`relative p-8 rounded-[3rem] ${isDarkMode ? 'bg-slate-800' : 'bg-white'} shadow-2xl`}>
        <div className="h-48 w-full rounded-[2rem] bg-gradient-to-r from-[#46178f] to-[#1368ce] absolute top-0 left-0"></div>

        <div className="relative pt-24 px-4 flex flex-col md:flex-row items-end gap-6">
          <div className="w-40 h-40 rounded-[2.5rem] bg-white p-2 shadow-xl">
             <div className="w-full h-full rounded-[2rem] bg-gradient-to-br from-pink-500 via-red-500 to-yellow-500 flex items-center justify-center">
               <span className="text-white text-5xl font-black">{user.displayName[0]}</span>
             </div>
          </div>
          <div className="flex-1 pb-4">
            {isEditing ? (
              <div className="space-y-2">
                <input 
                  className={`text-3xl font-black p-2 rounded-xl w-full border-2 ${isDarkMode ? 'bg-slate-700 border-slate-600' : 'bg-gray-50 border-gray-100'}`}
                  value={displayName}
                  onChange={(e) => setDisplayName(e.target.value)}
                />
                <input 
                  className={`text-xl font-bold opacity-60 p-2 rounded-xl w-full border-2 ${isDarkMode ? 'bg-slate-700 border-slate-600' : 'bg-gray-50 border-gray-100'}`}
                  value={username}
                  onChange={(e) => setUsername(e.target.value)}
                />
              </div>
            ) : (
              <>
                <h2 className="text-4xl font-black italic">{user.displayName}</h2>
                <p className="text-xl font-bold opacity-60 uppercase tracking-tighter">@{user.username}</p>
              </>
            )}
          </div>
          <div className="flex gap-4 pb-4">
             {isEditing ? (
               <button onClick={handleSave} className="kahoot-button-green px-8 py-3 text-white rounded-2xl font-black">SAVE</button>
             ) : (
               <button onClick={() => setIsEditing(true)} className="kahoot-button-blue px-8 py-3 text-white rounded-2xl font-black flex items-center gap-2">
                 <Edit size={20} /> EDIT
               </button>
             )}
          </div>
        </div>

        <div className="mt-8 flex gap-12 border-t border-gray-100 dark:border-slate-700 pt-8 px-4">
           <div className="text-center">
             <p className="text-2xl font-black">{user.followers.length}</p>
             <p className="text-xs font-bold opacity-50 uppercase tracking-widest">Followers</p>
           </div>
           <div className="text-center">
             <p className="text-2xl font-black">{user.following.length}</p>
             <p className="text-xs font-bold opacity-50 uppercase tracking-widest">Following</p>
           </div>
           <div className="text-center">
             <p className="text-2xl font-black">{myPosts.length}</p>
             <p className="text-xs font-bold opacity-50 uppercase tracking-widest">Posts</p>
           </div>
        </div>
      </div>

      <div className="flex gap-4">
         {(['Posts', 'Reposts', 'Stats'] as const).map(tab => (
           <button
             key={tab}
             onClick={() => setActiveTab(tab)}
             className={`flex-1 p-4 rounded-2xl font-black transition-all border-b-4 ${activeTab === tab ? 'bg-[#1368ce] border-[#0e4c99] text-white' : 'bg-gray-200 dark:bg-slate-700 text-gray-500 border-gray-300 dark:border-slate-600'}`}
           >
             {tab.toUpperCase()}
           </button>
         ))}
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {activeTab === 'Posts' && (
          myPosts.length > 0 ? (
            myPosts.map(post => (
              <div key={post.id} className={`p-6 rounded-3xl ${isDarkMode ? 'bg-slate-800' : 'bg-white'} shadow-md border-b-4 border-gray-200 dark:border-slate-700`}>
                <p className="text-lg mb-4">{post.content}</p>
                <div className="flex gap-4 opacity-50 text-sm font-bold">
                  <span className="flex items-center gap-1"><Heart size={16}/> {post.hearts}</span>
                  <span className="flex items-center gap-1"><MessageCircle size={16}/> {post.comments.length}</span>
                </div>
              </div>
            ))
          ) : (
            <div className="col-span-2 text-center py-20 opacity-40 italic">You haven't posted anything yet!</div>
          )
        )}

        {activeTab === 'Reposts' && (
          myReposts.length > 0 ? (
            myReposts.map(post => (
              <div key={post.id} className={`p-6 rounded-3xl ${isDarkMode ? 'bg-slate-800' : 'bg-white'} shadow-md border-b-4 border-gray-200 dark:border-slate-700`}>
                <p className="text-xs font-bold text-green-500 mb-2 flex items-center gap-1"><Repeat size={14}/> REPOSTED FROM @{post.originalAuthor}</p>
                <p className="text-lg mb-4">{post.content}</p>
                <div className="flex gap-4 opacity-50 text-sm font-bold">
                  <span className="flex items-center gap-1"><Heart size={16}/> {post.hearts}</span>
                </div>
              </div>
            ))
          ) : (
            <div className="col-span-2 text-center py-20 opacity-40 italic">No reposts found.</div>
          )
        )}

        {activeTab === 'Stats' && (
          <div className={`col-span-2 p-10 rounded-3xl ${isDarkMode ? 'bg-slate-800' : 'bg-white'} shadow-xl`}>
            <PieChart className="mx-auto mb-6 text-purple-500" size={60} />
            <h3 className="text-2xl font-black text-center mb-8">MOOD DISTRIBUTION</h3>
            <div className="space-y-4">
              {['Happy', 'Sad', 'Angry', 'Tired'].map(m => {
                const count = user.moodHistory.filter(mh => mh.mood === m).length;
                const total = user.moodHistory.length || 1;
                const pct = (count / total) * 100;
                return (
                  <div key={m} className="space-y-1">
                    <div className="flex justify-between text-xs font-black uppercase tracking-widest">
                      <span>{m}</span>
                      <span>{Math.round(pct)}%</span>
                    </div>
                    <div className="w-full h-4 bg-gray-100 dark:bg-slate-700 rounded-full overflow-hidden">
                      <div className={`h-full bg-purple-500 rounded-full transition-all duration-1000`} style={{ width: `${pct}%` }}></div>
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default ProfileSection;

