import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Heart, Star, Book, Zap, Calendar, Sparkles } from 'lucide-react';
import { ZODIACS } from '../constants';
import { getHoroscope, getLovePrediction, getPlanetaryInsights } from '../services/geminiService';

interface ZodiacSectionProps {
  isDarkMode: boolean;
}

type ZodiacTab = 'LoveMatcher' | 'Horoscope' | 'PlanetaryAspects' | 'Almanac' | 'LuckyDay';

const ZodiacSection: React.FC<ZodiacSectionProps> = ({ isDarkMode }) => {
  const [tab, setTab] = useState<ZodiacTab>('LoveMatcher');
  const [sign1, setSign1] = useState('Aries');
  const [sign2, setSign2] = useState('Leo');
  const [matchResult, setMatchResult] = useState<{ percentage: number, reason: string } | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [horoscope, setHoroscope] = useState<{ sign: string, text: string } | null>(null);
  const [planetaryInfo, setPlanetaryInfo] = useState<{ sign: string, text: string } | null>(null);
  const [selectedAlmanac, setSelectedAlmanac] = useState(ZODIACS[0]);

  const handleMatch = async () => {
    setIsLoading(true);
    try {
      const result = await getLovePrediction(sign1, sign2);
      setMatchResult(result);
    } catch (e) {
      setMatchResult({ percentage: 75, reason: "The stars suggest a strong bond, despite minor friction in the outer orbits." });
    } finally {
      setIsLoading(false);
    }
  };

  const handlePlanetaryInsights = async (sign: string) => {
    setIsLoading(true);
    try {
      const res = await getPlanetaryInsights(sign);
      setPlanetaryInfo({ sign, text: res || 'Consulting planetary movements...' });
    } catch (e) {
      setPlanetaryInfo({ sign, text: "The planetary alignment is currently obscured." });
    } finally {
      setIsLoading(false);
    }
  };

  const handleHoroscope = async (sign: string) => {
    setIsLoading(true);
    try {
      const today = new Date().toDateString();
      const saved = localStorage.getItem(`horoscope_${sign}_${today}`);
      if (saved) {
        setHoroscope({ sign, text: saved });
      } else {
        const res = await getHoroscope(sign);
        localStorage.setItem(`horoscope_${sign}_${today}`, res || '');
        setHoroscope({ sign, text: res || 'Consulting stars...' });
      }
    } catch (e) {
      setHoroscope({ sign, text: "A mercury retrograde has blocked the transmission." });
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="space-y-6 pb-20">
      <div className="flex gap-2 overflow-x-auto pb-2 scrollbar-hide">
        {['LoveMatcher', 'Horoscope', 'PlanetaryAspects', 'Almanac', 'LuckyDay'].map((t) => (
          <button
            key={t}
            onClick={() => setTab(t as ZodiacTab)}
            className={`px-6 py-2 rounded-full font-bold transition-all whitespace-nowrap ${tab === t ? 'bg-[#26890c] text-white scale-105 shadow-md' : 'bg-gray-200 dark:bg-slate-700 opacity-70'}`}
          >
            {t.replace(/([A-Z])/g, ' $1').trim()}
          </button>
        ))}
      </div>

      {tab === 'LoveMatcher' && (
        <div className={`p-8 rounded-3xl ${isDarkMode ? 'bg-slate-800' : 'bg-white'} shadow-xl text-center`}>
          <Heart className="mx-auto mb-6 text-red-500 animate-pulse" size={60} />
          <h2 className="text-3xl font-black mb-8 uppercase">Love Matcher</h2>
          <div className="flex flex-col md:flex-row items-center justify-center gap-8 mb-10">
            <div className="space-y-2">
              <label className="text-xs font-bold uppercase opacity-50">Person A</label>
              <select value={sign1} onChange={(e) => setSign1(e.target.value)} className={`p-4 rounded-xl font-bold border-2 ${isDarkMode ? 'bg-slate-700 border-slate-600' : 'bg-gray-50 border-gray-100'}`}>
                {ZODIACS.map(z => <option key={z.name} value={z.name}>{z.name}</option>)}
              </select>
            </div>
            <div className="text-4xl font-black text-red-500">+</div>
            <div className="space-y-2">
              <label className="text-xs font-bold uppercase opacity-50">Person B</label>
              <select value={sign2} onChange={(e) => setSign2(e.target.value)} className={`p-4 rounded-xl font-bold border-2 ${isDarkMode ? 'bg-slate-700 border-slate-600' : 'bg-gray-50 border-gray-100'}`}>
                {ZODIACS.map(z => <option key={z.name} value={z.name}>{z.name}</option>)}
              </select>
            </div>
          </div>
          <button disabled={isLoading} onClick={handleMatch} className={`kahoot-button-red px-10 py-4 rounded-2xl text-white font-black text-xl mb-10 ${isLoading ? 'opacity-50' : ''}`}>
            {isLoading ? 'MATCHING...' : 'CHECK COMPATIBILITY'}
          </button>
          {matchResult && (
            <motion.div initial={{ scale: 0.9, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} className="p-8 rounded-3xl border-4 border-[#e21b3c] bg-[#e21b3c]/5">
              <p className="text-6xl font-black text-[#e21b3c] mb-4">{matchResult.percentage}%</p>
              <div className="text-left bg-white/50 dark:bg-slate-900/50 p-6 rounded-2xl">
                 <h4 className="font-black text-xs uppercase tracking-widest opacity-50 mb-2">Cosmic Reasoning</h4>
                 <p className="text-lg font-bold leading-relaxed">{matchResult.reason}</p>
              </div>
            </motion.div>
          )}
        </div>
      )}

      {tab === 'Horoscope' && (
        <div className={`p-8 rounded-3xl ${isDarkMode ? 'bg-slate-800' : 'bg-white'} shadow-xl`}>
          <Star className="mx-auto mb-6 text-yellow-400" size={60} />
          <h2 className="text-3xl font-black text-center mb-8 uppercase">Daily Reading</h2>
          <div className="grid grid-cols-3 md:grid-cols-4 lg:grid-cols-6 gap-3 mb-10">
            {ZODIACS.map(z => (
              <button key={z.name} onClick={() => handleHoroscope(z.name)} className={`p-3 rounded-xl border-2 font-bold text-sm transition-all hover:border-[#ffa602] ${horoscope?.sign === z.name ? 'border-[#ffa602] bg-[#ffa602]/10' : 'border-transparent bg-gray-100 dark:bg-slate-700'}`}>
                {z.name}
              </button>
            ))}
          </div>
          {horoscope && (
            <motion.div initial={{ opacity: 0, x: -20 }} animate={{ opacity: 1, x: 0 }} className="p-8 rounded-3xl bg-yellow-50 dark:bg-slate-700 border-2 border-yellow-200 dark:border-slate-600 relative overflow-hidden">
              <h4 className="text-2xl font-black text-[#ffa602] mb-2">{horoscope.sign.toUpperCase()}</h4>
              <p className="text-lg font-semibold leading-relaxed relative z-10">{horoscope.text}</p>
              <div className="mt-6 text-xs italic font-bold text-[#ffa602] border-t border-yellow-200 pt-4">LOCKED UNTIL MIDNIGHT</div>
            </motion.div>
          )}
        </div>
      )}

      {tab === 'PlanetaryAspects' && (
        <div className={`p-8 rounded-3xl ${isDarkMode ? 'bg-slate-800' : 'bg-white'} shadow-xl`}>
          <Sparkles className="mx-auto mb-6 text-purple-500" size={60} />
          <h2 className="text-3xl font-black text-center mb-4 uppercase">Cosmic Aspects</h2>
          <p className="text-center opacity-60 mb-8 font-bold">Deep planetary influences on your current state of being.</p>
          <div className="grid grid-cols-3 md:grid-cols-4 lg:grid-cols-6 gap-3 mb-10">
            {ZODIACS.map(z => (
              <button key={z.name} onClick={() => handlePlanetaryInsights(z.name)} className={`p-3 rounded-xl border-2 font-bold text-sm transition-all hover:border-purple-500 ${planetaryInfo?.sign === z.name ? 'border-purple-500 bg-purple-500/10' : 'border-transparent bg-gray-100 dark:bg-slate-700'}`}>
                {z.name}
              </button>
            ))}
          </div>
          {planetaryInfo && (
            <motion.div initial={{ opacity: 0, scale: 0.95 }} animate={{ opacity: 1, scale: 1 }} className="p-10 rounded-[2.5rem] bg-gradient-to-br from-indigo-500 to-purple-600 text-white shadow-2xl relative overflow-hidden">
               <div className="absolute -top-10 -right-10 w-40 h-40 bg-white/10 rounded-full blur-3xl"></div>
               <h4 className="text-3xl font-black mb-6 uppercase tracking-widest">{planetaryInfo.sign} Transits</h4>
               <p className="text-xl leading-relaxed italic font-medium">"{planetaryInfo.text}"</p>
            </motion.div>
          )}
        </div>
      )}

      {tab === 'Almanac' && (
        <div className={`p-8 rounded-3xl ${isDarkMode ? 'bg-slate-800' : 'bg-white'} shadow-xl`}>
          <Book className="mx-auto mb-6 text-[#1368ce]" size={60} />
          <h2 className="text-3xl font-black text-center mb-8 uppercase">Zodiac Almanac</h2>
          <div className="flex flex-col md:flex-row gap-8">
            <div className="w-full md:w-1/3 space-y-2 h-[400px] overflow-y-auto pr-2 custom-scrollbar">
              {ZODIACS.map(z => (
                <button key={z.name} onClick={() => setSelectedAlmanac(z)} className={`w-full p-4 rounded-xl text-left font-bold transition-all ${selectedAlmanac.name === z.name ? 'bg-[#1368ce] text-white' : 'bg-gray-100 dark:bg-slate-700 hover:bg-gray-200'}`}>
                  {z.name}
                </button>
              ))}
            </div>
            <div className="flex-1 p-8 rounded-3xl border-2 border-gray-100 dark:border-slate-700">
               <h3 className="text-4xl font-black text-[#1368ce] mb-2">{selectedAlmanac.name}</h3>
               <p className="text-lg font-bold opacity-70 mb-6">{selectedAlmanac.dates}</p>
               <div className="space-y-6">
                 <div>
                   <h5 className="font-black text-xs uppercase tracking-widest opacity-50 mb-1">Traits</h5>
                   <p className="text-lg">{selectedAlmanac.description}</p>
                 </div>
                 <div>
                   <h5 className="font-black text-xs uppercase tracking-widest opacity-50 mb-1">Ancient Lore</h5>
                   <p className="text-lg italic leading-relaxed">{selectedAlmanac.history}</p>
                 </div>
               </div>
            </div>
          </div>
        </div>
      )}

      {tab === 'LuckyDay' && (
        <div className={`p-8 rounded-3xl ${isDarkMode ? 'bg-slate-800' : 'bg-white'} shadow-xl text-center`}>
          <Zap className="mx-auto mb-6 text-purple-500" size={60} />
          <h2 className="text-3xl font-black mb-8 uppercase">Lucky Day Predictor</h2>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6 max-w-2xl mx-auto">
            <div className="p-8 rounded-3xl bg-purple-500 text-white shadow-lg">
               <h4 className="text-xs font-black uppercase tracking-widest mb-4">Lucky Color</h4>
               <div className="w-16 h-16 rounded-full bg-yellow-400 mx-auto mb-4 border-4 border-white"></div>
               <p className="text-3xl font-black uppercase">Sunflower</p>
            </div>
            <div className={`p-8 rounded-3xl ${isDarkMode ? 'bg-slate-700' : 'bg-gray-100'} shadow-lg border-2 border-purple-500`}>
               <h4 className="text-xs font-black uppercase tracking-widest mb-4">Lucky Number</h4>
               <p className="text-7xl font-black text-purple-500">42</p>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

