        )}
        {activeTab === 'Stats' && (
          <div className={`col-span-2 p-10 rounded-3xl ${isDarkMode ? 'bg-slate-800' : 'bg-white'} shadow-xl`}>
            <PieChart className="mx-auto mb-6 text-purple-500" size={60} />
