                      <div className={`h-full bg-gradient-to-r from-purple-500 to-indigo-500 rounded-full transition-all duration-1000`} style={{ width: `${pct}%` }}></div>
                    </div>
                  </div>
                );
              })}
            </div>
            {user.moodStreak >= 7 && (
               <div className="mt-10 p-4 border-2 border-dashed border-green-500 rounded-2xl flex items-center gap-4 bg-green-50 dark:bg-green-900/10">
                  <ShieldCheck className="text-green-500" size={32} />
