                    <p className="font-black text-green-600 dark:text-green-400">UNLOCKED: MASTER LOGER BADGE</p>
                    <p className="text-xs font-bold opacity-60 italic">You've logged moods for 7 consecutive days!</p>
                  </div>
               </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
};

