import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { Heart, MessageCircle, Repeat, Send, UserPlus, UserMinus, Brain, Sparkles, Wind, ShieldAlert } from 'lucide-react';
import { User, Post } from '../types';
import { getTellerResponse } from '../services/geminiService';

interface MoodSectionProps {
  user: User;
  posts: Post[];
  onPost: (content: string) => void;
  onHeart: (postId: string) => void;
  onComment: (postId: string, text: string) => void;
  onRepost: (post: Post) => void;
  onFollow: (username: string) => void;
  onBlock: (username: string) => void;
  isDarkMode: boolean;
}

type MoodSubTab = 'Express' | 'Teller' | 'Quiz' | 'Meditation';

const MoodSection: React.FC<MoodSectionProps> = ({ user, posts, onPost, onHeart, onComment, onRepost, onFollow, onBlock, isDarkMode }) => {
  const [subTab, setSubTab] = useState<MoodSubTab>('Express');
  const [postContent, setPostContent] = useState('');
  const [tellerQuestion, setTellerQuestion] = useState('');
  const [tellerAnswer, setTellerAnswer] = useState('');
  const [isTellerLoading, setIsTellerLoading] = useState(false);
  const [feedFilter, setFeedFilter] = useState<'All' | 'Following'>('All');

  const filteredPosts = feedFilter === 'All' 
    ? posts 
    : posts.filter(p => user.following.includes(p.author) || p.author === user.username);

  const handlePost = () => {
    if (!postContent.trim()) return;
    onPost(postContent);
    setPostContent('');
  };

  const handleTeller = async () => {
    if (!tellerQuestion.trim()) return;
    setIsTellerLoading(true);
    try {
      const res = await getTellerResponse(tellerQuestion);
      setTellerAnswer(res || "The stars are silent right now...");
    } catch (e) {
      setTellerAnswer("A cloud obscures my vision.");
    } finally {
      setIsTellerLoading(false);
    }
  };

  return (
    <div className="space-y-6 pb-20">
      <div className="flex justify-between items-center">
        <div className="flex gap-2 overflow-x-auto pb-2 scrollbar-hide">
          {['Express', 'Teller', 'Quiz', 'Meditation'].map((tab) => (
            <button
              key={tab}
              onClick={() => setSubTab(tab as MoodSubTab)}
              className={`px-6 py-2 rounded-full font-bold transition-all ${subTab === tab ? 'bg-[#46178f] text-white scale-105 shadow-md' : 'bg-gray-200 dark:bg-slate-700 opacity-70 text-slate-600 dark:text-slate-300'}`}
            >
              {tab}
            </button>
          ))}
        </div>
      </div>

      {subTab === 'Express' && (
        <div className="space-y-6">
          <div className="flex gap-2 p-1 bg-gray-200 dark:bg-slate-800 rounded-xl w-fit">
            <button 
              onClick={() => setFeedFilter('All')} 
              className={`px-4 py-1.5 rounded-lg text-sm font-bold transition-all ${feedFilter === 'All' ? 'bg-white dark:bg-slate-700 shadow-sm text-slate-900 dark:text-white' : 'opacity-50 text-slate-600 dark:text-slate-400'}`}
            >
              All Moods
            </button>
            <button 
              onClick={() => setFeedFilter('Following')} 
              className={`px-4 py-1.5 rounded-lg text-sm font-bold transition-all ${feedFilter === 'Following' ? 'bg-white dark:bg-slate-700 shadow-sm text-slate-900 dark:text-white' : 'opacity-50 text-slate-600 dark:text-slate-400'}`}
            >
              Following
            </button>
          </div>

          <div className={`p-6 rounded-3xl ${isDarkMode ? 'bg-slate-800' : 'bg-white'} shadow-xl`}>
            <textarea
              value={postContent}
              onChange={(e) => setPostContent(e.target.value)}
              placeholder="What's your emotional status today, citizen?"
              className={`w-full p-4 rounded-xl border-2 focus:border-[#46178f] outline-none transition-all ${isDarkMode ? 'bg-slate-700 border-slate-600 text-white' : 'bg-gray-50 border-gray-100 text-slate-900'}`}
              rows={3}
            />
            <div className="flex justify-end mt-4">
              <button 
                onClick={handlePost}
                className="kahoot-button-blue px-8 py-2 text-white rounded-xl font-bold flex items-center gap-2"
              >
                <Send size={18} /> EXPRESS IT
              </button>
            </div>
          </div>

          <div className="space-y-4">
            {filteredPosts.map(post => {
              const isFollowing = user.following.includes(post.author);
              const isSelf = post.author === user.username;

              return (
                <motion.div 
                  layout
                  key={post.id} 
                  className={`p-6 rounded-3xl ${isDarkMode ? 'bg-slate-800 text-white' : 'bg-white text-slate-900'} shadow-md border-b-4 border-gray-200 dark:border-slate-700`}
                >
                  <div className="flex items-center justify-between mb-4">
                    <div className="flex items-center gap-3">
                      <div className="w-10 h-10 rounded-full bg-gradient-to-tr from-blue-400 to-purple-400"></div>
                      <div>
                        <h4 className="font-bold">@{post.author}</h4>
                        {post.isRepost && <p className="text-xs opacity-50 flex items-center gap-1"><Repeat size={10}/> Reposted from @{post.originalAuthor}</p>}
                      </div>
                    </div>
                    {!isSelf && (
                      <div className="flex items-center gap-2">
                        <button 
                          onClick={() => onFollow(post.author)}
                          className={`font-bold text-sm flex items-center gap-1 px-4 py-1.5 rounded-full border-2 transition-all ${isFollowing ? 'border-gray-300 text-gray-500' : 'border-[#1368ce] text-[#1368ce] hover:bg-blue-50'}`}
                        >
                          {isFollowing ? <UserMinus size={16}/> : <UserPlus size={16}/>}
                          {isFollowing ? 'Following' : 'Follow'}
                        </button>
                        <button 
                          onClick={() => onBlock(post.author)}
                          title="Block User"
                          className="p-2 rounded-full text-red-400 hover:bg-red-50 dark:hover:bg-red-900/10 transition-colors"
                        >
                          <ShieldAlert size={18} />
                        </button>
                      </div>
                    )}
                  </div>
                  <p className="text-lg mb-6 leading-relaxed">{post.content}</p>
                  <div className="flex items-center gap-6 pt-4 border-t border-gray-100 dark:border-slate-700">
                    <button onClick={() => onHeart(post.id)} className="flex items-center gap-2 text-red-500 font-bold group">
                      <Heart size={20} className="group-hover:fill-red-500 transition-colors" /> {post.hearts}
                    </button>
                    <button className="flex items-center gap-2 text-blue-500 font-bold">
                      <MessageCircle size={20} /> {post.comments.length}
                    </button>
                    <button onClick={() => onRepost(post)} className="flex items-center gap-2 text-green-500 font-bold">
                      <Repeat size={20} /> Repost
                    </button>
                  </div>
                </motion.div>
              );
            })}
          </div>
        </div>
      )}
      {/* ... other subtabs ... */}
    </div>
  );
};

export default MoodSection;

