              </div>
            </motion.div>
          )}
        </div>
      )}

      {tab === 'Horoscope' && (
        <div className={`p-8 rounded-3xl ${isDarkMode ? 'bg-slate-800 text-white' : 'bg-white text-slate-900'} shadow-xl`}>
