          {horoscope && (
            <motion.div initial={{ opacity: 0, x: -20 }} animate={{ opacity: 1, x: 0 }} className={`p-8 rounded-3xl border-2 border-yellow-200 dark:border-slate-600 ${isDarkMode ? 'bg-slate-700' : 'bg-white'}`}>
              <h4 className="text-2xl font-black text-[#ffa602] mb-2">{horoscope.sign.toUpperCase()}</h4>
              <p className={`text-lg font-semibold leading-relaxed ${isDarkMode ? 'text-white' : 'text-slate-900'}`}>{horoscope.text}</p>
            </motion.div>
          )}
        </div>
      )}

      {tab === 'PlanetaryAspects' && (
        <div className={`p-8 rounded-3xl ${isDarkMode ? 'bg-slate-800 text-white' : 'bg-white text-slate-900'} shadow-xl`}>
          <Sparkles className="mx-auto mb-6 text-purple-500" size={60} />
          <h2 className="text-3xl font-black text-center mb-4 uppercase">Cosmic Aspects</h2>
          <div className="grid grid-cols-3 md:grid-cols-4 lg:grid-cols-6 gap-3 mb-10">
            {ZODIACS.map(z => (
              <button key={z.name} onClick={() => handlePlanetaryInsights(z.name)} className={`p-3 rounded-xl border-2 font-bold text-sm transition-all ${planetaryInfo?.sign === z.name ? 'border-purple-500 bg-purple-500/10 text-purple-500' : 'border-transparent bg-gray-100 dark:bg-slate-700 text-slate-700 dark:text-slate-300'}`}>
                {z.name}
