              ))}
            </div>
            <div className="flex-1 p-8 rounded-3xl border-2 border-gray-100 dark:border-slate-700">
               <h3 className="text-4xl font-black text-[#1368ce] mb-2">{selectedAlmanac.name}</h3>
               <p className={`text-lg font-bold opacity-70 mb-6 ${isDarkMode ? 'text-white' : 'text-slate-900'}`}>{selectedAlmanac.dates}</p>
               <div className="space-y-6">
                 <div>
                   <h5 className={`font-black text-xs uppercase tracking-widest opacity-50 mb-1 ${isDarkMode ? 'text-white' : 'text-slate-900'}`}>Traits</h5>
