          <Zap className="mx-auto mb-6 text-purple-500" size={60} />
          <h2 className="text-3xl font-black mb-8 uppercase">Lucky Day Predictor</h2>
          <div className="mb-10 max-w-xs mx-auto">
             <select 
               value={luckyZodiac} 
               onChange={(e) => setLuckyZodiac(e.target.value)} 
               className={`w-full p-4 rounded-xl font-bold border-2 ${isDarkMode ? 'bg-slate-700 border-slate-600 text-white' : 'bg-white border-gray-100 text-slate-900'}`}
