export default ZodiacSection;

export type Mood = 'Happy' | 'Sad' | 'Angry' | 'Tired' | null;

export interface Badge {
  id: string;
  name: string;
  icon: string;
  description: string;
  threshold: number;
}

export interface User {
  displayName: string;
  username: string;
  email: string;
  password?: string; // Added for simulated login persistence
  followers: string[];
  following: string[];
  friends: string[];
  blockedUsers: string[];
  posts: Post[];
  reposts: Post[];
  moodHistory: { date: string, mood: Mood }[];
  moodStreak: number;
