import React, { useState, useEffect, useCallback } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { User, Mood, Section, Post, Comment } from './types';
import Sidebar from './components/Sidebar';
import MoodCheckIn from './components/MoodCheckIn';
import HomeSection from './sections/HomeSection';
import MoodSection from './sections/MoodSection';
import ZodiacSection from './sections/ZodiacSection';
import CityHallSection from './sections/CityHallSection';
import ProfileSection from './sections/ProfileSection';
import SettingsSection from './sections/SettingsSection';
import AuthScreen from './sections/AuthScreen';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [activeSection, setActiveSection] = useState<Section>('Home');
  const [isMoodModalOpen, setIsMoodModalOpen] = useState(false);
  const [isDarkMode, setIsDarkMode] = useState(false);
  const [allPosts, setAllPosts] = useState<Post[]>([]);

  useEffect(() => {
    const savedUser = localStorage.getItem('mooderia_user');
    const savedPosts = localStorage.getItem('mooderia_posts');
    const savedTheme = localStorage.getItem('mooderia_theme');

    if (savedUser) setCurrentUser(JSON.parse(savedUser));
    if (savedPosts) setAllPosts(JSON.parse(savedPosts));
    if (savedTheme === 'dark') setIsDarkMode(true);
  }, []);

  // Update both current session and the simulated "global" user database
  useEffect(() => {
    if (currentUser) {
      localStorage.setItem('mooderia_user', JSON.stringify(currentUser));

      const allUsersStr = localStorage.getItem('mooderia_all_users') || '[]';
      const allUsers: User[] = JSON.parse(allUsersStr);
      const userIndex = allUsers.findIndex(u => u.email === currentUser.email);

      if (userIndex > -1) {
        allUsers[userIndex] = currentUser;
      } else {
        allUsers.push(currentUser);
      }
      localStorage.setItem('mooderia_all_users', JSON.stringify(allUsers));
    }
    localStorage.setItem('mooderia_posts', JSON.stringify(allPosts));
    localStorage.setItem('mooderia_theme', isDarkMode ? 'dark' : 'light');
  }, [currentUser, allPosts, isDarkMode]);

  const handleLogin = (user: User) => {
    setCurrentUser(user);
    const today = new Date().toDateString();
    const hasCheckedMoodToday = user.moodHistory.some(m => m.date === today);
    if (!hasCheckedMoodToday) {
      setIsMoodModalOpen(true);
    }
    if (user.lastMoodDate) {
      const lastDate = new Date(user.lastMoodDate);
      const todayDate = new Date(today);
      const diffDays = Math.floor((todayDate.getTime() - lastDate.getTime()) / (1000 * 3600 * 24));
      if (diffDays > 1) {
        setCurrentUser({ ...user, moodStreak: 0 });
      }
    }
  };

  const handleLogout = () => {
    setCurrentUser(null);
    localStorage.removeItem('mooderia_user');
    setActiveSection('Home');
  };

  const handleDeleteAccount = () => {
    if (!currentUser) return;
    if (window.confirm("Are you sure you want to leave Mooderia permanently? This cannot be undone.")) {
      const emailToDelete = currentUser.email;

      // Update global list
      const allUsersStr = localStorage.getItem('mooderia_all_users') || '[]';
      let allUsers: User[] = JSON.parse(allUsersStr);
      allUsers = allUsers.filter(u => u.email !== emailToDelete);
      localStorage.setItem('mooderia_all_users', JSON.stringify(allUsers));

      // Clear session
      localStorage.removeItem('mooderia_user');
      setCurrentUser(null);

      alert("Account deleted. Farewell, citizen.");
      setActiveSection('Home');
    }
  };

  const submitMood = (mood: Mood) => {
    if (!currentUser) return;
    const today = new Date().toDateString();
    let newStreak = currentUser.moodStreak || 0;
    if (currentUser.lastMoodDate) {
      const lastDate = new Date(currentUser.lastMoodDate);
      const todayDate = new Date(today);
      const diffDays = Math.floor((todayDate.getTime() - lastDate.getTime()) / (1000 * 3600 * 24));
      if (diffDays === 1) newStreak += 1;
      else if (diffDays > 1) newStreak = 1;
    } else {
      newStreak = 1;
    }
    const updatedUser = {
      ...currentUser,
      moodStreak: newStreak,
      lastMoodDate: today,
      moodHistory: [...currentUser.moodHistory, { date: today, mood }]
    };
    setCurrentUser(updatedUser);
    setIsMoodModalOpen(false);
  };

  const addPost = (content: string) => {
    if (!currentUser) return;
    const newPost: Post = {
      id: Math.random().toString(36).substr(2, 9),
      author: currentUser.username,
      content,
      hearts: 0,
      comments: [],
      timestamp: Date.now()
    };
    setAllPosts([newPost, ...allPosts]);
  };

  const toggleHeart = (postId: string) => {
    setAllPosts(prev => prev.map(p => {
      if (p.id === postId) return { ...p, hearts: p.hearts + 1 };
      return p;
    }));
  };

  const handleFollow = (username: string) => {
    if (!currentUser) return;
    const isFollowing = currentUser.following.includes(username);
    if (isFollowing) {
      setCurrentUser({ ...currentUser, following: currentUser.following.filter(u => u !== username) });
    } else {
      setCurrentUser({ ...currentUser, following: [...currentUser.following, username] });
    }
  };

  const handleBlockUser = (username: string) => {
    if (!currentUser) return;
    if (!currentUser.blockedUsers.includes(username)) {
      setCurrentUser({
        ...currentUser,
        blockedUsers: [...currentUser.blockedUsers, username],
        following: currentUser.following.filter(u => u !== username),
        friends: (currentUser.friends || []).filter(u => u !== username)
      });
      alert(`User @${username} has been blocked.`);
    }
  };

  const handleUnblockUser = (username: string) => {
    if (!currentUser) return;
    setCurrentUser({
      ...currentUser,
      blockedUsers: currentUser.blockedUsers.filter(u => u !== username)
    });
  };

  const addComment = (postId: string, text: string) => {
    if (!currentUser) return;
    setAllPosts(prev => prev.map(p => {
      if (p.id === postId) {
        const newComment: Comment = {
          id: Math.random().toString(36).substr(2, 9),
          author: currentUser.username,
          text,
          replies: []
        };
        return { ...p, comments: [...p.comments, newComment] };
      }
      return p;
    }));
  };

  const repost = (post: Post) => {
    if (!currentUser) return;
    const newRepost: Post = {
      ...post,
      id: Math.random().toString(36).substr(2, 9),
      isRepost: true,
      originalAuthor: post.author,
      author: currentUser.username,
      timestamp: Date.now()
    };
    setAllPosts([newRepost, ...allPosts]);
    setCurrentUser({ ...currentUser, reposts: [newRepost, ...currentUser.reposts] });
  };

  const updateProfile = (displayName: string, username: string) => {
    if (!currentUser) return;
    setCurrentUser({ ...currentUser, displayName, username });
  };

  const visiblePosts = allPosts.filter(p => !currentUser?.blockedUsers.includes(p.author));

  if (!currentUser) {
    return <AuthScreen onLogin={handleLogin} />;
  }

  return (
    <div className={`min-h-screen ${isDarkMode ? 'bg-slate-900 text-white' : 'bg-gray-50 text-slate-900'} transition-colors duration-300`}>
      <AnimatePresence>
        {isMoodModalOpen && (
          <MoodCheckIn onSubmit={submitMood} isDarkMode={isDarkMode} />
        )}
      </AnimatePresence>

      <div className="flex flex-col md:flex-row min-h-screen">
        <Sidebar 
          activeSection={activeSection} 
          onNavigate={setActiveSection} 
          isDarkMode={isDarkMode}
          user={currentUser}
        />

        <main className="flex-1 p-4 md:p-8 pt-20 md:pt-8 overflow-y-auto">
          <motion.div
            key={activeSection}
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -20 }}
            transition={{ type: "spring", stiffness: 100 }}
            className="max-w-5xl mx-auto"
          >
            {activeSection === 'Home' && (
              <HomeSection user={currentUser} posts={visiblePosts} isDarkMode={isDarkMode} />
            )}
            {activeSection === 'Mood' && (
              <MoodSection 
                user={currentUser} 
                posts={visiblePosts} 
                onPost={addPost} 
                onHeart={toggleHeart} 
                onComment={addComment}
                onRepost={repost}
                onFollow={handleFollow}
                onBlock={handleBlockUser}
                isDarkMode={isDarkMode}
              />
            )}
            {activeSection === 'Zodiac' && (
              <ZodiacSection isDarkMode={isDarkMode} />
            )}
            {activeSection === 'CityHall' && (
              <CityHallSection isDarkMode={isDarkMode} />
            )}
            {activeSection === 'Profile' && (
              <ProfileSection 
                user={currentUser} 
                allPosts={visiblePosts} 
                isDarkMode={isDarkMode}
                onEditProfile={updateProfile}
                onBlock={handleBlockUser}
              />
            )}
            {activeSection === 'Settings' && (
              <SettingsSection 
                isDarkMode={isDarkMode} 
                onToggleDarkMode={() => setIsDarkMode(!isDarkMode)}
                onLogout={handleLogout}
                onDelete={handleDeleteAccount}
                user={currentUser}
                onUnblock={handleUnblockUser}
              />
            )}
          </motion.div>
        </main>
      </div>
    </div>
  );
};

export default App;

