                animate={{ height: 'auto', opacity: 1 }} 
                exit={{ height: 0, opacity: 0 }} 
                className="space-y-4 overflow-hidden"
              >
                <input 
                  type="text" 
                  placeholder="Display Name" 
                  required 
                  value={displayName} 
