import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { Brain, HeartPulse, Send, Stethoscope, Carrot, GraduationCap, BookOpen } from 'lucide-react';
import { getPsychiatristResponse, getNutritionistResponse, getStudyGuideResponse } from '../services/geminiService';

interface CityHallSectionProps {
  isDarkMode: boolean;
}

type AgentType = 'Pinel' | 'Lavoisier' | 'RonClark';

const CityHallSection: React.FC<CityHallSectionProps> = ({ isDarkMode }) => {
  const [activeDr, setActiveDr] = useState<AgentType>('Pinel');
  const [pinelChat, setPinelChat] = useState<{ role: 'user' | 'bot', text: string }[]>([]);
  const [lavoisierChat, setLavoisierChat] = useState<{ role: 'user' | 'bot', text: string }[]>([]);
  const [clarkChat, setClarkChat] = useState<{ role: 'user' | 'bot', text: string }[]>([]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  const handleSend = async () => {
    if (!input.trim() || isLoading) return;
    const userMsg = input;
    setInput('');
    setIsLoading(true);

    if (activeDr === 'Pinel') {
      setPinelChat(prev => [...prev, { role: 'user', text: userMsg }]);
      const res = await getPsychiatristResponse(userMsg);
      setPinelChat(prev => [...prev, { role: 'bot', text: res || 'I am here for you.' }]);
    } else if (activeDr === 'Lavoisier') {
      setLavoisierChat(prev => [...prev, { role: 'user', text: userMsg }]);
      const res = await getNutritionistResponse(userMsg);
      setLavoisierChat(prev => [...prev, { role: 'bot', text: res || 'Eat well, live well.' }]);
    } else {
      setClarkChat(prev => [...prev, { role: 'user', text: userMsg }]);
      const res = await getStudyGuideResponse(userMsg);
      setClarkChat(prev => [...prev, { role: 'bot', text: res || 'Believe in yourself!' }]);
    }
    setIsLoading(false);
  };

  const getChat = () => {
    switch (activeDr) {
      case 'Pinel': return pinelChat;
      case 'Lavoisier': return lavoisierChat;
      case 'RonClark': return clarkChat;
    }
  };

  const currentChat = getChat();

  const getAgentTitle = () => {
    switch (activeDr) {
      case 'Pinel': return 'Dr. Philippe Pinel (Psychiatrist)';
      case 'Lavoisier': return 'Dr. Antoine Lavoisier (Nutritionist)';
      case 'RonClark': return 'Sir Ron Clark (Study Guide)';
    }
  };

  return (
    <div className="flex flex-col h-[85vh] gap-6">
      <div className="flex flex-wrap gap-4">
        <button 
          onClick={() => setActiveDr('Pinel')}
          className={`flex-1 min-w-[150px] p-4 rounded-2xl font-black text-sm md:text-base flex items-center justify-center gap-2 transition-all ${activeDr === 'Pinel' ? 'kahoot-button-purple text-white scale-105 shadow-xl' : 'bg-gray-200 dark:bg-slate-700 opacity-60 text-slate-600 dark:text-slate-400'}`}
        >
          <Brain size={22} /> PINEL
        </button>
        <button 
          onClick={() => setActiveDr('Lavoisier')}
          className={`flex-1 min-w-[150px] p-4 rounded-2xl font-black text-sm md:text-base flex items-center justify-center gap-2 transition-all ${activeDr === 'Lavoisier' ? 'kahoot-button-green text-white scale-105 shadow-xl' : 'bg-gray-200 dark:bg-slate-700 opacity-60 text-slate-600 dark:text-slate-400'}`}
        >
          <HeartPulse size={22} /> LAVOISIER
        </button>
        <button 
          onClick={() => setActiveDr('RonClark')}
          className={`flex-1 min-w-[150px] p-4 rounded-2xl font-black text-sm md:text-base flex items-center justify-center gap-2 transition-all ${activeDr === 'RonClark' ? 'kahoot-button-yellow text-white scale-105 shadow-xl' : 'bg-gray-200 dark:bg-slate-700 opacity-60 text-slate-600 dark:text-slate-400'}`}
        >
          <GraduationCap size={22} /> SIR RON CLARK
        </button>
      </div>

      <div className={`flex-1 flex flex-col rounded-3xl ${isDarkMode ? 'bg-slate-800' : 'bg-white'} shadow-2xl overflow-hidden border-4 border-gray-100 dark:border-slate-700`}>
        <div className={`p-4 border-b ${isDarkMode ? 'bg-slate-700/50 border-slate-700' : 'bg-gray-50 border-gray-100'} flex items-center gap-3`}>
          {activeDr === 'Pinel' && <Stethoscope className="text-purple-500" />}
          {activeDr === 'Lavoisier' && <Carrot className="text-green-500" />}
          {activeDr === 'RonClark' && <BookOpen className="text-yellow-500" />}
          <h3 className={`font-black italic uppercase text-xs md:text-sm ${isDarkMode ? 'text-white' : 'text-slate-900'}`}>
            Consulting with {getAgentTitle()}
          </h3>
        </div>

        <div className="flex-1 overflow-y-auto p-6 space-y-4 custom-scrollbar">
          {currentChat.length === 0 && (
            <div className="h-full flex flex-col items-center justify-center text-center opacity-40">
              <p className={`text-xl font-bold ${isDarkMode ? 'text-white' : 'text-slate-900'}`}>Start a conversation with {activeDr === 'RonClark' ? 'Sir Ron Clark' : `Dr. ${activeDr}`}</p>
              <p className={`text-sm ${isDarkMode ? 'text-white' : 'text-slate-900'}`}>
                {activeDr === 'RonClark' 
                  ? 'Get help with assignments, study tips, and motivation!' 
                  : 'They are here to help you live your best life in Mooderia.'}
              </p>
            </div>
          )}
          {currentChat.map((msg, i) => (
            <div key={i} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
              <div className={`max-w-[85%] p-4 rounded-2xl font-semibold shadow-sm ${msg.role === 'user' ? 'bg-[#1368ce] text-white rounded-tr-none' : 'bg-gray-100 dark:bg-slate-700 text-slate-800 dark:text-white rounded-tl-none border-b-2 border-gray-200 dark:border-slate-600'}`}>
                {msg.text}
              </div>
            </div>
          ))}
          {isLoading && (
            <div className="flex justify-start">
              <div className="bg-gray-100 dark:bg-slate-700 p-4 rounded-2xl animate-pulse font-bold text-xs text-slate-600 dark:text-white">
                {activeDr === 'RonClark' ? 'Sir Ron Clark' : `Dr. ${activeDr}`} is thinking...
              </div>
            </div>
          )}
        </div>

        <div className={`p-4 border-t ${isDarkMode ? 'border-slate-700 bg-slate-800' : 'border-gray-100 bg-white'}`}>
          <div className="flex gap-2">
            <input 
              type="text" 
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && handleSend()}
              placeholder={`Ask ${activeDr === 'RonClark' ? 'Sir Ron Clark' : `Dr. ${activeDr}`} anything...`}
              className={`flex-1 p-4 rounded-xl border-2 outline-none focus:border-[#46178f] font-bold ${isDarkMode ? 'bg-slate-700 border-slate-600 text-white' : 'bg-gray-50 border-gray-100 text-slate-900'}`}
            />
            <button 
              onClick={handleSend}
              className={`kahoot-button p-4 rounded-xl text-white ${activeDr === 'Pinel' ? 'bg-[#46178f]' : activeDr === 'Lavoisier' ? 'bg-[#26890c]' : 'bg-[#ffa602]'}`}
            >
              <Send size={24} />
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default CityHallSection;

