import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { Heart, Star, Book, Zap, Sparkles } from 'lucide-react';
import { ZODIACS, getZodiacFromDate } from '../constants';
import { getHoroscope, getLovePrediction, getPlanetaryInsights } from '../services/geminiService';

interface ZodiacSectionProps {
  isDarkMode: boolean;
}

type ZodiacTab = 'LoveMatcher' | 'Horoscope' | 'PlanetaryAspects' | 'Almanac' | 'LuckyDay';

const MONTHS = [
  "January", "February", "March", "April", "May", "June",
  "July", "August", "September", "October", "November", "December"
];

const ZodiacSection: React.FC<ZodiacSectionProps> = ({ isDarkMode }) => {
  const [tab, setTab] = useState<ZodiacTab>('LoveMatcher');

  // Love Matcher State
  const [m1, setM1] = useState(1);
  const [d1, setD1] = useState(1);
  const [m2, setM2] = useState(1);
  const [d2, setD2] = useState(1);

  const [matchResult, setMatchResult] = useState<{ percentage: number, reason: string } | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [horoscope, setHoroscope] = useState<{ sign: string, text: string } | null>(null);
  const [planetaryInfo, setPlanetaryInfo] = useState<{ sign: string, text: string } | null>(null);
  const [selectedAlmanac, setSelectedAlmanac] = useState(ZODIACS[0]);
  const [luckyZodiac, setLuckyZodiac] = useState(ZODIACS[0].name);

  const handleMatch = async () => {
    setIsLoading(true);
    const sign1 = getZodiacFromDate(m1, d1);
    const sign2 = getZodiacFromDate(m2, d2);
    try {
      const result = await getLovePrediction(sign1, sign2);
      setMatchResult(result);
    } catch (e) {
      setMatchResult({ percentage: 75, reason: "The stars suggest a strong bond, despite minor friction in the outer orbits." });
    } finally {
      setIsLoading(false);
    }
  };

  const handlePlanetaryInsights = async (sign: string) => {
    setIsLoading(true);
    try {
      const res = await getPlanetaryInsights(sign);
      setPlanetaryInfo({ sign, text: res || 'Consulting planetary movements...' });
    } catch (e) {
      setPlanetaryInfo({ sign, text: "The planetary alignment is currently obscured." });
    } finally {
      setIsLoading(false);
    }
  };

  const handleHoroscope = async (sign: string) => {
    setIsLoading(true);
    try {
      const today = new Date().toDateString();
      const saved = localStorage.getItem(`horoscope_${sign}_${today}`);
      if (saved) {
        setHoroscope({ sign, text: saved });
      } else {
        const res = await getHoroscope(sign);
        localStorage.setItem(`horoscope_${sign}_${today}`, res || '');
        setHoroscope({ sign, text: res || 'Consulting stars...' });
      }
    } catch (e) {
      setHoroscope({ sign, text: "A mercury retrograde has blocked the transmission." });
    } finally {
      setIsLoading(false);
    }
  };

  const getLuckyData = (sign: string) => {
    const today = new Date().toDateString();
    const seed = sign + today;
    let hash = 0;
    for (let i = 0; i < seed.length; i++) {
      hash = seed.charCodeAt(i) + ((hash << 5) - hash);
    }
    const colors = ["Ruby Red", "Emerald Green", "Azure Blue", "Goldenrod", "Vibrant Purple", "Sunset Orange", "Teal", "Rose Pink", "Silver", "Ivory"];
    const luckyColor = colors[Math.abs(hash) % colors.length];
    const luckyNumber = (Math.abs(hash) % 99) + 1;
    return { color: luckyColor, number: luckyNumber };
  };

  const currentLucky = getLuckyData(luckyZodiac);

  const DayPicker = ({ val, setVal }: { val: number, setVal: (v: number) => void }) => (
    <select value={val} onChange={(e) => setVal(parseInt(e.target.value))} className={`p-4 rounded-xl font-bold border-2 ${isDarkMode ? 'bg-slate-700 border-slate-600 text-white' : 'bg-white border-gray-100 text-slate-900'}`}>
      {Array.from({ length: 31 }, (_, i) => i + 1).map(d => <option key={d} value={d}>{d}</option>)}
    </select>
  );

  const MonthPicker = ({ val, setVal }: { val: number, setVal: (v: number) => void }) => (
    <select value={val} onChange={(e) => setVal(parseInt(e.target.value))} className={`p-4 rounded-xl font-bold border-2 ${isDarkMode ? 'bg-slate-700 border-slate-600 text-white' : 'bg-white border-gray-100 text-slate-900'}`}>
      {MONTHS.map((m, i) => <option key={m} value={i + 1}>{m}</option>)}
    </select>
  );

  return (
    <div className="space-y-6 pb-20">
      <div className="flex gap-2 overflow-x-auto pb-2 scrollbar-hide">
        {['LoveMatcher', 'Horoscope', 'PlanetaryAspects', 'Almanac', 'LuckyDay'].map((t) => (
          <button
            key={t}
            onClick={() => setTab(t as ZodiacTab)}
            className={`px-6 py-2 rounded-full font-bold transition-all whitespace-nowrap ${tab === t ? 'bg-[#26890c] text-white scale-105 shadow-md' : 'bg-gray-200 dark:bg-slate-700 opacity-70 text-slate-900 dark:text-white'}`}
          >
            {t.replace(/([A-Z])/g, ' $1').trim()}
          </button>
        ))}
      </div>

      {tab === 'LoveMatcher' && (
        <div className={`p-8 rounded-3xl ${isDarkMode ? 'bg-slate-800 text-white' : 'bg-white text-slate-900'} shadow-xl text-center`}>
          <Heart className="mx-auto mb-6 text-red-500 animate-pulse" size={60} />
          <h2 className="text-3xl font-black mb-8 uppercase">Love Matcher</h2>
          <div className="flex flex-col md:flex-row items-center justify-center gap-12 mb-10">
            <div className="flex flex-col gap-3">
              <label className="text-xs font-black uppercase opacity-50">Partner 1 Birthdate</label>
              <div className="flex gap-2">
                <MonthPicker val={m1} setVal={setM1} />
                <DayPicker val={d1} setVal={setD1} />
              </div>
            </div>
            <div className="text-4xl font-black text-red-500 animate-bounce">&hearts;</div>
            <div className="flex flex-col gap-3">
              <label className="text-xs font-black uppercase opacity-50">Partner 2 Birthdate</label>
              <div className="flex gap-2">
                <MonthPicker val={m2} setVal={setM2} />
                <DayPicker val={d2} setVal={setD2} />
              </div>
            </div>
          </div>
          <button disabled={isLoading} onClick={handleMatch} className={`kahoot-button-red px-10 py-4 rounded-2xl text-white font-black text-xl mb-10 ${isLoading ? 'opacity-50' : ''}`}>
            {isLoading ? 'MATCHING...' : 'REVEAL LOVE SCORE'}
          </button>
          {matchResult && (
            <motion.div initial={{ scale: 0.9, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} className="p-8 rounded-3xl border-4 border-[#e21b3c] bg-[#e21b3c]/5">
              <p className="text-6xl font-black text-[#e21b3c] mb-4">{matchResult.percentage}%</p>
              <div className="text-left bg-white/50 dark:bg-slate-900/50 p-6 rounded-2xl">
                 <p className={`text-lg font-bold leading-relaxed ${isDarkMode ? 'text-white' : 'text-slate-900'}`}>{matchResult.reason}</p>
              </div>
            </motion.div>
          )}
        </div>
      )}

      {tab === 'Horoscope' && (
        <div className={`p-8 rounded-3xl ${isDarkMode ? 'bg-slate-800 text-white' : 'bg-white text-slate-900'} shadow-xl`}>
          <Star className="mx-auto mb-6 text-yellow-400" size={60} />
          <h2 className="text-3xl font-black text-center mb-8 uppercase">Daily Reading</h2>
          <div className="grid grid-cols-3 md:grid-cols-4 lg:grid-cols-6 gap-3 mb-10">
            {ZODIACS.map(z => (
              <button key={z.name} onClick={() => handleHoroscope(z.name)} className={`p-3 rounded-xl border-2 font-bold text-sm transition-all ${horoscope?.sign === z.name ? 'border-[#ffa602] bg-[#ffa602]/10 text-[#ffa602]' : 'border-transparent bg-gray-100 dark:bg-slate-700 text-slate-700 dark:text-slate-300'}`}>
                {z.name}
              </button>
            ))}
          </div>
          {horoscope && (
            <motion.div initial={{ opacity: 0, x: -20 }} animate={{ opacity: 1, x: 0 }} className={`p-8 rounded-3xl border-2 border-yellow-200 dark:border-slate-600 ${isDarkMode ? 'bg-slate-700' : 'bg-white'}`}>
              <h4 className="text-2xl font-black text-[#ffa602] mb-2">{horoscope.sign.toUpperCase()}</h4>
              <p className={`text-lg font-semibold leading-relaxed ${isDarkMode ? 'text-white' : 'text-slate-900'}`}>{horoscope.text}</p>
            </motion.div>
          )}
        </div>
      )}

      {tab === 'PlanetaryAspects' && (
        <div className={`p-8 rounded-3xl ${isDarkMode ? 'bg-slate-800 text-white' : 'bg-white text-slate-900'} shadow-xl`}>
          <Sparkles className="mx-auto mb-6 text-purple-500" size={60} />
          <h2 className="text-3xl font-black text-center mb-4 uppercase">Cosmic Aspects</h2>
          <div className="grid grid-cols-3 md:grid-cols-4 lg:grid-cols-6 gap-3 mb-10">
            {ZODIACS.map(z => (
              <button key={z.name} onClick={() => handlePlanetaryInsights(z.name)} className={`p-3 rounded-xl border-2 font-bold text-sm transition-all ${planetaryInfo?.sign === z.name ? 'border-purple-500 bg-purple-500/10 text-purple-500' : 'border-transparent bg-gray-100 dark:bg-slate-700 text-slate-700 dark:text-slate-300'}`}>
                {z.name}
              </button>
            ))}
          </div>
          {planetaryInfo && (
            <motion.div initial={{ opacity: 0, scale: 0.95 }} animate={{ opacity: 1, scale: 1 }} className={`p-10 rounded-[2.5rem] border-2 border-purple-500 ${isDarkMode ? 'bg-slate-700' : 'bg-white'}`}>
               <h4 className="text-3xl font-black mb-6 uppercase text-purple-500">{planetaryInfo.sign} Transits</h4>
               <div className={`text-xl leading-relaxed font-medium space-y-4 whitespace-pre-line ${isDarkMode ? 'text-white' : 'text-slate-900'}`}>
                 {planetaryInfo.text}
               </div>
            </motion.div>
          )}
          {isLoading && !planetaryInfo && (
            <div className="text-center py-10 animate-pulse font-black text-purple-500 uppercase tracking-widest">
              Consulting the planets...
            </div>
          )}
        </div>
      )}

      {tab === 'Almanac' && (
        <div className={`p-8 rounded-3xl ${isDarkMode ? 'bg-slate-800 text-white' : 'bg-white text-slate-900'} shadow-xl`}>
          <Book className="mx-auto mb-6 text-[#1368ce]" size={60} />
          <h2 className="text-3xl font-black text-center mb-8 uppercase">Zodiac Almanac</h2>
          <div className="flex flex-col md:flex-row gap-8">
            <div className="w-full md:w-1/3 space-y-2 h-[400px] overflow-y-auto pr-2 custom-scrollbar">
              {ZODIACS.map(z => (
                <button key={z.name} onClick={() => setSelectedAlmanac(z)} className={`w-full p-4 rounded-xl text-left font-bold transition-all ${selectedAlmanac.name === z.name ? 'bg-[#1368ce] text-white' : 'bg-gray-100 dark:bg-slate-700 text-slate-800 dark:text-slate-300'}`}>
                  {z.name}
                </button>
              ))}
            </div>
            <div className="flex-1 p-8 rounded-3xl border-2 border-gray-100 dark:border-slate-700">
               <h3 className="text-4xl font-black text-[#1368ce] mb-2">{selectedAlmanac.name}</h3>
               <p className={`text-lg font-bold opacity-70 mb-6 ${isDarkMode ? 'text-white' : 'text-slate-900'}`}>{selectedAlmanac.dates}</p>
