           <button key={tab} onClick={() => setActiveTab(tab)} className={`flex-1 p-4 rounded-2xl font-black transition-all border-b-4 ${activeTab === tab ? 'bg-[#1368ce] border-[#0e4c99] text-white' : 'bg-gray-200 dark:bg-slate-700 text-gray-500 border-gray-300 dark:border-slate-600'}`}>
             {tab.toUpperCase()}
