      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {activeTab === 'Posts' && (
          myPosts.length > 0 ? (
            myPosts.map(post => (
              <div key={post.id} className={`p-6 rounded-3xl ${isDarkMode ? 'bg-slate-800 text-white' : 'bg-white text-slate-900'} shadow-md border-b-4 border-gray-200 dark:border-slate-700`}>
                <p className="text-lg mb-4">{post.content}</p>
                <div className="flex gap-4 opacity-50 text-sm font-bold">
                  <span className="flex items-center gap-1"><Heart size={16}/> {post.hearts}</span>
                  <span className="flex items-center gap-1"><MessageCircle size={16}/> {post.comments.length}</span>
