            <div className="col-span-2 text-center py-20 opacity-40 italic font-bold text-slate-900 dark:text-white">No logs in the archive yet.</div>
          )
        )}
        {activeTab === 'Stats' && (
          <div className={`col-span-2 p-10 rounded-3xl ${isDarkMode ? 'bg-slate-800 text-white' : 'bg-white text-slate-900'} shadow-xl`}>
            <h3 className="text-2xl font-black text-center mb-8 uppercase">Mood Distribution</h3>
            <div className="space-y-4">
              {['Happy', 'Sad', 'Angry', 'Tired'].map(m => {
                const count = user.moodHistory.filter(mh => mh.mood === m).length;
                const total = user.moodHistory.length || 1;
                const pct = (count / total) * 100;
                return (
                  <div key={m} className="space-y-1">
                    <div className="flex justify-between text-xs font-black uppercase tracking-widest">
                      <span>{m}</span>
                      <span>{Math.round(pct)}%</span>
