import React, { useState, useEffect, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Heart, MessageCircle, Repeat, Send, Brain, Sparkles, Wind, ShieldAlert, CheckCircle2, Play, Pause, RefreshCw } from 'lucide-react';
import { User, Post, Mood } from '../types';
import { getTellerResponse } from '../services/geminiService';

interface MoodSectionProps {
  user: User;
  posts: Post[];
  onPost: (content: string) => void;
  onHeart: (postId: string) => void;
  onComment: (postId: string, text: string) => void;
  onRepost: (post: Post) => void;
  onFollow: (username: string) => void;
  onBlock: (username: string) => void;
  isDarkMode: boolean;
}

type MoodSubTab = 'Express' | 'Teller' | 'Quiz' | 'Meditation';

const QUIZ_QUESTIONS = [
  {
    question: "How do you typically start your morning in the metropolis?",
    options: [
      { text: "With a huge smile and high energy!", mood: 'Happy' },
      { text: "Slowly, wondering if I can stay in bed...", mood: 'Tired' },
      { text: "Checking my to-do list with intense focus.", mood: 'Angry' },
      { text: "Quietly, with a cup of coffee and some reflection.", mood: 'Sad' }
    ]
  },
  {
    question: "A giant robot is blocking the street! Your reaction?",
    options: [
      { text: "Yell at it to move! I have places to be!", mood: 'Angry' },
      { text: "Take a selfie with it! How cool!", mood: 'Happy' },
      { text: "Sigh... typical Monday in Mooderia.", mood: 'Sad' },
      { text: "Just walk around it, I'm too sleepy to care.", mood: 'Tired' }
    ]
  },
  {
    question: "What's your favorite district vibe?",
    options: [
      { text: "Neon lights and 24/7 parties.", mood: 'Happy' },
      { text: "Rainy windows and jazz cafes.", mood: 'Sad' },
      { text: "High-stakes boardrooms and power.", mood: 'Angry' },
      { text: "Cloud-soft pillows and silence.", mood: 'Tired' }
    ]
  }
];

const MoodSection: React.FC<MoodSectionProps> = ({ user, posts, onPost, onHeart, onComment, onRepost, onFollow, onBlock, isDarkMode }) => {
  const [subTab, setSubTab] = useState<MoodSubTab>('Express');
  const [postContent, setPostContent] = useState('');
  const [tellerQuestion, setTellerQuestion] = useState('');
  const [tellerAnswer, setTellerAnswer] = useState('');
  const [isTellerLoading, setIsTellerLoading] = useState(false);
  const [feedFilter, setFeedFilter] = useState<'All' | 'Following'>('All');

  // Quiz State
  const [quizStep, setQuizStep] = useState<number | 'result'>(0);
  const [quizAnswers, setQuizAnswers] = useState<string[]>([]);

  // Meditation State
  const [meditationActive, setMeditationActive] = useState(false);
  const [meditationPhase, setMeditationPhase] = useState<'Inhale' | 'Hold' | 'Exhale' | 'Idle'>('Idle');
  const [timer, setTimer] = useState(0);
  const meditationInterval = useRef<number | null>(null);

  const filteredPosts = feedFilter === 'All' 
    ? posts 
    : posts.filter(p => user.following.includes(p.author) || p.author === user.username);

  // --- Quiz Logic ---
  const handleQuizAnswer = (mood: string) => {
    const newAnswers = [...quizAnswers, mood];
    setQuizAnswers(newAnswers);
    if (typeof quizStep === 'number') {
      if (quizStep < QUIZ_QUESTIONS.length - 1) {
        setQuizStep(quizStep + 1);
      } else {
        setQuizStep('result');
      }
    }
  };

  const calculateQuizResult = () => {
    const counts: Record<string, number> = {};
    quizAnswers.forEach(m => counts[m] = (counts[m] || 0) + 1);
    const topMood = Object.keys(counts).reduce((a, b) => counts[a] > counts[b] ? a : b);

    switch(topMood) {
      case 'Happy': return { title: "Joy District Elite", desc: "You belong in the neon-soaked streets of happiness!", icon: "✨" };
      case 'Sad': return { title: "Blue Bayou Poet", desc: "You find beauty in the city's melancholic rain.", icon: "🌊" };
      case 'Angry': return { title: "Ember Peak Commander", desc: "Your fiery passion drives the city's industry!", icon: "🔥" };
      case 'Tired': return { title: "Slumber Sanctuary Sage", desc: "You are the master of the quiet, cozy corners.", icon: "💤" };
      default: return { title: "Metropolis Wanderer", desc: "You fit in everywhere!", icon: "🏙️" };
    }
  };

  // --- Meditation Logic ---
  useEffect(() => {
    if (meditationActive) {
      let currentPhase: 'Inhale' | 'Hold' | 'Exhale' = 'Inhale';
      let timeLeft = 4;
      setMeditationPhase('Inhale');
      setTimer(4);

      meditationInterval.current = window.setInterval(() => {
        timeLeft -= 1;
        setTimer(timeLeft);

        if (timeLeft <= 0) {
          if (currentPhase === 'Inhale') {
            currentPhase = 'Hold';
            timeLeft = 7;
          } else if (currentPhase === 'Hold') {
            currentPhase = 'Exhale';
            timeLeft = 8;
          } else {
            currentPhase = 'Inhale';
            timeLeft = 4;
          }
          setMeditationPhase(currentPhase);
          setTimer(timeLeft);
        }
      }, 1000);
    } else {
      if (meditationInterval.current) clearInterval(meditationInterval.current);
      setMeditationPhase('Idle');
      setTimer(0);
    }
    return () => { if (meditationInterval.current) clearInterval(meditationInterval.current); };
  }, [meditationActive]);

  const handlePost = () => {
    if (!postContent.trim()) return;
    onPost(postContent);
    setPostContent('');
  };

  const handleTeller = async () => {
    if (!tellerQuestion.trim()) return;
    setIsTellerLoading(true);
    try {
      const res = await getTellerResponse(tellerQuestion);
      setTellerAnswer(res || "The stars are silent right now...");
    } catch (e) {
      setTellerAnswer("A cloud obscures my vision.");
    } finally {
      setIsTellerLoading(false);
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center -mx-4 px-4 overflow-x-auto no-scrollbar">
        <div className="flex gap-2 pb-2">
          {['Express', 'Teller', 'Quiz', 'Meditation'].map((tab) => (
            <button
              key={tab}
              onClick={() => setSubTab(tab as MoodSubTab)}
              className={`px-5 py-2.5 rounded-full font-black whitespace-nowrap transition-all text-xs md:text-sm ${subTab === tab ? 'bg-[#46178f] text-white scale-105 shadow-md' : 'bg-gray-200 dark:bg-slate-700 opacity-70 text-slate-800 dark:text-slate-300'}`}
            >
              {tab.toUpperCase()}
            </button>
          ))}
        </div>
      </div>

      {subTab === 'Express' && (
        <div className="space-y-6">
          <div className="flex gap-2 p-1.5 bg-gray-200 dark:bg-slate-800 rounded-2xl w-fit">
            <button onClick={() => setFeedFilter('All')} className={`px-4 py-1.5 rounded-xl text-xs font-black transition-all ${feedFilter === 'All' ? 'bg-white dark:bg-slate-700 shadow-sm text-slate-900 dark:text-white' : 'opacity-50 text-slate-600 dark:text-slate-400'}`}>ALL MOODS</button>
            <button onClick={() => setFeedFilter('Following')} className={`px-4 py-1.5 rounded-xl text-xs font-black transition-all ${feedFilter === 'Following' ? 'bg-white dark:bg-slate-700 shadow-sm text-slate-900 dark:text-white' : 'opacity-50 text-slate-600 dark:text-slate-400'}`}>FOLLOWING</button>
          </div>
          <div className={`p-6 rounded-[2rem] ${isDarkMode ? 'bg-slate-800' : 'bg-white'} shadow-xl`}>
            <textarea value={postContent} onChange={(e) => setPostContent(e.target.value)} placeholder="What's your emotional status today, citizen?" className={`w-full p-4 rounded-xl border-2 focus:border-[#46178f] outline-none transition-all text-sm md:text-base ${isDarkMode ? 'bg-slate-700 border-slate-600 text-white' : 'bg-gray-50 border-gray-100 text-slate-900'}`} rows={3} />
            <div className="flex justify-end mt-4">
              <button onClick={handlePost} className="kahoot-button-blue px-6 py-2.5 text-white rounded-xl font-black text-xs md:text-sm flex items-center gap-2"><Send size={16} /> EXPRESS IT</button>
            </div>
          </div>
          <div className="space-y-4">
            {filteredPosts.length === 0 ? (
              <div className="py-20 text-center opacity-40 font-black italic uppercase tracking-widest text-xs">The streets are quiet...</div>
            ) : filteredPosts.map(post => (
                <motion.div layout key={post.id} className={`p-6 rounded-[2rem] ${isDarkMode ? 'bg-slate-800 text-white' : 'bg-white text-slate-900'} shadow-md border-b-4 border-gray-200 dark:border-slate-700`}>
                  <div className="flex items-center justify-between mb-4">
                    <div className="flex items-center gap-3">
                      <div className="w-10 h-10 rounded-2xl bg-gradient-to-tr from-blue-400 to-purple-400 flex items-center justify-center text-white font-black">{post.author[0].toUpperCase()}</div>
                      <div>
                        <h4 className="font-black text-sm">@{post.author}</h4>
                        {post.isRepost && <p className="text-[10px] font-bold opacity-50 flex items-center gap-1"><Repeat size={8}/> Reposted from @{post.originalAuthor}</p>}
                      </div>
                    </div>
                  </div>
                  <p className="text-base md:text-lg mb-6 leading-relaxed font-medium">{post.content}</p>
                  <div className="flex items-center gap-6 pt-4 border-t border-gray-100 dark:border-slate-700">
                    <button onClick={() => onHeart(post.id)} className="flex items-center gap-1.5 text-red-500 font-black text-xs"><Heart size={18} /> {post.hearts}</button>
                    <button className="flex items-center gap-1.5 text-blue-500 font-black text-xs"><MessageCircle size={18} /> {post.comments.length}</button>
                    <button onClick={() => onRepost(post)} className="flex items-center gap-1.5 text-green-500 font-black text-xs"><Repeat size={18} /> REPOST</button>
                  </div>
                </motion.div>
            ))}
          </div>
        </div>
      )}

      {subTab === 'Teller' && (
        <div className={`p-6 md:p-10 rounded-[2.5rem] text-center bg-gradient-to-b from-[#46178f] to-[#1368ce] text-white shadow-2xl`}>
          <Sparkles className="mx-auto mb-6 text-yellow-400" size={48} />
          <h2 className="text-2xl md:text-4xl font-black mb-4 uppercase italic">The Mooderia Oracle</h2>
          <div className="max-w-xl mx-auto space-y-4">
            <input type="text" value={tellerQuestion} onChange={(e) => setTellerQuestion(e.target.value)} placeholder="Will I find peace today?" className="w-full p-4 rounded-2xl text-slate-900 font-bold text-center focus:outline-none focus:ring-4 ring-yellow-400 text-sm md:text-base" />
            <button disabled={isTellerLoading} onClick={handleTeller} className={`w-full p-4 rounded-2xl kahoot-button-yellow text-white font-black text-lg md:text-xl transition-all ${isTellerLoading ? 'opacity-50 animate-pulse' : ''}`}>{isTellerLoading ? 'CONSULTING...' : 'PREDICT MY FATE'}</button>
          </div>
          {tellerAnswer && (
            <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} className="mt-12 p-6 md:p-8 bg-white/10 backdrop-blur-md rounded-3xl border border-white/20">
              <p className="text-xl md:text-2xl font-black italic">"{tellerAnswer}"</p>
            </motion.div>
          )}
        </div>
      )}

      {subTab === 'Quiz' && (
        <div className={`p-8 rounded-[2.5rem] ${isDarkMode ? 'bg-slate-800 text-white' : 'bg-white text-slate-900'} shadow-xl text-center min-h-[400px] flex flex-col justify-center`}>
          <AnimatePresence mode="wait">
            {quizStep === 'result' ? (
              <motion.div key="result" initial={{ scale: 0.8, opacity: 0 }} animate={{ scale: 1, opacity: 1 }}>
                <div className="text-6xl mb-4">{calculateQuizResult().icon}</div>
                <h2 className="text-3xl font-black mb-2 uppercase italic text-[#26890c]">{calculateQuizResult().title}</h2>
                <p className="text-lg font-bold opacity-70 mb-8">{calculateQuizResult().desc}</p>
                <button onClick={() => {setQuizStep(0); setQuizAnswers([]);}} className="kahoot-button-blue px-10 py-4 rounded-2xl text-white font-black uppercase">RETAKE QUIZ</button>
              </motion.div>
            ) : (
              <motion.div key={quizStep} initial={{ x: 50, opacity: 0 }} animate={{ x: 0, opacity: 1 }} exit={{ x: -50, opacity: 0 }} className="space-y-6">
                <Brain className="mx-auto mb-6 text-[#26890c]" size={56} />
                <h2 className="text-xl md:text-2xl font-black uppercase tracking-tighter">{QUIZ_QUESTIONS[quizStep].question}</h2>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  {QUIZ_QUESTIONS[quizStep].options.map((opt, i) => {
                    const colors = ['kahoot-button-red', 'kahoot-button-blue', 'kahoot-button-yellow', 'kahoot-button-green'];
                    return (
                      <button key={i} onClick={() => handleQuizAnswer(opt.mood)} className={`${colors[i]} p-6 rounded-2xl text-white font-black text-left flex items-center gap-4 transition-transform active:scale-95`}>
                        <div className="w-8 h-8 rounded-lg bg-white/20 flex items-center justify-center">{i+1}</div>
                        {opt.text}
                      </button>
                    );
                  })}
                </div>
                <p className="text-[10px] font-black opacity-30 uppercase tracking-[0.2em]">Question {quizStep + 1} of {QUIZ_QUESTIONS.length}</p>
              </motion.div>
            )}
          </AnimatePresence>
        </div>
      )}

      {subTab === 'Meditation' && (
        <div className={`p-8 rounded-[2.5rem] ${isDarkMode ? 'bg-slate-800 text-white' : 'bg-white text-slate-900'} shadow-xl text-center flex flex-col items-center`}>
          <Wind className="mb-6 text-blue-400" size={56} />
          <h2 className="text-2xl md:text-3xl font-black mb-2 uppercase tracking-tighter italic">Zen Garden</h2>
          <p className="mb-10 opacity-70 font-bold text-sm">4-7-8 Breathing Guide</p>

          <div className="relative w-64 h-64 flex items-center justify-center mb-10">
            {/* Pulsing Orb */}
            <motion.div 
              animate={{ 
                scale: meditationPhase === 'Inhale' ? 1.5 : meditationPhase === 'Exhale' ? 1 : meditationPhase === 'Hold' ? 1.5 : 1,
                opacity: meditationPhase === 'Idle' ? 0.3 : 1
              }}
              transition={{ duration: meditationPhase === 'Inhale' ? 4 : meditationPhase === 'Exhale' ? 8 : 0.5 }}
              className={`absolute w-32 h-32 rounded-full blur-2xl ${meditationPhase === 'Inhale' ? 'bg-blue-400' : meditationPhase === 'Hold' ? 'bg-purple-500' : 'bg-green-400'}`}
            />
            <motion.div 
              animate={{ 
                scale: meditationPhase === 'Inhale' ? 1.5 : meditationPhase === 'Exhale' ? 1 : meditationPhase === 'Hold' ? 1.5 : 1
              }}
              transition={{ duration: meditationPhase === 'Inhale' ? 4 : meditationPhase === 'Exhale' ? 8 : 0.5 }}
              className={`w-32 h-32 rounded-full border-4 flex flex-col items-center justify-center z-10 ${isDarkMode ? 'bg-slate-800' : 'bg-white'} shadow-2xl`}
              style={{ borderColor: meditationPhase === 'Inhale' ? '#60a5fa' : meditationPhase === 'Hold' ? '#a855f7' : '#4ade80' }}
            >
              <span className="text-4xl font-black italic">{timer || '--'}</span>
              <span className="text-[8px] font-black uppercase tracking-widest opacity-50">{meditationPhase}</span>
            </motion.div>
          </div>

          <div className="flex gap-4">
            <button 
              onClick={() => setMeditationActive(!meditationActive)} 
              className={`px-10 py-4 rounded-2xl font-black text-white flex items-center gap-2 shadow-xl transition-all ${meditationActive ? 'bg-red-500 border-b-4 border-red-700' : 'bg-blue-500 border-b-4 border-blue-700'}`}
            >
              {meditationActive ? <Pause size={20} /> : <Play size={20} />}
              {meditationActive ? 'STOP SESSION' : 'START SESSION'}
            </button>
            {meditationActive && (
              <button onClick={() => {setMeditationActive(false); setTimeout(() => setMeditationActive(true), 100);}} className="p-4 rounded-2xl bg-gray-200 dark:bg-slate-700 text-slate-600 dark:text-white border-b-4 border-gray-300 dark:border-slate-900">
                <RefreshCw size={24} />
              </button>
            )}
          </div>

          <div className="mt-12 grid grid-cols-3 gap-8 w-full max-w-sm">
            <div className="text-center">
              <p className="text-xs font-black text-blue-400">4s</p>
              <p className="text-[8px] font-bold uppercase opacity-50">Inhale</p>
            </div>
            <div className="text-center border-x border-gray-100 dark:border-slate-700">
              <p className="text-xs font-black text-purple-400">7s</p>
              <p className="text-[8px] font-bold uppercase opacity-50">Hold</p>
            </div>
            <div className="text-center">
              <p className="text-xs font-black text-green-400">8s</p>
              <p className="text-[8px] font-bold uppercase opacity-50">Exhale</p>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default MoodSection;

import React, { useState, useEffect, useMemo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Brain, HeartPulse, Send, Stethoscope, Carrot, GraduationCap, BookOpen, AlertTriangle, ShieldCheck, Activity, Users, Search, MessageSquare, ArrowLeft } from 'lucide-react';
import { getPsychiatristResponse, getNutritionistResponse, getStudyGuideResponse } from '../services/geminiService';
import { User, Message } from '../types';

interface CityHallSectionProps {
  isDarkMode: boolean;
  currentUser: User;
  messages: Message[];
  onSendMessage: (recipient: string, text: string) => void;
  onReadMessages: (withUsername: string) => void;
}

type HallTab = 'Pinel' | 'Lavoisier' | 'RonClark' | 'Community';

const CityHallSection: React.FC<CityHallSectionProps> = ({ isDarkMode, currentUser, messages, onSendMessage, onReadMessages }) => {
  const [activeTab, setActiveTab] = useState<HallTab>('Pinel');
  const [pinelChat, setPinelChat] = useState<{ role: 'user' | 'bot', text: string }[]>([]);
  const [lavoisierChat, setLavoisierChat] = useState<{ role: 'user' | 'bot', text: string }[]>([]);
  const [clarkChat, setClarkChat] = useState<{ role: 'user' | 'bot', text: string }[]>([]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  // Community State
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedCitizen, setSelectedCitizen] = useState<User | null>(null);

  const allUsers: User[] = useMemo(() => {
    return JSON.parse(localStorage.getItem('mooderia_all_users') || '[]');
  }, []);

  const filteredCitizens = useMemo(() => {
    if (!searchTerm.trim()) return [];
    return allUsers.filter(u => 
      u.username !== currentUser.username && 
      (u.displayName.toLowerCase().includes(searchTerm.toLowerCase()) || 
       u.username.toLowerCase().includes(searchTerm.toLowerCase()))
    );
  }, [searchTerm, allUsers, currentUser.username]);

  const conversationUsers = useMemo(() => {
    const userNames = new Set<string>();
    messages.forEach(m => {
      if (m.sender === currentUser.username) userNames.add(m.recipient);
      if (m.recipient === currentUser.username) userNames.add(m.sender);
    });
    return allUsers.filter(u => userNames.has(u.username));
  }, [messages, allUsers, currentUser.username]);

  const chatMessages = useMemo(() => {
    if (!selectedCitizen) return [];
    return messages.filter(m => 
      (m.sender === currentUser.username && m.recipient === selectedCitizen.username) ||
      (m.sender === selectedCitizen.username && m.recipient === currentUser.username)
    ).sort((a, b) => a.timestamp - b.timestamp);
  }, [messages, selectedCitizen, currentUser.username]);

  const unreadPerUser = useMemo(() => {
    const counts: Record<string, number> = {};
    messages.forEach(m => {
      if (m.recipient === currentUser.username && !m.read) {
        counts[m.sender] = (counts[m.sender] || 0) + 1;
      }
    });
    return counts;
  }, [messages, currentUser.username]);

  useEffect(() => {
    if (selectedCitizen && activeTab === 'Community') {
      onReadMessages(selectedCitizen.username);
    }
  }, [selectedCitizen, messages.length, activeTab]);

  const handleAISend = async () => {
    if (!input.trim() || isLoading) return;
    const userMsg = input;
    setInput('');
    setIsLoading(true);

    try {
        if (activeTab === 'Pinel') {
          setPinelChat(prev => [...prev, { role: 'user', text: userMsg }]);
          const res = await getPsychiatristResponse(userMsg);
          setPinelChat(prev => [...prev, { role: 'bot', text: res || 'I am here for you.' }]);
        } else if (activeTab === 'Lavoisier') {
          setLavoisierChat(prev => [...prev, { role: 'user', text: userMsg }]);
          const res = await getNutritionistResponse(userMsg);
          setLavoisierChat(prev => [...prev, { role: 'bot', text: res || 'Eat well, live well.' }]);
        } else if (activeTab === 'RonClark') {
          setClarkChat(prev => [...prev, { role: 'user', text: userMsg }]);
          const res = await getStudyGuideResponse(userMsg);
          setClarkChat(prev => [...prev, { role: 'bot', text: res || 'Believe in yourself!' }]);
        }
    } catch (error) {
        const errorMsg = "The city communication lines are busy. Please try again in a moment.";
        if (activeTab === 'Pinel') setPinelChat(prev => [...prev, { role: 'bot', text: errorMsg }]);
        else if (activeTab === 'Lavoisier') setLavoisierChat(prev => [...prev, { role: 'bot', text: errorMsg }]);
        else if (activeTab === 'RonClark') setClarkChat(prev => [...prev, { role: 'bot', text: errorMsg }]);
    } finally {
        setIsLoading(false);
    }
  };

  const handleCommunitySend = () => {
    if (!input.trim() || !selectedCitizen) return;
    onSendMessage(selectedCitizen.username, input);
    setInput('');
  };

  const getAgentTitle = () => {
    switch (activeTab) {
      case 'Pinel': return 'Dr. Philippe Pinel (Psychiatrist)';
      case 'Lavoisier': return 'Dr. Antoine Lavoisier (Nutritionist)';
      case 'RonClark': return 'Sir Clark (Study Guide)';
      case 'Community': return 'Citizens Community';
    }
  };

  const getAgentShortName = () => {
    switch (activeTab) {
      case 'Pinel': return 'Dr. Pinel';
      case 'Lavoisier': return 'Dr. Lavoisier';
      case 'RonClark': return 'Sir Clark';
      case 'Community': return selectedCitizen?.displayName || 'Citizen';
    }
  };

  return (
    <div className="flex flex-col h-[85vh] gap-4">
      {/* Tab Navigation */}
      <div className="flex flex-wrap gap-2 md:gap-4 overflow-x-auto no-scrollbar pb-2">
        <button 
          onClick={() => setActiveTab('Pinel')}
          className={`flex-1 min-w-[120px] p-3 rounded-2xl font-black text-xs md:text-sm flex items-center justify-center gap-2 transition-all ${activeTab === 'Pinel' ? 'kahoot-button-purple text-white scale-105 shadow-xl' : 'bg-gray-200 dark:bg-slate-700 opacity-60 text-slate-600 dark:text-slate-400'}`}
        >
          <Brain size={18} /> PINEL
        </button>
        <button 
          onClick={() => setActiveTab('Lavoisier')}
          className={`flex-1 min-w-[120px] p-3 rounded-2xl font-black text-xs md:text-sm flex items-center justify-center gap-2 transition-all ${activeTab === 'Lavoisier' ? 'kahoot-button-green text-white scale-105 shadow-xl' : 'bg-gray-200 dark:bg-slate-700 opacity-60 text-slate-600 dark:text-slate-400'}`}
        >
          <HeartPulse size={18} /> LAVOISIER
        </button>
        <button 
          onClick={() => setActiveTab('RonClark')}
          className={`flex-1 min-w-[120px] p-3 rounded-2xl font-black text-xs md:text-sm flex items-center justify-center gap-2 transition-all ${activeTab === 'RonClark' ? 'kahoot-button-yellow text-white scale-105 shadow-xl' : 'bg-gray-200 dark:bg-slate-700 opacity-60 text-slate-600 dark:text-slate-400'}`}
        >
          <GraduationCap size={18} /> CLARK
        </button>
        <button 
          onClick={() => setActiveTab('Community')}
          className={`flex-1 min-w-[120px] p-3 rounded-2xl font-black text-xs md:text-sm flex items-center justify-center gap-2 transition-all relative ${activeTab === 'Community' ? 'bg-[#1368ce] border-b-4 border-[#0e4c99] text-white scale-105 shadow-xl' : 'bg-gray-200 dark:bg-slate-700 opacity-60 text-slate-600 dark:text-slate-400'}`}
        >
          <Users size={18} /> 
          COMMUNITY
          {Object.values(unreadPerUser).length > 0 && (
            <span className="absolute -top-1 -right-1 w-5 h-5 bg-red-500 rounded-full text-[10px] flex items-center justify-center border-2 border-white dark:border-slate-800">
              {/* Fix: Explicitly type reduce parameters to resolve TypeScript error where types are inferred as unknown */}
              {Object.values(unreadPerUser).reduce((a: number, b: number) => a + b, 0)}
            </span>
          )}
        </button>
      </div>

      <div className={`flex-1 flex flex-col md:flex-row rounded-3xl ${isDarkMode ? 'bg-slate-800' : 'bg-white'} shadow-2xl overflow-hidden border-4 border-gray-100 dark:border-slate-700`}>

        {/* Community Sidebar */}
        {activeTab === 'Community' && (
          <div className={`w-full md:w-72 border-r ${isDarkMode ? 'border-slate-700' : 'border-gray-100'} flex flex-col ${selectedCitizen ? 'hidden md:flex' : 'flex'}`}>
             <div className="p-4 border-b border-gray-100 dark:border-slate-700">
               <div className="relative">
                 <Search className="absolute left-3 top-1/2 -translate-y-1/2 opacity-30" size={16} />
                 <input 
                   type="text" 
                   value={searchTerm}
                   onChange={(e) => setSearchTerm(e.target.value)}
                   placeholder="Search Citizens..."
                   className={`w-full pl-9 pr-4 py-2 rounded-xl text-xs font-bold outline-none border-2 focus:border-blue-500 ${isDarkMode ? 'bg-slate-700 border-slate-600 text-white' : 'bg-gray-50 border-gray-200 text-slate-900'}`}
                 />
               </div>
             </div>

             <div className="flex-1 overflow-y-auto custom-scrollbar p-2 space-y-1">
               {searchTerm.trim() ? (
                 <>
                   <p className="text-[10px] font-black uppercase tracking-widest opacity-30 mb-2 px-2 mt-2">Search Results</p>
                   {filteredCitizens.map(u => (
                     <button 
                       key={u.username}
                       onClick={() => { setSelectedCitizen(u); setSearchTerm(''); }}
                       className={`w-full p-3 rounded-xl flex items-center gap-3 transition-colors ${selectedCitizen?.username === u.username ? 'bg-blue-500 text-white' : 'hover:bg-gray-50 dark:hover:bg-slate-700'}`}
                     >
                       <div className="w-8 h-8 rounded-full bg-blue-100 dark:bg-slate-600 flex items-center justify-center text-[10px] font-black shrink-0">
                         {u.profilePic ? <img src={u.profilePic} className="w-full h-full object-cover rounded-full" /> : u.displayName[0]}
                       </div>
                       <div className="text-left truncate">
                         <p className="font-black text-[11px] truncate">{u.displayName}</p>
                         <p className={`text-[9px] font-bold ${selectedCitizen?.username === u.username ? 'text-white/60' : 'opacity-40'} truncate`}>@{u.username}</p>
                       </div>
                     </button>
                   ))}
                   {filteredCitizens.length === 0 && <p className="text-[10px] italic opacity-40 px-2">No citizens found.</p>}
                 </>
               ) : (
                 <>
                   <p className="text-[10px] font-black uppercase tracking-widest opacity-30 mb-2 px-2 mt-2">Active Conversations</p>
                   {conversationUsers.map(u => (
                     <button 
                       key={u.username}
                       onClick={() => setSelectedCitizen(u)}
                       className={`w-full p-3 rounded-xl flex items-center gap-3 transition-colors relative ${selectedCitizen?.username === u.username ? 'bg-blue-500 text-white' : 'hover:bg-gray-50 dark:hover:bg-slate-700'}`}
                     >
                       <div className="w-10 h-10 rounded-full bg-blue-100 dark:bg-slate-600 flex items-center justify-center text-xs font-black shrink-0">
                         {u.profilePic ? <img src={u.profilePic} className="w-full h-full object-cover rounded-full" /> : u.displayName[0]}
                       </div>
                       <div className="text-left flex-1 min-w-0">
                         <p className="font-black text-xs truncate">{u.displayName}</p>
                         <p className={`text-[10px] font-bold ${selectedCitizen?.username === u.username ? 'text-white/60' : 'opacity-40'} truncate italic`}>{u.title || 'Citizen'}</p>
                       </div>
                       {unreadPerUser[u.username] > 0 && selectedCitizen?.username !== u.username && (
                         <span className="w-5 h-5 bg-red-500 rounded-full text-[10px] flex items-center justify-center text-white font-black border-2 border-white dark:border-slate-800">
                           {unreadPerUser[u.username]}
                         </span>
                       )}
                     </button>
                   ))}
                   {conversationUsers.length === 0 && <p className="text-[10px] italic opacity-40 px-2 py-8 text-center">Your inbox is empty. Search for a citizen to start chatting!</p>}
                 </>
               )}
             </div>
          </div>
        )}

        {/* Chat Area */}
        <div className={`flex-1 flex flex-col min-h-0 ${activeTab === 'Community' && !selectedCitizen ? 'hidden md:flex' : 'flex'}`}>
          <div className={`p-4 border-b ${isDarkMode ? 'bg-slate-700/50 border-slate-700' : 'bg-gray-50 border-gray-100'} flex items-center justify-between gap-3`}>
            <div className="flex items-center gap-3">
              {activeTab === 'Community' && selectedCitizen && (
                <button onClick={() => setSelectedCitizen(null)} className="md:hidden mr-1">
                  <ArrowLeft size={20} />
                </button>
              )}
              {activeTab === 'Pinel' && <Stethoscope className="text-purple-500" />}
              {activeTab === 'Lavoisier' && <Carrot className="text-green-500" />}
              {activeTab === 'RonClark' && <BookOpen className="text-yellow-500" />}
              {activeTab === 'Community' && <MessageSquare className="text-blue-500" />}
              <h3 className={`font-black italic uppercase text-[11px] md:text-sm truncate ${isDarkMode ? 'text-white' : 'text-slate-900'}`}>
                {activeTab === 'Community' && !selectedCitizen ? 'Select a citizen to chat' : `Consulting: ${getAgentTitle()}`}
              </h3>
            </div>
            <div className="flex items-center gap-2">
               <ShieldCheck size={14} className="text-green-500" />
               <span className="text-[9px] font-black text-green-500 uppercase tracking-tighter hidden sm:block">Secure Tunnel</span>
            </div>
          </div>

          {activeTab !== 'Community' && (
            <div className={`px-6 py-2 border-b ${isDarkMode ? 'bg-amber-900/10 border-amber-900/20' : 'bg-amber-50 border-amber-100'} flex items-center gap-2`}>
              <AlertTriangle className="text-amber-500 shrink-0" size={14} />
              <p className={`text-[10px] font-bold ${isDarkMode ? 'text-amber-200/50' : 'text-amber-700'} leading-tight`}>
                AI PERSONA NOTICE: Digital characters for entertainment/support. 1,500 daily request cap.
              </p>
            </div>
          )}

          <div className="flex-1 overflow-y-auto p-4 md:p-6 space-y-4 custom-scrollbar">
            {activeTab === 'Community' ? (
              !selectedCitizen ? (
                <div className="h-full flex flex-col items-center justify-center text-center p-8 opacity-30">
                  <Users size={64} className="mb-4" />
                  <p className="text-lg font-black uppercase italic">City Messenger</p>
                  <p className="text-xs font-bold max-w-xs">Talk with other citizens of Mooderia in real-time. Use the search bar to find people by name.</p>
                </div>
              ) : (
                chatMessages.length === 0 ? (
                  <div className="h-full flex flex-col items-center justify-center text-center opacity-30">
                    <p className="font-black uppercase italic">New Connection</p>
                    <p className="text-[10px] font-bold mt-1">Say hello to @{selectedCitizen.username}!</p>
                  </div>
                ) : (
                  chatMessages.map((msg, i) => (
                    <div key={msg.id} className={`flex ${msg.sender === currentUser.username ? 'justify-end' : 'justify-start'}`}>
                      <div className={`max-w-[80%] p-3 md:p-4 rounded-2xl text-xs md:text-sm font-semibold shadow-sm ${msg.sender === currentUser.username ? 'bg-[#1368ce] text-white rounded-tr-none' : 'bg-gray-100 dark:bg-slate-700 text-slate-800 dark:text-white rounded-tl-none border-b-2 border-gray-200 dark:border-slate-600'}`}>
                        {msg.text}
                        <p className={`text-[8px] mt-1 text-right font-black opacity-40 uppercase`}>
                          {new Date(msg.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                        </p>
                      </div>
                    </div>
                  ))
                )
              ) : (
                <>
                  {(activeTab === 'Pinel' ? pinelChat : activeTab === 'Lavoisier' ? lavoisierChat : clarkChat).length === 0 && (
                    <div className="h-full flex flex-col items-center justify-center text-center opacity-40 p-8">
                      <p className={`text-xl font-black italic uppercase ${isDarkMode ? 'text-white' : 'text-slate-900'}`}>Welcome, Citizen</p>
                      <p className={`text-sm font-bold mt-2 ${isDarkMode ? 'text-white' : 'text-slate-900'}`}>How can {getAgentShortName()} assist you today?</p>
                    </div>
                  )}
                  {(activeTab === 'Pinel' ? pinelChat : activeTab === 'Lavoisier' ? lavoisierChat : clarkChat).map((msg, i) => (
                    <div key={i} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                      <div className={`max-w-[85%] p-4 rounded-2xl text-xs md:text-sm font-semibold shadow-sm ${msg.role === 'user' ? 'bg-[#1368ce] text-white rounded-tr-none' : 'bg-gray-100 dark:bg-slate-700 text-slate-800 dark:text-white rounded-tl-none border-b-2 border-gray-200 dark:border-slate-600'}`}>
                        {msg.text}
                      </div>
                    </div>
                  ))}
                  {isLoading && (
                    <div className="flex justify-start">
                      <div className="bg-gray-100 dark:bg-slate-700 p-4 rounded-2xl animate-pulse font-black text-[10px] text-slate-600 dark:text-white uppercase tracking-widest">
                        {getAgentShortName()} is transmitting...
                      </div>
                    </div>
                  )}
                </>
              )}
          </div>

          {(activeTab !== 'Community' || selectedCitizen) && (
            <div className={`p-4 border-t ${isDarkMode ? 'border-slate-700 bg-slate-800' : 'border-gray-100 bg-white'}`}>
              <div className="flex gap-2">
                <input 
                  type="text" 
                  value={input}
                  onChange={(e) => setInput(e.target.value)}
                  onKeyDown={(e) => e.key === 'Enter' && (activeTab === 'Community' ? handleCommunitySend() : handleAISend())}
                  placeholder={activeTab === 'Community' ? "Type a message..." : `Consult ${getAgentShortName()}...`}
                  className={`flex-1 p-3 md:p-4 rounded-xl border-2 outline-none focus:border-blue-500 font-bold text-sm md:text-base ${isDarkMode ? 'bg-slate-700 border-slate-600 text-white' : 'bg-gray-50 border-gray-100 text-slate-900'}`}
                />
                <button 
                  onClick={activeTab === 'Community' ? handleCommunitySend : handleAISend}
                  className={`p-4 rounded-xl text-white transition-transform active:scale-95 shadow-lg ${activeTab === 'Pinel' ? 'bg-[#46178f]' : activeTab === 'Lavoisier' ? 'bg-[#26890c]' : activeTab === 'RonClark' ? 'bg-[#ffa602]' : 'bg-[#1368ce]'}`}
                >
                  <Send size={24} />
                </button>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default CityHallSection;

import React, { useState, useEffect, useMemo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { User, Mood, Section, Post, Comment, Message } from './types';
import Sidebar from './components/Sidebar';
import MoodCheckIn from './components/MoodCheckIn';
import HomeSection from './sections/HomeSection';
import MoodSection from './sections/MoodSection';
import ZodiacSection from './sections/ZodiacSection';
import CityHallSection from './sections/CityHallSection';
import ProfileSection from './sections/ProfileSection';
import SettingsSection from './sections/SettingsSection';
import AuthScreen from './sections/AuthScreen';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [activeSection, setActiveSection] = useState<Section>('Home');
  const [isMoodModalOpen, setIsMoodModalOpen] = useState(false);
  const [isDarkMode, setIsDarkMode] = useState(false);
  const [allPosts, setAllPosts] = useState<Post[]>([]);
  const [allMessages, setAllMessages] = useState<Message[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);

  // Initial Load
  useEffect(() => {
    const savedUser = localStorage.getItem('mooderia_user');
    const savedPosts = localStorage.getItem('mooderia_posts');
    const savedMessages = localStorage.getItem('mooderia_messages');
    const savedTheme = localStorage.getItem('mooderia_theme');

    if (savedUser) setCurrentUser(JSON.parse(savedUser));
    if (savedPosts) setAllPosts(JSON.parse(savedPosts));
    if (savedMessages) setAllMessages(JSON.parse(savedMessages));
    if (savedTheme === 'dark') setIsDarkMode(true);

    setIsLoaded(true);
  }, []);

  // Save on changes - only after initial load is complete
  useEffect(() => {
    if (!isLoaded) return;

    if (currentUser) {
      localStorage.setItem('mooderia_user', JSON.stringify(currentUser));

      const allUsersStr = localStorage.getItem('mooderia_all_users') || '[]';
      const allUsers: User[] = JSON.parse(allUsersStr);
      const userIndex = allUsers.findIndex(u => u.email === currentUser.email);

      if (userIndex > -1) {
        allUsers[userIndex] = currentUser;
      } else {
        allUsers.push(currentUser);
      }
      localStorage.setItem('mooderia_all_users', JSON.stringify(allUsers));
    }

    localStorage.setItem('mooderia_posts', JSON.stringify(allPosts));
    localStorage.setItem('mooderia_messages', JSON.stringify(allMessages));
    localStorage.setItem('mooderia_theme', isDarkMode ? 'dark' : 'light');
  }, [currentUser, allPosts, allMessages, isDarkMode, isLoaded]);

  const handleLogin = (user: User) => {
    setCurrentUser(user);
    const today = new Date().toDateString();
    const hasCheckedMoodToday = user.moodHistory.some(m => m.date === today);
    if (!hasCheckedMoodToday) {
      setIsMoodModalOpen(true);
    }
    if (user.lastMoodDate) {
      const lastDate = new Date(user.lastMoodDate);
      const todayDate = new Date(today);
      const diffDays = Math.floor((todayDate.getTime() - lastDate.getTime()) / (1000 * 3600 * 24));
      if (diffDays > 1) {
        setCurrentUser({ ...user, moodStreak: 0 });
      }
    }
  };

  const handleLogout = () => {
    setCurrentUser(null);
    localStorage.removeItem('mooderia_user');
    setActiveSection('Home');
  };

  const submitMood = (mood: Mood) => {
    if (!currentUser) return;
    const today = new Date().toDateString();
    let newStreak = currentUser.moodStreak || 0;
    if (currentUser.lastMoodDate) {
      const lastDate = new Date(currentUser.lastMoodDate);
      const todayDate = new Date(today);
      const diffDays = Math.floor((todayDate.getTime() - lastDate.getTime()) / (1000 * 3600 * 24));
      if (diffDays === 1) newStreak += 1;
      else if (diffDays > 1) newStreak = 1;
    } else {
      newStreak = 1;
    }
    const updatedUser = {
      ...currentUser,
      moodStreak: newStreak,
      lastMoodDate: today,
      moodHistory: [...currentUser.moodHistory, { date: today, mood }]
    };
    setCurrentUser(updatedUser);
    setIsMoodModalOpen(false);
  };

  const addPost = (content: string) => {
    if (!currentUser) return;
    const newPost: Post = {
      id: Math.random().toString(36).substr(2, 9),
      author: currentUser.username,
      content,
      hearts: 0,
      comments: [],
      timestamp: Date.now()
    };
    setAllPosts(prev => [newPost, ...prev]);
  };

  const sendMessage = (recipient: string, text: string) => {
    if (!currentUser) return;
    const newMessage: Message = {
      id: Math.random().toString(36).substr(2, 9),
      sender: currentUser.username,
      recipient,
      text,
      timestamp: Date.now(),
      read: false
    };
    setAllMessages(prev => [...prev, newMessage]);
  };

  const markMessagesAsRead = (withUsername: string) => {
    if (!currentUser) return;
    setAllMessages(prev => prev.map(msg => {
      if (msg.recipient === currentUser.username && msg.sender === withUsername) {
        return { ...msg, read: true };
      }
      return msg;
    }));
  };

  const toggleHeart = (postId: string) => {
    setAllPosts(prev => prev.map(p => {
      if (p.id === postId) return { ...p, hearts: p.hearts + 1 };
      return p;
    }));
  };

  const handleFollow = (username: string) => {
    if (!currentUser) return;
    const isFollowing = currentUser.following.includes(username);
    if (isFollowing) {
      setCurrentUser({ ...currentUser, following: currentUser.following.filter(u => u !== username) });
    } else {
      setCurrentUser({ ...currentUser, following: [...currentUser.following, username] });
    }
  };

  const handleBlockUser = (username: string) => {
    if (!currentUser) return;
    if (!currentUser.blockedUsers.includes(username)) {
      setCurrentUser({
        ...currentUser,
        blockedUsers: [...currentUser.blockedUsers, username],
        following: currentUser.following.filter(u => u !== username),
        friends: (currentUser.friends || []).filter(u => u !== username)
      });
      alert(`User @${username} has been blocked.`);
    }
  };

  const handleUnblockUser = (username: string) => {
    if (!currentUser) return;
    setCurrentUser({
      ...currentUser,
      blockedUsers: currentUser.blockedUsers.filter(u => u !== username)
    });
  };

  const addComment = (postId: string, text: string) => {
    if (!currentUser) return;
    setAllPosts(prev => prev.map(p => {
      if (p.id === postId) {
        const newComment: Comment = {
          id: Math.random().toString(36).substr(2, 9),
          author: currentUser.username,
          text,
          replies: []
        };
        return { ...p, comments: [...p.comments, newComment] };
      }
      return p;
    }));
  };

  const repost = (post: Post) => {
    if (!currentUser) return;
    const newRepost: Post = {
      ...post,
      id: Math.random().toString(36).substr(2, 9),
      isRepost: true,
      originalAuthor: post.author,
      author: currentUser.username,
      timestamp: Date.now()
    };
    setAllPosts(prev => [newRepost, ...prev]);
    setCurrentUser({ ...currentUser, reposts: [newRepost, ...(currentUser.reposts || [])] });
  };

  const updateProfile = (displayName: string, username: string, profilePic?: string, title?: string, bannerPic?: string, profileColor?: string) => {
    if (!currentUser) return;
    setCurrentUser({ ...currentUser, displayName, username, profilePic, title, bannerPic, profileColor });
  };

  const unreadCount = useMemo(() => {
    if (!currentUser) return 0;
    return allMessages.filter(m => m.recipient === currentUser.username && !m.read).length;
  }, [allMessages, currentUser]);

  const visiblePosts = useMemo(() => {
    return allPosts.filter(p => !currentUser?.blockedUsers.includes(p.author));
  }, [allPosts, currentUser?.blockedUsers]);

  if (!currentUser) {
    return <AuthScreen onLogin={handleLogin} />;
  }

  return (
    <div className={`min-h-screen ${isDarkMode ? 'bg-slate-900 text-white' : 'bg-gray-50 text-slate-900'} transition-colors duration-300`}>
      <AnimatePresence>
        {isMoodModalOpen && (
          <MoodCheckIn onSubmit={submitMood} isDarkMode={isDarkMode} />
        )}
      </AnimatePresence>

      <div className="flex flex-col md:flex-row min-h-screen">
        <Sidebar 
          activeSection={activeSection} 
          onNavigate={setActiveSection} 
          isDarkMode={isDarkMode}
          user={currentUser}
          unreadMessages={unreadCount}
        />

        <main className="flex-1 p-4 md:p-8 pt-20 pb-24 md:pt-8 md:pb-8 overflow-y-auto">
          <motion.div
            key={activeSection}
            initial={{ opacity: 0, scale: 0.98 }}
            animate={{ opacity: 1, scale: 1 }}
            exit={{ opacity: 0, scale: 1.02 }}
            transition={{ type: "spring", stiffness: 100, damping: 20 }}
            className="max-w-5xl mx-auto"
          >
            {activeSection === 'Home' && (
              <HomeSection user={currentUser} posts={visiblePosts} isDarkMode={isDarkMode} />
            )}
            {activeSection === 'Mood' && (
              <MoodSection 
                user={currentUser} 
                posts={visiblePosts} 
                onPost={addPost} 
                onHeart={toggleHeart} 
                onComment={addComment}
                onRepost={repost}
                onFollow={handleFollow}
                onBlock={handleBlockUser}
                isDarkMode={isDarkMode}
              />
            )}
            {activeSection === 'Zodiac' && (
              <ZodiacSection isDarkMode={isDarkMode} />
            )}
            {activeSection === 'CityHall' && (
              <CityHallSection 
                isDarkMode={isDarkMode} 
                currentUser={currentUser}
                messages={allMessages}
                onSendMessage={sendMessage}
                onReadMessages={markMessagesAsRead}
              />
            )}
            {activeSection === 'Profile' && (
              <ProfileSection 
                user={currentUser} 
                allPosts={visiblePosts} 
                isDarkMode={isDarkMode}
                onEditProfile={updateProfile}
                onBlock={handleBlockUser}
              />
            )}
            {activeSection === 'Settings' && (
              <SettingsSection 
                isDarkMode={isDarkMode} 
                onToggleDarkMode={() => setIsDarkMode(!isDarkMode)}
                onLogout={handleLogout}
                user={currentUser}
                onUnblock={handleUnblockUser}
              />
            )}
          </motion.div>
        </main>
      </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Heart, MessageCircle, Repeat, Send, Brain, Sparkles, Wind, ShieldAlert, CheckCircle2, Play, Pause, RefreshCw, X } from 'lucide-react';
import { User, Post, Mood, Comment } from '../types';
import { getTellerResponse } from '../services/geminiService';

interface MoodSectionProps {
  user: User;
  posts: Post[];
  onPost: (content: string) => void;
  onHeart: (postId: string) => void;
  onComment: (postId: string, text: string) => void;
  onRepost: (post: Post) => void;
  onFollow: (username: string) => void;
  onBlock: (username: string) => void;
  isDarkMode: boolean;
}

type MoodSubTab = 'Express' | 'Teller' | 'Quiz' | 'Meditation';

const QUIZ_QUESTIONS = [
  {
    question: "How do you typically start your morning in the metropolis?",
    options: [
      { text: "With a huge smile and high energy!", mood: 'Happy' },
      { text: "Slowly, wondering if I can stay in bed...", mood: 'Tired' },
      { text: "Checking my to-do list with intense focus.", mood: 'Angry' },
      { text: "Quietly, with a cup of coffee and some reflection.", mood: 'Sad' }
    ]
  },
  {
    question: "A giant robot is blocking the street! Your reaction?",
    options: [
      { text: "Yell at it to move! I have places to be!", mood: 'Angry' },
      { text: "Take a selfie with it! How cool!", mood: 'Happy' },
      { text: "Sigh... typical Monday in Mooderia.", mood: 'Sad' },
      { text: "Just walk around it, I'm too sleepy to care.", mood: 'Tired' }
    ]
  },
  {
    question: "What's your favorite district vibe?",
    options: [
      { text: "Neon lights and 24/7 parties.", mood: 'Happy' },
      { text: "Rainy windows and jazz cafes.", mood: 'Sad' },
      { text: "High-stakes boardrooms and power.", mood: 'Angry' },
      { text: "Cloud-soft pillows and silence.", mood: 'Tired' }
    ]
  }
];

const MoodSection: React.FC<MoodSectionProps> = ({ user, posts, onPost, onHeart, onComment, onRepost, onFollow, onBlock, isDarkMode }) => {
  const [subTab, setSubTab] = useState<MoodSubTab>('Express');
  const [postContent, setPostContent] = useState('');
  const [tellerQuestion, setTellerQuestion] = useState('');
  const [tellerAnswer, setTellerAnswer] = useState('');
  const [isTellerLoading, setIsTellerLoading] = useState(false);
  const [feedFilter, setFeedFilter] = useState<'All' | 'Following'>('All');

  // Comment System State
  const [expandedComments, setExpandedComments] = useState<string | null>(null);
  const [newComment, setNewComment] = useState('');

  // Quiz State
  const [quizStep, setQuizStep] = useState<number | 'result'>(0);
  const [quizAnswers, setQuizAnswers] = useState<string[]>([]);

  // Meditation State
  const [meditationActive, setMeditationActive] = useState(false);
  const [meditationPhase, setMeditationPhase] = useState<'Inhale' | 'Hold' | 'Exhale' | 'Idle'>('Idle');
  const [timer, setTimer] = useState(0);
  const meditationInterval = useRef<number | null>(null);

  const filteredPosts = feedFilter === 'All' 
    ? posts 
    : posts.filter(p => user.following.includes(p.author) || p.author === user.username);

  // --- Quiz Logic ---
  const handleQuizAnswer = (mood: string) => {
    const newAnswers = [...quizAnswers, mood];
    setQuizAnswers(newAnswers);
    if (typeof quizStep === 'number') {
      if (quizStep < QUIZ_QUESTIONS.length - 1) {
        setQuizStep(quizStep + 1);
      } else {
        setQuizStep('result');
      }
    }
  };

  const calculateQuizResult = () => {
    const counts: Record<string, number> = {};
    quizAnswers.forEach(m => counts[m] = (counts[m] || 0) + 1);
    const topMood = Object.keys(counts).reduce((a, b) => counts[a] > counts[b] ? a : b);

    switch(topMood) {
      case 'Happy': return { title: "Joy District Elite", desc: "You belong in the neon-soaked streets of happiness!", icon: "✨" };
      case 'Sad': return { title: "Blue Bayou Poet", desc: "You find beauty in the city's melancholic rain.", icon: "🌊" };
      case 'Angry': return { title: "Ember Peak Commander", desc: "Your fiery passion drives the city's industry!", icon: "🔥" };
      case 'Tired': return { title: "Slumber Sanctuary Sage", desc: "You are the master of the quiet, cozy corners.", icon: "💤" };
      default: return { title: "Metropolis Wanderer", desc: "You fit in everywhere!", icon: "🏙️" };
    }
  };

  // --- Meditation Logic ---
  useEffect(() => {
    if (meditationActive) {
      let currentPhase: 'Inhale' | 'Hold' | 'Exhale' = 'Inhale';
      let timeLeft = 4;
      setMeditationPhase('Inhale');
      setTimer(4);

      meditationInterval.current = window.setInterval(() => {
        timeLeft -= 1;
        setTimer(timeLeft);

        if (timeLeft <= 0) {
          if (currentPhase === 'Inhale') {
            currentPhase = 'Hold';
            timeLeft = 7;
          } else if (currentPhase === 'Hold') {
            currentPhase = 'Exhale';
            timeLeft = 8;
          } else {
            currentPhase = 'Inhale';
            timeLeft = 4;
          }
          setMeditationPhase(currentPhase);
          setTimer(timeLeft);
        }
      }, 1000);
    } else {
      if (meditationInterval.current) clearInterval(meditationInterval.current);
      setMeditationPhase('Idle');
      setTimer(0);
    }
    return () => { if (meditationInterval.current) clearInterval(meditationInterval.current); };
  }, [meditationActive]);

  const handlePost = () => {
    if (!postContent.trim()) return;
    onPost(postContent);
    setPostContent('');
  };

  const handleTeller = async () => {
    if (!tellerQuestion.trim()) return;
    setIsTellerLoading(true);
    try {
      const res = await getTellerResponse(tellerQuestion);
      setTellerAnswer(res || "The stars are silent right now...");
    } catch (e) {
      setTellerAnswer("A cloud obscures my vision.");
    } finally {
      setIsTellerLoading(false);
    }
  };

  const submitComment = (postId: string) => {
    if (!newComment.trim()) return;
    onComment(postId, newComment);
    setNewComment('');
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center -mx-4 px-4 overflow-x-auto no-scrollbar">
        <div className="flex gap-2 pb-2">
          {['Express', 'Teller', 'Quiz', 'Meditation'].map((tab) => (
            <button
              key={tab}
              onClick={() => setSubTab(tab as MoodSubTab)}
              className={`px-5 py-2.5 rounded-full font-black whitespace-nowrap transition-all text-xs md:text-sm ${subTab === tab ? 'bg-[#46178f] text-white scale-105 shadow-md' : 'bg-gray-200 dark:bg-slate-700 opacity-70 text-slate-800 dark:text-slate-300'}`}
            >
              {tab.toUpperCase()}
            </button>
          ))}
        </div>
      </div>

      {subTab === 'Express' && (
        <div className="space-y-6">
          <div className="flex gap-2 p-1.5 bg-gray-200 dark:bg-slate-800 rounded-2xl w-fit">
            <button onClick={() => setFeedFilter('All')} className={`px-4 py-1.5 rounded-xl text-xs font-black transition-all ${feedFilter === 'All' ? 'bg-white dark:bg-slate-700 shadow-sm text-slate-900 dark:text-white' : 'opacity-50 text-slate-600 dark:text-slate-400'}`}>ALL MOODS</button>
            <button onClick={() => setFeedFilter('Following')} className={`px-4 py-1.5 rounded-xl text-xs font-black transition-all ${feedFilter === 'Following' ? 'bg-white dark:bg-slate-700 shadow-sm text-slate-900 dark:text-white' : 'opacity-50 text-slate-600 dark:text-slate-400'}`}>FOLLOWING</button>
          </div>

          <div className={`p-6 rounded-[2rem] ${isDarkMode ? 'bg-slate-800' : 'bg-white'} shadow-xl`}>
            <textarea value={postContent} onChange={(e) => setPostContent(e.target.value)} placeholder="What's your emotional status today, citizen?" className={`w-full p-4 rounded-xl border-2 focus:border-[#46178f] outline-none transition-all text-sm md:text-base ${isDarkMode ? 'bg-slate-700 border-slate-600 text-white' : 'bg-gray-50 border-gray-100 text-slate-900'}`} rows={3} />
            <div className="flex justify-end mt-4">
              <button onClick={handlePost} className="kahoot-button-blue px-6 py-2.5 text-white rounded-xl font-black text-xs md:text-sm flex items-center gap-2 transition-transform active:scale-95"><Send size={16} /> EXPRESS IT</button>
            </div>
          </div>

          <div className="space-y-4">
            {filteredPosts.length === 0 ? (
              <div className="py-20 text-center opacity-40 font-black italic uppercase tracking-widest text-xs">The streets are quiet...</div>
            ) : filteredPosts.map(post => (
                <motion.div layout key={post.id} className={`p-6 rounded-[2.5rem] ${isDarkMode ? 'bg-slate-800 text-white' : 'bg-white text-slate-900'} shadow-md border-b-4 border-gray-200 dark:border-slate-700`}>
                  <div className="flex items-center justify-between mb-4">
                    <div className="flex items-center gap-3">
                      <div className="w-10 h-10 rounded-2xl bg-gradient-to-tr from-blue-400 to-purple-400 flex items-center justify-center text-white font-black overflow-hidden">
                        {post.author[0].toUpperCase()}
                      </div>
                      <div>
                        <h4 className="font-black text-sm">@{post.author}</h4>
                        {post.isRepost && <p className="text-[10px] font-bold opacity-50 flex items-center gap-1"><Repeat size={8}/> Reposted from @{post.originalAuthor}</p>}
                      </div>
                    </div>
                  </div>
                  <p className="text-base md:text-lg mb-6 leading-relaxed font-medium">{post.content}</p>

                  <div className="flex items-center gap-6 pt-4 border-t border-gray-100 dark:border-slate-700">
                    <button onClick={() => onHeart(post.id)} className="flex items-center gap-1.5 text-red-500 font-black text-xs transition-transform active:scale-110 hover:opacity-80"><Heart size={18} fill={post.hearts > 0 ? "currentColor" : "none"} /> {post.hearts}</button>
                    <button onClick={() => setExpandedComments(expandedComments === post.id ? null : post.id)} className="flex items-center gap-1.5 text-blue-500 font-black text-xs hover:opacity-80"><MessageCircle size={18} /> {post.comments.length}</button>
                    <button onClick={() => onRepost(post)} className="flex items-center gap-1.5 text-green-500 font-black text-xs hover:opacity-80 transition-transform active:rotate-180"><Repeat size={18} /> REPOST</button>
                  </div>

                  {/* Comment Section */}
                  <AnimatePresence>
                    {expandedComments === post.id && (
                      <motion.div initial={{ height: 0, opacity: 0 }} animate={{ height: 'auto', opacity: 1 }} exit={{ height: 0, opacity: 0 }} className="mt-6 pt-6 border-t border-gray-100 dark:border-slate-700 space-y-4">
                         <div className="flex gap-2">
                           <input 
                             type="text" 
                             value={newComment}
                             onChange={(e) => setNewComment(e.target.value)}
                             onKeyDown={(e) => e.key === 'Enter' && submitComment(post.id)}
                             placeholder="Add a citizen feedback..."
                             className={`flex-1 p-3 rounded-xl text-xs font-bold outline-none border-2 focus:border-blue-500 ${isDarkMode ? 'bg-slate-700 border-slate-600' : 'bg-gray-50 border-gray-200'}`}
                           />
                           <button onClick={() => submitComment(post.id)} className="p-3 bg-blue-500 text-white rounded-xl shadow-md"><Send size={16} /></button>
                         </div>

                         <div className="space-y-3 max-h-60 overflow-y-auto custom-scrollbar">
                           {post.comments.length === 0 ? (
                             <p className="text-[10px] font-black opacity-30 text-center uppercase tracking-widest py-4">No comments yet.</p>
                           ) : post.comments.map(c => (
                             <div key={c.id} className="flex gap-3 items-start">
                               <div className="w-8 h-8 rounded-lg bg-gray-200 dark:bg-slate-700 shrink-0 flex items-center justify-center font-black text-[10px] uppercase">{c.author[0]}</div>
                               <div className="flex-1">
                                 <p className="text-[10px] font-black italic">@{c.author}</p>
                                 <p className="text-xs font-medium opacity-80">{c.text}</p>
                               </div>
                             </div>
                           ))}
                         </div>
                      </motion.div>
                    )}
                  </AnimatePresence>
                </motion.div>
            ))}
          </div>
        </div>
      )}

      {subTab === 'Teller' && (
        <div className={`p-6 md:p-10 rounded-[2.5rem] text-center bg-gradient-to-b from-[#46178f] to-[#1368ce] text-white shadow-2xl`}>
          <Sparkles className="mx-auto mb-6 text-yellow-400" size={48} />
          <h2 className="text-2xl md:text-4xl font-black mb-4 uppercase italic">The Mooderia Oracle</h2>
          <div className="max-w-xl mx-auto space-y-4">
            <input type="text" value={tellerQuestion} onChange={(e) => setTellerQuestion(e.target.value)} placeholder="Will I find peace today?" className="w-full p-4 rounded-2xl text-slate-900 font-bold text-center focus:outline-none focus:ring-4 ring-yellow-400 text-sm md:text-base" />
            <button disabled={isTellerLoading} onClick={handleTeller} className={`w-full p-4 rounded-2xl kahoot-button-yellow text-white font-black text-lg md:text-xl transition-all ${isTellerLoading ? 'opacity-50 animate-pulse' : ''}`}>{isTellerLoading ? 'CONSULTING...' : 'PREDICT MY FATE'}</button>
          </div>
          {tellerAnswer && (
            <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} className="mt-12 p-6 md:p-8 bg-white/10 backdrop-blur-md rounded-3xl border border-white/20">
              <p className="text-xl md:text-2xl font-black italic">"{tellerAnswer}"</p>
            </motion.div>
          )}
        </div>
      )}

      {subTab === 'Quiz' && (
        <div className={`p-8 rounded-[2.5rem] ${isDarkMode ? 'bg-slate-800 text-white' : 'bg-white text-slate-900'} shadow-xl text-center min-h-[400px] flex flex-col justify-center`}>
          <AnimatePresence mode="wait">
            {quizStep === 'result' ? (
              <motion.div key="result" initial={{ scale: 0.8, opacity: 0 }} animate={{ scale: 1, opacity: 1 }}>
                <div className="text-6xl mb-4">{calculateQuizResult().icon}</div>
                <h2 className="text-3xl font-black mb-2 uppercase italic text-[#26890c]">{calculateQuizResult().title}</h2>
                <p className="text-lg font-bold opacity-70 mb-8">{calculateQuizResult().desc}</p>
                <button onClick={() => {setQuizStep(0); setQuizAnswers([]);}} className="kahoot-button-blue px-10 py-4 rounded-2xl text-white font-black uppercase">RETAKE QUIZ</button>
              </motion.div>
            ) : (
              <motion.div key={quizStep} initial={{ x: 50, opacity: 0 }} animate={{ x: 0, opacity: 1 }} exit={{ x: -50, opacity: 0 }} className="space-y-6">
                <Brain className="mx-auto mb-6 text-[#26890c]" size={56} />
                <h2 className="text-xl md:text-2xl font-black uppercase tracking-tighter">{QUIZ_QUESTIONS[quizStep].question}</h2>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  {QUIZ_QUESTIONS[quizStep].options.map((opt, i) => {
                    const colors = ['kahoot-button-red', 'kahoot-button-blue', 'kahoot-button-yellow', 'kahoot-button-green'];
                    return (
                      <button key={i} onClick={() => handleQuizAnswer(opt.mood)} className={`${colors[i]} p-6 rounded-2xl text-white font-black text-left flex items-center gap-4 transition-transform active:scale-95`}>
                        <div className="w-8 h-8 rounded-lg bg-white/20 flex items-center justify-center">{i+1}</div>
                        {opt.text}
                      </button>
                    );
                  })}
                </div>
                <p className="text-[10px] font-black opacity-30 uppercase tracking-[0.2em]">Question {quizStep + 1} of {QUIZ_QUESTIONS.length}</p>
              </motion.div>
            )}
          </AnimatePresence>
        </div>
      )}

      {subTab === 'Meditation' && (
        <div className={`p-8 rounded-[2.5rem] ${isDarkMode ? 'bg-slate-800 text-white' : 'bg-white text-slate-900'} shadow-xl text-center flex flex-col items-center`}>
          <Wind className="mb-6 text-blue-400" size={56} />
          <h2 className="text-2xl md:text-3xl font-black mb-2 uppercase tracking-tighter italic">Zen Garden</h2>
          <p className="mb-10 opacity-70 font-bold text-sm">4-7-8 Breathing Guide</p>

          <div className="relative w-64 h-64 flex items-center justify-center mb-10">
            {/* Pulsing Orb */}
            <motion.div 
              animate={{ 
                scale: meditationPhase === 'Inhale' ? 1.5 : meditationPhase === 'Exhale' ? 1 : meditationPhase === 'Hold' ? 1.5 : 1,
                opacity: meditationPhase === 'Idle' ? 0.3 : 1
              }}
              transition={{ duration: meditationPhase === 'Inhale' ? 4 : meditationPhase === 'Exhale' ? 8 : 0.5 }}
              className={`absolute w-32 h-32 rounded-full blur-2xl ${meditationPhase === 'Inhale' ? 'bg-blue-400' : meditationPhase === 'Hold' ? 'bg-purple-500' : 'bg-green-400'}`}
            />
            <motion.div 
              animate={{ 
                scale: meditationPhase === 'Inhale' ? 1.5 : meditationPhase === 'Exhale' ? 1 : meditationPhase === 'Hold' ? 1.5 : 1
              }}
              transition={{ duration: meditationPhase === 'Inhale' ? 4 : meditationPhase === 'Exhale' ? 8 : 0.5 }}
              className={`w-32 h-32 rounded-full border-4 flex flex-col items-center justify-center z-10 ${isDarkMode ? 'bg-slate-800' : 'bg-white'} shadow-2xl`}
              style={{ borderColor: meditationPhase === 'Inhale' ? '#60a5fa' : meditationPhase === 'Hold' ? '#a855f7' : '#4ade80' }}
            >
              <span className="text-4xl font-black italic">{timer || '--'}</span>
              <span className="text-[8px] font-black uppercase tracking-widest opacity-50">{meditationPhase}</span>
            </motion.div>
          </div>

          <div className="flex gap-4">
            <button 
              onClick={() => setMeditationActive(!meditationActive)} 
              className={`px-10 py-4 rounded-2xl font-black text-white flex items-center gap-2 shadow-xl transition-all ${meditationActive ? 'bg-red-500 border-b-4 border-red-700' : 'bg-blue-500 border-b-4 border-blue-700'}`}
            >
              {meditationActive ? <Pause size={20} /> : <Play size={20} />}
              {meditationActive ? 'STOP SESSION' : 'START SESSION'}
            </button>
            {meditationActive && (
              <button onClick={() => {setMeditationActive(false); setTimeout(() => setMeditationActive(true), 100);}} className="p-4 rounded-2xl bg-gray-200 dark:bg-slate-700 text-slate-600 dark:text-white border-b-4 border-gray-300 dark:border-slate-900">
                <RefreshCw size={24} />
              </button>
            )}
          </div>

          <div className="mt-12 grid grid-cols-3 gap-8 w-full max-w-sm">
            <div className="text-center">
              <p className="text-xs font-black text-blue-400">4s</p>
              <p className="text-[8px] font-bold uppercase opacity-50">Inhale</p>
            </div>
            <div className="text-center border-x border-gray-100 dark:border-slate-700">
              <p className="text-xs font-black text-purple-400">7s</p>
              <p className="text-[8px] font-bold uppercase opacity-50">Hold</p>
            </div>
            <div className="text-center">
              <p className="text-xs font-black text-green-400">8s</p>
              <p className="text-[8px] font-bold uppercase opacity-50">Exhale</p>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default MoodSection;

