                className={`p-6 rounded-[2.5rem] border-l-8 shadow-xl flex items-center gap-6 transition-all hover:scale-[1.02] ${isDarkMode ? 'text-white' : 'text-slate-900'} ${getColorTheme(notif.type)}`}
