import { User, Message } from '../types';

interface CityHallSectionProps {
  isDarkMode: boolean;
  currentUser: User;
  messages: Message[];
  onSendMessage: (recipient: string, text: string) => void;
  onReadMessages: (withUsername: string) => void;
}

const CityHallSection: React.FC<CityHallSectionProps> = ({ isDarkMode, currentUser, messages, onSendMessage, onReadMessages }) => {
  const [input, setInput] = useState('');
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedCitizen, setSelectedCitizen] = useState<User | null>(null);

  // Get all registered users from local storage
  const allUsers: User[] = useMemo(() => {
    return JSON.parse(localStorage.getItem('mooderia_all_users') || '[]');
  }, []);

  // Filter citizens based on search input
  const filteredCitizens = useMemo(() => {
    if (!searchTerm.trim()) return [];
    return allUsers.filter(u => 
      u.username !== currentUser.username && 
      (u.displayName.toLowerCase().includes(searchTerm.toLowerCase()) || 
       u.username.toLowerCase().includes(searchTerm.toLowerCase()))
    );
  }, [searchTerm, allUsers, currentUser.username]);

  // Find users who have an active conversation with the current user
  const conversationUsers = useMemo(() => {
    const userNames = new Set<string>();
    messages.forEach(m => {
      if (m.sender === currentUser.username) userNames.add(m.recipient);
      if (m.recipient === currentUser.username) userNames.add(m.sender);
    });
    return allUsers.filter(u => userNames.has(u.username));
  }, [messages, allUsers, currentUser.username]);

  // Get messages for the currently selected chat
  const chatMessages = useMemo(() => {
    if (!selectedCitizen) return [];
    return messages.filter(m => 
      (m.sender === currentUser.username && m.recipient === selectedCitizen.username) ||
      (m.sender === selectedCitizen.username && m.recipient === currentUser.username)
    ).sort((a, b) => a.timestamp - b.timestamp);
  }, [messages, selectedCitizen, currentUser.username]);

  // Count unread messages per user
  const unreadPerUser = useMemo(() => {
    const counts: Record<string, number> = {};
    messages.forEach(m => {
      if (m.recipient === currentUser.username && !m.read) {
        counts[m.sender] = (counts[m.sender] || 0) + 1;
      }
    });
    return counts;
  }, [messages, currentUser.username]);

  // Mark messages as read when a citizen is selected
  useEffect(() => {
    if (selectedCitizen) {
      onReadMessages(selectedCitizen.username);
    }
  }, [selectedCitizen, messages.length]);

  const handleCommunitySend = () => {
    if (!input.trim() || !selectedCitizen) return;
    onSendMessage(selectedCitizen.username, input);
    setInput('');
  };

  return (
    <div className="flex flex-col h-[82vh] gap-4">
      <div className="flex justify-between items-center px-2">
        <div>
          <h2 className={`text-4xl font-black italic uppercase tracking-tighter ${isDarkMode ? 'text-white' : 'text-slate-900'}`}>Citizen Hub</h2>
          <p className="text-[10px] font-black opacity-40 uppercase tracking-widest mt-1">Connect with the Metropolis</p>
        </div>
      </div>

      <div className={`flex-1 flex flex-col md:flex-row rounded-[2.5rem] ${isDarkMode ? 'bg-slate-800' : 'bg-white'} shadow-2xl overflow-hidden border-4 border-gray-100 dark:border-slate-700`}>

        {/* Citizen Selection Sidebar */}
        <div className={`w-full md:w-80 border-r ${isDarkMode ? 'border-slate-700' : 'border-gray-100'} flex flex-col ${selectedCitizen ? 'hidden md:flex' : 'flex'}`}>
          <div className="p-5 border-b border-gray-100 dark:border-slate-700 space-y-4">
            <div className="relative">
              <Search className="absolute left-4 top-1/2 -translate-y-1/2 opacity-30" size={18} />
              <input 
                type="text" 
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                placeholder="Search Citizens..."
                className={`w-full pl-11 pr-4 py-3 rounded-2xl text-sm font-bold outline-none border-2 focus:border-blue-500 transition-all ${isDarkMode ? 'bg-slate-700 border-slate-600 text-white' : 'bg-gray-50 border-gray-200 text-slate-900'}`}
              />
            </div>
          </div>

          <div className="flex-1 overflow-y-auto custom-scrollbar p-3 space-y-2">
            {searchTerm.trim() ? (
              <>
                <p className="text-[10px] font-black uppercase tracking-widest opacity-40 mb-3 px-3 mt-2">Citizens Found</p>
                {filteredCitizens.map(u => (
                  <button 
                    key={u.username}
                    onClick={() => { setSelectedCitizen(u); setSearchTerm(''); }}
                    className={`w-full p-4 rounded-2xl flex items-center gap-4 transition-all hover:scale-[0.98] ${selectedCitizen?.username === u.username ? 'bg-blue-600 text-white shadow-lg' : 'hover:bg-gray-50 dark:hover:bg-slate-700'}`}
                  >
                    <div className="w-12 h-12 rounded-2xl bg-blue-100 dark:bg-slate-600 flex items-center justify-center font-black shrink-0 shadow-sm overflow-hidden">
                      {u.profilePic ? <img src={u.profilePic} className="w-full h-full object-cover" alt={u.displayName} /> : u.displayName[0].toUpperCase()}
                    </div>
                    <div className="text-left truncate">
                      <p className="font-black text-sm truncate">{u.displayName}</p>
                      <p className={`text-[10px] font-bold ${selectedCitizen?.username === u.username ? 'text-white/60' : 'opacity-40'} truncate uppercase tracking-tighter`}>@{u.username}</p>
                    </div>
                  </button>
                ))}
                {filteredCitizens.length === 0 && (
                  <div className="py-10 text-center opacity-30">
                    <UserPlus size={32} className="mx-auto mb-2" />
                    <p className="text-[10px] font-black uppercase">No citizen matched.</p>
                  </div>
                )}
