                  <button 
                    key={u.username}
                    onClick={() => setSelectedCitizen(u)}
                    className={`w-full p-4 rounded-2xl flex items-center gap-4 transition-all hover:scale-[0.98] relative ${selectedCitizen?.username === u.username ? 'bg-blue-600 text-white shadow-lg' : 'hover:bg-gray-50 dark:hover:bg-slate-700'}`}
                  >
