                    </div>
                    {unreadPerUser[u.username] > 0 && selectedCitizen?.username !== u.username && (
                      <span className="w-6 h-6 bg-red-500 rounded-full text-[10px] flex items-center justify-center text-white font-black border-2 border-white dark:border-slate-800 shadow-md">
                        {unreadPerUser[u.username]}
                      </span>
                    )}
                  </button>
                ))}
                {conversationUsers.length === 0 && (
                  <div className="h-full flex flex-col items-center justify-center text-center p-8 opacity-20">
                    <Users size={48} className="mb-4" />
                    <p className="text-xs font-black uppercase tracking-tighter">No Active Chats</p>
                    <p className="text-[10px] font-bold mt-1">Search for a citizen to begin communication.</p>
                  </div>
                )}
              </>
            )}
          </div>
        </div>

        {/* Messaging Area */}
        <div className={`flex-1 flex flex-col min-h-0 ${!selectedCitizen ? 'hidden md:flex' : 'flex'}`}>
          <div className={`p-5 border-b ${isDarkMode ? 'bg-slate-700/50 border-slate-700' : 'bg-gray-50 border-gray-100'} flex items-center justify-between gap-3 shadow-sm`}>
            <div className="flex items-center gap-4">
              {selectedCitizen && (
                <button onClick={() => setSelectedCitizen(null)} className="md:hidden p-2 rounded-xl hover:bg-gray-200 dark:hover:bg-slate-600 transition-colors">
                  <ArrowLeft size={24} />
                </button>
              )}
              {selectedCitizen ? (
                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 rounded-xl bg-blue-500 flex items-center justify-center text-white font-black shadow-md overflow-hidden">
                    {selectedCitizen.profilePic ? <img src={selectedCitizen.profilePic} className="w-full h-full object-cover" alt={selectedCitizen.displayName} /> : selectedCitizen.displayName[0].toUpperCase()}
                  </div>
                  <div>
                    <h3 className={`font-black uppercase text-sm ${isDarkMode ? 'text-white' : 'text-slate-900'}`}>{selectedCitizen.displayName}</h3>
                    <p className="text-[9px] font-black text-blue-500 uppercase tracking-widest">Active Citizen</p>
