              ) : (
                <h3 className={`font-black italic uppercase text-sm ${isDarkMode ? 'text-white' : 'text-slate-900'}`}>Select a Conversation</h3>
              )}
            </div>
            {selectedCitizen && (
              <div className="flex items-center gap-2 px-3 py-1.5 bg-green-500/10 rounded-full border border-green-500/20">
                 <ShieldCheck size={14} className="text-green-500" />
                 <span className="text-[9px] font-black text-green-500 uppercase tracking-tighter hidden sm:block">Citizen Security Active</span>
              </div>
            )}
