          <div className="flex-1 overflow-y-auto p-5 space-y-4 custom-scrollbar bg-transparent">
            {!selectedCitizen ? (
              <div className="h-full flex flex-col items-center justify-center text-center p-12 opacity-20">
                <MessageSquare size={80} className="mb-6" />
                <h3 className="text-2xl font-black uppercase italic tracking-tighter">Metropolis Messenger</h3>
                <p className="text-sm font-bold max-w-xs mx-auto mt-2">Connect with neighbors and friends. Your city, your conversations.</p>
