                    animate={{ opacity: 1, y: 0 }}
                    className={`flex ${msg.sender === currentUser.username ? 'justify-end' : 'justify-start'}`}
                  >
                    <div className={`max-w-[75%] p-4 rounded-[1.5rem] text-sm font-bold shadow-md ${msg.sender === currentUser.username ? 'bg-[#1368ce] text-white rounded-tr-none' : 'bg-gray-100 dark:bg-slate-700 text-slate-800 dark:text-white rounded-tl-none border-b-4 border-gray-200 dark:border-slate-600'}`}>
                      {msg.text}
