                  className={`flex-1 p-4 rounded-2xl border-2 outline-none focus:border-blue-500 font-bold text-sm transition-all ${isDarkMode ? 'bg-slate-700 border-slate-600 text-white' : 'bg-gray-50 border-gray-100 text-slate-900'}`}
