        }
    });

    return JSON.parse(response.text.trim());
}

import React, { useState, useEffect, useMemo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { User, Mood, Section, Post, Comment, Message, Notification } from './types';
import Sidebar from './components/Sidebar';
import MoodCheckIn from './components/MoodCheckIn';
import HomeSection from './sections/HomeSection';
import MoodSection from './sections/MoodSection';
import ZodiacSection from './sections/ZodiacSection';
import CityHallSection from './sections/CityHallSection';
import ProfileSection from './sections/ProfileSection';
import SettingsSection from './sections/SettingsSection';
import NotificationsSection from './sections/NotificationsSection';
import AuthScreen from './sections/AuthScreen';
import LoadingScreen from './components/LoadingScreen';
import { getExpNeeded } from './constants';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [activeSection, setActiveSection] = useState<Section>('Home');
  const [viewingUsername, setViewingUsername] = useState<string | null>(null);
  const [isMoodModalOpen, setIsMoodModalOpen] = useState(false);
  const [isDarkMode, setIsDarkMode] = useState(false);
  const [isAppStarting, setIsAppStarting] = useState(true);

  const [allPosts, setAllPosts] = useState<Post[]>([]);
  const [allMessages, setAllMessages] = useState<Message[]>([]);
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);

  useEffect(() => {
    const savedUser = localStorage.getItem('mooderia_user');
    const savedPosts = localStorage.getItem('mooderia_posts') || '[]';
    const savedMessages = localStorage.getItem('mooderia_messages') || '[]';
    const savedNotifications = localStorage.getItem('mooderia_notifications') || '[]';
    const savedTheme = localStorage.getItem('mooderia_theme');

    if (savedUser) {
      let user: User = JSON.parse(savedUser);
      const now = Date.now();
      if (user.petLastUpdate) {
        const secondsPassed = Math.floor((now - user.petLastUpdate) / 1000);
        const hungerDrain = Math.floor(secondsPassed / 3600);
        const thirstDrain = Math.floor(secondsPassed / 1800);
        const restDrain = Math.floor(secondsPassed / 7200);

        user.petHunger = Math.max(0, user.petHunger - hungerDrain);
        user.petThirst = Math.max(0, user.petThirst - thirstDrain);
        user.petRest = Math.max(0, user.petRest - restDrain);
      }
      user.petLastUpdate = now;
      setCurrentUser(user);
    }

    setAllPosts(JSON.parse(savedPosts));
    setAllMessages(JSON.parse(savedMessages));
    setNotifications(JSON.parse(savedNotifications));
    if (savedTheme === 'dark') setIsDarkMode(true);

    setIsLoaded(true);

    const timer = setTimeout(() => {
      setIsAppStarting(false);
    }, 2500);
    return () => clearTimeout(timer);
  }, []);

  useEffect(() => {
    if (!isLoaded) return;

    if (currentUser) {
      localStorage.setItem('mooderia_user', JSON.stringify(currentUser));
      const allUsers: User[] = JSON.parse(localStorage.getItem('mooderia_all_users') || '[]');
      const idx = allUsers.findIndex(u => u.username === currentUser.username);
      if (idx > -1) allUsers[idx] = currentUser;
      else allUsers.push(currentUser);
      localStorage.setItem('mooderia_all_users', JSON.stringify(allUsers));
    }

    localStorage.setItem('mooderia_posts', JSON.stringify(allPosts));
    localStorage.setItem('mooderia_messages', JSON.stringify(allMessages));
    localStorage.setItem('mooderia_notifications', JSON.stringify(notifications));
    localStorage.setItem('mooderia_theme', isDarkMode ? 'dark' : 'light');
  }, [currentUser, allPosts, allMessages, notifications, isDarkMode, isLoaded]);

  // Robust midnight check for streak & modal
  useEffect(() => {
    if (currentUser && currentUser.lastMoodDate !== new Date().toDateString()) {
      setIsMoodModalOpen(true);
    }
  }, [currentUser?.lastMoodDate]);

  const unreadMessages = useMemo(() => 
    allMessages.filter(m => m.recipient === currentUser?.username && !m.read).length, 
    [allMessages, currentUser?.username]
  );

  const unreadNotifs = useMemo(() => 
    notifications.filter(n => !n.read).length, 
    [notifications]
  );

  const visiblePosts = useMemo(() => {
    if (!currentUser) return allPosts;
    return allPosts.filter(p => !currentUser.blockedUsers.includes(p.author));
  }, [allPosts, currentUser?.blockedUsers]);

  const profileToView = useMemo(() => {
    if (!isLoaded) return null;
    const target = viewingUsername || currentUser?.username;
    if (!target) return currentUser;

    const allUsers: User[] = JSON.parse(localStorage.getItem('mooderia_all_users') || '[]');
    return allUsers.find(u => u.username === target) || currentUser;
  }, [viewingUsername, currentUser, isLoaded]);

  const navigateToProfile = (username: string) => {
    setViewingUsername(username);
    setActiveSection('Profile');
  };

  const addPost = (content: string) => {
    if (!currentUser) return;
    const newPost: Post = {
      id: Math.random().toString(36).substr(2, 9),
      author: currentUser.username,
      content,
      hearts: 0,
      comments: [],
      timestamp: Date.now()
    };
    setAllPosts(prev => [newPost, ...prev]);
  };

  const toggleHeart = (postId: string) => {
    setAllPosts(prev => prev.map(p => {
      if (p.id === postId) return { ...p, hearts: p.hearts + 1 };
      return p;
    }));
  };

  const addComment = (postId: string, text: string) => {
    if (!currentUser) return;
    const newComment: Comment = {
      id: Math.random().toString(36).substr(2, 9),
      author: currentUser.username,
      text,
      replies: []
    };
    setAllPosts(prev => prev.map(p => {
      if (p.id === postId) return { ...p, comments: [...p.comments, newComment] };
      return p;
    }));
  };

  const handleFollow = (targetUsername: string) => {
    if (!currentUser || targetUsername === currentUser.username) return;
    const allUsers: User[] = JSON.parse(localStorage.getItem('mooderia_all_users') || '[]');
    const targetIdx = allUsers.findIndex(u => u.username === targetUsername);
    if (targetIdx === -1) return;

    const targetUser = allUsers[targetIdx];
    const isFollowing = currentUser.following.includes(targetUsername);

    let updatedCurrentUser: User;
    let updatedTargetUser: User;

    if (isFollowing) {
      updatedCurrentUser = { ...currentUser, following: currentUser.following.filter(u => u !== targetUsername) };
      updatedTargetUser = { ...targetUser, followers: (targetUser.followers || []).filter(u => u !== currentUser.username) };
    } else {
      updatedCurrentUser = { ...currentUser, following: [...currentUser.following, targetUsername] };
      updatedTargetUser = { ...targetUser, followers: [...(targetUser.followers || []), currentUser.username] };
    }

    setCurrentUser(updatedCurrentUser);
    allUsers[targetIdx] = updatedTargetUser;
    localStorage.setItem('mooderia_all_users', JSON.stringify(allUsers));
  };

  const handleBlockUser = (username: string) => {
    if (!currentUser) return;
    const updated = {
      ...currentUser,
      blockedUsers: [...new Set([...currentUser.blockedUsers, username])],
      following: currentUser.following.filter(u => u !== username)
    };
    setCurrentUser(updated);
    setActiveSection('Home');
  };

  const handleUnblockUser = (username: string) => {
    if (!currentUser) return;
    setCurrentUser({
      ...currentUser,
      blockedUsers: currentUser.blockedUsers.filter(u => u !== username)
    });
  };

  const handleLogout = () => {
    setCurrentUser(null);
    localStorage.removeItem('mooderia_user');
    setActiveSection('Home');
    setViewingUsername(null);
  };

  const submitMood = (mood: Mood) => {
    if (!currentUser) return;
    const today = new Date().toDateString();
    const updatedUser = {
      ...currentUser,
      moodStreak: (currentUser.moodStreak || 0) + 1,
      lastMoodDate: today,
      moodHistory: [...currentUser.moodHistory, { date: today, mood }]
    };
    setCurrentUser(updatedUser);
    setIsMoodModalOpen(false);
  };

  const sendMessage = (recipient: string, text: string) => {
    if (!currentUser) return;
    const newMessage: Message = {
      id: Math.random().toString(36).substr(2, 9),
      sender: currentUser.username,
      recipient,
      text,
      timestamp: Date.now(),
      read: false
    };
    setAllMessages(prev => [...prev, newMessage]);
  };

  const updatePetStats = (hunger: number, thirst: number, rest: number, coins: number, exp: number = 0, sleepUntil: number | null = null, newEmoji?: string, markChosen?: boolean) => {
    if (!currentUser) return;
    let newLevel = currentUser.petLevel;
    let newExp = currentUser.petExp + exp;

    while (newExp >= getExpNeeded(newLevel)) {
      newExp -= getExpNeeded(newLevel);
      newLevel += 1;
    }

    setCurrentUser({
      ...currentUser,
      petEmoji: newEmoji || currentUser.petEmoji,
      petHasBeenChosen: markChosen !== undefined ? markChosen : currentUser.petHasBeenChosen,
      petHunger: Math.min(100, Math.max(0, currentUser.petHunger + hunger)),
      petThirst: Math.min(100, Math.max(0, currentUser.petThirst + thirst)),
      petRest: Math.min(100, Math.max(0, currentUser.petRest + rest)),
      moodCoins: currentUser.moodCoins + coins,
      petLevel: newLevel,
      petExp: newExp,
      petSleepUntil: sleepUntil !== undefined ? sleepUntil : currentUser.petSleepUntil,
      petLastUpdate: Date.now()
    });
  };

  if (isAppStarting) return <LoadingScreen />;

  if (!currentUser) {
    return <AuthScreen onLogin={(user) => { 
      setCurrentUser(user); 
    }} />;
  }

  return (
    <div className={`h-screen max-h-screen overflow-hidden flex flex-col md:flex-row ${isDarkMode ? 'bg-slate-900 text-white' : 'bg-gray-50 text-slate-900'} transition-colors duration-300`}>
      <AnimatePresence>
        {isMoodModalOpen && <MoodCheckIn onSubmit={submitMood} isDarkMode={isDarkMode} />}
      </AnimatePresence>

      <Sidebar 
        activeSection={activeSection} 
        onNavigate={(s) => { setActiveSection(s); if(s === 'Profile') setViewingUsername(currentUser.username); }} 
        isDarkMode={isDarkMode}
        user={currentUser}
        unreadMessages={unreadMessages}
        unreadNotifications={unreadNotifs}
      />

      <main className="flex-1 flex flex-col relative pt-16 pb-20 md:pt-0 md:pb-0 h-full overflow-hidden">
        <div className="flex-1 overflow-hidden p-4 md:p-8">
          <motion.div
            key={activeSection + (activeSection === 'Profile' ? viewingUsername : '')}
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            className="h-full max-w-5xl mx-auto flex flex-col"
          >
            {activeSection === 'Home' && <div className="h-full overflow-y-auto custom-scrollbar pr-2"><HomeSection user={currentUser} posts={visiblePosts} isDarkMode={isDarkMode} /></div>}
            {activeSection === 'Mood' && (
              <MoodSection 
                user={currentUser} posts={visiblePosts} onPost={addPost} onHeart={toggleHeart} 
                onComment={addComment} onRepost={(p) => setAllPosts([ { ...p, id: Math.random().toString(36).substr(2, 9), author: currentUser.username, isRepost: true, originalAuthor: p.author, timestamp: Date.now() }, ...allPosts])} 
                onFollow={handleFollow} onBlock={handleBlockUser} isDarkMode={isDarkMode} 
                onNavigateToProfile={navigateToProfile}
                onUpdatePet={updatePetStats}
              />
            )}
            {activeSection === 'Zodiac' && <div className="h-full overflow-y-auto custom-scrollbar pr-2"><ZodiacSection isDarkMode={isDarkMode} /></div>}
            {activeSection === 'CityHall' && (
              <CityHallSection 
                isDarkMode={isDarkMode} currentUser={currentUser} messages={allMessages} 
                onSendMessage={sendMessage} onReadMessages={(u) => setAllMessages(allMessages.map(m => (m.recipient === currentUser.username && m.sender === u) ? {...m, read: true} : m))} 
                onNavigateToProfile={navigateToProfile} 
              />
            )}
            {activeSection === 'Notifications' && <div className="h-full overflow-y-auto custom-scrollbar pr-2"><NotificationsSection notifications={notifications} isDarkMode={isDarkMode} onMarkRead={() => setNotifications(notifications.map(n => ({...n, read: true})))} /></div>}
            {activeSection === 'Profile' && profileToView && (
              <ProfileSection 
                user={profileToView} allPosts={allPosts} isDarkMode={isDarkMode} 
                onEditProfile={(dn, un, pp, t, bp, pc) => setCurrentUser({...currentUser, displayName: dn, username: un, profilePic: pp, title: t, bannerPic: bp, profileColor: pc})} 
                onBlock={handleBlockUser} onFollow={handleFollow} currentUser={currentUser}
              />
            )}
            {activeSection === 'Settings' && <div className="h-full overflow-y-auto custom-scrollbar pr-2"><SettingsSection isDarkMode={isDarkMode} onToggleDarkMode={() => setIsDarkMode(!isDarkMode)} onLogout={handleLogout} user={currentUser} onUnblock={handleUnblockUser} /></div>}
          </motion.div>
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Heart, MessageCircle, Repeat, Send, Sparkles, Brain, Wind, ShoppingBag, Gamepad2, Bed, Lock, Coins, Ghost, QuestionMark } from 'lucide-react';
import { User, Post, Mood, Comment } from '../types';
import MoodPetSection from './MoodPetSection';
import { getTellerResponse } from '../services/geminiService';
import { QUIZ_QUESTIONS } from '../constants';

interface MoodSectionProps {
  user: User;
  posts: Post[];
  onPost: (content: string) => void;
  onHeart: (postId: string) => void;
  onComment: (postId: string, text: string) => void;
  onRepost: (post: Post) => void;
  onFollow: (username: string) => void;
  onBlock: (username: string) => void;
  isDarkMode: boolean;
  onNavigateToProfile: (username: string) => void;
  onUpdatePet: (hunger: number, thirst: number, rest: number, coins: number, exp?: number, sleepUntil?: number | null, newEmoji?: string, markChosen?: boolean) => void;
}

type MoodSubTab = 'Express' | 'Teller' | 'Quiz' | 'MoodPet';

const MoodSection: React.FC<MoodSectionProps> = ({ user, posts, onPost, onHeart, onComment, onRepost, onFollow, onBlock, isDarkMode, onNavigateToProfile, onUpdatePet }) => {
  const [subTab, setSubTab] = useState<MoodSubTab>('Express');
  const [postContent, setPostContent] = useState('');
  const [feedFilter, setFeedFilter] = useState<'All' | 'Following'>('All');
  const [expandedComments, setExpandedComments] = useState<string | null>(null);
  const [newComment, setNewComment] = useState('');

  // Teller State
  const [tellerQuestion, setTellerQuestion] = useState('');
  const [tellerResponse, setTellerResponse] = useState('');
  const [isTellerLoading, setIsTellerLoading] = useState(false);

  // Quiz State
  const [quizActive, setQuizActive] = useState(false);
  const [quizQuestions, setQuizQuestions] = useState<typeof QUIZ_QUESTIONS>([]);
  const [quizStep, setQuizStep] = useState(0);
  const [quizScore, setQuizScore] = useState(0);
  const [quizFinished, setQuizFinished] = useState(false);

  const startQuiz = () => {
    const shuffled = [...QUIZ_QUESTIONS].sort(() => 0.5 - Math.random()).slice(0, 5);
    setQuizQuestions(shuffled);
    setQuizActive(true);
    setQuizStep(0);
    setQuizScore(0);
    setQuizFinished(false);
  };

  const handleQuizAnswer = (idx: number) => {
    if (idx === quizQuestions[quizStep].a) setQuizScore(s => s + 1);
    if (quizStep < quizQuestions.length - 1) {
      setQuizStep(s => s + 1);
    } else {
      setQuizFinished(true);
      onUpdatePet(0, 0, 0, quizScore * 10, quizScore * 20);
    }
  };

  const handleTeller = async () => {
    if (!tellerQuestion.trim()) return;
    setIsTellerLoading(true);
    setTellerResponse('');
    try {
      const res = await getTellerResponse(tellerQuestion);
      setTellerResponse(res || 'The stars remain silent...');
    } catch (e) {
      setTellerResponse('MAYBE. A cosmic ripple has obscured the vision.');
    } finally {
      setIsTellerLoading(false);
    }
  };

  const filteredPosts = feedFilter === 'All' 
    ? posts 
    : posts.filter(p => user.following.includes(p.author) || p.author === user.username);

  const handlePost = () => {
    if (!postContent.trim()) return;
    onPost(postContent);
    setPostContent('');
  };

  const submitComment = (postId: string) => {
    if (!newComment.trim()) return;
    onComment(postId, newComment);
    setNewComment('');
  };

  return (
    <div className="flex flex-col h-full overflow-hidden">
      <div className="flex items-center justify-between pb-4 shrink-0 overflow-x-auto no-scrollbar">
        <div className="flex gap-2">
          {['Express', 'Teller', 'Quiz', 'MoodPet'].map((tab) => (
            <button
              key={tab}
              onClick={() => setSubTab(tab as MoodSubTab)}
              className={`px-5 py-2.5 rounded-full font-black whitespace-nowrap transition-all text-xs md:text-sm ${subTab === tab ? 'bg-[#46178f] text-white scale-105 shadow-md' : 'bg-gray-200 dark:bg-slate-700 opacity-70 text-slate-800 dark:text-slate-300'}`}
            >
              {tab === 'MoodPet' ? 'MOOD PET 🐾' : tab.toUpperCase()}
            </button>
          ))}
        </div>

        {subTab === 'MoodPet' && (
          <div className="flex items-center gap-2 bg-yellow-400 px-4 py-2 rounded-2xl shadow-lg border-b-4 border-yellow-600 ml-4">
             <Coins className="text-white animate-bounce" size={20} />
             <span className="text-white font-black italic">{user.moodCoins}</span>
          </div>
        )}
      </div>

      <div className="flex-1 overflow-y-auto custom-scrollbar pr-1">
        {subTab === 'Express' && (
          <div className="space-y-6">
            <div className="flex gap-2 p-1.5 bg-gray-200 dark:bg-slate-800 rounded-2xl w-fit shrink-0">
              <button onClick={() => setFeedFilter('All')} className={`px-4 py-1.5 rounded-xl text-xs font-black transition-all ${feedFilter === 'All' ? 'bg-white dark:bg-slate-700 shadow-sm text-slate-900 dark:text-white' : 'opacity-50 text-slate-600 dark:text-slate-400'}`}>ALL MOODS</button>
              <button onClick={() => setFeedFilter('Following')} className={`px-4 py-1.5 rounded-xl text-xs font-black transition-all ${feedFilter === 'Following' ? 'bg-white dark:bg-slate-700 shadow-sm text-slate-900 dark:text-white' : 'opacity-50 text-slate-600 dark:text-slate-400'}`}>FOLLOWING</button>
            </div>

            <div className={`p-6 rounded-[2rem] ${isDarkMode ? 'bg-slate-800' : 'bg-white'} shadow-xl shrink-0`}>
              <textarea value={postContent} onChange={(e) => setPostContent(e.target.value)} placeholder="What's your emotional status today, citizen?" className={`w-full p-4 rounded-xl border-2 focus:border-[#46178f] outline-none transition-all text-sm md:text-base ${isDarkMode ? 'bg-slate-700 border-slate-600 text-white' : 'bg-gray-50 border-gray-100 text-slate-900'}`} rows={2} />
              <div className="flex justify-end mt-4">
                <button onClick={handlePost} className="kahoot-button-blue px-6 py-2.5 text-white rounded-xl font-black text-xs md:text-sm flex items-center gap-2 transition-transform active:scale-95"><Send size={16} /> EXPRESS IT</button>
              </div>
            </div>

            <div className="space-y-4 pb-10">
              {filteredPosts.map(post => (
                  <motion.div layout key={post.id} className={`p-6 rounded-[2.5rem] ${isDarkMode ? 'bg-slate-800 text-white' : 'bg-white text-slate-900'} shadow-md border-b-4 border-gray-200 dark:border-slate-700`}>
                    <div className="flex items-center justify-between mb-4">
                      <button onClick={() => onNavigateToProfile(post.author)} className="flex items-center gap-3 text-left hover:opacity-80 transition-opacity">
                        <div className="w-10 h-10 rounded-2xl bg-gradient-to-tr from-blue-400 to-purple-400 flex items-center justify-center text-white font-black overflow-hidden shadow-sm">
                          {post.author[0].toUpperCase()}
                        </div>
                        <div>
                          <h4 className="font-black text-sm">@{post.author}</h4>
                          {post.isRepost && <p className="text-[10px] font-bold opacity-50 flex items-center gap-1"><Repeat size={8}/> Reposted from @{post.originalAuthor}</p>}
                        </div>
                      </button>
                    </div>
                    <p className="text-base md:text-lg mb-6 leading-relaxed font-medium">{post.content}</p>
                    <div className="flex items-center gap-6 pt-4 border-t border-gray-100 dark:border-slate-700">
                      <button onClick={() => onHeart(post.id)} className="flex items-center gap-1.5 text-red-500 font-black text-xs transition-transform active:scale-110 hover:opacity-80"><Heart size={18} fill={post.hearts > 0 ? "currentColor" : "none"} /> {post.hearts}</button>
                      <button onClick={() => setExpandedComments(expandedComments === post.id ? null : post.id)} className="flex items-center gap-1.5 text-blue-500 font-black text-xs hover:opacity-80"><MessageCircle size={18} /> {post.comments.length}</button>
                      <button onClick={() => onRepost(post)} className="flex items-center gap-1.5 text-green-500 font-black text-xs hover:opacity-80 transition-transform active:rotate-180"><Repeat size={18} /> REPOST</button>
                    </div>
                    <AnimatePresence>
                      {expandedComments === post.id && (
                        <motion.div initial={{ height: 0, opacity: 0 }} animate={{ height: 'auto', opacity: 1 }} exit={{ height: 0, opacity: 0 }} className="mt-6 pt-6 border-t border-gray-100 dark:border-slate-700 space-y-4 overflow-hidden">
                           <div className="flex gap-2">
                             <input type="text" value={newComment} onChange={(e) => setNewComment(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && submitComment(post.id)} placeholder="Add citizen feedback..." className={`flex-1 p-3 rounded-xl text-xs font-bold outline-none border-2 focus:border-blue-500 ${isDarkMode ? 'bg-slate-700 border-slate-600' : 'bg-gray-50 border-gray-200'}`} />
                             <button onClick={() => submitComment(post.id)} className="p-3 bg-blue-500 text-white rounded-xl shadow-md"><Send size={16} /></button>
                           </div>
                        </motion.div>
                      )}
                    </AnimatePresence>
                  </motion.div>
              ))}
            </div>
          </div>
        )}

        {subTab === 'MoodPet' && (
          <MoodPetSection user={user} isDarkMode={isDarkMode} onUpdate={onUpdatePet} onPost={onPost} />
        )}

        {subTab === 'Teller' && (
          <div className="h-full flex flex-col items-center justify-center p-8 text-center">
            <motion.div animate={{ rotate: isTellerLoading ? 360 : 0 }} transition={{ repeat: Infinity, duration: 2, ease: "linear" }} className="mb-8 text-8xl">🔮</motion.div>
            <h3 className="text-3xl font-black italic uppercase text-purple-600 mb-4">Mystic Teller</h3>
            <p className="opacity-60 mb-8 max-w-sm">Ask a yes/no question to the void...</p>
            <div className="w-full max-w-md space-y-4">
              <input type="text" value={tellerQuestion} onChange={e => setTellerQuestion(e.target.value)} placeholder="Will I find my zen today?" className={`w-full p-4 rounded-2xl border-2 outline-none font-black ${isDarkMode ? 'bg-slate-700 border-slate-600 text-white' : 'bg-white border-gray-100'}`} />
              <button onClick={handleTeller} disabled={isTellerLoading} className="kahoot-button-purple w-full p-4 rounded-2xl text-white font-black uppercase text-lg shadow-lg">CONSULT</button>
            </div>
            {tellerResponse && (
              <motion.div initial={{ scale: 0.9, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} className="mt-12 p-8 rounded-[3rem] bg-purple-500/10 border-4 border-purple-500 max-w-md">
                <p className="text-2xl font-black italic text-purple-600 uppercase mb-4">{tellerResponse.split('.')[0]}</p>
                <p className="text-lg font-bold opacity-80">{tellerResponse.split('.').slice(1).join('.')}</p>
              </motion.div>
            )}
          </div>
        )}

        {subTab === 'Quiz' && (
          <div className="h-full p-6">
            {!quizActive ? (
              <div className="h-full flex flex-col items-center justify-center text-center">
                <Brain className="text-green-500 mb-6" size={80} />
                <h3 className="text-4xl font-black italic uppercase mb-4">Mind Palace Quiz</h3>
                <p className="opacity-60 mb-10 max-w-xs">Test your Mooderia knowledge for coins and EXP!</p>
                <button onClick={startQuiz} className="kahoot-button-green px-12 py-5 rounded-[2rem] text-white font-black text-2xl uppercase shadow-xl">START TEST</button>
              </div>
            ) : quizFinished ? (
              <div className="h-full flex flex-col items-center justify-center text-center">
                <Sparkles className="text-yellow-400 mb-6" size={80} />
                <h3 className="text-4xl font-black italic uppercase mb-4">Quiz Complete!</h3>
                <p className="text-2xl font-black mb-2">Score: {quizScore}/5</p>
                <div className="bg-yellow-400/10 p-6 rounded-3xl border-2 border-yellow-400 mb-10">
                  <p className="text-yellow-600 font-black">+{quizScore * 10} Coins & +{quizScore * 20} EXP</p>
                </div>
                <button onClick={startQuiz} className="kahoot-button-blue px-10 py-4 rounded-2xl text-white font-black uppercase shadow-lg">RETRIAL</button>
              </div>
            ) : (
              <div className="max-w-xl mx-auto py-10">
                <div className="flex justify-between items-center mb-10">
                  <span className="text-xs font-black uppercase opacity-40">Question {quizStep + 1} of 5</span>
                  <div className="h-2 flex-1 mx-4 bg-gray-200 rounded-full overflow-hidden">
                    <motion.div initial={{ width: 0 }} animate={{ width: `${(quizStep + 1) * 20}%` }} className="h-full bg-green-500" />
                  </div>
                </div>
                <h4 className="text-2xl md:text-3xl font-black italic mb-10 leading-tight">{quizQuestions[quizStep].q}</h4>
                <div className="grid grid-cols-1 gap-4">
                  {quizQuestions[quizStep].options.map((opt, i) => (
                    <button key={i} onClick={() => handleQuizAnswer(i)} className={`p-6 rounded-2xl border-4 text-left font-black text-lg transition-all active:scale-95 ${isDarkMode ? 'bg-slate-800 border-slate-700 hover:border-blue-500' : 'bg-white border-gray-100 hover:border-blue-500'}`}>{opt}</button>
                  ))}
                </div>
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
};

export default MoodSection;

import React, { useState, useEffect, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { User } from '../types';
import { Coins, ShoppingBag, Gamepad2, Bed, Lock, X, Ghost, Plus, Clock, Smile, Utensils, Droplets, Zap, Target, MousePointer2, Calculator, Share2, Star } from 'lucide-react';
import { getExpNeeded } from '../constants';

interface MoodPetSectionProps {
  user: User;
  isDarkMode: boolean;
  onUpdate: (hunger: number, thirst: number, rest: number, coins: number, exp?: number, sleepUntil?: number | null, newEmoji?: string, markChosen?: boolean) => void;
