  { id: 'd1', type: 'thirst', name: 'Mood Water', emoji: '💧', cost: 5, fill: 10 },
  { id: 'd2', type: 'thirst', name: 'Energy Elixir', emoji: '⚡', cost: 20, fill: 35 },
  { id: 'd3', type: 'thirst', name: 'Royal Tea', emoji: '🍵', cost: 45, fill: 80 },
];

const GAMES = [
  { id: 'g1', name: 'Coin Clicker', difficulty: 'Easy', rewardPerUnit: 0.5, expPerUnit: 1, drain: 5, color: 'bg-green-500', icon: <MousePointer2 size={24}/>, description: 'Click the coin as fast as you can!' },
  { id: 'g2', name: 'Vibe Hunter', difficulty: 'Medium', rewardPerUnit: 5, expPerUnit: 10, drain: 15, color: 'bg-blue-500', icon: <Target size={24}/>, description: 'Catch the moving vibes!' },
  { id: 'g3', name: 'Math Blitz', difficulty: 'Hard', rewardPerUnit: 12, expPerUnit: 25, drain: 30, color: 'bg-purple-600', icon: <Calculator size={24}/>, description: 'Solve equations under pressure!' },
];

const SLEEP_OPTIONS = [
  { id: 's1', label: 'Quick Nap', duration: 10 * 60 * 1000, fill: 20, exp: 50 },
  { id: 's2', label: 'Deep Slumber', duration: 60 * 60 * 1000, fill: 60, exp: 200 },
  { id: 's3', label: 'Cosmic Sleep', duration: 4 * 60 * 60 * 1000, fill: 100, exp: 1000 },
];

const EMOJI_OPTIONS = ['🐱', '🐶', '🦊', '🦁', '🐨', '🐼', '🦄', '🐲'];

const MoodPetSection: React.FC<MoodPetSectionProps> = ({ user, isDarkMode, onUpdate, onPost }) => {
  const [activeTab, setActiveTab] = useState<'Interaction' | 'Shop' | 'Games'>('Interaction');
  const [showSleepModal, setShowSleepModal] = useState(false);
  const [activeGameId, setActiveGameId] = useState<string | null>(null);
  const [timeLeft, setTimeLeft] = useState(0);

  useEffect(() => {
    if (!user.petSleepUntil) return;
    const interval = setInterval(() => {
      const remaining = user.petSleepUntil! - Date.now();
      if (remaining <= 0) {
        onUpdate(0, 0, 100, 0, 0, null);
      } else {
        setTimeLeft(Math.floor(remaining / 1000));
      }
    }, 1000);
    return () => clearInterval(interval);
  }, [user.petSleepUntil]);

  const handleBuy = (item: typeof ITEMS[0]) => {
    if (user.moodCoins < item.cost) return;
    onUpdate(item.type === 'hunger' ? item.fill : 0, item.type === 'thirst' ? item.fill : 0, 0, -item.cost, 5);
  };

  const finishGame = (reward: number, exp: number, drain: number) => {
    onUpdate(0, 0, -drain, Math.floor(reward), Math.floor(exp));
    setActiveGameId(null);
  };

  const shareLevel = () => {
    onPost(`Level Up! My Spirit Pet ${user.petEmoji} just reached LEVEL ${user.petLevel} in Mooderia! 🐾✨ #MoodPet #LevelUp`);
    alert("Citizens have been notified of your growth!");
  };

  if (!user.petHasBeenChosen) {
    return (
      <div className="h-full flex flex-col items-center justify-center p-8 text-center">
        <h3 className="text-4xl font-black italic uppercase mb-4">Choose Your Spirit</h3>
        <p className="opacity-60 mb-10 max-w-sm">Select the guardian that will represent your vibes in Mooderia.</p>
        <div className="grid grid-cols-4 gap-4 max-w-md">
          {EMOJI_OPTIONS.map(e => (
            <button key={e} onClick={() => onUpdate(0,0,0,0,0,null,e,true)} className={`text-5xl p-4 rounded-3xl border-4 border-transparent hover:border-blue-500 transition-all ${isDarkMode ? 'bg-slate-800' : 'bg-white shadow-lg'}`}>{e}</button>
          ))}
        </div>
      </div>
    );
  }

  if (user.petSleepUntil && Date.now() < user.petSleepUntil) {
    const hours = Math.floor(timeLeft / 3600);
    const mins = Math.floor((timeLeft % 3600) / 60);
    const secs = timeLeft % 60;
    return (
      <div className={`h-full flex flex-col items-center justify-center p-8 rounded-[3rem] ${isDarkMode ? 'bg-slate-800' : 'bg-white shadow-2xl'} border-8 border-purple-500/20`}>
        <div className="relative mb-8">
           <div className="text-[120px] filter grayscale opacity-40">💤</div>
           <Lock className="absolute bottom-0 right-0 text-red-500 bg-white p-4 rounded-full shadow-2xl" size={80} />
        </div>
        <h2 className="text-4xl font-black italic uppercase text-[#46178f] mb-4 text-center">Do Not Disturb!</h2>
        <div className="bg-purple-600 text-white px-10 py-6 rounded-[2rem] shadow-[0_10px_0_0_#321067]">
          <p className="text-5xl font-black italic">{hours > 0 ? `${hours}h ` : ''}{mins}m {secs}s</p>
        </div>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-full gap-6">
      {activeGameId ? (
        <GameInterface gameId={activeGameId} isDarkMode={isDarkMode} onFinish={finishGame} />
      ) : (
        <>
          <div className={`flex-1 flex flex-col items-center justify-center p-8 rounded-[3rem] ${isDarkMode ? 'bg-slate-800' : 'bg-white'} shadow-xl border-b-8 border-gray-100 dark:border-slate-700 relative overflow-hidden`}>
            <div className="absolute top-6 left-6 flex items-center gap-2">
               <div className="bg-purple-600 text-white px-4 py-1.5 rounded-full font-black italic text-xs shadow-md">LVL {user.petLevel}</div>
               <button onClick={shareLevel} className="p-1.5 bg-blue-500 text-white rounded-full hover:scale-110 transition-transform"><Share2 size={14}/></button>
            </div>

            <motion.div animate={{ y: [0, -15, 0], scale: [1, 1.05, 1] }} transition={{ duration: 3, repeat: Infinity, ease: "easeInOut" }} className="text-[120px] mb-8 drop-shadow-2xl">
              {user.petHunger < 20 ? '😵' : user.petThirst < 20 ? '🌵' : user.petRest < 20 ? '😴' : user.petEmoji}
            </motion.div>

            <div className="w-full max-w-sm mb-8">
              <div className="flex justify-between items-center text-[10px] font-black uppercase opacity-40 mb-1">
                <span className="flex items-center gap-1"><Star size={12}/> EXP</span>
                <span>{user.petExp} / {getExpNeeded(user.petLevel)}</span>
              </div>
              <div className="h-4 bg-gray-100 dark:bg-slate-700 rounded-full overflow-hidden border border-gray-200">
                <motion.div initial={{ width: 0 }} animate={{ width: `${(user.petExp / getExpNeeded(user.petLevel)) * 100}%` }} className="h-full bg-gradient-to-r from-purple-400 to-pink-500 rounded-full" />
              </div>
            </div>

            <div className="w-full grid grid-cols-3 gap-4">
               {[
                 { label: 'Hunger', val: user.petHunger, color: 'bg-red-500', icon: <Utensils size={14} /> },
                 { label: 'Thirst', val: user.petThirst, color: 'bg-blue-500', icon: <Droplets size={14} /> },
                 { label: 'Rest', val: user.petRest, color: 'bg-green-500', icon: <Zap size={14} /> },
               ].map(bar => (
                 <div key={bar.label} className="space-y-1 text-center">
                   <div className="flex justify-center items-center text-[10px] font-black uppercase opacity-40 gap-1">{bar.icon}{bar.val}%</div>
                   <div className="h-2 bg-gray-100 dark:bg-slate-700 rounded-full overflow-hidden">
                     <motion.div initial={{ width: 0 }} animate={{ width: `${bar.val}%` }} className={`h-full ${bar.color}`} />
                   </div>
                 </div>
               ))}
            </div>
          </div>

          <div className="flex gap-2 shrink-0 overflow-x-auto no-scrollbar pb-2">
             {[
               { id: 'Interaction', icon: <Smile />, color: 'bg-purple-500' },
               { id: 'Shop', icon: <ShoppingBag />, color: 'bg-yellow-500' },
               { id: 'Games', icon: <Gamepad2 />, color: 'bg-blue-500' },
             ].map(btn => (
               <button key={btn.id} onClick={() => setActiveTab(btn.id as any)} className={`flex-1 py-4 px-6 rounded-2xl flex items-center justify-center gap-2 font-black uppercase text-xs transition-all ${activeTab === btn.id ? `${btn.color} text-white shadow-lg scale-105` : 'bg-gray-200 dark:bg-slate-700 opacity-60'}`}>{btn.icon}<span>{btn.id}</span></button>
             ))}
          </div>

          <div className="flex-1 overflow-y-auto custom-scrollbar">
            {activeTab === 'Interaction' && (
              <button onClick={() => setShowSleepModal(true)} className="w-full p-8 rounded-[2rem] bg-[#46178f] text-white flex flex-col items-center justify-center gap-3 shadow-[0_8px_0_0_#321067] active:translate-y-2 active:shadow-none transition-all">
                <Bed size={40} /><span className="font-black italic uppercase text-lg">Send to Bed</span>
              </button>
            )}

            {activeTab === 'Shop' && (
              <div className="space-y-8 pb-10">
                <div className="grid grid-cols-2 gap-4">
                  {ITEMS.map(item => (
                    <button key={item.id} onClick={() => handleBuy(item)} disabled={user.moodCoins < item.cost} className={`p-4 rounded-3xl border-2 flex flex-col items-center text-center gap-1 transition-all ${user.moodCoins < item.cost ? 'opacity-40 grayscale cursor-not-allowed' : 'hover:scale-[1.02] shadow-md'} ${isDarkMode ? 'bg-slate-800 border-slate-700' : 'bg-white border-gray-100'}`}>
                      <span className="text-4xl mb-2">{item.emoji}</span>
                      <p className="text-[10px] font-black uppercase leading-none mb-1">{item.name}</p>
                      <div className="bg-yellow-400 px-3 py-1 rounded-full text-white font-black text-xs flex items-center gap-1"><Coins size={12} /> {item.cost}</div>
                    </button>
                  ))}
                </div>
                <div className="p-6 rounded-[2.5rem] bg-indigo-600 text-white flex flex-col items-center">
                  <h4 className="font-black uppercase italic mb-2">Spirit Evolution</h4>
                  <p className="text-[10px] mb-4 opacity-70">Transform your pet into a new form</p>
                  <div className="flex gap-2 mb-4">
                    {EMOJI_OPTIONS.filter(e => e !== user.petEmoji).slice(0, 4).map(e => (
                      <button key={e} onClick={() => { if(user.moodCoins >= 100) onUpdate(0,0,0,-100,0,undefined,e); }} className="text-2xl p-2 bg-white/20 rounded-xl hover:bg-white/40">{e}</button>
                    ))}
                  </div>
                  <div className="bg-white/20 px-4 py-2 rounded-full font-black text-xs italic">100 COINS</div>
                </div>
              </div>
            )}

            {activeTab === 'Games' && (
              <div className="space-y-4 pb-10">
                {GAMES.map(game => (
                  <div key={game.id} className={`p-6 rounded-[2rem] border-2 flex items-center justify-between gap-4 ${isDarkMode ? 'bg-slate-800 border-slate-700' : 'bg-white border-gray-100'}`}>
                    <div className="flex-1">
                      <div className="flex items-center gap-2 mb-1">
                        <span className="text-blue-500">{game.icon}</span>
                        <h4 className="font-black uppercase italic text-lg leading-none">{game.name}</h4>
                      </div>
                      <p className="text-[10px] font-bold opacity-60 mb-2">{game.description}</p>
                      <div className="flex gap-4">
                        <span className="text-[9px] font-black text-green-500 uppercase">Cost: {game.drain} Rest</span>
                      </div>
                    </div>
                    <button onClick={() => setActiveGameId(game.id)} disabled={user.petRest < game.drain} className={`kahoot-button px-6 py-3 text-white rounded-xl font-black text-xs uppercase shadow-lg ${game.color} ${user.petRest < game.drain ? 'opacity-30 cursor-not-allowed' : ''}`}>PLAY</button>
                  </div>
                ))}
              </div>
            )}
          </div>
        </>
      )}

      <AnimatePresence>
        {showSleepModal && (
          <div className="fixed inset-0 z-[150] flex items-center justify-center p-6 bg-black/60 backdrop-blur-sm">
            <motion.div initial={{ scale: 0.9, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} exit={{ scale: 0.9, opacity: 0 }} className={`w-full max-w-sm rounded-[3rem] p-8 shadow-2xl relative ${isDarkMode ? 'bg-slate-800 text-white' : 'bg-white text-slate-900'}`}>
              <button onClick={() => setShowSleepModal(false)} className="absolute top-6 right-6 opacity-30 hover:opacity-100"><X /></button>
              <div className="text-center mb-8"><Bed className="mx-auto text-purple-500 mb-4" size={48} /><h3 className="text-2xl font-black italic uppercase">Mood Nap</h3></div>
              <div className="space-y-3">
                {SLEEP_OPTIONS.map(opt => (
                  <button key={opt.id} onClick={() => { onUpdate(0, 0, opt.fill, 0, opt.exp, Date.now() + opt.duration); setShowSleepModal(false); }} className={`w-full p-5 rounded-2xl border-2 font-black text-sm uppercase flex justify-between items-center transition-all hover:scale-[1.02] ${isDarkMode ? 'bg-slate-700 border-slate-600' : 'bg-gray-50 border-gray-100'}`}>
                    <div className="flex items-center gap-3"><Clock size={16} /> {opt.label}</div>
                    <div className="text-right text-[10px]"><span className="text-purple-500">+{opt.fill}% REST</span><br/><span className="text-green-500">+{opt.exp} EXP</span></div>
                  </button>
                ))}
              </div>
