const GameInterface: React.FC<any> = ({ gameId, isDarkMode, onFinish }) => {
  const [score, setScore] = useState(0);
  const [timer, setTimer] = useState(gameId === 'g1' ? 10 : gameId === 'g2' ? 15 : 20);
  const [gameState, setGameState] = useState<'IDLE' | 'PLAYING' | 'FINISHED'>('IDLE');

  useEffect(() => {
    if (gameState === 'PLAYING' && timer > 0) {
      const t = setInterval(() => setTimer(prev => prev - 1), 1000);
      return () => clearInterval(t);
    } else if (gameState === 'PLAYING' && timer === 0) {
      setGameState('FINISHED');
    }
  }, [gameState, timer]);

  const handleFinish = () => {
    const game = GAMES.find(g => g.id === gameId);
    if (game) onFinish(score * game.rewardPerUnit, score * game.expPerUnit, game.drain);
  };

  return (
    <div className={`h-full flex flex-col p-6 rounded-[3rem] ${isDarkMode ? 'bg-slate-800' : 'bg-white shadow-2xl'} overflow-hidden`}>
      <div className="flex justify-between items-center mb-6">
        <h3 className="text-xl font-black uppercase italic">{GAMES.find(g => g.id === gameId)?.name}</h3>
        <div className="flex gap-4">
          <div className="bg-yellow-400 text-white px-4 py-2 rounded-xl font-black text-xs flex items-center gap-2 shadow-md"><Coins size={14}/> {score}</div>
          <div className="bg-blue-500 text-white px-4 py-2 rounded-xl font-black text-xs flex items-center gap-2 shadow-md"><Clock size={14}/> {timer}s</div>
        </div>
      </div>
      <div className="flex-1 relative flex items-center justify-center bg-gray-50 dark:bg-slate-900 rounded-[2rem] border-4 border-dashed border-gray-200 dark:border-slate-700 overflow-hidden">
        {gameState === 'IDLE' && (
          <div className="text-center"><p className="text-sm font-bold opacity-50 mb-6 uppercase tracking-widest">Are you ready, citizen?</p><button onClick={() => { setGameState('PLAYING'); }} className="kahoot-button-green px-12 py-4 text-white rounded-2xl font-black text-xl uppercase shadow-xl">GO!</button></div>
        )}
        {gameState === 'PLAYING' && (
          <>
            {gameId === 'g1' && <CoinClickerGame onScore={() => setScore(s => s + 1)} />}
            {gameId === 'g2' && <VibeHunterGame onScore={() => setScore(s => s + 1)} />}
            {gameId === 'g3' && <MathBlitzGame onScore={() => setScore(s => s + 1)} />}
          </>
        )}
        {gameState === 'FINISHED' && (
          <div className="text-center animate-bounce-in">
            <h4 className="text-4xl font-black text-green-500 uppercase mb-2">TIME UP!</h4>
            <div className="space-y-2 mb-6">
               <p className="text-xl font-bold">Rewards:</p>
               <div className="flex justify-center gap-4">
                  <div className="bg-yellow-400 px-4 py-2 rounded-xl text-white font-black text-xs">+{Math.floor(score * (GAMES.find(g => g.id === gameId)?.rewardPerUnit || 0))} COINS</div>
                  <div className="bg-purple-500 px-4 py-2 rounded-xl text-white font-black text-xs">+{Math.floor(score * (GAMES.find(g => g.id === gameId)?.expPerUnit || 0))} EXP</div>
               </div>
            </div>
            <button onClick={handleFinish} className="kahoot-button-blue px-10 py-4 text-white rounded-2xl font-black text-sm uppercase shadow-xl">CLAIM</button>
          </div>
        )}
      </div>
    </div>
  );
};

const CoinClickerGame = ({ onScore }: { onScore: () => void }) => (
  <motion.button whileTap={{ scale: 0.9 }} onClick={onScore} className="w-40 h-40 bg-yellow-400 rounded-full flex items-center justify-center border-b-8 border-yellow-600 shadow-2xl relative"><Coins size={64} className="text-white" /><motion.div animate={{ rotate: 360 }} transition={{ duration: 2, repeat: Infinity, ease: "linear" }} className="absolute inset-0 border-4 border-dashed border-white/30 rounded-full" /></motion.button>
);

const VibeHunterGame = ({ onScore }: { onScore: () => void }) => {
  const [pos, setPos] = useState({ x: 50, y: 50 });
  return <motion.button animate={{ x: `${pos.x}%`, y: `${pos.y}%` }} transition={{ type: "spring", stiffness: 300, damping: 20 }} onClick={() => { onScore(); setPos({ x: Math.random() * 80 + 10, y: Math.random() * 80 + 10 }); }} className="absolute w-16 h-16 bg-blue-500 rounded-2xl border-b-4 border-blue-700 flex items-center justify-center text-white shadow-lg" style={{ left: 0, top: 0, transform: 'translate(-50%, -50%)' }}><Target size={32} /></motion.button>;
};

const MathBlitzGame = ({ onScore }: { onScore: () => void }) => {
  const [problem, setProblem] = useState({ q: '', a: 0 });
  const [input, setInput] = useState('');
  const generate = () => {
    const a = Math.floor(Math.random() * 20) + 1;
    const b = Math.floor(Math.random() * 20) + 1;
    const op = Math.random() > 0.5 ? '+' : '-';
    setProblem({ q: `${a} ${op} ${b}`, a: op === '+' ? a + b : a - b });
  };
  useEffect(generate, []);
  const check = (e: any) => {
    const val = e.target.value;
    setInput(val);
    if (parseInt(val) === problem.a) { onScore(); setInput(''); generate(); }
  };
  return (
    <div className="text-center w-full max-w-xs">
      <h5 className="text-6xl font-black mb-8 italic tracking-tighter text-purple-500">{problem.q} = ?</h5>
      <input autoFocus type="number" value={input} onChange={check} placeholder="Type answer..." className="w-full p-6 rounded-2xl bg-white dark:bg-slate-800 border-4 border-purple-500 text-center text-3xl font-black outline-none shadow-xl" />
    </div>
  );
};

