import React, { useState, useEffect, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { User } from '../types';
import { Coins, ShoppingBag, Gamepad2, Bed, Lock, X, Ghost, Plus, Clock, Smile, Utensils, Droplets, Zap, Target, MousePointer2, Calculator, Share2, Star, Trophy } from 'lucide-react';
