  { id: 'f1', type: 'hunger', name: 'Metropolis Munchies', emoji: '🍿', cost: 10, fill: 15 },
  { id: 'f2', type: 'hunger', name: 'Cosmic Burger', emoji: '🍔', cost: 25, fill: 40 },
