  { id: 'g1', name: 'Coin Clicker', difficulty: 'Easy', rewardPerUnit: 1, expPerUnit: 2, drain: 5, color: 'bg-green-500', icon: <MousePointer2 size={24}/>, description: 'Tap fast to earn coins!' },
  { id: 'g2', name: 'Vibe Hunter', difficulty: 'Medium', rewardPerUnit: 5, expPerUnit: 8, drain: 15, color: 'bg-blue-500', icon: <Target size={24}/>, description: 'Catch the flying vibes!' },
  { id: 'g3', name: 'Math Blitz', difficulty: 'Hard', rewardPerUnit: 15, expPerUnit: 25, drain: 30, color: 'bg-purple-600', icon: <Calculator size={24}/>, description: 'Solve problems for massive rewards!' },
];

const SLEEP_OPTIONS = [
  { id: 's1', label: 'Quick Nap', duration: 10 * 60 * 1000, fill: 20, exp: 50 },
  { id: 's2', label: 'Deep Slumber', duration: 60 * 60 * 1000, fill: 60, exp: 200 },
  { id: 's3', label: 'Cosmic Sleep', duration: 4 * 60 * 60 * 1000, fill: 100, exp: 1000 },
];

const EMOJI_OPTIONS = ['🐱', '🐶', '🦊', '🦁', '🐨', '🐼', '🦄', '🐲', '🐸', '🐹', '🐰', '🐯'];

const MoodPetSection: React.FC<MoodPetSectionProps> = ({ user, isDarkMode, onUpdate, onPost }) => {
  const [activeTab, setActiveTab] = useState<'Interaction' | 'Shop' | 'Games'>('Interaction');
  const [showSleepModal, setShowSleepModal] = useState(false);
  const [activeGameId, setActiveGameId] = useState<string | null>(null);
  const [timeLeft, setTimeLeft] = useState(0);

  useEffect(() => {
    if (!user.petSleepUntil) return;
    const interval = setInterval(() => {
      const remaining = user.petSleepUntil! - Date.now();
      if (remaining <= 0) {
        onUpdate(0, 0, 100, 0, 0, null);
      } else {
        setTimeLeft(Math.floor(remaining / 1000));
      }
    }, 1000);
    return () => clearInterval(interval);
  }, [user.petSleepUntil]);

  const handleBuy = (item: typeof ITEMS[0]) => {
    if (user.moodCoins < item.cost) return;
    onUpdate(item.type === 'hunger' ? item.fill : 0, item.type === 'thirst' ? item.fill : 0, 0, -item.cost, 10);
  };

  const finishGame = (reward: number, exp: number, drain: number) => {
    onUpdate(0, 0, -drain, Math.floor(reward), Math.floor(exp));
    setActiveGameId(null);
  };

  const shareLevel = () => {
    onPost(`LEVEL ${user.petLevel} ACHIEVED! 🏆 My spirit guardian ${user.petEmoji} is thriving in Mooderia. Check out my citizen status! #MoodPet #LevelUp #Mooderia`);
    alert("Citizens in the Express feed have been notified of your pet's growth!");
  };

  if (!user.petHasBeenChosen) {
    return (
      <div className="h-full flex flex-col items-center justify-center p-8 text-center bg-gradient-to-b from-purple-50 to-white dark:from-slate-900 dark:to-slate-800 rounded-[3rem]">
        <motion.div initial={{ scale: 0 }} animate={{ scale: 1 }} className="mb-8 p-6 bg-white dark:bg-slate-800 rounded-full shadow-2xl">
