        <div className="grid grid-cols-4 gap-4 max-w-md">
          {EMOJI_OPTIONS.map(e => (
            <motion.button 
              key={e} 
              whileHover={{ scale: 1.1, rotate: 5 }}
              whileTap={{ scale: 0.9 }}
              onClick={() => onUpdate(0,0,0,0,0,null,e,true)} 
              className={`text-5xl p-6 rounded-[2rem] border-4 border-transparent hover:border-blue-500 transition-all ${isDarkMode ? 'bg-slate-700' : 'bg-white shadow-lg'}`}
            >
              {e}
            </motion.button>
          ))}
        </div>
      </div>
    );
  }

  if (user.petSleepUntil && Date.now() < user.petSleepUntil) {
    const hours = Math.floor(timeLeft / 3600);
    const mins = Math.floor((timeLeft % 3600) / 60);
    const secs = timeLeft % 60;
    return (
      <div className={`h-full flex flex-col items-center justify-center p-8 rounded-[3rem] ${isDarkMode ? 'bg-slate-800' : 'bg-white shadow-2xl'} border-8 border-purple-500/20 relative overflow-hidden`}>
        <div className="absolute top-[-10%] left-[-10%] w-[50%] h-[50%] bg-purple-500/10 blur-[100px] rounded-full"></div>
        <div className="relative mb-12">
