                  </div>
                  <p className="text-[10px] font-black italic opacity-60 mt-1">{user.petExp} / {getExpNeeded(user.petLevel)}</p>
               </div>
            </div>

            <motion.div animate={{ y: [0, -20, 0], scale: [1, 1.08, 1] }} transition={{ duration: 3, repeat: Infinity, ease: "easeInOut" }} className="text-[140px] mb-8 drop-shadow-2xl select-none mt-12">
              {user.petHunger < 25 ? '😵' : user.petThirst < 25 ? '🌵' : user.petRest < 25 ? '😴' : user.petEmoji}
            </motion.div>

            <div className="w-full grid grid-cols-3 gap-6 max-w-sm">
               {[
                 { label: 'Hunger', val: user.petHunger, color: 'bg-red-500', icon: <Utensils size={14} /> },
                 { label: 'Thirst', val: user.petThirst, color: 'bg-blue-500', icon: <Droplets size={14} /> },
                 { label: 'Rest', val: user.petRest, color: 'bg-green-500', icon: <Zap size={14} /> },
               ].map(bar => (
                 <div key={bar.label} className="space-y-2 text-center group">
                   <div className="flex justify-center items-center text-[10px] font-black uppercase opacity-40 gap-1 group-hover:opacity-100 transition-opacity">{bar.icon}{bar.val}%</div>
                   <div className="h-3 bg-gray-100 dark:bg-slate-700 rounded-full overflow-hidden shadow-inner">
                     <motion.div initial={{ width: 0 }} animate={{ width: `${bar.val}%` }} className={`h-full ${bar.color} rounded-full`} />
