             ].map(btn => (
               <button key={btn.id} onClick={() => setActiveTab(btn.id as any)} className={`flex-1 py-5 px-6 rounded-[1.5rem] flex items-center justify-center gap-3 font-black uppercase text-xs transition-all ${activeTab === btn.id ? `${btn.color} text-white shadow-[0_6px_0_0_rgba(0,0,0,0.2)] scale-105` : 'bg-gray-200 dark:bg-slate-700 opacity-60 hover:opacity-100'}`}>
                 {btn.icon}
                 <span className="hidden sm:inline">{btn.id}</span>
               </button>
             ))}
          </div>

          <div className="flex-1 overflow-y-auto custom-scrollbar">
            {activeTab === 'Interaction' && (
              <div className="space-y-4">
                <button onClick={() => setShowSleepModal(true)} className="w-full p-10 rounded-[2.5rem] bg-[#46178f] text-white flex flex-col items-center justify-center gap-4 shadow-[0_10px_0_0_#321067] active:translate-y-2 active:shadow-none transition-all group overflow-hidden relative">
                  <div className="absolute inset-0 bg-white/5 opacity-0 group-hover:opacity-100 transition-opacity"></div>
                  <Bed size={56} className="group-hover:rotate-12 transition-transform" />
                  <span className="font-black italic uppercase text-2xl tracking-tighter">Enter Dream Mode</span>
                  <p className="text-[10px] font-bold opacity-50 uppercase tracking-widest">Restore energy & gain Massive EXP</p>
                </button>
              </div>
            )}

            {activeTab === 'Shop' && (
              <div className="space-y-10 pb-16">
                <div className="grid grid-cols-2 gap-4">
                  {ITEMS.map(item => (
                    <motion.button 
                      key={item.id} 
                      whileHover={{ scale: 1.02 }}
                      whileTap={{ scale: 0.98 }}
                      onClick={() => handleBuy(item)} 
                      disabled={user.moodCoins < item.cost} 
                      className={`p-5 rounded-[2rem] border-4 flex flex-col items-center text-center gap-2 transition-all ${user.moodCoins < item.cost ? 'opacity-40 grayscale cursor-not-allowed' : 'shadow-lg hover:border-yellow-400'} ${isDarkMode ? 'bg-slate-800 border-slate-700' : 'bg-white border-gray-100'}`}
                    >
                      <span className="text-5xl mb-2">{item.emoji}</span>
                      <p className="text-xs font-black uppercase leading-none">{item.name}</p>
                      <p className="text-[9px] font-bold opacity-40 uppercase">+{item.fill}% {item.type}</p>
                      <div className="bg-yellow-400 px-4 py-2 rounded-2xl text-white font-black text-sm flex items-center gap-1 mt-2 shadow-md border-b-4 border-yellow-600"><Coins size={14} /> {item.cost}</div>
                    </motion.button>
                  ))}
                </div>

                {/* Evolution Section */}
                <div className="p-8 rounded-[3rem] bg-indigo-600 text-white flex flex-col items-center shadow-xl relative overflow-hidden">
