                      className={`px-10 py-5 text-white rounded-[1.5rem] font-black text-sm uppercase shadow-xl transition-all active:translate-y-1 ${game.color} ${user.petRest < game.drain ? 'opacity-30 cursor-not-allowed grayscale shadow-none' : 'hover:brightness-110 active:shadow-none'}`}
