const GameInterface: React.FC<any> = ({ gameId, isDarkMode, onFinish }) => {
  const [score, setScore] = useState(0);
  const [timer, setTimer] = useState(gameId === 'g1' ? 10 : gameId === 'g2' ? 15 : 20);
  const [gameState, setGameState] = useState<'IDLE' | 'PLAYING' | 'FINISHED'>('IDLE');
  const gameInfo = GAMES.find(g => g.id === gameId);

  useEffect(() => {
    if (gameState === 'PLAYING' && timer > 0) {
      const t = setInterval(() => setTimer(prev => prev - 1), 1000);
      return () => clearInterval(t);
    } else if (gameState === 'PLAYING' && timer === 0) {
      setGameState('FINISHED');
    }
  }, [gameState, timer]);

  const handleFinish = () => {
    if (gameInfo) onFinish(score * gameInfo.rewardPerUnit, score * gameInfo.expPerUnit, gameInfo.drain);
  };

  return (
    <div className={`h-full flex flex-col p-8 rounded-[3.5rem] ${isDarkMode ? 'bg-slate-800' : 'bg-white shadow-2xl'} overflow-hidden relative`}>
      <div className="flex justify-between items-center mb-8 relative z-10">
        <div>
           <h3 className="text-2xl font-black uppercase italic tracking-tighter text-blue-600 dark:text-blue-400">{gameInfo?.name}</h3>
           <p className="text-[10px] font-black uppercase opacity-40 tracking-widest">Citizen Performance Mode</p>
        </div>
        <div className="flex gap-4">
          <div className="bg-yellow-400 text-white px-6 py-3 rounded-2xl font-black text-sm flex items-center gap-3 shadow-lg border-b-4 border-yellow-600 tabular-nums"><Coins size={20}/> {score}</div>
          <div className="bg-blue-500 text-white px-6 py-3 rounded-2xl font-black text-sm flex items-center gap-3 shadow-lg border-b-4 border-blue-700 tabular-nums"><Clock size={20}/> {timer}s</div>
        </div>
      </div>

      <div className="flex-1 relative flex items-center justify-center bg-gray-50 dark:bg-slate-900/50 rounded-[3rem] border-8 border-dashed border-gray-200 dark:border-slate-800 overflow-hidden shadow-inner">
        {gameState === 'IDLE' && (
          <div className="text-center animate-fade-in">
            <div className="mb-8 scale-150 opacity-40">{gameInfo?.icon}</div>
            <p className="text-lg font-black opacity-60 mb-8 uppercase tracking-widest">Maximize your output, citizen.</p>
            <motion.button 
              whileHover={{ scale: 1.05 }}
              whileTap={{ scale: 0.95 }}
              onClick={() => { setGameState('PLAYING'); }} 
              className="px-16 py-6 bg-green-500 hover:bg-green-600 text-white rounded-[2rem] font-black text-3xl uppercase shadow-[0_12px_0_0_#1c6409] transition-all"
            >
              GO!
            </motion.button>
          </div>
        )}

        {gameState === 'PLAYING' && (
          <>
            {gameId === 'g1' && <CoinClickerGame onScore={() => setScore(s => s + 1)} />}
            {gameId === 'g2' && <VibeHunterGame onScore={() => setScore(s => s + 1)} />}
            {gameId === 'g3' && <MathBlitzGame onScore={() => setScore(s => s + 1)} />}
          </>
        )}

        {gameState === 'FINISHED' && (
          <div className="text-center p-8 bg-white dark:bg-slate-800 rounded-[3rem] shadow-2xl border-4 border-green-500 max-w-sm w-full mx-4">
            <h4 className="text-5xl font-black text-green-500 uppercase italic mb-6 tracking-tighter">TIME UP!</h4>
            <div className="space-y-4 mb-10">
               <div className="flex justify-between items-center bg-yellow-400/10 p-4 rounded-2xl border-2 border-yellow-400/20">
                  <span className="font-black text-xs uppercase opacity-60">Mood Coins Earned</span>
                  <span className="text-2xl font-black text-yellow-500">+{Math.floor(score * (gameInfo?.rewardPerUnit || 0))}</span>
               </div>
               <div className="flex justify-between items-center bg-purple-500/10 p-4 rounded-2xl border-2 border-purple-500/20">
                  <span className="font-black text-xs uppercase opacity-60">Guardian EXP</span>
                  <span className="text-2xl font-black text-purple-500">+{Math.floor(score * (gameInfo?.expPerUnit || 0))}</span>
               </div>
            </div>
            <button onClick={handleFinish} className="w-full py-5 bg-blue-600 hover:bg-blue-700 text-white rounded-2xl font-black text-lg uppercase shadow-[0_8px_0_0_#0e4c99] active:translate-y-1 active:shadow-none transition-all">CLAIM & EXIT</button>
          </div>
        )}
      </div>
    </div>
  );
};

const CoinClickerGame = ({ onScore }: { onScore: () => void }) => (
  <div className="relative flex items-center justify-center w-full h-full">
    <motion.button 
      whileTap={{ scale: 0.8, rotate: [0, 10, -10, 0] }} 
      onClick={onScore} 
      className="w-56 h-56 bg-gradient-to-b from-yellow-300 to-yellow-500 rounded-full flex items-center justify-center border-b-[12px] border-yellow-700 shadow-2xl relative z-10"
    >
      <Coins size={96} className="text-white drop-shadow-lg" />
      <motion.div animate={{ scale: [1, 1.2, 1], opacity: [0.1, 0.3, 0.1] }} transition={{ duration: 1, repeat: Infinity }} className="absolute inset-[-20px] bg-yellow-400 rounded-full blur-xl" />
    </motion.button>
  </div>
);

const VibeHunterGame = ({ onScore }: { onScore: () => void }) => {
  const [pos, setPos] = useState({ x: 50, y: 50 });
  const [vibeEmoji, setVibeEmoji] = useState('✨');
  const vibes = ['✨', '🔥', '⚡', '💎', '🌈', '🌀'];

  const handleHit = () => {
    onScore();
    setPos({ x: Math.random() * 80 + 10, y: Math.random() * 80 + 10 });
    setVibeEmoji(vibes[Math.floor(Math.random() * vibes.length)]);
  };

  return (
    <div className="w-full h-full relative">
      <motion.button 
        animate={{ x: `${pos.x}%`, y: `${pos.y}%` }} 
        transition={{ type: "spring", stiffness: 400, damping: 15 }} 
        onClick={handleHit} 
        className="absolute w-24 h-24 bg-blue-500 rounded-[2rem] border-b-[6px] border-blue-700 flex items-center justify-center text-white shadow-2xl text-4xl"
        style={{ left: 0, top: 0, transform: 'translate(-50%, -50%)' }}
      >
        {vibeEmoji}
      </motion.button>
    </div>
  );
};

const MathBlitzGame = ({ onScore }: { onScore: () => void }) => {
  const [problem, setProblem] = useState({ q: '', a: 0 });
  const [input, setInput] = useState('');

  const generate = () => {
    const a = Math.floor(Math.random() * 30) + 5;
    const b = Math.floor(Math.random() * 30) + 5;
    const op = Math.random() > 0.5 ? '+' : '-';
    setProblem({ q: `${a} ${op} ${b}`, a: op === '+' ? a + b : a - b });
  };

  useEffect(generate, []);

  const check = (e: any) => {
    const val = e.target.value;
    setInput(val);
    if (parseInt(val) === problem.a) { 
      onScore(); 
      setInput(''); 
      generate(); 
    }
  };

  return (
    <div className="text-center w-full max-w-sm p-10 bg-white dark:bg-slate-800 rounded-[3rem] shadow-2xl border-4 border-purple-500 animate-slide-up">
      <h5 className="text-[10px] font-black uppercase tracking-widest opacity-40 mb-10">Solve Transmission Fault</h5>
      <h5 className="text-7xl font-black mb-12 italic tracking-tighter text-purple-600 dark:text-purple-400 tabular-nums">{problem.q} = ?</h5>
      <input 
        autoFocus 
        type="number" 
        value={input} 
        onChange={check} 
        placeholder="..." 
        className="w-full p-8 rounded-[2rem] bg-gray-50 dark:bg-slate-900 border-4 border-purple-500 text-center text-5xl font-black outline-none shadow-inner text-purple-600 dark:text-purple-400" 
      />
    </div>
  );
};

