            >
              {tab === 'MoodPet' ? 'PET PARLOR 🐾' : tab.toUpperCase()}
            </button>
          ))}
        </div>

        <div className="flex items-center gap-3 ml-4">
           <div className="flex items-center gap-2 bg-yellow-400 px-5 py-2.5 rounded-2xl shadow-lg border-b-4 border-yellow-600 transition-transform active:scale-95">
             <Coins className="text-white animate-bounce" size={20} />
             <span className="text-white font-black italic tabular-nums">{user.moodCoins}</span>
          </div>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto custom-scrollbar pr-1 pb-10">
        <AnimatePresence mode="wait">
