import React, { useState, useEffect, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Heart, MessageCircle, Repeat, Send, Sparkles, Brain, Wind, ShoppingBag, Gamepad2, Bed, Lock, Coins, Ghost, QuestionMark, Zap, Calculator, Target } from 'lucide-react';
import { User, Post, Mood, Comment } from '../types';
import MoodPetSection from './MoodPetSection';
import { getTellerResponse } from '../services/geminiService';
import { QUIZ_QUESTIONS } from '../constants';

interface MoodSectionProps {
  user: User;
  posts: Post[];
  onPost: (content: string) => void;
  onHeart: (postId: string) => void;
  onComment: (postId: string, text: string) => void;
  onRepost: (post: Post) => void;
  onFollow: (username: string) => void;
  onBlock: (username: string) => void;
  isDarkMode: boolean;
  onNavigateToProfile: (username: string) => void;
  onUpdatePet: (hunger: number, thirst: number, rest: number, coins: number, exp?: number, sleepUntil?: number | null, newEmoji?: string, markChosen?: boolean) => void;
}

type MoodSubTab = 'Express' | 'Teller' | 'Quiz' | 'MoodPet';

const MoodSection: React.FC<MoodSectionProps> = ({ user, posts, onPost, onHeart, onComment, onRepost, onFollow, onBlock, isDarkMode, onNavigateToProfile, onUpdatePet }) => {
  const [subTab, setSubTab] = useState<MoodSubTab>('Express');
  const [postContent, setPostContent] = useState('');
  const [feedFilter, setFeedFilter] = useState<'All' | 'Following'>('All');
  const [expandedComments, setExpandedComments] = useState<string | null>(null);
  const [newComment, setNewComment] = useState('');

  // Teller State
  const [tellerQuestion, setTellerQuestion] = useState('');
  const [tellerResponse, setTellerResponse] = useState('');
  const [isTellerLoading, setIsTellerLoading] = useState(false);

  // Quiz State
  const [quizActive, setQuizActive] = useState(false);
  const [quizQuestions, setQuizQuestions] = useState<typeof QUIZ_QUESTIONS>([]);
  const [quizStep, setQuizStep] = useState(0);
  const [quizScore, setQuizScore] = useState(0);
  const [quizFinished, setQuizFinished] = useState(false);

  const startQuiz = () => {
    // Randomize 5 questions from the pool
    const shuffled = [...QUIZ_QUESTIONS].sort(() => 0.5 - Math.random()).slice(0, 5);
    setQuizQuestions(shuffled);
    setQuizActive(true);
    setQuizStep(0);
    setQuizScore(0);
    setQuizFinished(false);
  };

  const handleQuizAnswer = (idx: number) => {
    if (idx === quizQuestions[quizStep].a) setQuizScore(s => s + 1);

    if (quizStep < quizQuestions.length - 1) {
      setQuizStep(s => s + 1);
    } else {
      setQuizFinished(true);
      // Reward calculation: 20 coins per correct answer, 50 EXP per correct answer
      onUpdatePet(0, 0, 0, quizScore * 20, quizScore * 50);
    }
  };

  const handleTeller = async () => {
    if (!tellerQuestion.trim()) return;
    setIsTellerLoading(true);
    setTellerResponse('');
    try {
      const res = await getTellerResponse(tellerQuestion);
      setTellerResponse(res || 'The cosmic fog obscures my vision...');
    } catch (e) {
      setTellerResponse('MAYBE. The spirits are currently in a meeting. Try again after the next lunar cycle.');
    } finally {
      setIsTellerLoading(false);
    }
  };

  const filteredPosts = feedFilter === 'All' 
    ? posts 
    : posts.filter(p => user.following.includes(p.author) || p.author === user.username);

  const handlePost = () => {
    if (!postContent.trim()) return;
    onPost(postContent);
    setPostContent('');
  };

  const submitComment = (postId: string) => {
    if (!newComment.trim()) return;
    onComment(postId, newComment);
    setNewComment('');
  };

  return (
    <div className="flex flex-col h-full overflow-hidden">
      {/* Tab Switcher Header */}
      <div className="flex items-center justify-center pb-4 shrink-0 overflow-x-auto no-scrollbar">
        <div className="flex gap-2 p-1 bg-gray-100 dark:bg-slate-800 rounded-full shadow-inner">
          {(['Express', 'Teller', 'Quiz', 'MoodPet'] as MoodSubTab[]).map((tab) => (
            <button
              key={tab}
              onClick={() => setSubTab(tab)}
              className={`px-4 py-2 rounded-full font-black whitespace-nowrap transition-all text-[10px] md:text-sm ${subTab === tab ? 'bg-white dark:bg-slate-700 text-[#46178f] dark:text-white shadow-md' : 'text-gray-400 hover:text-slate-900 dark:hover:text-white opacity-70'}`}
            >
              {tab === 'MoodPet' ? 'PET 🐾' : tab.toUpperCase()}
            </button>
          ))}
        </div>
      </div>

      <div className="flex-1 fading-scrollbar overflow-y-auto pr-1 pb-10">
        <AnimatePresence mode="wait">
          {subTab === 'Express' && (
            <motion.div key="express" initial={{ opacity: 0, x: -10 }} animate={{ opacity: 1, x: 0 }} exit={{ opacity: 0, x: 10 }} className="space-y-6">
              <div className="flex justify-center md:justify-start">
                <div className="flex gap-2 p-1.5 bg-gray-200 dark:bg-slate-800 rounded-2xl w-fit">
                  <button onClick={() => setFeedFilter('All')} className={`px-5 py-2 rounded-xl text-[10px] font-black transition-all ${feedFilter === 'All' ? 'bg-white dark:bg-slate-700 shadow-sm text-slate-900 dark:text-white' : 'opacity-50 text-slate-600 dark:text-slate-400 hover:opacity-80'}`}>ALL DISTRICTS</button>
                  <button onClick={() => setFeedFilter('Following')} className={`px-5 py-2 rounded-xl text-[10px] font-black transition-all ${feedFilter === 'Following' ? 'bg-white dark:bg-slate-700 shadow-sm text-slate-900 dark:text-white' : 'opacity-50 text-slate-600 dark:text-slate-400 hover:opacity-80'}`}>MY CIRCLE</button>
                </div>
              </div>

              <div className={`p-6 md:p-8 rounded-[3rem] ${isDarkMode ? 'bg-slate-800 border-slate-700' : 'bg-white border-gray-100 shadow-xl'} border-4`}>
                <textarea value={postContent} onChange={(e) => setPostContent(e.target.value)} placeholder="What's your emotional broadcast for today?" className={`w-full p-5 rounded-2xl border-2 focus:border-[#46178f] outline-none transition-all text-sm md:text-lg font-medium ${isDarkMode ? 'bg-slate-700 border-slate-600 text-white' : 'bg-gray-50 border-gray-200 text-slate-900'}`} rows={3} />
                <div className="flex justify-end mt-4">
                  <button onClick={handlePost} className="kahoot-button-blue px-10 py-4 text-white rounded-2xl font-black text-sm flex items-center gap-3 transition-all hover:scale-105 active:scale-95"><Send size={20} /> TRANSMIT VIBES</button>
                </div>
              </div>

              <div className="space-y-6 pb-20">
                {filteredPosts.map(post => (
                    <motion.div layout key={post.id} className={`p-6 md:p-8 rounded-[3rem] ${isDarkMode ? 'bg-slate-800 border-slate-700 text-white' : 'bg-white border-gray-100 text-slate-900'} shadow-2xl border-4`}>
                      <div className="flex items-center justify-between mb-6">
                        <button onClick={() => onNavigateToProfile(post.author)} className="flex items-center gap-4 text-left hover:opacity-80 transition-opacity">
                          <div className="w-12 h-12 rounded-2xl bg-gradient-to-tr from-purple-500 to-indigo-600 flex items-center justify-center text-white font-black text-xl overflow-hidden shadow-lg border-b-4 border-black/10">
                            {post.author[0].toUpperCase()}
                          </div>
                          <div>
                            <h4 className="font-black text-sm md:text-lg tracking-tight">@{post.author}</h4>
                            {post.isRepost && <p className="text-[10px] font-bold opacity-50 flex items-center gap-1 text-green-500"><Repeat size={10}/> Echoed from @{post.originalAuthor}</p>}
                          </div>
                        </button>
                      </div>
                      <p className="text-base md:text-xl mb-8 leading-relaxed font-bold tracking-tight">{post.content}</p>

                      <div className="flex items-center gap-8 pt-6 border-t border-gray-100 dark:border-slate-700">
                        <button onClick={() => onHeart(post.id)} className="flex items-center gap-2 text-red-500 font-black text-xs hover:scale-110 transition-transform"><Heart size={20} fill={post.hearts > 0 ? "currentColor" : "none"} /> {post.hearts}</button>
                        <button onClick={() => setExpandedComments(expandedComments === post.id ? null : post.id)} className="flex items-center gap-2 text-blue-500 font-black text-xs hover:scale-110 transition-transform"><MessageCircle size={20} /> {post.comments.length}</button>
                        <button onClick={() => onRepost(post)} className="flex items-center gap-2 text-green-500 font-black text-xs hover:scale-110 transition-transform"><Repeat size={20} /> ECHO</button>
                      </div>
                    </motion.div>
                ))}
              </div>
            </motion.div>
          )}

          {subTab === 'MoodPet' && (
            <motion.div key="pet" initial={{ opacity: 0, scale: 0.98 }} animate={{ opacity: 1, scale: 1 }} exit={{ opacity: 0, scale: 0.98 }} className="h-full">
              <MoodPetSection user={user} isDarkMode={isDarkMode} onUpdate={onUpdatePet} onPost={onPost} />
            </motion.div>
          )}

          {subTab === 'Teller' && (
            <motion.div key="teller" initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -10 }} className="h-full flex flex-col items-center justify-center p-6 md:p-10 text-center bg-white dark:bg-slate-800 rounded-[3rem] shadow-2xl border-4 border-purple-500/20 relative overflow-hidden">
              <div className="absolute top-[-20%] left-[-20%] w-[60%] h-[60%] bg-purple-500/5 blur-[100px] rounded-full"></div>
              <motion.div animate={{ 
                rotate: isTellerLoading ? 360 : [0, 5, -5, 0],
                scale: [1, 1.05, 1]
              }} transition={{ repeat: Infinity, duration: isTellerLoading ? 1 : 4, ease: "easeInOut" }} className="mb-10 text-7xl md:text-9xl select-none">🔮</motion.div>
              <h3 className="text-2xl md:text-4xl font-black italic uppercase text-purple-600 dark:text-purple-400 mb-4 tracking-tighter">Mystic Teller</h3>
              <p className="text-sm opacity-60 mb-10 max-w-sm font-bold">Ask a question about your destiny, and the spirits shall answer.</p>
              <div className="w-full max-w-lg space-y-6">
                <input 
                  type="text" 
                  value={tellerQuestion} 
                  onChange={e => setTellerQuestion(e.target.value)} 
                  onKeyDown={e => e.key === 'Enter' && handleTeller()}
                  placeholder="Will I find inner peace today?" 
                  className={`w-full p-5 rounded-[2rem] border-4 outline-none font-black text-lg shadow-inner focus:border-purple-500 transition-all ${isDarkMode ? 'bg-slate-700 border-slate-600 text-white' : 'bg-gray-50 border-gray-100'}`} 
                />
                <button onClick={handleTeller} disabled={isTellerLoading} className="kahoot-button-purple w-full p-5 rounded-[2rem] text-white font-black uppercase text-lg md:text-2xl shadow-[0_12px_0_0_#321067] active:translate-y-2 active:shadow-none transition-all">CONSULT THE VOID</button>
              </div>

              <AnimatePresence>
                {tellerResponse && (
                  <motion.div initial={{ scale: 0.8, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} exit={{ scale: 0.8, opacity: 0 }} className="mt-10 md:mt-16 p-6 md:p-10 rounded-[3rem] bg-gradient-to-br from-purple-500/10 to-indigo-500/10 border-4 border-purple-500 max-w-md w-full shadow-2xl">
                    <p className="text-2xl md:text-4xl font-black italic text-purple-600 dark:text-purple-400 uppercase mb-4 tracking-tighter">{tellerResponse.split('.')[0]}</p>
                    <p className="text-base md:text-xl font-bold opacity-80 leading-snug italic">{tellerResponse.split('.').slice(1).join('.')}</p>
                  </motion.div>
                )}
              </AnimatePresence>
            </motion.div>
          )}

          {subTab === 'Quiz' && (
            <motion.div key="quiz" initial={{ opacity: 0, scale: 0.95 }} animate={{ opacity: 1, scale: 1 }} exit={{ opacity: 0, scale: 0.95 }} className="h-full">
              {!quizActive ? (
                <div className="h-full flex flex-col items-center justify-center text-center p-6 md:p-10 bg-white dark:bg-slate-800 rounded-[3rem] shadow-2xl border-4 border-green-500/20">
                  <div className="w-24 h-24 md:w-32 md:h-32 bg-green-500/10 rounded-[2rem] flex items-center justify-center mb-8 border-4 border-green-500/20">
                    <Brain className="text-green-500" size={64} />
                  </div>
                  <h3 className="text-3xl md:text-5xl font-black italic uppercase mb-4 tracking-tighter">Mind Palace Quiz</h3>
                  <p className="text-sm opacity-60 mb-12 max-w-sm font-bold">Showcase your Mooderia expertise. High scores grant massive Rewards!</p>
                  <button onClick={startQuiz} className="kahoot-button-green px-12 py-5 rounded-[2.5rem] text-white font-black text-2xl md:text-3xl uppercase shadow-[0_12px_0_0_#1c6409] active:translate-y-2 active:shadow-none transition-all">INITIATE TEST</button>
                </div>
              ) : quizFinished ? (
                <div className="h-full flex flex-col items-center justify-center text-center p-6 md:p-10 bg-white dark:bg-slate-800 rounded-[3rem] shadow-2xl border-4 border-yellow-500/30">
                  <div className="w-32 h-32 md:w-40 md:h-40 bg-yellow-400/10 rounded-full flex items-center justify-center mb-8 border-4 border-yellow-400 relative">
                     <Sparkles className="text-yellow-400" size={80} />
                     <div className="absolute inset-0 animate-ping opacity-20 bg-yellow-400 rounded-full"></div>
                  </div>
                  <h3 className="text-3xl md:text-5xl font-black italic uppercase mb-4 tracking-tighter">Evaluation Complete</h3>
                  <p className="text-2xl md:text-3xl font-black mb-10 text-yellow-600">Performance Rating: {quizScore}/5</p>
                  <div className="grid grid-cols-2 gap-4 w-full max-w-md mb-12">
                    <div className="bg-yellow-400 p-4 md:p-6 rounded-[2rem] shadow-lg shadow-yellow-400/20 text-center">
                       <p className="text-[10px] font-black uppercase text-white/70 mb-1">Mood Coins</p>
                       <p className="text-xl md:text-3xl font-black text-white">+{quizScore * 20}</p>
                    </div>
                    <div className="bg-purple-600 p-4 md:p-6 rounded-[2rem] shadow-lg shadow-purple-600/20 text-center">
                       <p className="text-[10px] font-black uppercase text-white/70 mb-1">Guardian EXP</p>
                       <p className="text-xl md:text-3xl font-black text-white">+{quizScore * 50}</p>
                    </div>
                  </div>
                  <button onClick={startQuiz} className="kahoot-button-blue px-10 py-4 rounded-[2rem] text-white font-black uppercase shadow-lg text-lg">TRY FOR PERFECTION</button>
                </div>
              ) : (
                <div className="max-w-2xl mx-auto py-8 px-4 md:py-12 md:px-6 bg-white dark:bg-slate-800 rounded-[3.5rem] shadow-2xl border-4 border-indigo-500/20">
                  <div className="flex justify-between items-center mb-12">
                    <div>
                      <span className="text-[10px] font-black uppercase opacity-40 tracking-widest block mb-1 text-indigo-500">Processing Node {quizStep + 1} of 5</span>
                      <h4 className="text-sm font-black uppercase italic tracking-tighter">Assessment in Progress</h4>
                    </div>
                    <div className="w-32 h-3 bg-gray-100 dark:bg-slate-700 rounded-full overflow-hidden border border-black/5">
                      <motion.div initial={{ width: 0 }} animate={{ width: `${(quizStep + 1) * 20}%` }} className="h-full bg-indigo-500" />
                    </div>
                  </div>
                  <h4 className="text-xl md:text-3xl font-black italic mb-12 leading-tight tracking-tight text-slate-800 dark:text-white mobile-center">{quizQuestions[quizStep].q}</h4>
                  <div className="grid grid-cols-1 gap-4">
                    {quizQuestions[quizStep].options.map((opt, i) => (
                      <motion.button 
                        key={i} 
                        whileHover={{ scale: 1.02 }}
                        whileTap={{ scale: 0.98 }}
                        onClick={() => handleQuizAnswer(i)} 
                        className={`p-6 md:p-8 rounded-[2rem] border-4 text-left font-black text-lg transition-all shadow-md active:translate-y-1 ${isDarkMode ? 'bg-slate-700 border-slate-600 hover:border-indigo-500' : 'bg-white border-gray-100 hover:border-indigo-500 hover:shadow-indigo-500/10'}`}
                      >
                        {opt}
                      </motion.button>
                    ))}
                  </div>
                </div>
              )}
            </motion.div>
          )}
        </AnimatePresence>
      </div>
    </div>
  );
};

