  { id: 'g2', name: 'Vibe Hunter', difficulty: 'Medium', rewardPerUnit: 5, expPerUnit: 8, drain: 15, color: 'bg-blue-500', icon: <Target size={24}/>, description: 'Catch the flying vibes!' },
  { id: 'g3', name: 'Math Blitz', difficulty: 'Hard', rewardPerUnit: 15, expPerUnit: 25, drain: 30, color: 'bg-purple-600', icon: <Calculator size={24}/>, description: 'Solve problems for massive rewards!' },
];

