  { id: 's1', label: 'Quick Nap', duration: 10 * 60 * 1000, fill: 20, exp: 50 },
  { id: 's2', label: 'Deep Slumber', duration: 60 * 60 * 1000, fill: 60, exp: 200 },
  { id: 's3', label: 'Cosmic Sleep', duration: 4 * 60 * 60 * 1000, fill: 100, exp: 1000 },
];

const EMOJI_OPTIONS = ['🐱', '🐶', '🦊', '🦁', '🐨', '🐼', '🦄', '🐲', '🐸', '🐹', '🐰', '🐯'];

const MoodPetSection: React.FC<MoodPetSectionProps> = ({ user, isDarkMode, onUpdate, onPost }) => {
  const [activeTab, setActiveTab] = useState<'Interaction' | 'Shop' | 'Games'>('Interaction');
  const [showSleepModal, setShowSleepModal] = useState(false);
