const GameInterface: React.FC<any> = ({ gameId, isDarkMode, onFinish }) => {
  const [score, setScore] = useState(0);
  const [timer, setTimer] = useState(gameId === 'g1' ? 10 : gameId === 'g2' ? 15 : 20);
  const [gameState, setGameState] = useState<'IDLE' | 'PLAYING' | 'FINISHED'>('IDLE');
  const gameInfo = GAMES.find(g => g.id === gameId);

  useEffect(() => {
    if (gameState === 'PLAYING' && timer > 0) {
      const t = setInterval(() => setTimer(prev => prev - 1), 1000);
      return () => clearInterval(t);
    } else if (gameState === 'PLAYING' && timer === 0) {
      setGameState('FINISHED');
    }
  }, [gameState, timer]);

  const handleFinish = () => {
    if (gameInfo) onFinish(score * gameInfo.rewardPerUnit, score * gameInfo.expPerUnit, gameInfo.drain);
  };

  return (
    <div className={`h-full flex flex-col p-6 rounded-[3rem] ${isDarkMode ? 'bg-slate-800' : 'bg-white shadow-2xl'} overflow-hidden relative`}>
      <div className="flex justify-between items-center mb-6 relative z-10">
        <h3 className="text-lg md:text-xl font-black uppercase italic tracking-tighter text-blue-600 dark:text-blue-400">{gameInfo?.name}</h3>
        <div className="flex gap-2">
          <div className="bg-yellow-400 text-white px-4 py-2 rounded-xl font-black text-[10px] md:text-xs flex items-center gap-2 shadow-lg tabular-nums"><Coins size={16}/> {score}</div>
          <div className="bg-blue-500 text-white px-4 py-2 rounded-xl font-black text-[10px] md:text-xs flex items-center gap-2 shadow-lg tabular-nums"><Clock size={16}/> {timer}s</div>
        </div>
      </div>

      <div className="flex-1 relative flex items-center justify-center bg-gray-50 dark:bg-slate-900/50 rounded-[2.5rem] border-4 md:border-8 border-dashed border-gray-200 dark:border-slate-800 overflow-hidden shadow-inner">
        {gameState === 'IDLE' && (
          <div className="text-center animate-fade-in px-4">
            <p className="text-sm md:text-lg font-black opacity-60 mb-6 uppercase tracking-widest">Citizen Performance Mode</p>
            <motion.button 
              whileHover={{ scale: 1.05 }}
              whileTap={{ scale: 0.95 }}
              onClick={() => { setGameState('PLAYING'); }} 
              className="px-12 py-5 bg-green-500 hover:bg-green-600 text-white rounded-[2rem] font-black text-xl md:text-3xl uppercase shadow-[0_8px_0_0_#1c6409] transition-all"
            >
              GO!
            </motion.button>
          </div>
        )}

        {gameState === 'PLAYING' && (
          <>
            {gameId === 'g1' && <CoinClickerGame onScore={() => setScore(s => s + 1)} />}
            {gameId === 'g2' && <VibeHunterGame onScore={() => setScore(s => s + 1)} />}
            {gameId === 'g3' && <MathBlitzGame onScore={() => setScore(s => s + 1)} />}
          </>
        )}

        {gameState === 'FINISHED' && (
          <div className="text-center p-6 md:p-8 bg-white dark:bg-slate-800 rounded-[2.5rem] shadow-2xl border-4 border-green-500 max-w-sm w-full mx-4">
            <h4 className="text-3xl md:text-5xl font-black text-green-500 uppercase italic mb-6 tracking-tighter">RESULT</h4>
            <div className="space-y-3 mb-8">
               <div className="flex justify-between items-center bg-yellow-400/10 p-4 rounded-xl border-2 border-yellow-400/20">
                  <span className="font-black text-[10px] uppercase opacity-60">Rewards</span>
                  <span className="text-xl font-black text-yellow-500">+{Math.floor(score * (gameInfo?.rewardPerUnit || 0))} COINS</span>
               </div>
               <div className="flex justify-between items-center bg-purple-500/10 p-4 rounded-xl border-2 border-purple-500/20">
                  <span className="font-black text-[10px] uppercase opacity-60">Growth</span>
                  <span className="text-xl font-black text-purple-500">+{Math.floor(score * (gameInfo?.expPerUnit || 0))} EXP</span>
               </div>
            </div>
            <button onClick={handleFinish} className="w-full py-4 bg-blue-600 hover:bg-blue-700 text-white rounded-xl font-black text-sm uppercase shadow-lg active:translate-y-1 transition-all">CLAIM & EXIT</button>
