const VibeHunterGame = ({ onScore }: { onScore: () => void }) => {
  const [pos, setPos] = useState({ x: 50, y: 50 });
  const [vibeEmoji, setVibeEmoji] = useState('✨');
  const [size, setSize] = useState(24);
  const [speed, setSpeed] = useState(400);
  const vibes = ['✨', '🔥', '⚡', '💎', '🌈', '🌀', '💎', '🍭'];

  const handleHit = () => {
    onScore();
    setPos({ x: Math.random() * 80 + 10, y: Math.random() * 80 + 10 });
    setVibeEmoji(vibes[Math.floor(Math.random() * vibes.length)]);
    setSize(Math.random() * 20 + 20); // Random size 20-40
    setSpeed(Math.random() * 300 + 200); // Random speed
  };

  return (
    <div className="w-full h-full relative">
      <motion.button 
        animate={{ x: `${pos.x}%`, y: `${pos.y}%` }} 
        transition={{ type: "spring", stiffness: speed, damping: 15 }} 
        onClick={handleHit} 
        className="absolute bg-blue-500 rounded-[1.5rem] border-b-[6px] border-blue-700 flex items-center justify-center text-white shadow-2xl"
        style={{ 
          left: 0, 
          top: 0, 
          transform: 'translate(-50%, -50%)',
          width: `${size * 2}px`,
          height: `${size * 2}px`,
          fontSize: `${size}px`
        }}
      >
        {vibeEmoji}
      </motion.button>
    </div>
  );
};

const MathBlitzGame = ({ onScore }: { onScore: () => void }) => {
  const [problem, setProblem] = useState({ q: '', a: 0 });
  const [input, setInput] = useState('');
  const [feedback, setFeedback] = useState<'none' | 'correct' | 'wrong'>('none');

  const generate = () => {
    const a = Math.floor(Math.random() * 30) + 5;
    const b = Math.floor(Math.random() * 30) + 5;
    const op = Math.random() > 0.5 ? '+' : '-';
    setProblem({ q: `${a} ${op} ${b}`, a: op === '+' ? a + b : a - b });
  };

  useEffect(generate, []);

  const check = (e: any) => {
    const val = e.target.value;
    setInput(val);
    if (parseInt(val) === problem.a) { 
      onScore(); 
      setFeedback('correct');
      setTimeout(() => {
        setFeedback('none');
        setInput(''); 
        generate(); 
      }, 300);
    }
  };

  return (
    <div className={`text-center w-full max-w-sm p-6 md:p-10 bg-white dark:bg-slate-800 rounded-[3rem] shadow-2xl border-4 transition-colors ${feedback === 'correct' ? 'border-green-500 bg-green-50 dark:bg-green-900/20' : 'border-purple-500'} animate-slide-up`}>
      <h5 className="text-[8px] font-black uppercase tracking-widest opacity-40 mb-6">NEURAL FAULT ISOLATION</h5>
      <motion.h5 
        animate={{ scale: [1, 1.05, 1] }}
        transition={{ duration: 1.5, repeat: Infinity }}
        className="text-5xl md:text-7xl font-black mb-8 md:mb-12 italic tracking-tighter text-purple-600 dark:text-purple-400 tabular-nums"
      >
        {problem.q} = ?
      </motion.h5>
      <input 
        autoFocus 
        type="number" 
        value={input} 
        onChange={check} 
        placeholder="..." 
        className="w-full p-6 md:p-8 rounded-[2rem] bg-gray-50 dark:bg-slate-900 border-4 border-purple-500 text-center text-4xl md:text-5xl font-black outline-none shadow-inner text-purple-600 dark:text-purple-400" 
      />
    </div>
  );
};

