  const myReposts = useMemo(() => allPosts.filter(p => p.author === user.username && p.isRepost), [allPosts, user.username]);

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>, type: 'profile' | 'banner') => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setEditForm(prev => ({
          ...prev,
          [type === 'profile' ? 'profilePic' : 'bannerPic']: reader.result as string
        }));
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSave = () => {
    if (onEditProfile) {
      onEditProfile(
        editForm.displayName,
        editForm.username,
        editForm.profilePic,
        editForm.title,
        editForm.bannerPic,
        editForm.profileColor,
        editForm.bio
      );
    }
    setIsEditing(false);
  };

  const accentColor = isEditing ? editForm.profileColor : (user.profileColor || '#46178f');

  return (
    <div className="flex flex-col h-full overflow-hidden">
      {/* Profile Header */}
      <div className={`relative p-6 rounded-[2.5rem] mb-4 shrink-0 ${isDarkMode ? 'bg-slate-800 text-white' : 'bg-white text-slate-900'} shadow-xl overflow-hidden`}>
        <div 
          className="h-32 md:h-40 w-full rounded-[1.5rem] absolute top-0 left-0 overflow-hidden" 
          style={{ backgroundColor: accentColor, backgroundImage: user.bannerPic ? `url(${user.bannerPic})` : 'none', backgroundSize: 'cover', backgroundPosition: 'center' }}
        >
          {user.bannerPic && <div className="absolute inset-0 bg-black/20"></div>}
        </div>

        <div className="relative pt-16 md:pt-20 flex flex-col md:flex-row items-end gap-4 px-2">
          <div className="w-24 h-24 md:w-32 md:h-32 rounded-[2rem] bg-white dark:bg-slate-700 p-1 shadow-2xl shrink-0 overflow-hidden relative group">
             {user.profilePic ? (
               <img src={user.profilePic} className="w-full h-full rounded-[1.8rem] object-cover" />
             ) : (
               <div className="w-full h-full rounded-[1.8rem] flex items-center justify-center text-white text-3xl font-black" style={{ backgroundColor: accentColor }}>
                 {user.displayName[0]}
               </div>
             )}
          </div>

          <div className="flex-1 min-w-0 pb-2 mobile-center md:text-left">
             <h2 className="text-2xl md:text-3xl font-black italic uppercase truncate leading-tight">{user.displayName}</h2>
             <p className="text-sm font-bold opacity-50 uppercase tracking-tighter">@{user.username}</p>
             {user.bio && <p className="text-xs font-bold opacity-70 mt-2 italic leading-snug line-clamp-2">"{user.bio}"</p>}
          </div>

          <div className="pb-2 w-full md:w-auto flex justify-center md:justify-end gap-2">
            {!isOwnProfile ? (
              <button 
                onClick={() => onFollow?.(user.username)} 
                className={`px-6 py-3 text-white rounded-xl font-black text-xs shadow-lg uppercase transition-all ${isFollowing ? 'bg-red-500' : 'bg-green-500'}`}
              >
                {isFollowing ? 'UNFOLLOW' : 'FOLLOW'}
              </button>
            ) : (
              <button 
                onClick={() => setIsEditing(true)} 
                className="px-6 py-3 text-white rounded-xl font-black text-xs uppercase shadow-xl transition-all active:scale-95" 
                style={{ backgroundColor: accentColor }}
              >
                EDIT ID
              </button>
            )}
          </div>
        </div>

        <div className="mt-6 flex justify-center md:justify-start gap-8 text-center border-t dark:border-slate-700 pt-4 px-2">
           <div><p className="text-lg font-black">{user.followers?.length || 0}</p><p className="text-[8px] md:text-[9px] uppercase font-black opacity-40 tracking-widest">Followers</p></div>
           <div><p className="text-lg font-black">{user.following?.length || 0}</p><p className="text-[8px] md:text-[9px] uppercase font-black opacity-40 tracking-widest">Following</p></div>
           <div><p className="text-lg font-black text-orange-500 italic">{user.moodStreak || 0}</p><p className="text-[8px] md:text-[9px] uppercase font-black opacity-40 tracking-widest">Streak</p></div>
        </div>
      </div>

      <div className="flex gap-2 mb-4 shrink-0">
         {(['Posts', 'Reposts', 'Stats'] as const).map(tab => (
           <button 
             key={tab} 
             onClick={() => setActiveTab(tab)} 
             className={`flex-1 p-3 rounded-2xl font-black text-xs uppercase transition-all ${activeTab === tab ? 'text-white' : 'bg-gray-200 dark:bg-slate-700 text-gray-400 opacity-60'}`} 
             style={{ backgroundColor: activeTab === tab ? accentColor : '' }}
           >
             {tab}
           </button>
         ))}
      </div>

      {/* Profile Content */}
      <div className="flex-1 fading-scrollbar overflow-y-auto pr-1 pb-10">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          {activeTab === 'Posts' && (
            myPosts.length > 0 ? myPosts.map(post => (
              <div key={post.id} className={`p-6 rounded-[2rem] ${isDarkMode ? 'bg-slate-800' : 'bg-white'} shadow-md border-b-4 border-gray-100 dark:border-slate-900`}>
                <p className="text-sm md:text-base font-medium mb-4">{post.content}</p>
                <div className="flex gap-4 opacity-40 text-[10px] font-black uppercase">
                  <span className="flex items-center gap-1"><Heart size={14} className="text-red-500" /> {post.hearts}</span>
                  <span className="flex items-center gap-1"><MessageCircle size={14} className="text-blue-500" /> {post.comments.length}</span>
                </div>
              </div>
            )) : <div className="col-span-2 text-center py-20 opacity-20 font-black uppercase italic">No expressions logged</div>
          )}
          {activeTab === 'Reposts' && (
             myReposts.length > 0 ? myReposts.map(post => (
              <div key={post.id} className={`p-6 rounded-[2rem] ${isDarkMode ? 'bg-slate-800' : 'bg-white'} shadow-md border-b-4 border-gray-100 dark:border-slate-900`}>
                <p className="text-[9px] font-black text-green-500 mb-2 italic">Reposted from @{post.originalAuthor}</p>
                <p className="text-sm font-medium mb-4">{post.content}</p>
              </div>
            )) : <div className="col-span-2 text-center py-20 opacity-20 font-black uppercase italic">No echoes found</div>
          )}
          {activeTab === 'Stats' && (
            <div className={`col-span-2 p-10 rounded-[3rem] ${isDarkMode ? 'bg-slate-800' : 'bg-white'} shadow-xl text-center space-y-6`}>
               <div className="flex justify-center gap-10">
                 <div><div className="w-16 h-16 rounded-2xl bg-blue-500/10 flex items-center justify-center text-blue-500 mx-auto mb-2"><Heart size={32}/></div><p className="text-2xl font-black">2.4k</p><p className="text-[10px] uppercase font-black opacity-40">Received</p></div>
                 <div><div className="w-16 h-16 rounded-2xl bg-orange-500/10 flex items-center justify-center text-orange-500 mx-auto mb-2"><Flame size={32}/></div><p className="text-2xl font-black">{user.moodStreak}</p><p className="text-[10px] uppercase font-black opacity-40">Persistence</p></div>
                 <div><div className="w-16 h-16 rounded-2xl bg-green-500/10 flex items-center justify-center text-green-500 mx-auto mb-2"><ShieldCheck size={32}/></div><p className="text-2xl font-black">Elite</p><p className="text-[10px] uppercase font-black opacity-40">Tier</p></div>
               </div>
               <p className="text-xs font-bold opacity-40 uppercase tracking-[0.4em]">Historical Citizen Data Verified</p>
            </div>
          )}
        </div>
      </div>

      {/* Edit Profile Modal */}
      <AnimatePresence>
        {isEditing && (
          <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 md:p-8 bg-black/80 backdrop-blur-md">
            <motion.div 
              initial={{ scale: 0.9, opacity: 0 }}
              animate={{ scale: 1, opacity: 1 }}
              exit={{ scale: 0.9, opacity: 0 }}
              className={`w-full max-w-2xl max-h-full fading-scrollbar overflow-y-auto rounded-[3rem] p-6 md:p-10 shadow-2xl relative ${isDarkMode ? 'bg-slate-800 text-white' : 'bg-white text-slate-900'} border-4 border-indigo-500/30`}
            >
              <button 
                onClick={() => setIsEditing(false)} 
                className="absolute top-6 right-6 p-2 rounded-full hover:bg-gray-100 dark:hover:bg-slate-700 transition-colors"
              >
                <X />
              </button>

              <h2 className="text-3xl font-black italic uppercase mb-8 text-center tracking-tighter">Configure ID</h2>

              <div className="space-y-6">
                {/* Visuals Selection */}
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div className="space-y-4">
                    <label className="text-[10px] font-black uppercase opacity-40 tracking-widest">Avatar Recognition</label>
                    <div className="flex items-center gap-4">
                      <div className="w-20 h-20 rounded-2xl bg-gray-100 dark:bg-slate-700 overflow-hidden relative border-4 border-white shadow-lg">
                        {editForm.profilePic ? <img src={editForm.profilePic} className="w-full h-full object-cover" /> : <Camera size={32} className="absolute inset-0 m-auto opacity-20" />}
                      </div>
                      <button 
                        onClick={() => profilePicInputRef.current?.click()}
                        className="px-4 py-2 bg-indigo-500 text-white rounded-xl text-[10px] font-black uppercase shadow-lg border-b-4 border-indigo-700 active:translate-y-1"
                      >
                        <Upload size={14} className="inline mr-2" /> Upload
                      </button>
                      <input type="file" ref={profilePicInputRef} className="hidden" accept="image/*" onChange={(e) => handleImageUpload(e, 'profile')} />
                    </div>
                  </div>

                  <div className="space-y-4">
                    <label className="text-[10px] font-black uppercase opacity-40 tracking-widest">Banner District</label>
                    <div className="w-full h-20 rounded-2xl bg-gray-100 dark:bg-slate-700 overflow-hidden relative shadow-lg border-2 border-white/10 group cursor-pointer" onClick={() => bannerPicInputRef.current?.click()}>
                      {editForm.bannerPic ? <img src={editForm.bannerPic} className="w-full h-full object-cover" /> : <div className="absolute inset-0 flex items-center justify-center opacity-20"><ImageIcon size={32} /></div>}
                      <div className="absolute inset-0 bg-black/20 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center text-white text-[10px] font-black">CLICK TO UPLOAD</div>
                      <input type="file" ref={bannerPicInputRef} className="hidden" accept="image/*" onChange={(e) => handleImageUpload(e, 'banner')} />
                    </div>
                  </div>
                </div>

                <div className="space-y-2">
                  <label className="text-[10px] font-black uppercase opacity-40 tracking-widest">Display Identifier</label>
                  <input 
                    type="text" 
                    value={editForm.displayName} 
                    onChange={e => setEditForm(prev => ({...prev, displayName: e.target.value}))} 
                    className={`w-full p-4 rounded-2xl border-2 font-bold outline-none focus:border-indigo-500 transition-all ${isDarkMode ? 'bg-slate-700 border-slate-600' : 'bg-gray-50 border-gray-100'}`}
                  />
                </div>

                <div className="space-y-2">
                  <label className="text-[10px] font-black uppercase opacity-40 tracking-widest">Unique Username</label>
                  <input 
                    type="text" 
                    value={editForm.username} 
                    onChange={e => setEditForm(prev => ({...prev, username: e.target.value}))} 
                    className={`w-full p-4 rounded-2xl border-2 font-bold outline-none focus:border-indigo-500 transition-all ${isDarkMode ? 'bg-slate-700 border-slate-600' : 'bg-gray-50 border-gray-100'}`}
                  />
                </div>

                <div className="space-y-2">
                  <label className="text-[10px] font-black uppercase opacity-40 tracking-widest">Biometric Insight (Bio)</label>
                  <textarea 
                    value={editForm.bio} 
                    onChange={e => setEditForm(prev => ({...prev, bio: e.target.value}))} 
                    rows={2}
                    className={`w-full p-4 rounded-2xl border-2 font-bold outline-none focus:border-indigo-500 transition-all resize-none ${isDarkMode ? 'bg-slate-700 border-slate-600' : 'bg-gray-50 border-gray-100'}`}
                    placeholder="Tell the city about your vibes..."
                  />
                </div>

                <div className="space-y-2">
                  <label className="text-[10px] font-black uppercase opacity-40 tracking-widest">District Theme Color</label>
                  <div className="flex flex-wrap gap-2">
                    {['#46178f', '#1368ce', '#26890c', '#e21b3c', '#ffa602', '#ec4899', '#06b6d4', '#8b5cf6'].map(color => (
                      <button 
                        key={color} 
                        onClick={() => setEditForm(prev => ({...prev, profileColor: color}))}
                        className={`w-10 h-10 rounded-xl transition-all ${editForm.profileColor === color ? 'ring-4 ring-indigo-500 ring-offset-4 dark:ring-offset-slate-800 scale-110' : 'scale-100'}`}
                        style={{ backgroundColor: color }}
                      />
                    ))}
                  </div>
                </div>

                <div className="pt-6">
                  <button 
                    onClick={handleSave} 
                    className="w-full py-5 bg-green-500 hover:bg-green-600 text-white rounded-2xl font-black text-xl uppercase shadow-[0_10px_0_0_#1c6409] active:translate-y-2 active:shadow-none transition-all flex items-center justify-center gap-3"
                  >
                    <Check size={28} /> AUTHORIZE CHANGES
                  </button>
                </div>
              </div>
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </div>
  );
};

