import React, { useState, useEffect, useMemo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { User, Mood, Section, Post, Comment, Message, Notification } from './types';
import Sidebar from './components/Sidebar';
import MoodCheckIn from './components/MoodCheckIn';
import HomeSection from './sections/HomeSection';
import MoodSection from './sections/MoodSection';
import ZodiacSection from './sections/ZodiacSection';
import CityHallSection from './sections/CityHallSection';
import ProfileSection from './sections/ProfileSection';
import SettingsSection from './sections/SettingsSection';
import NotificationsSection from './sections/NotificationsSection';
import AuthScreen from './sections/AuthScreen';
import LoadingScreen from './components/LoadingScreen';
import { getExpNeeded, MOOD_SCORES, getTier } from './constants';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [activeSection, setActiveSection] = useState<Section>('Home');
  const [viewingUsername, setViewingUsername] = useState<string | null>(null);
  const [isMoodModalOpen, setIsMoodModalOpen] = useState(false);
  const [isDarkMode, setIsDarkMode] = useState(false);
  const [isAppStarting, setIsAppStarting] = useState(true);

  const [allPosts, setAllPosts] = useState<Post[]>([]);
  const [allMessages, setAllMessages] = useState<Message[]>([]);
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);

  useEffect(() => {
    const savedUser = localStorage.getItem('mooderia_user');
    const savedPosts = localStorage.getItem('mooderia_posts') || '[]';
    const savedMessages = localStorage.getItem('mooderia_messages') || '[]';
    const savedNotifications = localStorage.getItem('mooderia_notifications') || '[]';
    const savedTheme = localStorage.getItem('mooderia_theme');

    if (savedUser) {
      let user: User = JSON.parse(savedUser);
      const now = Date.now();

      // Pet Stat Decay
      if (user.petLastUpdate) {
        const secondsPassed = Math.floor((now - user.petLastUpdate) / 1000);
        const hungerDrain = Math.floor(secondsPassed / 3600);
        const thirstDrain = Math.floor(secondsPassed / 1800);
        const restDrain = Math.floor(secondsPassed / 7200);

        user.petHunger = Math.max(0, user.petHunger - hungerDrain);
        user.petThirst = Math.max(0, user.petThirst - thirstDrain);
        user.petRest = Math.max(0, user.petRest - restDrain);
      }
      user.petLastUpdate = now;

      // Streak Logic
      const todayStr = new Date().toDateString();
      if (user.lastMoodDate && user.lastMoodDate !== todayStr) {
        const lastDate = new Date(user.lastMoodDate);
        const diffDays = Math.floor((new Date(todayStr).getTime() - lastDate.getTime()) / (1000 * 3600 * 24));

        if (diffDays > 1) {
          user.moodStreak = 0; // Skipped a day
        }
        setIsMoodModalOpen(true);
      } else if (!user.lastMoodDate) {
        setIsMoodModalOpen(true);
      }

      setCurrentUser(user);
    }

    setAllPosts(JSON.parse(savedPosts));
    setAllMessages(JSON.parse(savedMessages));
    setNotifications(JSON.parse(savedNotifications));
    if (savedTheme === 'dark') setIsDarkMode(true);

    setIsLoaded(true);

    const timer = setTimeout(() => {
      setIsAppStarting(false);
    }, 2500);
    return () => clearTimeout(timer);
  }, []);

  useEffect(() => {
    if (!isLoaded) return;

    if (currentUser) {
      localStorage.setItem('mooderia_user', JSON.stringify(currentUser));
      const allUsers: User[] = JSON.parse(localStorage.getItem('mooderia_all_users') || '[]');
      const idx = allUsers.findIndex(u => u.username === currentUser.username);
      if (idx > -1) allUsers[idx] = currentUser;
      else allUsers.push(currentUser);
      localStorage.setItem('mooderia_all_users', JSON.stringify(allUsers));
    }

    localStorage.setItem('mooderia_posts', JSON.stringify(allPosts));
    localStorage.setItem('mooderia_messages', JSON.stringify(allMessages));
    localStorage.setItem('mooderia_notifications', JSON.stringify(notifications));
    localStorage.setItem('mooderia_theme', isDarkMode ? 'dark' : 'light');
  }, [currentUser, allPosts, allMessages, notifications, isDarkMode, isLoaded]);

  const unreadMessages = useMemo(() => 
    allMessages.filter(m => m.recipient === currentUser?.username && !m.read).length, 
    [allMessages, currentUser?.username]
  );

  const unreadNotifs = useMemo(() => 
    notifications.filter(n => !n.read).length, 
    [notifications]
  );

  const visiblePosts = useMemo(() => {
    if (!currentUser) return allPosts;
    return allPosts.filter(p => !currentUser.blockedUsers.includes(p.author));
  }, [allPosts, currentUser?.blockedUsers]);

  const profileToView = useMemo(() => {
    if (!isLoaded) return null;
    const target = viewingUsername || currentUser?.username;
    if (!target) return currentUser;

    const allUsers: User[] = JSON.parse(localStorage.getItem('mooderia_all_users') || '[]');
    return allUsers.find(u => u.username === target) || currentUser;
  }, [viewingUsername, currentUser, isLoaded]);

  const navigateToProfile = (username: string) => {
    setViewingUsername(username);
    setActiveSection('Profile');
  };

  const addPost = (content: string) => {
    if (!currentUser) return;
    const newPost: Post = {
      id: Math.random().toString(36).substr(2, 9),
      author: currentUser.username,
      content,
      hearts: 0,
      comments: [],
      timestamp: Date.now()
    };
    setAllPosts(prev => [newPost, ...prev]);
  };

  const toggleHeart = (postId: string) => {
    const post = allPosts.find(p => p.id === postId);
    if (!post || !currentUser) return;

    const isOwnPost = post.author === currentUser.username;

    setAllPosts(prev => prev.map(p => {
      if (p.id === postId) return { ...p, hearts: p.hearts + 1 };
      return p;
    }));

    // Logic to update author's likesReceived and potentially trigger tier notification
    const allUsers: User[] = JSON.parse(localStorage.getItem('mooderia_all_users') || '[]');
    const authorIdx = allUsers.findIndex(u => u.username === post.author);

    if (authorIdx > -1) {
      const author = allUsers[authorIdx];
      const oldTier = getTier(author.likesReceived).name;
      author.likesReceived += 1;
      const newTier = getTier(author.likesReceived).name;

      if (oldTier !== newTier) {
        const newNotif: Notification = {
          id: Math.random().toString(36).substr(2, 9),
          type: 'tier',
          fromUser: 'City Council',
          timestamp: Date.now(),
          read: false,
          postContentSnippet: `Congratulations! Your tier has been upgraded to ${newTier}!`
        };

        if (post.author === currentUser.username) {
          setCurrentUser({ ...currentUser, likesReceived: author.likesReceived });
          setNotifications(prev => [newNotif, ...prev]);
        }
      }

      if (post.author === currentUser.username) {
         setCurrentUser(prev => prev ? { ...prev, likesReceived: author.likesReceived } : null);
      } else {
         localStorage.setItem('mooderia_all_users', JSON.stringify(allUsers));
      }
    }
  };

  const addComment = (postId: string, text: string) => {
    if (!currentUser) return;
    const newComment: Comment = {
      id: Math.random().toString(36).substr(2, 9),
      author: currentUser.username,
      text,
      replies: []
    };
    setAllPosts(prev => prev.map(p => {
      if (p.id === postId) return { ...p, comments: [...p.comments, newComment] };
      return p;
    }));
  };

  const handleFollow = (targetUsername: string) => {
    if (!currentUser || targetUsername === currentUser.username) return;
    const allUsers: User[] = JSON.parse(localStorage.getItem('mooderia_all_users') || '[]');
    const targetIdx = allUsers.findIndex(u => u.username === targetUsername);
    if (targetIdx === -1) return;

    const targetUser = allUsers[targetIdx];
    const isFollowing = currentUser.following.includes(targetUsername);

    let updatedCurrentUser: User;
    let updatedTargetUser: User;

    if (isFollowing) {
      updatedCurrentUser = { ...currentUser, following: currentUser.following.filter(u => u !== targetUsername) };
      updatedTargetUser = { ...targetUser, followers: (targetUser.followers || []).filter(u => u !== currentUser.username) };
    } else {
      updatedCurrentUser = { ...currentUser, following: [...currentUser.following, targetUsername] };
      updatedTargetUser = { ...targetUser, followers: [...(targetUser.followers || []), currentUser.username] };
    }

    setCurrentUser(updatedCurrentUser);
    allUsers[targetIdx] = updatedTargetUser;
    localStorage.setItem('mooderia_all_users', JSON.stringify(allUsers));
  };

  const handleBlockUser = (username: string) => {
    if (!currentUser) return;
    const updated = {
      ...currentUser,
      blockedUsers: [...new Set([...currentUser.blockedUsers, username])],
      following: currentUser.following.filter(u => u !== username)
    };
    setCurrentUser(updated);
    setActiveSection('Home');
  };

  const handleUnblockUser = (username: string) => {
    if (!currentUser) return;
    setCurrentUser({
      ...currentUser,
      blockedUsers: currentUser.blockedUsers.filter(u => u !== username)
    });
  };

  const handleLogout = () => {
    setCurrentUser(null);
    localStorage.removeItem('mooderia_user');
    setActiveSection('Home');
    setViewingUsername(null);
  };

  const submitMood = (mood: Mood) => {
    if (!currentUser) return;
    const today = new Date().toDateString();
    const score = MOOD_SCORES[mood || 'Normal'] || 50;

    const updatedUser: User = {
      ...currentUser,
      moodStreak: (currentUser.moodStreak || 0) + 1,
      lastMoodDate: today,
      moodHistory: [...(currentUser.moodHistory || []), { date: today, mood, score }]
    };
    setCurrentUser(updatedUser);
    setIsMoodModalOpen(false);
  };

  const sendMessage = (recipient: string, text: string) => {
    if (!currentUser) return;
    const newMessage: Message = {
      id: Math.random().toString(36).substr(2, 9),
      sender: currentUser.username,
      recipient,
      text,
      timestamp: Date.now(),
      read: false
    };
    setAllMessages(prev => [...prev, newMessage]);
  };

  const updatePetStats = (hunger: number, thirst: number, rest: number, coins: number, exp: number = 0, sleepUntil: number | null = null, newEmoji?: string, markChosen?: boolean) => {
    if (!currentUser) return;
    let newLevel = currentUser.petLevel;
    let newExp = currentUser.petExp + exp;

    while (newExp >= getExpNeeded(newLevel)) {
      newExp -= getExpNeeded(newLevel);
      newLevel += 1;
    }

    setCurrentUser({
      ...currentUser,
      petEmoji: newEmoji || currentUser.petEmoji,
      petHasBeenChosen: markChosen !== undefined ? markChosen : currentUser.petHasBeenChosen,
      petHunger: Math.min(100, Math.max(0, currentUser.petHunger + hunger)),
      petThirst: Math.min(100, Math.max(0, currentUser.petThirst + thirst)),
      petRest: Math.min(100, Math.max(0, currentUser.petRest + rest)),
      moodCoins: currentUser.moodCoins + coins,
      petLevel: newLevel,
      petExp: newExp,
      petSleepUntil: sleepUntil !== undefined ? sleepUntil : currentUser.petSleepUntil,
      petLastUpdate: Date.now()
    });
  };

  const handleEditProfile = (displayName: string, username: string, profilePic?: string, title?: string, bannerPic?: string, profileColor?: string, bio?: string) => {
    if (!currentUser) return;

    const allUsers: User[] = JSON.parse(localStorage.getItem('mooderia_all_users') || '[]');
    const userIdx = allUsers.findIndex(u => u.username === currentUser.username);

    // Creators only for Travis
    let finalTitle = title || currentUser.title;
    if (finalTitle === 'Creator' && currentUser.email !== 'travismiguel014@gmail.com') {
      finalTitle = 'Citizen';
    }

    const updatedUser = {
      ...currentUser,
      displayName,
      username,
      profilePic: profilePic || currentUser.profilePic,
      title: finalTitle,
      bannerPic: bannerPic || currentUser.bannerPic,
      profileColor: profileColor || currentUser.profileColor,
      bio: bio || currentUser.bio
    };

    // Update all posts/messages if username changed
    if (username !== currentUser.username) {
      setAllPosts(prev => prev.map(p => ({
        ...p,
        author: p.author === currentUser.username ? username : p.author,
        originalAuthor: p.originalAuthor === currentUser.username ? username : p.originalAuthor
      })));
      setAllMessages(prev => prev.map(m => ({
        ...m,
        sender: m.sender === currentUser.username ? username : m.sender,
        recipient: m.recipient === currentUser.username ? username : m.recipient
      })));
    }

    if (userIdx > -1) {
      allUsers[userIdx] = updatedUser;
      localStorage.setItem('mooderia_all_users', JSON.stringify(allUsers));
    }

    setCurrentUser(updatedUser);
  };

  if (isAppStarting) return <LoadingScreen />;

  if (!currentUser) {
    return <AuthScreen onLogin={(user) => { 
      setCurrentUser(user); 
    }} />;
  }

  return (
    <div className={`h-screen max-h-screen overflow-hidden flex flex-col md:flex-row ${isDarkMode ? 'bg-slate-900 text-white' : 'bg-gray-50 text-slate-900'} transition-colors duration-300`}>
      <AnimatePresence>
        {isMoodModalOpen && <MoodCheckIn onSubmit={submitMood} isDarkMode={isDarkMode} />}
      </AnimatePresence>

      <Sidebar 
        activeSection={activeSection} 
        onNavigate={(s) => { setActiveSection(s); if(s === 'Profile') setViewingUsername(currentUser.username); }} 
        isDarkMode={isDarkMode}
        user={currentUser}
        unreadMessages={unreadMessages}
        unreadNotifications={unreadNotifs}
      />

      <main className="flex-1 flex flex-col relative pt-16 pb-20 md:pt-0 md:pb-0 h-full overflow-hidden">
        <div className="flex-1 overflow-hidden p-4 md:p-8">
          <motion.div
            key={activeSection + (activeSection === 'Profile' ? viewingUsername : '')}
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            className="h-full max-w-5xl mx-auto flex flex-col"
          >
            {activeSection === 'Home' && <div className="h-full fading-scrollbar overflow-y-auto pr-2"><HomeSection user={currentUser} posts={visiblePosts} isDarkMode={isDarkMode} /></div>}
            {activeSection === 'Mood' && (
              <MoodSection 
                user={currentUser} posts={visiblePosts} onPost={addPost} onHeart={toggleHeart} 
                onComment={addComment} onRepost={(p) => setAllPosts([ { ...p, id: Math.random().toString(36).substr(2, 9), author: currentUser.username, isRepost: true, originalAuthor: p.author, timestamp: Date.now() }, ...allPosts])} 
                onFollow={handleFollow} onBlock={handleBlockUser} isDarkMode={isDarkMode} 
                onNavigateToProfile={navigateToProfile}
                onUpdatePet={updatePetStats}
              />
            )}
            {activeSection === 'Zodiac' && <div className="h-full fading-scrollbar overflow-y-auto pr-2"><ZodiacSection isDarkMode={isDarkMode} /></div>}
            {activeSection === 'CityHall' && (
              <CityHallSection 
                isDarkMode={isDarkMode} currentUser={currentUser} messages={allMessages} 
                onSendMessage={sendMessage} onReadMessages={(u) => setAllMessages(allMessages.map(m => (m.recipient === currentUser.username && m.sender === u) ? {...m, read: true} : m))} 
                onNavigateToProfile={navigateToProfile} 
              />
            )}
            {activeSection === 'Notifications' && <div className="h-full fading-scrollbar overflow-y-auto pr-2"><NotificationsSection notifications={notifications} isDarkMode={isDarkMode} onMarkRead={() => setNotifications(notifications.map(n => ({...n, read: true})))} /></div>}
            {activeSection === 'Profile' && profileToView && (
              <ProfileSection 
                user={profileToView} allPosts={allPosts} isDarkMode={isDarkMode} 
                onEditProfile={handleEditProfile} 
                onBlock={handleBlockUser} onFollow={handleFollow} currentUser={currentUser}
                onShareToExpress={(msg) => addPost(msg)}
              />
            )}
            {activeSection === 'Settings' && <div className="h-full fading-scrollbar overflow-y-auto pr-2"><SettingsSection isDarkMode={isDarkMode} onToggleDarkMode={() => setIsDarkMode(!isDarkMode)} onLogout={handleLogout} user={currentUser} onUnblock={handleUnblockUser} /></div>}
          </motion.div>
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useMemo } from 'react';
import { User, Post } from '../types';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';
import { Flame, Award, TrendingUp, ShieldCheck, Heart, Sparkles } from 'lucide-react';
import { STREAK_BADGES, DAILY_WISDOM } from '../constants';

interface HomeSectionProps {
  user: User;
  posts: Post[];
  isDarkMode: boolean;
}

const HomeSection: React.FC<HomeSectionProps> = ({ user, posts, isDarkMode }) => {
  const currentMood = user.moodHistory?.[user.moodHistory.length - 1]?.mood || 'Not set';
  const earnedBadges = STREAK_BADGES.filter(b => user.moodStreak >= b.threshold);

  const todayWisdom = useMemo(() => {
    const day = new Date().getDate();
    return DAILY_WISDOM[day % DAILY_WISDOM.length];
  }, []);

  // Map mood scores to chart
  const chartData = useMemo(() => {
    if (!user.moodHistory || user.moodHistory.length === 0) {
      return [{ name: 'New', score: 0 }];
    }
    return user.moodHistory.slice(-7).map((entry, idx) => ({
      name: `T${idx + 1}`,
      score: entry.score
    }));
  }, [user.moodHistory]);

  const happiness = useMemo(() => {
    if (!user.moodHistory || user.moodHistory.length === 0) return 0;
    const recent = user.moodHistory.slice(-5);
    const avg = recent.reduce((acc, curr) => acc + curr.score, 0) / recent.length;
    return Math.round(avg);
  }, [user.moodHistory]);

  const harmonyScore = user.moodHistory?.[user.moodHistory.length - 1]?.score || 0;

  return (
    <div className="space-y-8">
      <div className="flex flex-col lg:flex-row justify-between items-start lg:items-center gap-6">
        <div className="text-center md:text-left w-full md:w-auto">
          <h2 className={`text-3xl md:text-4xl font-black italic tracking-tighter uppercase ${isDarkMode ? 'text-white' : 'text-slate-900'}`}>
            Welcome, {user.displayName}!
          </h2>
          <p className={`opacity-40 font-black uppercase tracking-[0.2em] text-[10px] md:text-xs mt-1 ${isDarkMode ? 'text-white' : 'text-slate-900'}`}>
            Mooderia Citizen Status: {user.title || 'Citizen'}
          </p>
        </div>

        <div className="flex flex-wrap gap-3 w-full md:w-auto justify-center md:justify-end">
          <div className={`flex items-center gap-2 px-5 py-3 rounded-2xl bg-[#ffa602] text-white font-black shadow-lg streak-glow text-xs md:text-sm`}>
            <Flame className="animate-pulse" size={18} />
            <span className="uppercase">{user.moodStreak || 0} Day Streak</span>
          </div>
          <div className={`flex items-center gap-2 px-5 py-3 rounded-2xl border-2 font-black text-xs md:text-sm ${isDarkMode ? 'border-purple-400 text-purple-400' : 'border-[#46178f] text-[#46178f]'}`}>
            <span className="opacity-50 uppercase mr-1">Mood:</span>
            <span className="uppercase italic">{currentMood}</span>
          </div>
        </div>
      </div>

      {/* Rewards Row */}
      {earnedBadges.length > 0 && (
        <div className={`p-4 md:p-6 rounded-[2rem] ${isDarkMode ? 'bg-slate-800' : 'bg-white'} shadow-lg border-2 border-green-400/30 overflow-x-auto no-scrollbar`}>
           <div className="flex items-center gap-4">
              <ShieldCheck className="text-green-500 shrink-0" size={28} />
              <div className="flex gap-4 min-w-max">
                 {earnedBadges.map(badge => (
                   <div key={badge.id} className="flex flex-col items-center justify-center bg-green-500/10 p-3 rounded-2xl border border-green-500/20 w-20">
                      <span className="text-2xl mb-1">{badge.icon}</span>
                      <span className={`text-[8px] font-black uppercase tracking-tighter text-center leading-none ${isDarkMode ? 'text-white' : 'text-slate-900'}`}>{badge.name}</span>
                   </div>
                 ))}
              </div>
           </div>
        </div>
      )}

      <div className="grid grid-cols-2 md:grid-cols-3 gap-4 md:gap-6">
        <div className={`p-5 md:p-6 rounded-[2rem] ${isDarkMode ? 'bg-slate-800' : 'bg-white'} shadow-xl border-b-4 border-blue-500/20 group`}>
          <div className="flex justify-between items-start mb-2">
            <p className="text-[10px] font-black opacity-30 uppercase tracking-widest">Followers</p>
            <Award className="text-yellow-500 opacity-20" size={16} />
          </div>
          <p className="text-3xl md:text-4xl font-black text-[#1368ce] italic">{user.followers.length}</p>
        </div>
        <div className={`p-5 md:p-6 rounded-[2rem] ${isDarkMode ? 'bg-slate-800' : 'bg-white'} shadow-xl border-b-4 border-green-500/20 group`}>
          <div className="flex justify-between items-start mb-2">
            <p className="text-[10px] font-black opacity-30 uppercase tracking-widest">Following</p>
            <TrendingUp className="text-blue-500 opacity-20" size={16} />
          </div>
          <p className="text-3xl md:text-4xl font-black text-[#26890c] italic">{user.following.length}</p>
        </div>
        <div className={`col-span-2 md:col-span-1 p-5 md:p-6 rounded-[2rem] ${isDarkMode ? 'bg-slate-800' : 'bg-white'} shadow-xl border-b-4 border-red-500/20 group`}>
           <div className="flex justify-between items-start mb-2">
            <p className="text-[10px] font-black opacity-30 uppercase tracking-widest">Happiness</p>
            <Sparkles className="text-red-500 opacity-20" size={16} />
          </div>
          <p className="text-3xl md:text-4xl font-black text-[#e21b3c] italic">{happiness}%</p>
        </div>
      </div>

      <div className={`p-6 md:p-8 rounded-[2.5rem] ${isDarkMode ? 'bg-slate-800 text-white' : 'bg-white text-slate-900'} shadow-2xl overflow-hidden`}>
        <div className="flex justify-between items-center mb-6">
          <h3 className="text-lg md:text-xl font-black uppercase italic flex items-center gap-2">
            <TrendingUp className="text-[#46178f]" />
            Emotional Harmony
          </h3>
          <div className="bg-purple-100 dark:bg-purple-900/40 px-4 py-2 rounded-full">
            <span className="text-purple-600 dark:text-purple-300 font-black text-xs uppercase tracking-widest">Score: {harmonyScore}</span>
          </div>
        </div>
        <div className="h-48 md:h-64 w-full">
          <ResponsiveContainer width="100%" height="100%">
            <AreaChart data={chartData}>
              <CartesianGrid strokeDasharray="3 3" vertical={false} stroke={isDarkMode ? "#334155" : "#e2e8f0"} />
              <XAxis dataKey="name" stroke={isDarkMode ? "#94a3b8" : "#64748b"} fontSize={10} axisLine={false} tickLine={false} />
              <YAxis domain={[0, 100]} hide />
              <Tooltip 
                contentStyle={{ 
                  backgroundColor: isDarkMode ? '#1e293b' : '#fff', 
                  borderRadius: '16px',
                  border: 'none',
                  boxShadow: '0 10px 15px -3px rgba(0, 0, 0, 0.1)',
                  fontWeight: '900',
                  fontSize: '12px'
                }} 
              />
              <Area type="monotone" dataKey="score" stroke="#46178f" fill="#46178f" fillOpacity={0.15} strokeWidth={4} />
            </AreaChart>
          </ResponsiveContainer>
        </div>
      </div>

      <div className="grid grid-cols-1 gap-4">
