import { User, Post } from '../types';
// Fixed error: Added missing TrendingUp icon to imports
import { Edit, Heart, MessageCircle, Flame, ShieldCheck, UserPlus, UserMinus, MoreVertical, ShieldAlert, Camera, Palette, Image as ImageIcon, Repeat, X, Check, Upload, Share2, Sparkles, Trophy, TrendingUp } from 'lucide-react';
import { getTier, JOB_TITLES } from '../constants';

interface ProfileSectionProps {
  user: User;
  allPosts: Post[];
  isDarkMode: boolean;
  currentUser: User;
  onEditProfile?: (displayName: string, username: string, profilePic?: string, title?: string, bannerPic?: string, profileColor?: string, bio?: string) => void;
  onBlock?: (username: string) => void;
  onFollow?: (username: string) => void;
  onShareToExpress?: (msg: string) => void;
}

const ProfileSection: React.FC<ProfileSectionProps> = ({ user, allPosts, isDarkMode, currentUser, onEditProfile, onBlock, onFollow, onShareToExpress }) => {
  const [isEditing, setIsEditing] = useState(false);
  const [editForm, setEditForm] = useState({
    displayName: user.displayName,
    username: user.username,
    profilePic: user.profilePic || '',
    bannerPic: user.bannerPic || '',
    title: user.title || 'Citizen',
    profileColor: user.profileColor || '#46178f',
    bio: user.bio || ''
  });

  const [activeTab, setActiveTab] = useState<'Posts' | 'Reposts' | 'Stats'>('Posts');
  const profilePicInputRef = useRef<HTMLInputElement>(null);
  const bannerPicInputRef = useRef<HTMLInputElement>(null);

  const isOwnProfile = currentUser.username === user.username;
  const isFollowing = currentUser.following.includes(user.username);
  const myPosts = useMemo(() => allPosts.filter(p => p.author === user.username && !p.isRepost), [allPosts, user.username]);
  const myReposts = useMemo(() => allPosts.filter(p => p.author === user.username && p.isRepost), [allPosts, user.username]);

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>, type: 'profile' | 'banner') => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setEditForm(prev => ({
          ...prev,
          [type === 'profile' ? 'profilePic' : 'bannerPic']: reader.result as string
        }));
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSave = () => {
    if (onEditProfile) {
      onEditProfile(
        editForm.displayName,
        editForm.username,
        editForm.profilePic,
        editForm.title,
        editForm.bannerPic,
        editForm.profileColor,
        editForm.bio
      );
    }
    setIsEditing(false);
  };

  const currentTier = getTier(user.likesReceived || 0);
  const harmonyScore = user.moodHistory?.[user.moodHistory.length - 1]?.score || 0;
  const accentColor = isEditing ? editForm.profileColor : (user.profileColor || '#46178f');

  const shareAchievement = (type: 'tier' | 'exp') => {
    let msg = "";
    if (type === 'tier') {
      msg = `Citizen Milestone! 🏆 My status in Mooderia has reached the ${currentTier.name} tier! #MoodMilestone #CitzenStatus`;
    } else {
      msg = `Mood Guardian update! 🐾 My pet ${user.petEmoji} is now Level ${user.petLevel}! #MoodPet #Guardian`;
    }
    onShareToExpress?.(msg);
    alert("Achievement shared to the Express feed!");
  };

  return (
    <div className="flex flex-col h-full overflow-hidden">
      {/* Profile Header */}
      <div className={`relative p-6 rounded-[2.5rem] mb-4 shrink-0 ${isDarkMode ? 'bg-slate-800 text-white' : 'bg-white text-slate-900'} shadow-xl overflow-hidden`}>
        <div 
          className="h-32 md:h-40 w-full rounded-[1.5rem] absolute top-0 left-0 overflow-hidden" 
          style={{ backgroundColor: accentColor, backgroundImage: user.bannerPic ? `url(${user.bannerPic})` : 'none', backgroundSize: 'cover', backgroundPosition: 'center' }}
        >
          {user.bannerPic && <div className="absolute inset-0 bg-black/20"></div>}
        </div>

        <div className="relative pt-16 md:pt-20 flex flex-col md:flex-row items-end gap-4 px-2">
          <div className="w-24 h-24 md:w-32 md:h-32 rounded-[2rem] bg-white dark:bg-slate-700 p-1 shadow-2xl shrink-0 overflow-hidden relative group">
             {user.profilePic ? (
               <img src={user.profilePic} className="w-full h-full rounded-[1.8rem] object-cover" />
             ) : (
               <div className="w-full h-full rounded-[1.8rem] flex items-center justify-center text-white text-3xl font-black" style={{ backgroundColor: accentColor }}>
                 {user.displayName[0]}
               </div>
             )}
          </div>

          <div className="flex-1 min-w-0 pb-2 mobile-center md:text-left">
             <div className="flex items-center gap-2 mb-1">
               <h2 className="text-2xl md:text-3xl font-black italic uppercase truncate leading-tight">{user.displayName}</h2>
               {user.email === 'travismiguel014@gmail.com' && <div className="p-1.5 bg-yellow-400 text-white rounded-lg shadow-sm" title="Original Creator"><Sparkles size={14} fill="currentColor" /></div>}
             </div>
             <p className="text-sm font-bold opacity-50 uppercase tracking-tighter">@{user.username}</p>
             <p className="text-[10px] font-black uppercase tracking-widest px-2 py-0.5 rounded-md bg-black/5 dark:bg-white/5 inline-block mt-2 italic">{user.title || 'Citizen'}</p>
             {user.bio && <p className="text-xs font-bold opacity-70 mt-2 italic leading-snug line-clamp-2">"{user.bio}"</p>}
          </div>

          <div className="pb-2 w-full md:w-auto flex justify-center md:justify-end gap-2">
            {!isOwnProfile ? (
              <button 
                onClick={() => onFollow?.(user.username)} 
                className={`px-6 py-3 text-white rounded-xl font-black text-xs shadow-lg uppercase transition-all ${isFollowing ? 'bg-red-500' : 'bg-green-500'}`}
              >
                {isFollowing ? 'UNFOLLOW' : 'FOLLOW'}
              </button>
            ) : (
              <button 
                onClick={() => setIsEditing(true)} 
                className="px-6 py-3 text-white rounded-xl font-black text-xs uppercase shadow-xl transition-all active:scale-95" 
                style={{ backgroundColor: accentColor }}
              >
                EDIT ID
              </button>
            )}
          </div>
        </div>

        <div className="mt-6 flex justify-center md:justify-start gap-8 text-center border-t dark:border-slate-700 pt-4 px-2">
           <div><p className="text-lg font-black">{user.followers?.length || 0}</p><p className="text-[8px] md:text-[9px] uppercase font-black opacity-40 tracking-widest">Followers</p></div>
           <div><p className="text-lg font-black">{user.following?.length || 0}</p><p className="text-[8px] md:text-[9px] uppercase font-black opacity-40 tracking-widest">Following</p></div>
           <div className="group relative cursor-pointer" onClick={() => isOwnProfile && shareAchievement('exp')}>
             <p className="text-lg font-black text-orange-500 italic">{user.moodStreak || 0}</p>
             <p className="text-[8px] md:text-[9px] uppercase font-black opacity-40 tracking-widest">Streak</p>
             {isOwnProfile && <Share2 className="absolute -right-4 top-0 opacity-0 group-hover:opacity-100 transition-opacity text-orange-500" size={10} />}
           </div>
        </div>
      </div>

      <div className="flex gap-2 mb-4 shrink-0">
         {(['Posts', 'Reposts', 'Stats'] as const).map(tab => (
           <button 
             key={tab} 
             onClick={() => setActiveTab(tab)} 
             className={`flex-1 p-3 rounded-2xl font-black text-xs uppercase transition-all ${activeTab === tab ? 'text-white' : 'bg-gray-200 dark:bg-slate-700 text-gray-400 opacity-60'}`} 
             style={{ backgroundColor: activeTab === tab ? accentColor : '' }}
           >
             {tab}
           </button>
         ))}
      </div>

      {/* Profile Content */}
      <div className="flex-1 fading-scrollbar overflow-y-auto pr-1 pb-10">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          {activeTab === 'Posts' && (
            myPosts.length > 0 ? myPosts.map(post => (
              <div key={post.id} className={`p-6 rounded-[2rem] ${isDarkMode ? 'bg-slate-800' : 'bg-white'} shadow-md border-b-4 border-gray-100 dark:border-slate-900`}>
                <p className="text-sm md:text-base font-medium mb-4">{post.content}</p>
                <div className="flex gap-4 opacity-40 text-[10px] font-black uppercase">
                  <span className="flex items-center gap-1"><Heart size={14} className="text-red-500" /> {post.hearts}</span>
                  <span className="flex items-center gap-1"><MessageCircle size={14} className="text-blue-500" /> {post.comments.length}</span>
                </div>
              </div>
            )) : <div className="col-span-2 text-center py-20 opacity-20 font-black uppercase italic">No expressions logged in this identifier</div>
          )}
          {activeTab === 'Reposts' && (
             myReposts.length > 0 ? myReposts.map(post => (
              <div key={post.id} className={`p-6 rounded-[2rem] ${isDarkMode ? 'bg-slate-800' : 'bg-white'} shadow-md border-b-4 border-gray-100 dark:border-slate-900`}>
                <p className="text-[9px] font-black text-green-500 mb-2 italic">Reposted from @{post.originalAuthor}</p>
                <p className="text-sm font-medium mb-4">{post.content}</p>
              </div>
            )) : <div className="col-span-2 text-center py-20 opacity-20 font-black uppercase italic">No echoed transmissions found</div>
          )}
          {activeTab === 'Stats' && (
            <div className={`col-span-2 p-8 rounded-[3rem] ${isDarkMode ? 'bg-slate-800' : 'bg-white'} shadow-xl space-y-8`}>
               <div className="grid grid-cols-2 md:grid-cols-4 gap-6 text-center">
                 <div className="relative group">
                    <div className="w-16 h-16 rounded-2xl bg-blue-500/10 flex items-center justify-center text-blue-500 mx-auto mb-2"><Heart size={32}/></div>
                    <p className="text-2xl font-black tabular-nums">{user.likesReceived || 0}</p>
                    <p className="text-[9px] uppercase font-black opacity-40">Likes Received</p>
                    {isOwnProfile && <button onClick={() => shareAchievement('tier')} className="absolute -top-1 -right-1 p-1 bg-blue-500 text-white rounded-full opacity-0 group-hover:opacity-100 transition-opacity"><Share2 size={10}/></button>}
                 </div>
                 <div className="relative group">
                    <div className="w-16 h-16 rounded-2xl bg-purple-500/10 flex items-center justify-center text-purple-500 mx-auto mb-2"><TrendingUp size={32}/></div>
                    <p className="text-2xl font-black tabular-nums">{harmonyScore}</p>
                    <p className="text-[9px] uppercase font-black opacity-40">Harmony Level</p>
                 </div>
                 <div className="relative group">
                    <div className="w-16 h-16 rounded-2xl bg-orange-500/10 flex items-center justify-center text-orange-500 mx-auto mb-2"><Flame size={32}/></div>
                    <p className="text-2xl font-black tabular-nums">{user.moodStreak || 0}</p>
                    <p className="text-[9px] uppercase font-black opacity-40">Persistence</p>
                 </div>
                 <div className="relative group">
                    <div className="w-16 h-16 rounded-2xl bg-indigo-500/10 flex items-center justify-center text-indigo-500 mx-auto mb-2" style={{ color: currentTier.color }}><Trophy size={32}/></div>
                    <p className="text-2xl font-black italic" style={{ color: currentTier.color }}>{currentTier.name}</p>
                    <p className="text-[9px] uppercase font-black opacity-40">Tier Status</p>
                 </div>
               </div>
               <p className="text-[10px] font-black opacity-30 uppercase tracking-[0.4em] text-center border-t dark:border-slate-700 pt-6">Historical Citizen Data Verified by Council</p>
            </div>
          )}
        </div>
      </div>

      {/* Edit Profile Modal */}
      <AnimatePresence>
        {isEditing && (
          <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 md:p-8 bg-black/80 backdrop-blur-md">
            <motion.div 
              initial={{ scale: 0.9, opacity: 0 }}
              animate={{ scale: 1, opacity: 1 }}
              exit={{ scale: 0.9, opacity: 0 }}
              className={`w-full max-w-2xl max-h-[90vh] fading-scrollbar overflow-y-auto rounded-[3.5rem] p-8 shadow-2xl relative ${isDarkMode ? 'bg-slate-800 text-white' : 'bg-white text-slate-900'} border-4 border-indigo-500/30`}
            >
              <button 
                onClick={() => setIsEditing(false)} 
                className="absolute top-8 right-8 p-2 rounded-full hover:bg-gray-100 dark:hover:bg-slate-700 transition-colors"
              >
                <X />
              </button>

              <h2 className="text-4xl font-black italic uppercase mb-10 text-center tracking-tighter">Configure ID</h2>

              <div className="space-y-8">
                {/* Visuals Selection */}
                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                  <div className="space-y-4">
                    <label className="text-[10px] font-black uppercase opacity-40 tracking-widest ml-2">Avatar Frequency</label>
                    <div className="flex items-center gap-6">
                      <div className="w-24 h-24 rounded-3xl bg-gray-100 dark:bg-slate-700 overflow-hidden relative border-4 border-white shadow-xl">
                        {editForm.profilePic ? <img src={editForm.profilePic} className="w-full h-full object-cover" /> : <Camera size={40} className="absolute inset-0 m-auto opacity-20" />}
                      </div>
                      <button 
                        onClick={() => profilePicInputRef.current?.click()}
                        className="px-5 py-3 bg-indigo-500 text-white rounded-2xl text-[10px] font-black uppercase shadow-lg border-b-4 border-indigo-700 active:translate-y-1"
                      >
                        <Upload size={16} className="inline mr-2" /> Select File
                      </button>
                      <input type="file" ref={profilePicInputRef} className="hidden" accept="image/*" onChange={(e) => handleImageUpload(e, 'profile')} />
                    </div>
                  </div>

                  <div className="space-y-4">
                    <label className="text-[10px] font-black uppercase opacity-40 tracking-widest ml-2">Banner Aura</label>
                    <div className="w-full h-24 rounded-3xl bg-gray-100 dark:bg-slate-700 overflow-hidden relative shadow-xl border-4 border-white group cursor-pointer" onClick={() => bannerPicInputRef.current?.click()}>
                      {editForm.bannerPic ? <img src={editForm.bannerPic} className="w-full h-full object-cover" /> : <div className="absolute inset-0 flex items-center justify-center opacity-20"><ImageIcon size={40} /></div>}
                      <div className="absolute inset-0 bg-black/20 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center text-white text-[10px] font-black">UPLOAD BANNER</div>
                      <input type="file" ref={bannerPicInputRef} className="hidden" accept="image/*" onChange={(e) => handleImageUpload(e, 'banner')} />
                    </div>
                  </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div className="space-y-2">
                    <label className="text-[10px] font-black uppercase opacity-40 tracking-widest ml-2">Display Name</label>
                    <input 
                      type="text" 
                      value={editForm.displayName} 
                      onChange={e => setEditForm(prev => ({...prev, displayName: e.target.value}))} 
                      className={`w-full p-5 rounded-2xl border-4 font-bold outline-none focus:border-indigo-500 transition-all ${isDarkMode ? 'bg-slate-700 border-slate-600' : 'bg-gray-50 border-gray-100'}`}
                    />
                  </div>

                  <div className="space-y-2">
                    <label className="text-[10px] font-black uppercase opacity-40 tracking-widest ml-2">Citizen ID (Username)</label>
                    <input 
                      type="text" 
                      value={editForm.username} 
                      onChange={e => setEditForm(prev => ({...prev, username: e.target.value}))} 
                      className={`w-full p-5 rounded-2xl border-4 font-bold outline-none focus:border-indigo-500 transition-all ${isDarkMode ? 'bg-slate-700 border-slate-600' : 'bg-gray-50 border-gray-100'}`}
                    />
                  </div>
                </div>

                <div className="space-y-2">
                  <label className="text-[10px] font-black uppercase opacity-40 tracking-widest ml-2">Occupational Title</label>
                  <select 
                    value={editForm.title} 
                    onChange={e => setEditForm(prev => ({...prev, title: e.target.value}))}
                    className={`w-full p-5 rounded-2xl border-4 font-bold outline-none focus:border-indigo-500 appearance-none transition-all ${isDarkMode ? 'bg-slate-700 border-slate-600' : 'bg-gray-50 border-gray-100'}`}
                  >
                    {JOB_TITLES.map(title => (
                      <option key={title} value={title}>{title}</option>
                    ))}
                    {currentUser.email === 'travismiguel014@gmail.com' && <option value="Creator">Creator</option>}
                  </select>
                </div>

                <div className="space-y-2">
                  <label className="text-[10px] font-black uppercase opacity-40 tracking-widest ml-2">Biometric Data (Bio)</label>
                  <textarea 
                    value={editForm.bio} 
                    onChange={e => setEditForm(prev => ({...prev, bio: e.target.value}))} 
                    rows={2}
                    className={`w-full p-5 rounded-2xl border-4 font-bold outline-none focus:border-indigo-500 transition-all resize-none ${isDarkMode ? 'bg-slate-700 border-slate-600' : 'bg-gray-50 border-gray-100'}`}
                    placeholder="Tell the city about your vibes..."
                  />
                </div>

                <div className="space-y-2">
                  <label className="text-[10px] font-black uppercase opacity-40 tracking-widest ml-2">District Color Palette</label>
                  <div className="flex flex-wrap gap-3">
                    {['#46178f', '#1368ce', '#26890c', '#e21b3c', '#ffa602', '#ec4899', '#06b6d4', '#8b5cf6'].map(color => (
                      <button 
                        key={color} 
                        onClick={() => setEditForm(prev => ({...prev, profileColor: color}))}
                        className={`w-12 h-12 rounded-2xl transition-all ${editForm.profileColor === color ? 'ring-4 ring-indigo-500 ring-offset-4 dark:ring-offset-slate-800 scale-110 shadow-lg' : 'scale-100 opacity-60 hover:opacity-100'}`}
                        style={{ backgroundColor: color }}
                      />
                    ))}
                  </div>
                </div>

                <div className="pt-8">
                  <button 
                    onClick={handleSave} 
                    className="w-full py-6 bg-green-500 hover:bg-green-600 text-white rounded-3xl font-black text-2xl uppercase shadow-[0_12px_0_0_#1c6409] active:translate-y-2 active:shadow-none transition-all flex items-center justify-center gap-4"
                  >
                    <Check size={32} strokeWidth={3} /> AUTHORIZE CHANGES
                  </button>
                </div>
              </div>
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </div>
  );
};

export default ProfileSection;

import React, { useState, useRef, useMemo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { User, Post } from '../types';
import { Heart, MessageCircle, Flame, ShieldCheck, Camera, Image as ImageIcon, Repeat, X, Check, Upload, Share2, Sparkles, Trophy, TrendingUp } from 'lucide-react';
import { getTier, JOB_TITLES } from '../constants';

interface ProfileSectionProps {
  user: User;
  allPosts: Post[];
  isDarkMode: boolean;
  currentUser: User;
  onEditProfile?: (displayName: string, username: string, profilePic?: string, title?: string, bannerPic?: string, profileColor?: string, bio?: string) => void;
  onBlock?: (username: string) => void;
  onFollow?: (username: string) => void;
  onShareToExpress?: (msg: string) => void;
}

const ProfileSection: React.FC<ProfileSectionProps> = ({ user, allPosts, isDarkMode, currentUser, onEditProfile, onBlock, onFollow, onShareToExpress }) => {
  const [isEditing, setIsEditing] = useState(false);
  const [editForm, setEditForm] = useState({
    displayName: user.displayName,
    username: user.username,
    profilePic: user.profilePic || '',
    title: user.title || 'Citizen',
    profileColor: user.profileColor || '#46178f',
    bio: user.bio || ''
  });

  const [activeTab, setActiveTab] = useState<'Posts' | 'Reposts' | 'Stats'>('Posts');
  const profilePicInputRef = useRef<HTMLInputElement>(null);

  const isOwnProfile = currentUser.username === user.username;
  const isFollowing = currentUser.following.includes(user.username);
  const myPosts = useMemo(() => allPosts.filter(p => p.author === user.username && !p.isRepost), [allPosts, user.username]);
  const myReposts = useMemo(() => allPosts.filter(p => p.author === user.username && p.isRepost), [allPosts, user.username]);

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setEditForm(prev => ({ ...prev, profilePic: reader.result as string }));
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSave = () => {
    if (onEditProfile) {
      onEditProfile(
        editForm.displayName,
        editForm.username,
        editForm.profilePic,
        editForm.title,
        undefined, // Removed bannerPic
        editForm.profileColor,
        editForm.bio
      );
    }
    setIsEditing(false);
  };

  const currentTier = getTier(user.likesReceived || 0);
  const harmonyScore = user.moodHistory?.[user.moodHistory.length - 1]?.score || 0;
  const accentColor = isEditing ? editForm.profileColor : (user.profileColor || '#46178f');

  const shareAchievement = (type: 'tier' | 'exp') => {
    let msg = "";
    if (type === 'tier') {
      msg = `Citizen Milestone! 🏆 My status in Mooderia has reached the ${currentTier.name} tier! #MoodMilestone #CitzenStatus`;
    } else {
      msg = `Mood Guardian update! 🐾 My pet ${user.petEmoji} is now Level ${user.petLevel}! #MoodPet #Guardian`;
    }
    onShareToExpress?.(msg);
    alert("Achievement shared to the Express feed!");
  };

  return (
    <div className="flex flex-col h-full overflow-hidden">
      {/* Profile Header - Compact and Mobile Centered */}
      <div className={`relative p-6 rounded-[2.5rem] mb-4 shrink-0 ${isDarkMode ? 'bg-slate-800 text-white' : 'bg-white text-slate-900'} shadow-xl overflow-hidden`}>
        {/* Banner with large Title text */}
        <div 
          className="h-32 md:h-40 w-full rounded-[1.5rem] absolute top-0 left-0 flex items-center justify-center overflow-hidden" 
          style={{ backgroundColor: accentColor }}
        >
          <h1 className="text-white/20 text-4xl md:text-6xl font-black italic uppercase tracking-widest select-none">
            {user.title || 'CITIZEN'}
          </h1>
        </div>

        <div className="relative pt-16 md:pt-20 flex flex-col md:flex-row items-center md:items-end gap-4 px-2 mobile-center">
          <div className="w-24 h-24 md:w-32 md:h-32 rounded-[2rem] bg-white dark:bg-slate-700 p-1 shadow-2xl shrink-0 overflow-hidden relative border-4 border-white">
             {user.profilePic ? (
               <img src={user.profilePic} className="w-full h-full rounded-[1.8rem] object-cover" alt="Profile" />
             ) : (
               <div className="w-full h-full rounded-[1.8rem] flex items-center justify-center text-white text-3xl font-black" style={{ backgroundColor: accentColor }}>
                 {user.displayName ? user.displayName[0] : '?'}
               </div>
             )}
          </div>

          <div className="flex-1 min-w-0 pb-2 text-center md:text-left">
             <div className="flex flex-col md:flex-row items-center gap-2 mb-1">
               <h2 className="text-2xl md:text-3xl font-black italic uppercase truncate leading-tight">{user.displayName}</h2>
               {user.email === 'travismiguel014@gmail.com' && <div className="p-1 bg-yellow-400 text-white rounded-lg shadow-sm" title="Original Creator"><Sparkles size={14} fill="currentColor" /></div>}
             </div>
             <p className="text-sm font-bold opacity-50 uppercase tracking-tighter">@{user.username}</p>
             <p className="text-[10px] font-black uppercase tracking-widest px-3 py-1 rounded-full bg-black/5 dark:bg-white/5 inline-block mt-2 italic border border-black/5">
               {user.title || 'CITIZEN'}
             </p>
             {user.bio && <p className="text-xs font-bold opacity-70 mt-2 italic leading-snug max-w-sm mx-auto md:mx-0">"{user.bio}"</p>}
          </div>

          <div className="pb-2 w-full md:w-auto flex justify-center md:justify-end gap-2 mt-4 md:mt-0">
            {!isOwnProfile ? (
              <button 
                onClick={() => onFollow?.(user.username)} 
