            <Heart className="mx-auto mb-6 text-red-500 animate-pulse" size={48} />
            <h2 className="text-2xl md:text-3xl font-black mb-8 uppercase italic tracking-tighter">Love Matcher</h2>

            <div className="grid grid-cols-1 md:grid-cols-3 items-center gap-6 mb-8">
