                <p className="text-[10px] font-black uppercase opacity-40">Person A</p>
                <div className="flex gap-2"><MonthPicker val={m1} setVal={setM1} /><DayPicker val={d1} setVal={setD1} /></div>
              </div>
              <div className="text-3xl font-black text-red-500">&hearts;</div>
              <div className="flex flex-col gap-2">
                <p className="text-[10px] font-black uppercase opacity-40">Person B</p>
