        )}

        {tab === 'Horoscope' && (
          <motion.div key="horoscope" initial={{ opacity: 0 }} animate={{ opacity: 1 }} className={`p-8 rounded-[2.5rem] ${isDarkMode ? 'bg-slate-800' : 'bg-white'} shadow-lg border border-gray-100 dark:border-slate-700`}>
