        const secondsPassed = Math.floor((now - user.petLastUpdate) / 1000);
        user.petHunger = Math.max(0, user.petHunger - Math.floor(secondsPassed / 3600));
        user.petThirst = Math.max(0, user.petThirst - Math.floor(secondsPassed / 1800));
        user.petRest = Math.max(0, user.petRest - Math.floor(secondsPassed / 7200));
      }
      user.petLastUpdate = now;

      // Streak Logic
      const todayStr = new Date().toDateString();
      if (user.lastMoodDate && user.lastMoodDate !== todayStr) {
        const lastDate = new Date(user.lastMoodDate);
        const diffTime = new Date(todayStr).getTime() - lastDate.getTime();
        const diffDays = Math.floor(diffTime / (1000 * 3600 * 24));
        if (diffDays > 1) user.moodStreak = 0;
        setIsMoodModalOpen(true);
      } else if (!user.lastMoodDate) {
        setIsMoodModalOpen(true);
      }
      setCurrentUser(user);
    }

    setAllPosts(JSON.parse(savedPosts));
    setAllMessages(JSON.parse(savedMessages));
    setNotifications(JSON.parse(savedNotifications));
    if (savedTheme === 'dark') setIsDarkMode(true);
    setIsLoaded(true);

    const timer = setTimeout(() => setIsAppStarting(false), 2500);
    return () => clearTimeout(timer);
  }, []);

  useEffect(() => {
    if (!isLoaded) return;
    if (currentUser) {
      localStorage.setItem('mooderia_user', JSON.stringify(currentUser));
      const allUsers: User[] = JSON.parse(localStorage.getItem('mooderia_all_users') || '[]');
      const idx = allUsers.findIndex(u => u.email === currentUser.email);
      if (idx > -1) {
        allUsers[idx] = currentUser;
        localStorage.setItem('mooderia_all_users', JSON.stringify(allUsers));
      }
    }
    localStorage.setItem('mooderia_posts', JSON.stringify(allPosts));
    localStorage.setItem('mooderia_messages', JSON.stringify(allMessages));
    localStorage.setItem('mooderia_notifications', JSON.stringify(notifications));
    localStorage.setItem('mooderia_theme', isDarkMode ? 'dark' : 'light');
  }, [currentUser, allPosts, allMessages, notifications, isDarkMode, isLoaded]);

  const unreadMessages = useMemo(() => 
    allMessages.filter(m => m.recipient === currentUser?.username && !m.read).length, 
    [allMessages, currentUser?.username]
  );

  const unreadNotifs = useMemo(() => 
    notifications.filter(n => !n.read).length, 
    [notifications]
  );

  const visiblePosts = useMemo(() => {
    if (!currentUser) return allPosts;
    return allPosts.filter(p => !currentUser.blockedUsers.includes(p.author));
  }, [allPosts, currentUser?.blockedUsers]);

  const profileToView = useMemo(() => {
    if (!isLoaded) return null;
    const target = viewingUsername || currentUser?.username;
    if (!target) return currentUser;
    const allUsers: User[] = JSON.parse(localStorage.getItem('mooderia_all_users') || '[]');
    return allUsers.find(u => u.username === target) || currentUser;
  }, [viewingUsername, currentUser, isLoaded]);

  const navigateToProfile = (username: string) => {
    setViewingUsername(username);
    setActiveSection('Profile');
  };

  const addPost = (content: string) => {
    if (!currentUser) return;
    const newPost: Post = {
      id: Math.random().toString(36).substr(2, 9),
      author: currentUser.username,
      content,
      hearts: 0,
      comments: [],
      timestamp: Date.now()
    };
    setAllPosts(prev => [newPost, ...prev]);
  };

  const toggleHeart = (postId: string) => {
    const post = allPosts.find(p => p.id === postId);
    if (!post || !currentUser) return;
    setAllPosts(prev => prev.map(p => p.id === postId ? { ...p, hearts: p.hearts + 1 } : p));
    const allUsers: User[] = JSON.parse(localStorage.getItem('mooderia_all_users') || '[]');
    const authorIdx = allUsers.findIndex(u => u.username === post.author);
    if (authorIdx > -1) {
      const author = allUsers[authorIdx];
      const oldTier = getTier(author.likesReceived).name;
      author.likesReceived += 1;
      const newTier = getTier(author.likesReceived).name;
      if (oldTier !== newTier && post.author === currentUser.username) {
        setNotifications(prev => [{
          id: Math.random().toString(36).substr(2, 9),
          type: 'tier',
          fromUser: 'Council',
          timestamp: Date.now(),
          read: false,
          postContentSnippet: `Upgraded to ${newTier}!`
        }, ...prev]);
      }
      if (post.author === currentUser.username) setCurrentUser({ ...currentUser, likesReceived: author.likesReceived });
      else localStorage.setItem('mooderia_all_users', JSON.stringify(allUsers));
    }
  };

  // Fix: Implemented addComment to handle adding comments to posts
  const addComment = (postId: string, text: string) => {
    if (!currentUser) return;
    const newComment: Comment = {
      id: Math.random().toString(36).substr(2, 9),
      author: currentUser.username,
      text,
      replies: []
    };
    setAllPosts(prev => prev.map(p => p.id === postId ? { ...p, comments: [...p.comments, newComment] } : p));
  };

  // Fix: Implemented handleFollow to manage following and unfollowing logic
  const handleFollow = (username: string) => {
    if (!currentUser || currentUser.username === username) return;
    const isFollowing = currentUser.following.includes(username);
    const updatedFollowing = isFollowing 
      ? currentUser.following.filter(u => u !== username)
      : [...currentUser.following, username];

    setCurrentUser({ ...currentUser, following: updatedFollowing });

    const allUsers: User[] = JSON.parse(localStorage.getItem('mooderia_all_users') || '[]');
    const targetIdx = allUsers.findIndex(u => u.username === username);
    if (targetIdx > -1) {
      const target = allUsers[targetIdx];
      const updatedFollowers = isFollowing
        ? target.followers.filter(u => u !== currentUser.username)
        : [...target.followers, currentUser.username];
      allUsers[targetIdx] = { ...target, followers: updatedFollowers };
      localStorage.setItem('mooderia_all_users', JSON.stringify(allUsers));
    }
  };

  // Fix: Implemented handleBlockUser to manage user blocking
  const handleBlockUser = (username: string) => {
    if (!currentUser || currentUser.username === username) return;
    if (currentUser.blockedUsers.includes(username)) return;
    setCurrentUser({ ...currentUser, blockedUsers: [...currentUser.blockedUsers, username] });
    setActiveSection('Home');
  };

  // Fix: Implemented handleUnblockUser to manage user unblocking
  const handleUnblockUser = (username: string) => {
    if (!currentUser) return;
    setCurrentUser({ ...currentUser, blockedUsers: currentUser.blockedUsers.filter(u => u !== username) });
  };

  // Fix: Implemented updatePetStats to handle mood pet state management
  const updatePetStats = (hunger: number, thirst: number, rest: number, coins: number, exp: number = 0, sleepUntil: number | null = null, newEmoji?: string, markChosen?: boolean) => {
    if (!currentUser) return;
    let newHunger = Math.min(100, Math.max(0, currentUser.petHunger + hunger));
    let newThirst = Math.min(100, Math.max(0, currentUser.petThirst + thirst));
    let newRest = Math.min(100, Math.max(0, currentUser.petRest + rest));
    let newExp = currentUser.petExp + exp;
    let newLevel = currentUser.petLevel;
    let newCoins = currentUser.moodCoins + coins;

    while (newExp >= getExpNeeded(newLevel)) {
      newExp -= getExpNeeded(newLevel);
      newLevel += 1;
    }

    setCurrentUser({
      ...currentUser,
      petHunger: newHunger,
      petThirst: newThirst,
      petRest: newRest,
      petExp: newExp,
      petLevel: newLevel,
      moodCoins: newCoins,
      petSleepUntil: sleepUntil !== undefined ? sleepUntil : currentUser.petSleepUntil,
      petEmoji: newEmoji || currentUser.petEmoji,
      petHasBeenChosen: markChosen !== undefined ? markChosen : currentUser.petHasBeenChosen,
      petLastUpdate: Date.now()
    });
  };

  // Fix: Implemented sendMessage to handle City Hall interactions
  const sendMessage = (recipient: string, text: string) => {
    if (!currentUser || !text.trim()) return;
    const newMessage: Message = {
      id: Math.random().toString(36).substr(2, 9),
      sender: currentUser.username,
      recipient,
      text,
      timestamp: Date.now(),
      read: false
    };
    setAllMessages(prev => [...prev, newMessage]);
  };

  // Fix: Implemented handleLogout to clear user session
  const handleLogout = () => {
    localStorage.removeItem('mooderia_user');
    setCurrentUser(null);
    setActiveSection('Home');
  };

  const handleEditProfile = (displayName: string, username: string, profilePic?: string, title?: string, bannerPic?: string, profileColor?: string, bio?: string) => {
    if (!currentUser) return;
    let finalTitle = title || currentUser.title;
    if (finalTitle === 'Creator' && currentUser.email !== 'travismiguel014@gmail.com') finalTitle = 'Citizen';
    const updatedUser = {
      ...currentUser,
      displayName,
      username,
      profilePic: profilePic || currentUser.profilePic,
      title: finalTitle,
      profileColor: profileColor || currentUser.profileColor,
      bio: bio || currentUser.bio
    };
    if (username !== currentUser.username) {
      setAllPosts(prev => prev.map(p => ({ ...p, author: p.author === currentUser.username ? username : p.author })));
      setAllMessages(prev => prev.map(m => ({
        ...m,
        sender: m.sender === currentUser.username ? username : m.sender,
        recipient: m.recipient === currentUser.username ? username : m.recipient
      })));
    }
    setCurrentUser(updatedUser);
  };

  if (isAppStarting) return <LoadingScreen />;
  if (!currentUser) return <AuthScreen onLogin={setCurrentUser} />;

  return (
    <div className={`h-screen max-h-screen overflow-hidden flex flex-col md:flex-row ${isDarkMode ? 'bg-slate-900 text-white' : 'bg-gray-50 text-slate-900'} transition-colors duration-300`}>
      <AnimatePresence>{isMoodModalOpen && <MoodCheckIn onSubmit={(m) => {
        const today = new Date().toDateString();
        setCurrentUser({
          ...currentUser,
          moodStreak: (currentUser.moodStreak || 0) + 1,
          lastMoodDate: today,
          moodHistory: [...(currentUser.moodHistory || []), { date: today, mood: m, score: MOOD_SCORES[m || 'Normal'] }]
        });
        setIsMoodModalOpen(false);
      }} isDarkMode={isDarkMode} />}</AnimatePresence>
      <Sidebar activeSection={activeSection} onNavigate={(s) => { setActiveSection(s); if(s === 'Profile') setViewingUsername(currentUser.username); }} isDarkMode={isDarkMode} user={currentUser} unreadMessages={unreadMessages} unreadNotifications={unreadNotifs} />
      <main className="flex-1 flex flex-col relative pt-16 pb-20 md:pt-0 md:pb-0 h-full overflow-hidden">
        <div className="flex-1 overflow-hidden p-4 md:p-8">
          <motion.div key={activeSection + (activeSection === 'Profile' ? viewingUsername : '')} initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} className="h-full max-w-5xl mx-auto flex flex-col">
            {activeSection === 'Home' && <div className="h-full fading-scrollbar overflow-y-auto pr-2"><HomeSection user={currentUser} posts={visiblePosts} isDarkMode={isDarkMode} /></div>}
            {activeSection === 'Mood' && <MoodSection user={currentUser} posts={visiblePosts} onPost={addPost} onHeart={toggleHeart} onComment={addComment} onRepost={(p) => setAllPosts([{ ...p, id: Math.random().toString(36).substr(2, 9), author: currentUser.username, isRepost: true, originalAuthor: p.author, timestamp: Date.now() }, ...allPosts])} onFollow={handleFollow} onBlock={handleBlockUser} isDarkMode={isDarkMode} onNavigateToProfile={navigateToProfile} onUpdatePet={updatePetStats} />}
            {activeSection === 'Zodiac' && <div className="h-full fading-scrollbar overflow-y-auto pr-2"><ZodiacSection isDarkMode={isDarkMode} /></div>}
            {activeSection === 'CityHall' && <CityHallSection isDarkMode={isDarkMode} currentUser={currentUser} messages={allMessages} onSendMessage={sendMessage} onReadMessages={(u) => setAllMessages(allMessages.map(m => (m.recipient === currentUser.username && m.sender === u) ? {...m, read: true} : m))} onNavigateToProfile={navigateToProfile} />}
            {activeSection === 'Notifications' && <div className="h-full fading-scrollbar overflow-y-auto pr-2"><NotificationsSection notifications={notifications} isDarkMode={isDarkMode} onMarkRead={() => setNotifications(notifications.map(n => ({...n, read: true})))} /></div>}
            {activeSection === 'Profile' && profileToView && <ProfileSection user={profileToView} allPosts={allPosts} isDarkMode={isDarkMode} onEditProfile={handleEditProfile} onBlock={handleBlockUser} onFollow={handleFollow} currentUser={currentUser} onShareToExpress={addPost} />}
            {activeSection === 'Settings' && <div className="h-full fading-scrollbar overflow-y-auto pr-2"><SettingsSection isDarkMode={isDarkMode} onToggleDarkMode={() => setIsDarkMode(!isDarkMode)} onLogout={handleLogout} user={currentUser} onUnblock={handleUnblockUser} /></div>}
          </motion.div>
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Heart, MessageCircle, Repeat, Send, Sparkles, Brain, Wind, ShoppingBag, Gamepad2, Bed, Lock, Coins, Ghost, QuestionMark, Zap, Calculator, Target, Trophy } from 'lucide-react';
import { User, Post, Mood, Comment } from '../types';
import MoodPetSection from './MoodPetSection';
import { getTellerResponse } from '../services/geminiService';
import { QUIZ_QUESTIONS } from '../constants';

interface MoodSectionProps {
  user: User;
  posts: Post[];
  onPost: (content: string) => void;
  onHeart: (postId: string) => void;
  onComment: (postId: string, text: string) => void;
  onRepost: (post: Post) => void;
  onFollow: (username: string) => void;
  onBlock: (username: string) => void;
  isDarkMode: boolean;
  onNavigateToProfile: (username: string) => void;
  onUpdatePet: (hunger: number, thirst: number, rest: number, coins: number, exp?: number, sleepUntil?: number | null, newEmoji?: string, markChosen?: boolean) => void;
}

type MoodSubTab = 'Express' | 'Teller' | 'Quiz' | 'MoodPet';

const MoodSection: React.FC<MoodSectionProps> = ({ user, posts, onPost, onHeart, onComment, onRepost, onFollow, onBlock, isDarkMode, onNavigateToProfile, onUpdatePet }) => {
  const [subTab, setSubTab] = useState<MoodSubTab>('Express');
  const [postContent, setPostContent] = useState('');
  const [feedFilter, setFeedFilter] = useState<'All' | 'Following'>('All');
  const [expandedComments, setExpandedComments] = useState<string | null>(null);
  const [newComment, setNewComment] = useState('');

  // Teller State
  const [tellerQuestion, setTellerQuestion] = useState('');
  const [tellerResponse, setTellerResponse] = useState('');
  const [isTellerLoading, setIsTellerLoading] = useState(false);

  // Quiz State
  const [quizActive, setQuizActive] = useState(false);
  const [quizQuestions, setQuizQuestions] = useState<typeof QUIZ_QUESTIONS>([]);
  const [quizStep, setQuizStep] = useState(0);
  const [quizScore, setQuizScore] = useState(0);
  const [quizFinished, setQuizFinished] = useState(false);

  const startQuiz = () => {
    const shuffled = [...QUIZ_QUESTIONS].sort(() => 0.5 - Math.random()).slice(0, 5);
    setQuizQuestions(shuffled);
    setQuizActive(true);
    setQuizStep(0);
    setQuizScore(0);
    setQuizFinished(false);
  };

  const handleQuizAnswer = (idx: number) => {
    if (idx === quizQuestions[quizStep].a) setQuizScore(s => s + 1);

    if (quizStep < quizQuestions.length - 1) {
      setQuizStep(s => s + 1);
    } else {
      setQuizFinished(true);
      onUpdatePet(0, 0, 0, quizScore * 20, quizScore * 50);
    }
  };

  const handleTeller = async () => {
    if (!tellerQuestion.trim()) return;
    setIsTellerLoading(true);
    setTellerResponse('');
    try {
      const res = await getTellerResponse(tellerQuestion);
      setTellerResponse(res || 'The cosmic fog obscures my vision...');
    } catch (e) {
      setTellerResponse('MAYBE. The spirits are currently in a meeting. Try again after the next lunar cycle.');
    } finally {
      setIsTellerLoading(false);
    }
  };

  const filteredPosts = feedFilter === 'All' 
    ? posts 
    : posts.filter(p => user.following.includes(p.author) || p.author === user.username);

  const handlePost = () => {
    if (!postContent.trim()) return;
    onPost(postContent);
    setPostContent('');
  };

  return (
    <div className="flex flex-col h-full overflow-hidden">
      {/* Tab Switcher Header */}
      <div className="flex items-center justify-center pb-4 shrink-0 overflow-x-auto no-scrollbar">
        <div className="flex gap-2 p-1 bg-gray-100 dark:bg-slate-800 rounded-full shadow-inner">
          {(['Express', 'Teller', 'Quiz', 'MoodPet'] as MoodSubTab[]).map((tab) => (
            <button
              key={tab}
              onClick={() => setSubTab(tab)}
              className={`px-6 py-2 rounded-full font-black whitespace-nowrap transition-all text-xs ${subTab === tab ? 'bg-white dark:bg-slate-700 text-[#46178f] dark:text-white shadow-md' : 'text-gray-400 hover:text-slate-900 dark:hover:text-white opacity-70'}`}
            >
              {tab === 'MoodPet' ? 'PET 🐾' : tab.toUpperCase()}
            </button>
          ))}
        </div>
      </div>

      <div className="flex-1 fading-scrollbar overflow-y-auto pr-1 pb-10">
        <AnimatePresence mode="wait">
          {subTab === 'Express' && (
            <motion.div key="express" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="space-y-6">
              <div className="flex justify-center md:justify-start">
                <div className="flex gap-2 p-1 bg-gray-200 dark:bg-slate-800 rounded-2xl w-fit">
                  <button onClick={() => setFeedFilter('All')} className={`px-5 py-2 rounded-xl text-[10px] font-black transition-all ${feedFilter === 'All' ? 'bg-white dark:bg-slate-700 shadow-sm text-slate-900 dark:text-white' : 'opacity-50 text-slate-600 dark:text-slate-400'}`}>ALL DISTRICTS</button>
                  <button onClick={() => setFeedFilter('Following')} className={`px-5 py-2 rounded-xl text-[10px] font-black transition-all ${feedFilter === 'Following' ? 'bg-white dark:bg-slate-700 shadow-sm text-slate-900 dark:text-white' : 'opacity-50 text-slate-600 dark:text-slate-400'}`}>MY CIRCLE</button>
                </div>
              </div>

              <div className={`p-6 rounded-[2.5rem] ${isDarkMode ? 'bg-slate-800' : 'bg-white'} shadow-lg border border-gray-100 dark:border-slate-700`}>
                <textarea value={postContent} onChange={(e) => setPostContent(e.target.value)} placeholder="What's your emotional broadcast for today?" className={`w-full p-4 rounded-xl border-2 focus:border-[#46178f] outline-none transition-all text-sm font-medium ${isDarkMode ? 'bg-slate-700 border-slate-600 text-white' : 'bg-gray-50 border-gray-200 text-slate-900'}`} rows={3} />
                <div className="flex justify-end mt-4">
                  <button onClick={handlePost} className="kahoot-button-blue px-8 py-3 text-white rounded-xl font-black text-xs flex items-center gap-2 transition-all hover:scale-105 active:scale-95"><Send size={16} /> TRANSMIT</button>
                </div>
              </div>

              <div className="space-y-4 pb-20">
                {filteredPosts.length > 0 ? filteredPosts.map(post => (
                    <motion.div layout key={post.id} className={`p-6 rounded-[2rem] ${isDarkMode ? 'bg-slate-800' : 'bg-white'} shadow-md border border-gray-100 dark:border-slate-700`}>
                      <div className="flex items-center justify-between mb-4">
                        <button onClick={() => onNavigateToProfile(post.author)} className="flex items-center gap-3 text-left hover:opacity-80 transition-opacity">
                          <div className="w-10 h-10 rounded-xl bg-gradient-to-tr from-purple-500 to-indigo-600 flex items-center justify-center text-white font-black overflow-hidden shadow-sm">
                            {post.author[0].toUpperCase()}
                          </div>
                          <div>
                            <h4 className="font-black text-sm tracking-tight">@{post.author}</h4>
                            {post.isRepost && <p className="text-[9px] font-bold opacity-50 flex items-center gap-1 text-green-500"><Repeat size={10}/> Echoed from @{post.originalAuthor}</p>}
                          </div>
                        </button>
                      </div>
                      <p className="text-sm md:text-base mb-6 leading-relaxed font-bold tracking-tight">{post.content}</p>

                      <div className="flex items-center gap-6 pt-4 border-t border-gray-100 dark:border-slate-700">
                        <button onClick={() => onHeart(post.id)} className="flex items-center gap-1 text-red-500 font-black text-[10px] hover:scale-110"><Heart size={18} fill={post.hearts > 0 ? "currentColor" : "none"} /> {post.hearts}</button>
                        <button onClick={() => setExpandedComments(expandedComments === post.id ? null : post.id)} className="flex items-center gap-1 text-blue-500 font-black text-[10px] hover:scale-110"><MessageCircle size={18} /> {post.comments.length}</button>
                        <button onClick={() => onRepost(post)} className="flex items-center gap-1 text-green-500 font-black text-[10px] hover:scale-110"><Repeat size={18} /> ECHO</button>
                      </div>
                    </motion.div>
                )) : (
                  <div className="py-20 text-center opacity-30 font-black uppercase tracking-widest text-[10px] italic">No transmissions detected in this district</div>
                )}
              </div>
            </motion.div>
          )}

          {subTab === 'MoodPet' && (
            <motion.div key="pet" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="h-full">
              <MoodPetSection user={user} isDarkMode={isDarkMode} onUpdate={onUpdatePet} onPost={onPost} />
            </motion.div>
          )}

          {subTab === 'Teller' && (
            <motion.div key="teller" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="h-full flex flex-col items-center justify-center p-6 md:p-10 text-center bg-[#46178f] rounded-[2.5rem] shadow-xl relative overflow-hidden">
              <div className="absolute top-[-20%] left-[-20%] w-[60%] h-[60%] bg-white/5 blur-[100px] rounded-full"></div>
              <motion.div animate={{ rotate: isTellerLoading ? 360 : [0, 5, -5, 0], scale: [1, 1.05, 1] }} transition={{ repeat: Infinity, duration: isTellerLoading ? 1 : 4 }} className="mb-8 text-7xl select-none">🔮</motion.div>
              <h3 className="text-2xl md:text-3xl font-black italic uppercase text-white mb-2 tracking-tighter">Mystic Teller</h3>
              <p className="text-xs opacity-90 mb-8 max-w-sm font-bold text-white uppercase tracking-widest">Ask a question about your destiny</p>
              <div className="w-full max-w-lg space-y-4">
                <input type="text" value={tellerQuestion} onChange={e => setTellerQuestion(e.target.value)} placeholder="Will I find peace today?" className={`w-full p-4 rounded-xl border-4 outline-none font-black text-lg shadow-inner focus:border-white transition-all bg-white/10 text-white placeholder-white/40 border-white/10`} />
                <button onClick={handleTeller} disabled={isTellerLoading} className="kahoot-button-blue w-full p-4 rounded-xl text-white font-black uppercase text-lg shadow-lg active:translate-y-1">CONSULT VOID</button>
              </div>
              <AnimatePresence>
                {tellerResponse && (
                  <motion.div initial={{ scale: 0.9, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} className="mt-8 p-6 rounded-3xl bg-white/10 border-2 border-white/20 max-w-md w-full shadow-2xl">
                    <p className="text-xl md:text-2xl font-black italic text-white uppercase mb-2 tracking-tighter">{tellerResponse.split('.')[0]}</p>
                    <p className="text-sm md:text-base font-bold text-white leading-snug italic opacity-80">{tellerResponse.split('.').slice(1).join('.')}</p>
                  </motion.div>
                )}
              </AnimatePresence>
            </motion.div>
          )}

          {subTab === 'Quiz' && (
            <motion.div key="quiz" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="h-full">
              {!quizActive ? (
                <div className="h-full flex flex-col items-center justify-center text-center p-6 md:p-10 bg-[#46178f] rounded-[2.5rem] shadow-xl">
                  <div className="w-20 h-20 bg-white/10 rounded-2xl flex items-center justify-center mb-6 border-2 border-white/10">
                    <Brain className="text-white" size={48} />
                  </div>
                  <h3 className="text-2xl md:text-4xl font-black italic uppercase mb-2 tracking-tighter text-white">Mind Palace Quiz</h3>
                  <p className="text-xs opacity-90 mb-8 max-w-xs font-bold text-white uppercase tracking-widest leading-relaxed">Showcase your Mooderia expertise for rewards!</p>
                  <button onClick={startQuiz} className="kahoot-button-green px-12 py-4 rounded-2xl text-white font-black text-xl uppercase shadow-lg active:translate-y-1">INITIATE TEST</button>
                </div>
              ) : quizFinished ? (
