                  <div className="grid grid-cols-2 gap-4 w-full max-w-md mb-8">
                    <div className="bg-yellow-400 p-4 rounded-2xl text-white">
                       <p className="text-[10px] font-black uppercase mb-1">Coins</p>
                       <p className="text-xl font-black">+{quizScore * 20}</p>
                    </div>
                    <div className="bg-purple-600 p-4 rounded-2xl text-white">
                       <p className="text-[10px] font-black uppercase mb-1">EXP</p>
                       <p className="text-xl font-black">+{quizScore * 50}</p>
                    </div>
                  </div>
                  <button onClick={startQuiz} className="kahoot-button-blue px-10 py-4 rounded-xl text-white font-black uppercase shadow-lg">RETRY</button>
                </div>
              ) : (
                <div className="max-w-xl mx-auto py-8 px-4 bg-white dark:bg-slate-800 rounded-3xl shadow-lg border border-gray-100 dark:border-slate-700">
                  <div className="flex justify-between items-center mb-10">
                    <span className="text-[9px] font-black uppercase opacity-40 tracking-widest text-indigo-500">Node {quizStep + 1} of 5</span>
                    <div className="w-24 h-2 bg-gray-100 dark:bg-slate-700 rounded-full overflow-hidden">
                      <motion.div initial={{ width: 0 }} animate={{ width: `${(quizStep + 1) * 20}%` }} className="h-full bg-indigo-500" />
                    </div>
                  </div>
                  <h4 className="text-lg md:text-2xl font-black italic mb-10 leading-tight tracking-tight text-center">{quizQuestions[quizStep].q}</h4>
                  <div className="grid grid-cols-1 gap-3">
                    {quizQuestions[quizStep].options.map((opt, i) => (
                      <motion.button key={i} whileHover={{ scale: 1.02 }} whileTap={{ scale: 0.98 }} onClick={() => handleQuizAnswer(i)} className={`p-5 rounded-2xl border-2 text-left font-black text-sm transition-all shadow-sm ${isDarkMode ? 'bg-slate-700 border-slate-600 hover:border-indigo-500' : 'bg-white border-gray-100 hover:border-indigo-500'}`}>
                        {opt}
                      </motion.button>
                    ))}
                  </div>
                </div>
              )}
            </motion.div>
          )}
        </AnimatePresence>
      </div>
    </div>
  );
};

