    history.forEach(h => {
      if (['Wonderful', 'Excited', 'Happy'].includes(h.mood || '')) counts.Happy++;
      else if (h.mood === 'Normal') counts.Sad++; // Mapping normal to sad/neutral as per logic
      else if (['Angry', 'Flaming'].includes(h.mood || '')) counts.Angry++;
      else if (h.mood === 'Tired') counts.Tired++;
    });

    const total = history.length;
    return {
      Happy: Math.round((counts.Happy / total) * 100),
      Sad: Math.round((counts.Sad / total) * 100),
      Angry: Math.round((counts.Angry / total) * 100),
      Tired: Math.round((counts.Tired / total) * 100),
