import React, { useState, useEffect, useMemo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { User, Mood, Section, Post, Comment, Message, Notification } from './types';
import Sidebar from './components/Sidebar';
import MoodCheckIn from './components/MoodCheckIn';
import HomeSection from './sections/HomeSection';
import MoodSection from './sections/MoodSection';
import ZodiacSection from './sections/ZodiacSection';
import CityHallSection from './sections/CityHallSection';
import ProfileSection from './sections/ProfileSection';
import SettingsSection from './sections/SettingsSection';
import NotificationsSection from './sections/NotificationsSection';
import AuthScreen from './sections/AuthScreen';
import LoadingScreen from './components/LoadingScreen';
import { getExpNeeded, MOOD_SCORES, getTier } from './constants';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [activeSection, setActiveSection] = useState<Section>('Home');
  const [viewingUsername, setViewingUsername] = useState<string | null>(null);
  const [isMoodModalOpen, setIsMoodModalOpen] = useState(false);
  const [isDarkMode, setIsDarkMode] = useState(true); // Default to dark for metropolis aesthetic
  const [isAppStarting, setIsAppStarting] = useState(true);

  const [allPosts, setAllPosts] = useState<Post[]>([]);
  const [allMessages, setAllMessages] = useState<Message[]>([]);
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);

  useEffect(() => {
    const savedUser = localStorage.getItem('mooderia_user');
    const savedPosts = localStorage.getItem('mooderia_posts') || '[]';
    const savedMessages = localStorage.getItem('mooderia_messages') || '[]';
    const savedNotifications = localStorage.getItem('mooderia_notifications') || '[]';
    const savedTheme = localStorage.getItem('mooderia_theme');

    if (savedUser) {
      let user: User = JSON.parse(savedUser);
      const now = Date.now();

      // Pet Stat Decay
      if (user.petLastUpdate) {
        const secondsPassed = Math.floor((now - user.petLastUpdate) / 1000);
        user.petHunger = Math.max(0, user.petHunger - Math.floor(secondsPassed / 3600));
        user.petThirst = Math.max(0, user.petThirst - Math.floor(secondsPassed / 1800));
        user.petRest = Math.max(0, user.petRest - Math.floor(secondsPassed / 7200));
      }
      user.petLastUpdate = now;

      // Streak Logic - Reset if skipped a day
      const todayStr = new Date().toDateString();
      if (user.lastMoodDate && user.lastMoodDate !== todayStr) {
        const lastDate = new Date(user.lastMoodDate);
        const diffTime = new Date(todayStr).getTime() - lastDate.getTime();
        const diffDays = Math.floor(diffTime / (1000 * 3600 * 24));
        if (diffDays > 1) {
          user.moodStreak = 0;
        }
        setIsMoodModalOpen(true);
      } else if (!user.lastMoodDate) {
        setIsMoodModalOpen(true);
      }
      setCurrentUser(user);
    }

    setAllPosts(JSON.parse(savedPosts));
    setAllMessages(JSON.parse(savedMessages));
    setNotifications(JSON.parse(savedNotifications));
    if (savedTheme === 'light') setIsDarkMode(false);
    setIsLoaded(true);

    const timer = setTimeout(() => setIsAppStarting(false), 2500);
    return () => clearTimeout(timer);
  }, []);

  useEffect(() => {
    if (!isLoaded) return;
    if (currentUser) {
      localStorage.setItem('mooderia_user', JSON.stringify(currentUser));
      const allUsers: User[] = JSON.parse(localStorage.getItem('mooderia_all_users') || '[]');
      const idx = allUsers.findIndex(u => u.email === currentUser.email);
      if (idx > -1) {
        allUsers[idx] = currentUser;
        localStorage.setItem('mooderia_all_users', JSON.stringify(allUsers));
      } else {
        allUsers.push(currentUser);
        localStorage.setItem('mooderia_all_users', JSON.stringify(allUsers));
      }
    }
    localStorage.setItem('mooderia_posts', JSON.stringify(allPosts));
    localStorage.setItem('mooderia_messages', JSON.stringify(allMessages));
    localStorage.setItem('mooderia_notifications', JSON.stringify(notifications));
    localStorage.setItem('mooderia_theme', isDarkMode ? 'dark' : 'light');
  }, [currentUser, allPosts, allMessages, notifications, isDarkMode, isLoaded]);

  const profileToView = useMemo(() => {
    if (!isLoaded) return null;
    const target = viewingUsername || currentUser?.username;
    if (!target) return currentUser;
    const allUsers: User[] = JSON.parse(localStorage.getItem('mooderia_all_users') || '[]');
    return allUsers.find(u => u.username === target) || currentUser;
  }, [viewingUsername, currentUser, isLoaded]);

  const handleEditProfile = (displayName: string, username: string, profilePic?: string, title?: string, bannerPic?: string, profileColor?: string, bio?: string) => {
    if (!currentUser) return;
    let finalTitle = title || currentUser.title;
    // Creator title only for specific user
    if (finalTitle === 'Creator' && currentUser.email !== 'travismiguel014@gmail.com') {
      finalTitle = 'Citizen';
    }

    const updatedUser = {
      ...currentUser,
      displayName,
      username,
      profilePic: profilePic || currentUser.profilePic,
      title: finalTitle,
      profileColor: profileColor || currentUser.profileColor,
      bio: bio || currentUser.bio
    };

    if (username !== currentUser.username) {
      // Update all data associated with old username
      setAllPosts(prev => prev.map(p => ({ ...p, author: p.author === currentUser.username ? username : p.author })));
      setAllMessages(prev => prev.map(m => ({
        ...m,
        sender: m.sender === currentUser.username ? username : m.sender,
        recipient: m.recipient === currentUser.username ? username : m.recipient
      })));
    }
    setCurrentUser(updatedUser);
  };

  const updatePetStats = (hunger: number, thirst: number, rest: number, coins: number, exp: number = 0, sleepUntil: number | null = null, newEmoji?: string, markChosen?: boolean) => {
    if (!currentUser) return;
    let newLevel = currentUser.petLevel;
    let newExp = currentUser.petExp + exp;
    while (newExp >= getExpNeeded(newLevel)) {
      newExp -= getExpNeeded(newLevel);
      newLevel += 1;
    }
    setCurrentUser({
      ...currentUser,
      petHunger: Math.min(100, Math.max(0, currentUser.petHunger + hunger)),
      petThirst: Math.min(100, Math.max(0, currentUser.petThirst + thirst)),
      petRest: Math.min(100, Math.max(0, currentUser.petRest + rest)),
      petExp: newExp,
      petLevel: newLevel,
      moodCoins: currentUser.moodCoins + coins,
      petSleepUntil: sleepUntil !== undefined ? sleepUntil : currentUser.petSleepUntil,
      petEmoji: newEmoji || currentUser.petEmoji,
      petHasBeenChosen: markChosen !== undefined ? markChosen : currentUser.petHasBeenChosen,
      petLastUpdate: Date.now()
    });
  };

  const toggleHeart = (postId: string) => {
    const post = allPosts.find(p => p.id === postId);
    if (!post || !currentUser) return;

    setAllPosts(prev => prev.map(p => p.id === postId ? { ...p, hearts: p.hearts + 1 } : p));

    const allUsers: User[] = JSON.parse(localStorage.getItem('mooderia_all_users') || '[]');
    const authorIdx = allUsers.findIndex(u => u.username === post.author);
    if (authorIdx > -1) {
      const author = allUsers[authorIdx];
      const oldTier = getTier(author.likesReceived).name;
      author.likesReceived += 1;
      const newTier = getTier(author.likesReceived).name;

      if (oldTier !== newTier && post.author === currentUser.username) {
        setNotifications(prev => [{
          id: Math.random().toString(36).substr(2, 9),
          type: 'tier',
          fromUser: 'City Council',
          timestamp: Date.now(),
          read: false,
          postContentSnippet: `Upgraded to ${newTier} tier!`
        }, ...prev]);
      }

      if (post.author === currentUser.username) {
        setCurrentUser({ ...currentUser, likesReceived: author.likesReceived });
      } else {
        localStorage.setItem('mooderia_all_users', JSON.stringify(allUsers));
      }
    }
  };

  if (isAppStarting) return <LoadingScreen />;
  if (!currentUser) return <AuthScreen onLogin={setCurrentUser} />;

  return (
    <div className={`h-screen max-h-screen overflow-hidden flex flex-col md:flex-row bg-[#0f0f0f] text-white transition-colors duration-300`}>
      <AnimatePresence>
        {isMoodModalOpen && (
          <MoodCheckIn 
            onSubmit={(m) => {
              const today = new Date().toDateString();
              setCurrentUser({
                ...currentUser,
                moodStreak: (currentUser.moodStreak || 0) + 1,
                lastMoodDate: today,
                moodHistory: [...(currentUser.moodHistory || []), { date: today, mood: m, score: MOOD_SCORES[m || 'Normal'] }]
              });
              setIsMoodModalOpen(false);
            }} 
            isDarkMode={true} 
          />
        )}
      </AnimatePresence>
      <Sidebar 
        activeSection={activeSection} 
        onNavigate={(s) => { setActiveSection(s); if(s === 'Profile') setViewingUsername(currentUser.username); }} 
        isDarkMode={true} 
        user={currentUser} 
        unreadMessages={allMessages.filter(m => m.recipient === currentUser.username && !m.read).length} 
        unreadNotifications={notifications.filter(n => !n.read).length} 
      />
      <main className="flex-1 flex flex-col relative pt-16 pb-20 md:pt-0 md:pb-0 h-full overflow-hidden">
        <div className="flex-1 overflow-hidden p-4 md:p-8">
          <motion.div key={activeSection + (activeSection === 'Profile' ? viewingUsername : '')} initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} className="h-full max-w-5xl mx-auto flex flex-col">
            {activeSection === 'Home' && <div className="h-full fading-scrollbar overflow-y-auto pr-2"><HomeSection user={currentUser} posts={allPosts} isDarkMode={true} /></div>}
            {activeSection === 'Mood' && <MoodSection user={currentUser} posts={allPosts.filter(p => !currentUser.blockedUsers.includes(p.author))} onPost={(c) => setAllPosts([{id: Math.random().toString(36).substr(2, 9), author: currentUser.username, content: c, hearts: 0, comments: [], timestamp: Date.now()}, ...allPosts])} onHeart={toggleHeart} onComment={(pid, t) => setAllPosts(prev => prev.map(p => p.id === pid ? {...p, comments: [...p.comments, {id: Math.random().toString(36).substr(2,9), author: currentUser.username, text: t, replies: []}]} : p))} onRepost={(p) => setAllPosts([{ ...p, id: Math.random().toString(36).substr(2, 9), author: currentUser.username, isRepost: true, originalAuthor: p.author, timestamp: Date.now() }, ...allPosts])} onFollow={(u) => {const isF = currentUser.following.includes(u); setCurrentUser({...currentUser, following: isF ? currentUser.following.filter(f => f !== u) : [...currentUser.following, u]});}} onBlock={(u) => {if(!currentUser.blockedUsers.includes(u)) setCurrentUser({...currentUser, blockedUsers: [...currentUser.blockedUsers, u]}); setActiveSection('Home');}} isDarkMode={true} onNavigateToProfile={(u) => {setViewingUsername(u); setActiveSection('Profile');}} onUpdatePet={updatePetStats} />}
            {activeSection === 'Zodiac' && <div className="h-full fading-scrollbar overflow-y-auto pr-2"><ZodiacSection isDarkMode={true} /></div>}
            {activeSection === 'CityHall' && <CityHallSection isDarkMode={true} currentUser={currentUser} messages={allMessages} onSendMessage={(r, t) => setAllMessages([...allMessages, {id: Math.random().toString(36).substr(2, 9), sender: currentUser.username, recipient: r, text: t, timestamp: Date.now(), read: false}])} onReadMessages={(u) => setAllMessages(allMessages.map(m => (m.recipient === currentUser.username && m.sender === u) ? {...m, read: true} : m))} onNavigateToProfile={(u) => {setViewingUsername(u); setActiveSection('Profile');}} />}
            {activeSection === 'Notifications' && <div className="h-full fading-scrollbar overflow-y-auto pr-2"><NotificationsSection notifications={notifications} isDarkMode={true} onMarkRead={() => setNotifications(notifications.map(n => ({...n, read: true})))} /></div>}
            {activeSection === 'Profile' && profileToView && <ProfileSection user={profileToView} allPosts={allPosts} isDarkMode={true} onEditProfile={handleEditProfile} onBlock={(u) => {if(!currentUser.blockedUsers.includes(u)) setCurrentUser({...currentUser, blockedUsers: [...currentUser.blockedUsers, u]}); setActiveSection('Home');}} onFollow={(u) => {const isF = currentUser.following.includes(u); setCurrentUser({...currentUser, following: isF ? currentUser.following.filter(f => f !== u) : [...currentUser.following, u]});}} currentUser={currentUser} onShareToExpress={(c) => setAllPosts([{id: Math.random().toString(36).substr(2, 9), author: currentUser.username, content: c, hearts: 0, comments: [], timestamp: Date.now()}, ...allPosts])} />}
            {activeSection === 'Settings' && <div className="h-full fading-scrollbar overflow-y-auto pr-2"><SettingsSection isDarkMode={true} onToggleDarkMode={() => setIsDarkMode(!isDarkMode)} onLogout={() => {localStorage.removeItem('mooderia_user'); setCurrentUser(null);}} user={currentUser} onUnblock={(u) => setCurrentUser({...currentUser, blockedUsers: currentUser.blockedUsers.filter(b => b !== u)})} /></div>}
          </motion.div>
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useRef, useMemo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
