import { Heart, MessageCircle, Flame, Camera, Repeat, X, Check, Share2, Edit3, ShieldAlert, Sparkles, Trophy, TrendingUp } from 'lucide-react';
import { getTier, JOB_TITLES } from '../constants';

interface ProfileSectionProps {
  user: User;
  allPosts: Post[];
  isDarkMode: boolean;
  currentUser: User;
  onEditProfile?: (displayName: string, username: string, profilePic?: string, title?: string, bannerPic?: string, profileColor?: string, bio?: string) => void;
  onBlock?: (username: string) => void;
  onFollow?: (username: string) => void;
  onShareToExpress?: (msg: string) => void;
}

