    setIsEditing(false);
  };

  const accentColor = user.profileColor || '#e21b3c';

  // Calculate Emotional DNA
  const emotionalDNA = useMemo(() => {
    const history = user.moodHistory || [];
    if (history.length === 0) return { Happy: 0, Sad: 0, Angry: 0, Tired: 0 };

    const counts = { Happy: 0, Sad: 0, Angry: 0, Tired: 0 };
    history.forEach(h => {
      if (['Wonderful', 'Excited', 'Happy'].includes(h.mood || '')) counts.Happy++;
      else if (h.mood === 'Normal') counts.Sad++; 
      else if (['Angry', 'Flaming'].includes(h.mood || '')) counts.Angry++;
      else if (h.mood === 'Tired') counts.Tired++;
    });

    const total = history.length;
    return {
      HAPPY: Math.round((counts.Happy / total) * 100),
      SAD: Math.round((counts.Sad / total) * 100),
      ANGRY: Math.round((counts.Angry / total) * 100),
      TIRED: Math.round((counts.Tired / total) * 100),
    };
  }, [user.moodHistory]);

  return (
    <div className="flex flex-col h-full overflow-hidden">
      {/* Scrollable Dashboard Container */}
