                   style={{ width: '200%', textAlign: 'center' }}
                 >
                   {user.title || 'CITIZEN'} {user.title || 'CITIZEN'} {user.title || 'CITIZEN'} {user.title || 'CITIZEN'}
                 </span>
              </div>
            </div>

            {/* Content Area */}
            <div className="px-6 md:px-8 pb-8 -mt-16 flex flex-col md:flex-row items-center md:items-end gap-6">
              {/* Profile Pic Container */}
              <div className="w-36 h-36 md:w-44 md:h-44 rounded-[2.5rem] bg-[#111111] p-1.5 shadow-2xl relative shrink-0">
                 <div className="w-full h-full rounded-[2.2rem] overflow-hidden border-4 border-black bg-slate-800">
                   {user.profilePic ? (
