                 </div>
              </div>

              {/* User Info */}
              <div className="flex-1 text-center md:text-left pb-2">
                <div className="bg-[#222222] border border-white/10 px-4 py-1 rounded-full w-fit mb-3 mx-auto md:mx-0">
                   <span className="text-[10px] font-black uppercase tracking-widest text-[#e21b3c] italic">{user.title || 'CITIZEN'}</span>
