                  <motion.div initial={{ opacity: 0, scale: 0.95 }} animate={{ opacity: 1, scale: 1 }} key={post.id} className="p-6 rounded-[2rem] bg-[#111111] border border-white/5 shadow-lg">
                    <p className="text-white font-medium mb-4 leading-relaxed">{post.content}</p>
