                       <span className="flex items-center gap-1.5"><MessageCircle size={14} className="text-blue-500" /> {post.comments.length}</span>
                    </div>
                  </motion.div>
                ))}
                {(activeTab === 'Posts' ? myPosts : myReposts).length === 0 && (
                  <div className="col-span-2 py-24 text-center opacity-20 font-black uppercase italic tracking-widest">
