            <motion.div initial={{ scale: 0.9, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} className="bg-[#111111] w-full max-w-xl rounded-[3rem] p-6 md:p-10 shadow-2xl border-4 border-[#e21b3c]/20 overflow-y-auto max-h-[90vh] custom-scrollbar">
              <div className="flex justify-between items-center mb-8">
                <h3 className="text-2xl md:text-3xl font-black italic uppercase text-white">Configure ID</h3>
                <button onClick={() => setIsEditing(false)} className="text-white/40 hover:text-white"><X size={32}/></button>
