                     {JOB_TITLES.map(t => <option key={t} value={t}>{t}</option>)}
                     {currentUser.email === 'travismiguel014@gmail.com' && <option value="Creator">Creator</option>}
                   </select>
                </div>

                <div className="space-y-2">
                   <label className="text-[10px] font-black uppercase text-white/40 tracking-[0.4em] ml-2">District Color</label>
                   <div className="flex flex-wrap gap-2 md:gap-3">
                     {['#e21b3c', '#1368ce', '#26890c', '#ffa602', '#46178f', '#ec4899', '#06b6d4'].map(c => (
                       <button key={c} onClick={() => setEditForm({...editForm, profileColor: c})} className={`w-10 h-10 md:w-12 md:h-12 rounded-2xl transition-all ${editForm.profileColor === c ? 'scale-110 ring-4 ring-offset-4 ring-offset-[#111111] ring-white' : 'opacity-40 hover:opacity-100'}`} style={{ backgroundColor: c }} />
                     ))}
                   </div>
                </div>

                <button onClick={handleSave} className="w-full py-5 md:py-6 bg-[#e21b3c] text-white rounded-3xl font-black text-lg md:text-xl uppercase shadow-[0_8px_0_0_#b31530] active:translate-y-2 active:shadow-none transition-all mt-4">
                  Authorize Sync
                </button>
              </div>
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </div>
  );
};

