            >
              {tab === 'MoodPet' ? 'PET 🐾' : tab}
            </button>
          ))}
        </div>
      </div>

      <div className="flex-1 fading-scrollbar overflow-y-auto pr-1">
        <div className="pb-16">
          <AnimatePresence mode="wait">
            {subTab === 'Express' && (
              <motion.div key="express" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="space-y-6">
                <div className="flex justify-center md:justify-start">
                  <div className="flex gap-2 p-1.5 bg-[#1a1a1a] rounded-2xl border border-white/5">
                    <button onClick={() => setFeedFilter('All')} className={`px-5 py-2 rounded-xl text-[10px] font-black transition-all ${feedFilter === 'All' ? 'bg-[#222222] text-white' : 'text-white/20'}`}>ALL DISTRICTS</button>
                    <button onClick={() => setFeedFilter('Following')} className={`px-5 py-2 rounded-xl text-[10px] font-black transition-all ${feedFilter === 'Following' ? 'bg-[#222222] text-white' : 'text-white/20'}`}>MY CIRCLE</button>
                  </div>
                </div>

                <div className="p-6 md:p-8 rounded-[2.5rem] bg-[#111111] border border-white/5 shadow-2xl">
                  <textarea value={postContent} onChange={(e) => setPostContent(e.target.value)} placeholder="Transmit your emotional frequency..." className="w-full bg-[#1a1a1a] p-5 rounded-2xl border-2 border-white/5 focus:border-[#e21b3c] outline-none transition-all text-white font-bold placeholder:text-white/10" rows={3} />
                  <div className="flex justify-end mt-4">
                    <button onClick={handlePost} className="kahoot-button-red px-8 md:px-10 py-3 md:py-4 text-white rounded-2xl font-black text-xs flex items-center gap-3 active:scale-95 transition-all">
                      <Send size={18} /> BROADCAST
                    </button>
                  </div>
                </div>

                <div className="space-y-4">
                  {filteredPosts.length > 0 ? filteredPosts.map(post => (
                      <motion.div layout key={post.id} className="p-6 md:p-8 rounded-[2.5rem] bg-[#111111] border border-white/5 shadow-md">
                        <div className="flex items-center justify-between mb-6">
