                            <div className="w-12 h-12 rounded-2xl bg-slate-800 border-2 border-white/5 flex items-center justify-center text-white font-black overflow-hidden shadow-lg">
                              {post.author[0].toUpperCase()}
                            </div>
                            <div>
                              <h4 className="font-black text-sm text-white tracking-tight">@{post.author}</h4>
