                            </div>
                          </button>
                        </div>
                        <p className="text-base md:text-lg text-white font-medium mb-8 leading-relaxed">{post.content}</p>

                        <div className="flex items-center gap-6 md:gap-8 pt-6 border-t border-white/5">
                          <button onClick={() => onHeart(post.id)} className="flex items-center gap-2 text-[#e21b3c] font-black text-[10px] active:scale-125 transition-transform"><Heart size={20} fill={post.hearts > 0 ? "currentColor" : "none"} /> {post.hearts}</button>
                          <button onClick={() => setExpandedComments(expandedComments === post.id ? null : post.id)} className="flex items-center gap-2 text-blue-500 font-black text-[10px] active:scale-125 transition-transform"><MessageCircle size={20} /> {post.comments.length}</button>
                          <button onClick={() => onRepost(post)} className="flex items-center gap-2 text-green-500 font-black text-[10px] active:scale-125 transition-transform"><Repeat size={20} /> ECHO</button>
                        </div>
                      </motion.div>
                  )) : (
                    <div className="py-24 text-center opacity-20 font-black uppercase italic text-xs tracking-[0.5em]">No transmissions detected</div>
                  )}
                </div>
              </motion.div>
            )}

            {subTab === 'MoodPet' && (
              <motion.div key="pet" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="h-full">
                <MoodPetSection user={user} isDarkMode={true} onUpdate={onUpdatePet} onPost={onPost} />
              </motion.div>
            )}

            {subTab === 'Teller' && (
              <motion.div key="teller" initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="flex flex-col items-center justify-center p-8 md:p-12 text-center bg-[#111111] rounded-[3rem] border border-white/5 shadow-2xl relative overflow-hidden">
                <div className="absolute top-[-20%] left-[-20%] w-[60%] h-[60%] bg-[#46178f]/10 blur-[120px] rounded-full"></div>
                <motion.div animate={{ scale: [1, 1.1, 1], rotate: isTellerLoading ? 360 : 0 }} transition={{ repeat: Infinity, duration: 2 }} className="mb-10 text-8xl md:text-9xl select-none drop-shadow-2xl">🔮</motion.div>
                <h3 className="text-3xl md:text-5xl font-black italic uppercase text-white mb-4 tracking-tighter">Mystic Teller</h3>
                <p className="text-xs text-white/40 mb-10 max-w-sm font-bold uppercase tracking-[0.3em]">Ask the spirits of Mooderia</p>

                <div className="w-full max-w-lg space-y-6">
                  <input type="text" value={tellerQuestion} onChange={e => setTellerQuestion(e.target.value)} placeholder="Will the stars align for me?" className="w-full bg-[#1a1a1a] p-6 rounded-[2rem] border-4 border-white/5 outline-none font-black text-xl text-white placeholder:text-white/10 focus:border-[#46178f] transition-all shadow-inner" />
                  <button onClick={handleTeller} disabled={isTellerLoading} className="kahoot-button-purple w-full p-6 rounded-[2rem] text-white font-black uppercase text-xl shadow-xl active:translate-y-2 transition-all">CONSULT THE VOID</button>
                </div>

                {tellerResponse && (
                  <motion.div initial={{ scale: 0.9, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} className="mt-12 p-8 md:p-10 rounded-[2.5rem] bg-[#1a1a1a] border-2 border-white/5 max-w-md w-full shadow-2xl">
                    <p className="text-2xl md:text-3xl font-black italic text-[#46178f] uppercase mb-4 tracking-tighter">{tellerResponse.split('.')[0]}</p>
                    <p className="text-sm md:text-lg font-bold text-white/80 leading-snug italic opacity-80">{tellerResponse.split('.').slice(1).join('.')}</p>
                  </motion.div>
                )}
              </motion.div>
            )}

            {subTab === 'Quiz' && (
              <motion.div key="quiz" initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="h-full">
                {!quizActive ? (
                  <div className="flex flex-col items-center justify-center text-center p-8 md:p-12 bg-[#111111] rounded-[3rem] border border-white/5 shadow-2xl">
                    <div className="w-20 md:w-24 h-20 md:h-24 bg-[#46178f]/20 rounded-3xl flex items-center justify-center mb-10 border-2 border-[#46178f]/30">
                      <Brain className="text-[#46178f]" size={56} />
