                    <h3 className="text-3xl md:text-5xl font-black italic uppercase mb-4 tracking-tighter text-white">Mind Palace Quiz</h3>
                    <p className="text-xs text-white/40 mb-12 max-w-xs font-bold uppercase tracking-widest leading-relaxed text-center">Demonstrate your Mooderia expertise</p>
                    <button onClick={startQuiz} className="kahoot-button-green px-12 md:px-16 py-5 md:py-6 rounded-3xl text-white font-black text-xl md:text-2xl uppercase active:scale-95 transition-all">START ASSESSMENT</button>
                  </div>
                ) : quizFinished ? (
                  <div className="flex flex-col items-center justify-center text-center p-8 md:p-12 bg-[#111111] rounded-[3rem] shadow-xl border border-white/5">
                    <Trophy className="text-[#ffa602] mb-10" size={96} />
                    <h3 className="text-3xl md:text-4xl font-black italic uppercase mb-2 tracking-tighter text-white">Evaluation Complete</h3>
                    <p className="text-2xl md:text-3xl font-black mb-10 text-[#ffa602]">{quizScore}/5 CORRECT</p>
