                  <div className="max-w-2xl mx-auto py-10 md:py-12 px-6 md:px-10 bg-[#111111] rounded-[3.5rem] shadow-2xl border border-white/5">
                    <div className="flex justify-between items-center mb-12">
                      <span className="text-[9px] md:text-[10px] font-black uppercase text-[#e21b3c] tracking-[0.4em] italic">Assessment {quizStep + 1} / 5</span>
