import React, { useState, useMemo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Heart, Star, Zap, ChevronRight } from 'lucide-react';
import { ZODIACS, getZodiacFromDate } from '../constants';
import { getHoroscope, getLovePrediction, getPlanetaryInsights } from '../services/geminiService';

interface ZodiacSectionProps {
  isDarkMode: boolean;
}

type ZodiacTab = 'LoveMatcher' | 'Horoscope' | 'Almanac' | 'LuckyDay';

const MONTHS = [
  "January", "February", "March", "April", "May", "June",
  "July", "August", "September", "October", "November", "December"
];

const ZodiacSection: React.FC<ZodiacSectionProps> = ({ isDarkMode }) => {
  const [tab, setTab] = useState<ZodiacTab>('LoveMatcher');

  // Love Matcher State
  const [m1, setM1] = useState(1);
  const [d1, setD1] = useState(1);
  const [m2, setM2] = useState(1);
  const [d2, setD2] = useState(1);

  const [matchResult, setMatchResult] = useState<{ percentage: number, reason: string } | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [horoscope, setHoroscope] = useState<{ sign: string, text: string } | null>(null);
  const [selectedAlmanac, setSelectedAlmanac] = useState(ZODIACS[0]);
  const [luckyZodiac, setLuckyZodiac] = useState(ZODIACS[0].name);

  const handleMatch = async () => {
    setIsLoading(true);
    const sign1 = getZodiacFromDate(m1, d1);
    const sign2 = getZodiacFromDate(m2, d2);
    try {
      const result = await getLovePrediction(sign1, sign2);
      setMatchResult(result);
    } catch (e) {
      setMatchResult({ percentage: 75, reason: "The stars suggest a strong bond, despite minor friction in the outer orbits." });
    } finally {
      setIsLoading(false);
    }
  };

  const handleHoroscope = async (sign: string) => {
    setIsLoading(true);
    try {
      const res = await getHoroscope(sign);
      setHoroscope({ sign, text: res || 'Consulting stars...' });
    } catch (e) {
      setHoroscope({ sign, text: "A mercury retrograde has blocked the transmission." });
    } finally {
      setIsLoading(false);
    }
  };

  const getLuckyData = (sign: string) => {
    const today = new Date().toDateString();
    const seed = sign + today;
    let hash = 0;
    for (let i = 0; i < seed.length; i++) hash = seed.charCodeAt(i) + ((hash << 5) - hash);
    const colors = ["Ruby Red", "Emerald Green", "Azure Blue", "Goldenrod", "Purple", "Teal", "Rose Pink"];
    const phrases = ["Great opportunities await in social hubs.", "Focus on self-care today.", "Your creative energy is peaking.", "A surprise connection might occur."];
    return { color: colors[Math.abs(hash) % colors.length], number: (Math.abs(hash) % 99) + 1, phrase: phrases[Math.abs(hash) % phrases.length] };
  };

  const currentLucky = useMemo(() => getLuckyData(luckyZodiac), [luckyZodiac]);

  const DayPicker = ({ val, setVal }: { val: number, setVal: (v: number) => void }) => (
    <select value={val} onChange={(e) => setVal(parseInt(e.target.value))} className="flex-1 bg-[#1a1a1a] p-3 md:p-4 rounded-xl font-black border-2 border-white/5 text-[10px] md:text-xs text-white outline-none focus:border-[#26890c]">
      {Array.from({ length: 31 }, (_, i) => i + 1).map(d => <option key={d} value={d}>{d}</option>)}
    </select>
  );

  const MonthPicker = ({ val, setVal }: { val: number, setVal: (v: number) => void }) => (
    <select value={val} onChange={(e) => setVal(parseInt(e.target.value))} className="flex-1 bg-[#1a1a1a] p-3 md:p-4 rounded-xl font-black border-2 border-white/5 text-[10px] md:text-xs text-white outline-none focus:border-[#26890c]">
      {MONTHS.map((m, i) => <option key={m} value={i + 1}>{m}</option>)}
    </select>
  );

  return (
    <div className="flex flex-col h-full overflow-hidden">
      {/* Tabs */}
      <div className="flex gap-2 pb-6 shrink-0 overflow-x-auto no-scrollbar scroll-smooth">
        {['LoveMatcher', 'Horoscope', 'Almanac', 'LuckyDay'].map((t) => (
          <button
            key={t}
            onClick={() => setTab(t as ZodiacTab)}
            className={`px-6 md:px-8 py-2.5 md:py-3 rounded-full font-black text-[10px] md:text-xs transition-all whitespace-nowrap uppercase tracking-tighter border-b-4 ${tab === t ? 'bg-[#26890c] border-[#1c6409] text-white shadow-xl' : 'bg-[#1a1a1a] border-black text-white/30 hover:text-white/60'}`}
          >
            {t.replace(/([A-Z])/g, ' $1').trim()}
          </button>
        ))}
      </div>

      <div className="flex-1 fading-scrollbar overflow-y-auto pr-1">
        <div className="pb-16">
          <AnimatePresence mode="wait">
            {tab === 'LoveMatcher' && (
              <motion.div key="love" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="p-8 md:p-10 rounded-[3rem] bg-[#111111] border border-white/5 shadow-2xl text-center">
                <Heart className="mx-auto mb-8 text-[#e21b3c] animate-pulse" size={64} />
                <h2 className="text-3xl md:text-5xl font-black mb-10 md:mb-12 uppercase italic tracking-tighter text-white">Love Matcher</h2>

                <div className="grid grid-cols-1 md:grid-cols-3 items-center gap-6 md:gap-10 mb-10 md:mb-12 max-w-2xl mx-auto">
                  <div className="space-y-4">
                    <p className="text-[10px] font-black uppercase text-white/30 tracking-[0.4em]">Citizen A</p>
                    <div className="flex gap-2"><MonthPicker val={m1} setVal={setM1} /><DayPicker val={d1} setVal={setD1} /></div>
                  </div>
                  <div className="text-4xl md:text-5xl font-black text-[#e21b3c] select-none">&hearts;</div>
                  <div className="space-y-4">
                    <p className="text-[10px] font-black uppercase text-white/30 tracking-[0.4em]">Citizen B</p>
                    <div className="flex gap-2"><MonthPicker val={m2} setVal={setM2} /><DayPicker val={d2} setVal={setD2} /></div>
