                    <h4 className="text-lg md:text-xl font-black text-[#ffa602] uppercase italic mb-4 tracking-widest">{horoscope.sign} Insight</h4>
                    <p className="text-sm md:text-base font-bold text-white leading-relaxed italic opacity-90">{horoscope.text}</p>
                  </motion.div>
                )}
              </motion.div>
