import React, { useState, useEffect, useMemo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { User, Mood, Section, Post, Comment, Message, Notification } from './types';
import Sidebar from './components/Sidebar';
import MoodCheckIn from './components/MoodCheckIn';
import HomeSection from './sections/HomeSection';
import MoodSection from './sections/MoodSection';
import ZodiacSection from './sections/ZodiacSection';
import CityHallSection from './sections/CityHallSection';
import ProfileSection from './sections/ProfileSection';
import SettingsSection from './sections/SettingsSection';
import NotificationsSection from './sections/NotificationsSection';
import AuthScreen from './sections/AuthScreen';
import LoadingScreen from './components/LoadingScreen';
import { getExpNeeded, MOOD_SCORES, getTier } from './constants';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [activeSection, setActiveSection] = useState<Section>('Home');
  const [viewingUsername, setViewingUsername] = useState<string | null>(null);
  const [isMoodModalOpen, setIsMoodModalOpen] = useState(false);
  const [isDarkMode, setIsDarkMode] = useState(false); // Default to Light Mode
  const [isAppStarting, setIsAppStarting] = useState(true);

  const [allPosts, setAllPosts] = useState<Post[]>([]);
  const [allMessages, setAllMessages] = useState<Message[]>([]);
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);

  useEffect(() => {
    const savedUser = localStorage.getItem('mooderia_user');
    const savedPosts = localStorage.getItem('mooderia_posts') || '[]';
    const savedMessages = localStorage.getItem('mooderia_messages') || '[]';
    const savedNotifications = localStorage.getItem('mooderia_notifications') || '[]';
    const savedTheme = localStorage.getItem('mooderia_theme');

    if (savedUser) {
      let user: User = JSON.parse(savedUser);
      const todayStr = new Date().toDateString();

      // Mandatory Daily Mood Check-in check on open
      if (user.lastMoodDate !== todayStr) {
        setIsMoodModalOpen(true);
      }

      setCurrentUser(user);
    }

    setAllPosts(JSON.parse(savedPosts));
    setAllMessages(JSON.parse(savedMessages));
    setNotifications(JSON.parse(savedNotifications));
    if (savedTheme === 'dark') setIsDarkMode(true);
    setIsLoaded(true);

    const timer = setTimeout(() => setIsAppStarting(false), 2000);
    return () => clearTimeout(timer);
  }, []);

  useEffect(() => {
    if (!isLoaded) return;
    if (currentUser) {
      localStorage.setItem('mooderia_user', JSON.stringify(currentUser));
      const allUsers: User[] = JSON.parse(localStorage.getItem('mooderia_all_users') || '[]');
      const idx = allUsers.findIndex(u => u.email === currentUser.email);
      if (idx > -1) {
        allUsers[idx] = currentUser;
        localStorage.setItem('mooderia_all_users', JSON.stringify(allUsers));
      }
    }
    localStorage.setItem('mooderia_posts', JSON.stringify(allPosts));
    localStorage.setItem('mooderia_messages', JSON.stringify(allMessages));
    localStorage.setItem('mooderia_notifications', JSON.stringify(notifications));
    localStorage.setItem('mooderia_theme', isDarkMode ? 'dark' : 'light');
  }, [currentUser, allPosts, allMessages, notifications, isDarkMode, isLoaded]);

  const handleEditProfile = (displayName: string, username: string, profilePic?: string, title?: string, bannerPic?: string, profileColor?: string, bio?: string) => {
    if (!currentUser) return;
    let finalTitle = title || currentUser.title;
    if (finalTitle === 'Creator' && currentUser.email !== 'travismiguel014@gmail.com') finalTitle = 'Citizen';

    const updatedUser = {
      ...currentUser,
      displayName,
      username,
      profilePic: profilePic || currentUser.profilePic,
      title: finalTitle,
      profileColor: profileColor || currentUser.profileColor,
      bio: bio || currentUser.bio
    };

    setCurrentUser(updatedUser);
  };

  const updatePetStats = (hunger: number, thirst: number, rest: number, coins: number, exp: number = 0, sleepUntil: number | null = null, newEmoji?: string, markChosen?: boolean) => {
    if (!currentUser) return;
    let newLevel = currentUser.petLevel;
    let newExp = currentUser.petExp + exp;
    while (newExp >= getExpNeeded(newLevel)) {
      newExp -= getExpNeeded(newLevel);
      newLevel += 1;
    }
    setCurrentUser({
      ...currentUser,
      petHunger: Math.min(100, Math.max(0, currentUser.petHunger + hunger)),
      petThirst: Math.min(100, Math.max(0, currentUser.petThirst + thirst)),
      petRest: Math.min(100, Math.max(0, currentUser.petRest + rest)),
      petExp: newExp,
      petLevel: newLevel,
      moodCoins: currentUser.moodCoins + coins,
      petSleepUntil: sleepUntil !== undefined ? sleepUntil : currentUser.petSleepUntil,
      petEmoji: newEmoji || currentUser.petEmoji,
      petHasBeenChosen: markChosen !== undefined ? markChosen : currentUser.petHasBeenChosen,
      petLastUpdate: Date.now()
    });
  };

  if (isAppStarting) return <LoadingScreen />;
  if (!currentUser) return <AuthScreen onLogin={setCurrentUser} />;

  return (
    <div className={`h-screen max-h-screen overflow-hidden flex flex-col md:flex-row ${isDarkMode ? 'bg-[#0f0f0f] text-white' : 'bg-[#f7f8fa] text-slate-900'} transition-colors duration-300`}>
      <AnimatePresence>
        {isMoodModalOpen && (
          <MoodCheckIn 
            onSubmit={(m) => {
              const today = new Date().toDateString();
              setCurrentUser({
                ...currentUser,
                moodStreak: currentUser.lastMoodDate === today ? currentUser.moodStreak : (currentUser.moodStreak || 0) + 1,
                lastMoodDate: today,
                moodHistory: [...(currentUser.moodHistory || []), { date: today, mood: m, score: MOOD_SCORES[m || 'Normal'] }]
              });
              setIsMoodModalOpen(false);
            }} 
            isDarkMode={isDarkMode} 
          />
        )}
      </AnimatePresence>
      <Sidebar 
        activeSection={activeSection} 
        onNavigate={(s) => { setActiveSection(s); if(s === 'Profile') setViewingUsername(currentUser.username); }} 
        isDarkMode={isDarkMode} 
        user={currentUser} 
        unreadMessages={allMessages.filter(m => m.recipient === currentUser.username && !m.read).length} 
        unreadNotifications={notifications.filter(n => !n.read).length} 
      />
      <main className="flex-1 flex flex-col relative pt-16 pb-20 md:pt-0 md:pb-0 h-full overflow-hidden">
        <div className="flex-1 overflow-y-auto fading-scrollbar p-4 md:p-8">
          <motion.div 
            key={activeSection + (activeSection === 'Profile' ? viewingUsername : '')} 
            initial={{ opacity: 0, y: 10 }} 
            animate={{ opacity: 1, y: 0 }} 
            className="max-w-5xl mx-auto"
          >
            {activeSection === 'Home' && <HomeSection user={currentUser} posts={allPosts} isDarkMode={isDarkMode} />}
            {activeSection === 'Mood' && <MoodSection user={currentUser} posts={allPosts.filter(p => !currentUser.blockedUsers.includes(p.author))} onPost={(c) => setAllPosts([{id: Math.random().toString(36).substr(2, 9), author: currentUser.username, content: c, hearts: 0, comments: [], timestamp: Date.now()}, ...allPosts])} onHeart={(pid) => setAllPosts(prev => prev.map(p => p.id === pid ? {...p, hearts: p.hearts + 1} : p))} onComment={(pid, t) => setAllPosts(prev => prev.map(p => p.id === pid ? {...p, comments: [...p.comments, {id: Math.random().toString(36).substr(2,9), author: currentUser.username, text: t, replies: []}]} : p))} onRepost={(p) => setAllPosts([{ ...p, id: Math.random().toString(36).substr(2, 9), author: currentUser.username, isRepost: true, originalAuthor: p.author, timestamp: Date.now() }, ...allPosts])} onFollow={(u) => {const isF = currentUser.following.includes(u); setCurrentUser({...currentUser, following: isF ? currentUser.following.filter(f => f !== u) : [...currentUser.following, u]});}} onBlock={(u) => {if(!currentUser.blockedUsers.includes(u)) setCurrentUser({...currentUser, blockedUsers: [...currentUser.blockedUsers, u]}); setActiveSection('Home');}} isDarkMode={isDarkMode} onNavigateToProfile={(u) => {setViewingUsername(u); setActiveSection('Profile');}} onUpdatePet={updatePetStats} />}
            {activeSection === 'Zodiac' && <ZodiacSection isDarkMode={isDarkMode} />}
            {activeSection === 'CityHall' && <CityHallSection isDarkMode={isDarkMode} currentUser={currentUser} messages={allMessages} onSendMessage={(r, t) => setAllMessages([...allMessages, {id: Math.random().toString(36).substr(2, 9), sender: currentUser.username, recipient: r, text: t, timestamp: Date.now(), read: false}])} onReadMessages={(u) => setAllMessages(allMessages.map(m => (m.recipient === currentUser.username && m.sender === u) ? {...m, read: true} : m))} onNavigateToProfile={(u) => {setViewingUsername(u); setActiveSection('Profile');}} />}
            {activeSection === 'Notifications' && <NotificationsSection notifications={notifications} isDarkMode={isDarkMode} onMarkRead={() => setNotifications(notifications.map(n => ({...n, read: true})))} />}
            {activeSection === 'Profile' && profileToView && <ProfileSection user={profileToView} allPosts={allPosts} isDarkMode={isDarkMode} onEditProfile={handleEditProfile} onBlock={(u) => {if(!currentUser.blockedUsers.includes(u)) setCurrentUser({...currentUser, blockedUsers: [...currentUser.blockedUsers, u]}); setActiveSection('Home');}} onFollow={(u) => {const isF = currentUser.following.includes(u); setCurrentUser({...currentUser, following: isF ? currentUser.following.filter(f => f !== u) : [...currentUser.following, u]});}} currentUser={currentUser} onShareToExpress={(c) => setAllPosts([{id: Math.random().toString(36).substr(2, 9), author: currentUser.username, content: c, hearts: 0, comments: [], timestamp: Date.now()}, ...allPosts])} />}
            {activeSection === 'Settings' && <SettingsSection isDarkMode={isDarkMode} onToggleDarkMode={() => setIsDarkMode(!isDarkMode)} onLogout={() => {localStorage.removeItem('mooderia_user'); setCurrentUser(null);}} user={currentUser} onUnblock={(u) => setCurrentUser({...currentUser, blockedUsers: currentUser.blockedUsers.filter(b => b !== u)})} />}
          </motion.div>
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Heart, MessageCircle, Repeat, Send, Sparkles, Brain, Wind, ShoppingBag, Gamepad2, Bed, Lock, Coins, Ghost, QuestionMark, Zap, Calculator, Target, Trophy } from 'lucide-react';
import { User, Post, Mood, Comment } from '../types';
import MoodPetSection from './MoodPetSection';
import { getTellerResponse } from '../services/geminiService';

interface MoodSectionProps {
  user: User;
  posts: Post[];
  onPost: (content: string) => void;
  onHeart: (postId: string) => void;
  onComment: (postId: string, text: string) => void;
  onRepost: (post: Post) => void;
  onFollow: (username: string) => void;
  onBlock: (username: string) => void;
  isDarkMode: boolean;
  onNavigateToProfile: (username: string) => void;
  onUpdatePet: (hunger: number, thirst: number, rest: number, coins: number, exp?: number, sleepUntil?: number | null, newEmoji?: string, markChosen?: boolean) => void;
}

type MoodSubTab = 'Express' | 'Teller' | 'Quiz' | 'MoodPet';

const MOOD_QUIZ = [
  { q: "Which of these emojis best represents an 'Angry' mood?", options: ["😐", "😡", "😴", "✨"], a: 1 },
  { q: "If someone is 'Flaming', which color would they likely be associated with?", options: ["Blue", "Yellow", "Red", "Green"], a: 2 },
  { q: "A 'Wonderful' mood represents what score in Mooderia?", options: ["50", "0", "100", "70"], a: 2 },
  { q: "Which emoji is 'Excited'?", options: ["🤩", "😐", "😴", "😊"], a: 0 },
  { q: "Which feeling is associated with a score of 15?", options: ["Happy", "Angry", "Tired", "Normal"], a: 1 },
];

const MoodSection: React.FC<MoodSectionProps> = ({ user, posts, onPost, onHeart, onComment, onRepost, onFollow, onBlock, isDarkMode, onNavigateToProfile, onUpdatePet }) => {
  const [subTab, setSubTab] = useState<MoodSubTab>('Express');
  const [postContent, setPostContent] = useState('');
  const [feedFilter, setFeedFilter] = useState<'All' | 'Following'>('All');

  // Teller State
  const [tellerQuestion, setTellerQuestion] = useState('');
  const [tellerResponse, setTellerResponse] = useState('');
  const [isTellerLoading, setIsTellerLoading] = useState(false);

  // Quiz State
  const [quizActive, setQuizActive] = useState(false);
  const [quizStep, setQuizStep] = useState(0);
  const [quizScore, setQuizScore] = useState(0);
  const [quizFinished, setQuizFinished] = useState(false);

  const startQuiz = () => {
    setQuizActive(true);
    setQuizStep(0);
    setQuizScore(0);
    setQuizFinished(false);
  };

  const handleQuizAnswer = (idx: number) => {
    if (idx === MOOD_QUIZ[quizStep].a) setQuizScore(s => s + 1);
    if (quizStep < MOOD_QUIZ.length - 1) {
      setQuizStep(s => s + 1);
    } else {
      setQuizFinished(true);
      onUpdatePet(0, 0, 0, quizScore * 20, quizScore * 50);
    }
  };

  const handleTeller = async () => {
    if (!tellerQuestion.trim()) return;
    setIsTellerLoading(true);
    setTellerResponse('');
    try {
      const res = await getTellerResponse(tellerQuestion);
      setTellerResponse(res || 'The cosmic fog obscures my vision...');
    } catch (e) {
      setTellerResponse('MAYBE. The spirits are currently in a meeting.');
    } finally {
      setIsTellerLoading(false);
    }
  };

  const filteredPosts = feedFilter === 'All' 
    ? posts 
    : posts.filter(p => user.following.includes(p.author) || p.author === user.username);

  return (
    <div className="flex flex-col gap-8 pb-10">
      {/* Tabs Header - Zodiac Style Buttons */}
      <div className="flex gap-2 overflow-x-auto no-scrollbar pb-2">
        {(['Express', 'Teller', 'Quiz', 'MoodPet'] as MoodSubTab[]).map((t) => (
          <button
            key={t}
            onClick={() => setSubTab(t)}
            className={`px-8 py-3 rounded-full font-black text-xs transition-all whitespace-nowrap uppercase tracking-tighter border-b-4 ${subTab === t ? 'bg-[#e21b3c] border-[#b31530] text-white shadow-xl' : isDarkMode ? 'bg-[#1a1a1a] border-black text-white/30' : 'bg-gray-200 border-gray-300 text-slate-500'}`}
          >
            {t === 'MoodPet' ? 'Mood Pet 🐾' : t}
          </button>
        ))}
      </div>

      <AnimatePresence mode="wait">
        {subTab === 'Express' && (
          <motion.div key="express" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="space-y-6">
            <div className={`p-6 md:p-8 rounded-[2.5rem] ${isDarkMode ? 'bg-[#111111]' : 'bg-white'} border border-black/5 shadow-2xl`}>
              <textarea value={postContent} onChange={(e) => setPostContent(e.target.value)} placeholder="Transmit your emotional frequency..." className={`w-full ${isDarkMode ? 'bg-[#1a1a1a] text-white' : 'bg-gray-50 text-slate-900'} p-5 rounded-2xl border-2 border-black/5 focus:border-[#e21b3c] outline-none transition-all font-bold placeholder:opacity-30`} rows={3} />
              <div className="flex justify-between items-center mt-4">
                <div className="flex gap-2">
                  <button onClick={() => setFeedFilter('All')} className={`px-4 py-2 rounded-xl text-[10px] font-black ${feedFilter === 'All' ? 'bg-[#e21b3c] text-white' : 'opacity-40'}`}>ALL DISTRICTS</button>
                  <button onClick={() => setFeedFilter('Following')} className={`px-4 py-2 rounded-xl text-[10px] font-black ${feedFilter === 'Following' ? 'bg-[#e21b3c] text-white' : 'opacity-40'}`}>MY CIRCLE</button>
                </div>
                <button onClick={() => {onPost(postContent); setPostContent('');}} className="kahoot-button-red px-10 py-4 text-white rounded-2xl font-black text-xs flex items-center gap-3">
                  <Send size={18} /> BROADCAST
                </button>
              </div>
            </div>

            <div className="space-y-4">
              {filteredPosts.map(post => (
                  <div key={post.id} className={`p-6 md:p-8 rounded-[2.5rem] ${isDarkMode ? 'bg-[#111111] text-white' : 'bg-white text-slate-900'} border border-black/5 shadow-md`}>
                    <div className="flex items-center gap-4 mb-6">
                      <div className="w-12 h-12 rounded-2xl bg-indigo-500 flex items-center justify-center text-white font-black overflow-hidden shadow-lg">
                        {post.author[0].toUpperCase()}
                      </div>
                      <h4 className="font-black text-sm tracking-tight">@{post.author}</h4>
                    </div>
                    <p className="text-base md:text-lg font-medium mb-8 leading-relaxed">{post.content}</p>
                    <div className="flex items-center gap-8 pt-6 border-t border-black/5">
                      <button onClick={() => onHeart(post.id)} className="flex items-center gap-2 text-[#e21b3c] font-black text-[10px]"><Heart size={20} fill={post.hearts > 0 ? "currentColor" : "none"} /> {post.hearts}</button>
                      <button onClick={() => onRepost(post)} className="flex items-center gap-2 text-green-500 font-black text-[10px]"><Repeat size={20} /> ECHO</button>
                    </div>
                  </div>
              ))}
            </div>
          </motion.div>
        )}

        {subTab === 'MoodPet' && (
          <motion.div key="pet" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}>
            <MoodPetSection user={user} isDarkMode={isDarkMode} onUpdate={onUpdatePet} onPost={onPost} />
          </motion.div>
        )}

        {subTab === 'Teller' && (
          <motion.div key="teller" initial={{ opacity: 0 }} animate={{ opacity: 1 }} className={`flex flex-col items-center justify-center p-12 text-center ${isDarkMode ? 'bg-[#111111]' : 'bg-white'} rounded-[3rem] border border-black/5 shadow-2xl relative overflow-hidden`}>
