            </div>
            {tellerResponse && (
              <motion.div initial={{ scale: 0.9, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} className={`mt-12 p-10 rounded-[2.5rem] ${isDarkMode ? 'bg-[#1a1a1a] text-white' : 'bg-indigo-50 text-indigo-900'} border-2 border-black/5 max-w-md w-full shadow-2xl`}>
                <p className="text-3xl font-black italic uppercase mb-4 tracking-tighter">{tellerResponse.split('.')[0]}</p>
                <p className="text-base font-bold leading-snug italic opacity-80">{tellerResponse.split('.').slice(1).join('.')}</p>
              </motion.div>
            )}
          </motion.div>
        )}

        {subTab === 'Quiz' && (
          <motion.div key="quiz" initial={{ opacity: 0 }} animate={{ opacity: 1 }}>
            {!quizActive ? (
              <div className={`flex flex-col items-center justify-center text-center p-12 ${isDarkMode ? 'bg-[#111111]' : 'bg-white'} rounded-[3rem] border border-black/5 shadow-2xl`}>
                <Brain className="text-[#46178f] mb-10" size={80} />
                <h3 className={`text-3xl md:text-5xl font-black italic uppercase mb-4 tracking-tighter ${isDarkMode ? 'text-white' : 'text-slate-900'}`}>Mood Reading Quiz</h3>
                <p className="text-xs opacity-40 mb-12 max-w-xs font-bold uppercase tracking-widest leading-relaxed">Can you identify the emotions correctly?</p>
                <button onClick={startQuiz} className="kahoot-button-green px-16 py-6 rounded-3xl text-white font-black text-2xl uppercase">START TEST</button>
              </div>
            ) : quizFinished ? (
              <div className={`flex flex-col items-center justify-center text-center p-12 ${isDarkMode ? 'bg-[#111111]' : 'bg-white'} rounded-[3rem] shadow-xl border border-black/5`}>
                <Trophy className="text-[#ffa602] mb-10" size={96} />
                <h3 className={`text-4xl font-black italic uppercase mb-2 tracking-tighter ${isDarkMode ? 'text-white' : 'text-slate-900'}`}>Results</h3>
                <p className="text-3xl font-black mb-10 text-[#ffa602]">{quizScore}/5 CORRECT</p>
                <button onClick={startQuiz} className="kahoot-button-blue px-12 py-5 rounded-2xl text-white font-black text-xl uppercase shadow-lg">RETAKE</button>
              </div>
            ) : (
              <div className={`max-w-2xl mx-auto py-12 px-10 ${isDarkMode ? 'bg-[#111111]' : 'bg-white'} rounded-[3.5rem] shadow-2xl border border-black/5`}>
                <div className="flex justify-between items-center mb-12">
                  <span className="text-[10px] font-black uppercase text-[#e21b3c] tracking-[0.4em] italic">Mood Reading {quizStep + 1} / 5</span>
                  <div className="w-32 h-3 bg-gray-100 rounded-full overflow-hidden">
                    <motion.div initial={{ width: 0 }} animate={{ width: `${(quizStep + 1) * 20}%` }} className="h-full bg-[#e21b3c]" />
                  </div>
                </div>
                <h4 className={`text-2xl md:text-3xl font-black italic mb-12 leading-tight tracking-tight text-center ${isDarkMode ? 'text-white' : 'text-slate-900'}`}>{MOOD_QUIZ[quizStep].q}</h4>
