const MoodPetSection: React.FC<MoodPetSectionProps> = ({ user, isDarkMode, onUpdate, onPost }) => {
  const [activeTab, setActiveTab] = useState<'Interaction' | 'Shop' | 'Games'>('Interaction');
  const [gameMode, setGameMode] = useState<string | null>(null);
  const [showEmojiPicker, setShowEmojiPicker] = useState(false);
  const [petting, setPetting] = useState(false);

  // Memory Game State
  const [cards, setCards] = useState<{ id: number, emoji: string, flipped: boolean, matched: boolean }[]>([]);
  const [flippedIds, setFlippedIds] = useState<number[]>([]);

  // Flappy Bird State
  const [birdY, setBirdY] = useState(150);
  const [score, setScore] = useState(0);
  const [isPlaying, setIsPlaying] = useState(false);

  const startMemory = () => {
    const emojis = ['🍎', '🍌', '🍒', '🍇', '🍉', '🥝'];
    const deck = [...emojis, ...emojis]
      .sort(() => Math.random() - 0.5)
      .map((e, i) => ({ id: i, emoji: e, flipped: false, matched: false }));
    setCards(deck);
    setFlippedIds([]);
    setGameMode('memory');
  };

  const flipCard = (id: number) => {
    if (flippedIds.length === 2 || cards[id].flipped || cards[id].matched) return;
    const newCards = [...cards];
    newCards[id].flipped = true;
    setCards(newCards);
    setFlippedIds([...flippedIds, id]);

    if (flippedIds.length === 1) {
      const first = flippedIds[0];
      if (cards[first].emoji === cards[id].emoji) {
        newCards[first].matched = true;
        newCards[id].matched = true;
        setCards(newCards);
        setFlippedIds([]);
        if (newCards.every(c => c.matched)) {
          setTimeout(() => {
            onUpdate(-5, -5, -5, 50, 40);
            setGameMode(null);
          }, 1000);
        }
      } else {
        setTimeout(() => {
          newCards[first].flipped = false;
          newCards[id].flipped = false;
          setCards(newCards);
          setFlippedIds([]);
        }, 1000);
      }
    }
  };

  const handlePet = () => {
    if (user.petRest < 5) return;
    setPetting(true);
    onUpdate(0, 0, -2, 2, 5);
    setTimeout(() => setPetting(false), 800);
