  return (
    <div className="flex flex-col gap-6">
      <div className={`p-8 rounded-[3rem] ${isDarkMode ? 'bg-[#111111] text-white' : 'bg-white text-slate-900'} border border-black/5 shadow-2xl flex flex-col items-center justify-center relative overflow-hidden`}>
        <div className="absolute top-6 left-6 flex items-center gap-2 bg-yellow-400 px-4 py-2 rounded-2xl text-white font-black text-xs shadow-lg">
          <Coins size={16}/> {user.moodCoins}
        </div>
        <button onClick={() => setShowEmojiPicker(true)} className="absolute top-6 right-6 p-3 bg-indigo-500 text-white rounded-2xl font-black text-xs shadow-lg hover:scale-110 active:scale-95 transition-all">
          <Wand2 size={18}/>
        </button>

        <motion.div 
          animate={petting ? { scale: [1, 1.2, 1], rotate: [0, 5, -5, 0] } : { y: [0, -10, 0] }}
          transition={petting ? { duration: 0.3 } : { duration: 4, repeat: Infinity }}
          className="text-[120px] md:text-[140px] my-10 select-none flex items-center justify-center cursor-pointer active:scale-90 transition-transform"
          onClick={handlePet}
        >
          {user.petEmoji}
          {petting && <motion.div initial={{ opacity: 0, scale: 0 }} animate={{ opacity: 1, scale: 1.5 }} className="absolute text-red-500"><Heart fill="currentColor" size={40}/></motion.div>}
        </motion.div>

