             </div>
           ))}
        </div>
      </div>

      <div className="flex gap-2">
        {(['Interaction', 'Shop', 'Games'] as const).map(tab => (
          <button key={tab} onClick={() => setActiveTab(tab)} className={`flex-1 py-4 rounded-2xl font-black text-[10px] uppercase border-b-4 transition-all ${activeTab === tab ? 'bg-[#1368ce] border-[#0e4c99] text-white shadow-lg' : isDarkMode ? 'bg-[#111111] border-black text-white/30' : 'bg-white border-gray-100 text-slate-500'}`}>{tab}</button>
        ))}
      </div>

      <div className="grid grid-cols-2 md:grid-cols-3 gap-4 pb-20">
        {activeTab === 'Shop' && ITEMS.map(item => (
          <button key={item.id} onClick={() => { if(checkCoins(item.cost)) onUpdate(item.type === 'hunger' ? item.fill : 0, item.type === 'thirst' ? item.fill : 0, 0, -item.cost, 10); }} className={`p-6 rounded-[2rem] border-2 border-black/5 flex flex-col items-center justify-center text-center gap-2 ${isDarkMode ? 'bg-[#111111] text-white' : 'bg-white text-slate-900'} shadow-md`}>
            <span className="text-4xl">{item.emoji}</span>
            <span className="text-[10px] font-black uppercase opacity-40">{item.name}</span>
            <div className="bg-yellow-400 text-white px-3 py-1 rounded-xl text-[10px] font-black flex items-center justify-center gap-1"><Coins size={12}/> {item.cost}</div>
          </button>
        ))}

        {activeTab === 'Games' && !gameMode && GAMES.map(game => (
          <button key={game.id} onClick={() => startLevelGame(game.id)} className={`p-6 rounded-[2rem] border-2 border-black/5 flex flex-col items-center justify-center text-center gap-2 ${isDarkMode ? 'bg-[#111111] text-white' : 'bg-white text-slate-900'} shadow-md transition-transform hover:scale-105`}>
            <span className="text-4xl">{game.emoji}</span>
            <span className="text-[10px] font-black uppercase opacity-40 leading-none">{game.name}</span>
            <span className="text-[8px] font-bold text-indigo-500">{game.time}s Limit</span>
          </button>
        ))}

        {gameMode && (
          <div className="col-span-full p-8 bg-indigo-500 rounded-[3rem] text-white text-center shadow-2xl relative">
             {gameResult ? (
               <div className="space-y-6">
                 <Trophy size={64} className="mx-auto text-yellow-300" />
                 <h4 className="text-3xl font-black italic uppercase">Level Complete!</h4>
                 <div className="flex justify-center gap-4">
                    <div className="bg-white/20 px-6 py-3 rounded-2xl">
                      <p className="text-[8px] font-black uppercase tracking-widest opacity-60">Coins</p>
                      <p className="text-2xl font-black">+{gameResult.coins}</p>
                    </div>
                    <div className="bg-white/20 px-6 py-3 rounded-2xl">
                      <p className="text-[8px] font-black uppercase tracking-widest opacity-60">Exp</p>
                      <p className="text-2xl font-black">+{gameResult.exp}</p>
                    </div>
                 </div>
                 <div className="flex gap-2">
                    <button onClick={() => setGameMode(null)} className="flex-1 p-4 bg-white text-indigo-600 rounded-2xl font-black uppercase text-xs">Menu</button>
                    <button onClick={() => shareBadge(`My Guardian level up! Found ${gameResult.coins} Mood Coins in ${gameMode}! 🚀`)} className="flex-1 p-4 bg-yellow-400 text-white rounded-2xl font-black uppercase text-xs">Share</button>
                 </div>
               </div>
             ) : (
               <div className="space-y-6">
                  <div className="flex justify-between items-center text-xs font-black uppercase">
                    <span>{gameMode}</span>
                    <span className="bg-black/20 px-4 py-1 rounded-full flex items-center gap-2"><Timer size={14}/> {timeLeft}s</span>
                  </div>
                  {gameMode === 'tap' && (
                    <button onClick={() => setTapScore(s => s + 1)} className="w-32 h-32 bg-white rounded-full mx-auto text-indigo-600 text-5xl font-black shadow-inner active:scale-90 transition-transform">{tapScore}</button>
                  )}
                  {gameMode === 'memory' && (
                    <div className="grid grid-cols-4 gap-2">
                      {cards.map(card => (
                        <button key={card.id} className="h-16 bg-white/20 rounded-xl text-2xl flex items-center justify-center">❓</button>
                      ))}
                    </div>
                  )}
                  {!['tap', 'memory'].includes(gameMode) && (
                    <div className="py-12 italic opacity-60 font-black">Scanning Frequency...</div>
                  )}
               </div>
             )}
          </div>
        )}

        {activeTab === 'Interaction' && (
          <div className="col-span-full space-y-4">
            <h5 className="text-[10px] font-black uppercase tracking-[0.3em] opacity-30 text-center mb-2">Rest Modes</h5>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
              {SLEEP_MODES.map(mode => (
                <button key={mode.id} onClick={() => startSleep(mode.id)} className={`p-6 rounded-[2rem] border-2 border-black/5 flex flex-col items-center justify-center gap-2 ${isDarkMode ? 'bg-[#111111] text-white' : 'bg-white text-slate-900'} shadow-md`}>
                   <span className="text-3xl">{mode.emoji}</span>
                   <p className="font-black uppercase text-[10px]">{mode.name}</p>
                   <p className="text-[8px] opacity-40 font-bold">{mode.duration} Mins • +{mode.rest} Rest</p>
                   <div className="flex items-center gap-1 text-[8px] font-black text-yellow-500 mt-1"><Coins size={10}/> {mode.cost}</div>
                </button>
              ))}
            </div>
          </div>
        )}
      </div>

      {/* Not Enough Coins Popup */}
      <AnimatePresence>
        {showCoinAlert && (
          <div className="fixed inset-0 z-[600] flex items-center justify-center pointer-events-none p-6">
            <motion.div initial={{ scale: 0.5, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} exit={{ scale: 0.5, opacity: 0 }} className="bg-red-500 text-white px-8 py-5 rounded-[2rem] shadow-2xl flex items-center gap-4 border-4 border-white/20">
               <AlertCircle size={32} />
               <div className="text-left">
                 <p className="font-black text-lg uppercase italic tracking-tighter">NOT ENOUGH MOOD COINS</p>
                 <p className="text-[10px] font-bold uppercase tracking-widest opacity-70">Complete quizzes or play games to earn more!</p>
               </div>
            </motion.div>
          </div>
        )}
      </AnimatePresence>

      <AnimatePresence>
        {showEmojiPicker && (
          <div className="fixed inset-0 z-[400] flex items-center justify-center p-6 bg-black/90 backdrop-blur-md">
            <motion.div initial={{ scale: 0.9, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} className={`${isDarkMode ? 'bg-[#111111]' : 'bg-white'} w-full max-w-md rounded-[3rem] p-8 shadow-2xl border-4 border-indigo-500/20`}>
              <div className="flex justify-between items-center mb-8">
                <h3 className={`text-2xl font-black italic uppercase ${isDarkMode ? 'text-white' : 'text-slate-900'}`}>Transform Pet</h3>
                <button onClick={() => setShowEmojiPicker(false)} className="opacity-40 hover:opacity-100"><X size={32}/></button>
              </div>
              <p className="text-xs font-black uppercase opacity-40 mb-6 text-center">Cost: <span className="text-yellow-500">100 Mood Coins</span></p>
              <div className="grid grid-cols-4 gap-3 max-h-60 overflow-y-auto pr-2 custom-scrollbar">
                {PET_OPTIONS.map(e => (
                  <button key={e} onClick={() => { if(checkCoins(100)) { onUpdate(0,0,0,-100,0,null,e); setShowEmojiPicker(false); } }} className={`text-3xl p-4 rounded-2xl border-2 transition-all ${isDarkMode ? 'bg-[#1a1a1a] border-white/5' : 'bg-gray-50 border-black/5'}`}>{e}</button>
                ))}
              </div>
              <button onClick={() => setShowEmojiPicker(false)} className="w-full mt-8 p-5 bg-gray-500 text-white rounded-2xl font-black uppercase">Cancel</button>
