import React, { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import { getLovePrediction } from '../services/geminiService';
import { useDarkMode } from '../context/DarkModeContext';

const MysticTeller = () => {
  const [tellerQuestion, setTellerQuestion] = useState('');
  const [tellerResponse, setTellerResponse] = useState(null);
  const [isTellerLoading, setIsTellerLoading] = useState(false);
  const { isDarkMode } = useDarkMode();

  const handleTeller = async () => {
    if (tellerQuestion.trim() === '') {
      return;
    }

    setIsTellerLoading(true);
    try {
      const response = await getLovePrediction(tellerQuestion);
      setTellerResponse(response.reason);
    } catch (error) {
      console.error('Error fetching prediction:', error);
      setTellerResponse('The void is silent. Try again.');
    } finally {
      setIsTellerLoading(false);
    }
  };

  useEffect(() => {
    // Clear the response when the question changes
    setTellerResponse(null);
  }, [tellerQuestion]);

  return (
    <motion.div initial={{ scale: 0.9, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} className="flex flex-col items-center justify-center w-full">
      <motion.div initial={{ y: 20, opacity: 0 }} animate={{ y: 0, opacity: 1 }} transition={{ delay: 0.2 }} className="max-w-md w-full">
        <div className="flex flex-col items-center gap-6">
          <input
            type="text"
            value={tellerQuestion}
            onChange={(e) => setTellerQuestion(e.target.value)}
            placeholder="Ask the void..."
            className={`${
              isDarkMode ? 'bg-slate-900 text-white' : 'bg-white text-slate-900'
            } w-full py-6 px-8 rounded-[2rem] border-4 border-black/5 outline-none font-black text-xl placeholder:opacity-10 focus:border-[#46178f] shadow-inner`}
          />
          <button
            onClick={handleTeller}
            disabled={isTellerLoading}
            className="kahoot-button-purple w-full p-6 rounded-[2rem] text-white font-black uppercase text-xl shadow-xl"
          >
            CONSULT THE VOID
          </button>
        </div>
        {tellerResponse && (
          <motion.div
            initial={{ scale: 0.9, opacity: 0 }}
            animate={{ scale: 1, opacity: 1 }}
            className={`mt-12 p-10 rounded-[2.5rem] ${
              isDarkMode ? 'bg-[#1a1a1a] text-white' : 'bg-indigo-50 text-indigo-900'
            } border-2 border-black/5 max-w-md w-full shadow-2xl`}
          >
            <p className="text-3xl font-black italic uppercase mb-4 tracking-tighter">
              {tellerResponse.split('.')[0]}
            </p>
            <p className="text-base font-bold leading-snug italic opacity-80">
              {tellerResponse.split('.').slice(1).join('.')}
            </p>
          </motion.div>
        )}
      </motion.div>
    </motion.div>
  );
};

export default MysticTeller;
```
