import React, { useState, useEffect, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Heart, MessageCircle, Repeat, Send, Sparkles, Brain, Wind, ShoppingBag, Gamepad2, Bed, Lock, Coins, Ghost, QuestionMark, Zap, Calculator, Target, Trophy, Info } from 'lucide-react';
import { User, Post, Mood, Comment } from '../types';
import MoodPetSection from './MoodPetSection';
import { getTellerResponse } from '../services/geminiService';

interface MoodSectionProps {
  user: User;
  posts: Post[];
  onPost: (content: string) => void;
  onHeart: (postId: string) => void;
  onComment: (postId: string, text: string) => void;
  onRepost: (post: Post) => void;
  onFollow: (username: string) => void;
  onBlock: (username: string) => void;
  isDarkMode: boolean;
  onNavigateToProfile: (username: string) => void;
  onUpdatePet: (hunger: number, thirst: number, rest: number, coins: number, exp?: number, sleepUntil?: number | null, newEmoji?: string, markChosen?: boolean) => void;
}

type MoodSubTab = 'Express' | 'Teller' | 'Quiz' | 'MoodPet';

const EMOTIONAL_QUIZ = [
  { q: "How did you feel the moment you woke up today?", options: ["Refreshed", "Stressed", "Meh", "Excited"], weights: { Happy: 1, Angry: 0, Tired: -1, Normal: 0 } },
  { q: "What's the weather in your internal 'City' right now?", options: ["Sunny", "Stormy", "Foggy", "Clear Skies"], weights: { Happy: 2, Angry: 1, Tired: 0, Normal: 1 } },
  { q: "How much energy do you have for socializing?", options: ["Tons!", "None", "Maybe later", "Only with friends"], weights: { Happy: 1, Tired: 1, Normal: 0, Excited: 2 } },
  { q: "Pick a color that resonates with you right now.", options: ["Crimson Red", "Soft Blue", "Bright Yellow", "Forest Green"], weights: { Angry: 1, Tired: 1, Happy: 1, Normal: 1 } },
  { q: "Is your mind busy or quiet?", options: ["Race track", "Library", "Zen garden", "Static noise"], weights: { Excited: 1, Normal: 1, Happy: 1, Tired: 1 } },
  { q: "What is your current physical comfort level?", options: ["Perfect", "A bit sore", "Exhausted", "Tense"], weights: { Happy: 1, Normal: 0, Tired: 2, Angry: 1 } },
  { q: "If you were a sound, what would you be?", options: ["A drum solo", "Soft rain", "White noise", "A symphony"], weights: { Angry: 1, Normal: 1, Tired: 1, Happy: 1 } },
  { q: "How do you feel about your tasks today?", options: ["Ready to crush!", "Dreading them", "I'll manage", "What tasks?"], weights: { Excited: 2, Angry: 1, Normal: 1, Happy: 1 } },
  { q: "Choose a snack mood.", options: ["Something spicy", "Something sweet", "Something healthy", "Nothing"], weights: { Angry: 1, Happy: 1, Normal: 1, Tired: 1 } },
  { q: "Finally, how would you rate your patience level?", options: ["Infinite", "Fragile", "Short", "Average"], weights: { Happy: 1, Tired: 1, Angry: 2, Normal: 1 } },
];

const MoodSection: React.FC<MoodSectionProps> = ({ user, posts, onPost, onHeart, onComment, onRepost, onFollow, onBlock, isDarkMode, onNavigateToProfile, onUpdatePet }) => {
  const [subTab, setSubTab] = useState<MoodSubTab>('Express');
  const [postContent, setPostContent] = useState('');
  const [feedFilter, setFeedFilter] = useState<'All' | 'Following'>('All');

  // Teller State
  const [tellerQuestion, setTellerQuestion] = useState('');
  const [tellerResponse, setTellerResponse] = useState('');
  const [isTellerLoading, setIsTellerLoading] = useState(false);

  // Quiz State
  const [quizActive, setQuizActive] = useState(false);
  const [quizStep, setQuizStep] = useState(0);
  const [quizScores, setQuizScores] = useState<Record<string, number>>({ Happy: 0, Angry: 0, Tired: 0, Normal: 0, Excited: 0 });
  const [quizResult, setQuizResult] = useState<string | null>(null);

  const startQuiz = () => {
    setQuizActive(true);
    setQuizStep(0);
    setQuizScores({ Happy: 0, Angry: 0, Tired: 0, Normal: 0, Excited: 0 });
    setQuizResult(null);
  };

  const handleQuizAnswer = (idx: number) => {
    const weights = EMOTIONAL_QUIZ[quizStep].weights;
    // Fix logic and type error: Use local variable to avoid stale closure issues and ensure numbers for arithmetic
    const nextScores = { ...quizScores };
    Object.entries(weights).forEach(([key, val]) => {
      nextScores[key] = (nextScores[key] || 0) + (val as number);
    });
    setQuizScores(nextScores);

    if (quizStep < EMOTIONAL_QUIZ.length - 1) {
      setQuizStep(s => s + 1);
    } else {
      // Calculate final result using the updated scores directly to avoid stale state issues.
      // Fix: Cast values to number to resolve TypeScript arithmetic errors on line 75
      const entries = Object.entries(nextScores);
      const sorted = entries.sort((a, b) => (b[1] as number) - (a[1] as number));
      const topMood = sorted[0][0];
      setQuizResult(topMood);
      onUpdatePet(0, 0, 0, 50, 100); // Reward for completion
    }
  };

  const handleTeller = async () => {
    if (!tellerQuestion.trim()) return;
    setIsTellerLoading(true);
    setTellerResponse('');
    try {
      const res = await getTellerResponse(tellerQuestion);
      setTellerResponse(res || 'The cosmic fog obscures my vision...');
    } catch (e) {
      setTellerResponse('MAYBE. The spirits are currently in a meeting.');
    } finally {
      setIsTellerLoading(false);
    }
  };

  const filteredPosts = feedFilter === 'All' 
    ? posts 
    : posts.filter(p => user.following.includes(p.author) || p.author === user.username);

  return (
    <div className="flex flex-col gap-8 pb-10">
      <div className="flex gap-2 overflow-x-auto no-scrollbar pb-2">
        {(['Express', 'Teller', 'Quiz', 'MoodPet'] as MoodSubTab[]).map((t) => (
          <button
            key={t}
            onClick={() => setSubTab(t)}
            className={`px-8 py-3 rounded-full font-black text-xs transition-all whitespace-nowrap uppercase tracking-tighter border-b-4 ${subTab === t ? 'bg-[#e21b3c] border-[#b31530] text-white shadow-xl' : isDarkMode ? 'bg-[#1a1a1a] border-black text-white/30' : 'bg-white border-gray-200 text-slate-500 shadow-sm'}`}
          >
            {t === 'MoodPet' ? 'Mood Pet 🐾' : t === 'Quiz' ? 'Mood Predictor 🧬' : t}
          </button>
        ))}
      </div>

      <AnimatePresence mode="wait">
        {subTab === 'Express' && (
          <motion.div key="express" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="space-y-6">
            <div className={`p-6 md:p-8 rounded-[2.5rem] ${isDarkMode ? 'bg-[#111111]' : 'bg-white'} border border-black/5 shadow-2xl`}>
              <textarea value={postContent} onChange={(e) => setPostContent(e.target.value)} placeholder="Transmit your emotional frequency..." className={`w-full ${isDarkMode ? 'bg-[#1a1a1a] text-white' : 'bg-gray-50 text-slate-900'} p-5 rounded-2xl border-2 border-black/5 focus:border-[#e21b3c] outline-none transition-all font-bold placeholder:opacity-30`} rows={3} />
              <div className="flex justify-between items-center mt-4">
                <div className="flex gap-2">
                  <button onClick={() => setFeedFilter('All')} className={`px-4 py-2 rounded-xl text-[10px] font-black ${feedFilter === 'All' ? 'bg-[#e21b3c] text-white' : 'opacity-40'}`}>ALL DISTRICTS</button>
                  <button onClick={() => setFeedFilter('Following')} className={`px-4 py-2 rounded-xl text-[10px] font-black ${feedFilter === 'Following' ? 'bg-[#e21b3c] text-white' : 'opacity-40'}`}>MY CIRCLE</button>
                </div>
                <button onClick={() => {onPost(postContent); setPostContent('');}} className="kahoot-button-red px-10 py-4 text-white rounded-2xl font-black text-xs flex items-center gap-3">
                  <Send size={18} /> BROADCAST
                </button>
              </div>
            </div>

            <div className="space-y-4">
              {filteredPosts.map(post => (
                  <div key={post.id} className={`p-6 md:p-8 rounded-[2.5rem] ${isDarkMode ? 'bg-[#111111] text-white' : 'bg-white text-slate-900'} border border-black/5 shadow-md`}>
                    <div className="flex items-center gap-4 mb-6">
                      <div className="w-12 h-12 rounded-2xl bg-indigo-500 flex items-center justify-center text-white font-black overflow-hidden shadow-lg">
                        {post.author[0].toUpperCase()}
                      </div>
                      <h4 className="font-black text-sm tracking-tight">@{post.author}</h4>
                    </div>
                    <p className="text-base md:text-lg font-medium mb-8 leading-relaxed">{post.content}</p>
                    <div className="flex items-center gap-8 pt-6 border-t border-black/5">
                      <button onClick={() => onHeart(post.id)} className="flex items-center gap-2 text-[#e21b3c] font-black text-[10px]"><Heart size={20} fill={post.hearts > 0 ? "currentColor" : "none"} /> {post.hearts}</button>
                      <button onClick={() => onRepost(post)} className="flex items-center gap-2 text-green-500 font-black text-[10px]"><Repeat size={20} /> ECHO</button>
                    </div>
                  </div>
              ))}
            </div>
          </motion.div>
        )}

        {subTab === 'MoodPet' && (
          <motion.div key="pet" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}>
            <MoodPetSection user={user} isDarkMode={isDarkMode} onUpdate={onUpdatePet} onPost={onPost} />
          </motion.div>
        )}

        {subTab === 'Teller' && (
          <motion.div key="teller" initial={{ opacity: 0 }} animate={{ opacity: 1 }} className={`flex flex-col items-center justify-center p-12 text-center ${isDarkMode ? 'bg-[#111111]' : 'bg-white'} rounded-[3rem] border border-black/5 shadow-2xl relative overflow-hidden`}>
            <div className="absolute top-[-20%] left-[-20%] w-[60%] h-[60%] bg-[#46178f]/10 blur-[120px] rounded-full"></div>
            <div className="mb-10 text-8xl md:text-9xl select-none drop-shadow-2xl">🔮</div>
            <h3 className={`text-3xl md:text-5xl font-black italic uppercase mb-4 tracking-tighter ${isDarkMode ? 'text-white' : 'text-slate-900'}`}>Mystic Teller</h3>
            <p className="text-xs opacity-40 mb-10 max-w-sm font-bold uppercase tracking-[0.3em]">Consult the void</p>
            <div className="w-full max-w-lg space-y-6">
              <input type="text" value={tellerQuestion} onChange={e => setTellerQuestion(e.target.value)} placeholder="Will I find peace?" className={`w-full ${isDarkMode ? 'bg-[#1a1a1a] text-white' : 'bg-gray-50 text-slate-900'} p-6 rounded-[2rem] border-4 border-black/5 outline-none font-black text-xl placeholder:opacity-10 focus:border-[#46178f] shadow-inner`} />
              <button onClick={handleTeller} disabled={isTellerLoading} className="kahoot-button-purple w-full p-6 rounded-[2rem] text-white font-black uppercase text-xl shadow-xl">CONSULT THE VOID</button>
            </div>
            {tellerResponse && (
              <motion.div initial={{ scale: 0.9, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} className={`mt-12 p-10 rounded-[2.5rem] ${isDarkMode ? 'bg-[#1a1a1a] text-white' : 'bg-indigo-50 text-indigo-900'} border-2 border-black/5 max-w-md w-full shadow-2xl`}>
                <p className="text-3xl font-black italic uppercase mb-4 tracking-tighter">{tellerResponse.split('.')[0]}</p>
                <p className="text-base font-bold leading-snug italic opacity-80">{tellerResponse.split('.').slice(1).join('.')}</p>
              </motion.div>
            )}
          </motion.div>
        )}

        {subTab === 'Quiz' && (
          <motion.div key="quiz" initial={{ opacity: 0 }} animate={{ opacity: 1 }}>
            {!quizActive ? (
              <div className={`flex flex-col items-center justify-center text-center p-12 ${isDarkMode ? 'bg-[#111111]' : 'bg-white'} rounded-[3rem] border border-black/5 shadow-2xl`}>
                <Brain className="text-indigo-500 mb-10" size={80} />
                <h3 className={`text-3xl md:text-5xl font-black italic uppercase mb-4 tracking-tighter ${isDarkMode ? 'text-white' : 'text-slate-900'}`}>Emotional Predictor</h3>
                <p className="text-xs opacity-40 mb-12 max-w-xs font-bold uppercase tracking-widest leading-relaxed">Answer 10 questions and Mooderia will map your current emotional district.</p>
                <button onClick={startQuiz} className="kahoot-button-purple px-16 py-6 rounded-3xl text-white font-black text-2xl uppercase">BEGIN SCAN</button>
              </div>
            ) : quizResult ? (
              <div className={`flex flex-col items-center justify-center text-center p-12 ${isDarkMode ? 'bg-[#111111]' : 'bg-white'} rounded-[3rem] shadow-xl border border-black/5`}>
                <Trophy className="text-yellow-500 mb-10" size={96} />
                <h3 className={`text-3xl md:text-4xl font-black italic uppercase mb-2 tracking-tighter ${isDarkMode ? 'text-white' : 'text-slate-900'}`}>District Scan Complete</h3>
                <p className="text-lg font-black uppercase tracking-widest opacity-40 mb-2">We predict your mood is:</p>
                <p className="text-6xl font-black mb-10 text-[#e21b3c] italic uppercase tracking-tighter">{quizResult}</p>
                <div className="flex gap-4">
                  <button onClick={() => { onPost(`My Mooderia scan result: ${quizResult}! 🧬`); setQuizActive(false); }} className="kahoot-button-blue px-10 py-4 rounded-2xl text-white font-black text-sm uppercase">SHARE TO FEED</button>
                  <button onClick={startQuiz} className="kahoot-button-red px-10 py-4 rounded-2xl text-white font-black text-sm uppercase">RE-SCAN</button>
                </div>
              </div>
            ) : (
              <div className={`max-w-2xl mx-auto py-12 px-10 ${isDarkMode ? 'bg-[#111111]' : 'bg-white'} rounded-[3.5rem] shadow-2xl border border-black/5`}>
                <div className="flex justify-between items-center mb-12">
                  <span className="text-[10px] font-black uppercase text-[#e21b3c] tracking-[0.4em] italic">Scanning Question {quizStep + 1} / 10</span>
                  <div className="w-32 h-3 bg-gray-100 rounded-full overflow-hidden">
                    <motion.div initial={{ width: 0 }} animate={{ width: `${(quizStep + 1) * 10}%` }} className="h-full bg-[#e21b3c]" />
                  </div>
                </div>
                <h4 className={`text-2xl md:text-3xl font-black italic mb-12 leading-tight tracking-tight text-center ${isDarkMode ? 'text-white' : 'text-slate-900'}`}>{EMOTIONAL_QUIZ[quizStep].q}</h4>
                <div className="grid grid-cols-1 gap-4">
                  {EMOTIONAL_QUIZ[quizStep].options.map((opt, i) => (
                    <button key={i} onClick={() => handleQuizAnswer(i)} className={`p-6 rounded-3xl border-2 border-black/5 text-center font-black text-base transition-all shadow-md ${isDarkMode ? 'bg-[#1a1a1a] text-white hover:border-[#e21b3c]' : 'bg-gray-50 text-slate-800 hover:border-[#e21b3c]'}`}>
                      {opt}
                    </button>
                  ))}
                </div>
              </div>
            )}
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
};

