                <input type="text" value={editForm.username} onChange={e => setEditForm({...editForm, username: e.target.value})} placeholder="Username" className={`w-full ${isDarkMode ? 'bg-[#1a1a1a] text-white' : 'bg-gray-50 text-slate-900'} border-2 border-black/5 p-4 md:p-5 rounded-2xl font-bold outline-none focus:border-[#e21b3c]`} />
