          <button
            key={t}
            onClick={() => setTab(t as ZodiacTab)}
            className={`px-6 md:px-8 py-2.5 md:py-3 rounded-full font-black text-[10px] md:text-xs transition-all whitespace-nowrap uppercase tracking-tighter border-b-4 ${tab === t ? 'bg-[#26890c] border-[#1c6409] text-white shadow-xl' : isDarkMode ? 'bg-[#1a1a1a] border-black text-white/30' : 'bg-white border-gray-100 text-slate-500 shadow-sm'}`}
          >
            {t.replace(/([A-Z])/g, ' $1').trim()}
          </button>
        ))}
      </div>

      <div className="flex-1 fading-scrollbar overflow-y-auto pr-1">
        <div className="pb-16">
          <AnimatePresence mode="wait">
            {tab === 'LoveMatcher' && (
              <motion.div key="love" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className={`p-8 md:p-10 rounded-[3rem] ${isDarkMode ? 'bg-[#111111]' : 'bg-white'} border border-black/5 shadow-2xl text-center`}>
                <Heart className="mx-auto mb-8 text-[#e21b3c] animate-pulse" size={64} />
                <h2 className={`text-3xl md:text-5xl font-black mb-10 md:mb-12 uppercase italic tracking-tighter ${isDarkMode ? 'text-white' : 'text-black'}`}>Love Matcher</h2>

                <div className="grid grid-cols-1 md:grid-cols-3 items-center gap-6 md:gap-10 mb-10 md:mb-12 max-w-2xl mx-auto">
                  <div className="space-y-4">
                    <p className={`text-[10px] font-black uppercase opacity-30 tracking-[0.4em] ${isDarkMode ? 'text-white' : 'text-black'}`}>Citizen A</p>
                    <div className="flex gap-2"><MonthPicker val={m1} setVal={setM1} /><DayPicker val={d1} setVal={setD1} /></div>
                  </div>
                  <div className="text-4xl md:text-5xl font-black text-[#e21b3c] select-none">&hearts;</div>
                  <div className="space-y-4">
                    <p className={`text-[10px] font-black uppercase opacity-30 tracking-[0.4em] ${isDarkMode ? 'text-white' : 'text-black'}`}>Citizen B</p>
                    <div className="flex gap-2"><MonthPicker val={m2} setVal={setM2} /><DayPicker val={d2} setVal={setD2} /></div>
                  </div>
