                <div className="relative max-w-sm mx-auto mb-12">
                  <select value={luckyZodiac} onChange={(e) => setLuckyZodiac(e.target.value)} className={`w-full ${isDarkMode ? 'bg-[#1a1a1a] text-white' : 'bg-gray-50 text-black'} p-4 md:p-5 rounded-2xl font-black border-2 border-black/5 text-lg md:text-xl outline-none focus:border-blue-500 appearance-none text-center shadow-inner`}>
                    {ZODIACS.map(z => <option key={z.name} value={z.name}>{z.symbol} {z.name.toUpperCase()}</option>)}
                  </select>
