interface MoodPetSectionProps {
  user: User;
  isDarkMode: boolean;
  onUpdate: (hunger: number, thirst: number, rest: number, coins: number, exp?: number, sleepUntil?: number | null, newEmoji?: string, markChosen?: boolean) => void;
  onPost: (content: string) => void;
}

const ITEMS = [
  { id: 'f1', type: 'hunger', name: 'Munchies', emoji: '🍿', cost: 10, fill: 15 },
  { id: 'f2', type: 'hunger', name: 'Burger', emoji: '🍔', cost: 25, fill: 40 },
  { id: 'f3', type: 'hunger', name: 'Feast', emoji: '🥘', cost: 50, fill: 90 },
  { id: 'd1', type: 'thirst', name: 'Water', emoji: '💧', cost: 5, fill: 10 },
  { id: 'd2', type: 'thirst', name: 'Energy', emoji: '⚡', cost: 20, fill: 35 },
  { id: 'd3', type: 'thirst', name: 'Tea', emoji: '🍵', cost: 45, fill: 80 },
];

const GAMES = [
  { id: 'memory', name: 'Mind Match', emoji: '🧠', color: 'bg-pink-400', time: 30 },
  { id: 'tap', name: 'Speed Tap', emoji: '⚡', color: 'bg-yellow-400', time: 10 },
  { id: 'math', name: 'Quick Math', emoji: '🔢', color: 'bg-indigo-400', time: 20 },
  { id: 'bubble', name: 'Bubble Pop', emoji: '🫧', color: 'bg-blue-400', time: 15 },
  { id: 'sort', name: 'Emoji Sort', emoji: '🎨', color: 'bg-green-400', time: 25 },
  { id: 'jumble', name: 'Word Rush', emoji: '🔠', color: 'bg-red-400', time: 30 },
  { id: 'pattern', name: 'Patterns', emoji: '🧩', color: 'bg-purple-400', time: 20 },
  { id: 'reaction', name: 'React Fast', emoji: '🎯', color: 'bg-orange-400', time: 5 },
  { id: 'flappy', name: 'Sky Wing', emoji: '🕊️', color: 'bg-sky-400', time: 40 },
];

const SLEEP_MODES = [
  { id: 'short', name: 'Napping', duration: 10, rest: 40, exp: 20, cost: 0, emoji: '😴' },
  { id: 'medium', name: 'Power Sleep', duration: 30, rest: 75, exp: 50, cost: 25, emoji: '🛌' },
  { id: 'deep', name: 'Hibernation', duration: 120, rest: 100, exp: 200, cost: 75, emoji: '🌌' },
];

const PET_OPTIONS = ['🐱', '🐶', '🦊', '🦁', '🐨', '🐼', '🦄', '🐲', '🐸', '🐹', '🐰', '🐯', '🐧', '🐻', '🦉'];

const MoodPetSection: React.FC<MoodPetSectionProps> = ({ user, isDarkMode, onUpdate, onPost }) => {
  const [activeTab, setActiveTab] = useState<'Interaction' | 'Shop' | 'Games'>('Interaction');
  const [gameMode, setGameMode] = useState<string | null>(null);
  const [gameResult, setGameResult] = useState<{ coins: number, exp: number } | null>(null);
  const [timeLeft, setTimeLeft] = useState(0);
  const [showEmojiPicker, setShowEmojiPicker] = useState(false);
  const [showCoinAlert, setShowCoinAlert] = useState(false);
  const [petting, setPetting] = useState(false);
  const [tapScore, setTapScore] = useState(0);

  const isSleeping = user.petSleepUntil && user.petSleepUntil > Date.now();

  useEffect(() => {
    let timer: number;
    if (gameMode && timeLeft > 0) {
      timer = window.setInterval(() => setTimeLeft(prev => prev - 1), 1000);
    } else if (gameMode && timeLeft === 0) {
      finishGame();
    }
    return () => clearInterval(timer);
  }, [gameMode, timeLeft]);

  const finishGame = () => {
    let coins = 0;
    let exp = 0;
    if (gameMode === 'tap') {
      coins = Math.min(60, tapScore * 3);
      exp = tapScore * 10;
    } else {
      coins = Math.floor(Math.random() * 30) + 20;
      exp = coins * 3;
    }
    setGameResult({ coins, exp });
    onUpdate(-15, -15, -20, coins, exp);
  };

  const startLevelGame = (id: string) => {
    if (user.petRest < 25) {
      alert("Guardian is too exhausted! Let them sleep first.");
      return;
    }
    const config = GAMES.find(g => g.id === id);
    if (!config) return;
    setGameMode(id);
    setTimeLeft(config.time);
    setGameResult(null);
    if (id === 'tap') setTapScore(0);
  };

  const checkCoins = (cost: number) => {
    if (user.moodCoins < cost) {
      setShowCoinAlert(true);
      setTimeout(() => setShowCoinAlert(false), 2000);
      return false;
    }
    return true;
  };

  const startSleep = (modeId: string) => {
    const mode = SLEEP_MODES.find(m => m.id === modeId);
    if (!mode) return;
    if (!checkCoins(mode.cost)) return;
    onUpdate(0, 0, mode.rest, -mode.cost, mode.exp, Date.now() + mode.duration * 60 * 1000);
  };

  const shareAchievement = (msg: string) => {
    onPost(msg);
    alert("Achievement broadcasted to Mooderia Metropolis!");
  };

  if (!user.petHasBeenChosen) {
    return (
      <div className={`flex flex-col items-center justify-center p-12 text-center ${isDarkMode ? 'bg-[#111111]' : 'bg-white'} rounded-[3rem] shadow-2xl border border-black/5`}>
        <h3 className={`text-4xl font-black italic uppercase mb-10 tracking-tighter ${isDarkMode ? 'text-white' : 'text-slate-900'}`}>Summon a Guardian</h3>
        <div className="grid grid-cols-4 gap-4 max-w-md">
          {PET_OPTIONS.map(e => (
            <button key={e} onClick={() => onUpdate(0,0,0,0,0,null,e,true)} className={`text-5xl p-6 rounded-[2rem] border-4 border-black/5 hover:border-[#e21b3c] transition-all ${isDarkMode ? 'bg-[#1a1a1a]' : 'bg-gray-50 shadow-inner'}`}>{e}</button>
          ))}
        </div>
      </div>
    );
  }

  return (
    <div className="flex flex-col gap-6 relative">
      <div className={`p-8 rounded-[3rem] ${isDarkMode ? 'bg-[#111111] text-white' : 'bg-white text-slate-900'} border border-black/5 shadow-2xl flex flex-col items-center justify-center relative overflow-hidden`}>
        <AnimatePresence>
          {isSleeping && (
            <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="absolute inset-0 z-50 bg-indigo-900/90 flex flex-col items-center justify-center text-white backdrop-blur-md p-6 text-center">
               <Lock size={64} className="mb-4 animate-pulse text-indigo-300" />
               <h4 className="text-3xl font-black uppercase italic tracking-tighter">REST MODE ACTIVATED</h4>
               <p className="text-[10px] font-black uppercase tracking-[0.3em] opacity-60">Do not disturb the Guardian's frequency.</p>
               <div className="mt-8 bg-black/30 px-6 py-4 rounded-[2rem] flex items-center gap-3 font-black text-xl border-2 border-white/10">
                 <Timer size={24}/> {Math.ceil((user.petSleepUntil! - Date.now()) / (1000 * 60))} Mins Left
               </div>
            </motion.div>
          )}
        </AnimatePresence>

        <div className="absolute top-6 left-6 flex items-center gap-2 bg-yellow-400 px-4 py-2 rounded-2xl text-white font-black text-xs shadow-lg">
          <Coins size={16}/> {user.moodCoins}
        </div>
        <button onClick={() => setShowEmojiPicker(true)} className="absolute top-6 right-6 p-3 bg-indigo-500 text-white rounded-2xl font-black text-xs shadow-lg hover:scale-110 active:scale-90 transition-transform">
          <Wand2 size={18}/>
        </button>

        <motion.div animate={{ y: [0, -15, 0], rotate: [0, 2, -2, 0] }} transition={{ duration: 5, repeat: Infinity }} className="text-[120px] md:text-[150px] my-10 select-none flex items-center justify-center">
          {user.petEmoji}
        </motion.div>

        <div className="w-full max-w-sm grid grid-cols-3 gap-4">
           {[
             { label: 'Hunger', val: user.petHunger, color: 'bg-red-500', icon: <Utensils size={14} /> },
             { label: 'Thirst', val: user.petThirst, color: 'bg-blue-500', icon: <Droplets size={14} /> },
             { label: 'Rest', val: user.petRest, color: 'bg-green-500', icon: <Zap size={14} /> },
           ].map(bar => (
             <div key={bar.label} className="flex flex-col items-center gap-2">
               <div className="flex items-center justify-center gap-1 text-[8px] font-black uppercase opacity-40">{bar.icon} {bar.val}%</div>
               <div className="w-full h-2.5 bg-black/5 rounded-full overflow-hidden">
                 <motion.div initial={{ width: 0 }} animate={{ width: `${bar.val}%` }} className={`h-full ${bar.color} rounded-full`} />
               </div>
             </div>
           ))}
        </div>

        <div className="mt-6 flex flex-col items-center">
           <p className="text-[10px] font-black uppercase opacity-30 tracking-widest mb-1">Guardian Level {user.petLevel}</p>
           <div className="w-48 h-2 bg-black/5 rounded-full overflow-hidden">
              <motion.div initial={{ width: 0 }} animate={{ width: `${(user.petExp / getExpNeeded(user.petLevel)) * 100}%` }} className="h-full bg-indigo-500" />
           </div>
        </div>
      </div>

      <div className="flex gap-2 shrink-0">
        {(['Interaction', 'Shop', 'Games'] as const).map(tab => (
          <button key={tab} onClick={() => setActiveTab(tab)} className={`flex-1 py-4 rounded-2xl font-black text-[10px] uppercase border-b-4 transition-all ${activeTab === tab ? 'bg-[#1368ce] border-[#0e4c99] text-white shadow-lg' : isDarkMode ? 'bg-[#111111] border-black text-white/30' : 'bg-white border-gray-100 text-slate-500 shadow-sm'}`}>{tab}</button>
        ))}
      </div>

      <div className="grid grid-cols-2 md:grid-cols-3 gap-4 pb-20">
        {activeTab === 'Shop' && ITEMS.map(item => (
          <button key={item.id} onClick={() => { if(checkCoins(item.cost)) onUpdate(item.type === 'hunger' ? item.fill : 0, item.type === 'thirst' ? item.fill : 0, 0, -item.cost, 15); }} className={`p-6 rounded-[2rem] border-2 border-black/5 flex flex-col items-center justify-center text-center gap-2 ${isDarkMode ? 'bg-[#111111] text-white' : 'bg-white text-slate-900'} shadow-md hover:scale-105 active:scale-95 transition-transform`}>
            <span className="text-4xl">{item.emoji}</span>
            <span className="text-[10px] font-black uppercase opacity-40">{item.name}</span>
            <div className="bg-yellow-400 text-white px-3 py-1 rounded-xl text-[10px] font-black flex items-center justify-center gap-1 shadow-sm"><Coins size={12}/> {item.cost}</div>
          </button>
        ))}

        {activeTab === 'Games' && !gameMode && GAMES.map(game => (
          <button key={game.id} onClick={() => startLevelGame(game.id)} className={`p-6 rounded-[2rem] border-2 border-black/5 flex flex-col items-center justify-center text-center gap-2 ${isDarkMode ? 'bg-[#111111] text-white' : 'bg-white text-slate-900'} shadow-md transition-all hover:scale-105 hover:border-indigo-500 group`}>
            <span className="text-4xl group-hover:scale-125 transition-transform">{game.emoji}</span>
            <span className="text-[10px] font-black uppercase opacity-40 leading-none">{game.name}</span>
            <span className="text-[8px] font-bold text-indigo-500 px-2 py-0.5 bg-indigo-50 rounded-full">{game.time}s Session</span>
          </button>
        ))}

        {gameMode && (
          <div className="col-span-full p-8 bg-indigo-500 rounded-[3rem] text-white text-center shadow-2xl relative border-4 border-white/20">
             {gameResult ? (
               <div className="space-y-6">
                 <motion.div initial={{ scale: 0 }} animate={{ scale: 1 }} className="flex flex-col items-center">
                   <Trophy size={80} className="text-yellow-300 mb-4" />
                   <h4 className="text-3xl font-black italic uppercase tracking-tighter">SESSION RESULTS</h4>
                 </motion.div>
                 <div className="flex justify-center gap-6">
                    <div className="bg-white/20 px-8 py-4 rounded-[1.5rem] border border-white/10">
                      <p className="text-[10px] font-black uppercase tracking-widest opacity-60 mb-1">Earned</p>
                      <p className="text-3xl font-black flex items-center gap-2 justify-center"><Coins size={24}/> {gameResult.coins}</p>
                    </div>
                    <div className="bg-white/20 px-8 py-4 rounded-[1.5rem] border border-white/10">
                      <p className="text-[10px] font-black uppercase tracking-widest opacity-60 mb-1">Exp Gain</p>
                      <p className="text-3xl font-black flex items-center gap-2 justify-center"><Sparkles size={24}/> {gameResult.exp}</p>
                    </div>
                 </div>
                 <div className="flex gap-4 max-w-sm mx-auto">
                    <button onClick={() => setGameMode(null)} className="flex-1 py-5 bg-white text-indigo-600 rounded-2xl font-black uppercase text-sm shadow-xl hover:scale-105 active:scale-95 transition-transform">Back to Hub</button>
                    <button onClick={() => shareAchievement(`METROPOLIS ALERT: My Guardian achieved Level ${user.petLevel}! Transmitting session results: ${gameResult.coins} Coins found! 🌌`)} className="flex-1 py-5 bg-yellow-400 text-white rounded-2xl font-black uppercase text-sm shadow-xl hover:scale-105 active:scale-95 transition-transform flex items-center justify-center gap-2">
                      <Share2 size={18}/> Share
                    </button>
                 </div>
               </div>
             ) : (
               <div className="space-y-8 py-10">
                  <div className="flex justify-between items-center bg-black/20 px-6 py-3 rounded-2xl">
                    <span className="text-sm font-black uppercase italic">{gameMode} ACTIVE</span>
                    <span className="flex items-center gap-2 font-black text-xl tabular-nums"><Timer size={20}/> {timeLeft}s</span>
                  </div>
                  {gameMode === 'tap' && (
                    <motion.button whileTap={{ scale: 0.8 }} onClick={() => setTapScore(s => s + 1)} className="w-44 h-44 bg-white rounded-full mx-auto text-indigo-600 text-7xl font-black shadow-[0_15px_0_0_#cbd5e1] flex items-center justify-center active:translate-y-2 active:shadow-none transition-all">
                      {tapScore}
                    </motion.button>
                  )}
                  {gameMode !== 'tap' && (
                    <div className="flex flex-col items-center gap-6">
                       <div className="animate-spin text-white opacity-40"><Zap size={64}/></div>
                       <p className="font-black italic uppercase text-2xl animate-pulse">Scanning Frequencies...</p>
                    </div>
                  )}
               </div>
             )}
          </div>
        )}

        {activeTab === 'Interaction' && (
          <div className="col-span-full space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
              {SLEEP_MODES.map(mode => (
                <button key={mode.id} onClick={() => startSleep(mode.id)} className={`p-6 rounded-[2.5rem] border-2 border-black/5 flex flex-col items-center justify-center gap-2 ${isDarkMode ? 'bg-[#111111] text-white' : 'bg-white text-slate-900'} shadow-md hover:scale-105 transition-transform active:translate-y-1`}>
                   <span className="text-4xl mb-2">{mode.emoji}</span>
                   <p className="font-black uppercase text-sm tracking-tight">{mode.name}</p>
                   <p className="text-[10px] opacity-40 font-bold mb-3">{mode.duration} Mins • +{mode.rest} Rest</p>
                   <div className="flex items-center gap-1.5 px-4 py-1.5 bg-yellow-400 text-white rounded-xl text-xs font-black shadow-sm"><Coins size={14}/> {mode.cost}</div>
                </button>
              ))}
            </div>

            <button onClick={() => { setPetting(true); onUpdate(0,0,0,0,5); setTimeout(() => setPetting(false), 1000); }} className="w-full p-8 rounded-[3rem] bg-[#e21b3c] text-white shadow-xl flex flex-col items-center justify-center gap-3 border-b-8 border-red-900 active:translate-y-2 active:border-b-0 transition-all group overflow-hidden relative">
               <Heart size={40} className={`group-hover:scale-125 transition-transform ${petting ? 'animate-ping' : ''}`} fill={petting ? "currentColor" : "none"} />
               <span className="font-black uppercase text-xl italic tracking-tighter">Citizen Interaction (+5 EXP)</span>
               <AnimatePresence>
                 {petting && <motion.div initial={{ scale: 0 }} animate={{ scale: 2 }} exit={{ scale: 0, opacity: 0 }} className="absolute text-white/20"><Heart size={200} fill="currentColor" /></motion.div>}
               </AnimatePresence>
            </button>
          </div>
        )}
      </div>

      <AnimatePresence>
        {showCoinAlert && (
          <div className="fixed inset-0 z-[600] flex items-center justify-center pointer-events-none p-6">
            <motion.div initial={{ scale: 0.5, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} exit={{ scale: 0.5, opacity: 0 }} className="bg-red-500 text-white px-10 py-6 rounded-[3rem] shadow-2xl flex items-center gap-5 border-4 border-white/20">
               <AlertCircle size={40} className="shrink-0" />
               <div className="text-left">
                 <p className="font-black text-2xl uppercase italic tracking-tighter">DEPLETED RESERVES</p>
                 <p className="text-[10px] font-bold uppercase tracking-widest opacity-80">Sync emotional frequencies in the Quiz or play games for more coins!</p>
               </div>
            </motion.div>
          </div>
        )}
      </AnimatePresence>

      <AnimatePresence>
        {showEmojiPicker && (
          <div className="fixed inset-0 z-[400] flex items-center justify-center p-6 bg-black/90 backdrop-blur-md">
            <motion.div initial={{ scale: 0.9, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} className={`${isDarkMode ? 'bg-[#111111]' : 'bg-white'} w-full max-w-md rounded-[3.5rem] p-10 shadow-2xl border-4 border-indigo-500/20`}>
              <div className="flex justify-between items-center mb-8">
                <h3 className={`text-2xl md:text-3xl font-black italic uppercase ${isDarkMode ? 'text-white' : 'text-slate-900'}`}>Transform Pet</h3>
                <button onClick={() => setShowEmojiPicker(false)} className="opacity-40 hover:opacity-100"><X size={36}/></button>
              </div>
              <p className="text-sm font-black uppercase opacity-40 mb-10 text-center flex items-center justify-center gap-2">Cost: <span className="text-yellow-500 flex items-center gap-1"><Coins size={16}/> 100</span></p>
              <div className="grid grid-cols-4 gap-4 max-h-72 overflow-y-auto pr-2 fading-scrollbar">
                {PET_OPTIONS.map(e => (
                  <button key={e} onClick={() => { if(checkCoins(100)) { onUpdate(0,0,0,-100,0,null,e); setShowEmojiPicker(false); } }} className={`text-4xl p-5 rounded-[2rem] border-2 transition-all hover:scale-110 active:scale-90 ${isDarkMode ? 'bg-[#1a1a1a] border-white/5' : 'bg-gray-50 border-black/5 shadow-inner'}`}>{e}</button>
                ))}
              </div>
              <button onClick={() => setShowEmojiPicker(false)} className="w-full mt-10 py-5 bg-gray-500 text-white rounded-[2rem] font-black uppercase text-sm shadow-lg">Abort Sync</button>
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </div>
  );
};

export default MoodPetSection;

import React, { useState, useEffect, useMemo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { User, Mood, Section, Post, Comment, Message, Notification } from './types';
import Sidebar from './components/Sidebar';
import MoodCheckIn from './components/MoodCheckIn';
import HomeSection from './sections/HomeSection';
import MoodSection from './sections/MoodSection';
import ZodiacSection from './sections/ZodiacSection';
import CityHallSection from './sections/CityHallSection';
import ProfileSection from './sections/ProfileSection';
import SettingsSection from './sections/SettingsSection';
import NotificationsSection from './sections/NotificationsSection';
import AuthScreen from './sections/AuthScreen';
import LoadingScreen from './components/LoadingScreen';
import { getExpNeeded, MOOD_SCORES, getTier } from './constants';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [activeSection, setActiveSection] = useState<Section>('Home');
  const [viewingUsername, setViewingUsername] = useState<string | null>(null);
  const [isMoodModalOpen, setIsMoodModalOpen] = useState(false);
  const [isDarkMode, setIsDarkMode] = useState(false); 
  const [isAppStarting, setIsAppStarting] = useState(true);

  const [allPosts, setAllPosts] = useState<Post[]>([]);
  const [allMessages, setAllMessages] = useState<Message[]>([]);
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);

  const profileToView = useMemo(() => {
    if (!viewingUsername) return null;
    if (currentUser && viewingUsername === currentUser.username) return currentUser;
    const allUsers: User[] = JSON.parse(localStorage.getItem('mooderia_all_users') || '[]');
    return allUsers.find(u => u.username === viewingUsername) || null;
  }, [viewingUsername, currentUser]);

  useEffect(() => {
    const savedUser = localStorage.getItem('mooderia_user');
    const savedPosts = localStorage.getItem('mooderia_posts') || '[]';
    const savedMessages = localStorage.getItem('mooderia_messages') || '[]';
    const savedNotifications = localStorage.getItem('mooderia_notifications') || '[]';
    const savedTheme = localStorage.getItem('mooderia_theme');

    if (savedUser) {
      const user: User = JSON.parse(savedUser);
      setCurrentUser(user);
      const todayStr = new Date().toDateString();
      if (user.lastMoodDate !== todayStr) {
        setIsMoodModalOpen(true);
      }
    }

    setAllPosts(JSON.parse(savedPosts));
    setAllMessages(JSON.parse(savedMessages));
    setNotifications(JSON.parse(savedNotifications));
    if (savedTheme === 'dark') setIsDarkMode(true);
    setIsLoaded(true);

    const timer = setTimeout(() => setIsAppStarting(false), 2000);
    return () => clearTimeout(timer);
  }, []);

  // Global Persistence Sync
  useEffect(() => {
    if (!isLoaded) return;
    if (currentUser) {
      localStorage.setItem('mooderia_user', JSON.stringify(currentUser));
      const allUsers: User[] = JSON.parse(localStorage.getItem('mooderia_all_users') || '[]');
      const idx = allUsers.findIndex(u => u.username === currentUser.username);
      if (idx > -1) {
        allUsers[idx] = currentUser;
        localStorage.setItem('mooderia_all_users', JSON.stringify(allUsers));
      }
    }
    localStorage.setItem('mooderia_posts', JSON.stringify(allPosts));
    localStorage.setItem('mooderia_messages', JSON.stringify(allMessages));
    localStorage.setItem('mooderia_notifications', JSON.stringify(notifications));
    localStorage.setItem('mooderia_theme', isDarkMode ? 'dark' : 'light');
  }, [currentUser, allPosts, allMessages, notifications, isDarkMode, isLoaded]);

  const handleEditProfile = (displayName: string, username: string, profilePic?: string, title?: string, bannerPic?: string, profileColor?: string, bio?: string) => {
    if (!currentUser) return;
    const updatedUser = {
      ...currentUser,
      displayName: displayName.slice(0, 20),
      username,
      profilePic: profilePic || currentUser.profilePic,
      title: title || currentUser.title,
      profileColor: profileColor || currentUser.profileColor,
      bio: bio || currentUser.bio
    };
    setCurrentUser(updatedUser);
  };

  const updatePetStats = (hunger: number, thirst: number, rest: number, coins: number, exp: number = 0, sleepUntil: number | null = null, newEmoji?: string, markChosen?: boolean) => {
    if (!currentUser) return;
    let newLevel = currentUser.petLevel;
    let newExp = currentUser.petExp + exp;
    while (newExp >= getExpNeeded(newLevel)) {
      newExp -= getExpNeeded(newLevel);
      newLevel += 1;
    }
    setCurrentUser({
      ...currentUser,
      petHunger: Math.min(100, Math.max(0, currentUser.petHunger + hunger)),
      petThirst: Math.min(100, Math.max(0, currentUser.petThirst + thirst)),
      petRest: Math.min(100, Math.max(0, currentUser.petRest + rest)),
      petExp: newExp,
      petLevel: newLevel,
      moodCoins: currentUser.moodCoins + coins,
      petSleepUntil: sleepUntil !== undefined ? sleepUntil : currentUser.petSleepUntil,
      petEmoji: newEmoji || currentUser.petEmoji,
      petHasBeenChosen: markChosen !== undefined ? markChosen : currentUser.petHasBeenChosen,
      petLastUpdate: Date.now()
    });
  };

  const handleLogin = (user: User) => {
    setCurrentUser(user);
    const todayStr = new Date().toDateString();
    if (user.lastMoodDate !== todayStr) {
      setIsMoodModalOpen(true);
    }
