const MoodPetSection: React.FC<MoodPetSectionProps> = ({ user, isDarkMode, onUpdate, onPost }) => {
  const [activeTab, setActiveTab] = useState<'Interaction' | 'Shop' | 'Games'>('Interaction');
  const [gameMode, setGameMode] = useState<string | null>(null);
  const [gameResult, setGameResult] = useState<{ coins: number, exp: number } | null>(null);
  const [timeLeft, setTimeLeft] = useState(0);
  const [showEmojiPicker, setShowEmojiPicker] = useState(false);
  const [showCoinAlert, setShowCoinAlert] = useState(false);
  const [showNameEdit, setShowNameEdit] = useState(false);
  const [tempName, setTempName] = useState(user.petName || '');
  const [petting, setPetting] = useState(false);
  const [tapScore, setTapScore] = useState(0);

  // New Selection State
  const [selectedInitialEmoji, setSelectedInitialEmoji] = useState<string | null>(null);
  const [initialPetName, setInitialPetName] = useState('');

  const isSleeping = user.petSleepUntil && user.petSleepUntil > Date.now();

  useEffect(() => {
    let timer: number;
    if (gameMode && timeLeft > 0) {
      timer = window.setInterval(() => setTimeLeft(prev => prev - 1), 1000);
    } else if (gameMode && timeLeft === 0) {
      finishGame();
    }
    return () => clearInterval(timer);
  }, [gameMode, timeLeft]);

  const finishGame = () => {
    let coins = 0;
    let exp = 0;
    if (gameMode === 'tap') {
      coins = Math.min(60, tapScore * 3);
      exp = tapScore * 10;
    } else {
      coins = Math.floor(Math.random() * 30) + 20;
      exp = coins * 3;
    }
    setGameResult({ coins, exp });
    onUpdate(-15, -15, -20, coins, exp);
  };

  const startLevelGame = (id: string) => {
    if (user.petRest < 25) {
      alert("Guardian is too exhausted! Let them sleep first.");
      return;
    }
    const config = GAMES.find(g => g.id === id);
    if (!config) return;
    setGameMode(id);
    setTimeLeft(config.time);
    setGameResult(null);
    if (id === 'tap') setTapScore(0);
  };

  const checkCoins = (cost: number) => {
    if (user.moodCoins < cost) {
      setShowCoinAlert(true);
      setTimeout(() => setShowCoinAlert(false), 2000);
      return false;
    }
    return true;
  };

  const startSleep = (modeId: string) => {
    const mode = SLEEP_MODES.find(m => m.id === modeId);
    if (!mode) return;
    if (!checkCoins(mode.cost)) return;
    onUpdate(0, 0, mode.rest, -mode.cost, mode.exp, Date.now() + mode.duration * 60 * 1000);
  };

  const handleInitialSummon = () => {
    if (!selectedInitialEmoji || !initialPetName.trim()) return;
    onUpdate(0, 0, 0, 0, 0, null, selectedInitialEmoji, true, initialPetName.trim());
  };

  const handleRename = () => {
    if (!tempName.trim()) return;
    onUpdate(0, 0, 0, 0, 0, null, undefined, undefined, tempName.trim());
    setShowNameEdit(false);
  };

  if (!user.petHasBeenChosen) {
    return (
      <div className={`flex flex-col items-center justify-center p-8 md:p-12 text-center ${isDarkMode ? 'bg-[#111111]' : 'bg-white'} rounded-[3rem] shadow-2xl border border-black/5`}>
