          />
        </div>

        <p className="text-[10px] font-black uppercase opacity-40 mb-4 tracking-widest">2. Choose Frequency Form</p>
        <div className="grid grid-cols-5 gap-3 max-w-md mx-auto mb-10 overflow-y-auto max-h-48 p-2 custom-scrollbar border-2 border-black/5 rounded-3xl">
          {PET_OPTIONS.map(e => (
            <button 
              key={e} 
              onClick={() => setSelectedInitialEmoji(e)} 
              className={`text-2xl p-4 rounded-2xl border-2 transition-all ${selectedInitialEmoji === e ? 'border-indigo-500 bg-indigo-500/10 scale-110 shadow-lg' : isDarkMode ? 'bg-[#1a1a1a] border-white/5' : 'bg-gray-50 border-gray-100 shadow-inner'}`}
            >
