            </button>
          ))}
        </div>

        <button 
          onClick={handleInitialSummon}
          disabled={!selectedInitialEmoji || !initialPetName.trim()}
          className={`kahoot-button-purple w-full max-w-sm py-5 rounded-[2rem] text-white font-black uppercase text-xl shadow-xl ${(!selectedInitialEmoji || !initialPetName.trim()) ? 'opacity-30' : ''}`}
        >
