interface ProfileSectionProps {
  user: User;
  allPosts: Post[];
  isDarkMode: boolean;
  currentUser: User;
  onEditProfile?: (displayName: string, username: string, profilePic?: string, title?: string, bannerPic?: string, profileColor?: string, bio?: string) => void;
  onBlock?: (username: string) => void;
  onFollow?: (username: string) => void;
  onShareToExpress?: (msg: string) => void;
}

const ProfileSection: React.FC<ProfileSectionProps> = ({ user, allPosts, isDarkMode, currentUser, onEditProfile, onBlock, onFollow, onShareToExpress }) => {
  const [isEditing, setIsEditing] = useState(false);
  const [activeTab, setActiveTab] = useState<'Posts' | 'Reposts' | 'Stats'>('Posts');

  const [editForm, setEditForm] = useState({
    displayName: user.displayName,
    username: user.username,
    profilePic: user.profilePic || '',
    title: user.title || 'Citizen',
    profileColor: user.profileColor || '#e21b3c',
    bio: user.bio || ''
  });

  const isOwnProfile = currentUser.username === user.username;
  const isFollowing = currentUser.following.includes(user.username);

  const myPosts = useMemo(() => allPosts.filter(p => p.author === user.username && !p.isRepost), [allPosts, user.username]);
  const myReposts = useMemo(() => allPosts.filter(p => p.author === user.username && p.isRepost), [allPosts, user.username]);

  const handleSave = () => {
    if (onEditProfile) {
      onEditProfile(
        editForm.displayName.slice(0, 20),
        editForm.username,
        editForm.profilePic,
        editForm.title,
        undefined,
        editForm.profileColor,
        editForm.bio
      );
    }
    setIsEditing(false);
  };

  const accentColor = user.profileColor || '#e21b3c';

  const chartData = useMemo(() => {
    if (!user.moodHistory || user.moodHistory.length === 0) {
      return [{ name: 'N/A', score: 0 }];
    }
    return user.moodHistory.slice(-10).map((entry, idx) => ({
      name: `T${idx + 1}`,
      score: entry.score
    }));
  }, [user.moodHistory]);

  // Dynamic font size for display name
  const getFontSize = (name: string) => {
    if (name.length > 15) return 'text-xl md:text-3xl';
    if (name.length > 10) return 'text-2xl md:text-4xl';
    return 'text-3xl md:text-5xl';
  };

  return (
    <div className="flex flex-col gap-6 pb-20">
      <div className={`${isDarkMode ? 'bg-[#111111]' : 'bg-white'} rounded-[2.5rem] overflow-hidden shadow-2xl border border-black/5`}>
        <div className="h-28 md:h-36 w-full relative overflow-hidden" style={{ backgroundColor: accentColor }}>
          <div className="absolute inset-0 flex items-center justify-center pointer-events-none opacity-20 rotate-[-10deg] scale-110 whitespace-nowrap">
             <span className="text-white text-3xl md:text-5xl font-black uppercase tracking-widest italic select-none">
               {user.title} {user.title} {user.title} {user.title}
             </span>
          </div>
        </div>

        <div className="px-6 md:px-10 pb-8 flex flex-col md:flex-row items-center md:items-end gap-6 -mt-12 md:-mt-16">
