               <span className="text-[10px] font-black uppercase tracking-widest text-[#e21b3c] italic">{user.title}</span>
            </div>
            <h2 className={`${getFontSize(user.displayName)} font-black italic uppercase tracking-tighter leading-none mb-1 ${isDarkMode ? 'text-white' : 'text-slate-900'}`}>
              {user.displayName}
            </h2>
            <p className={`text-sm md:text-lg font-bold uppercase tracking-tighter opacity-40 ${isDarkMode ? 'text-white' : 'text-slate-900'}`}>@{user.username}</p>
