            {isOwnProfile ? (
              <button onClick={() => setIsEditing(true)} className="w-full md:w-auto kahoot-button-red flex items-center justify-center gap-2 px-8 py-3.5 text-white rounded-2xl font-black text-xs md:text-sm uppercase shadow-lg">
