              <button onClick={() => onFollow?.(user.username)} className={`w-full md:w-auto px-8 py-3.5 text-white rounded-2xl font-black text-xs md:text-sm uppercase shadow-lg transition-all flex items-center justify-center gap-2 ${isFollowing ? 'bg-red-500/20 border border-red-500/50 text-red-500' : 'bg-[#e21b3c]'}`}>
                {isFollowing ? <UserMinus size={18}/> : <UserPlus size={18}/>}
                {isFollowing ? 'UNFOLLOW' : 'FOLLOW CITIZEN'}
