                <textarea value={editForm.bio} onChange={e => setEditForm({...editForm, bio: e.target.value})} placeholder="Express your personality (Bio)..." className={`w-full ${isDarkMode ? 'bg-[#1a1a1a] text-white' : 'bg-gray-50 text-slate-900'} border-2 border-black/5 p-4 md:p-5 rounded-2xl font-bold outline-none focus:border-[#e21b3c]`} rows={3} />
                <select value={editForm.title} onChange={e => setEditForm({...editForm, title: e.target.value})} className={`w-full ${isDarkMode ? 'bg-[#1a1a1a] text-white' : 'bg-gray-50 text-slate-900'} border-2 border-black/5 p-4 md:p-5 rounded-2xl font-bold outline-none focus:border-[#e21b3c]`}>
