                     <button key={c} onClick={() => setEditForm({...editForm, profileColor: c})} className={`w-10 h-10 rounded-full border-4 ${editForm.profileColor === c ? 'border-black' : 'border-transparent'}`} style={{ backgroundColor: c }} />
