                </div>
                <button onClick={handleSave} className="w-full py-5 md:py-6 bg-[#e21b3c] text-white rounded-3xl font-black text-lg md:text-xl uppercase shadow-[0_8px_0_0_#b31530]">Authorize Sync</button>
