  const getLuckyData = (sign: string) => {
    const today = new Date().toDateString();
    const seed = sign + today;
    let hash = 0;
    for (let i = 0; i < seed.length; i++) hash = seed.charCodeAt(i) + ((hash << 5) - hash);
    const colors = [
      { name: "Ruby Red", hex: "#e21b3c" },
      { name: "Emerald Green", hex: "#26890c" },
      { name: "Azure Blue", hex: "#1368ce" },
      { name: "Goldenrod", hex: "#ffa602" },
      { name: "Purple", hex: "#46178f" }
    ];
    const phrases = ["Great opportunities await in social hubs.", "Focus on self-care today.", "Your creative energy is peaking.", "A surprise connection might occur."];
    return { color: colors[Math.abs(hash) % colors.length], number: (Math.abs(hash) % 99) + 1, phrase: phrases[Math.abs(hash) % phrases.length] };
  };

  const currentLucky = useMemo(() => getLuckyData(luckyZodiac), [luckyZodiac]);

