    <select value={val} onChange={(e) => setVal(parseInt(e.target.value))} className={`flex-1 ${isDarkMode ? 'bg-[#1a1a1a] text-white' : 'bg-gray-50 text-black'} p-3 md:p-4 rounded-xl font-black border-2 border-black/5 text-[10px] md:text-xs outline-none focus:border-[#26890c]`}>
      {MONTHS.map((m, i) => <option key={m} value={i + 1}>{m}</option>)}
