          >
            {t.replace(/([A-Z])/g, ' $1').trim()}
          </button>
        ))}
      </div>

      <div className="flex-1 fading-scrollbar overflow-y-auto pr-1">
        <div className="pb-16">
          <AnimatePresence mode="wait">
            {tab === 'LoveMatcher' && (
              <motion.div key="love" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className={`p-8 md:p-10 rounded-[3rem] ${isDarkMode ? 'bg-[#111111]' : 'bg-white'} border border-black/5 shadow-2xl text-center`}>
                <Heart className="mx-auto mb-8 text-[#e21b3c] animate-pulse" size={64} />
