                <button disabled={isLoading} onClick={handleMatch} className="kahoot-button-red px-12 md:px-16 py-4 md:py-5 rounded-2xl md:rounded-3xl text-white font-black text-xl md:text-2xl uppercase shadow-lg">
                  {isLoading ? 'SYNCING...' : 'REVEAL CONNECTION'}
                </button>

                {matchResult && (
                  <motion.div initial={{ scale: 0.9, y: 20 }} animate={{ scale: 1, y: 0 }} className="mt-10 md:mt-12 p-8 md:p-10 rounded-[2.5rem] border-4 border-[#e21b3c]/20 bg-[#e21b3c]/5 max-w-xl mx-auto">
                    <p className="text-5xl md:text-7xl font-black text-[#e21b3c] mb-4 italic tracking-tighter">{matchResult.percentage}%</p>
                    <p className={`text-sm md:text-base font-bold opacity-80 leading-relaxed italic ${isDarkMode ? 'text-white' : 'text-black'}`}>{matchResult.reason}</p>
