                 </div>

                 <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    {ZODIACS.map(z => (
                      <div key={z.name} className={`p-8 rounded-[2.5rem] ${isDarkMode ? 'bg-slate-800' : 'bg-white'} border-2 border-black/5 shadow-lg group hover:border-emerald-500/50 transition-colors`}>
                        <div className="flex items-center justify-between mb-4">
                           <div className="flex items-center gap-4">
                              <span className="text-4xl select-none">{z.symbol}</span>
                              <div>
                                <h3 className="text-xl font-black uppercase italic tracking-tight">{z.name}</h3>
