                     <p className="text-[9px] md:text-[10px] font-black uppercase mb-3 opacity-60 tracking-[0.4em]">Color</p>
                     <p className="text-2xl md:text-3xl font-black italic tracking-tighter">{currentLucky.color.name}</p>
                  </motion.div>
                  <motion.div whileHover={{ scale: 1.05 }} className={`p-6 md:p-8 rounded-[2rem] ${isDarkMode ? 'bg-slate-800' : 'bg-white'} border-4 shadow-xl transition-colors duration-500`} style={{ borderColor: currentLucky.color.hex }}>
                     <p className="text-[9px] md:text-[10px] font-black uppercase mb-3 opacity-60 tracking-[0.4em]" style={{ color: currentLucky.color.hex }}>Number</p>
                     <p className="text-5xl md:text-6xl font-black italic tracking-tighter tabular-nums" style={{ color: currentLucky.color.hex }}>{currentLucky.number}</p>
