  const [showEmojiPicker, setShowEmojiPicker] = useState(false);
  const [showCoinAlert, setShowCoinAlert] = useState(false);
  const [showNameEdit, setShowNameEdit] = useState(false);
  const [tempName, setTempName] = useState(user.petName || '');
  const [petting, setPetting] = useState(false);

  // Game States
  const [tapScore, setTapScore] = useState(0);
  const [vibeTargets, setVibeTargets] = useState<{ id: number, x: number, y: number, emoji: string, size: number, speed: number }[]>([]);
  const [mathProblem, setMathProblem] = useState({ q: '', a: 0 });
  const [mathInput, setMathInput] = useState('');
  const [feedback, setFeedback] = useState<'correct' | 'wrong' | null>(null);
  const [floatingTexts, setFloatingTexts] = useState<{id: number, text: string, x: number, y: number}[]>([]);

  const isSleeping = user.petSleepUntil && user.petSleepUntil > Date.now();

  useEffect(() => {
    let timer: number;
    if (gameMode && timeLeft > 0) {
      timer = window.setInterval(() => setTimeLeft(prev => prev - 1), 1000);
    } else if (gameMode && timeLeft === 0) {
      finishGame();
    }
    return () => clearInterval(timer);
  }, [gameMode, timeLeft]);

  // Vibe Hunter Spawner
  useEffect(() => {
    if (gameMode !== 'hunter' || timeLeft <= 0) return;
    const interval = setInterval(() => {
      const vibes = ['✨', '🔥', '💖', '⭐', '🌈', '💎'];
      const newVibe = {
        id: Date.now(),
        x: Math.random() * 80 + 10,
        y: Math.random() * 80 + 10,
        emoji: vibes[Math.floor(Math.random() * vibes.length)],
        size: Math.random() * 30 + 30,
        speed: Math.random() * 1.5 + 0.5
      };
      setVibeTargets(prev => [...prev.slice(-10), newVibe]);
    }, 800);
    return () => clearInterval(interval);
  }, [gameMode, timeLeft]);

  const finishGame = () => {
    let coins = 0;
    let exp = 0;
    if (gameMode === 'clicker') {
      coins = Math.min(50, tapScore * 2);
      exp = tapScore * 5;
    } else if (gameMode === 'hunter') {
      coins = Math.min(60, tapScore * 4);
      exp = tapScore * 8;
    } else if (gameMode === 'math') {
      coins = Math.min(100, tapScore * 10);
      exp = tapScore * 20;
    }
    setGameResult({ coins, exp });
    onUpdate(-15, -15, -20, coins, exp, null, undefined, undefined, undefined, gameMode!);
    setVibeTargets([]);
  };

  const startLevelGame = (id: string) => {
    const cooldown = user.gameCooldowns?.[id];
    if (cooldown && cooldown > Date.now()) {
      const wait = Math.ceil((cooldown - Date.now()) / 1000);
      alert(`Terminal cooling down! Wait ${wait}s.`);
      return;
    }
    if (user.petRest < 25) {
      alert("Guardian is too exhausted! Let them sleep first.");
      return;
    }
    const config = GAMES.find(g => g.id === id);
    if (!config) return;
    setGameMode(id);
    setTimeLeft(config.time);
    setGameResult(null);
    setTapScore(0);
    if (id === 'math') generateMath();
  };

  const generateMath = () => {
    const a = Math.floor(Math.random() * 12) + 1;
    const b = Math.floor(Math.random() * 12) + 1;
    setMathProblem({ q: `${a} + ${b} = ?`, a: a + b });
    setMathInput('');
  };

  const checkMath = (e: React.FormEvent) => {
    e.preventDefault();
    if (parseInt(mathInput) === mathProblem.a) {
      setTapScore(s => s + 1);
      setFeedback('correct');
      setTimeout(() => { setFeedback(null); generateMath(); }, 400);
    } else {
      setFeedback('wrong');
      setTimeout(() => setFeedback(null), 400);
    }
  };

  const spawnFloatingText = (text: string, x: number, y: number) => {
    const id = Date.now();
    setFloatingTexts(prev => [...prev, { id, text, x, y }]);
    setTimeout(() => setFloatingTexts(prev => prev.filter(f => f.id !== id)), 800);
  };

  const checkCoins = (cost: number) => {
    if (user.moodCoins < cost) {
      setShowCoinAlert(true);
      setTimeout(() => setShowCoinAlert(false), 2000);
      return false;
    }
    return true;
  };

  const startSleep = (modeId: string) => {
    const mode = SLEEP_MODES.find(m => m.id === modeId);
    if (!mode) return;
    if (!checkCoins(mode.cost)) return;
    onUpdate(0, 0, mode.rest, -mode.cost, mode.exp, Date.now() + mode.duration * 60 * 1000);
  };

  const handleRename = () => {
    if (!tempName.trim()) return;
    onUpdate(0, 0, 0, 0, 0, null, undefined, undefined, tempName.trim());
    setShowNameEdit(false);
  };

  if (!user.petHasBeenChosen) {
    return (
      <div className={`flex flex-col items-center justify-center p-8 md:p-12 text-center ${isDarkMode ? 'bg-[#111111]' : 'bg-white'} rounded-[3rem] shadow-2xl border border-black/5`}>
        <h3 className={`text-3xl font-black italic uppercase mb-8 tracking-tighter ${isDarkMode ? 'text-white' : 'text-slate-900'}`}>Summon a Guardian</h3>
        <div className="w-full max-w-sm mb-8">
          <p className="text-[10px] font-black uppercase opacity-40 mb-3 tracking-widest">1. Name your Protector</p>
          <input type="text" value={tempName} onChange={e => setTempName(e.target.value)} placeholder="Protector Name..." className={`w-full p-4 rounded-2xl border-2 font-bold outline-none text-center ${isDarkMode ? 'bg-slate-800 border-slate-700 text-white' : 'bg-gray-50 border-gray-200'}`} />
        </div>
        <div className="grid grid-cols-5 gap-3 max-w-md mx-auto mb-10 overflow-y-auto max-h-48 p-2 custom-scrollbar border-2 border-black/5 rounded-3xl">
          {PET_OPTIONS.map(e => (
            <button key={e} onClick={() => onUpdate(0, 0, 0, 0, 0, null, e, true, tempName)} className={`text-2xl p-4 rounded-2xl border-2 transition-all hover:scale-110 active:scale-90 ${isDarkMode ? 'bg-[#1a1a1a] border-white/5' : 'bg-gray-50 border-gray-100 shadow-inner'}`}>{e}</button>
          ))}
        </div>
      </div>
    );
  }

  return (
    <div className="flex flex-col gap-6 relative">
      <div className={`p-8 rounded-[3rem] ${isDarkMode ? 'bg-[#111111] text-white' : 'bg-white text-slate-900'} border border-black/5 shadow-2xl flex flex-col items-center justify-center relative overflow-hidden`}>
        <AnimatePresence>
          {isSleeping && (
            <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="absolute inset-0 z-50 bg-indigo-900/90 flex flex-col items-center justify-center text-white backdrop-blur-md p-6 text-center">
               <Lock size={64} className="mb-4 animate-pulse text-indigo-300" />
               <h4 className="text-3xl font-black uppercase italic tracking-tighter">REST MODE ACTIVATED</h4>
               <p className="text-[10px] font-black uppercase tracking-[0.3em] opacity-60">Do not disturb {user.petName}'s frequency.</p>
               <div className="mt-8 bg-black/30 px-6 py-4 rounded-[2rem] flex items-center gap-3 font-black text-xl border-2 border-white/10">
                 <Timer size={24}/> {Math.ceil((user.petSleepUntil! - Date.now()) / (1000 * 60))} Mins Left
               </div>
            </motion.div>
          )}
        </AnimatePresence>

        <div className="absolute top-6 left-6 flex items-center gap-2 bg-yellow-400 px-4 py-2 rounded-2xl text-white font-black text-xs shadow-lg">
          <Coins size={16}/> {user.moodCoins}
        </div>
        <div className="absolute top-6 right-6 flex gap-2">
          <button onClick={() => setShowNameEdit(true)} className="p-3 bg-green-500 text-white rounded-2xl font-black text-xs shadow-lg hover:scale-110 active:scale-90 transition-transform">
            <PenTool size={18}/>
          </button>
          <button onClick={() => setShowEmojiPicker(true)} className="p-3 bg-indigo-500 text-white rounded-2xl font-black text-xs shadow-lg hover:scale-110 active:scale-90 transition-transform">
            <Wand2 size={18}/>
          </button>
        </div>

        <div className="text-center mb-6 mt-4">
           <h3 className="text-2xl font-black italic uppercase tracking-tighter">{user.petName}</h3>
           <p className="text-[10px] font-black opacity-30 uppercase tracking-[0.2em]">Guardian Tier: {user.petLevel >= 10 ? 'Mythic' : user.petLevel >= 5 ? 'Protector' : 'Kin'}</p>
        </div>

        <motion.div animate={{ y: [0, -15, 0], rotate: [0, 2, -2, 0] }} transition={{ duration: 5, repeat: Infinity }} className="text-[120px] md:text-[150px] mb-8 select-none flex items-center justify-center">
          {user.petEmoji}
        </motion.div>

        <div className="w-full max-w-sm grid grid-cols-3 gap-4">
           {[
             { label: 'Hunger', val: user.petHunger, color: 'bg-red-500', icon: <Utensils size={14} /> },
             { label: 'Thirst', val: user.petThirst, color: 'bg-blue-500', icon: <Droplets size={14} /> },
             { label: 'Rest', val: user.petRest, color: 'bg-green-500', icon: <Zap size={14} /> },
           ].map(bar => (
             <div key={bar.label} className="flex flex-col items-center gap-2">
               <div className="flex items-center justify-center gap-1 text-[8px] font-black uppercase opacity-40">{bar.icon} {bar.val}%</div>
               <div className="w-full h-2.5 bg-black/5 rounded-full overflow-hidden">
                 <motion.div initial={{ width: 0 }} animate={{ width: `${bar.val}%` }} className={`h-full ${bar.color} rounded-full`} />
               </div>
             </div>
           ))}
        </div>

        <div className="mt-6 flex flex-col items-center">
           <p className="text-[10px] font-black uppercase opacity-30 tracking-widest mb-1">Guardian Level {user.petLevel}</p>
           <div className="w-48 h-2 bg-black/5 rounded-full overflow-hidden">
              <motion.div initial={{ width: 0 }} animate={{ width: `${(user.petExp / getExpNeeded(user.petLevel)) * 100}%` }} className="h-full bg-indigo-500" />
           </div>
        </div>
      </div>

      <div className="flex gap-2 shrink-0">
        {(['Interaction', 'Shop', 'Games'] as const).map(tab => (
          <button key={tab} onClick={() => setActiveTab(tab)} className={`flex-1 py-4 rounded-2xl font-black text-[10px] uppercase border-b-4 transition-all ${activeTab === tab ? 'bg-[#1368ce] border-[#0e4c99] text-white shadow-lg' : isDarkMode ? 'bg-[#111111] border-black text-white/30' : 'bg-white border-gray-100 text-slate-500 shadow-sm'}`}>{tab}</button>
        ))}
      </div>

      <div className="grid grid-cols-2 md:grid-cols-3 gap-4 pb-20">
        {activeTab === 'Shop' && ITEMS.map(item => (
          <button key={item.id} onClick={() => { if(checkCoins(item.cost)) onUpdate(item.type === 'hunger' ? item.fill : 0, item.type === 'thirst' ? item.fill : 0, 0, -item.cost, 15); }} className={`p-6 rounded-[2rem] border-2 border-black/5 flex flex-col items-center justify-center text-center gap-2 ${isDarkMode ? 'bg-[#111111] text-white' : 'bg-white text-slate-900'} shadow-md hover:scale-105 active:scale-95 transition-transform`}>
            <span className="text-4xl">{item.emoji}</span>
            <span className="text-[10px] font-black uppercase opacity-40">{item.name}</span>
            <div className="bg-yellow-400 text-white px-3 py-1 rounded-xl text-[10px] font-black flex items-center justify-center gap-1 shadow-sm"><Coins size={12}/> {item.cost}</div>
          </button>
        ))}

        {activeTab === 'Games' && !gameMode && GAMES.map(game => {
          const cd = user.gameCooldowns?.[game.id];
          const isOff = cd && cd > Date.now();
          return (
            <button key={game.id} onClick={() => startLevelGame(game.id)} className={`relative p-6 rounded-[2rem] border-2 border-black/5 flex flex-col items-center justify-center text-center gap-2 ${isDarkMode ? 'bg-[#111111] text-white' : 'bg-white text-slate-900'} shadow-md transition-all hover:scale-105 group overflow-hidden ${isOff ? 'opacity-50 grayscale' : ''}`}>
              <span className="text-4xl group-hover:scale-125 transition-transform">{game.emoji}</span>
              <span className="text-[10px] font-black uppercase opacity-40 leading-none">{game.name}</span>
              {isOff && <div className="absolute inset-0 bg-black/40 flex items-center justify-center font-black text-white text-[10px] uppercase tracking-tighter">Cooldown</div>}
            </button>
          );
        })}

        {gameMode && (
          <div className="col-span-full min-h-[300px] p-8 bg-indigo-500 rounded-[3rem] text-white text-center shadow-2xl relative border-4 border-white/20 overflow-hidden">
             {gameResult ? (
               <div className="h-full flex flex-col items-center justify-center space-y-6">
                 <motion.div initial={{ scale: 0 }} animate={{ scale: 1 }} className="flex flex-col items-center">
                   <Trophy size={80} className="text-yellow-300 mb-4" />
                   <h4 className="text-3xl font-black italic uppercase tracking-tighter">TERMINAL DATA SYNCED</h4>
                 </motion.div>
                 <div className="flex justify-center gap-6">
                    <div className="bg-white/20 px-8 py-4 rounded-[1.5rem] border border-white/10">
                      <p className="text-[10px] font-black uppercase opacity-60 mb-1">User Rewards</p>
                      <p className="text-3xl font-black flex items-center gap-2 justify-center"><Coins size={24}/> {gameResult.coins}</p>
                    </div>
                    <div className="bg-white/20 px-8 py-4 rounded-[1.5rem] border border-white/10">
                      <p className="text-[10px] font-black uppercase opacity-60 mb-1">Guardian Exp</p>
                      <p className="text-3xl font-black flex items-center gap-2 justify-center"><Sparkles size={24}/> {gameResult.exp}</p>
                    </div>
                 </div>
                 <button onClick={() => setGameMode(null)} className="w-full max-w-sm py-5 bg-white text-indigo-600 rounded-2xl font-black uppercase text-sm shadow-xl hover:scale-105 active:scale-95 transition-transform">Close Terminal</button>
               </div>
             ) : (
               <div className="h-full flex flex-col space-y-4">
                  <div className="flex justify-between items-center bg-black/20 px-6 py-3 rounded-2xl shrink-0">
                    <span className="text-sm font-black uppercase italic">{gameMode} ACTIVE</span>
                    <span className="flex items-center gap-2 font-black text-xl tabular-nums"><Timer size={20}/> {timeLeft}s</span>
                  </div>

                  <div className="flex-1 flex flex-col items-center justify-center relative">
                    <AnimatePresence>
                      {floatingTexts.map(f => (
                        <motion.div key={f.id} initial={{ y: f.y, x: f.x, opacity: 1 }} animate={{ y: f.y - 100, opacity: 0 }} className="absolute z-10 pointer-events-none font-black text-2xl text-yellow-300">
                          {f.text}
                        </motion.div>
                      ))}
                    </AnimatePresence>

                    {gameMode === 'clicker' && (
                      <motion.div 
                        whileTap={{ scale: 0.8 }} 
                        onClick={(e) => { 
                          setTapScore(s => s + 1); 
                          spawnFloatingText("+2", (e.nativeEvent as any).offsetX, (e.nativeEvent as any).offsetY); 
                        }} 
                        className="w-44 h-44 bg-yellow-400 rounded-full text-white text-7xl font-black shadow-[0_15px_0_0_#ca8a04] flex items-center justify-center active:translate-y-2 active:shadow-none transition-all cursor-pointer relative"
                      >
                        <Coins size={80} />
                        <div className="absolute -bottom-8 bg-black/30 px-4 py-1 rounded-full text-xl">{tapScore}</div>
                      </motion.div>
                    )}

                    {gameMode === 'hunter' && (
                      <div className="w-full h-full min-h-[200px] relative overflow-hidden bg-black/10 rounded-2xl">
                        <AnimatePresence>
                          {vibeTargets.map(v => (
                            <motion.button
                              key={v.id}
                              initial={{ scale: 0, opacity: 0 }}
                              animate={{ scale: 1, opacity: 1 }}
                              exit={{ scale: 0, opacity: 0 }}
                              onClick={() => { 
                                setTapScore(s => s + 1); 
                                spawnFloatingText("+4", v.x, v.y);
                                setVibeTargets(prev => prev.filter(vt => vt.id !== v.id));
                              }}
                              className="absolute z-10 p-2 cursor-pointer transition-transform hover:scale-110"
                              style={{ left: `${v.x}%`, top: `${v.y}%`, fontSize: `${v.size}px` }}
                            >
                              {v.emoji}
                            </motion.button>
                          ))}
                        </AnimatePresence>
                        <div className="absolute bottom-2 left-2 font-black opacity-40 uppercase text-[10px]">Vibes Captured: {tapScore}</div>
                      </div>
                    )}

                    {gameMode === 'math' && (
                      <div className="flex flex-col items-center gap-8 w-full max-w-sm">
                        <motion.h4 
                          animate={{ scale: [1, 1.05, 1] }} 
                          transition={{ duration: 0.5, repeat: Infinity }}
                          className="text-6xl font-black italic tracking-tighter"
                        >
                          {mathProblem.q}
                        </motion.h4>
                        <form onSubmit={checkMath} className="w-full flex gap-2">
                           <input 
                             type="number" 
                             autoFocus
                             value={mathInput} 
                             onChange={e => setMathInput(e.target.value)} 
                             className={`flex-1 p-5 rounded-3xl bg-white text-indigo-600 font-black text-2xl text-center outline-none border-4 transition-colors ${feedback === 'correct' ? 'border-green-500' : feedback === 'wrong' ? 'border-red-500' : 'border-transparent'}`} 
                             placeholder="?"
                           />
                           <button type="submit" className="p-5 bg-yellow-400 rounded-3xl shadow-lg"><CheckCircle size={32}/></button>
                        </form>
                        <div className="flex items-center gap-2 font-black text-xl"><Target size={24}/> Score: {tapScore}</div>
                      </div>
                    )}
                  </div>
               </div>
             )}
          </div>
        )}

        {activeTab === 'Interaction' && (
          <div className="col-span-full space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
              {SLEEP_MODES.map(mode => (
                <button key={mode.id} onClick={() => startSleep(mode.id)} className={`p-6 rounded-[2.5rem] border-2 border-black/5 flex flex-col items-center justify-center gap-2 ${isDarkMode ? 'bg-[#111111] text-white' : 'bg-white text-slate-900'} shadow-md hover:scale-105 transition-transform active:translate-y-1`}>
                   <span className="text-4xl mb-2">{mode.emoji}</span>
                   <p className="font-black uppercase text-sm tracking-tight">{mode.name}</p>
                   <p className="text-[10px] opacity-40 font-bold mb-3">{mode.duration} Mins • +{mode.rest} Rest</p>
                   <div className="flex items-center gap-1.5 px-4 py-1.5 bg-yellow-400 text-white rounded-xl text-xs font-black shadow-sm"><Coins size={14}/> {mode.cost}</div>
                </button>
              ))}
            </div>
            <button onClick={() => { setPetting(true); onUpdate(0,0,0,0,5); setTimeout(() => setPetting(false), 1000); }} className="w-full p-8 rounded-[3rem] bg-[#e21b3c] text-white shadow-xl flex flex-col items-center justify-center gap-3 border-b-8 border-red-900 active:translate-y-2 active:border-b-0 transition-all group overflow-hidden relative">
               <Heart size={40} className={`group-hover:scale-125 transition-transform ${petting ? 'animate-ping' : ''}`} fill={petting ? "currentColor" : "none"} />
               <span className="font-black uppercase text-xl italic tracking-tighter">Citizen Interaction (+5 EXP)</span>
            </button>
          </div>
        )}
      </div>

      <AnimatePresence>
        {showNameEdit && (
          <div className="fixed inset-0 z-[600] flex items-center justify-center p-6 bg-black/90 backdrop-blur-md">
            <motion.div initial={{ scale: 0.9, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} className={`${isDarkMode ? 'bg-slate-800' : 'bg-white'} w-full max-w-md p-10 rounded-[3rem] shadow-2xl`}>
              <h3 className="text-2xl font-black uppercase italic mb-8">Rename Guardian</h3>
              <input type="text" value={tempName} onChange={e => setTempName(e.target.value)} className={`w-full p-5 rounded-2xl border-2 font-bold mb-8 outline-none ${isDarkMode ? 'bg-slate-700 border-slate-600 text-white' : 'bg-gray-50 border-gray-100'}`} placeholder="New Name..." />
              <div className="flex gap-4">
                <button onClick={() => setShowNameEdit(false)} className="flex-1 p-4 rounded-2xl border-2 font-black uppercase text-xs opacity-50">Cancel</button>
                <button onClick={handleRename} className="flex-1 p-4 bg-green-500 text-white rounded-2xl font-black uppercase text-xs shadow-lg">Confirm</button>
              </div>
            </motion.div>
          </div>
        )}
      </AnimatePresence>

      <AnimatePresence>
        {showCoinAlert && (
          <div className="fixed inset-0 z-[600] flex items-center justify-center pointer-events-none p-6">
            <motion.div initial={{ scale: 0.5, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} exit={{ scale: 0.5, opacity: 0 }} className="bg-red-500 text-white px-10 py-6 rounded-[3rem] shadow-2xl flex items-center gap-5 border-4 border-white/20">
               <AlertCircle size={40} className="shrink-0" />
               <div className="text-left">
                 <p className="font-black text-2xl uppercase italic tracking-tighter">DEPLETED RESERVES</p>
                 <p className="text-[10px] font-bold uppercase tracking-widest opacity-80">Sync emotional frequencies in the Quiz or play games for more coins!</p>
               </div>
            </motion.div>
          </div>
        )}
      </AnimatePresence>

      <AnimatePresence>
        {showEmojiPicker && (
          <div className="fixed inset-0 z-[400] flex items-center justify-center p-6 bg-black/90 backdrop-blur-md">
            <motion.div initial={{ scale: 0.9, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} className={`${isDarkMode ? 'bg-[#111111]' : 'bg-white'} w-full max-w-md rounded-[3.5rem] p-10 shadow-2xl border-4 border-indigo-500/20`}>
              <div className="flex justify-between items-center mb-8">
                <h3 className={`text-2xl md:text-3xl font-black italic uppercase ${isDarkMode ? 'text-white' : 'text-slate-900'}`}>Transform Form</h3>
                <button onClick={() => setShowEmojiPicker(false)} className="opacity-40 hover:opacity-100"><X size={36}/></button>
              </div>
              <p className="text-sm font-black uppercase opacity-40 mb-10 text-center flex items-center justify-center gap-2">Cost: <span className="text-yellow-500 flex items-center gap-1"><Coins size={16}/> 100</span></p>
              <div className="grid grid-cols-5 gap-3 max-h-72 overflow-y-auto pr-2 fading-scrollbar">
                {PET_OPTIONS.map(e => (
                  <button key={e} onClick={() => { if(checkCoins(100)) { onUpdate(0,0,0,-100,0,null,e); setShowEmojiPicker(false); } }} className={`text-3xl p-4 rounded-2xl border-2 transition-all hover:scale-110 active:scale-90 ${isDarkMode ? 'bg-[#1a1a1a] border-white/5' : 'bg-gray-50 border-black/5 shadow-inner'}`}>{e}</button>
                ))}
              </div>
              <button onClick={() => setShowEmojiPicker(false)} className="w-full mt-10 py-5 bg-gray-500 text-white rounded-[2rem] font-black uppercase text-sm shadow-lg">Abort Sync</button>
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </div>
  );
};

export default MoodPetSection;

import React, { useState, useEffect, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Heart, MessageCircle, Repeat, Send, Sparkles, Brain, Wind, ShoppingBag, Gamepad2, Bed, Lock, Coins, Ghost, QuestionMark, Zap, Calculator, Target, Trophy, Info, Clock } from 'lucide-react';
import { User, Post, Mood, Comment } from '../types';
import MoodPetSection from './MoodPetSection';
import { getTellerResponse } from '../services/geminiService';

interface MoodSectionProps {
  user: User;
  posts: Post[];
  onPost: (content: string) => void;
  onHeart: (postId: string) => void;
  onComment: (postId: string, text: string) => void;
  onRepost: (post: Post) => void;
  onFollow: (username: string) => void;
  onBlock: (username: string) => void;
  isDarkMode: boolean;
  onNavigateToProfile: (username: string) => void;
  onUpdatePet: (hunger: number, thirst: number, rest: number, coins: number, exp?: number, sleepUntil?: number | null, newEmoji?: string, markChosen?: boolean, newName?: string, gameCooldownId?: string) => void;
}

type MoodSubTab = 'Express' | 'Teller' | 'Quiz' | 'MoodPet';

const EMOTIONAL_QUIZ = [
  { q: "How did you feel the moment you woke up today?", options: ["Refreshed", "Stressed", "Meh", "Excited"], weights: { Happy: 1, Angry: 0, Tired: -1, Normal: 0 } },
  { q: "What's the weather in your internal 'City' right now?", options: ["Sunny", "Stormy", "Foggy", "Clear Skies"], weights: { Happy: 2, Angry: 1, Tired: 0, Normal: 1 } },
  { q: "How much energy do you have for socializing?", options: ["Tons!", "None", "Maybe later", "Only with friends"], weights: { Happy: 1, Tired: 1, Normal: 0, Excited: 2 } },
  { q: "Pick a color that resonates with you right now.", options: ["Crimson Red", "Soft Blue", "Bright Yellow", "Forest Green"], weights: { Angry: 1, Tired: 1, Happy: 1, Normal: 1 } },
  { q: "Is your mind busy or quiet?", options: ["Race track", "Library", "Zen garden", "Static noise"], weights: { Excited: 1, Normal: 1, Happy: 1, Tired: 1 } },
  { q: "What is your current physical comfort level?", options: ["Perfect", "A bit sore", "Exhausted", "Tense"], weights: { Happy: 1, Normal: 0, Tired: 2, Angry: 1 } },
  { q: "If you were a sound, what would you be?", options: ["A drum solo", "Soft rain", "White noise", "A symphony"], weights: { Angry: 1, Normal: 1, Tired: 1, Happy: 1 } },
  { q: "How do you feel about your tasks today?", options: ["Ready to crush!", "Dreading them", "I'll manage", "What tasks?"], weights: { Excited: 2, Angry: 1, Normal: 1, Happy: 1 } },
  { q: "Choose a snack mood.", options: ["Something spicy", "Something sweet", "Something healthy", "Nothing"], weights: { Angry: 1, Happy: 1, Normal: 1, Tired: 1 } },
  { q: "Finally, how would you rate your patience level?", options: ["Infinite", "Fragile", "Short", "Average"], weights: { Happy: 1, Tired: 1, Angry: 2, Normal: 1 } },
];

const MoodSection: React.FC<MoodSectionProps> = ({ user, posts, onPost, onHeart, onComment, onRepost, onFollow, onBlock, isDarkMode, onNavigateToProfile, onUpdatePet }) => {
  const [subTab, setSubTab] = useState<MoodSubTab>('Express');
  const [postContent, setPostContent] = useState('');
  const [feedFilter, setFeedFilter] = useState<'All' | 'Following'>('All');

  // Teller State
  const [tellerQuestion, setTellerQuestion] = useState('');
  const [tellerResponse, setTellerResponse] = useState('');
  const [isTellerLoading, setIsTellerLoading] = useState(false);

  // Quiz State
  const [quizActive, setQuizActive] = useState(false);
  const [quizStep, setQuizStep] = useState(0);
  const [quizScores, setQuizScores] = useState<Record<string, number>>({ Happy: 0, Angry: 0, Tired: 0, Normal: 0, Excited: 0 });
  const [quizResult, setQuizResult] = useState<string | null>(null);

  const startQuiz = () => {
    setQuizActive(true);
    setQuizStep(0);
    setQuizScores({ Happy: 0, Angry: 0, Tired: 0, Normal: 0, Excited: 0 });
    setQuizResult(null);
  };

  const handleQuizAnswer = (idx: number) => {
    const weights = EMOTIONAL_QUIZ[quizStep].weights;
    const nextScores = { ...quizScores };
    Object.entries(weights).forEach(([key, val]) => {
      nextScores[key] = (nextScores[key] || 0) + (val as number);
    });
    setQuizScores(nextScores);

    if (quizStep < EMOTIONAL_QUIZ.length - 1) {
      setQuizStep(s => s + 1);
    } else {
      const entries = Object.entries(nextScores);
      const sorted = entries.sort((a, b) => (b[1] as number) - (a[1] as number));
      const topMood = sorted[0][0];
      setQuizResult(topMood);
      onUpdatePet(0, 0, 0, 50, 100);
    }
  };

  const handleTeller = async () => {
    if (!tellerQuestion.trim()) return;
    setIsTellerLoading(true);
    setTellerResponse('');
    try {
      const res = await getTellerResponse(tellerQuestion);
      setTellerResponse(res || 'The cosmic fog obscures my vision...');
    } catch (e) {
      setTellerResponse('MAYBE. The spirits are currently in a meeting.');
    } finally {
      setIsTellerLoading(false);
    }
  };

  const formatTime = (ts: number) => {
    const diff = Date.now() - ts;
    if (diff < 60000) return 'Just now';
    if (diff < 3600000) return `${Math.floor(diff / 60000)}m ago`;
    if (diff < 86400000) return `${Math.floor(diff / 3600000)}h ago`;
    return new Date(ts).toLocaleDateString();
  };

  const filteredPosts = feedFilter === 'All' 
    ? posts 
    : posts.filter(p => user.following.includes(p.author) || p.author === user.username);

  return (
    <div className="flex flex-col gap-8 pb-10 h-full overflow-hidden">
      <div className="flex gap-2 overflow-x-auto no-scrollbar pb-2 shrink-0">
        {(['Express', 'Teller', 'Quiz', 'MoodPet'] as MoodSubTab[]).map((t) => (
          <button
            key={t}
            onClick={() => setSubTab(t)}
            className={`px-8 py-3 rounded-full font-black text-xs transition-all whitespace-nowrap uppercase tracking-tighter border-b-4 ${subTab === t ? 'bg-[#e21b3c] border-[#b31530] text-white shadow-xl' : isDarkMode ? 'bg-[#1a1a1a] border-black text-white/30' : 'bg-white border-gray-200 text-slate-500 shadow-sm'}`}
          >
            {t === 'MoodPet' ? 'Mood Pet 🐾' : t === 'Quiz' ? 'Mood Predictor 🧬' : t}
          </button>
        ))}
      </div>

      <div className="flex-1 overflow-y-auto fading-scrollbar pr-2">
        <AnimatePresence mode="wait">
          {subTab === 'Express' && (
            <motion.div key="express" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="space-y-6">
              <div className={`p-6 md:p-8 rounded-[2.5rem] ${isDarkMode ? 'bg-[#111111]' : 'bg-white'} border border-black/5 shadow-2xl`}>
                <textarea value={postContent} onChange={(e) => setPostContent(e.target.value)} placeholder="Transmit your emotional frequency..." className={`w-full ${isDarkMode ? 'bg-[#1a1a1a] text-white' : 'bg-gray-50 text-slate-900'} p-5 rounded-2xl border-2 border-black/5 focus:border-[#e21b3c] outline-none transition-all font-bold placeholder:opacity-30`} rows={3} />
                <div className="flex justify-between items-center mt-4">
                  <div className="flex gap-2">
                    <button onClick={() => setFeedFilter('All')} className={`px-4 py-2 rounded-xl text-[10px] font-black ${feedFilter === 'All' ? 'bg-[#e21b3c] text-white' : 'opacity-40'}`}>ALL DISTRICTS</button>
                    <button onClick={() => setFeedFilter('Following')} className={`px-4 py-2 rounded-xl text-[10px] font-black ${feedFilter === 'Following' ? 'bg-[#e21b3c] text-white' : 'opacity-40'}`}>MY CIRCLE</button>
                  </div>
                  <button onClick={() => {onPost(postContent); setPostContent('');}} className="kahoot-button-red px-10 py-4 text-white rounded-2xl font-black text-xs flex items-center gap-3">
                    <Send size={18} /> BROADCAST
                  </button>
                </div>
              </div>

              <div className="space-y-4 pb-20">
                {filteredPosts.map(post => (
                    <div key={post.id} className={`p-6 md:p-8 rounded-[2.5rem] ${isDarkMode ? 'bg-[#111111] text-white' : 'bg-white text-slate-900'} border border-black/5 shadow-md`}>
                      <div className="flex items-center justify-between mb-6">
                        <div className="flex items-center gap-4">
                          <div className="w-12 h-12 rounded-2xl bg-indigo-500 flex items-center justify-center text-white font-black overflow-hidden shadow-lg shrink-0">
                            {post.author[0].toUpperCase()}
                          </div>
                          <div>
                            <h4 className="font-black text-sm tracking-tight">@{post.author}</h4>
                            <p className="text-[9px] font-black uppercase opacity-30 flex items-center gap-1"><Clock size={10}/> {formatTime(post.timestamp)}</p>
                          </div>
                        </div>
                        {post.isRepost && <span className="text-[8px] font-black uppercase bg-green-500/10 text-green-500 px-3 py-1 rounded-full">Echo from @{post.originalAuthor}</span>}
                      </div>
                      <p className="text-base md:text-lg font-medium mb-8 leading-relaxed">{post.content}</p>

                      {/* Comments Section */}
                      {post.comments.length > 0 && (
                        <div className="mb-8 space-y-3 pl-4 border-l-2 border-black/5">
                           {post.comments.slice(0, 3).map(comment => (
                             <div key={comment.id} className="text-xs">
                               <span className="font-black">@{comment.author}</span> <span className="opacity-70">{comment.text}</span>
                               <p className="text-[8px] opacity-30 uppercase mt-0.5">{formatTime(comment.timestamp)}</p>
                             </div>
                           ))}
                        </div>
                      )}

                      <div className="flex items-center gap-8 pt-6 border-t border-black/5">
                        <button onClick={() => onHeart(post.id)} className="flex items-center gap-2 text-[#e21b3c] font-black text-[10px]"><Heart size={20} fill={post.hearts > 0 ? "currentColor" : "none"} /> {post.hearts}</button>
                        <button onClick={() => onRepost(post)} className="flex items-center gap-2 text-green-500 font-black text-[10px]"><Repeat size={20} /> ECHO</button>
                        <button className="flex items-center gap-2 text-blue-500 font-black text-[10px]"><MessageCircle size={20} /> {post.comments.length}</button>
                      </div>
                    </div>
                ))}
              </div>
            </motion.div>
          )}

          {subTab === 'MoodPet' && (
            <motion.div key="pet" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}>
              <MoodPetSection user={user} isDarkMode={isDarkMode} onUpdate={onUpdatePet} onPost={onPost} />
            </motion.div>
          )}

          {subTab === 'Teller' && (
            <motion.div key="teller" initial={{ opacity: 0 }} animate={{ opacity: 1 }} className={`flex flex-col items-center justify-center p-12 text-center ${isDarkMode ? 'bg-[#111111]' : 'bg-white'} rounded-[3rem] border border-black/5 shadow-2xl relative overflow-hidden`}>
              <div className="absolute top-[-20%] left-[-20%] w-[60%] h-[60%] bg-[#46178f]/10 blur-[120px] rounded-full"></div>
              <div className="mb-10 text-8xl md:text-9xl select-none drop-shadow-2xl">🔮</div>
              <h3 className={`text-3xl md:text-5xl font-black italic uppercase mb-4 tracking-tighter ${isDarkMode ? 'text-white' : 'text-slate-900'}`}>Mystic Teller</h3>
              <p className="text-xs opacity-40 mb-10 max-w-sm font-bold uppercase tracking-[0.3em]">Consult the void</p>
              <div className="w-full max-w-lg space-y-6">
                <input type="text" value={tellerQuestion} onChange={e => setTellerQuestion(e.target.value)} placeholder="Will I find peace?" className={`w-full ${isDarkMode ? 'bg-[#1a1a1a] text-white' : 'bg-gray-50 text-slate-900'} p-6 rounded-[2rem] border-4 border-black/5 outline-none font-black text-xl placeholder:opacity-10 focus:border-[#46178f] shadow-inner`} />
                <button onClick={handleTeller} disabled={isTellerLoading} className="kahoot-button-purple w-full p-6 rounded-[2rem] text-white font-black uppercase text-xl shadow-xl">CONSULT THE VOID</button>
              </div>
              {tellerResponse && (
                <motion.div initial={{ scale: 0.9, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} className={`mt-12 p-10 rounded-[2.5rem] ${isDarkMode ? 'bg-[#1a1a1a] text-white' : 'bg-indigo-50 text-indigo-900'} border-2 border-black/5 max-w-md w-full shadow-2xl`}>
                  <p className="text-3xl font-black italic uppercase mb-4 tracking-tighter">{tellerResponse.split('.')[0]}</p>
                  <p className="text-base font-bold leading-snug italic opacity-80">{tellerResponse.split('.').slice(1).join('.')}</p>
                </motion.div>
              )}
            </motion.div>
          )}

          {subTab === 'Quiz' && (
            <motion.div key="quiz" initial={{ opacity: 0 }} animate={{ opacity: 1 }}>
              {!quizActive ? (
                <div className={`flex flex-col items-center justify-center text-center p-12 ${isDarkMode ? 'bg-[#111111]' : 'bg-white'} rounded-[3rem] border border-black/5 shadow-2xl`}>
                  <Brain className="text-indigo-500 mb-10" size={80} />
                  <h3 className={`text-3xl md:text-5xl font-black italic uppercase mb-4 tracking-tighter ${isDarkMode ? 'text-white' : 'text-slate-900'}`}>Emotional Predictor</h3>
                  <p className="text-xs opacity-40 mb-12 max-w-xs font-bold uppercase tracking-widest leading-relaxed">Answer 10 questions and Mooderia will map your current emotional district.</p>
                  <button onClick={startQuiz} className="kahoot-button-purple px-16 py-6 rounded-3xl text-white font-black text-2xl uppercase">BEGIN SCAN</button>
                </div>
              ) : quizResult ? (
                <div className={`flex flex-col items-center justify-center text-center p-12 ${isDarkMode ? 'bg-[#111111]' : 'bg-white'} rounded-[3rem] shadow-xl border border-black/5`}>
                  <Trophy className="text-yellow-500 mb-10" size={96} />
                  <h3 className={`text-3xl md:text-4xl font-black italic uppercase mb-2 tracking-tighter ${isDarkMode ? 'text-white' : 'text-slate-900'}`}>District Scan Complete</h3>
                  <p className="text-lg font-black uppercase tracking-widest opacity-40 mb-2">We predict your mood is:</p>
                  <p className="text-6xl font-black mb-10 text-[#e21b3c] italic uppercase tracking-tighter">{quizResult}</p>
                  <div className="flex gap-4">
                    <button onClick={() => { onPost(`My Mooderia scan result: ${quizResult}! 🧬`); setQuizActive(false); }} className="kahoot-button-blue px-10 py-4 rounded-2xl text-white font-black text-sm uppercase">SHARE TO FEED</button>
                    <button onClick={startQuiz} className="kahoot-button-red px-10 py-4 rounded-2xl text-white font-black text-sm uppercase">RE-SCAN</button>
                  </div>
                </div>
              ) : (
                <div className={`max-w-2xl mx-auto py-12 px-10 ${isDarkMode ? 'bg-[#111111]' : 'bg-white'} rounded-[3.5rem] shadow-2xl border border-black/5`}>
                  <div className="flex justify-between items-center mb-12">
                    <span className="text-[10px] font-black uppercase text-[#e21b3c] tracking-[0.4em] italic">Scanning Question {quizStep + 1} / 10</span>
                    <div className="w-32 h-3 bg-gray-100 rounded-full overflow-hidden">
                      <motion.div initial={{ width: 0 }} animate={{ width: `${(quizStep + 1) * 10}%` }} className="h-full bg-[#e21b3c]" />
                    </div>
                  </div>
                  <h4 className={`text-2xl md:text-3xl font-black italic mb-12 leading-tight tracking-tight text-center ${isDarkMode ? 'text-white' : 'text-slate-900'}`}>{EMOTIONAL_QUIZ[quizStep].q}</h4>
                  <div className="grid grid-cols-1 gap-4">
                    {EMOTIONAL_QUIZ[quizStep].options.map((opt, i) => (
                      <button key={i} onClick={() => handleQuizAnswer(i)} className={`p-6 rounded-3xl border-2 border-black/5 text-center font-black text-base transition-all shadow-md ${isDarkMode ? 'bg-[#1a1a1a] text-white hover:border-[#e21b3c]' : 'bg-gray-50 text-slate-800 hover:border-[#e21b3c]'}`}>
                        {opt}
                      </button>
                    ))}
                  </div>
                </div>
              )}
            </motion.div>
          )}
        </AnimatePresence>
      </div>
    </div>
  );
};

export default MoodSection;

import React, { useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Heart, MessageCircle, Repeat, Bell, CheckCircle2, Inbox, Clock } from 'lucide-react';
import { Notification } from '../types';

interface NotificationsSectionProps {
  notifications: Notification[];
  isDarkMode: boolean;
  onMarkRead: () => void;
}

const NotificationsSection: React.FC<NotificationsSectionProps> = ({ notifications, isDarkMode, onMarkRead }) => {
  // Clear unread notifications when viewing this tab
  useEffect(() => {
    onMarkRead();
  }, [onMarkRead]);

  const getIcon = (type: string) => {
    switch (type) {
      case 'heart': return <Heart className="text-red-500" size={24} fill="currentColor" />;
      case 'comment': return <MessageCircle className="text-blue-500" size={24} fill="currentColor" />;
      case 'repost': return <Repeat className="text-green-500" size={24} />;
      default: return <Bell size={24} />;
    }
  };

  const getMessageText = (notif: Notification) => {
    switch (notif.type) {
      case 'heart': return (
        <p className="text-sm md:text-base leading-snug">
          <span className="font-black">@{notif.fromUser}</span> liked your post
        </p>
      );
      case 'comment': return (
        <p className="text-sm md:text-base leading-snug">
          <span className="font-black">@{notif.fromUser}</span> commented on your post
        </p>
      );
      case 'repost': return (
        <p className="text-sm md:text-base leading-snug">
          <span className="font-black">@{notif.fromUser}</span> reposted your expression
        </p>
      );
      default: return <p>Activity from <b>@{notif.fromUser}</b></p>;
    }
  };

  const getColorTheme = (type: string) => {
    switch (type) {
      case 'heart': return 'border-red-500 bg-red-50/50 dark:bg-red-900/10';
      case 'comment': return 'border-blue-500 bg-blue-50/50 dark:bg-blue-900/10';
      case 'repost': return 'border-green-500 bg-green-50/50 dark:bg-green-900/10';
      default: return 'border-gray-500 bg-gray-50 dark:bg-slate-700/50';
    }
  };

  const formatTime = (ts: number) => {
    const diff = Date.now() - ts;
    if (diff < 60000) return 'Just now';
    if (diff < 3600000) return `${Math.floor(diff / 60000)}m ago`;
    if (diff < 86400000) return `${Math.floor(diff / 3600000)}h ago`;
    return new Date(ts).toLocaleDateString();
  };

  return (
    <div className="space-y-8 min-h-[70vh] pb-20 overflow-y-auto">
      <div className="flex justify-between items-center">
        <div>
          <h2 className={`text-4xl font-black italic uppercase tracking-tighter ${isDarkMode ? 'text-white' : 'text-slate-900'}`}>Alerts</h2>
          <p className="text-[10px] font-black opacity-40 uppercase tracking-widest mt-1">Live from the Mooderia Network</p>
        </div>
        <div className="flex items-center gap-2 px-4 py-2 bg-green-500 text-white rounded-full font-black text-[10px] uppercase tracking-widest shadow-lg">
          <CheckCircle2 size={14} /> City Secured
        </div>
      </div>

      <div className="space-y-4">
        {notifications.length === 0 ? (
          <motion.div 
            initial={{ opacity: 0 }} 
            animate={{ opacity: 1 }}
            className={`py-24 text-center rounded-[3rem] border-4 border-dashed ${isDarkMode ? 'border-slate-800' : 'border-gray-200'} opacity-30`}
          >
            <Inbox size={64} className="mx-auto mb-4" />
            <p className="text-lg font-black uppercase italic">Quiet Streets Today</p>
            <p className="text-xs font-bold max-w-xs mx-auto mt-2">Express yourself in the Mood tab to start receiving citizen interactions!</p>
          </motion.div>
        ) : (
          <AnimatePresence>
            {[...notifications].reverse().map((notif, i) => (
              <motion.div
                key={notif.id}
                initial={{ opacity: 0, x: -20 }}
                animate={{ opacity: 1, x: 0 }}
                transition={{ delay: i * 0.05 }}
                className={`p-6 rounded-[2.5rem] border-l-8 shadow-xl flex items-center gap-6 transition-all hover:scale-[1.02] ${isDarkMode ? 'text-white' : 'text-slate-900'} ${getColorTheme(notif.type)}`}
              >
                <div className={`w-14 h-14 rounded-2xl flex items-center justify-center shrink-0 shadow-inner bg-white dark:bg-slate-800`}>
                  {getIcon(notif.type)}
                </div>
                <div className="flex-1 min-w-0 text-left">
                  {getMessageText(notif)}
                  {notif.postContentSnippet && (
                    <div className="mt-3 p-3 bg-white/40 dark:bg-black/20 rounded-xl italic text-xs font-medium opacity-70 truncate">
                      "{notif.postContentSnippet}"
                    </div>
                  )}
                  <p className="text-[9px] font-black uppercase tracking-widest opacity-40 mt-3 flex items-center gap-2">
                    <Clock size={10} /> {formatTime(notif.timestamp)} • DISTRICT FEED
                  </p>
                </div>
                {!notif.read && (
                  <div className="w-3 h-3 bg-blue-500 rounded-full animate-ping shadow-lg"></div>
                )}
              </motion.div>
            ))}
          </AnimatePresence>
        )}
      </div>

      <div className="text-center py-10 opacity-10 font-black italic text-[10px] uppercase tracking-[0.5em]">
        --- END OF TRANSMISSION ---
      </div>
    </div>
  );
};

export default NotificationsSection;

import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { User } from '../types';
import LoadingScreen from '../components/LoadingScreen';

interface AuthScreenProps {
  onLogin: (user: User) => void;
}

const AuthScreen: React.FC<AuthScreenProps> = ({ onLogin }) => {
  const [isSignUp, setIsSignUp] = useState(false);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [displayName, setDisplayName] = useState('');
  const [username, setUsername] = useState('');
  const [error, setError] = useState('');
  const [isAuthenticating, setIsAuthenticating] = useState(false);
  const [pendingUser, setPendingUser] = useState<User | null>(null);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    const allUsersStr = localStorage.getItem('mooderia_all_users') || '[]';
    const allUsers: User[] = JSON.parse(allUsersStr);

    if (isSignUp) {
      const userExists = allUsers.some(u => u.email === email || u.username === username);
      if (userExists) {
        setError('This citizen identifier already exists in Mooderia.');
        return;
      }

      // Fix: Add missing gameCooldowns property to satisfy the User interface definition from types.ts.
      const newUser: User = {
        displayName: displayName,
        username: username,
        email: email,
        password: password,
        followers: [],
        following: [],
        friends: [],
        blockedUsers: [],
        posts: [],
        reposts: [],
        moodHistory: [], // Starts empty, scores calculated on check-in
        moodStreak: 0,
        title: 'Citizen',
        likesReceived: 0, // Starts at zero
        // Mood Pet Init
        petName: 'Guardian',
        moodCoins: 50,
        petEmoji: '🐱',
        petHunger: 80,
        petThirst: 80,
        petRest: 100,
        petLevel: 1,
        petExp: 0,
        petHasBeenChosen: false,
        petLastUpdate: Date.now(),
        petSleepUntil: null,
        gameCooldowns: {}
      };

      allUsers.push(newUser);
      localStorage.setItem('mooderia_all_users', JSON.stringify(allUsers));

      setIsAuthenticating(true);
      setPendingUser(newUser);
      setTimeout(() => {
        onLogin(newUser);
      }, 3000);
    } else {
      const existingUser = allUsers.find(u => u.email === email && u.password === password);

      if (existingUser) {
        setIsAuthenticating(true);
        setPendingUser(existingUser);
        setTimeout(() => {
          onLogin(existingUser);
        }, 3000);
      } else {
        setError('Citizenship credentials invalid. Please check your email and password.');
      }
    }
  };

  if (isAuthenticating) {
    return <LoadingScreen />;
  }

  return (
    <div className="min-h-screen flex items-center justify-center bg-[#46178f] p-4 relative overflow-hidden text-slate-900">
      <div className="absolute top-[-10%] left-[-10%] w-[40%] h-[40%] bg-[#1368ce] rounded-full blur-[100px] opacity-30"></div>
      <div className="absolute bottom-[-10%] right-[-10%] w-[40%] h-[40%] bg-[#e21b3c] rounded-full blur-[100px] opacity-30"></div>

      <motion.div 
        initial={{ y: 50, opacity: 0 }} 
        animate={{ y: 0, opacity: 1 }} 
        className="w-full max-w-md bg-slate-800 border-4 border-white/10 rounded-[2.5rem] shadow-2xl p-8 z-10 text-white"
      >
        <div className="text-center mb-8">
          <h1 className="text-5xl font-black italic text-white tracking-tighter mb-2 uppercase">Mooderia</h1>
          <p className="text-blue-400 font-bold uppercase tracking-widest text-xs">The Vibrant Metropolis</p>
        </div>

        <form onSubmit={handleSubmit} className="space-y-4 text-slate-900">
          <AnimatePresence mode="wait">
            {isSignUp && (
              <motion.div 
                key="signup-fields" 
                initial={{ height: 0, opacity: 0 }} 
                animate={{ height: 'auto', opacity: 1 }} 
                exit={{ height: 0, opacity: 0 }} 
                className="space-y-4 overflow-hidden"
              >
                <div className="relative">
                  <input 
                    type="text" 
                    placeholder="Display Name" 
                    required 
                    value={displayName} 
                    onChange={(e) => setDisplayName(e.target.value)} 
                    maxLength={20}
                    className="w-full p-4 rounded-xl border-2 border-slate-700 bg-slate-700 text-white focus:border-white outline-none font-bold placeholder-slate-400" 
                  />
                  <span className="absolute right-3 bottom-1 text-[8px] font-bold opacity-30">{displayName.length}/20</span>
                </div>
                <div className="relative">
                  <input 
                    type="text" 
                    placeholder="Username (e.g. mood_king)" 
                    required 
                    value={username} 
                    onChange={(e) => setUsername(e.target.value)} 
                    maxLength={20}
                    className="w-full p-4 rounded-xl border-2 border-slate-700 bg-slate-700 text-white focus:border-white outline-none font-bold placeholder-slate-400" 
                  />
                  <span className="absolute right-3 bottom-1 text-[8px] font-bold opacity-30">{username.length}/20</span>
                </div>
              </motion.div>
            )}
          </AnimatePresence>

          <input 
            type="email" 
            placeholder="Email Address" 
            required 
            value={email} 
            onChange={(e) => setEmail(e.target.value)} 
            className="w-full p-4 rounded-xl border-2 border-slate-700 bg-slate-700 text-white focus:border-white outline-none font-bold placeholder-slate-400" 
          />
          <input 
            type="password" 
            placeholder="Password" 
            required 
            value={password} 
            onChange={(e) => setPassword(e.target.value)} 
            className="w-full p-4 rounded-xl border-2 border-slate-700 bg-slate-700 text-white focus:border-white outline-none font-bold placeholder-slate-400" 
          />

          {error && (
            <p className="text-[#e21b3c] text-sm font-bold text-center bg-red-500/10 p-2 rounded-lg">{error}</p>
          )}

          <button 
            type="submit" 
            className="kahoot-button w-full p-5 rounded-2xl bg-[#1368ce] text-white font-black text-xl mt-4 shadow-lg transition-transform active:scale-95 uppercase"
          >
            {isSignUp ? 'Apply for Citizenship' : 'Enter the City'}
          </button>
        </form>

        <div className="mt-8 text-center">
          <button 
            onClick={() => {
              setIsSignUp(!isSignUp);
              setError('');
            }} 
            className="text-sm font-bold text-blue-400 hover:text-white transition-colors hover:underline"
          >
            {isSignUp ? 'Already a citizen? Sign In' : "New to Mooderia? Register!"}
          </button>
        </div>
      </motion.div>
    </div>
  );
};

