  { id: 'medium', name: 'Power Sleep', duration: 30, rest: 75, exp: 50, cost: 25, emoji: '🛌' },
  { id: 'deep', name: 'Hibernation', duration: 120, rest: 100, exp: 200, cost: 75, emoji: '🌌' },
];

const PET_OPTIONS = ['🐱', '🐶', '🦊', '🦁', '🐨', '🐼', '🦄', '🐲', '🐸', '🐹', '🐰', '🐯', '🐧', '🐻', '🦉'];

const MoodPetSection: React.FC<MoodPetSectionProps> = ({ user, isDarkMode, onUpdate, onPost }) => {
  const [activeTab, setActiveTab] = useState<'Interaction' | 'Shop' | 'Games'>('Interaction');
  const [gameMode, setGameMode] = useState<string | null>(null);
  const [gameResult, setGameResult] = useState<{ coins: number, exp: number } | null>(null);
  const [timeLeft, setTimeLeft] = useState(0);
  const [showEmojiPicker, setShowEmojiPicker] = useState(false);
  const [showCoinAlert, setShowCoinAlert] = useState(false);
  const [showNameEdit, setShowNameEdit] = useState(false);
  const [tempName, setTempName] = useState(user.petName || '');
  const [petting, setPetting] = useState(false);
  const [selectedInitialEmoji, setSelectedInitialEmoji] = useState<string | null>(null);

  // Dynamic Game States
  const [tapScore, setTapScore] = useState(0);
  const [vibeTargets, setVibeTargets] = useState<{ id: number, x: number, y: number, emoji: string, size: number, speed: number }[]>([]);
  const [mathProblem, setMathProblem] = useState({ q: '', a: 0 });
  const [mathInput, setMathInput] = useState('');
  const [feedback, setFeedback] = useState<'correct' | 'wrong' | null>(null);
  const [floatingTexts, setFloatingTexts] = useState<{id: number, text: string, x: number, y: number}[]>([]);
  const [reactionState, setReactionState] = useState<'wait' | 'ready' | 'result'>('wait');
  const [reactionStart, setReactionStart] = useState(0);

  const isSleeping = user.petSleepUntil && user.petSleepUntil > Date.now();

  useEffect(() => {
    let timer: number;
    if (gameMode && timeLeft > 0) {
      timer = window.setInterval(() => setTimeLeft(prev => prev - 1), 1000);
    } else if (gameMode && timeLeft === 0) {
      finishGame();
    }
    return () => clearInterval(timer);
  }, [gameMode, timeLeft]);

  // Game Logic Spawners
  useEffect(() => {
    if (gameMode === 'hunter' && timeLeft > 0) {
      const interval = setInterval(() => {
        const vibes = ['✨', '🔥', '💖', '⭐', '🌈', '💎'];
        const newVibe = {
          id: Math.random(),
          x: Math.random() * 80 + 10,
          y: Math.random() * 80 + 10,
          emoji: vibes[Math.floor(Math.random() * vibes.length)],
          size: Math.random() * 40 + 20,
          speed: Math.random() * 2 + 1
        };
        setVibeTargets(prev => [...prev.slice(-8), newVibe]);
      }, 700);
      return () => clearInterval(interval);
    }

    if (gameMode === 'bubbles' && timeLeft > 0) {
      const interval = setInterval(() => {
        const newBubble = {
          id: Math.random(),
          x: Math.random() * 90,
          y: 100,
          emoji: '🫧',
          size: 40,
          speed: 2
        };
        setVibeTargets(prev => [...prev.slice(-10), newBubble]);
      }, 500);
      return () => clearInterval(interval);
    }
  }, [gameMode, timeLeft]);

  const finishGame = () => {
    let coins = 0;
    let exp = 0;
    switch(gameMode) {
      case 'clicker': coins = Math.min(50, tapScore * 2); exp = tapScore * 5; break;
      case 'hunter': coins = Math.min(80, tapScore * 5); exp = tapScore * 10; break;
      case 'math': coins = Math.min(100, tapScore * 10); exp = tapScore * 20; break;
      case 'reaction': coins = tapScore > 0 ? 50 : 10; exp = 50; break;
      case 'bubbles': coins = Math.min(60, tapScore * 3); exp = tapScore * 6; break;
      default: coins = 30; exp = 60;
    }
    setGameResult({ coins, exp });
    onUpdate(-10, -10, -15, coins, exp, null, undefined, undefined, undefined, gameMode!);
    setVibeTargets([]);
  };

  const startLevelGame = (id: string) => {
    const cooldown = user.gameCooldowns?.[id];
    if (cooldown && cooldown > Date.now()) {
      const wait = Math.ceil((cooldown - Date.now()) / 1000);
      alert(`Terminal charging! Access allowed in ${wait}s.`);
      return;
    }
    if (user.petRest < 20) {
      alert("Guardian is too exhausted! Let them sleep first.");
      return;
    }
    const config = GAMES.find(g => g.id === id);
    if (!config) return;
    setGameMode(id);
    setTimeLeft(config.time);
    setGameResult(null);
    setTapScore(0);
    if (id === 'math') generateMath();
    if (id === 'reaction') startReaction();
  };

  const startReaction = () => {
    setReactionState('wait');
    const delay = Math.random() * 3000 + 2000;
    setTimeout(() => {
      setReactionState('ready');
      setReactionStart(Date.now());
    }, delay);
  };

  const generateMath = () => {
    const a = Math.floor(Math.random() * 15) + 1;
    const b = Math.floor(Math.random() * 15) + 1;
    setMathProblem({ q: `${a} + ${b} = ?`, a: a + b });
    setMathInput('');
  };

  const spawnFloatingText = (text: string, x: number, y: number) => {
    const id = Date.now();
    setFloatingTexts(prev => [...prev, { id, text, x, y }]);
    setTimeout(() => setFloatingTexts(prev => prev.filter(f => f.id !== id)), 800);
  };

  const checkCoins = (cost: number) => {
    if (user.moodCoins < cost) {
      setShowCoinAlert(true);
      setTimeout(() => setShowCoinAlert(false), 2000);
      return false;
    }
    return true;
  };

  if (!user.petHasBeenChosen) {
    return (
      <div className={`flex flex-col items-center justify-center p-8 md:p-12 text-center ${isDarkMode ? 'bg-[#111111]' : 'bg-white'} rounded-[3rem] shadow-2xl border border-black/5`}>
        <h3 className={`text-4xl font-black italic uppercase mb-8 tracking-tighter ${isDarkMode ? 'text-white' : 'text-slate-900'}`}>Summon a Guardian</h3>
        <div className="w-full max-w-sm mb-8">
          <p className="text-[10px] font-black uppercase opacity-40 mb-3 tracking-[0.3em]">1. Assign Identity</p>
          <input type="text" value={tempName} onChange={e => setTempName(e.target.value)} placeholder="Guardian Name..." className={`w-full p-4 rounded-2xl border-4 font-bold outline-none text-center shadow-inner ${isDarkMode ? 'bg-slate-800 border-slate-700 text-white' : 'bg-gray-50 border-gray-100'}`} />
        </div>
        <p className="text-[10px] font-black uppercase opacity-40 mb-4 tracking-[0.3em]">2. Choose Material Form</p>
        <div className="grid grid-cols-5 gap-3 max-w-md mx-auto mb-10 overflow-y-auto max-h-48 p-3 custom-scrollbar border-4 border-black/5 rounded-[2rem]">
          {PET_OPTIONS.map(e => (
            <button 
              key={e} 
              onClick={() => setSelectedInitialEmoji(e)} 
              className={`text-3xl p-3 rounded-2xl border-4 transition-all hover:scale-110 active:scale-90 ${selectedInitialEmoji === e ? 'border-indigo-500 bg-indigo-50 shadow-lg' : isDarkMode ? 'bg-[#1a1a1a] border-white/5' : 'bg-gray-100 border-transparent shadow-inner'}`}
            >
              {e}
            </button>
          ))}
        </div>
        <button 
          disabled={!tempName.trim() || !selectedInitialEmoji} 
          onClick={() => onUpdate(0,0,0,0,0,null,selectedInitialEmoji!,true,tempName)}
          className={`kahoot-button-purple w-full max-w-xs py-5 rounded-3xl text-white font-black uppercase text-xl shadow-xl transition-all ${(!tempName.trim() || !selectedInitialEmoji) ? 'opacity-20 grayscale' : 'hover:scale-105'}`}
        >
          Begin Sync
        </button>
      </div>
    );
  }

  return (
    <div className="flex flex-col gap-6 relative">
      {/* Guardian Dashboard */}
      <div className={`p-8 rounded-[3.5rem] ${isDarkMode ? 'bg-[#111111] text-white' : 'bg-white text-slate-900'} border-4 border-black/5 shadow-2xl flex flex-col items-center justify-center relative overflow-hidden`}>
        <AnimatePresence>
          {isSleeping && (
            <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="absolute inset-0 z-50 bg-indigo-900/90 flex flex-col items-center justify-center text-white backdrop-blur-md p-6 text-center">
               <Lock size={64} className="mb-4 animate-pulse text-indigo-300" />
               <h4 className="text-3xl font-black uppercase italic tracking-tighter">REST MODE ACTIVATED</h4>
               <p className="text-[10px] font-black uppercase tracking-[0.3em] opacity-60">Do not disturb {user.petName}.</p>
               <div className="mt-8 bg-black/30 px-8 py-4 rounded-3xl flex items-center gap-3 font-black text-2xl border-4 border-white/10">
                 <Timer size={28}/> {Math.ceil((user.petSleepUntil! - Date.now()) / (1000 * 60))}m
               </div>
            </motion.div>
          )}
        </AnimatePresence>

        <div className="absolute top-8 left-8 flex items-center gap-2 bg-yellow-400 px-5 py-2.5 rounded-2xl text-white font-black text-sm shadow-lg border-b-4 border-yellow-600">
          <Coins size={18}/> {user.moodCoins}
        </div>
        <div className="absolute top-8 right-8 flex gap-3">
          <button onClick={() => setShowNameEdit(true)} className="p-3.5 bg-green-500 text-white rounded-2xl font-black shadow-lg border-b-4 border-green-700 hover:scale-110 active:scale-90 transition-transform"><PenTool size={20}/></button>
          <button onClick={() => setShowEmojiPicker(true)} className="p-3.5 bg-indigo-500 text-white rounded-2xl font-black shadow-lg border-b-4 border-indigo-700 hover:scale-110 active:scale-90 transition-transform"><Wand2 size={20}/></button>
        </div>

        <div className="text-center mb-8 mt-6">
           <h3 className="text-3xl font-black italic uppercase tracking-tighter mb-1">{user.petName}</h3>
           <div className="bg-black/5 px-4 py-1 rounded-full"><p className="text-[9px] font-black opacity-30 uppercase tracking-[0.3em]">Guardian LVL {user.petLevel}</p></div>
        </div>

        <motion.div animate={{ y: [0, -20, 0], rotate: [0, 5, -5, 0], scale: [1, 1.05, 1] }} transition={{ duration: 4, repeat: Infinity, ease: "easeInOut" }} className="text-[140px] md:text-[180px] mb-12 select-none flex items-center justify-center drop-shadow-2xl">
          {user.petEmoji}
        </motion.div>

        <div className="w-full max-w-sm grid grid-cols-3 gap-6">
           {[
             { label: 'Energy', val: user.petHunger, color: 'bg-red-500', icon: <Utensils size={14} /> },
             { label: 'Hydration', val: user.petThirst, color: 'bg-blue-500', icon: <Droplets size={14} /> },
             { label: 'Rest', val: user.petRest, color: 'bg-green-500', icon: <Zap size={14} /> },
           ].map(bar => (
             <div key={bar.label} className="flex flex-col items-center gap-3">
               <div className="flex items-center justify-center gap-2 text-[9px] font-black uppercase opacity-40">{bar.icon} {bar.val}%</div>
               <div className="w-full h-3 bg-black/5 rounded-full overflow-hidden border border-black/5">
                 <motion.div initial={{ width: 0 }} animate={{ width: `${bar.val}%` }} className={`h-full ${bar.color} rounded-full`} />
               </div>
             </div>
           ))}
        </div>
      </div>

      <div className="flex gap-2 shrink-0">
        {(['Interaction', 'Shop', 'Games'] as const).map(tab => (
          <button key={tab} onClick={() => setActiveTab(tab)} className={`flex-1 py-5 rounded-3xl font-black text-[11px] uppercase border-b-[6px] transition-all ${activeTab === tab ? 'bg-[#1368ce] border-[#0e4c99] text-white shadow-xl -translate-y-1' : isDarkMode ? 'bg-[#111111] border-black text-white/30' : 'bg-white border-gray-200 text-slate-500 shadow-sm'}`}>{tab}</button>
        ))}
      </div>

      {/* Tab Content */}
      <div className="grid grid-cols-2 md:grid-cols-3 gap-4 pb-24">
        {activeTab === 'Shop' && ITEMS.map(item => (
          <button key={item.id} onClick={() => { if(checkCoins(item.cost)) onUpdate(item.type === 'hunger' ? item.fill : 0, item.type === 'thirst' ? item.fill : 0, 0, -item.cost, 15); }} className={`p-6 rounded-[2.5rem] border-4 border-black/5 flex flex-col items-center justify-center text-center gap-3 ${isDarkMode ? 'bg-[#111111] text-white' : 'bg-white text-slate-900'} shadow-lg hover:scale-105 active:scale-95 transition-all group`}>
            <span className="text-5xl group-hover:scale-125 transition-transform duration-300">{item.emoji}</span>
            <span className="text-[10px] font-black uppercase opacity-40">{item.name}</span>
            <div className="bg-yellow-400 text-white px-4 py-1.5 rounded-2xl text-xs font-black flex items-center gap-1 shadow-md border-b-4 border-yellow-600"><Coins size={14}/> {item.cost}</div>
          </button>
        ))}

        {activeTab === 'Games' && !gameMode && GAMES.map(game => {
          const cd = user.gameCooldowns?.[game.id];
          const isOff = cd && cd > Date.now();
          return (
            <button key={game.id} onClick={() => startLevelGame(game.id)} className={`relative p-6 rounded-[2.5rem] border-4 border-black/5 flex flex-col items-center justify-center text-center gap-2 ${isDarkMode ? 'bg-[#111111] text-white' : 'bg-white text-slate-900'} shadow-lg transition-all hover:scale-105 group overflow-hidden ${isOff ? 'opacity-40 grayscale' : 'hover:border-indigo-500'}`}>
              <span className="text-5xl group-hover:rotate-12 transition-transform duration-300">{game.emoji}</span>
              <div className="flex flex-col">
                <span className="text-[11px] font-black uppercase tracking-tight leading-none">{game.name}</span>
                <span className="text-[8px] font-bold opacity-30 mt-1">{game.desc}</span>
              </div>
              {isOff && (
                <div className="absolute inset-0 bg-black/60 flex flex-col items-center justify-center font-black text-white p-2">
                   <ZapOff size={24} className="mb-1" />
                   <span className="text-[8px] uppercase tracking-tighter">Terminal Cooling</span>
                </div>
              )}
            </button>
          );
        })}

        {gameMode && (
          <div className={`col-span-full min-h-[400px] p-8 rounded-[3.5rem] text-white text-center shadow-2xl relative border-[8px] border-white/20 overflow-hidden flex flex-col ${GAMES.find(g=>g.id===gameMode)?.color}`}>
             {gameResult ? (
               <div className="h-full flex flex-col items-center justify-center space-y-8">
                 <motion.div initial={{ scale: 0, rotate: -20 }} animate={{ scale: 1, rotate: 0 }} className="flex flex-col items-center">
                   <div className="relative">
                      <Trophy size={100} className="text-yellow-300 mb-4 drop-shadow-lg" />
                      <Sparkles className="absolute -top-4 -right-4 text-white animate-pulse" size={40} />
                   </div>
                   <h4 className="text-4xl font-black italic uppercase tracking-tighter">DATA SYNCED!</h4>
                 </motion.div>
                 <div className="flex justify-center gap-8">
                    <div className="bg-black/20 px-8 py-5 rounded-[2rem] border-4 border-white/10 shadow-xl">
                      <p className="text-[11px] font-black uppercase opacity-60 mb-2">Rewards</p>
                      <p className="text-4xl font-black flex items-center gap-2 justify-center drop-shadow-md"><Coins size={32}/> {gameResult.coins}</p>
                    </div>
                    <div className="bg-black/20 px-8 py-5 rounded-[2rem] border-4 border-white/10 shadow-xl">
                      <p className="text-[11px] font-black uppercase opacity-60 mb-2">Guardian XP</p>
                      <p className="text-4xl font-black flex items-center gap-2 justify-center drop-shadow-md"><Activity size={32}/> {gameResult.exp}</p>
                    </div>
                 </div>
                 <button onClick={() => setGameMode(null)} className="w-full max-w-sm py-6 bg-white text-indigo-700 rounded-3xl font-black uppercase text-lg shadow-[0_8px_0_0_#cbd5e1] hover:scale-105 active:translate-y-1 active:shadow-none transition-all">Close Terminal</button>
               </div>
             ) : (
               <div className="h-full flex flex-col space-y-6">
                  <div className="flex justify-between items-center bg-black/30 px-8 py-4 rounded-[2rem] shrink-0 shadow-inner">
                    <span className="text-base font-black uppercase italic tracking-tighter">SIMULATING {gameMode?.toUpperCase()}</span>
                    <span className="flex items-center gap-3 font-black text-2xl tabular-nums bg-white/10 px-4 py-1 rounded-2xl"><Timer size={24}/> {timeLeft}s</span>
                  </div>

                  <div className="flex-1 flex flex-col items-center justify-center relative bg-black/10 rounded-[2.5rem] p-6 shadow-inner">
                    {/* Floating Text Particles */}
                    <AnimatePresence>
                      {floatingTexts.map(f => (
                        <motion.div key={f.id} initial={{ y: f.y, x: f.x, opacity: 1, scale: 1 }} animate={{ y: f.y - 120, opacity: 0, scale: 2 }} className="absolute z-50 pointer-events-none font-black text-4xl text-yellow-300 drop-shadow-lg">
                          {f.text}
                        </motion.div>
                      ))}
                    </AnimatePresence>

