               </div>
            </motion.div>
          </div>
        )}
      </AnimatePresence>

      <AnimatePresence>
        {showEmojiPicker && (
          <div className="fixed inset-0 z-[400] flex items-center justify-center p-6 bg-black/90 backdrop-blur-xl">
            <motion.div initial={{ scale: 0.9, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} className={`${isDarkMode ? 'bg-[#111111]' : 'bg-white'} w-full max-w-lg rounded-[4rem] p-12 shadow-2xl border-8 border-indigo-500/20`}>
              <div className="flex justify-between items-center mb-10">
