              </div>
              <p className="text-sm font-black uppercase opacity-40 mb-10 text-center flex items-center justify-center gap-3">Required Sync: <span className="text-yellow-500 flex items-center gap-2"><Coins size={20}/> 100</span></p>
              <div className="grid grid-cols-5 gap-4 max-h-[400px] overflow-y-auto pr-3 fading-scrollbar">
                {PET_OPTIONS.map(e => (
                  <button key={e} onClick={() => { if(checkCoins(100)) { onUpdate(0,0,0,-100,0,null,e); setShowEmojiPicker(false); } }} className={`text-5xl p-4 rounded-[2rem] border-4 transition-all hover:scale-110 active:scale-90 ${isDarkMode ? 'bg-[#1a1a1a] border-white/5' : 'bg-gray-50 border-black/5 shadow-inner'}`}>{e}</button>
                ))}
              </div>
              <button onClick={() => setShowEmojiPicker(false)} className="w-full mt-10 py-6 bg-gray-500 text-white rounded-3xl font-black uppercase text-sm shadow-xl hover:bg-gray-600 active:translate-y-1 transition-all">Abort Shift</button>
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </div>
  );
};

