                        <motion.div animate={{ x: `${towerBal}%` }} className="w-8 h-8 bg-white rounded-full absolute -top-2 left-0 shadow-lg" />
                      </div>
                      <div className="flex gap-4 w-full">
                        <button onMouseDown={()=>setTowerBal(p=>Math.max(0, p-15))} className="flex-1 p-5 bg-white/20 rounded-2xl font-black">LEFT</button>
                        <button onMouseDown={()=>setTowerBal(p=>Math.min(100, p+15))} className="flex-1 p-5 bg-white/20 rounded-2xl font-black">RIGHT</button>
                      </div>
                    </div>
                  )}

                  {gameMode === 'hunter' && (
                    <div className="w-full h-full bg-black/10 rounded-2xl relative overflow-hidden">
                      {vibeTargets.map(v => (
                        <button key={v.id} onClick={() => { setTapScore(s=>s+1); spawnFloating('+5', 0, 0); setVibeTargets(p=>p.filter(t=>t.id!==v.id)); }} className="absolute text-5xl p-2 hover:scale-125 transition-transform" style={{ left: `${v.x}%`, top: `${v.y}%` }}>{v.emoji}</button>
