                        <button key={card.id} onClick={() => {
                          if (card.flipped || card.matched || flippedIndices.length === 2) return;
                          const next = [...memoryCards];
                          next[i].flipped = true;
                          setMemoryCards(next);
                          setFlippedIndices(p => [...p, i]);
                          if (flippedIndices.length === 1) {
                            const first = memoryCards[flippedIndices[0]];
                            if (first.emoji === card.emoji) {
                              next[flippedIndices[0]].matched = true;
                              next[i].matched = true;
                              setMemoryCards(next);
                              setFlippedIndices([]);
                              setTapScore(s=>s+1);
                              if (tapScore + 1 === 6) handleFinishGame();
                            } else {
                              setTimeout(() => {
                                next[flippedIndices[0]].flipped = false;
                                next[i].flipped = false;
                                setMemoryCards(next);
                                setFlippedIndices([]);
                              }, 1000);
                            }
                          }
                        }} className={`w-14 h-14 rounded-xl flex items-center justify-center text-2xl transition-all shadow-md ${card.flipped || card.matched ? 'bg-white' : 'bg-black/30'}`}>
                          {(card.flipped || card.matched) ? card.emoji : '?'}
                        </button>
                      ))}
                    </div>
                  )}

                  {gameMode === 'hangman' && (
                    <div className="space-y-6">
