                        {'ABCDEFGHIJKLMNOPQRSTUVWXYZ'.split('').map(l => (
                          <button key={l} disabled={hangmanState.guessed.includes(l)} onClick={() => {
                            const next = { ...hangmanState, guessed: [...hangmanState.guessed, l] };
                            if (!hangmanState.word.includes(l)) next.lives--;
                            setHangmanState(next);
                            if (next.lives === 0) handleFinishGame();
                            if (next.word.split('').every(ch => next.guessed.includes(ch))) { setTapScore(10); handleFinishGame(); }
                          }} className="w-8 h-8 bg-white/20 rounded-lg text-xs font-black disabled:opacity-30">{l}</button>
                        ))}
                      </div>
                      <p className="font-black">LIVES: {hangmanState.lives}</p>
                    </div>
                  )}

                  {gameMode === 'connect' && (
                    <div className="w-full h-full relative">
                      {dots.map(d => (
