                            nextDots[d.id].active = true;
                            setDots(nextDots);
                            setNextDot(p => p + 1);
                            setTapScore(s=>s+1);
                            if (d.id === 5) handleFinishGame();
                          }
                        }} className={`absolute w-12 h-12 rounded-full flex items-center justify-center font-black border-4 ${d.active ? 'bg-white text-slate-900 border-white' : 'bg-transparent border-white/50'}`} style={{ left: `${d.x}%`, top: `${d.y}%` }}>{d.id + 1}</button>
                      ))}
                    </div>
