const GAMES = [
  { id: 'clicker', name: 'Coin Clicker', emoji: '🪙', color: 'bg-yellow-400', time: 10, desc: 'Rapid Taps' },
  { id: 'hunter', name: 'Vibe Hunter', emoji: '🏹', color: 'bg-red-400', time: 15, desc: 'Catch Vibes' },
