  { id: 'wheel', name: 'Spin Wheel', emoji: '🎡', color: 'bg-orange-400', time: 5, desc: 'Roulette Rewards' },
  { id: 'hangman', name: 'Word Crypt', emoji: '🔠', color: 'bg-teal-400', time: 30, desc: 'Guess Word' },
];

const PET_OPTIONS = ['🐱', '🐶', '🦊', '🦁', '🐨', '🐼', '🦄', '🐲', '🐸', '🐹', '🐰', '🐯', '🐧', '🐻', '🦉'];

const ITEMS = [
  { id: 'f1', type: 'hunger', name: 'Munchies', emoji: '🍿', cost: 10, fill: 15 },
  { id: 'f2', type: 'hunger', name: 'Burger', emoji: '🍔', cost: 25, fill: 40 },
  { id: 'd1', type: 'thirst', name: 'Water', emoji: '💧', cost: 5, fill: 10 },
  { id: 'd2', type: 'thirst', name: 'Energy', emoji: '⚡', cost: 20, fill: 35 },
];

const SLEEP_MODES = [
  { id: 'short', name: 'Napping', duration: 5, rest: 30, exp: 10, cost: 0, emoji: '😴' },
  { id: 'deep', name: 'Hibernate', duration: 60, rest: 100, exp: 200, cost: 50, emoji: '🌌' },
];

const HANGMAN_WORDS = ['CITIZEN', 'MOODERIA', 'GALAXY', 'DYNAMICS', 'RESONANCE', 'METROPOLIS', 'FREQUENCY', 'PHANTOM', 'VIBRATION', 'AURORA', 'COSMIC', 'QUANTUM'];

const MoodPetSection: React.FC<MoodPetSectionProps> = ({ user, isDarkMode, onUpdate, onPost }) => {
  const [activeTab, setActiveTab] = useState<'Interaction' | 'Shop' | 'Games'>('Interaction');
  const [gameMode, setGameMode] = useState<string | null>(null);
  const [gameResult, setGameResult] = useState<{ coins: number, exp: number, bonus?: string } | null>(null);
  const [timeLeft, setTimeLeft] = useState(0);
  const [tapScore, setTapScore] = useState(0);
  const [floatingTexts, setFloatingTexts] = useState<{id: number, text: string, x: number, y: number}[]>([]);

  // Mini-game specific
  const [mathProb, setMathProb] = useState({ q: '', a: 0 });
  const [mathInput, setMathInput] = useState('');
  const [vibeTargets, setVibeTargets] = useState<{id: number, x: number, y: number, emoji: string}[]>([]);
  const [memoryCards, setMemoryCards] = useState<{id: number, emoji: string, matched: boolean, flipped: boolean}[]>([]);
  const [flippedIndices, setFlippedIndices] = useState<number[]>([]);
  const [wheelSpinning, setWheelSpinning] = useState(false);
  const [hangmanState, setHangmanState] = useState({ word: '', guessed: [] as string[], lives: 6 });

  const isSleeping = user.petSleepUntil && user.petSleepUntil > Date.now();
  const isDepleted = user.petHunger <= 0 || user.petThirst <= 0 || user.petRest <= 0;

  useEffect(() => {
    let timer: number;
    if (gameMode && timeLeft > 0 && !gameResult) {
      timer = window.setInterval(() => setTimeLeft(prev => prev - 1), 1000);
    } else if (gameMode && timeLeft === 0 && !gameResult) {
      handleFinishGame();
    }
    return () => clearInterval(timer);
  }, [gameMode, timeLeft, gameResult]);

  const genMath = () => {
    const a = Math.floor(Math.random() * 25) + 1;
    const b = Math.floor(Math.random() * 25) + 1;
    setMathProb({ q: `${a} + ${b}`, a: a + b });
    setMathInput('');
  };

  const genMemory = () => {
    const emojis = ['🐨', '🐼', '🦊', '🦁', '🦉', '🦄'];
    const deck = [...emojis, ...emojis].sort(() => Math.random() - 0.5).map((e, i) => ({ id: i, emoji: e, flipped: false, matched: false }));
    setMemoryCards(deck);
    setFlippedIndices([]);
  };

  const genHangman = () => {
    const word = HANGMAN_WORDS[Math.floor(Math.random() * HANGMAN_WORDS.length)];
    setHangmanState({ word, guessed: [], lives: 6 });
  };

  const handleStartGame = (id: string) => {
    if (isDepleted) {
      alert("Guardian is too exhausted to sync! Use the Shop or Interaction first.");
      return;
    }
    const cd = user.gameCooldowns?.[id];
    if (cd && cd > Date.now()) {
      alert(`Terminal Cooling Down... (${Math.ceil((cd - Date.now())/1000)}s)`);
      return;
    }
    setGameMode(id);
    setGameResult(null);
    setTapScore(0);
    setTimeLeft(GAMES.find(g => g.id === id)?.time || 15);
    if (id === 'math') genMath();
    if (id === 'memory') genMemory();
    if (id === 'hangman') genHangman();
  };

  const handleFinishGame = (rewards?: { coins: number, exp: number, bonus?: string }) => {
    let coins = rewards?.coins || 20;
    let exp = rewards?.exp || 50;
    let bonus = rewards?.bonus;

    if (gameMode === 'clicker') { coins = Math.min(60, tapScore * 2); exp = tapScore * 5; }
    if (gameMode === 'hunter') { coins = Math.min(80, tapScore * 5); exp = tapScore * 10; }
    if (gameMode === 'math') { coins = Math.min(100, tapScore * 8); exp = tapScore * 20; }
    if (gameMode === 'memory') { coins = tapScore === 6 ? 120 : 30; exp = 200; }

    setGameResult({ coins, exp, bonus });
    onUpdate(-8, -12, -5, coins, exp, null, undefined, undefined, undefined, gameMode!);
  };

  const handleSpin = () => {
    if (wheelSpinning) return;
    setWheelSpinning(true);
    setTimeout(() => {
      const outcomes = [
        { coins: 200, exp: 0, bonus: 'BIG JACKPOT!' },
        { coins: 0, exp: 500, bonus: 'XP BURST!' },
        { coins: 50, exp: 50, bonus: 'MEGA SYNC' },
        { coins: 0, exp: 0, bonus: 'EMPTY TERMINAL' },
        { coins: 20, exp: 20, bonus: 'MILD REWARD' }
      ];
      const win = outcomes[Math.floor(Math.random() * outcomes.length)];
      setWheelSpinning(false);
      handleFinishGame(win);
    }, 2500);
  };

  const spawnFloating = (text: string, x: number, y: number) => {
    const id = Date.now();
    setFloatingTexts(prev => [...prev, { id, text, x, y }]);
    setTimeout(() => setFloatingTexts(prev => prev.filter(f => f.id !== id)), 800);
  };

  if (isSleeping) {
    return (
      <div className="p-10 rounded-[3rem] bg-indigo-900 text-white shadow-2xl flex flex-col items-center justify-center text-center gap-6 relative overflow-hidden min-h-[400px]">
        <Lock size={64} className="text-indigo-300 animate-pulse" />
        <h2 className="text-4xl font-black uppercase italic tracking-tighter">System Restoration</h2>
        <p className="opacity-60 text-xs font-bold uppercase tracking-widest">Unavailable until cycle completion</p>
        <div className="bg-black/30 px-8 py-4 rounded-2xl border-4 border-white/10 text-3xl font-black tabular-nums">
          <Timer className="inline mr-2" /> {Math.ceil((user.petSleepUntil! - Date.now()) / 60000)}m
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className={`p-8 rounded-[3rem] ${isDarkMode ? 'bg-[#111111]' : 'bg-white'} border-4 border-black/5 shadow-2xl flex flex-col items-center relative overflow-hidden`}>
        <div className="absolute top-6 left-6 flex items-center gap-2 bg-yellow-400 text-white px-4 py-2 rounded-xl font-black text-xs shadow-lg border-b-4 border-yellow-600">
          <Coins size={14}/> {user.moodCoins}
        </div>
        <div className="text-center mt-4">
          <h3 className="text-2xl font-black italic uppercase tracking-tighter mb-1">{user.petName}</h3>
          <div className="flex items-center justify-center gap-2 bg-black/5 px-4 py-1 rounded-full"><Activity size={12} className="text-custom"/><span className="text-[10px] font-black opacity-40 uppercase tracking-widest">LVL {user.petLevel}</span></div>
        </div>
        <motion.div animate={{ y: [0, -20, 0] }} transition={{ duration: 4, repeat: Infinity }} className="text-[140px] md:text-[180px] my-6 select-none drop-shadow-2xl">
          {user.petEmoji}
        </motion.div>
        <div className="w-full max-w-xs grid grid-cols-3 gap-4">
          {[
            { label: 'Hunger', val: user.petHunger, color: 'bg-red-500' },
            { label: 'Thirst', val: user.petThirst, color: 'bg-blue-500' },
            { label: 'Rest', val: user.petRest, color: 'bg-green-500' },
          ].map(bar => (
            <div key={bar.label} className="text-center space-y-1.5">
              <span className="text-[8px] font-black opacity-50 uppercase">{bar.label}</span>
