          <button key={item.id} onClick={() => { if(user.moodCoins >= item.cost) onUpdate(item.type === 'hunger' ? item.fill : 0, item.type === 'thirst' ? item.fill : 0, 0, -item.cost, 15); }} className={`p-6 rounded-[2.5rem] border-4 border-black/5 bg-white text-slate-900 shadow-xl flex flex-col items-center gap-1 group hover:scale-105 transition-transform`}>
