        ))}

        {gameMode && (
          <div className={`col-span-full p-8 rounded-[3.5rem] text-white text-center shadow-2xl relative border-8 border-white/20 min-h-[400px] flex flex-col ${GAMES.find(g=>g.id===gameMode)?.color}`}>
            <div className="flex-1 relative flex flex-col">
              {gameResult ? (
                <div className="flex-1 flex flex-col items-center justify-center space-y-8">
