import React, { useState, useEffect, useRef, useMemo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Heart, MessageCircle, Repeat, Send, Sparkles, Brain, Clock, Globe, Users, Trophy } from 'lucide-react';
import { User, Post, Comment } from '../types';
import MoodPetSection from './MoodPetSection';
import { getTellerResponse } from '../services/geminiService';

interface MoodSectionProps {
  user: User;
  posts: Post[];
  onPost: (content: string, visibility: 'global' | 'circle') => void;
  onHeart: (postId: string) => void;
  onComment: (postId: string, text: string) => void;
  onRepost: (post: Post) => void;
  onFollow: (username: string) => void;
  onBlock: (username: string) => void;
  isDarkMode: boolean;
  onNavigateToProfile: (username: string) => void;
  onUpdatePet: (hunger: number, thirst: number, rest: number, coins: number, exp?: number, sleepUntil?: number | null, newEmoji?: string, markChosen?: boolean, newName?: string, gameCooldownId?: string) => void;
}

type MoodSubTab = 'Express' | 'Teller' | 'Scan' | 'Mood Pet';

const EMOTIONAL_QUIZ = [
  { q: "How did you feel the moment you woke up today?", options: ["Refreshed", "Stressed", "Meh", "Excited"], weights: { Happy: 1, Angry: 0, Tired: -1, Normal: 0 } },
  { q: "What's the weather in your internal 'City' right now?", options: ["Sunny", "Stormy", "Foggy", "Clear Skies"], weights: { Happy: 2, Angry: 1, Tired: 0, Normal: 1 } },
  { q: "How much energy do you have for socializing?", options: ["Tons!", "None", "Maybe later", "Only with friends"], weights: { Happy: 1, Tired: 1, Normal: 0, Excited: 2 } },
  { q: "Pick a color that resonates with you right now.", options: ["Crimson Red", "Soft Blue", "Bright Yellow", "Forest Green"], weights: { Angry: 1, Tired: 1, Happy: 1, Normal: 1 } },
  { q: "Is your mind busy or quiet?", options: ["Race track", "Library", "Zen garden", "Static noise"], weights: { Excited: 1, Normal: 1, Happy: 1, Tired: 1 } },
  { q: "What is your current physical comfort level?", options: ["Perfect", "A bit sore", "Exhausted", "Tense"], weights: { Happy: 1, Normal: 0, Tired: 2, Angry: 1 } },
  { q: "If you were a sound, what would you be?", options: ["A drum solo", "Soft rain", "White noise", "A symphony"], weights: { Angry: 1, Normal: 1, Tired: 1, Happy: 1 } },
  { q: "How do you feel about your tasks today?", options: ["Ready to crush!", "Dreading them", "I'll manage", "What tasks?"], weights: { Excited: 2, Angry: 1, Normal: 1, Happy: 1 } },
  { q: "Choose a snack mood.", options: ["Something spicy", "Something sweet", "Something healthy", "Nothing"], weights: { Angry: 1, Happy: 1, Normal: 1, Tired: 1 } },
  { q: "Finally, how would you rate your patience level?", options: ["Infinite", "Fragile", "Short", "Average"], weights: { Happy: 1, Tired: 1, Angry: 2, Normal: 1 } },
];

const MoodSection: React.FC<MoodSectionProps> = ({ user, posts, onPost, onHeart, onComment, onRepost, onFollow, onBlock, isDarkMode, onNavigateToProfile, onUpdatePet }) => {
  const [subTab, setSubTab] = useState<MoodSubTab>('Express');
  const [postContent, setPostContent] = useState('');
  const [feedFilter, setFeedFilter] = useState<'Global' | 'Circle'>('Global');
  const [postVisibility, setPostVisibility] = useState<'global' | 'circle'>('global');

  const [tellerQuestion, setTellerQuestion] = useState('');
  const [tellerResponse, setTellerResponse] = useState('');
  const [isTellerLoading, setIsTellerLoading] = useState(false);

  const [quizActive, setQuizActive] = useState(false);
  const [quizStep, setQuizStep] = useState(0);
  const [quizScores, setQuizScores] = useState<Record<string, number>>({ Happy: 0, Angry: 0, Tired: 0, Normal: 0, Excited: 0 });
  const [quizResult, setQuizResult] = useState<string | null>(null);

  const filteredPosts = useMemo(() => {
    if (feedFilter === 'Global') {
      return posts.filter(p => p.visibility === 'global');
    }
    return posts.filter(p => p.visibility === 'circle' && (user.following.includes(p.author) || p.author === user.username));
  }, [posts, feedFilter, user.following, user.username]);

  const handlePost = () => {
    if (!postContent.trim()) return;
    onPost(postContent, postVisibility);
    setPostContent('');
  };

  const handleTeller = async () => {
    if (!tellerQuestion.trim()) return;
    setIsTellerLoading(true);
    setTellerResponse('');
    try {
      const res = await getTellerResponse(tellerQuestion);
      setTellerResponse(res || 'The static clouds the view.');
    } catch (e) {
      setTellerResponse("The stars are unavailable. Try later.");
    } finally {
      setIsTellerLoading(false);
    }
  };

  const startQuiz = () => {
    setQuizActive(true);
    setQuizStep(0);
    setQuizScores({ Happy: 0, Angry: 0, Tired: 0, Normal: 0, Excited: 0 });
    setQuizResult(null);
  };

  // Fixed arithmetic operation errors by explicitly typing the state object and casting values during operations
  const handleQuizAnswer = (idx: number) => {
    const currentWeights = EMOTIONAL_QUIZ[quizStep].weights;
    const nextScores: Record<string, number> = { ...quizScores };

    Object.entries(currentWeights).forEach(([key, val]) => {
      // Accessing state by string key and ensuring valid arithmetic operand
      const currentScoreVal = nextScores[key] || 0;
      nextScores[key] = currentScoreVal + (val as number);
    });

    if (quizStep < EMOTIONAL_QUIZ.length - 1) {
      setQuizStep(s => s + 1);
    } else {
      // Sorting operation explicitly casting numeric values for arithmetic subtraction
      const sortedEntries = Object.entries(nextScores).sort((a, b) => (b[1] as number) - (a[1] as number));
      setQuizResult(sortedEntries[0][0]);
      onUpdatePet(0, 0, 0, 50, 100);
    }
  };

  const formatTime = (ts: number) => {
    const diff = Date.now() - ts;
    if (diff < 60000) return 'Just now';
    if (diff < 3600000) return `${Math.floor(diff / 60000)}m ago`;
    return new Date(ts).toLocaleDateString();
  };

  return (
    <div className="flex flex-col gap-4 md:gap-8 pb-10 h-full overflow-hidden">
      <div className="flex gap-2 overflow-x-auto no-scrollbar pb-2 shrink-0">
        {(['Express', 'Teller', 'Scan', 'Mood Pet'] as MoodSubTab[]).map((t) => (
          <button key={t} onClick={() => setSubTab(t)} className={`px-6 md:px-8 py-2.5 md:py-3 rounded-full font-black text-[10px] md:text-xs transition-all whitespace-nowrap uppercase tracking-tighter border-b-4 ${subTab === t ? 'bg-custom border-black/20 text-white shadow-xl' : isDarkMode ? 'bg-[#1a1a1a] border-black text-white/30' : 'bg-white border-gray-100 text-slate-500 shadow-sm'}`}>
            {t}
          </button>
        ))}
      </div>

      <div className="flex-1 overflow-y-auto fading-scrollbar pr-2">
        <AnimatePresence mode="wait">
          {subTab === 'Express' && (
            <motion.div key="express" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="space-y-4 md:space-y-6">
              <div className={`p-4 md:p-8 rounded-[2rem] md:rounded-[3rem] ${isDarkMode ? 'bg-[#111111]' : 'bg-white'} border-4 border-black/5 shadow-2xl relative`}>
                <textarea value={postContent} onChange={(e) => setPostContent(e.target.value)} placeholder={postVisibility === 'global' ? "Global Broadcast..." : "Circle Whisper..."} className={`w-full ${isDarkMode ? 'bg-[#1a1a1a] text-white' : 'bg-gray-50 text-slate-900'} p-4 md:p-6 rounded-2xl md:rounded-[2rem] border-2 md:border-4 border-black/5 focus:border-custom outline-none font-bold text-sm md:text-lg shadow-inner`} rows={window.innerWidth < 768 ? 2 : 3} />
                <div className="flex flex-wrap justify-between items-center mt-3 md:mt-6 gap-3">
                  <div className="flex gap-2">
                    <button onClick={() => setPostVisibility('global')} className={`flex items-center gap-2 px-3 py-1.5 rounded-xl text-[10px] font-black uppercase transition-all ${postVisibility === 'global' ? 'bg-custom text-white shadow-md' : 'opacity-40'}`}><Globe size={14}/> GLOBAL</button>
                    <button onClick={() => setPostVisibility('circle')} className={`flex items-center gap-2 px-3 py-1.5 rounded-xl text-[10px] font-black uppercase transition-all ${postVisibility === 'circle' ? 'bg-custom text-white shadow-md' : 'opacity-40'}`}><Users size={14}/> CIRCLE</button>
                  </div>
                  <button onClick={handlePost} className="kahoot-button-custom px-8 md:px-12 py-3 md:py-4 text-white rounded-xl md:rounded-[1.5rem] font-black text-xs md:text-sm flex items-center gap-2 md:gap-3 shadow-xl"><Send size={18} /> BROADCAST</button>
                </div>
              </div>
              <div className="flex gap-2 bg-black/5 p-1 rounded-2xl w-fit">
                <button onClick={() => setFeedFilter('Global')} className={`px-4 md:px-6 py-2 rounded-xl text-[10px] md:text-xs font-black uppercase transition-all ${feedFilter === 'Global' ? 'bg-white text-custom shadow-md' : 'opacity-40'}`}>Global Feed</button>
                <button onClick={() => setFeedFilter('Circle')} className={`px-4 md:px-6 py-2 rounded-xl text-[10px] md:text-xs font-black uppercase transition-all ${feedFilter === 'Circle' ? 'bg-white text-custom shadow-md' : 'opacity-40'}`}>Circle Feed</button>
              </div>
              <div className="space-y-4 pb-24">
                {filteredPosts.map(post => (
                  <div key={post.id} className={`p-6 md:p-8 rounded-[2rem] md:rounded-[3rem] ${isDarkMode ? 'bg-[#111111] text-white' : 'bg-white text-slate-900'} border-4 border-black/5 shadow-xl transition-all`}>
                    <div className="flex items-center justify-between mb-4">
                      <div className="flex items-center gap-3">
                        <button onClick={() => onNavigateToProfile(post.author)} className="w-10 h-10 md:w-14 rounded-xl bg-custom text-white font-black shrink-0 text-lg">{post.author[0].toUpperCase()}</button>
                        <div><h4 className="font-black text-xs md:text-base leading-tight">@{post.author}</h4><p className="text-[8px] md:text-[9px] font-black opacity-30 flex items-center gap-1"><Clock size={10}/> {formatTime(post.timestamp)}</p></div>
                      </div>
                      <div className="flex items-center gap-2">{post.visibility === 'circle' && <Users size={14} className="text-indigo-400" />}{post.isRepost && <div className="bg-green-500/10 text-green-500 px-3 py-1 rounded-full border border-green-500/20 text-[8px] font-black uppercase">Echo</div>}</div>
                    </div>
                    <p className="text-sm md:text-lg font-medium italic opacity-90 mb-4">"{post.content}"</p>
                    <div className="flex items-center gap-6 pt-4 border-t border-black/5">
                      <button onClick={() => onHeart(post.id)} className="flex items-center gap-2 text-custom font-black text-[10px]"><Heart size={18} fill={post.hearts > 0 ? "currentColor" : "none"} /> {post.hearts}</button>
                      <button onClick={() => onRepost(post)} className="flex items-center gap-2 text-green-500 font-black text-[10px]"><Repeat size={18} /> ECHO</button>
                    </div>
                  </div>
                ))}
              </div>
            </motion.div>
          )}

          {subTab === 'Teller' && (
            <motion.div key="teller" initial={{ opacity: 0 }} animate={{ opacity: 1 }} className={`p-10 rounded-[3rem] ${isDarkMode ? 'bg-[#111111]' : 'bg-white'} border-4 border-black/5 shadow-2xl text-center min-h-[400px] flex flex-col justify-center`}>
              <div className="text-8xl mb-8 animate-pulse">🔮</div>
              <h3 className="text-3xl font-black italic uppercase mb-8">Mystic Teller</h3>
              <input type="text" value={tellerQuestion} onChange={e => setTellerQuestion(e.target.value)} placeholder="Will I find peace today?" className={`w-full p-5 rounded-2xl border-4 outline-none font-black text-lg mb-4 ${isDarkMode ? 'bg-slate-800' : 'bg-gray-50'}`} />
              <button onClick={handleTeller} disabled={isTellerLoading} className="kahoot-button-custom w-full py-5 rounded-2xl text-white font-black uppercase text-xl">CONSULT THE VOID</button>
              {tellerResponse && <p className="mt-8 text-2xl font-black italic text-custom">{tellerResponse}</p>}
            </motion.div>
          )}

          {subTab === 'Scan' && (
            <motion.div key="scan" initial={{ opacity: 0 }} animate={{ opacity: 1 }} className={`p-10 rounded-[3rem] ${isDarkMode ? 'bg-[#111111]' : 'bg-white'} border-4 border-black/5 shadow-2xl text-center min-h-[400px] flex flex-col justify-center`}>
              {!quizActive ? (
                <>
                  <Brain size={80} className="mx-auto text-custom mb-6" />
                  <h3 className="text-3xl font-black italic uppercase mb-10">Metropolis Scan</h3>
                  <button onClick={startQuiz} className="kahoot-button-custom px-16 py-6 rounded-3xl text-white font-black text-2xl">START SCAN</button>
                </>
              ) : quizResult ? (
                <>
                  <Trophy className="text-yellow-500 mx-auto mb-6" size={100} />
                  <p className="text-6xl font-black text-custom italic uppercase mb-10">{quizResult}</p>
                  <button onClick={() => { onPost(`SCAN COMPLETE: Emotion is ${quizResult}! 🧬`, 'global'); setQuizActive(false); }} className="kahoot-button-blue w-full py-5 rounded-2xl text-white font-black uppercase shadow-xl">BROADCAST RESULTS</button>
                </>
              ) : (
                <div className="max-w-2xl mx-auto w-full">
                  <h4 className="text-2xl font-black mb-8 italic">{EMOTIONAL_QUIZ[quizStep].q}</h4>
                  <div className="grid gap-4">
                    {EMOTIONAL_QUIZ[quizStep].options.map((opt, i) => (
                      <button key={i} onClick={() => handleQuizAnswer(i)} className="p-6 rounded-2xl border-4 border-black/5 font-black bg-gray-50 hover:border-custom transition-all">{opt}</button>
                    ))}
                  </div>
                </div>
              )}
            </motion.div>
          )}

          {subTab === 'Mood Pet' && (
            <motion.div key="pet" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}>
              <MoodPetSection user={user} isDarkMode={isDarkMode} onUpdate={onUpdatePet} onPost={(c) => onPost(c, 'global')} />
            </motion.div>
          )}
        </AnimatePresence>
      </div>
    </div>
  );
};

