                  <button onClick={() => setGameMode(null)} className="w-full max-w-xs py-5 bg-white text-slate-900 rounded-2xl font-black uppercase text-sm shadow-xl">EXIT TERMINAL</button>
                </div>
              ) : (
                <>
                  <div className="flex justify-between items-center mb-10 bg-black/20 px-6 py-4 rounded-[1.5rem]">
                    <span className="font-black uppercase text-xs italic">{gameMode.toUpperCase()} ACTIVE</span>
                    <span className="font-black text-2xl tabular-nums"><Timer className="inline mr-2" size={24}/> {timeLeft}s</span>
                  </div>
                  <div className="flex-1 relative flex items-center justify-center">
                    {gameMode === 'wheel' && (
                      <div className="flex flex-col items-center gap-10">
                        <motion.div animate={{ rotate: wheelSpinning ? 1800 : 0 }} transition={{ duration: 2.5, ease: [0.1, 0, 0.1, 1] }} className="w-56 h-56 bg-white rounded-full border-[12px] border-black/10 flex items-center justify-center relative shadow-2xl">
                          <div className="grid grid-cols-2 grid-rows-2 w-full h-full opacity-20 absolute rotate-45"><div className="bg-red-500"></div><div className="bg-blue-500"></div><div className="bg-yellow-500"></div><div className="bg-green-500"></div></div>
                          <RefreshCcw size={64} className="text-slate-900 animate-spin-slow" />
                        </motion.div>
                        <button onClick={handleSpin} disabled={wheelSpinning} className="kahoot-button-custom px-12 py-5 rounded-2xl text-white font-black uppercase text-xl shadow-xl">PULL LEVER</button>
                      </div>
                    )}
                    {gameMode === 'clicker' && (
                      <motion.button whileTap={{ scale: 0.8 }} onClick={() => setTapScore(s=>s+1)} className="w-56 h-56 bg-yellow-400 rounded-full shadow-[0_20px_0_0_#ca8a04] flex items-center justify-center text-9xl font-black border-[12px] border-white/20 active:translate-y-4 active:shadow-none transition-all">
                        <DollarSign size={100} />
                      </motion.button>
                    )}
                    {gameMode === 'math' && (
                      <div className="space-y-10 w-full max-w-sm">
                        <p className="text-8xl font-black italic tracking-tighter">{mathProb.q}</p>
                        <input type="number" autoFocus value={mathInput} onChange={e => { setMathInput(e.target.value); if(parseInt(e.target.value) === mathProb.a) { setTapScore(s=>s+1); genMath(); } }} className="w-full p-8 rounded-[2rem] bg-white text-slate-900 font-black text-6xl text-center outline-none" placeholder="?" />
                      </div>
                    )}
                    {gameMode === 'hangman' && (
                      <div className="space-y-8 w-full max-w-md">
                        <p className="text-4xl md:text-5xl font-black tracking-[0.3em] bg-black/10 p-6 rounded-3xl">{hangmanState.word.split('').map(l => hangmanState.guessed.includes(l) ? l : '_').join(' ')}</p>
                        <div className="grid grid-cols-6 md:grid-cols-8 gap-2">
                          {'ABCDEFGHIJKLMNOPQRSTUVWXYZ'.split('').map(l => (
                            <button key={l} disabled={hangmanState.guessed.includes(l)} onClick={() => {
                              const next = { ...hangmanState, guessed: [...hangmanState.guessed, l] };
                              if (!hangmanState.word.includes(l)) next.lives--;
                              setHangmanState(next);
                              if (next.lives === 0) handleFinishGame();
                              if (next.word.split('').every(ch => next.guessed.includes(ch))) { setTapScore(15); handleFinishGame({ coins: 150, exp: 300, bonus: 'WORD MASTER' }); }
                            }} className={`p-3 rounded-xl font-black text-xs transition-all ${hangmanState.guessed.includes(l) ? 'opacity-20' : 'bg-white/20 hover:bg-white/40'}`}>{l}</button>
                          ))}
                        </div>
                        <p className="font-black text-xl uppercase tracking-widest">COORDINATES LEFT: {hangmanState.lives}</p>
                      </div>
                    )}
                  </div>
                </>
              )}
            </div>
          </div>
        )}

        {activeTab === 'Interaction' && (
          <div className="col-span-full space-y-6">
            <div className="grid grid-cols-2 gap-4">
              {SLEEP_MODES.map(mode => (
                <button key={mode.id} onClick={() => onUpdate(0,0,mode.rest, -mode.cost, mode.exp, Date.now() + mode.duration * 60000)} className="p-8 rounded-[2.5rem] border-4 border-black/5 bg-white text-slate-900 shadow-xl flex flex-col items-center gap-3 transition-transform hover:scale-105 active:translate-y-1">
                  <span className="text-5xl mb-2">{mode.emoji}</span>
                  <p className="font-black uppercase text-sm tracking-tighter">{mode.name}</p>
                  <p className="text-[10px] font-black text-blue-500 opacity-60">+{mode.rest}% REST</p>
                  <div className="bg-yellow-400 text-white px-5 py-2 rounded-2xl text-xs font-black border-b-4 border-yellow-600 flex items-center gap-2"><Coins size={14}/> {mode.cost}</div>
                </button>
              ))}
            </div>
            <button onClick={() => onUpdate(0,0,0,0,10)} className="w-full p-10 rounded-[3rem] bg-custom text-white shadow-2xl flex flex-col items-center justify-center gap-4 border-b-[12px] border-black/20 active:translate-y-2 active:border-b-0 transition-all">
              <Heart size={64} className="animate-pulse" />
              <span className="font-black text-2xl italic uppercase tracking-tighter">CITIZEN INTERACT (+10 XP)</span>
            </button>
          </div>
        )}
      </div>
    </div>
  );
};

export default MoodPetSection;

import React, { useState, useEffect, useMemo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { User, Mood, Section, Post, Comment, Message, Notification } from './types';
import Sidebar from './components/Sidebar';
import MoodCheckIn from './components/MoodCheckIn';
import HomeSection from './sections/HomeSection';
import MoodSection from './sections/MoodSection';
import ZodiacSection from './sections/ZodiacSection';
import CityHallSection from './sections/CityHallSection';
import ProfileSection from './sections/ProfileSection';
import SettingsSection from './sections/SettingsSection';
import NotificationsSection from './sections/NotificationsSection';
import AuthScreen from './sections/AuthScreen';
import LoadingScreen from './components/LoadingScreen';
import { getExpNeeded, MOOD_SCORES } from './constants';
import { Trophy, Share2, X } from 'lucide-react';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [activeSection, setActiveSection] = useState<Section>('Home');
  const [viewingUsername, setViewingUsername] = useState<string | null>(null);
  const [isMoodModalOpen, setIsMoodModalOpen] = useState(false);
  const [isDarkMode, setIsDarkMode] = useState(false); 
  const [isAppStarting, setIsAppStarting] = useState(true);
  const [levelUpInfo, setLevelUpInfo] = useState<{ level: number } | null>(null);

  const [allPosts, setAllPosts] = useState<Post[]>([]);
  const [allMessages, setAllMessages] = useState<Message[]>([]);
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);

  const profileToView = useMemo(() => {
    if (!viewingUsername) return null;
    if (currentUser && viewingUsername === currentUser.username) return currentUser;
    const allUsers: User[] = JSON.parse(localStorage.getItem('mooderia_all_users') || '[]');
    return allUsers.find(u => u.username === viewingUsername) || null;
  }, [viewingUsername, currentUser]);

  // Handle Mood Check-in Trigger
  const triggerMoodCheck = (user: User) => {
    const todayStr = new Date().toDateString();
    if (user.lastMoodDate !== todayStr) {
      setIsMoodModalOpen(true);
    }
  };

  useEffect(() => {
    const savedUser = localStorage.getItem('mooderia_user');
    const savedPosts = localStorage.getItem('mooderia_posts') || '[]';
    const savedMessages = localStorage.getItem('mooderia_messages') || '[]';
    const savedNotifications = localStorage.getItem('mooderia_notifications') || '[]';
    const savedTheme = localStorage.getItem('mooderia_theme');

    if (savedUser) {
      const user: User = JSON.parse(savedUser);
      // Simulate pet drain based on last update
      const now = Date.now();
      const elapsedMinutes = Math.floor((now - (user.petLastUpdate || now)) / 60000);
      if (elapsedMinutes > 0) {
        user.petHunger = Math.max(0, user.petHunger - elapsedMinutes * 0.15);
        user.petThirst = Math.max(0, user.petThirst - elapsedMinutes * 0.2);
        if (!user.petSleepUntil || user.petSleepUntil < now) {
          user.petRest = Math.max(0, user.petRest - elapsedMinutes * 0.1);
        }
        user.petLastUpdate = now;
      }
      if (!user.gameCooldowns) user.gameCooldowns = {};
      setCurrentUser(user);
      triggerMoodCheck(user);
    }

    setAllPosts(JSON.parse(savedPosts));
    setAllMessages(JSON.parse(savedMessages));
    setNotifications(JSON.parse(savedNotifications));
    if (savedTheme === 'dark') setIsDarkMode(true);
    setIsLoaded(true);

    const timer = setTimeout(() => setIsAppStarting(false), 2000);
    return () => clearTimeout(timer);
  }, []);

  useEffect(() => {
    if (!isLoaded) return;
    if (currentUser) {
      localStorage.setItem('mooderia_user', JSON.stringify(currentUser));
      const allUsers: User[] = JSON.parse(localStorage.getItem('mooderia_all_users') || '[]');
      const idx = allUsers.findIndex(u => u.username === currentUser.username);
      if (idx > -1) {
        allUsers[idx] = currentUser;
        localStorage.setItem('mooderia_all_users', JSON.stringify(allUsers));
      }
    }
    localStorage.setItem('mooderia_posts', JSON.stringify(allPosts));
    localStorage.setItem('mooderia_messages', JSON.stringify(allMessages));
    localStorage.setItem('mooderia_notifications', JSON.stringify(notifications));
    localStorage.setItem('mooderia_theme', isDarkMode ? 'dark' : 'light');
  }, [currentUser, allPosts, allMessages, notifications, isDarkMode, isLoaded]);

  const handleEditProfile = (displayName: string, username: string, profilePic?: string, title?: string, bannerPic?: string, profileColor?: string, bio?: string) => {
    if (!currentUser) return;
    setCurrentUser({
      ...currentUser,
      displayName: displayName.slice(0, 20),
      username,
      profilePic: profilePic || currentUser.profilePic,
      title: title || currentUser.title,
      profileColor: profileColor || currentUser.profileColor,
      bio: bio || currentUser.bio
    });
  };

  const updatePetStats = (hunger: number, thirst: number, rest: number, coins: number, exp: number = 0, sleepUntil: number | null = null, newEmoji?: string, markChosen?: boolean, newName?: string, gameCooldownId?: string) => {
    if (!currentUser) return;
    let oldLevel = currentUser.petLevel;
    let newLevel = currentUser.petLevel;
    let newExp = currentUser.petExp + exp;
    while (newExp >= getExpNeeded(newLevel)) {
      newExp -= getExpNeeded(newLevel);
      newLevel += 1;
    }

    if (newLevel > oldLevel) {
      setLevelUpInfo({ level: newLevel });
    }

    const updatedCooldowns = { ...currentUser.gameCooldowns };
    if (gameCooldownId) {
      updatedCooldowns[gameCooldownId] = Date.now() + 60000; 
    }

    setCurrentUser({
      ...currentUser,
      petName: newName || currentUser.petName,
      petHunger: Math.min(100, Math.max(0, currentUser.petHunger + hunger)),
      petThirst: Math.min(100, Math.max(0, currentUser.petThirst + thirst)),
      petRest: Math.min(100, Math.max(0, currentUser.petRest + rest)),
      petExp: newExp,
      petLevel: newLevel,
      moodCoins: currentUser.moodCoins + coins,
      petSleepUntil: sleepUntil !== undefined ? sleepUntil : currentUser.petSleepUntil,
      petEmoji: newEmoji || currentUser.petEmoji,
      petHasBeenChosen: markChosen !== undefined ? markChosen : currentUser.petHasBeenChosen,
      petLastUpdate: Date.now(),
      gameCooldowns: updatedCooldowns
    });
  };

  const shareLevelUp = () => {
    if (!currentUser || !levelUpInfo) return;
    const content = `CONGRATULATIONS! My Guardian ${currentUser.petName} just leveled up to Level ${levelUpInfo.level}! 🏆✨`;
    setAllPosts([{id: Math.random().toString(36).substr(2, 9), author: currentUser.username, content, hearts: 0, comments: [], timestamp: Date.now(), visibility: 'global'}, ...allPosts]);
    setLevelUpInfo(null);
  };

  const handleLogin = (user: User) => {
    setCurrentUser(user);
    triggerMoodCheck(user);
  };

  const themeStyle = useMemo(() => {
    const color = currentUser?.profileColor || '#e21b3c';
    return {
      '--theme-color': color,
      '--theme-color-dark': `${color}cc`,
    } as React.CSSProperties;
  }, [currentUser?.profileColor]);

  if (isAppStarting) return <LoadingScreen />;
  if (!currentUser) return <AuthScreen onLogin={handleLogin} />;

  return (
    <div style={themeStyle} className={`h-screen max-h-screen overflow-hidden flex flex-col md:flex-row ${isDarkMode ? 'bg-[#0f0f0f] text-white' : 'bg-[#f7f8fa] text-slate-900'} transition-colors duration-300`}>
      <style>{`
        :root { --theme-color: ${currentUser.profileColor || '#e21b3c'}; }
        .kahoot-button-custom { background-color: var(--theme-color); border-bottom: 4px solid rgba(0,0,0,0.3); }
        .text-custom { color: var(--theme-color); }
        .bg-custom { background-color: var(--theme-color); }
        .border-custom { border-color: var(--theme-color); }
      `}</style>

      <AnimatePresence>
        {isMoodModalOpen && (
          <MoodCheckIn 
            onSubmit={(m) => {
              const today = new Date().toDateString();
              setCurrentUser({
                ...currentUser,
                moodStreak: currentUser.lastMoodDate === today ? currentUser.moodStreak : (currentUser.moodStreak || 0) + 1,
                lastMoodDate: today,
                moodHistory: [...(currentUser.moodHistory || []), { date: today, mood: m, score: MOOD_SCORES[m || 'Normal'] }]
              });
              setIsMoodModalOpen(false);
            }} 
            isDarkMode={isDarkMode} 
          />
        )}
      </AnimatePresence>

      <AnimatePresence>
        {levelUpInfo && (
          <div className="fixed inset-0 z-[500] flex items-center justify-center p-6 bg-black/90 backdrop-blur-xl">
            <motion.div initial={{ scale: 0.8, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} className={`${isDarkMode ? 'bg-slate-800' : 'bg-white'} w-full max-w-md p-10 rounded-[3rem] shadow-2xl text-center border-4 border-yellow-400`}>
              <Trophy size={80} className="mx-auto text-yellow-500 mb-6 animate-bounce" />
              <h2 className="text-4xl font-black uppercase italic tracking-tighter mb-2">Level Up!</h2>
              <p className="text-xl font-bold opacity-70 mb-8">Your Guardian {currentUser.petName} is now Level {levelUpInfo.level}!</p>
              <div className="flex flex-col gap-3">
                <button onClick={shareLevelUp} className="kahoot-button-yellow w-full py-5 rounded-2xl text-white font-black uppercase flex items-center justify-center gap-2 shadow-xl"><Share2 size={20}/> Share Achievement</button>
                <button onClick={() => setLevelUpInfo(null)} className="p-4 text-xs font-black uppercase opacity-40 hover:opacity-100 transition-opacity">Skip Achievement</button>
              </div>
            </motion.div>
          </div>
        )}
      </AnimatePresence>

      <Sidebar activeSection={activeSection} onNavigate={(s) => { setActiveSection(s); if(s === 'Profile') setViewingUsername(currentUser.username); }} isDarkMode={isDarkMode} user={currentUser} unreadMessages={allMessages.filter(m => m.recipient === currentUser.username && !m.read).length} unreadNotifications={notifications.filter(n => !n.read).length} />
      <main className="flex-1 flex flex-col relative pt-16 pb-20 md:pt-0 md:pb-0 h-full overflow-hidden">
        <div className="flex-1 overflow-y-auto fading-scrollbar p-4 md:p-8">
          <motion.div key={activeSection + (activeSection === 'Profile' ? viewingUsername : '')} initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} className="max-w-5xl mx-auto">
            {activeSection === 'Home' && <HomeSection user={currentUser} posts={allPosts} isDarkMode={isDarkMode} />}
            {activeSection === 'Mood' && <MoodSection 
              user={currentUser} 
              posts={allPosts} 
              onPost={(c, v) => setAllPosts([{id: Math.random().toString(36).substr(2, 9), author: currentUser.username, content: c, hearts: 0, comments: [], timestamp: Date.now(), visibility: v}, ...allPosts])} 
              onHeart={(pid) => setAllPosts(prev => prev.map(p => p.id === pid ? {...p, hearts: p.hearts + 1} : p))} 
              onComment={(pid, t) => setAllPosts(prev => prev.map(p => p.id === pid ? {...p, comments: [...p.comments, {id: Math.random().toString(36).substr(2,9), author: currentUser.username, text: t, timestamp: Date.now(), replies: []}]} : p))} 
              onRepost={(p) => setAllPosts([{ ...p, id: Math.random().toString(36).substr(2, 9), author: currentUser.username, isRepost: true, originalAuthor: p.author, timestamp: Date.now(), visibility: 'global' }, ...allPosts])} 
              onFollow={(u) => {const isF = currentUser.following.includes(u); setCurrentUser({...currentUser, following: isF ? currentUser.following.filter(f => f !== u) : [...currentUser.following, u]});}} 
              onBlock={(u) => {if(!currentUser.blockedUsers.includes(u)) setCurrentUser({...currentUser, blockedUsers: [...currentUser.blockedUsers, u]}); setActiveSection('Home');}} 
              isDarkMode={isDarkMode} 
              onNavigateToProfile={(u) => {setViewingUsername(u); setActiveSection('Profile');}} 
              onUpdatePet={updatePetStats} 
            />}
            {activeSection === 'Zodiac' && <ZodiacSection isDarkMode={isDarkMode} />}
            {activeSection === 'CityHall' && <CityHallSection isDarkMode={isDarkMode} currentUser={currentUser} messages={allMessages} onSendMessage={(r, t) => setAllMessages([...allMessages, {id: Math.random().toString(36).substr(2, 9), sender: currentUser.username, recipient: r, text: t, timestamp: Date.now(), read: false}])} onReadMessages={(u) => setAllMessages(allMessages.map(m => (m.recipient === currentUser.username && m.sender === u) ? {...m, read: true} : m))} onNavigateToProfile={(u) => {setViewingUsername(u); setActiveSection('Profile');}} />}
            {activeSection === 'Notifications' && <NotificationsSection notifications={notifications} isDarkMode={isDarkMode} onMarkRead={() => setNotifications(notifications.map(n => ({...n, read: true})))} />}
            {activeSection === 'Profile' && profileToView && <ProfileSection user={profileToView} allPosts={allPosts} isDarkMode={isDarkMode} onEditProfile={handleEditProfile} onBlock={(u) => {if(!currentUser.blockedUsers.includes(u)) setCurrentUser({...currentUser, blockedUsers: [...currentUser.blockedUsers, u]}); setActiveSection('Home');}} onFollow={(u) => {const isF = currentUser.following.includes(u); setCurrentUser({...currentUser, following: isF ? currentUser.following.filter(f => f !== u) : [...currentUser.following, u]});}} currentUser={currentUser} onShareToExpress={(c) => setAllPosts([{id: Math.random().toString(36).substr(2, 9), author: currentUser.username, content: c, hearts: 0, comments: [], timestamp: Date.now(), visibility: 'global'}, ...allPosts])} />}
            {activeSection === 'Settings' && <SettingsSection isDarkMode={isDarkMode} onToggleDarkMode={() => setIsDarkMode(!isDarkMode)} onLogout={() => {localStorage.removeItem('mooderia_user'); setCurrentUser(null);}} user={currentUser} onUnblock={(u) => setCurrentUser({...currentUser, blockedUsers: currentUser.blockedUsers.filter(b => b !== u)})} />}
          </motion.div>
        </div>
      </main>
    </div>
  );
};

