                <div className="p-6 bg-black/5 rounded-[2rem] text-center border-b-8 border-yellow-500/20"><Star className="mx-auto mb-3 text-yellow-500" size={32}/><p className="text-3xl font-black">{user.moodCoins}</p><p className="text-[10px] font-black opacity-30 uppercase tracking-widest">Mood Coins</p></div>
                <div className="p-6 bg-black/5 rounded-[2rem] text-center border-b-8 border-red-500/20"><Heart className="mx-auto mb-3 text-red-500" size={32}/><p className="text-3xl font-black">{user.likesReceived || 0}</p><p className="text-[10px] font-black opacity-30 uppercase tracking-widest">Global Hearts</p></div>
              </div>

              {moodDistribution && (
                <div className="mt-10 pt-10 border-t-4 border-black/5">
                  <h5 className="text-sm font-black uppercase opacity-40 mb-6 tracking-[0.4em]">Daily Mood Frequency Distribution</h5>
                  <div className="space-y-6">
                    {moodDistribution.map(m => (
