        )}
      </div>

      <AnimatePresence>
        {isEditing && (
          <div className="fixed inset-0 z-[400] flex items-center justify-center p-6 bg-black/90 backdrop-blur-xl">
            <motion.div initial={{ scale: 0.9, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} className={`${isDarkMode ? 'bg-[#111111]' : 'bg-white'} w-full max-w-2xl rounded-[4rem] p-10 md:p-14 shadow-2xl relative overflow-hidden`}>
