                  <div className="flex items-center gap-4 p-4 bg-black/5 rounded-2xl shadow-inner"><Palette className="text-custom" /><input type="color" value={editForm.profileColor} onChange={e => setEditForm({...editForm, profileColor: e.target.value})} className="h-10 w-24 rounded-lg cursor-pointer border-none bg-transparent" /><span className="font-black text-xs opacity-50">{editForm.profileColor.toUpperCase()}</span></div>
