import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { User, Mood, Section, Post, Comment, Message, Notification } from './types';
import Sidebar from './components/Sidebar';
import MoodCheckIn from './components/MoodCheckIn';
import HomeSection from './sections/HomeSection';
import MoodSection from './sections/MoodSection';
import ZodiacSection from './sections/ZodiacSection';
import CityHallSection from './sections/CityHallSection';
import ProfileSection from './sections/ProfileSection';
import SettingsSection from './sections/SettingsSection';
import NotificationsSection from './sections/NotificationsSection';
import AuthScreen from './sections/AuthScreen';
import LoadingScreen from './components/LoadingScreen';
import { getExpNeeded, MOOD_SCORES } from './constants';
import { Trophy, Share2, X } from 'lucide-react';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [activeSection, setActiveSection] = useState<Section>('Home');
  const [viewingUsername, setViewingUsername] = useState<string | null>(null);
  const [isMoodModalOpen, setIsMoodModalOpen] = useState(false);
  const [isDarkMode, setIsDarkMode] = useState(false); 
  const [isAppStarting, setIsAppStarting] = useState(true);
  const [levelUpInfo, setLevelUpInfo] = useState<{ level: number } | null>(null);
  const [globalUpdateToggle, setGlobalUpdateToggle] = useState(0);

  const [allPosts, setAllPosts] = useState<Post[]>([]);
  const [allMessages, setAllMessages] = useState<Message[]>([]);
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);

  const profileToView = useMemo(() => {
    if (!viewingUsername) return null;
    if (currentUser && viewingUsername === currentUser.username) return currentUser;
    const allUsers: User[] = JSON.parse(localStorage.getItem('mooderia_all_users') || '[]');
    return allUsers.find(u => u.username === viewingUsername) || null;
  }, [viewingUsername, currentUser, globalUpdateToggle]);

  const addNotification = useCallback((recipient: string, type: Notification['type'], snippet: string, postId: string = '') => {
    if (!currentUser || recipient === currentUser.username) return;
    const newNotif: Notification = {
      id: Math.random().toString(36).substr(2, 9),
      fromUser: currentUser.username,
      recipient,
      type,
      postId,
      timestamp: Date.now(),
      read: false,
      postContentSnippet: snippet
    };
    setNotifications(prev => [...prev, newNotif]);
  }, [currentUser]);

  const triggerMoodCheck = (user: User) => {
    const todayStr = new Date().toDateString();
    if (user.lastMoodDate !== todayStr) {
      setIsMoodModalOpen(true);
    }
  };

  useEffect(() => {
    const savedUser = localStorage.getItem('mooderia_user');
    const savedPosts = localStorage.getItem('mooderia_posts') || '[]';
    const savedMessages = localStorage.getItem('mooderia_messages') || '[]';
    const savedNotifications = localStorage.getItem('mooderia_notifications') || '[]';
    const savedTheme = localStorage.getItem('mooderia_theme');

    if (savedUser) {
      const user: User = JSON.parse(savedUser);
      const now = Date.now();
      const elapsedMinutes = Math.floor((now - (user.petLastUpdate || now)) / 60000);
      if (elapsedMinutes > 0) {
        user.petHunger = Math.max(0, user.petHunger - elapsedMinutes * 0.15);
        user.petThirst = Math.max(0, user.petThirst - elapsedMinutes * 0.2);
        if (!user.petSleepUntil || user.petSleepUntil < now) {
          user.petRest = Math.max(0, user.petRest - elapsedMinutes * 0.1);
        }
        user.petLastUpdate = now;
      }
      if (!user.gameCooldowns) user.gameCooldowns = {};
      setCurrentUser(user);
    }

    setAllPosts(JSON.parse(savedPosts));
    setAllMessages(JSON.parse(savedMessages));
    setNotifications(JSON.parse(savedNotifications));
    if (savedTheme === 'dark') setIsDarkMode(true);
    setIsLoaded(true);

    const timer = setTimeout(() => setIsAppStarting(false), 2000);
    return () => clearTimeout(timer);
  }, []);

  useEffect(() => {
    if (!isLoaded) return;
    if (currentUser) {
      localStorage.setItem('mooderia_user', JSON.stringify(currentUser));
      const allUsers: User[] = JSON.parse(localStorage.getItem('mooderia_all_users') || '[]');
      const idx = allUsers.findIndex(u => u.username === currentUser.username);
      if (idx > -1) {
        allUsers[idx] = currentUser;
        localStorage.setItem('mooderia_all_users', JSON.stringify(allUsers));
      }
    }
    localStorage.setItem('mooderia_posts', JSON.stringify(allPosts));
    localStorage.setItem('mooderia_messages', JSON.stringify(allMessages));
    localStorage.setItem('mooderia_notifications', JSON.stringify(notifications));
    localStorage.setItem('mooderia_theme', isDarkMode ? 'dark' : 'light');
  }, [currentUser, allPosts, allMessages, notifications, isDarkMode, isLoaded]);

  const handleFollow = (targetUsername: string) => {
    if (!currentUser) return;
    const isFollowing = currentUser.following.includes(targetUsername);

    // Update Current User
    const updatedFollowing = isFollowing 
      ? currentUser.following.filter(u => u !== targetUsername)
      : [...currentUser.following, targetUsername];
    const updatedCurrentUser = { ...currentUser, following: updatedFollowing };
    setCurrentUser(updatedCurrentUser);

    // Update Target User in Global List
    const allUsers: User[] = JSON.parse(localStorage.getItem('mooderia_all_users') || '[]');
    const targetIdx = allUsers.findIndex(u => u.username === targetUsername);
    if (targetIdx > -1) {
      const targetUser = { ...allUsers[targetIdx] };
      const isFollower = targetUser.followers.includes(currentUser.username);
      targetUser.followers = isFollower 
        ? targetUser.followers.filter(u => u !== currentUser.username)
        : [...targetUser.followers, currentUser.username];

      allUsers[targetIdx] = targetUser;
      localStorage.setItem('mooderia_all_users', JSON.stringify(allUsers));

      if (!isFollowing) {
        addNotification(targetUsername, 'follow', 'started following your frequencies!');
      }
    }
    setGlobalUpdateToggle(t => t + 1);
  };

  const handleHeart = (postId: string) => {
    if (!currentUser) return;
    setAllPosts(prev => prev.map(p => {
      if (p.id === postId) {
        const newHearts = p.hearts + 1;
        if (p.author !== currentUser.username) {
          addNotification(p.author, 'heart', 'liked your transmission', p.id);
          const allUsers: User[] = JSON.parse(localStorage.getItem('mooderia_all_users') || '[]');
          const authorIdx = allUsers.findIndex(u => u.username === p.author);
          if (authorIdx > -1) {
            allUsers[authorIdx].likesReceived += 1;
            localStorage.setItem('mooderia_all_users', JSON.stringify(allUsers));
          }
        }
        return { ...p, hearts: newHearts };
      }
      return p;
    }));
  };

  const handleComment = (postId: string, text: string) => {
    if (!currentUser) return;
    setAllPosts(prev => prev.map(p => {
      if (p.id === postId) {
        const newComment: Comment = {
          id: Math.random().toString(36).substr(2, 9),
          author: currentUser.username,
          text,
          hearts: 0,
          timestamp: Date.now(),
          replies: []
        };
        if (p.author !== currentUser.username) {
          addNotification(p.author, 'comment', 'replied to your transmission', p.id);
        }
        return { ...p, comments: [...p.comments, newComment] };
      }
      return p;
    }));
  };

  const handleCommentInteraction = (postId: string, commentId: string, action: 'heart' | 'reply', replyText?: string) => {
    if (!currentUser) return;
    setAllPosts(prev => prev.map(p => {
      if (p.id === postId) {
        const updateComments = (comments: Comment[]): Comment[] => {
          return comments.map(c => {
            if (c.id === commentId) {
              if (action === 'heart') {
                if (c.author !== currentUser.username) {
                  addNotification(c.author, 'comment_heart', 'liked your frequency', postId);
                }
                return { ...c, hearts: c.hearts + 1 };
              }
              if (action === 'reply' && replyText) {
                if (c.author !== currentUser.username) {
                  addNotification(c.author, 'reply', 'responded to your frequency', postId);
                }
                const newReply: Comment = {
                  id: Math.random().toString(36).substr(2, 9),
                  author: currentUser.username,
                  text: replyText,
                  hearts: 0,
                  timestamp: Date.now(),
                  replies: []
                };
                return { ...c, replies: [...c.replies, newReply] };
              }
            }
            if (c.replies.length > 0) {
              return { ...c, replies: updateComments(c.replies) };
            }
            return c;
          });
        };
        return { ...p, comments: updateComments(p.comments) };
      }
      return p;
    }));
  };

  const handleRepost = (p: Post) => {
    if (!currentUser) return;
    const newRepost: Post = {
      id: Math.random().toString(36).substr(2, 9),
      author: currentUser.username,
      content: p.content,
      hearts: 0,
      comments: [],
      timestamp: Date.now(),
      isRepost: true,
      originalAuthor: p.author,
      visibility: 'global'
    };
    setAllPosts([newRepost, ...allPosts]);
    if (p.author !== currentUser.username) {
      addNotification(p.author, 'repost', 'echoed your transmission', p.id);
    }
  };

  const handleEditProfile = (displayName: string, username: string, profilePic?: string, title?: string, bannerPic?: string, profileColor?: string, bio?: string) => {
    if (!currentUser) return;
    setCurrentUser({
      ...currentUser,
      displayName: displayName.slice(0, 20),
      username,
      profilePic: profilePic || currentUser.profilePic,
      title: title || currentUser.title,
      profileColor: profileColor || currentUser.profileColor,
      bio: bio || currentUser.bio
    });
  };

  const updatePetStats = (hunger: number, thirst: number, rest: number, coins: number, exp: number = 0, sleepUntil: number | null = null, newEmoji?: string, markChosen?: boolean, newName?: string, gameCooldownId?: string) => {
    if (!currentUser) return;
    let oldLevel = currentUser.petLevel;
    let newLevel = currentUser.petLevel;
    let newExp = currentUser.petExp + exp;
    while (newExp >= getExpNeeded(newLevel)) {
      newExp -= getExpNeeded(newLevel);
      newLevel += 1;
    }

    if (newLevel > oldLevel) {
      setLevelUpInfo({ level: newLevel });
      addNotification(currentUser.username, 'achievement', `Pet leveled up to ${newLevel}!`);
    }

    const updatedCooldowns = { ...currentUser.gameCooldowns };
    if (gameCooldownId) {
      updatedCooldowns[gameCooldownId] = Date.now() + 60000; 
    }

    setCurrentUser({
      ...currentUser,
      petName: newName || currentUser.petName,
      petHunger: Math.min(100, Math.max(0, currentUser.petHunger + hunger)),
      petThirst: Math.min(100, Math.max(0, currentUser.petThirst + thirst)),
      petRest: Math.min(100, Math.max(0, currentUser.petRest + rest)),
      petExp: newExp,
      petLevel: newLevel,
      moodCoins: currentUser.moodCoins + coins,
      petSleepUntil: sleepUntil !== undefined ? sleepUntil : currentUser.petSleepUntil,
      petEmoji: newEmoji || currentUser.petEmoji,
      petHasBeenChosen: markChosen !== undefined ? markChosen : currentUser.petHasBeenChosen,
      petLastUpdate: Date.now(),
      gameCooldowns: updatedCooldowns
    });
  };

  const shareLevelUp = () => {
    if (!currentUser || !levelUpInfo) return;
    const content = `CONGRATULATIONS! My Guardian ${currentUser.petName} just leveled up to Level ${levelUpInfo.level}! 🏆✨`;
    setAllPosts([{id: Math.random().toString(36).substr(2, 9), author: currentUser.username, content, hearts: 0, comments: [], timestamp: Date.now(), visibility: 'global'}, ...allPosts]);
    setLevelUpInfo(null);
  };

  const handleLogin = (user: User) => {
    setCurrentUser(user);
  };

  const themeStyle = useMemo(() => {
    const color = currentUser?.profileColor || '#e21b3c';
    return {
      '--theme-color': color,
      '--theme-color-dark': `${color}cc`,
    } as React.CSSProperties;
  }, [currentUser?.profileColor]);

  if (isAppStarting) return <LoadingScreen />;
  if (!currentUser) return <AuthScreen onLogin={handleLogin} />;

  return (
    <div style={themeStyle} className={`h-screen max-h-screen overflow-hidden flex flex-col md:flex-row ${isDarkMode ? 'bg-[#0f0f0f] text-white' : 'bg-[#f7f8fa] text-slate-900'} transition-colors duration-300`}>
      <style>{`
        :root { --theme-color: ${currentUser.profileColor || '#e21b3c'}; }
        .kahoot-button-custom { background-color: var(--theme-color); border-bottom: 4px solid rgba(0,0,0,0.3); }
        .text-custom { color: var(--theme-color); }
        .bg-custom { background-color: var(--theme-color); }
        .border-custom { border-color: var(--theme-color); }
      `}</style>

      <AnimatePresence>
        {isMoodModalOpen && (
          <MoodCheckIn 
            onSubmit={(m) => {
              const today = new Date().toDateString();
              setCurrentUser({
                ...currentUser,
                moodStreak: currentUser.lastMoodDate === today ? currentUser.moodStreak : (currentUser.moodStreak || 0) + 1,
                lastMoodDate: today,
                moodHistory: [...(currentUser.moodHistory || []), { date: today, mood: m, score: MOOD_SCORES[m || 'Normal'] }]
              });
              setIsMoodModalOpen(false);
            }} 
            isDarkMode={isDarkMode} 
          />
        )}
      </AnimatePresence>

      <AnimatePresence>
        {levelUpInfo && (
          <div className="fixed inset-0 z-[500] flex items-center justify-center p-6 bg-black/90 backdrop-blur-xl">
            <motion.div initial={{ scale: 0.8, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} className={`${isDarkMode ? 'bg-slate-800' : 'bg-white'} w-full max-w-md p-10 rounded-[3rem] shadow-2xl text-center border-4 border-yellow-400`}>
              <Trophy size={80} className="mx-auto text-yellow-500 mb-6 animate-bounce" />
              <h2 className="text-4xl font-black uppercase italic tracking-tighter mb-2">Level Up!</h2>
              <p className="text-xl font-bold opacity-70 mb-8">Your Guardian {currentUser.petName} is now Level {levelUpInfo.level}!</p>
              <div className="flex flex-col gap-3">
                <button onClick={shareLevelUp} className="kahoot-button-yellow w-full py-5 rounded-2xl text-white font-black uppercase flex items-center justify-center gap-2 shadow-xl"><Share2 size={20}/> Share Achievement</button>
                <button onClick={() => setLevelUpInfo(null)} className="p-4 text-xs font-black uppercase opacity-40 hover:opacity-100 transition-opacity flex items-center justify-center gap-2"><X size={14}/> Skip Achievement</button>
              </div>
            </motion.div>
          </div>
        )}
      </AnimatePresence>

      <Sidebar activeSection={activeSection} onNavigate={(s) => { setActiveSection(s); if(s === 'Profile') setViewingUsername(currentUser.username); }} isDarkMode={isDarkMode} user={currentUser} unreadMessages={allMessages.filter(m => m.recipient === currentUser.username && !m.read).length} unreadNotifications={notifications.filter(n => n.recipient === currentUser.username && !n.read).length} />
      <main className="flex-1 flex flex-col relative pt-16 pb-20 md:pt-0 md:pb-0 h-full overflow-hidden">
        <div className="flex-1 overflow-y-auto fading-scrollbar p-4 md:p-8">
          <motion.div key={activeSection + (activeSection === 'Profile' ? viewingUsername : '')} initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} className="max-w-5xl mx-auto">
            {activeSection === 'Home' && <HomeSection user={currentUser} posts={allPosts} isDarkMode={isDarkMode} />}
            {activeSection === 'Mood' && <MoodSection 
              user={currentUser} 
              posts={allPosts} 
              onPost={(c, v) => setAllPosts([{id: Math.random().toString(36).substr(2, 9), author: currentUser.username, content: c, hearts: 0, comments: [], timestamp: Date.now(), visibility: v}, ...allPosts])} 
              onHeart={handleHeart} 
              onComment={handleComment} 
              onCommentInteraction={handleCommentInteraction}
              onRepost={handleRepost} 
              onFollow={handleFollow} 
              onBlock={(u) => {if(!currentUser.blockedUsers.includes(u)) setCurrentUser({...currentUser, blockedUsers: [...currentUser.blockedUsers, u]}); setActiveSection('Home');}} 
              isDarkMode={isDarkMode} 
              onNavigateToProfile={(u) => {setViewingUsername(u); setActiveSection('Profile');}} 
              onUpdatePet={updatePetStats} 
            />}
            {activeSection === 'Zodiac' && <ZodiacSection isDarkMode={isDarkMode} />}
            {activeSection === 'CityHall' && <CityHallSection isDarkMode={isDarkMode} currentUser={currentUser} messages={allMessages} onSendMessage={(r, t) => setAllMessages([...allMessages, {id: Math.random().toString(36).substr(2, 9), sender: currentUser.username, recipient: r, text: t, timestamp: Date.now(), read: false}])} onReadMessages={(u) => setAllMessages(allMessages.map(m => (m.recipient === currentUser.username && m.sender === u) ? {...m, read: true} : m))} onNavigateToProfile={(u) => {setViewingUsername(u); setActiveSection('Profile');}} />}
            {activeSection === 'Notifications' && <NotificationsSection notifications={notifications.filter(n => n.recipient === currentUser.username)} isDarkMode={isDarkMode} onMarkRead={() => setNotifications(notifications.map(n => n.recipient === currentUser.username ? {...n, read: true} : n))} />}
            {activeSection === 'Profile' && profileToView && <ProfileSection user={profileToView} allPosts={allPosts} isDarkMode={isDarkMode} onEditProfile={handleEditProfile} onBlock={(u) => {if(!currentUser.blockedUsers.includes(u)) setCurrentUser({...currentUser, blockedUsers: [...currentUser.blockedUsers, u]}); setViewingUsername(currentUser.username); setActiveSection('Home');}} onFollow={handleFollow} currentUser={currentUser} onShareToExpress={(c) => setAllPosts([{id: Math.random().toString(36).substr(2, 9), author: currentUser.username, content: c, hearts: 0, comments: [], timestamp: Date.now(), visibility: 'global'}, ...allPosts])} />}
            {activeSection === 'Settings' && <SettingsSection isDarkMode={isDarkMode} onToggleDarkMode={() => setIsDarkMode(!isDarkMode)} onLogout={() => {localStorage.removeItem('mooderia_user'); setCurrentUser(null);}} user={currentUser} onUnblock={(u) => setCurrentUser({...currentUser, blockedUsers: currentUser.blockedUsers.filter(b => b !== u)})} />}
          </motion.div>
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Heart, MessageCircle, Repeat, Send, Sparkles, Brain, Clock, Globe, Users, Trophy, X, MessageSquare, Reply } from 'lucide-react';
import { User, Post, Comment } from '../types';
import MoodPetSection from './MoodPetSection';
import { getTellerResponse } from '../services/geminiService';

interface MoodSectionProps {
  user: User;
  posts: Post[];
  onPost: (content: string, visibility: 'global' | 'circle') => void;
  onHeart: (postId: string) => void;
  onComment: (postId: string, text: string) => void;
  onCommentInteraction: (postId: string, commentId: string, action: 'heart' | 'reply', replyText?: string) => void;
  onRepost: (post: Post) => void;
  onFollow: (username: string) => void;
  onBlock: (username: string) => void;
  isDarkMode: boolean;
  onNavigateToProfile: (username: string) => void;
  onUpdatePet: (hunger: number, thirst: number, rest: number, coins: number, exp?: number, sleepUntil?: number | null, newEmoji?: string, markChosen?: boolean, newName?: string, gameCooldownId?: string) => void;
}

const CommentItem: React.FC<{ 
  comment: Comment, 
  postId: string, 
  onNavigateToProfile: (u: string) => void,
  onInteraction: (postId: string, commentId: string, action: 'heart' | 'reply', replyText?: string) => void,
  isDarkMode: boolean,
  formatTime: (ts: number) => string
}> = ({ comment, postId, onNavigateToProfile, onInteraction, isDarkMode, formatTime }) => {
  const [showReplyInput, setShowReplyInput] = useState(false);
  const [replyText, setReplyText] = useState('');

  return (
    <div className="flex flex-col gap-2">
      <div className="flex gap-3 group">
        <button onClick={() => onNavigateToProfile(comment.author)} className="w-8 h-8 rounded-lg bg-black/5 flex items-center justify-center font-black text-[10px] shrink-0 border border-black/5 hover:border-custom transition-all">
          {comment.author[0].toUpperCase()}
        </button>
        <div className="flex-1">
          <div className="flex items-center justify-between">
            <p className="text-[10px] font-black uppercase tracking-tight">@{comment.author}</p>
            <p className="text-[8px] opacity-30 font-black">{formatTime(comment.timestamp)}</p>
          </div>
          <p className="text-xs opacity-80 mt-1 leading-relaxed">{comment.text}</p>
          <div className="flex items-center gap-4 mt-2 opacity-40 group-hover:opacity-100 transition-opacity">
            <button onClick={() => onInteraction(postId, comment.id, 'heart')} className="flex items-center gap-1 text-[9px] font-black uppercase hover:text-custom">
              <Heart size={10} fill={comment.hearts > 0 ? "currentColor" : "none"} /> {comment.hearts}
            </button>
            <button onClick={() => setShowReplyInput(!showReplyInput)} className="flex items-center gap-1 text-[9px] font-black uppercase hover:text-blue-500">
              <Reply size={10} /> Reply
            </button>
          </div>
        </div>
      </div>

      <AnimatePresence>
        {showReplyInput && (
          <motion.div initial={{ height: 0, opacity: 0 }} animate={{ height: 'auto', opacity: 1 }} exit={{ height: 0, opacity: 0 }} className="pl-11 pr-2 overflow-hidden">
            <div className="flex gap-2">
              <input 
                value={replyText} 
                onChange={(e) => setReplyText(e.target.value)} 
                placeholder="Write a response..." 
                className={`flex-1 p-2 rounded-lg text-[10px] font-bold outline-none border-2 border-black/5 focus:border-custom ${isDarkMode ? 'bg-slate-700' : 'bg-gray-100'}`} 
              />
              <button 
                onClick={() => { if(replyText.trim()) { onInteraction(postId, comment.id, 'reply', replyText); setReplyText(''); setShowReplyInput(false); }}} 
                className="p-2 bg-custom text-white rounded-lg shadow-md shrink-0"
              >
                <Send size={12} />
              </button>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      {comment.replies.length > 0 && (
        <div className="pl-11 space-y-4 border-l-2 border-black/5 mt-2">
          {comment.replies.map(reply => (
            <CommentItem 
              key={reply.id} 
              comment={reply} 
              postId={postId} 
              onNavigateToProfile={onNavigateToProfile} 
              onInteraction={onInteraction} 
              isDarkMode={isDarkMode} 
              formatTime={formatTime} 
            />
          ))}
        </div>
      )}
    </div>
  );
};

