                  </div>
                  {notif.type !== 'follow' && notif.postContentSnippet && (
                    <div className="p-5 bg-black/5 dark:bg-white/5 rounded-[1.5rem] italic text-sm font-medium opacity-80 border-l-4 border-black/10 truncate">
                      "{notif.postContentSnippet}"
                    </div>
                  )}
                </div>
              </motion.div>
            ))}
          </AnimatePresence>
        )}
      </div>
    </div>
  );
};

