                  <div className="space-y-2"><p className="text-[10px] font-black uppercase opacity-30 ml-2">Display Identity</p><input type="text" value={editForm.displayName} onChange={e => setEditForm({...editForm, displayName: e.target.value})} className="w-full p-4 rounded-2xl border-4 dark:bg-slate-800 font-black outline-none" /></div>
                  <div className="space-y-2"><p className="text-[10px] font-black uppercase opacity-30 ml-2">Role</p><select value={editForm.title} onChange={e => setEditForm({...editForm, title: e.target.value})} className="w-full p-4 rounded-2xl border-4 dark:bg-slate-800 font-black outline-none appearance-none">{JOB_TITLES.map(j => <option key={j} value={j}>{j}</option>)}</select></div>
                </div>
                <div className="space-y-2"><p className="text-[10px] font-black uppercase opacity-30 ml-2">Internal Aura (Color)</p><input type="color" value={editForm.profileColor} onChange={e => setEditForm({...editForm, profileColor: e.target.value})} className="h-10 w-full rounded-lg cursor-pointer" /></div>
                <div className="space-y-2"><p className="text-[10px] font-black uppercase opacity-30 ml-2">Bio</p><textarea value={editForm.bio} onChange={e => setEditForm({...editForm, bio: e.target.value})} className="w-full p-4 rounded-2xl border-4 dark:bg-slate-800 font-bold outline-none" rows={3} /></div>
                <button onClick={handleSave} className="kahoot-button-custom w-full py-6 rounded-3xl text-white font-black uppercase text-xl shadow-xl mt-6">AUTHORIZE SYNC</button>
              </div>
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </div>
  );
};

