                              {m.text}

                              {/* Reactions display */}
                              {m.reactions && m.reactions.length > 0 && (
                                <div className={`absolute -bottom-3 ${isMe ? 'right-2' : 'left-2'} flex gap-1 bg-white dark:bg-slate-800 rounded-full px-2 py-0.5 shadow-md border border-black/5`}>
                                  {m.reactions.map(r => <span key={r} className="text-xs">{r}</span>)}
                                </div>
                              )}

                              {/* Reaction picker trigger */}
                              <button 
                                onClick={() => setReactionPickerMsgId(reactionPickerMsgId === m.id ? null : m.id)}
                                className={`absolute ${isMe ? '-left-8' : '-right-8'} top-1/2 -translate-y-1/2 opacity-0 group-hover:opacity-100 transition-opacity p-1 text-slate-400 hover:text-blue-500`}
                              >
                                <Smile size={18} />
                              </button>

                              {/* Reaction Picker Popover */}
                              <AnimatePresence>
                                {reactionPickerMsgId === m.id && (
                                  <motion.div 
                                    initial={{ scale: 0.8, opacity: 0 }} 
                                    animate={{ scale: 1, opacity: 1 }} 
                                    exit={{ scale: 0.8, opacity: 0 }}
                                    className={`absolute z-10 ${isMe ? 'right-0 -top-12' : 'left-0 -top-12'} bg-white dark:bg-slate-800 border border-black/5 rounded-full p-1 flex gap-1 shadow-2xl`}
                                  >
                                    {REACTION_EMOJIS.map(emoji => (
                                      <button 
                                        key={emoji} 
                                        onClick={() => { onReactToMessage(m.id, emoji); setReactionPickerMsgId(null); }}
                                        className="hover:scale-125 transition-transform p-1"
                                      >
                                        {emoji}
                                      </button>
                                    ))}
                                  </motion.div>
                                )}
                              </AnimatePresence>
                            </div>

                            <div className={`flex items-center gap-2 text-[9px] font-black uppercase opacity-30 ${isMe ? 'justify-end' : 'justify-start'}`}>
                              <Clock size={10} /> {new Date(m.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                              {isMe && (
                                m.read ? <CheckCheck size={12} className="text-blue-400" /> : <Check size={12} />
                              )}
                            </div>
                          </div>
                        </div>
                      );
                    })}
                  </div>
                ))}
                <div ref={chatEndRef} />
              </div>

              <div className="p-4 md:p-6 border-t border-gray-100 dark:border-slate-700 shrink-0">
                <div className={`flex items-center gap-3 p-2 rounded-2xl border-4 ${isDarkMode ? 'bg-slate-700/50 border-slate-700' : 'bg-gray-50 border-gray-200'} focus-within:border-blue-500/50 transition-all`}>
                  <input 
                    type="text" 
                    value={input} 
                    onChange={(e) => setInput(e.target.value)} 
                    onKeyPress={(e) => e.key === 'Enter' && handleSend()} 
                    placeholder="Broadcast frequency..." 
                    className="flex-1 bg-transparent px-4 py-2 font-bold text-sm outline-none"
                  />
                  <button onClick={handleSend} className="bg-blue-600 text-white p-3 rounded-xl shadow-lg hover:scale-105 active:scale-95 transition-all"><Send size={20} /></button>
                </div>
              </div>
            </>
          ) : (
            <div className="flex-1 flex flex-col items-center justify-center p-10 text-center opacity-30">
              <MessageSquare size={80} className="mb-6" />
              <h3 className="text-2xl font-black italic uppercase tracking-tighter">Citizen Terminal</h3>
              <p className="text-xs font-bold uppercase tracking-[0.2em] mt-2">Select a frequency to synchronize transmissions</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default CityHallSection;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Heart, MessageCircle, Repeat, Send, Sparkles, Brain, Clock, Globe, Users, Trophy, X, MessageSquare, Reply } from 'lucide-react';
import { User, Post, Comment } from '../types';
import MoodPetSection from './MoodPetSection';
import { getTellerResponse } from '../services/geminiService';

interface MoodSectionProps {
  user: User;
  posts: Post[];
  onPost: (content: string, visibility: 'global' | 'circle') => void;
  onHeart: (postId: string) => void;
  onComment: (postId: string, text: string) => void;
  onCommentInteraction: (postId: string, commentId: string, action: 'heart' | 'reply', replyText?: string) => void;
  onRepost: (post: Post) => void;
  onFollow: (username: string) => void;
  onBlock: (username: string) => void;
  isDarkMode: boolean;
  onNavigateToProfile: (username: string) => void;
  onUpdatePet: (hunger: number, thirst: number, rest: number, coins: number, exp?: number, sleepUntil?: number | null, newEmoji?: string, markChosen?: boolean, newName?: string, gameCooldownId?: string) => void;
}

const CommentItem: React.FC<{ 
  comment: Comment, 
  postId: string, 
  onNavigateToProfile: (u: string) => void,
  onInteraction: (postId: string, commentId: string, action: 'heart' | 'reply', replyText?: string) => void,
  isDarkMode: boolean,
  formatTime: (ts: number) => string
}> = ({ comment, postId, onNavigateToProfile, onInteraction, isDarkMode, formatTime }) => {
  const [showReplyInput, setShowReplyInput] = useState(false);
  const [replyText, setReplyText] = useState('');

  return (
    <div className="flex flex-col gap-2">
      <div className="flex gap-3 group">
        <button onClick={() => onNavigateToProfile(comment.author)} className="w-8 h-8 rounded-lg bg-black/5 flex items-center justify-center font-black text-[10px] shrink-0 border border-black/5 hover:border-custom transition-all">
          {comment.author[0].toUpperCase()}
        </button>
        <div className="flex-1">
          <div className="flex items-center justify-between">
            <p className="text-[10px] font-black uppercase tracking-tight">@{comment.author}</p>
            <p className="text-[8px] opacity-30 font-black">{formatTime(comment.timestamp)}</p>
          </div>
          <p className="text-xs opacity-80 mt-1 leading-relaxed">{comment.text}</p>
          <div className="flex items-center gap-4 mt-2 opacity-40 group-hover:opacity-100 transition-opacity">
            <button onClick={() => onInteraction(postId, comment.id, 'heart')} className="flex items-center gap-1 text-[9px] font-black uppercase hover:text-custom">
              <Heart size={10} fill={comment.hearts > 0 ? "currentColor" : "none"} /> {comment.hearts}
            </button>
            <button onClick={() => setShowReplyInput(!showReplyInput)} className="flex items-center gap-1 text-[9px] font-black uppercase hover:text-blue-500">
              <Reply size={10} /> Reply
            </button>
          </div>
        </div>
      </div>

      <AnimatePresence>
        {showReplyInput && (
          <motion.div initial={{ height: 0, opacity: 0 }} animate={{ height: 'auto', opacity: 1 }} exit={{ height: 0, opacity: 0 }} className="pl-11 pr-2 overflow-hidden">
            <div className="flex gap-2">
              <input 
                value={replyText} 
                onChange={(e) => setReplyText(e.target.value)} 
                placeholder="Write a response..." 
                className={`flex-1 p-2 rounded-lg text-[10px] font-bold outline-none border-2 border-black/5 focus:border-custom ${isDarkMode ? 'bg-slate-700' : 'bg-gray-100'}`} 
              />
              <button 
                onClick={() => { if(replyText.trim()) { onInteraction(postId, comment.id, 'reply', replyText); setReplyText(''); setShowReplyInput(false); }}} 
                className="p-2 bg-custom text-white rounded-lg shadow-md shrink-0"
              >
                <Send size={12} />
              </button>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      {comment.replies.length > 0 && (
        <div className="pl-11 space-y-4 border-l-2 border-black/5 mt-2">
          {comment.replies.map(reply => (
            <CommentItem 
              key={reply.id} 
              comment={reply} 
              postId={postId} 
              onNavigateToProfile={onNavigateToProfile} 
              onInteraction={onInteraction} 
              isDarkMode={isDarkMode} 
              formatTime={formatTime} 
            />
          ))}
        </div>
      )}
    </div>
  );
};

const MoodSection: React.FC<MoodSectionProps> = ({ user, posts, onPost, onHeart, onComment, onCommentInteraction, onRepost, onFollow, onBlock, isDarkMode, onNavigateToProfile, onUpdatePet }) => {
  const [subTab, setSubTab] = useState<'Express' | 'Teller' | 'Scan' | 'Mood Pet'>('Express');
  const [postContent, setPostContent] = useState('');
  const [feedFilter, setFeedFilter] = useState<'Global' | 'Circle'>('Global');
  const [postVisibility, setPostVisibility] = useState<'global' | 'circle'>('global');

  const [tellerQuestion, setTellerQuestion] = useState('');
  const [tellerResponse, setTellerResponse] = useState('');
  const [isTellerLoading, setIsTellerLoading] = useState(false);

  const [quizActive, setQuizActive] = useState(false);
  const [quizStep, setQuizStep] = useState(0);
  const [quizScores, setQuizScores] = useState<Record<string, number>>({ Happy: 0, Angry: 0, Tired: 0, Normal: 0, Excited: 0 });
  const [quizResult, setQuizResult] = useState<string | null>(null);

  const [expandedPostId, setExpandedPostId] = useState<string | null>(null);
  const [commentText, setCommentText] = useState('');

  // Blocking logic: Filter posts
  const filteredPosts = useMemo(() => {
    const allUsers: User[] = JSON.parse(localStorage.getItem('mooderia_all_users') || '[]');
    const usersWhoBlockedMe = allUsers.filter(u => u.blockedUsers.includes(user.username)).map(u => u.username);

    let result = posts.filter(p => 
      !user.blockedUsers.includes(p.author) && 
      !usersWhoBlockedMe.includes(p.author)
    );

    if (feedFilter === 'Global') {
      return result.filter(p => p.visibility === 'global');
    }
    return result.filter(p => p.visibility === 'circle' && (user.following.includes(p.author) || p.author === user.username));
  }, [posts, feedFilter, user.following, user.username, user.blockedUsers]);

  const handlePost = () => {
    if (!postContent.trim()) return;
    onPost(postContent, postVisibility);
    setPostContent('');
  };

  const handleTeller = async () => {
    if (!tellerQuestion.trim()) return;
    setIsTellerLoading(true);
    try {
      const res = await getTellerResponse(tellerQuestion);
      setTellerResponse(res || 'The cosmic fog remains thick.');
    } catch (e) {
      setTellerResponse('ERROR: Signal lost in orbit.');
    } finally {
      setIsTellerLoading(false);
    }
  };

  const startQuiz = () => {
    setQuizActive(true);
    setQuizStep(0);
    setQuizScores({ Happy: 0, Angry: 0, Tired: 0, Normal: 0, Excited: 0 });
    setQuizResult(null);
  };

  const QUIZ_STEPS = [
    { q: "How do you feel about the city lights?", options: ["Exciting!", "Peaceful", "Too bright", "Annoying"], scores: { Excited: 5, Normal: 5, Tired: 5, Angry: 5 } },
    { q: "Your pet hasn't eaten in 10 hours...", options: ["Panic", "I forgot", "Fixing it now", "Oh well"], scores: { Excited: 5, Tired: 5, Normal: 5, Angry: 5 } },
    { q: "A citizen sends you a random heart.", options: ["Heart back!", "Confused", "Who is this?", "Ignore"], scores: { Happy: 5, Normal: 5, Angry: 5, Tired: 5 } }
  ];

  const handleQuizChoice = (idx: number) => {
    const nextStep = quizStep + 1;
    if (nextStep < QUIZ_STEPS.length) {
      setQuizStep(nextStep);
    } else {
      const winner = Object.entries(quizScores).sort((a,b) => b[1] - a[1])[0][0];
      setQuizResult(winner);
    }
  };

  const formatTime = (ts: number) => {
    const diff = Date.now() - ts;
    if (diff < 60000) return 'Just now';
    if (diff < 3600000) return `${Math.floor(diff / 60000)}m ago`;
    return new Date(ts).toLocaleDateString();
  };

  return (
    <div className="flex flex-col gap-4 md:gap-8 pb-10 h-full overflow-hidden">
      <div className="flex gap-2 overflow-x-auto no-scrollbar pb-2 shrink-0">
        {['Express', 'Teller', 'Scan', 'Mood Pet'].map((t) => (
          <button key={t} onClick={() => setSubTab(t as any)} className={`px-6 md:px-8 py-2.5 md:py-3 rounded-full font-black text-[10px] md:text-xs transition-all whitespace-nowrap uppercase tracking-tighter border-b-4 ${subTab === t ? 'bg-custom border-black/20 text-white shadow-xl' : isDarkMode ? 'bg-[#1a1a1a] border-black text-white/30' : 'bg-white border-gray-100 text-slate-500 shadow-sm'}`}>
            {t}
          </button>
        ))}
      </div>

      <div className="flex-1 overflow-y-auto fading-scrollbar pr-2">
        <AnimatePresence mode="wait">
          {subTab === 'Express' && (
            <motion.div key="express" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="space-y-4 md:space-y-6">
              <div className={`p-4 md:p-8 rounded-[2rem] md:rounded-[3rem] ${isDarkMode ? 'bg-[#111111]' : 'bg-white'} border-4 border-black/5 shadow-2xl relative`}>
                <textarea value={postContent} onChange={(e) => setPostContent(e.target.value)} placeholder={postVisibility === 'global' ? "Global Broadcast..." : "Circle Whisper..."} className={`w-full ${isDarkMode ? 'bg-[#1a1a1a] text-white' : 'bg-gray-50 text-slate-900'} p-4 md:p-6 rounded-2xl md:rounded-[2rem] border-2 md:border-4 border-black/5 focus:border-custom outline-none font-bold text-sm md:text-lg shadow-inner`} rows={window.innerWidth < 768 ? 2 : 3} />
                <div className="flex flex-wrap justify-between items-center mt-3 md:mt-6 gap-3">
                  <div className="flex gap-2">
                    <button onClick={() => setPostVisibility('global')} className={`flex items-center gap-2 px-3 py-1.5 rounded-xl text-[10px] font-black uppercase transition-all ${postVisibility === 'global' ? 'bg-custom text-white shadow-md' : 'opacity-40'}`}><Globe size={14}/> GLOBAL</button>
                    <button onClick={() => setPostVisibility('circle')} className={`flex items-center gap-2 px-3 py-1.5 rounded-xl text-[10px] font-black uppercase transition-all ${postVisibility === 'circle' ? 'bg-custom text-white shadow-md' : 'opacity-40'}`}><Users size={14}/> CIRCLE</button>
                  </div>
                  <button onClick={handlePost} className="kahoot-button-custom px-8 md:px-12 py-3 md:py-4 text-white rounded-xl md:rounded-[1.5rem] font-black text-xs md:text-sm flex items-center gap-2 md:gap-3 shadow-xl"><Send size={18} /> BROADCAST</button>
                </div>
              </div>
              <div className="flex gap-2 bg-black/5 p-1 rounded-2xl w-fit">
                <button onClick={() => setFeedFilter('Global')} className={`px-4 md:px-6 py-2 rounded-xl text-[10px] md:text-xs font-black uppercase transition-all ${feedFilter === 'Global' ? 'bg-white text-custom shadow-md' : 'opacity-40'}`}>Global Feed</button>
                <button onClick={() => setFeedFilter('Circle')} className={`px-4 md:px-6 py-2 rounded-xl text-[10px] md:text-xs font-black uppercase transition-all ${feedFilter === 'Circle' ? 'bg-white text-custom shadow-md' : 'opacity-40'}`}>Circle Feed</button>
              </div>
              <div className="space-y-4 pb-24">
                {filteredPosts.map(post => (
                  <div key={post.id} className={`p-6 md:p-8 rounded-[2rem] md:rounded-[3rem] ${isDarkMode ? 'bg-[#111111] text-white' : 'bg-white text-slate-900'} border-4 border-black/5 shadow-xl transition-all`}>
                    <div className="flex items-center justify-between mb-4">
                      <div className="flex items-center gap-3">
                        <button onClick={() => onNavigateToProfile(post.author)} className="w-10 h-10 md:w-14 rounded-xl bg-custom text-white font-black shrink-0 text-lg shadow-md hover:scale-105 transition-transform">{post.author[0].toUpperCase()}</button>
                        <div>
                          <h4 className="font-black text-xs md:text-base leading-tight flex items-center gap-2">@{post.author} {post.isRepost && <span className="text-[7px] bg-green-500/10 text-green-500 px-2 py-0.5 rounded-full border border-green-500/20 uppercase tracking-widest">Echo</span>}</h4>
                          <p className="text-[8px] md:text-[9px] font-black opacity-30 flex items-center gap-1"><Clock size={10}/> {formatTime(post.timestamp)}</p>
                        </div>
                      </div>
                    </div>
                    {post.isRepost && <p className="text-[8px] font-black uppercase opacity-30 mb-2 italic">Originally transmitted by @{post.originalAuthor}</p>}
                    <p className="text-sm md:text-lg font-medium italic opacity-90 mb-4">"{post.content}"</p>
                    <div className="flex items-center gap-6 pt-4 border-t border-black/5">
                      <button onClick={() => onHeart(post.id)} className="flex items-center gap-2 text-custom font-black text-[10px] hover:scale-110 transition-transform"><Heart size={18} fill={post.hearts > 0 ? "currentColor" : "none"} /> {post.hearts}</button>
                      <button onClick={() => setExpandedPostId(expandedPostId === post.id ? null : post.id)} className="flex items-center gap-2 text-blue-500 font-black text-[10px] hover:scale-110 transition-transform"><MessageSquare size={18} /> {post.comments?.length || 0}</button>
                      <button onClick={() => onRepost(post)} className="flex items-center gap-2 text-green-500 font-black text-[10px] hover:scale-110 transition-transform"><Repeat size={18} /> ECHO</button>
                    </div>
                  </div>
                ))}
              </div>
            </motion.div>
          )}

          {subTab === 'Teller' && (
            <motion.div key="teller" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="space-y-6">
               <div className={`p-8 md:p-10 rounded-[3rem] ${isDarkMode ? 'bg-[#111111]' : 'bg-white'} border-4 border-black/5 shadow-2xl text-center`}>
                 <Sparkles className="mx-auto mb-6 text-custom" size={60} />
                 <h2 className="text-3xl md:text-5xl font-black mb-8 uppercase italic tracking-tighter">Fortune Teller</h2>
                 <input value={tellerQuestion} onChange={e => setTellerQuestion(e.target.value)} placeholder="Ask the city's oracle..." className={`w-full p-6 rounded-3xl border-4 font-black text-center mb-6 outline-none ${isDarkMode ? 'bg-[#1a1a1a] border-slate-700' : 'bg-gray-50 border-gray-100'}`} />
                 <button onClick={handleTeller} disabled={isTellerLoading} className="kahoot-button-custom w-full py-5 rounded-2xl text-white font-black uppercase text-lg shadow-xl">{isTellerLoading ? 'CONSULTING...' : 'SYNC WITH ORACLE'}</button>
                 {tellerResponse && <div className="mt-10 p-8 rounded-[2rem] bg-custom/5 border-l-8 border-custom italic font-bold text-lg leading-relaxed">"{tellerResponse}"</div>}
               </div>
            </motion.div>
          )}

          {subTab === 'Scan' && (
            <motion.div key="scan" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className={`p-8 md:p-10 rounded-[3rem] ${isDarkMode ? 'bg-[#111111]' : 'bg-white'} border-4 border-black/5 shadow-2xl text-center`}>
               <Brain className="mx-auto mb-6 text-blue-500" size={60} />
               <h2 className="text-3xl md:text-5xl font-black mb-4 uppercase italic tracking-tighter">Emotional Scan</h2>
               {!quizActive ? (
                 <>
                   <p className="opacity-40 font-bold uppercase tracking-widest text-xs mb-10">Run diagnostics on your current resonance</p>
                   <button onClick={startQuiz} className="kahoot-button-blue px-16 py-5 rounded-2xl text-white font-black uppercase text-xl shadow-xl">INITIATE SCAN</button>
                 </>
               ) : (
                 <div className="space-y-8">
                   {quizResult ? (
                     <motion.div initial={{ scale: 0.9 }} animate={{ scale: 1 }} className="space-y-6">
                        <div className="text-7xl mb-4">✨</div>
                        <h3 className="text-4xl font-black italic uppercase">Scan Complete</h3>
                        <p className="text-xl font-bold opacity-70">Your resonance is currently: <span className="text-custom underline">{quizResult}</span></p>
                        <button onClick={() => setQuizActive(false)} className="kahoot-button-custom px-10 py-4 rounded-xl text-white font-black uppercase">REBOOT SCANNER</button>
                     </motion.div>
                   ) : (
                     <div className="space-y-6">
                        <p className="text-2xl font-black italic">"{QUIZ_STEPS[quizStep].q}"</p>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                           {QUIZ_STEPS[quizStep].options.map((opt, i) => (
                             <button key={opt} onClick={() => handleQuizChoice(i)} className="kahoot-button-custom py-5 rounded-2xl text-white font-black uppercase tracking-tight">{opt}</button>
                           ))}
                        </div>
                     </div>
                   )}
                 </div>
               )}
            </motion.div>
          )}

          {subTab === 'Mood Pet' && (
            <motion.div key="pet" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}>
               <MoodPetSection user={user} isDarkMode={isDarkMode} onUpdate={onUpdatePet} onPost={onPost} />
            </motion.div>
          )}
        </AnimatePresence>
      </div>
    </div>
  );
};

