                  <div className="space-y-2"><p className="text-[10px] font-black uppercase opacity-30 ml-4">Full Name</p><input type="text" value={editForm.displayName} onChange={e => setEditForm({...editForm, displayName: e.target.value})} className="w-full p-5 rounded-2xl border-4 bg-black/5 font-black outline-none focus:border-custom" /></div>
                  <div className="space-y-2"><p className="text-[10px] font-black uppercase opacity-30 ml-4">Designation</p><select value={editForm.title} onChange={e => setEditForm({...editForm, title: e.target.value})} className="w-full p-5 rounded-2xl border-4 bg-black/5 font-black outline-none focus:border-custom appearance-none">{JOB_TITLES.map(j => <option key={j} value={j}>{j}</option>)}</select></div>
                </div>
                <div className="space-y-2"><p className="text-[10px] font-black uppercase opacity-30 ml-4">Internal Aura (Theme)</p><input type="color" value={editForm.profileColor} onChange={e => setEditForm({...editForm, profileColor: e.target.value})} className="h-16 w-full rounded-2xl cursor-pointer bg-transparent border-4 border-black/5" /></div>
                <div className="space-y-2"><p className="text-[10px] font-black uppercase opacity-30 ml-4">Bio Frequency</p><textarea value={editForm.bio} onChange={e => setEditForm({...editForm, bio: e.target.value})} className="w-full p-6 rounded-2xl border-4 bg-black/5 font-bold outline-none focus:border-custom" rows={3} maxLength={150} /></div>
                <button onClick={handleSave} className="kahoot-button-custom w-full py-6 rounded-[2rem] text-white font-black uppercase text-xl shadow-2xl mt-8 active:scale-95 transition-all">Authorize Profile Sync</button>
              </div>
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </div>
  );
};

