import { STREAK_BADGES } from '../constants';

interface MoodSectionProps {
  user: User;
  posts: Post[];
  onPost: (content: string, visibility: 'global' | 'circle') => void;
  onHeart: (postId: string) => void;
  onComment: (postId: string, text: string) => void;
  onCommentInteraction: (postId: string, commentId: string, action: 'heart' | 'reply', replyText?: string) => void;
  onRepost: (post: Post) => void;
  onFollow: (username: string) => void;
  onBlock: (username: string) => void;
  isDarkMode: boolean;
  onNavigateToProfile: (username: string) => void;
  onUpdatePet: (hunger: number, thirst: number, rest: number, coins: number, exp?: number, sleepUntil?: number | null, newEmoji?: string, markChosen?: boolean, newName?: string, gameCooldownId?: string) => void;
}

const MoodSection: React.FC<MoodSectionProps> = ({ user, posts, onPost, onHeart, onComment, onCommentInteraction, onRepost, onFollow, onBlock, isDarkMode, onNavigateToProfile, onUpdatePet }) => {
  const [subTab, setSubTab] = useState<'Express' | 'Teller' | 'Scan' | 'Mood Pet'>('Express');
  const [postContent, setPostContent] = useState('');
  const [feedFilter, setFeedFilter] = useState<'Global' | 'Circle'>('Global');
  const [postVisibility, setPostVisibility] = useState<'global' | 'circle'>('global');

  const [tellerQuestion, setTellerQuestion] = useState('');
  const [tellerResponse, setTellerResponse] = useState('');
  const [isTellerLoading, setIsTellerLoading] = useState(false);

  const [quizActive, setQuizActive] = useState(false);
  const [quizStep, setQuizStep] = useState(0);
  const [quizScores, setQuizScores] = useState<Record<string, number>>({ Happy: 0, Angry: 0, Tired: 0, Normal: 0, Excited: 0 });
  const [quizResult, setQuizResult] = useState<string | null>(null);

  const [expandedPostId, setExpandedPostId] = useState<string | null>(null);

  // Blocking logic: Mutual invisibility
  const filteredPosts = useMemo(() => {
    const allUsers: User[] = JSON.parse(localStorage.getItem('mooderia_all_users') || '[]');
    const usersWhoBlockedMe = allUsers.filter(u => u.blockedUsers.includes(user.username)).map(u => u.username);

    let result = posts.filter(p => 
      !user.blockedUsers.includes(p.author) && 
      !usersWhoBlockedMe.includes(p.author)
    );

    if (feedFilter === 'Global') {
      return result.filter(p => p.visibility === 'global');
    }
    return result.filter(p => p.visibility === 'circle' && (user.following.includes(p.author) || p.author === user.username));
  }, [posts, feedFilter, user.following, user.username, user.blockedUsers]);

  const earnedBadges = useMemo(() => STREAK_BADGES.filter(b => user.moodStreak >= b.threshold), [user.moodStreak]);

  const handlePost = () => {
    if (!postContent.trim()) return;
    onPost(postContent, postVisibility);
    setPostContent('');
  };

  const handleTeller = async () => {
    if (!tellerQuestion.trim()) return;
    setIsTellerLoading(true);
    try {
      const res = await getTellerResponse(tellerQuestion);
      setTellerResponse(res || 'YES. The frequencies align.');
    } catch (e) {
      setTellerResponse('ERROR: Cosmic interference.');
    } finally {
      setIsTellerLoading(false);
    }
  };

  const startQuiz = () => {
    setQuizActive(true);
    setQuizStep(0);
    setQuizScores({ Happy: 0, Angry: 0, Tired: 0, Normal: 0, Excited: 0 });
    setQuizResult(null);
  };

  const QUIZ_STEPS = [
    { q: "The metropolis goes silent at midnight. How do you respond?", options: ["Finally, peace.", "I broadcast louder.", "I sleep immediately.", "It makes me anxious."], scores: { Normal: 5, Excited: 5, Tired: 5, Angry: 5 } },
    { q: "A stranger sends you a heart. Your reaction?", options: ["Heart back instantly!", "Skepticism.", "Ignore it.", "Warmth."], scores: { Excited: 5, Angry: 5, Tired: 5, Happy: 5 } },
    { q: "Your Guardian pet is glowing green. What now?", options: ["Study its frequency.", "Dance with it!", "Check its stats.", "Panic."], scores: { Normal: 5, Happy: 5, Tired: 5, Angry: 5 } }
  ];

  const handleQuizChoice = (idx: number) => {
    const currentStep = QUIZ_STEPS[quizStep];
    const moodKey = Object.keys(currentStep.scores)[idx];
    const updatedScores = { ...quizScores };

    if (moodKey) {
      updatedScores[moodKey] = (updatedScores[moodKey] || 0) + 5;
      setQuizScores(updatedScores);
    }

    const nextStep = quizStep + 1;
    if (nextStep < QUIZ_STEPS.length) {
      setQuizStep(nextStep);
    } else {
      const sortedEntries = Object.entries(updatedScores).sort((a, b) => (b[1] as number) - (a[1] as number));
      setQuizResult(sortedEntries[0][0]);
    }
  };

  const formatTime = (ts: number) => {
    const diff = Date.now() - ts;
    if (diff < 60000) return 'Just now';
    if (diff < 3600000) return `${Math.floor(diff / 60000)}m ago`;
    return new Date(ts).toLocaleDateString();
  };

  return (
    <div className="flex flex-col gap-6 pb-20 h-full overflow-hidden">
      {/* Achievement & Streak Banner restored */}
      {earnedBadges.length > 0 && subTab === 'Express' && (
        <motion.div initial={{ y: -20, opacity: 0 }} animate={{ y: 0, opacity: 1 }} className={`p-6 rounded-[2.5rem] ${isDarkMode ? 'bg-[#1a1a1a]' : 'bg-white'} border-4 border-green-500/20 shadow-2xl flex items-center gap-6 overflow-x-auto no-scrollbar shrink-0`}>
          <div className="flex items-center gap-3 bg-green-500 text-white px-5 py-3 rounded-2xl shadow-lg border-b-4 border-green-700 shrink-0">
            <Trophy size={20} /> <span className="text-[10px] font-black uppercase">Resonator Level</span>
          </div>
          <div className="flex gap-4 min-w-max">
            {earnedBadges.map(b => (
              <div key={b.id} className="flex flex-col items-center p-3 bg-black/5 rounded-2xl border-2 border-black/5 w-20">
                <span className="text-3xl mb-1">{b.icon}</span>
                <span className="text-[8px] font-black uppercase tracking-tighter text-center">{b.name}</span>
              </div>
            ))}
          </div>
        </motion.div>
      )}

      <div className="flex gap-2 overflow-x-auto no-scrollbar shrink-0">
        {['Express', 'Teller', 'Scan', 'Mood Pet'].map((t) => (
          <button key={t} onClick={() => setSubTab(t as any)} className={`px-8 py-4 rounded-full font-black text-xs transition-all whitespace-nowrap uppercase tracking-tighter border-b-4 ${subTab === t ? 'bg-custom border-black/20 text-white shadow-xl translate-y-[-2px]' : isDarkMode ? 'bg-slate-800 border-slate-900 text-white/30' : 'bg-white border-gray-100 text-slate-500 opacity-60'}`}>
            {t}
          </button>
        ))}
      </div>

      <div className="flex-1 overflow-y-auto fading-scrollbar pr-2">
        <AnimatePresence mode="wait">
          {subTab === 'Express' && (
            <motion.div key="express" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="space-y-6">
              <div className={`p-8 rounded-[3rem] ${isDarkMode ? 'bg-slate-900' : 'bg-white'} border-4 border-black/5 shadow-2xl relative`}>
                <textarea value={postContent} onChange={(e) => setPostContent(e.target.value)} placeholder={postVisibility === 'global' ? "Transmit a global frequency..." : "Whisper to your circle..."} className={`w-full ${isDarkMode ? 'bg-slate-800 text-white' : 'bg-gray-50 text-slate-900'} p-6 rounded-[2rem] border-4 border-black/5 focus:border-custom outline-none font-bold text-lg shadow-inner min-h-[140px]`} />
                <div className="flex flex-wrap justify-between items-center mt-6 gap-4">
                  <div className="flex gap-2 bg-black/5 p-1 rounded-2xl">
                    <button onClick={() => setPostVisibility('global')} className={`flex items-center gap-2 px-5 py-2 rounded-xl text-[10px] font-black uppercase transition-all ${postVisibility === 'global' ? 'bg-custom text-white shadow-md' : 'opacity-40'}`}><Globe size={14}/> GLOBAL</button>
                    <button onClick={() => setPostVisibility('circle')} className={`flex items-center gap-2 px-5 py-2 rounded-xl text-[10px] font-black uppercase transition-all ${postVisibility === 'circle' ? 'bg-custom text-white shadow-md' : 'opacity-40'}`}><Users size={14}/> CIRCLE</button>
                  </div>
                  <button onClick={handlePost} className="kahoot-button-custom px-12 py-5 text-white rounded-[1.5rem] font-black text-sm flex items-center gap-3 shadow-2xl active:scale-95 transition-transform"><Send size={20} /> BROADCAST</button>
                </div>
              </div>

              <div className="flex gap-2 bg-black/5 p-1 rounded-2xl w-fit">
                <button onClick={() => setFeedFilter('Global')} className={`px-6 py-2.5 rounded-xl text-[10px] font-black uppercase transition-all ${feedFilter === 'Global' ? 'bg-white text-custom shadow-md' : 'opacity-40'}`}>Global Stream</button>
                <button onClick={() => setFeedFilter('Circle')} className={`px-6 py-2.5 rounded-xl text-[10px] font-black uppercase transition-all ${feedFilter === 'Circle' ? 'bg-white text-custom shadow-md' : 'opacity-40'}`}>Neural Circle</button>
              </div>

              <div className="space-y-6 pb-24">
                {filteredPosts.length > 0 ? filteredPosts.map(post => (
                  <motion.div key={post.id} initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} className={`p-8 rounded-[3.5rem] ${isDarkMode ? 'bg-slate-900 text-white' : 'bg-white text-slate-900'} border-4 border-black/5 shadow-2xl transition-all`}>
                    <div className="flex items-center justify-between mb-6">
                      <div className="flex items-center gap-4">
                        <button onClick={() => onNavigateToProfile(post.author)} className="w-14 h-14 rounded-2xl bg-custom text-white font-black shrink-0 text-2xl shadow-xl hover:scale-105 transition-transform flex items-center justify-center italic">{post.author[0].toUpperCase()}</button>
                        <div>
                          <h4 className="font-black text-lg leading-tight">@{post.author}</h4>
                          <p className="text-[10px] font-black opacity-30 uppercase tracking-[0.2em] flex items-center gap-2"><Clock size={12}/> {formatTime(post.timestamp)}</p>
                        </div>
                      </div>
                    </div>
                    {post.isRepost && <div className="flex items-center gap-2 text-[10px] font-black text-green-500 uppercase italic tracking-widest mb-4"><Repeat size={14}/> Echoing original transmission by @{post.originalAuthor}</div>}
                    <p className="text-lg md:text-xl font-bold italic opacity-90 mb-6 leading-relaxed">"{post.content}"</p>
                    <div className="flex items-center gap-8 pt-6 border-t border-black/5">
                      <button onClick={() => onHeart(post.id)} className="flex items-center gap-2 text-custom font-black text-xs hover:scale-110 transition-transform"><Heart size={22} fill={post.hearts > 0 ? "currentColor" : "none"} /> {post.hearts} RESONANCE</button>
                      <button onClick={() => setExpandedPostId(expandedPostId === post.id ? null : post.id)} className="flex items-center gap-2 text-blue-500 font-black text-xs hover:scale-110 transition-transform"><MessageSquare size={22} /> {post.comments?.length || 0} ECHOES</button>
                      <button onClick={() => onRepost(post)} className="flex items-center gap-2 text-green-500 font-black text-xs hover:scale-110 transition-transform"><Repeat size={22} /> ECHO</button>
                    </div>
                  </motion.div>
                )) : <div className="py-20 text-center opacity-20 font-black uppercase italic text-xl">The airwaves are silent.</div>}
              </div>
            </motion.div>
          )}

          {subTab === 'Teller' && (
            <motion.div key="teller" initial={{ opacity: 0, scale: 0.95 }} animate={{ opacity: 1, scale: 1 }} className={`p-10 rounded-[4rem] ${isDarkMode ? 'bg-slate-900' : 'bg-white'} border-4 border-black/5 shadow-2xl text-center flex flex-col items-center justify-center min-h-[400px]`}>
               <Sparkles className="mb-8 text-custom animate-pulse" size={80} />
               <h2 className="text-4xl md:text-6xl font-black mb-10 uppercase italic tracking-tighter">Fortune Teller</h2>
               <input value={tellerQuestion} onChange={e => setTellerQuestion(e.target.value)} placeholder="Submit a query to the stars..." className={`w-full max-w-xl p-6 rounded-[2rem] border-4 font-black text-center mb-8 outline-none focus:border-custom shadow-inner ${isDarkMode ? 'bg-slate-800 border-slate-700' : 'bg-gray-50 border-gray-100'}`} />
               <button onClick={handleTeller} disabled={isTellerLoading} className="kahoot-button-custom w-full max-w-sm py-6 rounded-[1.5rem] text-white font-black uppercase text-xl shadow-2xl active:scale-95 transition-transform">{isTellerLoading ? 'CALCULATING...' : 'SYNC WITH ORACLE'}</button>
               {tellerResponse && (
                 <motion.div initial={{ y: 20, opacity: 0 }} animate={{ y: 0, opacity: 1 }} className="mt-12 p-8 rounded-[2.5rem] bg-custom/5 border-l-[12px] border-custom italic font-bold text-2xl leading-relaxed text-center max-w-2xl">
                   "{tellerResponse}"
                 </motion.div>
               )}
            </motion.div>
          )}

          {subTab === 'Scan' && (
            <motion.div key="scan" initial={{ opacity: 0, scale: 0.95 }} animate={{ opacity: 1, scale: 1 }} className={`p-10 rounded-[4rem] ${isDarkMode ? 'bg-slate-900' : 'bg-white'} border-4 border-black/5 shadow-2xl text-center flex flex-col items-center justify-center min-h-[400px]`}>
               <Brain className="mb-8 text-blue-500" size={80} />
               <h2 className="text-4xl md:text-6xl font-black mb-4 uppercase italic tracking-tighter">Emotional Scan</h2>
               {!quizActive ? (
                 <>
                   <p className="opacity-40 font-bold uppercase tracking-[0.2em] text-xs mb-12">Run deep resonance diagnostics</p>
                   <button onClick={startQuiz} className="kahoot-button-blue px-16 py-6 rounded-[1.5rem] text-white font-black uppercase text-2xl shadow-2xl active:scale-95 transition-transform">INITIATE SCAN</button>
                 </>
               ) : (
                 <div className="w-full max-w-2xl space-y-10">
                   {quizResult ? (
                     <motion.div initial={{ scale: 0.9 }} animate={{ scale: 1 }} className="space-y-8">
                        <div className="text-8xl mb-6">✨</div>
                        <h3 className="text-5xl font-black italic uppercase tracking-tighter">Scan Complete</h3>
                        <div className="p-8 rounded-[2.5rem] bg-custom/10 border-4 border-custom/20">
                          <p className="text-xl font-bold opacity-70 uppercase tracking-widest mb-2">Current Resonance</p>
                          <p className="text-4xl font-black text-custom italic uppercase underline">{quizResult}</p>
                        </div>
                        <button onClick={() => setQuizActive(false)} className="kahoot-button-custom px-12 py-5 rounded-[1.5rem] text-white font-black uppercase text-lg">Reboot Scanner</button>
                     </motion.div>
                   ) : (
                     <div className="space-y-8">
                        <div className="h-2 bg-black/10 rounded-full overflow-hidden mb-10"><motion.div className="h-full bg-blue-500" initial={{ width: 0 }} animate={{ width: `${((quizStep + 1) / QUIZ_STEPS.length) * 100}%` }} /></div>
                        <p className="text-3xl font-black italic mb-8 leading-tight">"{QUIZ_STEPS[quizStep].q}"</p>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                           {QUIZ_STEPS[quizStep].options.map((opt, i) => (
                             <button key={opt} onClick={() => handleQuizChoice(i)} className="kahoot-button-custom py-6 rounded-2xl text-white font-black uppercase tracking-tight text-sm shadow-xl active:scale-95 transition-transform">{opt}</button>
                           ))}
                        </div>
                     </div>
                   )}
                 </div>
               )}
            </motion.div>
          )}

          {subTab === 'Mood Pet' && (
            <motion.div key="pet" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}>
               <MoodPetSection user={user} isDarkMode={isDarkMode} onUpdate={onUpdatePet} onPost={onPost} />
            </motion.div>
          )}
        </AnimatePresence>
      </div>
    </div>
  );
};

