import React, { useState, useMemo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Heart, Send, Sparkles, Brain, Clock, Globe, Users, Trophy, MessageSquare, Repeat } from 'lucide-react';
import { User, Post } from '../types';
import MoodPetSection from './MoodPetSection';
import { getTellerResponse } from '../services/geminiService';
import { STREAK_BADGES } from '../constants';

interface MoodSectionProps {
  user: User;
  posts: Post[];
  onPost: (content: string, visibility: 'global' | 'circle') => void;
  onHeart: (postId: string) => void;
  onComment: (postId: string, text: string) => void;
  onCommentInteraction: (postId: string, commentId: string, action: 'heart' | 'reply', replyText?: string) => void;
  onRepost: (post: Post) => void;
  onFollow: (username: string) => void;
  onBlock: (username: string) => void;
  isDarkMode: boolean;
  onNavigateToProfile: (username: string) => void;
  onUpdatePet: (hunger: number, thirst: number, rest: number, coins: number, exp?: number, sleepUntil?: number | null, newEmoji?: string, markChosen?: boolean, newName?: string, gameCooldownId?: string) => void;
}

const MoodSection: React.FC<MoodSectionProps> = ({ user, posts, onPost, onHeart, onComment, onCommentInteraction, onRepost, onFollow, onBlock, isDarkMode, onNavigateToProfile, onUpdatePet }) => {
  const [subTab, setSubTab] = useState<'Express' | 'Teller' | 'Scan' | 'Mood Pet'>('Express');
  const [postContent, setPostContent] = useState('');
  const [feedFilter, setFeedFilter] = useState<'Global' | 'Circle'>('Global');
  const [postVisibility, setPostVisibility] = useState<'global' | 'circle'>('global');

  const [tellerQuestion, setTellerQuestion] = useState('');
  const [tellerResponse, setTellerResponse] = useState('');
  const [isTellerLoading, setIsTellerLoading] = useState(false);

  const [quizActive, setQuizActive] = useState(false);
  const [quizStep, setQuizStep] = useState(0);
  const [quizScores, setQuizScores] = useState<Record<string, number>>({ Happy: 0, Angry: 0, Tired: 0, Normal: 0, Excited: 0 });
  const [quizResult, setQuizResult] = useState<string | null>(null);

  const [expandedPostId, setExpandedPostId] = useState<string | null>(null);

  // Blocking logic: Filter posts to hide blocked users and blockers
  const filteredPosts = useMemo(() => {
    const allUsers: User[] = JSON.parse(localStorage.getItem('mooderia_all_users') || '[]');
    const usersWhoBlockedMe = allUsers.filter(u => u.blockedUsers.includes(user.username)).map(u => u.username);

    let result = posts.filter(p => 
      !user.blockedUsers.includes(p.author) && 
      !usersWhoBlockedMe.includes(p.author)
    );

    if (feedFilter === 'Global') {
      return result.filter(p => p.visibility === 'global');
    }
    return result.filter(p => p.visibility === 'circle' && (user.following.includes(p.author) || p.author === user.username));
  }, [posts, feedFilter, user.following, user.username, user.blockedUsers]);

  const earnedBadges = useMemo(() => STREAK_BADGES.filter(b => user.moodStreak >= b.threshold), [user.moodStreak]);

  const handlePost = () => {
    if (!postContent.trim()) return;
    onPost(postContent, postVisibility);
    setPostContent('');
  };

  const handleTeller = async () => {
    if (!tellerQuestion.trim()) return;
    setIsTellerLoading(true);
    try {
      const res = await getTellerResponse(tellerQuestion);
      setTellerResponse(res || 'THE COSMOS IS SILENT.');
    } catch (e) {
      setTellerResponse('ERROR: NEURAL LINK SEVERED.');
    } finally {
      setIsTellerLoading(false);
    }
  };

  const startQuiz = () => {
    setQuizActive(true);
    setQuizStep(0);
    setQuizScores({ Happy: 0, Angry: 0, Tired: 0, Normal: 0, Excited: 0 });
    setQuizResult(null);
  };

  const QUIZ_STEPS = [
    { q: "A silent broadcast echoes through the city. Do you listen?", options: ["Deep Focus", "Active Search", "Ignore Link", "Report Anomaly"], scores: { Normal: 5, Excited: 5, Tired: 5, Angry: 5 } },
    { q: "A fellow citizen sends a neural heart. Your vibe?", options: ["Return Pulse", "Analyze Intention", "Block Frequency", "Feel Glow"], scores: { Excited: 5, Angry: 5, Tired: 5, Happy: 5 } },
    { q: "Your Guardian pet is glowing a strange violet. Actions?", options: ["Study Pattern", "Join Rhythm", "Check Health", "Alert City"], scores: { Normal: 5, Happy: 5, Tired: 5, Angry: 5 } }
  ];

  const handleQuizChoice = (idx: number) => {
    const currentStep = QUIZ_STEPS[quizStep];
    const moodKey = Object.keys(currentStep.scores)[idx];
    const updatedScores = { ...quizScores };

    if (moodKey) {
      updatedScores[moodKey] = (updatedScores[moodKey] || 0) + 5;
      setQuizScores(updatedScores);
    }

    const nextStep = quizStep + 1;
    if (nextStep < QUIZ_STEPS.length) {
      setQuizStep(nextStep);
    } else {
      const sortedEntries = Object.entries(updatedScores).sort((a, b) => (b[1] as number) - (a[1] as number));
      setQuizResult(sortedEntries[0][0]);
    }
  };

  const formatTime = (ts: number) => {
    const diff = Date.now() - ts;
    if (diff < 60000) return 'Just now';
    if (diff < 3600000) return `${Math.floor(diff / 60000)}m ago`;
    return new Date(ts).toLocaleDateString();
  };

  return (
    <div className="flex flex-col gap-6 pb-20 h-full overflow-hidden">
      {/* Achievement & Streak Banner restored and improved */}
      <AnimatePresence>
        {earnedBadges.length > 0 && subTab === 'Express' && (
          <motion.div initial={{ y: -30, opacity: 0 }} animate={{ y: 0, opacity: 1 }} exit={{ y: -30, opacity: 0 }} className={`p-4 md:p-6 rounded-[2rem] md:rounded-[3rem] ${isDarkMode ? 'bg-slate-900 border-green-500/20' : 'bg-white border-green-500/10'} border-4 shadow-2xl flex items-center gap-4 md:gap-8 overflow-x-auto no-scrollbar shrink-0`}>
            <div className="flex items-center gap-3 bg-green-500 text-white px-5 py-3 rounded-2xl shadow-lg border-b-6 border-green-700 shrink-0">
              <Trophy size={24} /> <span className="text-[10px] md:text-xs font-black uppercase tracking-widest">Resonance Rank</span>
            </div>
            <div className="flex gap-4 min-w-max">
              {earnedBadges.map(b => (
                <div key={b.id} className="flex flex-col items-center justify-center p-3 md:p-4 bg-black/5 rounded-[1.5rem] border-2 border-black/5 w-20 md:w-24">
                  <span className="text-3xl md:text-4xl mb-1">{b.icon}</span>
                  <span className="text-[7px] md:text-[9px] font-black uppercase tracking-tighter text-center leading-none">{b.name}</span>
                </div>
              ))}
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      <div className="flex gap-2 overflow-x-auto no-scrollbar pb-2 shrink-0">
        {['Express', 'Teller', 'Scan', 'Mood Pet'].map((t) => (
          <button key={t} onClick={() => setSubTab(t as any)} className={`px-6 md:px-10 py-3 md:py-4 rounded-full font-black text-[10px] md:text-xs transition-all whitespace-nowrap uppercase tracking-tighter border-b-4 ${subTab === t ? 'bg-custom border-black/20 text-white shadow-xl translate-y-[-2px]' : isDarkMode ? 'bg-slate-800 border-slate-900 text-white/30' : 'bg-white border-gray-100 text-slate-500 opacity-60'}`}>
            {t}
          </button>
        ))}
      </div>

      <div className="flex-1 overflow-y-auto fading-scrollbar pr-2">
        <AnimatePresence mode="wait">
          {subTab === 'Express' && (
            <motion.div key="express" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="space-y-6">
              <div className={`p-6 md:p-10 rounded-[2.5rem] md:rounded-[4rem] ${isDarkMode ? 'bg-slate-900' : 'bg-white'} border-4 border-black/5 shadow-2xl relative`}>
                <textarea value={postContent} onChange={(e) => setPostContent(e.target.value)} placeholder={postVisibility === 'global' ? "Transmit a global frequency..." : "Whisper to your circle..."} className={`w-full ${isDarkMode ? 'bg-slate-800 text-white' : 'bg-gray-50 text-slate-900'} p-6 rounded-[2rem] border-4 border-black/5 focus:border-custom outline-none font-bold text-base md:text-xl shadow-inner min-h-[140px] md:min-h-[180px]`} />
                <div className="flex flex-wrap justify-between items-center mt-6 gap-4">
                  <div className="flex gap-2 bg-black/5 p-1 rounded-2xl">
                    <button onClick={() => setPostVisibility('global')} className={`flex items-center gap-2 px-5 py-2.5 rounded-xl text-[9px] md:text-[11px] font-black uppercase transition-all ${postVisibility === 'global' ? 'bg-custom text-white shadow-md' : 'opacity-40'}`}><Globe size={16}/> GLOBAL</button>
                    <button onClick={() => setPostVisibility('circle')} className={`flex items-center gap-2 px-5 py-2.5 rounded-xl text-[9px] md:text-[11px] font-black uppercase transition-all ${postVisibility === 'circle' ? 'bg-custom text-white shadow-md' : 'opacity-40'}`}><Users size={16}/> CIRCLE</button>
                  </div>
                  <button onClick={handlePost} className="kahoot-button-custom px-10 md:px-16 py-4 md:py-6 text-white rounded-[1.5rem] md:rounded-[2rem] font-black text-xs md:text-sm flex items-center gap-3 shadow-2xl active:scale-95 transition-transform"><Send size={20} /> BROADCAST</button>
                </div>
              </div>

              <div className="flex gap-2 bg-black/5 p-1 rounded-2xl w-fit">
                <button onClick={() => setFeedFilter('Global')} className={`px-6 py-2.5 rounded-xl text-[9px] md:text-[11px] font-black uppercase transition-all ${feedFilter === 'Global' ? 'bg-white text-custom shadow-md' : 'opacity-40'}`}>Metropolis Feed</button>
                <button onClick={() => setFeedFilter('Circle')} className={`px-6 py-2.5 rounded-xl text-[9px] md:text-[11px] font-black uppercase transition-all ${feedFilter === 'Circle' ? 'bg-white text-custom shadow-md' : 'opacity-40'}`}>Neural Circle</button>
              </div>

              <div className="space-y-6 pb-24">
                {filteredPosts.length > 0 ? filteredPosts.map(post => (
                  <motion.div key={post.id} initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} className={`p-6 md:p-10 rounded-[2.5rem] md:rounded-[4rem] ${isDarkMode ? 'bg-slate-900 text-white' : 'bg-white text-slate-900'} border-4 border-black/5 shadow-2xl transition-all`}>
                    <div className="flex items-center justify-between mb-6">
                      <div className="flex items-center gap-4">
                        <button onClick={() => onNavigateToProfile(post.author)} className="w-12 h-12 md:w-16 md:h-16 rounded-[1.5rem] md:rounded-[2rem] bg-custom text-white font-black shrink-0 text-xl md:text-3xl shadow-xl hover:scale-105 transition-transform flex items-center justify-center italic">{post.author[0].toUpperCase()}</button>
                        <div>
                          <h4 className="font-black text-base md:text-xl leading-tight">@{post.author}</h4>
                          <p className="text-[9px] md:text-[11px] font-black opacity-30 uppercase tracking-[0.2em] flex items-center gap-2"><Clock size={12}/> {formatTime(post.timestamp)}</p>
                        </div>
                      </div>
                    </div>
                    {post.isRepost && <div className="flex items-center gap-2 text-[9px] md:text-[11px] font-black text-green-500 uppercase italic tracking-widest mb-4"><Repeat size={14}/> Echoing transmission: @{post.originalAuthor}</div>}
                    <p className="text-base md:text-2xl font-bold italic opacity-90 mb-8 leading-relaxed break-words">"{post.content}"</p>
                    <div className="flex items-center gap-6 md:gap-10 pt-6 border-t border-black/5">
                      <button onClick={() => onHeart(post.id)} className="flex items-center gap-2 text-custom font-black text-[9px] md:text-xs hover:scale-110 transition-transform"><Heart size={20} md:size={24} fill={post.hearts > 0 ? "currentColor" : "none"} /> {post.hearts} SYNC</button>
                      <button onClick={() => setExpandedPostId(expandedPostId === post.id ? null : post.id)} className="flex items-center gap-2 text-blue-500 font-black text-[9px] md:text-xs hover:scale-110 transition-transform"><MessageSquare size={20} md:size={24} /> {post.comments?.length || 0} ECHO</button>
                      <button onClick={() => onRepost(post)} className="flex items-center gap-2 text-green-500 font-black text-[9px] md:text-xs hover:scale-110 transition-transform"><Repeat size={20} md:size={24} /> REPLAY</button>
                    </div>
                  </motion.div>
                )) : <div className="py-24 text-center opacity-20 font-black uppercase italic text-lg md:text-2xl tracking-[0.4em]">The metropolis is quiet.</div>}
              </div>
            </motion.div>
          )}

          {subTab === 'Teller' && (
            <motion.div key="teller" initial={{ opacity: 0, scale: 0.98 }} animate={{ opacity: 1, scale: 1 }} className={`p-8 md:p-16 rounded-[3rem] md:rounded-[5rem] ${isDarkMode ? 'bg-slate-900' : 'bg-white'} border-4 border-black/5 shadow-2xl text-center flex flex-col items-center justify-center min-h-[450px]`}>
               <Sparkles className="mb-8 text-custom animate-pulse" size={60} md:size={100} />
               <h2 className="text-3xl md:text-6xl font-black mb-10 uppercase italic tracking-tighter">Fortune Oracle</h2>
               <input value={tellerQuestion} onChange={e => setTellerQuestion(e.target.value)} placeholder="Sync query with the stars..." className={`w-full max-w-2xl p-6 md:p-8 rounded-[2rem] border-4 font-black text-center mb-8 outline-none focus:border-custom shadow-inner text-base md:text-2xl ${isDarkMode ? 'bg-slate-800 border-slate-700' : 'bg-gray-50 border-gray-100'}`} />
               <button onClick={handleTeller} disabled={isTellerLoading} className="kahoot-button-custom w-full max-w-md py-6 rounded-[2rem] text-white font-black uppercase text-lg md:text-2xl shadow-2xl active:scale-95 transition-transform">{isTellerLoading ? 'CALCULATING...' : 'AUTHORIZE QUERY'}</button>
               {tellerResponse && (
                 <motion.div initial={{ y: 20, opacity: 0 }} animate={{ y: 0, opacity: 1 }} className="mt-12 p-8 md:p-12 rounded-[2.5rem] md:rounded-[4rem] bg-custom/5 border-l-[12px] md:border-l-[16px] border-custom italic font-bold text-xl md:text-3xl leading-relaxed text-center max-w-3xl">
                   "{tellerResponse}"
                 </motion.div>
               )}
            </motion.div>
          )}

          {subTab === 'Scan' && (
            <motion.div key="scan" initial={{ opacity: 0, scale: 0.98 }} animate={{ opacity: 1, scale: 1 }} className={`p-8 md:p-16 rounded-[3rem] md:rounded-[5rem] ${isDarkMode ? 'bg-slate-900' : 'bg-white'} border-4 border-black/5 shadow-2xl text-center flex flex-col items-center justify-center min-h-[450px]`}>
               <Brain className="mb-8 text-blue-500" size={60} md:size={100} />
               <h2 className="text-3xl md:text-6xl font-black mb-6 uppercase italic tracking-tighter">Emotional Scan</h2>
               {!quizActive ? (
                 <>
                   <p className="opacity-40 font-bold uppercase tracking-[0.2em] text-[10px] md:text-xs mb-14">Initiate neural resonance diagnostics</p>
                   <button onClick={startQuiz} className="kahoot-button-blue px-12 md:px-20 py-6 rounded-[2rem] text-white font-black uppercase text-xl md:text-3xl shadow-2xl active:scale-95 transition-transform">Run Diagnostics</button>
                 </>
               ) : (
                 <div className="w-full max-w-3xl space-y-12">
                   {quizResult ? (
                     <motion.div initial={{ scale: 0.9 }} animate={{ scale: 1 }} className="space-y-10">
                        <div className="text-7xl md:text-9xl mb-6">✨</div>
                        <h3 className="text-4xl md:text-6xl font-black italic uppercase tracking-tighter leading-none">Scan Complete</h3>
                        <div className="p-8 md:p-12 rounded-[3rem] md:rounded-[4rem] bg-custom/10 border-4 border-custom/20 shadow-inner">
                          <p className="text-xs md:text-lg font-bold opacity-70 uppercase tracking-widest mb-4">Neural Signature</p>
                          <p className="text-3xl md:text-5xl font-black text-custom italic uppercase underline decoration-double">{quizResult}</p>
                        </div>
                        <button onClick={() => setQuizActive(false)} className="kahoot-button-custom px-12 py-5 rounded-[2rem] text-white font-black uppercase text-xs md:text-lg">Reset Scanner</button>
                     </motion.div>
                   ) : (
                     <div className="space-y-10">
                        <div className="h-3 bg-black/10 rounded-full overflow-hidden mb-12"><motion.div className="h-full bg-blue-500" initial={{ width: 0 }} animate={{ width: `${((quizStep + 1) / QUIZ_STEPS.length) * 100}%` }} /></div>
                        <p className="text-2xl md:text-4xl font-black italic mb-10 leading-tight">"{QUIZ_STEPS[quizStep].q}"</p>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 md:gap-6">
                           {QUIZ_STEPS[quizStep].options.map((opt, i) => (
                             <button key={opt} onClick={() => handleQuizChoice(i)} className="kahoot-button-custom py-5 md:py-8 rounded-2xl md:rounded-[2.5rem] text-white font-black uppercase tracking-tight text-xs md:text-base shadow-xl active:scale-95 transition-transform">{opt}</button>
                           ))}
                        </div>
                     </div>
                   )}
                 </div>
               )}
            </motion.div>
          )}

          {subTab === 'Mood Pet' && (
            <motion.div key="pet" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}>
               <MoodPetSection user={user} isDarkMode={isDarkMode} onUpdate={onUpdatePet} onPost={onPost} />
            </motion.div>
          )}
        </AnimatePresence>
      </div>
    </div>
  );
};

export default MoodSection;

import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { User } from '../types';
import { 
  Coins, Trophy, Heart, Timer, Sparkles, Star, Moon, DollarSign, PenTool
} from 'lucide-react';
import { getExpNeeded } from '../constants';

interface MoodPetSectionProps {
  user: User;
  isDarkMode: boolean;
  onUpdate: (hunger: number, thirst: number, rest: number, coins: number, exp?: number, sleepUntil?: number | null, newEmoji?: string, markChosen?: boolean, newName?: string, gameCooldownId?: string) => void;
  onPost: (content: string) => void;
}

const GAMES = [
  { id: 'clicker', name: 'Neural Tap', emoji: '$', color: 'bg-yellow-400', time: 10, desc: 'Harvest Mood Coins' },
  { id: 'math', name: 'Logic Pulse', emoji: '🔢', color: 'bg-blue-400', time: 15, desc: 'High Velocity Logic' },
  { id: 'wheel', name: 'Sync Wheel', emoji: '🎡', color: 'bg-orange-400', time: 5, desc: 'Probability Hub' },
];

const PET_OPTIONS = ['🐱', '🐶', '🦊', '🦁', '🐨', '🐼', '🦄', '🐲', '🐸', '🐹', '🐰', '🐯', '🐧', '🐻', '🦉'];

const ITEMS = [
  { id: 'f1', type: 'hunger', name: 'Neural Munch', emoji: '🍿', cost: 10, fill: 15 },
  { id: 'f2', type: 'hunger', name: 'Giga Burger', emoji: '🍔', cost: 30, fill: 50 },
  { id: 'd1', type: 'thirst', name: 'Vibe Water', emoji: '💧', cost: 5, fill: 10 },
  { id: 'd2', type: 'thirst', name: 'Energy Pulse', emoji: '⚡', cost: 25, fill: 45 },
];

const SLEEP_MODES = [
  { id: 'short', name: 'Power Nap', duration: 5, rest: 30, cost: 0, emoji: '😴' },
  { id: 'deep', name: 'Neural Stasis', duration: 60, rest: 100, cost: 60, emoji: '🌌' },
];

const MoodPetSection: React.FC<MoodPetSectionProps> = ({ user, isDarkMode, onUpdate, onPost }) => {
  const [activeTab, setActiveTab] = useState<'Care' | 'Shop' | 'Arcade'>('Care');
  const [creationStep, setCreationStep] = useState(1);
  const [tempName, setTempName] = useState('');
  const [selectedEmoji, setSelectedEmoji] = useState('');
  const [now, setNow] = useState(Date.now());

  const [gameMode, setGameMode] = useState<string | null>(null);
  const [gameResult, setGameResult] = useState<{ coins: number, exp: number } | null>(null);
  const [timeLeft, setTimeLeft] = useState(0);
  const [tapScore, setTapScore] = useState(0);
  const [mathProb, setMathProb] = useState({ q: '', a: 0 });
  const [mathInput, setMathInput] = useState('');
  const [wheelSpinning, setWheelSpinning] = useState(false);

  const isSleeping = user.petSleepUntil && user.petSleepUntil > now;
  const isDepleted = user.petHunger <= 5 || user.petThirst <= 5 || user.petRest <= 5;

  useEffect(() => {
    const interval = setInterval(() => setNow(Date.now()), 1000);
    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
    let timer: number;
    if (gameMode && timeLeft > 0 && !gameResult) {
      timer = window.setInterval(() => setTimeLeft(prev => prev - 1), 1000);
    } else if (gameMode && timeLeft === 0 && !gameResult) {
      handleFinishGame();
    }
    return () => clearInterval(timer);
  }, [gameMode, timeLeft, gameResult]);

  const genMath = () => {
    const a = Math.floor(Math.random() * 25) + 5;
    const b = Math.floor(Math.random() * 25) + 5;
    setMathProb({ q: `${a} + ${b}`, a: a + b });
    setMathInput('');
  };

  const startCreation = () => {
    if (creationStep === 1 && tempName.trim()) setCreationStep(2);
    else if (creationStep === 2 && selectedEmoji) setCreationStep(3);
    else if (creationStep === 3) {
      onUpdate(0, 0, 0, 0, 0, null, selectedEmoji, true, tempName);
    }
  };

  const handleStartGame = (id: string) => {
    if (isDepleted) return alert("Guardian needs energy to sync!");
    const cd = user.gameCooldowns?.[id];
    if (cd && cd > now) return;
    setGameMode(id);
    setGameResult(null);
    setTapScore(0);
    setTimeLeft(GAMES.find(g => g.id === id)?.time || 15);
    if (id === 'math') genMath();
  };

  const handleFinishGame = (rewards?: { coins: number, exp: number }) => {
    let coins = rewards?.coins || 20;
    let exp = rewards?.exp || 50;
    if (gameMode === 'clicker') { coins = Math.min(100, tapScore * 4); exp = tapScore * 8; }
    if (gameMode === 'math') { coins = Math.min(150, tapScore * 15); exp = tapScore * 30; }

    setGameResult({ coins, exp });
    // Only games give EXP
    onUpdate(-15, -12, -10, coins, exp, null, undefined, undefined, undefined, gameMode!);
  };

  const handleSpin = () => {
    if (wheelSpinning) return;
    setWheelSpinning(true);
    setTimeout(() => {
      const outcomes = [
        { coins: 250, exp: 100 },
        { coins: 50, exp: 400 },
        { coins: 150, exp: 150 }
      ];
      const win = outcomes[Math.floor(Math.random() * outcomes.length)];
      setWheelSpinning(false);
      handleFinishGame(win);
    }, 2000);
  };

  if (!user.petHasBeenChosen) {
    return (
      <div className="flex flex-col items-center justify-center p-10 md:p-20 text-center min-h-[450px]">
        <AnimatePresence mode="wait">
          {creationStep === 1 && (
            <motion.div key="step1" initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} className="space-y-8 w-full max-w-sm">
              <PenTool size={80} className="mx-auto text-custom" />
              <h2 className="text-3xl md:text-5xl font-black italic uppercase tracking-tighter">Design Guardian</h2>
              <input type="text" value={tempName} onChange={(e) => setTempName(e.target.value)} placeholder="Neural Handle..." className="w-full p-6 rounded-[2rem] border-4 bg-black/5 font-black text-center text-lg md:text-2xl outline-none focus:border-custom" />
              <button onClick={startCreation} disabled={!tempName.trim()} className="kahoot-button-custom w-full py-6 rounded-[1.5rem] text-white font-black uppercase text-xl shadow-2xl">Proceed</button>
            </motion.div>
          )}
          {creationStep === 2 && (
            <motion.div key="step2" initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} className="space-y-10 w-full max-w-lg">
              <h2 className="text-3xl md:text-5xl font-black italic uppercase tracking-tighter">Select Neural Core</h2>
              <div className="grid grid-cols-5 gap-3">
                {PET_OPTIONS.map(e => <button key={e} onClick={() => setSelectedEmoji(e)} className={`text-4xl p-4 rounded-3xl border-4 transition-all ${selectedEmoji === e ? 'border-custom bg-custom/10 scale-110 shadow-xl' : 'border-black/5'}`}>{e}</button>)}
              </div>
              <button onClick={startCreation} disabled={!selectedEmoji} className="kahoot-button-custom w-full py-6 rounded-[1.5rem] text-white font-black uppercase text-xl shadow-2xl">Initialize Core</button>
            </motion.div>
          )}
          {creationStep === 3 && (
            <motion.div key="step3" initial={{ opacity: 0, scale: 0.8 }} animate={{ opacity: 1, scale: 1 }} className="space-y-12 text-center">
              <div className="text-9xl md:text-[180px] animate-bounce drop-shadow-2xl">{selectedEmoji}</div>
              <h2 className="text-5xl md:text-7xl font-black italic uppercase tracking-tighter">{tempName}</h2>
              <button onClick={startCreation} className="kahoot-button-custom w-full py-6 rounded-[2rem] text-white font-black uppercase text-2xl shadow-2xl">Finalize Link</button>
            </motion.div>
          )}
        </AnimatePresence>
      </div>
    );
  }

  if (isSleeping) {
    return (
      <div className="p-16 rounded-[4rem] bg-indigo-950 text-white shadow-2xl flex flex-col items-center justify-center text-center gap-12 min-h-[450px] border-[12px] border-indigo-900">
        <motion.div animate={{ scale: [1, 1.1, 1], rotate: [0, 5, -5, 0] }} transition={{ repeat: Infinity, duration: 4 }}><Moon size={120} className="text-indigo-300 fill-indigo-200" /></motion.div>
        <div className="space-y-4">
          <h2 className="text-4xl md:text-6xl font-black uppercase italic tracking-tighter">In Stasis Mode</h2>
          <p className="opacity-40 font-black uppercase tracking-[0.4em] text-[10px] md:text-xs">Neural Restoration in progress...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-8">
      {/* Experience / Progress Bar */}
      <div className={`p-6 md:p-8 rounded-[2.5rem] md:rounded-[3.5rem] ${isDarkMode ? 'bg-slate-900' : 'bg-white'} border-4 border-black/5 shadow-2xl`}>
         <div className="flex justify-between items-center mb-5">
            <div className="flex items-center gap-3"><Star className="text-yellow-500" size={20} /><span className="text-[10px] md:text-xs font-black uppercase tracking-widest">Guardian Level {user.petLevel}</span></div>
            <span className="text-[8px] md:text-[10px] font-black opacity-40 uppercase tabular-nums">{user.petExp} / {getExpNeeded(user.petLevel)} SYNC XP</span>
         </div>
         <div className="h-6 md:h-8 bg-black/5 rounded-full overflow-hidden p-1.5 shadow-inner border-2 border-black/5">
            <motion.div initial={{ width: 0 }} animate={{ width: `${(user.petExp / getExpNeeded(user.petLevel)) * 100}%` }} className="h-full bg-gradient-to-r from-blue-500 via-indigo-500 to-purple-500 rounded-full shadow-lg" />
         </div>
      </div>

      <div className={`p-10 md:p-14 rounded-[3.5rem] md:rounded-[5rem] ${isDarkMode ? 'bg-slate-900' : 'bg-white'} border-4 border-black/5 shadow-2xl flex flex-col items-center relative overflow-hidden min-h-[480px]`}>
        <div className="absolute top-10 left-10 bg-yellow-400 text-white px-6 md:px-8 py-3 md:py-4 rounded-2xl font-black text-sm md:text-lg shadow-xl border-b-6 border-yellow-700 flex items-center gap-3 active:scale-95 transition-transform cursor-default">
          <Coins size={20}/> {user.moodCoins}
        </div>
        <motion.div animate={{ y: [0, -30, 0], scale: [1, 1.05, 1] }} transition={{ duration: 5, repeat: Infinity, ease: "easeInOut" }} className="text-[180px] md:text-[240px] my-12 drop-shadow-2xl select-none">
          {user.petEmoji}
        </motion.div>
        <div className="w-full max-w-md grid grid-cols-3 gap-6 md:gap-10 mt-6">
          {[
            { label: 'Energy', val: user.petHunger, color: 'bg-red-500' },
            { label: 'Hydration', val: user.petThirst, color: 'bg-blue-500' },
            { label: 'Neural', val: user.petRest, color: 'bg-green-500' },
          ].map(bar => (
            <div key={bar.label} className="text-center space-y-3">
              <span className="text-[8px] md:text-[10px] font-black opacity-40 uppercase tracking-[0.2em]">{bar.label}</span>
              <div className="h-4 md:h-5 bg-black/5 rounded-full overflow-hidden border-2 border-black/5 shadow-inner">
                <motion.div animate={{ width: `${Math.max(0, bar.val)}%` }} className={`h-full ${bar.color} rounded-full`} />
              </div>
            </div>
          ))}
        </div>
      </div>

      <div className="flex gap-2 md:gap-4">
        {(['Care', 'Shop', 'Arcade'] as const).map(tab => (
          <button key={tab} onClick={() => setActiveTab(tab)} className={`flex-1 py-4 md:py-6 rounded-[2rem] md:rounded-[3rem] font-black text-[10px] md:text-xs uppercase border-b-6 md:border-b-8 transition-all shadow-xl ${activeTab === tab ? 'bg-custom border-black/20 text-white translate-y-[-4px]' : 'bg-white text-slate-400 border-gray-100'}`}>{tab}</button>
        ))}
      </div>

      <div className="grid grid-cols-2 md:grid-cols-3 gap-4 md:gap-8 pb-32">
        {activeTab === 'Shop' && ITEMS.map(item => (
          <button key={item.id} onClick={() => { if(user.moodCoins >= item.cost) onUpdate(item.type === 'hunger' ? item.fill : 0, item.type === 'thirst' ? item.fill : 0, 0, -item.cost, 0); }} className="p-8 md:p-12 rounded-[3.5rem] md:rounded-[4.5rem] bg-white text-slate-900 shadow-2xl border-4 border-black/5 flex flex-col items-center gap-3 group hover:scale-105 active:scale-95 transition-all">
            <span className="text-6xl md:text-8xl mb-4 group-hover:scale-110 transition-transform">{item.emoji}</span>
            <span className="font-black uppercase text-[10px] md:text-xs tracking-widest text-center">{item.name}</span>
            <div className="mt-4 bg-yellow-400 text-white px-6 py-2.5 rounded-2xl text-[10px] md:text-xs font-black border-b-6 border-yellow-700 flex items-center gap-2 shadow-lg"><Coins size={16}/> {item.cost}</div>
          </button>
        ))}

        {activeTab === 'Arcade' && !gameMode && GAMES.map(game => {
          const cd = user.gameCooldowns?.[game.id];
          const isCooling = cd && cd > now;
          return (
            <button key={game.id} onClick={() => handleStartGame(game.id)} className={`relative p-8 md:p-12 rounded-[3.5rem] md:rounded-[4.5rem] bg-white text-slate-900 border-4 border-black/5 shadow-2xl flex flex-col items-center gap-3 group hover:scale-105 active:scale-95 transition-all ${isDepleted || isCooling ? 'opacity-40 grayscale pointer-events-none' : ''}`}>
              {isCooling && <div className="absolute inset-0 z-10 bg-black/80 rounded-[3rem] flex flex-col items-center justify-center text-white p-4 text-center"><Timer size={32} className="animate-spin mb-2"/><span className="text-[10px] font-black uppercase">Rebooting Grid</span></div>}
              <span className="text-6xl md:text-8xl mb-4 group-hover:rotate-6 transition-transform">{game.emoji}</span>
              <span className="text-[10px] md:text-xs font-black uppercase text-center leading-tight tracking-[0.2em]">{game.name}</span>
              <div className="mt-3 bg-blue-500/10 text-blue-600 px-4 py-2 rounded-full text-[9px] font-black uppercase tracking-tighter">Awards XP</div>
            </button>
          );
        })}

        {gameMode && (
          <div className={`col-span-full p-12 md:p-20 rounded-[4rem] md:rounded-[6rem] text-white text-center shadow-2xl relative border-[16px] border-white/20 min-h-[480px] flex flex-col ${GAMES.find(g=>g.id===gameMode)?.color}`}>
              {gameResult ? (
                <div className="flex-1 flex flex-col items-center justify-center space-y-12">
                  <motion.div initial={{ scale: 0 }} animate={{ scale: 1 }}><Trophy size={120} className="text-yellow-300 animate-bounce" /></motion.div>
                  <div className="space-y-4">
                    <h4 className="text-4xl md:text-7xl font-black italic uppercase tracking-tighter">Sync Successful</h4>
