  { id: 'hunter', name: 'Signal Catch', emoji: '🎯', color: 'bg-red-400', time: 20, desc: 'Tap Moving Targets' },
  { id: 'memory', name: 'Vibe Match', emoji: '🧠', color: 'bg-pink-400', time: 20, desc: 'Pattern Recognition' },
  { id: 'riddle', name: 'Code Breaker', emoji: '💻', color: 'bg-purple-500', time: 20, desc: 'Unscramble Metropolis Code' },
];

const PET_OPTIONS = ['🐱', '🐶', '🦊', '🦁', '🐨', '🐼', '🦄', '🐲', '🐸', '🐹', '🐰', '🐯', '🐧', '🐻', '🦉'];

const ITEMS = [
  { id: 'f1', type: 'hunger', name: 'Sync Snack', emoji: '🥨', cost: 5, fill: 8 },
  { id: 'f2', type: 'hunger', name: 'Metropop', emoji: '🍿', cost: 10, fill: 15 },
  { id: 'f3', type: 'hunger', name: 'Core Meal', emoji: '🍱', cost: 25, fill: 35 },
  { id: 'd1', type: 'thirst', name: 'Nano Dew', emoji: '💧', cost: 3, fill: 6 },
  { id: 'd2', type: 'thirst', name: 'Vibe Cola', emoji: '🥤', cost: 12, fill: 20 },
  { id: 'd3', type: 'thirst', name: 'Energy Link', emoji: '⚡', cost: 30, fill: 45 },
];

const RIDDLE_WORDS = ['STREAK', 'CITIZEN', 'MOODERIA', 'GUARDIAN', 'COSMIC', 'NEURAL', 'SIGNAL', 'FREQUENCY'];

const MoodPetSection: React.FC<MoodPetSectionProps> = ({ user, isDarkMode, onUpdate, onPost }) => {
  const [activeTab, setActiveTab] = useState<'Care' | 'Shop' | 'Arcade'>('Care');
  const [creationStep, setCreationStep] = useState(1);
  const [tempName, setTempName] = useState('');
  const [selectedEmoji, setSelectedEmoji] = useState('');
  const [now, setNow] = useState(Date.now());

  const [gameMode, setGameMode] = useState<string | null>(null);
  const [gameResult, setGameResult] = useState<{ coins: number, exp: number } | null>(null);
  const [timeLeft, setTimeLeft] = useState(0);
  const [tapScore, setTapScore] = useState(0);
  const [mathProb, setMathProb] = useState({ q: '', a: 0 });
  const [mathInput, setMathInput] = useState('');
  const [wheelSpinning, setWheelSpinning] = useState(false);
  const [hunterTarget, setHunterTarget] = useState({ x: 50, y: 50 });
  const [riddleWord, setRiddleWord] = useState({ scrambled: '', original: '' });

  const [levelUpModal, setLevelUpModal] = useState<number | null>(null);

  const isSleeping = user.petSleepUntil && user.petSleepUntil > now;
  const isDepleted = user.petHunger <= 5 || user.petThirst <= 5 || user.petRest <= 5;

  useEffect(() => {
    const interval = setInterval(() => setNow(Date.now()), 1000);
    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
    let timer: number;
    if (gameMode && timeLeft > 0 && !gameResult) {
      timer = window.setInterval(() => setTimeLeft(prev => prev - 1), 1000);
    } else if (gameMode && timeLeft === 0 && !gameResult) {
      handleFinishGame();
    }
    return () => clearInterval(timer);
  }, [gameMode, timeLeft, gameResult]);

  // Level Up Watcher
  useEffect(() => {
    const needed = getExpNeeded(user.petLevel);
    if (user.petExp >= needed) {
      setLevelUpModal(user.petLevel + 1);
    }
  }, [user.petExp, user.petLevel]);

  const genMath = () => {
    const a = Math.floor(Math.random() * 20) + 1;
    const b = Math.floor(Math.random() * 20) + 1;
    setMathProb({ q: `${a} + ${b}`, a: a + b });
    setMathInput('');
  };

  const genHunter = () => {
    setHunterTarget({ x: 10 + Math.random() * 80, y: 10 + Math.random() * 80 });
  };

  const genRiddle = () => {
    const original = RIDDLE_WORDS[Math.floor(Math.random() * RIDDLE_WORDS.length)];
    const scrambled = original.split('').sort(() => 0.5 - Math.random()).join('');
    setRiddleWord({ scrambled, original });
    setMathInput('');
  };

  const handleStartGame = (id: string) => {
    if (isDepleted) return alert("Guardian needs energy to play!");
    const cd = user.gameCooldowns?.[id];
    if (cd && cd > now) return;
    setGameMode(id);
    setGameResult(null);
    setTapScore(0);
    setTimeLeft(GAMES.find(g => g.id === id)?.time || 15);
    if (id === 'math') genMath();
    if (id === 'hunter') genHunter();
    if (id === 'riddle') genRiddle();
  };

  const handleFinishGame = (rewards?: { coins: number, exp: number }) => {
    let coins = rewards?.coins || 0;
    let exp = rewards?.exp || 0;

    if (gameMode === 'clicker') { coins = Math.min(80, tapScore * 3); exp = tapScore * 6; }
    if (gameMode === 'math') { coins = Math.min(120, tapScore * 10); exp = tapScore * 20; }
    if (gameMode === 'hunter') { coins = Math.min(100, tapScore * 8); exp = tapScore * 15; }
    if (gameMode === 'riddle') { coins = Math.min(150, tapScore * 25); exp = tapScore * 50; }

    setGameResult({ coins, exp });
    onUpdate(-12, -10, -8, coins, exp, null, undefined, undefined, undefined, gameMode!);
  };

  const handleShareLevel = () => {
    if (levelUpModal) {
      onPost(`🚀 METROPOLIS UPDATE: My Guardian ${user.petName} just leveled up to Rank ${levelUpModal}! The cosmic bond is strengthening! ✨ #MooderiaGuardian`);
      setLevelUpModal(null);
    }
  };

  if (!user.petHasBeenChosen) {
    return (
      <div className="flex flex-col items-center justify-center p-8 md:p-20 text-center min-h-[450px]">
        <AnimatePresence mode="wait">
          {creationStep === 1 && (
            <motion.div key="step1" initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} className="space-y-6 md:space-y-10 w-full max-w-sm">
              <PenTool size={60} md:size={100} className="mx-auto text-custom" />
              <h2 className="text-2xl md:text-5xl font-black italic uppercase tracking-tighter leading-none">Design Guardian</h2>
              <input type="text" value={tempName} onChange={(e) => setTempName(e.target.value)} placeholder="Neural Handle..." className="w-full p-4 md:p-6 rounded-2xl md:rounded-[2rem] border-4 bg-black/5 font-black text-center text-sm md:text-2xl outline-none focus:border-custom" />
              <button onClick={() => setCreationStep(2)} disabled={!tempName.trim()} className="kahoot-button-custom w-full py-4 md:py-6 rounded-2xl text-white font-black uppercase text-base md:text-xl shadow-2xl">Proceed</button>
            </motion.div>
          )}
          {creationStep === 2 && (
            <motion.div key="step2" initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} className="space-y-8 w-full max-w-lg">
              <h2 className="text-2xl md:text-5xl font-black italic uppercase tracking-tighter leading-none">Select Core</h2>
              <div className="grid grid-cols-5 gap-2 md:gap-4">
                {PET_OPTIONS.map(e => <button key={e} onClick={() => setSelectedEmoji(e)} className={`text-2xl md:text-4xl p-2 md:p-4 rounded-xl md:rounded-3xl border-4 transition-all ${selectedEmoji === e ? 'border-custom bg-custom/10 scale-110 shadow-xl' : 'border-black/5'}`}>{e}</button>)}
              </div>
              <button onClick={() => setCreationStep(3)} disabled={!selectedEmoji} className="kahoot-button-custom w-full py-4 md:py-6 rounded-2xl text-white font-black uppercase text-base md:text-xl shadow-2xl">Initialize</button>
            </motion.div>
          )}
          {creationStep === 3 && (
            <motion.div key="step3" initial={{ opacity: 0, scale: 0.8 }} animate={{ opacity: 1, scale: 1 }} className="space-y-8 md:space-y-12 text-center">
              <div className="text-7xl md:text-[160px] animate-bounce drop-shadow-2xl">{selectedEmoji}</div>
              <h2 className="text-3xl md:text-7xl font-black italic uppercase tracking-tighter leading-none">{tempName}</h2>
              <button onClick={() => onUpdate(0, 0, 0, 0, 0, null, selectedEmoji, true, tempName)} className="kahoot-button-custom w-full py-4 md:py-6 rounded-2xl text-white font-black uppercase text-base md:text-2xl shadow-2xl">Finalize Link</button>
            </motion.div>
          )}
        </AnimatePresence>
      </div>
    );
  }

  if (isSleeping) {
    return (
      <div className="p-12 md:p-20 rounded-[3rem] md:rounded-[5rem] bg-indigo-950 text-white shadow-2xl flex flex-col items-center justify-center text-center gap-8 md:gap-12 min-h-[450px] border-[12px] border-indigo-900">
        <motion.div animate={{ scale: [1, 1.1, 1], rotate: [0, 5, -5, 0] }} transition={{ repeat: Infinity, duration: 4 }}><Moon size={100} className="text-indigo-300 fill-indigo-200" /></motion.div>
        <div className="space-y-4">
          <h2 className="text-3xl md:text-6xl font-black uppercase italic tracking-tighter">Neural Stasis</h2>
          <p className="opacity-40 font-black uppercase tracking-[0.4em] text-[8px] md:text-xs">Restoration in progress...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6 md:space-y-10">
      {/* Cinematic Level Up Modal */}
      <AnimatePresence>
        {levelUpModal && (
          <div className="fixed inset-0 z-[200] flex items-center justify-center p-6 bg-black/95 backdrop-blur-3xl">
            <motion.div initial={{ scale: 0.8, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} className="w-full max-w-md bg-white rounded-[3rem] md:rounded-[4rem] p-8 md:p-12 text-center shadow-[0_0_100px_rgba(255,166,2,0.4)] border-8 border-yellow-400/20">
              <div className="mb-6 md:mb-10 relative">
                <Trophy size={100} className="mx-auto text-yellow-500 animate-bounce" />
                <Sparkles size={60} className="absolute top-0 right-10 text-blue-500 animate-pulse" />
              </div>
              <h2 className="text-4xl md:text-6xl font-black italic uppercase tracking-tighter text-slate-900 leading-none">LEVEL UP!</h2>
              <p className="text-lg md:text-2xl font-black text-custom uppercase italic tracking-widest mt-2">Rank {levelUpModal}</p>
              <p className="text-[9px] md:text-xs font-bold opacity-40 uppercase tracking-[0.4em] mt-6 md:mt-10 mb-8 md:mb-12">Guardian resonance has expanded</p>
              <div className="flex flex-col gap-3">
                <button onClick={handleShareLevel} className="kahoot-button-custom flex items-center justify-center gap-3 py-5 rounded-2xl text-white font-black uppercase text-sm md:text-xl shadow-2xl active:scale-95 transition-all">
                  <Share2 size={24} /> Broadcast
                </button>
                <button onClick={() => setLevelUpModal(null)} className="py-4 text-xs md:text-sm font-black text-slate-400 uppercase tracking-widest hover:text-slate-900 transition-colors">
                  Skip for now
                </button>
              </div>
            </motion.div>
          </div>
        )}
      </AnimatePresence>

      <div className={`p-6 md:p-10 rounded-[2.5rem] md:rounded-[4rem] ${isDarkMode ? 'bg-slate-900' : 'bg-white'} border-4 border-black/5 shadow-2xl`}>
         <div className="flex justify-between items-center mb-4 md:mb-6">
            <div className="flex items-center gap-2 md:gap-4"><Star className="text-yellow-500" size={24} /><span className="text-[10px] md:text-sm font-black uppercase tracking-widest">Rank {user.petLevel}</span></div>
            <span className="text-[8px] md:text-[10px] font-black opacity-40 uppercase tabular-nums">{user.petExp} / {getExpNeeded(user.petLevel)} SYNC XP</span>
         </div>
         <div className="h-4 md:h-8 bg-black/5 rounded-full overflow-hidden p-1 shadow-inner border-2 border-black/5">
            <motion.div initial={{ width: 0 }} animate={{ width: `${(user.petExp / getExpNeeded(user.petLevel)) * 100}%` }} className="h-full bg-gradient-to-r from-yellow-400 via-orange-500 to-red-500 rounded-full shadow-lg" />
         </div>
      </div>

      <div className={`p-8 md:p-14 rounded-[3rem] md:rounded-[5rem] ${isDarkMode ? 'bg-slate-900' : 'bg-white'} border-4 border-black/5 shadow-2xl flex flex-col items-center relative overflow-hidden min-h-[400px] md:min-h-[520px]`}>
        <div className="absolute top-8 left-8 bg-yellow-400 text-white px-5 md:px-10 py-3 md:py-5 rounded-2xl font-black text-xs md:text-2xl shadow-xl border-b-4 md:border-b-8 border-yellow-700 flex items-center gap-2 md:gap-4 active:scale-90 transition-transform cursor-default">
          <Coins size={28}/> {user.moodCoins}
        </div>
        <motion.div animate={{ y: [0, -20, 0], scale: [1, 1.05, 1] }} transition={{ duration: 4, repeat: Infinity, ease: "easeInOut" }} className="text-[140px] md:text-[240px] my-8 md:my-14 drop-shadow-2xl select-none">
          {user.petEmoji}
        </motion.div>
        <div className="w-full max-w-sm grid grid-cols-3 gap-4 md:gap-10 mt-6">
          {[
            { label: 'Energy', val: user.petHunger, color: 'bg-red-500' },
            { label: 'Vibe', val: user.petThirst, color: 'bg-blue-500' },
            { label: 'Neural', val: user.petRest, color: 'bg-green-500' },
          ].map(bar => (
            <div key={bar.label} className="text-center space-y-2 md:space-y-4">
              <span className="text-[7px] md:text-[10px] font-black opacity-40 uppercase tracking-[0.2em]">{bar.label}</span>
              <div className="h-3 md:h-5 bg-black/5 rounded-full overflow-hidden border-2 border-black/5 shadow-inner">
                <motion.div animate={{ width: `${Math.max(0, bar.val)}%` }} className={`h-full ${bar.color} rounded-full`} />
              </div>
            </div>
          ))}
        </div>
      </div>

      <div className="flex gap-2">
        {(['Care', 'Shop', 'Arcade'] as const).map(tab => (
          <button key={tab} onClick={() => setActiveTab(tab)} className={`flex-1 py-4 md:py-6 rounded-2xl md:rounded-[3rem] font-black text-[9px] md:text-xs uppercase border-b-4 md:border-b-[8px] transition-all shadow-xl ${activeTab === tab ? 'bg-custom border-black/20 text-white translate-y-[-2px]' : 'bg-white text-slate-400 border-gray-100'}`}>{tab}</button>
        ))}
      </div>

      <div className="grid grid-cols-2 md:grid-cols-3 gap-4 md:gap-8 pb-32">
        {activeTab === 'Shop' && ITEMS.map(item => (
          <button key={item.id} onClick={() => { if(user.moodCoins >= item.cost) onUpdate(item.type === 'hunger' ? item.fill : 0, item.type === 'thirst' ? item.fill : 0, 0, -item.cost, 0); }} className="p-6 md:p-12 rounded-[2.5rem] md:rounded-[4.5rem] bg-white text-slate-900 shadow-2xl border-4 border-black/5 flex flex-col items-center gap-2 group hover:scale-105 active:scale-95 transition-all">
            <span className="text-5xl md:text-8xl mb-2 md:mb-4 group-hover:scale-110 transition-transform">{item.emoji}</span>
            <span className="font-black uppercase text-[8px] md:text-xs tracking-widest text-center leading-tight">{item.name}</span>
            <div className="mt-4 bg-yellow-400 text-white px-4 md:px-8 py-2 md:py-3 rounded-xl md:rounded-2xl text-[8px] md:text-base font-black border-b-4 md:border-b-6 border-yellow-700 flex items-center gap-2 shadow-lg"><Coins size={16}/> {item.cost}</div>
          </button>
        ))}

        {activeTab === 'Arcade' && !gameMode && GAMES.map(game => {
          const cd = user.gameCooldowns?.[game.id];
          const isCooling = cd && cd > now;
          return (
            <button key={game.id} onClick={() => handleStartGame(game.id)} className={`relative p-6 md:p-12 rounded-[2.5rem] md:rounded-[4.5rem] bg-white text-slate-900 border-4 border-black/5 shadow-2xl flex flex-col items-center gap-2 group hover:scale-105 active:scale-95 transition-all ${isDepleted || isCooling ? 'opacity-40 grayscale pointer-events-none' : ''}`}>
              {isCooling && <div className="absolute inset-0 z-10 bg-black/80 rounded-[2.5rem] md:rounded-[4rem] flex flex-col items-center justify-center text-white p-4 text-center"><Timer size={32} className="animate-spin mb-2"/><span className="text-[8px] md:text-[10px] font-black uppercase">Neural Cooling</span></div>}
              <span className="text-5xl md:text-8xl mb-2 md:mb-4 group-hover:rotate-6 transition-transform">{game.emoji}</span>
              <span className="text-[8px] md:text-xs font-black uppercase text-center leading-tight tracking-[0.2em]">{game.name}</span>
              <div className="mt-3 bg-blue-500/10 text-blue-600 px-3 md:px-6 py-1 md:py-2 rounded-full text-[7px] md:text-[11px] font-black uppercase tracking-tighter">Gain XP</div>
            </button>
          );
        })}

        {gameMode && (
          <div className={`col-span-full p-10 md:p-20 rounded-[4rem] md:rounded-[6rem] text-white text-center shadow-2xl relative border-[16px] border-white/20 min-h-[420px] md:min-h-[500px] flex flex-col ${GAMES.find(g=>g.id===gameMode)?.color}`}>
              {gameResult ? (
                <div className="flex-1 flex flex-col items-center justify-center space-y-8 md:space-y-12">
                  <motion.div initial={{ scale: 0 }} animate={{ scale: 1 }}><Trophy size={100} md:size={140} className="text-yellow-300 animate-bounce" /></motion.div>
                  <div className="space-y-4">
                    <h4 className="text-3xl md:text-7xl font-black italic uppercase tracking-tighter leading-none">Sync Successful</h4>
                    <div className="flex gap-4 md:gap-8 justify-center">
                      <div className="bg-black/30 px-6 md:px-12 py-4 md:py-8 rounded-2xl md:rounded-[3rem] font-black text-xl md:text-5xl flex items-center gap-3 shadow-inner"><Coins size={40}/> {gameResult.coins}</div>
                      <div className="bg-black/30 px-6 md:px-12 py-4 md:py-8 rounded-2xl md:rounded-[3rem] font-black text-xl md:text-5xl flex items-center gap-3 shadow-inner"><Sparkles size={40}/> {gameResult.exp}</div>
                    </div>
                  </div>
                  <button onClick={() => setGameMode(null)} className="w-full max-w-sm py-5 md:py-8 bg-white text-slate-900 rounded-[2rem] font-black uppercase text-base md:text-2xl shadow-2xl active:scale-95 transition-transform">Close Terminal</button>
                </div>
              ) : (
                <div className="flex-1 flex flex-col items-center justify-center">
                   <div className="absolute top-10 right-10 flex items-center gap-3 bg-black/20 px-8 py-4 rounded-2xl font-black text-2xl md:text-5xl tabular-nums shadow-inner">
                     <Timer size={40} /> {timeLeft}s
                   </div>
                   {gameMode === 'clicker' && <motion.button whileTap={{ scale: 0.8 }} onClick={() => setTapScore(s=>s+1)} className="w-48 h-48 md:w-80 md:h-80 bg-yellow-400 rounded-[3rem] md:rounded-[5rem] shadow-[0_20px_0_0_#ca8a04] md:shadow-[0_40px_0_0_#ca8a04] flex items-center justify-center text-6xl md:text-[140px] font-black border-[12px] md:border-[20px] border-white/30"><DollarSign size={100}/></motion.button>}
                   {gameMode === 'math' && <div className="space-y-10"><p className="text-7xl md:text-[160px] font-black italic tracking-tighter tabular-nums">{mathProb.q}</p><input type="number" autoFocus value={mathInput} onChange={e => { setMathInput(e.target.value); if(parseInt(e.target.value) === mathProb.a) { setTapScore(s=>s+1); genMath(); } }} className="w-full max-w-sm md:max-w-lg p-6 md:p-10 rounded-[2rem] md:rounded-[4rem] bg-white text-slate-900 font-black text-4xl md:text-9xl text-center outline-none shadow-2xl" /></div>}
                   {gameMode === 'wheel' && <div className="space-y-12"><motion.div animate={wheelSpinning ? { rotate: 360 * 6 } : {}} transition={{ duration: 2, ease: "easeOut" }} className="text-[100px] md:text-[220px] mb-8">🎡</motion.div><button onClick={handleSpin} disabled={wheelSpinning} className="bg-white text-orange-500 px-12 md:px-20 py-5 md:py-8 rounded-[2rem] font-black text-2xl md:text-5xl uppercase shadow-2xl active:scale-95">Spin!</button></div>}
                   {gameMode === 'hunter' && <div className="relative w-full h-full min-h-[300px] border-4 border-dashed border-white/20 rounded-[3rem] overflow-hidden">
                      <motion.button animate={{ x: `${hunterTarget.x}%`, y: `${hunterTarget.y}%` }} onClick={() => { setTapScore(s=>s+1); genHunter(); }} className="absolute w-20 h-20 md:w-32 md:h-32 bg-white rounded-full flex items-center justify-center text-red-500 shadow-2xl border-8 border-white/30"><Target size={60} /></motion.button>
                   </div>}
                   {gameMode === 'memory' && <div className="grid grid-cols-2 gap-4"><button onClick={() => { setTapScore(s=>s+1); }} className="p-10 md:p-16 bg-white/20 rounded-[3rem] border-4 border-white/30 hover:bg-white/40 transition-colors"><Brain size={80} /></button></div>}
                   {gameMode === 'riddle' && <div className="space-y-10"><p className="text-4xl md:text-9xl font-black italic tracking-[0.2em] tabular-nums uppercase">{riddleWord.scrambled}</p><input type="text" autoFocus value={mathInput} onChange={e => { setMathInput(e.target.value.toUpperCase()); if(e.target.value.toUpperCase() === riddleWord.original) { setTapScore(s=>s+1); genRiddle(); } }} className="w-full max-w-sm md:max-w-lg p-6 md:p-10 rounded-[2rem] md:rounded-[4rem] bg-white text-slate-900 font-black text-3xl md:text-7xl text-center outline-none shadow-2xl uppercase" /></div>}
                   <p className="mt-12 md:mt-16 opacity-50 font-black uppercase tracking-[0.4em] text-[7px] md:text-sm">Processing Metropolis Data...</p>
                </div>
              )}
          </div>
        )}

        {activeTab === 'Care' && (
          <div className="col-span-full space-y-6 md:space-y-10">
            <div className="grid grid-cols-2 gap-4 md:gap-8">
              {SLEEP_MODES.map(mode => (
                <button key={mode.id} onClick={() => onUpdate(0,0,mode.rest, -mode.cost, 0, Date.now() + mode.duration * 60000)} className="p-8 md:p-14 rounded-[3rem] md:rounded-[5rem] bg-white text-slate-900 shadow-2xl border-4 border-black/5 flex flex-col items-center gap-2 md:gap-6 transition-transform hover:scale-105 active:scale-95">
                  <span className="text-4xl md:text-8xl">{mode.emoji}</span>
                  <p className="font-black uppercase text-xs md:text-2xl tracking-tighter text-center">{mode.name}</p>
                  <p className="text-[7px] md:text-[11px] font-black text-blue-500 opacity-60 uppercase tracking-widest">+{mode.rest}% Core</p>
                  <div className="bg-yellow-400 text-white px-5 md:px-10 py-2 md:py-4 rounded-xl md:rounded-[2rem] text-[8px] md:text-sm font-black border-b-4 md:border-b-8 border-yellow-700 flex items-center gap-2 shadow-xl mt-2 md:mt-4"><Coins size={20}/> {mode.cost}</div>
                </button>
              ))}
            </div>
            <button onClick={() => onUpdate(0,0,0,0,0)} className="w-full p-10 md:p-20 rounded-[4rem] md:rounded-[7rem] bg-custom text-white shadow-2xl flex flex-col items-center justify-center gap-6 md:gap-10 border-b-[12px] md:border-b-[24px] border-black/20 active:translate-y-8 active:border-b-0 transition-all">
              <Heart size={60} md:size={120} className="animate-pulse" />
              <div className="text-center"><h4 className="text-2xl md:text-7xl font-black italic uppercase tracking-tighter leading-none">Sync Bond</h4><p className="text-[8px] md:text-xs font-black opacity-60 uppercase tracking-[0.4em] mt-3">Neural Connection Solidified</p></div>
            </button>
          </div>
        )}
      </div>
    </div>
  );
};

export default MoodPetSection;

import React, { useState, useEffect, useMemo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { User } from '../types';
import { 
  Coins, Trophy, Heart, Timer, Sparkles, Star, Moon, DollarSign, PenTool, 
  Gamepad2, Calculator, Share2, Target, Brain, Dices, Keyboard, X
} from 'lucide-react';
import { getExpNeeded } from '../constants';

interface MoodPetSectionProps {
  user: User;
  isDarkMode: boolean;
  onUpdate: (hunger: number, thirst: number, rest: number, coins: number, exp?: number, sleepUntil?: number | null, newEmoji?: string, markChosen?: boolean, newName?: string, gameCooldownId?: string) => void;
  onPost: (content: string) => void;
}

const GAMES = [
  { id: 'clicker', name: 'Neural Tap', emoji: '👆', color: 'bg-yellow-400', time: 10, desc: 'High Frequency Tapping' },
  { id: 'math', name: 'Logic Pulse', emoji: '🔢', color: 'bg-blue-400', time: 15, desc: 'Solve or Reboot' },
  { id: 'wheel', name: 'Sync Wheel', emoji: '🎡', color: 'bg-orange-400', time: 5, desc: 'Spin for Vibe Rewards' },
  { id: 'hunter', name: 'Signal Catch', emoji: '🎯', color: 'bg-red-400', time: 20, desc: 'Tap Moving Targets' },
  { id: 'memory', name: 'Vibe Match', emoji: '🧠', color: 'bg-pink-400', time: 20, desc: 'Pattern Recognition' },
  { id: 'riddle', name: 'Code Breaker', emoji: '💻', color: 'bg-purple-500', time: 20, desc: 'Unscramble Metropolis Code' },
];

const PET_OPTIONS = ['🐱', '🐶', '🦊', '🦁', '🐨', '🐼', '🦄', '🐲', '🐸', '🐹', '🐰', '🐯', '🐧', '🐻', '🦉'];

const ITEMS = [
  { id: 'f1', type: 'hunger', name: 'Sync Snack', emoji: '🥨', cost: 5, fill: 8 },
  { id: 'f2', type: 'hunger', name: 'Metropop', emoji: '🍿', cost: 10, fill: 15 },
  { id: 'f3', type: 'hunger', name: 'Core Meal', emoji: '🍱', cost: 25, fill: 35 },
  { id: 'd1', type: 'thirst', name: 'Nano Dew', emoji: '💧', cost: 3, fill: 6 },
  { id: 'd2', type: 'thirst', name: 'Vibe Cola', emoji: '🥤', cost: 12, fill: 20 },
  { id: 'd3', type: 'thirst', name: 'Energy Link', emoji: '⚡', cost: 30, fill: 45 },
];

// Define missing SLEEP_MODES constant
const SLEEP_MODES = [
  { id: 'nap', name: 'Quick Nap', emoji: '😴', rest: 15, cost: 0, duration: 30 },
  { id: 'recharge', name: 'Neural Charge', emoji: '⚡', rest: 40, cost: 50, duration: 120 },
  { id: 'deep', name: 'Deep Sleep', emoji: '💤', rest: 100, cost: 100, duration: 480 },
];

const RIDDLE_WORDS = ['STREAK', 'CITIZEN', 'MOODERIA', 'GUARDIAN', 'COSMIC', 'NEURAL', 'SIGNAL', 'FREQUENCY'];

const MoodPetSection: React.FC<MoodPetSectionProps> = ({ user, isDarkMode, onUpdate, onPost }) => {
  const [activeTab, setActiveTab] = useState<'Care' | 'Shop' | 'Arcade'>('Care');
  const [creationStep, setCreationStep] = useState(1);
  const [tempName, setTempName] = useState('');
  const [selectedEmoji, setSelectedEmoji] = useState('');
  const [now, setNow] = useState(Date.now());

  const [gameMode, setGameMode] = useState<string | null>(null);
  const [gameResult, setGameResult] = useState<{ coins: number, exp: number } | null>(null);
  const [timeLeft, setTimeLeft] = useState(0);
  const [tapScore, setTapScore] = useState(0);
  const [mathProb, setMathProb] = useState({ q: '', a: 0 });
  const [mathInput, setMathInput] = useState('');
  const [wheelSpinning, setWheelSpinning] = useState(false);
  const [hunterTarget, setHunterTarget] = useState({ x: 50, y: 50 });
  const [riddleWord, setRiddleWord] = useState({ scrambled: '', original: '' });

  const [levelUpModal, setLevelUpModal] = useState<number | null>(null);

  const isSleeping = user.petSleepUntil && user.petSleepUntil > now;
  const isDepleted = user.petHunger <= 5 || user.petThirst <= 5 || user.petRest <= 5;

  useEffect(() => {
    const interval = setInterval(() => setNow(Date.now()), 1000);
    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
    let timer: number;
    if (gameMode && timeLeft > 0 && !gameResult) {
      timer = window.setInterval(() => setTimeLeft(prev => prev - 1), 1000);
    } else if (gameMode && timeLeft === 0 && !gameResult) {
      handleFinishGame();
    }
    return () => clearInterval(timer);
  }, [gameMode, timeLeft, gameResult]);

  // Level Up Watcher
  useEffect(() => {
    const needed = getExpNeeded(user.petLevel);
    if (user.petExp >= needed) {
      setLevelUpModal(user.petLevel + 1);
    }
  }, [user.petExp, user.petLevel]);

  const genMath = () => {
    const a = Math.floor(Math.random() * 20) + 1;
    const b = Math.floor(Math.random() * 20) + 1;
    setMathProb({ q: `${a} + ${b}`, a: a + b });
    setMathInput('');
  };

  const genHunter = () => {
    setHunterTarget({ x: 10 + Math.random() * 80, y: 10 + Math.random() * 80 });
  };

  const genRiddle = () => {
    const original = RIDDLE_WORDS[Math.floor(Math.random() * RIDDLE_WORDS.length)];
    const scrambled = original.split('').sort(() => 0.5 - Math.random()).join('');
    setRiddleWord({ scrambled, original });
    setMathInput('');
  };

  const handleStartGame = (id: string) => {
    if (isDepleted) return alert("Guardian needs energy to play!");
    const cd = user.gameCooldowns?.[id];
    if (cd && cd > now) return;
    setGameMode(id);
    setGameResult(null);
    setTapScore(0);
    setTimeLeft(GAMES.find(g => g.id === id)?.time || 15);
    if (id === 'math') genMath();
    if (id === 'hunter') genHunter();
    if (id === 'riddle') genRiddle();
  };

  const handleFinishGame = (rewards?: { coins: number, exp: number }) => {
    let coins = rewards?.coins || 0;
    let exp = rewards?.exp || 0;

    if (gameMode === 'clicker') { coins = Math.min(80, tapScore * 3); exp = tapScore * 6; }
    if (gameMode === 'math') { coins = Math.min(120, tapScore * 10); exp = tapScore * 20; }
    if (gameMode === 'hunter') { coins = Math.min(100, tapScore * 8); exp = tapScore * 15; }
    if (gameMode === 'riddle') { coins = Math.min(150, tapScore * 25); exp = tapScore * 50; }

    setGameResult({ coins, exp });
    onUpdate(-12, -10, -8, coins, exp, null, undefined, undefined, undefined, gameMode!);
  };

  // Define missing handleSpin function
  const handleSpin = () => {
    if (wheelSpinning) return;
    setWheelSpinning(true);
    setTimeout(() => {
      setWheelSpinning(false);
      const isBigWin = Math.random() > 0.8;
      const coins = isBigWin ? 200 : 50;
      const exp = isBigWin ? 300 : 100;
      handleFinishGame({ coins, exp });
    }, 2000);
  };

  const handleShareLevel = () => {
    if (levelUpModal) {
      onPost(`🚀 METROPOLIS UPDATE: My Guardian ${user.petName} just leveled up to Rank ${levelUpModal}! The cosmic bond is strengthening! ✨ #MooderiaGuardian`);
      setLevelUpModal(null);
    }
  };

  if (!user.petHasBeenChosen) {
    return (
      <div className="flex flex-col items-center justify-center p-8 md:p-20 text-center min-h-[450px]">
        <AnimatePresence mode="wait">
          {creationStep === 1 && (
            <motion.div key="step1" initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} className="space-y-6 md:space-y-10 w-full max-w-sm">
              <PenTool size={60} md:size={100} className="mx-auto text-custom" />
              <h2 className="text-2xl md:text-5xl font-black italic uppercase tracking-tighter leading-none">Design Guardian</h2>
              <input type="text" value={tempName} onChange={(e) => setTempName(e.target.value)} placeholder="Neural Handle..." className="w-full p-4 md:p-6 rounded-2xl md:rounded-[2rem] border-4 bg-black/5 font-black text-center text-sm md:text-2xl outline-none focus:border-custom" />
              <button onClick={() => setCreationStep(2)} disabled={!tempName.trim()} className="kahoot-button-custom w-full py-4 md:py-6 rounded-2xl text-white font-black uppercase text-base md:text-xl shadow-2xl">Proceed</button>
            </motion.div>
          )}
          {creationStep === 2 && (
            <motion.div key="step2" initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} className="space-y-8 w-full max-w-lg">
              <h2 className="text-2xl md:text-5xl font-black italic uppercase tracking-tighter leading-none">Select Core</h2>
              <div className="grid grid-cols-5 gap-2 md:gap-4">
                {PET_OPTIONS.map(e => <button key={e} onClick={() => setSelectedEmoji(e)} className={`text-2xl md:text-4xl p-2 md:p-4 rounded-xl md:rounded-3xl border-4 transition-all ${selectedEmoji === e ? 'border-custom bg-custom/10 scale-110 shadow-xl' : 'border-black/5'}`}>{e}</button>)}
              </div>
              <button onClick={() => setCreationStep(3)} disabled={!selectedEmoji} className="kahoot-button-custom w-full py-4 md:py-6 rounded-2xl text-white font-black uppercase text-base md:text-xl shadow-2xl">Initialize</button>
            </motion.div>
          )}
          {creationStep === 3 && (
            <motion.div key="step3" initial={{ opacity: 0, scale: 0.8 }} animate={{ opacity: 1, scale: 1 }} className="space-y-8 md:space-y-12 text-center">
              <div className="text-7xl md:text-[160px] animate-bounce drop-shadow-2xl">{selectedEmoji}</div>
              <h2 className="text-3xl md:text-7xl font-black italic uppercase tracking-tighter leading-none">{tempName}</h2>
              <button onClick={() => onUpdate(0, 0, 0, 0, 0, null, selectedEmoji, true, tempName)} className="kahoot-button-custom w-full py-4 md:py-6 rounded-2xl text-white font-black uppercase text-base md:text-2xl shadow-2xl">Finalize Link</button>
            </motion.div>
          )}
        </AnimatePresence>
      </div>
    );
  }

  if (isSleeping) {
    return (
      <div className="p-12 md:p-20 rounded-[3rem] md:rounded-[5rem] bg-indigo-950 text-white shadow-2xl flex flex-col items-center justify-center text-center gap-8 md:gap-12 min-h-[450px] border-[12px] border-indigo-900">
        <motion.div animate={{ scale: [1, 1.1, 1], rotate: [0, 5, -5, 0] }} transition={{ repeat: Infinity, duration: 4 }}><Moon size={100} className="text-indigo-300 fill-indigo-200" /></motion.div>
        <div className="space-y-4">
          <h2 className="text-3xl md:text-6xl font-black uppercase italic tracking-tighter">Neural Stasis</h2>
          <p className="opacity-40 font-black uppercase tracking-[0.4em] text-[8px] md:text-xs">Restoration in progress...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6 md:space-y-10">
      {/* Cinematic Level Up Modal */}
      <AnimatePresence>
        {levelUpModal && (
          <div className="fixed inset-0 z-[200] flex items-center justify-center p-6 bg-black/95 backdrop-blur-3xl">
            <motion.div initial={{ scale: 0.8, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} className="w-full max-w-md bg-white rounded-[3rem] md:rounded-[4rem] p-8 md:p-12 text-center shadow-[0_0_100px_rgba(255,166,2,0.4)] border-8 border-yellow-400/20">
              <div className="mb-6 md:mb-10 relative">
                <Trophy size={100} className="mx-auto text-yellow-500 animate-bounce" />
                <Sparkles size={60} className="absolute top-0 right-10 text-blue-500 animate-pulse" />
              </div>
              <h2 className="text-4xl md:text-6xl font-black italic uppercase tracking-tighter text-slate-900 leading-none">LEVEL UP!</h2>
              <p className="text-lg md:text-2xl font-black text-custom uppercase italic tracking-widest mt-2">Rank {levelUpModal}</p>
              <p className="text-[9px] md:text-xs font-bold opacity-40 uppercase tracking-[0.4em] mt-6 md:mt-10 mb-8 md:mb-12">Guardian resonance has expanded</p>
              <div className="flex flex-col gap-3">
                <button onClick={handleShareLevel} className="kahoot-button-custom flex items-center justify-center gap-3 py-5 rounded-2xl text-white font-black uppercase text-sm md:text-xl shadow-2xl active:scale-95 transition-all">
                  <Share2 size={24} /> Broadcast
                </button>
                <button onClick={() => setLevelUpModal(null)} className="py-4 text-xs md:text-sm font-black text-slate-400 uppercase tracking-widest hover:text-slate-900 transition-colors">
                  Skip for now
                </button>
              </div>
            </motion.div>
          </div>
        )}
      </AnimatePresence>

      <div className={`p-6 md:p-10 rounded-[2.5rem] md:rounded-[4rem] ${isDarkMode ? 'bg-slate-900' : 'bg-white'} border-4 border-black/5 shadow-2xl`}>
         <div className="flex justify-between items-center mb-4 md:mb-6">
            <div className="flex items-center gap-2 md:gap-4"><Star className="text-yellow-500" size={24} /><span className="text-[10px] md:text-sm font-black uppercase tracking-widest">Rank {user.petLevel}</span></div>
            <span className="text-[8px] md:text-[10px] font-black opacity-40 uppercase tabular-nums">{user.petExp} / {getExpNeeded(user.petLevel)} SYNC XP</span>
         </div>
         <div className="h-4 md:h-8 bg-black/5 rounded-full overflow-hidden p-1 shadow-inner border-2 border-black/5">
            <motion.div initial={{ width: 0 }} animate={{ width: `${(user.petExp / getExpNeeded(user.petLevel)) * 100}%` }} className="h-full bg-gradient-to-r from-yellow-400 via-orange-500 to-red-500 rounded-full shadow-lg" />
         </div>
      </div>

      <div className={`p-8 md:p-14 rounded-[3rem] md:rounded-[5rem] ${isDarkMode ? 'bg-slate-900' : 'bg-white'} border-4 border-black/5 shadow-2xl flex flex-col items-center relative overflow-hidden min-h-[400px] md:min-h-[520px]`}>
        <div className="absolute top-8 left-8 bg-yellow-400 text-white px-5 md:px-10 py-3 md:py-5 rounded-2xl font-black text-xs md:text-2xl shadow-xl border-b-4 md:border-b-8 border-yellow-700 flex items-center gap-2 md:gap-4 active:scale-90 transition-transform cursor-default">
          <Coins size={28}/> {user.moodCoins}
        </div>
        <motion.div animate={{ y: [0, -20, 0], scale: [1, 1.05, 1] }} transition={{ duration: 4, repeat: Infinity, ease: "easeInOut" }} className="text-[140px] md:text-[240px] my-8 md:my-14 drop-shadow-2xl select-none">
          {user.petEmoji}
        </motion.div>
        <div className="w-full max-w-sm grid grid-cols-3 gap-4 md:gap-10 mt-6">
          {[
            { label: 'Energy', val: user.petHunger, color: 'bg-red-500' },
            { label: 'Vibe', val: user.petThirst, color: 'bg-blue-500' },
            { label: 'Neural', val: user.petRest, color: 'bg-green-500' },
          ].map(bar => (
            <div key={bar.label} className="text-center space-y-2 md:space-y-4">
              <span className="text-[7px] md:text-[10px] font-black opacity-40 uppercase tracking-[0.2em]">{bar.label}</span>
              <div className="h-3 md:h-5 bg-black/5 rounded-full overflow-hidden border-2 border-black/5 shadow-inner">
                <motion.div animate={{ width: `${Math.max(0, bar.val)}%` }} className={`h-full ${bar.color} rounded-full`} />
              </div>
            </div>
          ))}
        </div>
      </div>

      <div className="flex gap-2">
        {(['Care', 'Shop', 'Arcade'] as const).map(tab => (
          <button key={tab} onClick={() => setActiveTab(tab)} className={`flex-1 py-4 md:py-6 rounded-2xl md:rounded-[3rem] font-black text-[9px] md:text-xs uppercase border-b-4 md:border-b-[8px] transition-all shadow-xl ${activeTab === tab ? 'bg-custom border-black/20 text-white translate-y-[-2px]' : 'bg-white text-slate-400 border-gray-100'}`}>{tab}</button>
        ))}
      </div>

      <div className="grid grid-cols-2 md:grid-cols-3 gap-4 md:gap-8 pb-32">
        {activeTab === 'Shop' && ITEMS.map(item => (
          <button key={item.id} onClick={() => { if(user.moodCoins >= item.cost) onUpdate(item.type === 'hunger' ? item.fill : 0, item.type === 'thirst' ? item.fill : 0, 0, -item.cost, 0); }} className="p-6 md:p-12 rounded-[2.5rem] md:rounded-[4.5rem] bg-white text-slate-900 shadow-2xl border-4 border-black/5 flex flex-col items-center gap-2 group hover:scale-105 active:scale-95 transition-all">
            <span className="text-5xl md:text-8xl mb-2 md:mb-4 group-hover:scale-110 transition-transform">{item.emoji}</span>
            <span className="font-black uppercase text-[8px] md:text-xs tracking-widest text-center leading-tight">{item.name}</span>
            <div className="mt-4 bg-yellow-400 text-white px-4 md:px-8 py-2 md:py-3 rounded-xl md:rounded-2xl text-[8px] md:text-base font-black border-b-4 md:border-b-6 border-yellow-700 flex items-center gap-2 shadow-lg"><Coins size={16}/> {item.cost}</div>
          </button>
        ))}

        {activeTab === 'Arcade' && !gameMode && GAMES.map(game => {
          const cd = user.gameCooldowns?.[game.id];
          const isCooling = cd && cd > now;
          return (
            <button key={game.id} onClick={() => handleStartGame(game.id)} className={`relative p-6 md:p-12 rounded-[2.5rem] md:rounded-[4.5rem] bg-white text-slate-900 border-4 border-black/5 shadow-2xl flex flex-col items-center gap-2 group hover:scale-105 active:scale-95 transition-all ${isDepleted || isCooling ? 'opacity-40 grayscale pointer-events-none' : ''}`}>
              {isCooling && <div className="absolute inset-0 z-10 bg-black/80 rounded-[2.5rem] md:rounded-[4rem] flex flex-col items-center justify-center text-white p-4 text-center"><Timer size={32} className="animate-spin mb-2"/><span className="text-[8px] md:text-[10px] font-black uppercase">Neural Cooling</span></div>}
              <span className="text-5xl md:text-8xl mb-2 md:mb-4 group-hover:rotate-6 transition-transform">{game.emoji}</span>
              <span className="text-[8px] md:text-xs font-black uppercase text-center leading-tight tracking-[0.2em]">{game.name}</span>
              <div className="mt-3 bg-blue-500/10 text-blue-600 px-3 md:px-6 py-1 md:py-2 rounded-full text-[7px] md:text-[11px] font-black uppercase tracking-tighter">Gain XP</div>
            </button>
          );
        })}

        {gameMode && (
          <div className={`col-span-full p-10 md:p-20 rounded-[4rem] md:rounded-[6rem] text-white text-center shadow-2xl relative border-[16px] border-white/20 min-h-[420px] md:min-h-[500px] flex flex-col ${GAMES.find(g=>g.id===gameMode)?.color}`}>
              {gameResult ? (
                <div className="flex-1 flex flex-col items-center justify-center space-y-8 md:space-y-12">
                  <motion.div initial={{ scale: 0 }} animate={{ scale: 1 }}><Trophy size={100} md:size={140} className="text-yellow-300 animate-bounce" /></motion.div>
                  <div className="space-y-4">
                    <h4 className="text-3xl md:text-7xl font-black italic uppercase tracking-tighter leading-none">Sync Successful</h4>
                    <div className="flex gap-4 md:gap-8 justify-center">
                      <div className="bg-black/30 px-6 md:px-12 py-4 md:py-8 rounded-2xl md:rounded-[3rem] font-black text-xl md:text-5xl flex items-center gap-3 shadow-inner"><Coins size={40}/> {gameResult.coins}</div>
                      <div className="bg-black/30 px-6 md:px-12 py-4 md:py-8 rounded-2xl md:rounded-[3rem] font-black text-xl md:text-5xl flex items-center gap-3 shadow-inner"><Sparkles size={40}/> {gameResult.exp}</div>
                    </div>
                  </div>
                  <button onClick={() => setGameMode(null)} className="w-full max-w-sm py-5 md:py-8 bg-white text-slate-900 rounded-[2rem] font-black uppercase text-base md:text-2xl shadow-2xl active:scale-95 transition-transform">Close Terminal</button>
                </div>
              ) : (
                <div className="flex-1 flex flex-col items-center justify-center">
                   <div className="absolute top-10 right-10 flex items-center gap-3 bg-black/20 px-8 py-4 rounded-2xl font-black text-2xl md:text-5xl tabular-nums shadow-inner">
                     <Timer size={40} /> {timeLeft}s
                   </div>
                   {gameMode === 'clicker' && <motion.button whileTap={{ scale: 0.8 }} onClick={() => setTapScore(s=>s+1)} className="w-48 h-48 md:w-80 md:h-80 bg-yellow-400 rounded-[3rem] md:rounded-[5rem] shadow-[0_20px_0_0_#ca8a04] md:shadow-[0_40px_0_0_#ca8a04] flex items-center justify-center text-6xl md:text-[140px] font-black border-[12px] md:border-[20px] border-white/30"><DollarSign size={100}/></motion.button>}
                   {gameMode === 'math' && <div className="space-y-10"><p className="text-7xl md:text-[160px] font-black italic tracking-tighter tabular-nums">{mathProb.q}</p><input type="number" autoFocus value={mathInput} onChange={e => { setMathInput(e.target.value); if(parseInt(e.target.value) === mathProb.a) { setTapScore(s=>s+1); genMath(); } }} className="w-full max-w-sm md:max-w-lg p-6 md:p-10 rounded-[2rem] md:rounded-[4rem] bg-white text-slate-900 font-black text-4xl md:text-9xl text-center outline-none shadow-2xl" /></div>}
                   {gameMode === 'wheel' && <div className="space-y-12"><motion.div animate={wheelSpinning ? { rotate: 360 * 6 } : {}} transition={{ duration: 2, ease: "easeOut" }} className="text-[100px] md:text-[220px] mb-8">🎡</motion.div><button onClick={handleSpin} disabled={wheelSpinning} className="bg-white text-orange-500 px-12 md:px-20 py-5 md:py-8 rounded-[2rem] font-black text-2xl md:text-5xl uppercase shadow-2xl active:scale-95">Spin!</button></div>}
                   {gameMode === 'hunter' && <div className="relative w-full h-full min-h-[300px] border-4 border-dashed border-white/20 rounded-[3rem] overflow-hidden">
                      <motion.button animate={{ x: `${hunterTarget.x}%`, y: `${hunterTarget.y}%` }} onClick={() => { setTapScore(s=>s+1); genHunter(); }} className="absolute w-20 h-20 md:w-32 md:h-32 bg-white rounded-full flex items-center justify-center text-red-500 shadow-2xl border-8 border-white/30"><Target size={60} /></motion.button>
                   </div>}
                   {gameMode === 'memory' && <div className="grid grid-cols-2 gap-4"><button onClick={() => { setTapScore(s=>s+1); }} className="p-10 md:p-16 bg-white/20 rounded-[3rem] border-4 border-white/30 hover:bg-white/40 transition-colors"><Brain size={80} /></button></div>}
                   {gameMode === 'riddle' && <div className="space-y-10"><p className="text-4xl md:text-9xl font-black italic tracking-[0.2em] tabular-nums uppercase">{riddleWord.scrambled}</p><input type="text" autoFocus value={mathInput} onChange={e => { setMathInput(e.target.value.toUpperCase()); if(e.target.value.toUpperCase() === riddleWord.original) { setTapScore(s=>s+1); genRiddle(); } }} className="w-full max-w-sm md:max-w-lg p-6 md:p-10 rounded-[2rem] md:rounded-[4rem] bg-white text-slate-900 font-black text-3xl md:text-7xl text-center outline-none shadow-2xl uppercase" /></div>}
                   <p className="mt-12 md:mt-16 opacity-50 font-black uppercase tracking-[0.4em] text-[7px] md:text-sm">Processing Metropolis Data...</p>
                </div>
              )}
          </div>
        )}

        {activeTab === 'Care' && (
          <div className="col-span-full space-y-6 md:space-y-10">
            <div className="grid grid-cols-2 gap-4 md:gap-8">
              {SLEEP_MODES.map(mode => (
