const RIDDLE_WORDS = ['STREAK', 'CITIZEN', 'MOODERIA', 'GUARDIAN', 'COSMIC', 'NEURAL', 'SIGNAL', 'FREQUENCY'];

const MoodPetSection: React.FC<MoodPetSectionProps> = ({ user, isDarkMode, onUpdate, onPost }) => {
  const [activeTab, setActiveTab] = useState<'Care' | 'Shop' | 'Arcade'>('Care');
  const [creationStep, setCreationStep] = useState(1);
  const [tempName, setTempName] = useState('');
  const [selectedEmoji, setSelectedEmoji] = useState('');
  const [now, setNow] = useState(Date.now());

  const [gameMode, setGameMode] = useState<string | null>(null);
  const [gameResult, setGameResult] = useState<{ coins: number, exp: number } | null>(null);
  const [timeLeft, setTimeLeft] = useState(0);
  const [tapScore, setTapScore] = useState(0);
  const [mathProb, setMathProb] = useState({ q: '', a: 0 });
  const [mathInput, setMathInput] = useState('');
  const [wheelSpinning, setWheelSpinning] = useState(false);
  const [hunterTarget, setHunterTarget] = useState({ x: 50, y: 50 });
  const [riddleWord, setRiddleWord] = useState({ scrambled: '', original: '' });

  const [levelUpModal, setLevelUpModal] = useState<number | null>(null);

  const isSleeping = user.petSleepUntil && user.petSleepUntil > now;
  const isDepleted = user.petHunger <= 5 || user.petThirst <= 5 || user.petRest <= 5;

  useEffect(() => {
    const interval = setInterval(() => setNow(Date.now()), 1000);
    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
    let timer: number;
    if (gameMode && timeLeft > 0 && !gameResult) {
      timer = window.setInterval(() => setTimeLeft(prev => prev - 1), 1000);
    } else if (gameMode && timeLeft === 0 && !gameResult) {
      handleFinishGame();
    }
    return () => clearInterval(timer);
  }, [gameMode, timeLeft, gameResult]);

  // Level Up Watcher
  useEffect(() => {
    const needed = getExpNeeded(user.petLevel);
    if (user.petExp >= needed) {
      setLevelUpModal(user.petLevel + 1);
    }
  }, [user.petExp, user.petLevel]);

  const genMath = () => {
    const a = Math.floor(Math.random() * 25) + 5;
    const b = Math.floor(Math.random() * 25) + 5;
    setMathProb({ q: `${a} + ${b}`, a: a + b });
    setMathInput('');
  };

  const genHunter = () => {
    setHunterTarget({ x: 15 + Math.random() * 70, y: 15 + Math.random() * 70 });
  };

  const genRiddle = () => {
    const original = RIDDLE_WORDS[Math.floor(Math.random() * RIDDLE_WORDS.length)];
    const scrambled = original.split('').sort(() => 0.5 - Math.random()).join('');
    setRiddleWord({ scrambled, original });
    setMathInput('');
  };

  const handleStartGame = (id: string) => {
    if (isDepleted) return alert("Guardian needs energy to enter the arcade!");
    const cd = user.gameCooldowns?.[id];
    if (cd && cd > now) return;
    setGameMode(id);
    setGameResult(null);
    setTapScore(0);
    setTimeLeft(GAMES.find(g => g.id === id)?.time || 15);
    if (id === 'math') genMath();
    if (id === 'hunter') genHunter();
    if (id === 'riddle') genRiddle();
  };

  const handleFinishGame = (rewards?: { coins: number, exp: number }) => {
    let coins = rewards?.coins || 0;
    let exp = rewards?.exp || 0;

    if (gameMode === 'clicker') { coins = Math.min(100, tapScore * 4); exp = tapScore * 8; }
    if (gameMode === 'math') { coins = Math.min(150, tapScore * 12); exp = tapScore * 25; }
    if (gameMode === 'hunter') { coins = Math.min(120, tapScore * 10); exp = tapScore * 20; }
    if (gameMode === 'riddle') { coins = Math.min(200, tapScore * 30); exp = tapScore * 60; }

    setGameResult({ coins, exp });
    onUpdate(-15, -12, -10, coins, exp, null, undefined, undefined, undefined, gameMode!);
  };

  const handleSpin = () => {
    if (wheelSpinning) return;
    setWheelSpinning(true);
    setTimeout(() => {
      setWheelSpinning(false);
      const isBigWin = Math.random() > 0.85;
      const coins = isBigWin ? 250 : 60;
      const exp = isBigWin ? 400 : 120;
      handleFinishGame({ coins, exp });
    }, 2000);
  };

  const handleShareLevel = () => {
    if (levelUpModal) {
      onPost(`🚀 METROPOLIS GUARDIAN UPDATE: ${user.petName} just achieved Sync Level ${levelUpModal}! The bond is deepening. ✨ #MooderiaGuardian`);
      setLevelUpModal(null);
    }
  };

  if (!user.petHasBeenChosen) {
    return (
      <div className="flex flex-col items-center justify-center p-8 md:p-24 text-center min-h-[500px]">
        <AnimatePresence mode="wait">
          {creationStep === 1 && (
            <motion.div key="step1" initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} className="space-y-8 md:space-y-12 w-full max-w-md">
              <PenTool size={100} className="mx-auto text-custom animate-pulse" />
              <h2 className="text-3xl md:text-6xl font-black italic uppercase tracking-tighter leading-none">Design Guardian</h2>
              <input type="text" value={tempName} onChange={(e) => setTempName(e.target.value)} placeholder="Guardian Alias..." className="w-full p-6 md:p-10 rounded-[2rem] md:rounded-[3rem] border-4 bg-black/5 font-black text-center text-xl md:text-3xl outline-none focus:border-custom shadow-inner" />
              <button onClick={() => setCreationStep(2)} disabled={!tempName.trim()} className="kahoot-button-custom w-full py-6 md:py-10 rounded-[2.5rem] text-white font-black uppercase text-xl md:text-3xl shadow-2xl active:scale-95 transition-all">Next Phase</button>
            </motion.div>
          )}
          {creationStep === 2 && (
            <motion.div key="step2" initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} className="space-y-10 w-full max-w-2xl">
              <h2 className="text-3xl md:text-6xl font-black italic uppercase tracking-tighter leading-none">Select Neural Core</h2>
              <div className="grid grid-cols-5 gap-3 md:gap-6">
                {PET_OPTIONS.map(e => <button key={e} onClick={() => setSelectedEmoji(e)} className={`text-4xl md:text-6xl p-4 md:p-8 rounded-[1.5rem] md:rounded-[3rem] border-4 transition-all ${selectedEmoji === e ? 'border-custom bg-custom/10 scale-110 shadow-xl' : 'border-black/5'}`}>{e}</button>)}
              </div>
              <button onClick={() => setCreationStep(3)} disabled={!selectedEmoji} className="kahoot-button-custom w-full py-6 md:py-10 rounded-[2.5rem] text-white font-black uppercase text-xl md:text-3xl shadow-2xl active:scale-95 transition-all">Initialize Core</button>
            </motion.div>
          )}
          {creationStep === 3 && (
            <motion.div key="step3" initial={{ opacity: 0, scale: 0.8 }} animate={{ opacity: 1, scale: 1 }} className="space-y-12 md:space-y-20 text-center">
              <div className="text-[120px] md:text-[240px] animate-bounce drop-shadow-2xl">{selectedEmoji}</div>
              <h2 className="text-5xl md:text-[100px] font-black italic uppercase tracking-tighter leading-none">{tempName}</h2>
              <button onClick={() => onUpdate(0, 0, 0, 0, 0, null, selectedEmoji, true, tempName)} className="kahoot-button-custom w-full py-8 md:py-12 rounded-[3rem] text-white font-black uppercase text-2xl md:text-5xl shadow-2xl active:scale-95 transition-all">Finalize Bond</button>
            </motion.div>
          )}
        </AnimatePresence>
      </div>
    );
  }

  if (isSleeping) {
    return (
      <div className="p-16 md:p-32 rounded-[4rem] md:rounded-[6rem] bg-indigo-950 text-white shadow-2xl flex flex-col items-center justify-center text-center gap-10 md:gap-16 min-h-[500px] border-[16px] border-indigo-900">
        <motion.div animate={{ scale: [1, 1.1, 1], rotate: [0, 5, -5, 0] }} transition={{ repeat: Infinity, duration: 4 }}><Moon size={140} className="text-indigo-300 fill-indigo-200" /></motion.div>
        <div className="space-y-6">
          <h2 className="text-4xl md:text-[80px] font-black uppercase italic tracking-tighter leading-none">Neural Stasis</h2>
          <p className="opacity-40 font-black uppercase tracking-[0.4em] text-[10px] md:text-xl">Guardian core is recharging...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-10 md:space-y-16 pb-32 max-w-6xl mx-auto">
      {/* Level Up Modal */}
      <AnimatePresence>
        {levelUpModal && (
          <div className="fixed inset-0 z-[200] flex items-center justify-center p-6 bg-black/95 backdrop-blur-3xl">
            <motion.div initial={{ scale: 0.8, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} className="w-full max-w-lg bg-white rounded-[4rem] md:rounded-[6rem] p-12 md:p-20 text-center shadow-[0_0_120px_rgba(255,166,2,0.5)] border-[12px] border-yellow-400/20">
              <Trophy size={140} className="mx-auto text-yellow-500 animate-bounce mb-8" />
              <h2 className="text-5xl md:text-8xl font-black italic uppercase tracking-tighter text-slate-900 leading-none mb-4">SYNC UP!</h2>
              <p className="text-2xl md:text-4xl font-black text-custom uppercase italic tracking-widest mb-12">Rank {levelUpModal}</p>
              <div className="flex flex-col gap-4">
                <button onClick={handleShareLevel} className="kahoot-button-custom flex items-center justify-center gap-4 py-6 md:py-10 rounded-[2.5rem] text-white font-black uppercase text-xl md:text-3xl shadow-2xl active:scale-95 transition-all">
                  <Share2 size={32} /> Share Progress
                </button>
                <button onClick={() => setLevelUpModal(null)} className="py-6 text-sm md:text-xl font-black text-slate-400 uppercase tracking-widest hover:text-slate-900 transition-colors">
                  Skip Transmission
                </button>
              </div>
            </motion.div>
          </div>
        )}
      </AnimatePresence>

      {/* Main Pet Display Card - Big and Scrollable Feel */}
      <div className={`relative p-10 md:p-20 rounded-[4rem] md:rounded-[7rem] ${isDarkMode ? 'bg-slate-900' : 'bg-white'} border-4 border-black/5 shadow-2xl flex flex-col items-center overflow-hidden min-h-[500px] md:min-h-[720px]`}>
        <div className="absolute top-10 left-10 bg-yellow-400 text-white px-8 md:px-14 py-4 md:py-8 rounded-[2rem] md:rounded-[3rem] font-black text-xl md:text-5xl shadow-2xl border-b-8 md:border-b-[16px] border-yellow-700 flex items-center gap-4 active:scale-90 transition-all cursor-default z-10 tabular-nums">
          <Coins size={40}/> {user.moodCoins}
        </div>

        <div className="absolute top-10 right-10 flex flex-col items-end gap-3 z-10">
           <div className="bg-blue-600/10 text-blue-600 px-6 py-2 rounded-full font-black uppercase text-[10px] md:text-sm tracking-widest border border-blue-600/20">Rank {user.petLevel} Guardian</div>
           <div className="w-32 md:w-64 h-3 md:h-6 bg-black/5 rounded-full overflow-hidden p-1 shadow-inner border-2 border-black/5">
              <motion.div initial={{ width: 0 }} animate={{ width: `${(user.petExp / getExpNeeded(user.petLevel)) * 100}%` }} className="h-full bg-gradient-to-r from-blue-400 via-indigo-500 to-purple-600 rounded-full" />
           </div>
           <p className="text-[8px] md:text-[10px] font-black opacity-30 uppercase tabular-nums">{user.petExp} / {getExpNeeded(user.petLevel)} SYNC XP</p>
        </div>

        <motion.div animate={{ y: [0, -40, 0], scale: [1, 1.08, 1] }} transition={{ duration: 5, repeat: Infinity, ease: "easeInOut" }} className="text-[200px] md:text-[400px] my-10 md:my-16 drop-shadow-[0_45px_45px_rgba(0,0,0,0.15)] select-none pointer-events-none">
          {user.petEmoji}
        </motion.div>

        <div className="w-full max-w-4xl grid grid-cols-3 gap-6 md:gap-20 mt-10">
          {[
            { label: 'Neural Energy', val: user.petHunger, color: 'bg-red-500' },
            { label: 'Vibe Sync', val: user.petThirst, color: 'bg-blue-500' },
            { label: 'Stasis Level', val: user.petRest, color: 'bg-green-500' },
          ].map(bar => (
            <div key={bar.label} className="text-center space-y-3 md:space-y-6">
              <span className="text-[8px] md:text-sm font-black opacity-40 uppercase tracking-[0.3em]">{bar.label}</span>
              <div className="h-4 md:h-10 bg-black/5 rounded-full overflow-hidden border-4 border-black/5 shadow-inner p-1">
                <motion.div animate={{ width: `${Math.max(0, bar.val)}%` }} className={`h-full ${bar.color} rounded-full shadow-lg`} />
              </div>
              <p className="text-[10px] md:text-xl font-black italic opacity-60 tabular-nums">{Math.round(bar.val)}%</p>
            </div>
          ))}
        </div>
      </div>

      <div className="flex gap-4">
        {(['Care', 'Shop', 'Arcade'] as const).map(tab => (
          <button key={tab} onClick={() => setActiveTab(tab)} className={`flex-1 py-6 md:py-10 rounded-[2.5rem] md:rounded-[4rem] font-black text-[10px] md:text-xl uppercase border-b-[8px] md:border-b-[16px] transition-all shadow-xl ${activeTab === tab ? 'bg-custom border-black/20 text-white translate-y-[-4px]' : 'bg-white text-slate-400 border-gray-100'}`}>{tab}</button>
        ))}
      </div>

      <div className="grid grid-cols-2 md:grid-cols-4 gap-4 md:gap-10 pb-40">
        <AnimatePresence mode="wait">
          {activeTab === 'Shop' && (
            <motion.div key="shop" initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="col-span-full grid grid-cols-2 md:grid-cols-4 gap-6 md:gap-10">
              {ITEMS.map(item => (
                <button key={item.id} onClick={() => { if(user.moodCoins >= item.cost) onUpdate(item.type === 'hunger' ? item.fill : 0, item.type === 'thirst' ? item.fill : 0, 0, -item.cost, 0); }} className="p-8 md:p-14 rounded-[3.5rem] md:rounded-[5rem] bg-white text-slate-900 shadow-2xl border-4 border-black/5 flex flex-col items-center gap-4 group hover:scale-105 active:scale-95 transition-all">
                  <span className="text-6xl md:text-[100px] mb-4 group-hover:scale-110 transition-transform">{item.emoji}</span>
                  <span className="font-black uppercase text-[10px] md:text-base tracking-widest text-center leading-tight h-10 md:h-12 flex items-center">{item.name}</span>
                  <div className="mt-4 bg-yellow-400 text-white px-6 md:px-12 py-3 md:py-5 rounded-2xl md:rounded-[2.5rem] text-xs md:text-2xl font-black border-b-6 md:border-b-[12px] border-yellow-700 flex items-center gap-3 shadow-xl"><Coins size={24}/> {item.cost}</div>
                </button>
              ))}
            </motion.div>
          )}

          {activeTab === 'Arcade' && !gameMode && (
             <motion.div key="arcade" initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="col-span-full grid grid-cols-2 md:grid-cols-3 gap-6 md:gap-10">
               {GAMES.map(game => {
                 const cd = user.gameCooldowns?.[game.id];
                 const isCooling = cd && cd > now;
                 return (
                   <button key={game.id} onClick={() => handleStartGame(game.id)} className={`relative p-8 md:p-14 rounded-[3.5rem] md:rounded-[5rem] bg-white text-slate-900 border-4 border-black/5 shadow-2xl flex flex-col items-center gap-4 group hover:scale-105 active:scale-95 transition-all ${isDepleted || isCooling ? 'opacity-40 grayscale pointer-events-none' : ''}`}>
                     {isCooling && <div className="absolute inset-0 z-10 bg-black/80 rounded-[3rem] md:rounded-[4.5rem] flex flex-col items-center justify-center text-white p-6 text-center"><Timer size={60} className="animate-spin mb-4"/><span className="text-sm md:text-2xl font-black uppercase tracking-widest">Rebooting Grid</span></div>}
                     <span className="text-7xl md:text-[120px] mb-4 group-hover:rotate-6 transition-transform">{game.emoji}</span>
                     <span className="text-[10px] md:text-xl font-black uppercase text-center leading-tight tracking-[0.2em]">{game.name}</span>
                     <div className="mt-4 bg-blue-600/10 text-blue-600 px-6 py-2 md:py-4 rounded-full text-[8px] md:text-sm font-black uppercase tracking-tighter border border-blue-600/20">Awards Neural XP</div>
                   </button>
                 );
               })}
             </motion.div>
          )}

          {/* FULL SCREEN GAME VIEWPORT */}
          {gameMode && (
            <div className="fixed inset-0 z-[200] flex items-center justify-center p-0 md:p-12 bg-black/95 backdrop-blur-2xl">
              <motion.div initial={{ scale: 0.9, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} className={`w-full h-full md:rounded-[6rem] text-white text-center shadow-[0_0_100px_rgba(255,255,255,0.1)] relative border-b-[24px] border-white/10 flex flex-col ${GAMES.find(g=>g.id===gameMode)?.color}`}>
                  {gameResult ? (
                    <div className="flex-1 flex flex-col items-center justify-center space-y-12 md:space-y-24 p-10">
                      <motion.div initial={{ scale: 0 }} animate={{ scale: 1 }} transition={{ type: 'spring' }}><Trophy size={180} md:size={300} className="text-yellow-300 animate-bounce drop-shadow-[0_20px_40px_rgba(0,0,0,0.3)]" /></motion.div>
                      <div className="space-y-6 md:space-y-10">
                        <h4 className="text-5xl md:text-[10rem] font-black italic uppercase tracking-tighter leading-none">TRANSMISSION OK</h4>
                        <div className="flex gap-6 md:gap-16 justify-center">
                          <div className="bg-black/30 px-10 md:px-24 py-6 md:py-12 rounded-[3rem] md:rounded-[5rem] font-black text-3xl md:text-8xl flex items-center gap-6 shadow-2xl"><Coins size={60}/> {gameResult.coins}</div>
                          <div className="bg-black/30 px-10 md:px-24 py-6 md:py-12 rounded-[3rem] md:rounded-[5rem] font-black text-3xl md:text-8xl flex items-center gap-6 shadow-2xl"><Sparkles size={60}/> {gameResult.exp} XP</div>
                        </div>
                      </div>
                      <button onClick={() => setGameMode(null)} className="w-full max-w-2xl py-8 md:py-14 bg-white text-slate-900 rounded-[3rem] md:rounded-[5rem] font-black uppercase text-2xl md:text-6xl shadow-2xl active:scale-95 transition-all">TERMINATE LINK</button>
                    </div>
                  ) : (
                    <div className="flex-1 flex flex-col items-center justify-center p-6 md:p-20 relative">
                       <div className="absolute top-10 right-10 flex items-center gap-6 bg-black/20 px-10 md:px-20 py-5 md:py-10 rounded-[2.5rem] md:rounded-[4rem] font-black text-3xl md:text-8xl tabular-nums shadow-inner border-4 border-white/20">
                         <Timer size={60} /> {timeLeft}s
                       </div>

                       <div className="flex-1 w-full flex flex-col items-center justify-center">
                         {gameMode === 'clicker' && <motion.button whileTap={{ scale: 0.85 }} onClick={() => setTapScore(s=>s+1)} className="w-64 h-64 md:w-[600px] md:h-[600px] bg-yellow-400 rounded-[5rem] md:rounded-[10rem] shadow-[0_30px_0_0_#ca8a04] md:shadow-[0_80px_0_0_#ca8a04] flex items-center justify-center text-[100px] md:text-[300px] font-black border-[16px] md:border-[40px] border-white/30"><DollarSign size={240}/></motion.button>}

                         {gameMode === 'math' && <div className="space-y-16 md:space-y-32 w-full"><p className="text-[120px] md:text-[300px] font-black italic tracking-tighter tabular-nums leading-none">{mathProb.q}</p><input type="number" autoFocus value={mathInput} onChange={e => { setMathInput(e.target.value); if(parseInt(e.target.value) === mathProb.a) { setTapScore(s=>s+1); genMath(); } }} className="w-full max-w-sm md:max-w-4xl p-10 md:p-24 rounded-[3rem] md:rounded-[6rem] bg-white text-slate-900 font-black text-6xl md:text-[180px] text-center outline-none shadow-2xl border-[16px] md:border-[32px] border-black/5" /></div>}

                         {gameMode === 'wheel' && <div className="space-y-16 md:space-y-32"><motion.div animate={wheelSpinning ? { rotate: 360 * 10 } : {}} transition={{ duration: 2, ease: "easeOut" }} className="text-[200px] md:text-[500px] drop-shadow-2xl leading-none">🎡</motion.div><button onClick={handleSpin} disabled={wheelSpinning} className="bg-white text-orange-500 px-20 md:px-40 py-8 md:py-20 rounded-[3rem] md:rounded-[6rem] font-black text-4xl md:text-9xl uppercase shadow-2xl active:scale-95 transition-all">SPIN NOW!</button></div>}

                         {gameMode === 'hunter' && <div className="relative w-full h-full max-w-5xl md:h-[80vh] border-[12px] md:border-[24px] border-dashed border-white/20 rounded-[4rem] md:rounded-[8rem] overflow-hidden bg-black/10">
                            <motion.button animate={{ x: `${hunterTarget.x}%`, y: `${hunterTarget.y}%` }} transition={{ type: 'spring', damping: 10 }} onClick={() => { setTapScore(s=>s+1); genHunter(); }} className="absolute w-24 h-24 md:w-56 md:h-56 bg-white rounded-full flex items-center justify-center text-red-500 shadow-2xl border-8 md:border-[24px] border-white/40 active:scale-75 transition-transform"><Target size={120} /></motion.button>
                         </div>}

                         {gameMode === 'memory' && <div className="grid grid-cols-2 gap-10"><button onClick={() => { setTapScore(s=>s+1); }} className="p-20 md:p-48 bg-white/20 rounded-[5rem] border-[16px] border-white/30 hover:bg-white/40 transition-all active:scale-90"><Brain size={240} /></button></div>}

                         {gameMode === 'riddle' && <div className="space-y-16 md:space-y-32 w-full"><p className="text-5xl md:text-[14rem] font-black italic tracking-[0.4em] tabular-nums uppercase leading-none">{riddleWord.scrambled}</p><input type="text" autoFocus value={mathInput} onChange={e => { setMathInput(e.target.value.toUpperCase()); if(e.target.value.toUpperCase() === riddleWord.original) { setTapScore(s=>s+1); genRiddle(); } }} className="w-full max-w-sm md:max-w-5xl p-10 md:p-24 rounded-[3rem] md:rounded-[6rem] bg-white text-slate-900 font-black text-4xl md:text-[120px] text-center outline-none shadow-2xl uppercase border-[16px] md:border-[32px] border-black/5" /></div>}
                       </div>

                       <p className="mt-16 md:mt-24 opacity-40 font-black uppercase tracking-[0.6em] text-[10px] md:text-4xl italic">NEURAL INTERFACE: ACTIVE</p>
                    </div>
                  )}
              </motion.div>
            </div>
          )}

          {activeTab === 'Care' && (
            <motion.div key="care" initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="col-span-full space-y-10 md:space-y-20">
              <div className="grid grid-cols-1 md:grid-cols-3 gap-6 md:gap-10">
                {SLEEP_MODES.map(mode => (
                  <button key={mode.id} onClick={() => onUpdate(0,0,mode.rest, -mode.cost, 0, Date.now() + mode.duration * 60000)} className="p-10 md:p-16 rounded-[4rem] md:rounded-[5.5rem] bg-white text-slate-900 shadow-2xl border-4 border-black/5 flex flex-col items-center gap-6 transition-transform hover:scale-105 active:scale-95">
                    <span className="text-[80px] md:text-[140px] leading-none">{mode.emoji}</span>
                    <p className="font-black uppercase text-xl md:text-4xl tracking-tighter text-center leading-none">{mode.name}</p>
                    <p className="text-xs md:text-xl font-black text-blue-500 opacity-60 uppercase tracking-widest">+{mode.rest}% Core Pulse</p>
                    <div className="bg-yellow-400 text-white px-8 md:px-14 py-4 md:py-6 rounded-[2rem] md:rounded-[3.5rem] text-sm md:text-3xl font-black border-b-8 md:border-b-[16px] border-yellow-700 flex items-center gap-4 shadow-2xl mt-4"><Coins size={32}/> {mode.cost}</div>
                  </button>
                ))}
              </div>
