                        </div>
                        <button onClick={() => setQuizActive(false)} className="kahoot-button-custom px-16 py-8 rounded-[3rem] text-white font-black uppercase text-xl md:text-4xl">Reset Terminal</button>
                     </motion.div>
                   ) : (
                     <div className="space-y-16">
                        <div className="h-6 bg-black/10 rounded-full overflow-hidden mb-16 p-1.5 shadow-inner"><motion.div className="h-full bg-blue-500 rounded-full" initial={{ width: 0 }} animate={{ width: `${((quizStep + 1) / QUIZ_STEPS.length) * 100}%` }} /></div>
                        <p className="text-3xl md:text-[5rem] font-black italic mb-16 leading-none">"{QUIZ_STEPS[quizStep].q}"</p>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6 md:gap-10">
                           {QUIZ_STEPS[quizStep].options.map((opt, i) => (
                             <button key={opt} onClick={() => handleQuizChoice(i)} className="kahoot-button-custom py-8 md:py-12 rounded-[2.5rem] md:rounded-[4rem] text-white font-black uppercase tracking-tight text-xl md:text-4xl shadow-xl active:scale-95 transition-transform">{opt}</button>
                           ))}
                        </div>
                     </div>
                   )}
                 </div>
               )}
            </motion.div>
          )}

          {subTab === 'Mood Pet' && (
            <motion.div key="pet" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}>
               <MoodPetSection user={user} isDarkMode={isDarkMode} onUpdate={onUpdatePet} onPost={onPost} />
            </motion.div>
          )}
        </AnimatePresence>
      </div>
    </div>
  );
};

