                    </div>
                  ))}
               </div>
            </motion.div>
          )}

          {tab === 'LuckyDay' && (
            <motion.div key="lucky" initial={{ opacity: 0 }} animate={{ opacity: 1 }} className={`p-6 md:p-10 rounded-[3rem] md:rounded-[4rem] ${isDarkMode ? 'bg-[#111111]' : 'bg-white'} border-4 border-black/5 shadow-2xl text-center`}>
