                    <div className="absolute top-4 right-6 opacity-20"><Unlock size={32} className="text-custom" /></div>
                    <h4 className="text-lg md:text-2xl font-black text-custom uppercase italic mb-3 md:mb-4 tracking-widest">{horoscope.sign} Alignment</h4>
