                  </motion.div>
                )}
              </AnimatePresence>
            </motion.div>
          )}

          {tab === 'Almanac' && (
            <motion.div key="almanac" initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="space-y-6">
               <div className={`p-8 md:p-10 rounded-[3rem] ${isDarkMode ? 'bg-[#111111]' : 'bg-white'} border-4 border-black/5 shadow-2xl text-center mb-8`}>
