    let hash = 0;
    for (let i = 0; i < seed.length; i++) hash = seed.charCodeAt(i) + ((hash << 5) - hash);
    const colors = [
      { name: "Ruby Red", hex: "#e21b3c" },
      { name: "Emerald Green", hex: "#26890c" },
      { name: "Azure Blue", hex: "#1368ce" },
      { name: "Goldenrod", hex: "#ffa602" },
      { name: "Metropolis Purple", hex: "#46178f" }
