                       <div className="absolute top-6 right-6 flex items-center gap-3 bg-black/20 px-6 py-3 rounded-2xl font-black text-2xl tabular-nums shadow-inner border-2 border-white/20">
                         <Timer size={24} /> {timeLeft}s
