                       <div className="flex-1 w-full flex flex-col items-center justify-center">
                         {gameMode === 'clicker' && (
                           <div className="flex flex-col items-center gap-8">
                             <p className="text-6xl font-black tabular-nums">{tapScore}</p>
                             <motion.button whileTap={{ scale: 0.85 }} onClick={() => setTapScore(s=>s+1)} className="w-48 h-48 md:w-64 md:h-64 bg-yellow-400 rounded-[3rem] shadow-[0_15px_0_0_#ca8a04] flex items-center justify-center text-8xl font-black border-[12px] border-white/30 hover:scale-105 transition-all"><DollarSign size={80}/></motion.button>
                           </div>
                         )}

                         {gameMode === 'math' && <div className="space-y-8 w-full"><p className="text-7xl md:text-9xl font-black italic tracking-tighter tabular-nums leading-none">{mathProb.q}</p><input type="number" autoFocus value={mathInput} onChange={e => { setMathInput(e.target.value); if(parseInt(e.target.value) === mathProb.a) { setTapScore(s=>s+1); genMath(); } }} className="w-full max-w-sm p-6 rounded-3xl bg-white text-slate-900 font-black text-4xl text-center outline-none shadow-xl border-4 border-black/5" /></div>}

                         {gameMode === 'wheel' && <div className="space-y-12"><motion.div animate={wheelSpinning ? { rotate: 360 * 5 } : {}} transition={{ duration: 2, ease: "easeOut" }} className="text-[120px] drop-shadow-xl leading-none">🎡</motion.div><button onClick={handleSpin} disabled={wheelSpinning} className="bg-white text-orange-500 px-12 py-4 rounded-2xl font-black text-2xl uppercase shadow-lg active:scale-95">Spin!</button></div>}

                         {gameMode === 'hunter' && <div className="relative w-full h-full max-w-lg border-4 border-dashed border-white/20 rounded-3xl overflow-hidden bg-black/10">
                            <motion.button animate={{ x: `${hunterTarget.x}%`, y: `${hunterTarget.y}%` }} onClick={() => { setTapScore(s=>s+1); genHunter(); }} className="absolute w-20 h-20 bg-white rounded-full flex items-center justify-center text-red-500 shadow-xl border-4 border-white/40 active:scale-75"><Target size={40} /></motion.button>
                         </div>}

                         {gameMode === 'memory' && <div className="grid grid-cols-2 gap-6"><button onClick={() => { setTapScore(s=>s+1); }} className="p-12 md:p-16 bg-white/20 rounded-[2rem] border-4 border-white/30 hover:bg-white/40 transition-all active:scale-90"><Brain size={80} /></button></div>}

                         {gameMode === 'riddle' && <div className="space-y-8 w-full"><p className="text-4xl md:text-7xl font-black italic tracking-widest uppercase leading-none">{riddleWord.scrambled}</p><input type="text" autoFocus value={mathInput} onChange={e => { setMathInput(e.target.value.toUpperCase()); if(e.target.value.toUpperCase() === riddleWord.original) { setTapScore(s=>s+1); genRiddle(); } }} className="w-full max-w-sm p-6 rounded-3xl bg-white text-slate-900 font-black text-2xl text-center outline-none shadow-xl uppercase border-4 border-black/5" /></div>}
                       </div>

                       <p className="mt-8 opacity-40 font-black uppercase tracking-widest text-[10px] italic">NEURAL INTERFACE ACTIVE</p>
                    </div>
                  )}
              </motion.div>
            </div>
          )}

          {activeTab === 'Care' && (
            <motion.div key="care" initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="col-span-full space-y-6">
              <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                {SLEEP_MODES.map(mode => (
                  <button key={mode.id} onClick={() => onUpdate(0,0,mode.rest, -mode.cost, 5, Date.now() + mode.duration * 60000)} className="p-8 rounded-3xl bg-white text-slate-900 shadow-md border-2 border-black/5 flex flex-col items-center gap-4 transition-all active:scale-95">
                    <span className="text-6xl leading-none">{mode.emoji}</span>
                    <p className="font-black uppercase text-base tracking-tighter text-center leading-none">{mode.name}</p>
                    <p className="text-[10px] font-black text-blue-500 opacity-60 uppercase tracking-widest">+{mode.rest}% Core</p>
                    <div className="bg-yellow-400 text-white px-6 py-2 rounded-2xl text-xs font-black border-b-4 border-yellow-700 flex items-center gap-2 shadow-sm mt-2"><Coins size={18}/> {mode.cost}</div>
                  </button>
                ))}
              </div>
              <button onClick={() => onUpdate(0,0,0,0,15)} className="w-full p-12 rounded-[3.5rem] bg-custom text-white shadow-lg flex flex-col items-center justify-center gap-4 border-b-8 border-black/20 active:translate-y-2 active:border-b-0 transition-all group overflow-hidden relative">
                <motion.div 
                  initial={{ scale: 1 }}
                  whileTap={{ scale: 1.5, rotate: 10 }}
                  className="z-10"
                >
                  <Heart size={80} className="group-hover:animate-ping" />
                </motion.div>
                <div className="text-center z-10">
                  <h4 className="text-2xl font-black italic uppercase tracking-tighter leading-none">Sync Core</h4>
                  <p className="text-[9px] font-black opacity-60 uppercase tracking-widest mt-2">Harmonize Vibe (+15 XP)</p>
                </div>
                {/* Visual heart feedback */}
                <div className="absolute inset-0 bg-white/5 opacity-0 group-hover:opacity-100 transition-opacity" />
              </button>
            </motion.div>
          )}
        </AnimatePresence>
      </div>
    </div>
  );
};

export default MoodPetSection;

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { User, Mood, Section, Post, Comment, Message, Notification } from './types';
import Sidebar from './components/Sidebar';
import MoodCheckIn from './components/MoodCheckIn';
import HomeSection from './sections/HomeSection';
import MoodSection from './sections/MoodSection';
import ZodiacSection from './sections/ZodiacSection';
import CityHallSection from './sections/CityHallSection';
import ProfileSection from './sections/ProfileSection';
import SettingsSection from './sections/SettingsSection';
import NotificationsSection from './sections/NotificationsSection';
import AuthScreen from './sections/AuthScreen';
import LoadingScreen from './components/LoadingScreen';
import { getExpNeeded, MOOD_SCORES } from './constants';
import { Trophy, Share2, X } from 'lucide-react';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [activeSection, setActiveSection] = useState<Section>('Home');
  const [viewingUsername, setViewingUsername] = useState<string | null>(null);
  const [isMoodModalOpen, setIsMoodModalOpen] = useState(false);
  const [isDarkMode, setIsDarkMode] = useState(false); 
  const [isAppStarting, setIsAppStarting] = useState(true);
  const [levelUpInfo, setLevelUpInfo] = useState<{ level: number } | null>(null);
  const [globalUpdateToggle, setGlobalUpdateToggle] = useState(0);

  const [allPosts, setAllPosts] = useState<Post[]>([]);
  const [allMessages, setAllMessages] = useState<Message[]>([]);
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);

  const profileToView = useMemo(() => {
    if (!viewingUsername) return null;
    if (currentUser && viewingUsername === currentUser.username) return currentUser;
    const allUsers: User[] = JSON.parse(localStorage.getItem('mooderia_all_users') || '[]');
    return allUsers.find(u => u.username === viewingUsername) || null;
  }, [viewingUsername, currentUser, globalUpdateToggle]);

  const addNotification = useCallback((recipient: string, type: Notification['type'], snippet: string, postId: string = '') => {
    if (!currentUser || recipient === currentUser.username) {
      // Allow achievement notifications for self
      if (type !== 'achievement' && type !== 'tier') return;
    }
    const newNotif: Notification = {
      id: Math.random().toString(36).substr(2, 9),
      fromUser: currentUser?.username || 'Metropolis',
      recipient,
      type,
      postId,
      timestamp: Date.now(),
      read: false,
      postContentSnippet: snippet
    };
    setNotifications(prev => [...prev, newNotif]);
  }, [currentUser]);

  useEffect(() => {
    const savedUser = localStorage.getItem('mooderia_user');
    const savedPosts = localStorage.getItem('mooderia_posts') || '[]';
    const savedMessages = localStorage.getItem('mooderia_messages') || '[]';
    const savedNotifications = localStorage.getItem('mooderia_notifications') || '[]';
    const savedTheme = localStorage.getItem('mooderia_theme');

    if (savedUser) {
      const user: User = JSON.parse(savedUser);
      const now = Date.now();
      const elapsedMinutes = Math.floor((now - (user.petLastUpdate || now)) / 60000);
      if (elapsedMinutes > 0) {
        user.petHunger = Math.max(0, user.petHunger - elapsedMinutes * 0.15);
        user.petThirst = Math.max(0, user.petThirst - elapsedMinutes * 0.2);
        if (!user.petSleepUntil || user.petSleepUntil < now) {
          user.petRest = Math.max(0, user.petRest - elapsedMinutes * 0.1);
        }
        user.petLastUpdate = now;
      }
      setCurrentUser(user);
    }

    setAllPosts(JSON.parse(savedPosts));
    setAllMessages(JSON.parse(savedMessages));
    setNotifications(JSON.parse(savedNotifications));
    if (savedTheme === 'dark') setIsDarkMode(true);
    setIsLoaded(true);

    const timer = setTimeout(() => setIsAppStarting(false), 2000);
    return () => clearTimeout(timer);
  }, []);

  useEffect(() => {
    if (!isAppStarting && currentUser) {
      const todayStr = new Date().toDateString();
      if (currentUser.lastMoodDate !== todayStr) {
        setIsMoodModalOpen(true);
      }
    }
  }, [isAppStarting, currentUser?.username, currentUser?.lastMoodDate]);

  useEffect(() => {
    if (!isLoaded) return;
    if (currentUser) {
      localStorage.setItem('mooderia_user', JSON.stringify(currentUser));
      const allUsers: User[] = JSON.parse(localStorage.getItem('mooderia_all_users') || '[]');
      const idx = allUsers.findIndex(u => u.username === currentUser.username);
      if (idx > -1) {
        allUsers[idx] = currentUser;
        localStorage.setItem('mooderia_all_users', JSON.stringify(allUsers));
      }
    }
    localStorage.setItem('mooderia_posts', JSON.stringify(allPosts));
    localStorage.setItem('mooderia_messages', JSON.stringify(allMessages));
    localStorage.setItem('mooderia_notifications', JSON.stringify(notifications));
    localStorage.setItem('mooderia_theme', isDarkMode ? 'dark' : 'light');
  }, [currentUser, allPosts, allMessages, notifications, isDarkMode, isLoaded]);

  const handleFollow = (targetUsername: string) => {
    if (!currentUser) return;
    const isFollowing = currentUser.following.includes(targetUsername);

    const updatedFollowing = isFollowing 
      ? currentUser.following.filter(u => u !== targetUsername)
      : [...currentUser.following, targetUsername];
    setCurrentUser({ ...currentUser, following: updatedFollowing });

    const allUsers: User[] = JSON.parse(localStorage.getItem('mooderia_all_users') || '[]');
    const targetIdx = allUsers.findIndex(u => u.username === targetUsername);
    if (targetIdx > -1) {
      const targetUser = { ...allUsers[targetIdx] };
      targetUser.followers = isFollowing 
        ? targetUser.followers.filter(u => u !== currentUser.username)
        : [...targetUser.followers, currentUser.username];
      allUsers[targetIdx] = targetUser;
      localStorage.setItem('mooderia_all_users', JSON.stringify(allUsers));

      if (!isFollowing) {
        addNotification(targetUsername, 'follow', 'started following you!');
      }
    }
    setGlobalUpdateToggle(t => t + 1);
  };

  const handleHeart = (postId: string) => {
    if (!currentUser) return;
    setAllPosts(prev => prev.map(p => {
      if (p.id === postId) {
        if (p.author !== currentUser.username) {
          addNotification(p.author, 'heart', 'liked your expression', p.id);
        }
        return { ...p, hearts: p.hearts + 1 };
      }
      return p;
    }));
  };

  const handleCommentInteraction = (postId: string, commentId: string, action: 'heart' | 'reply', replyText?: string) => {
    if (!currentUser) return;
    setAllPosts(prev => prev.map(p => {
      if (p.id === postId) {
        const updateNested = (list: Comment[]): Comment[] => {
          return list.map(c => {
            if (c.id === commentId) {
              if (action === 'heart') {
                if (c.author !== currentUser.username) addNotification(c.author, 'comment_heart', 'liked your frequency', postId);
                return { ...c, hearts: c.hearts + 1 };
              }
              if (action === 'reply' && replyText) {
                const newRep: Comment = {
                  id: Math.random().toString(36).substr(2, 9),
                  author: currentUser.username,
                  text: replyText,
                  hearts: 0,
                  timestamp: Date.now(),
                  replies: []
                };
                if (c.author !== currentUser.username) addNotification(c.author, 'reply', 'responded to your frequency', postId);
                return { ...c, replies: [...c.replies, newRep] };
              }
            }
            if (c.replies.length > 0) return { ...c, replies: updateNested(c.replies) };
            return c;
          });
        };
        return { ...p, comments: updateNested(p.comments) };
      }
      return p;
    }));
  };

  const handleRepost = (p: Post) => {
    if (!currentUser) return;
    const newRepost: Post = {
      id: Math.random().toString(36).substr(2, 9),
      author: currentUser.username,
      content: p.content,
      hearts: 0,
      comments: [],
      timestamp: Date.now(),
      isRepost: true,
      originalAuthor: p.author,
      visibility: 'global'
    };
    setAllPosts(prev => [newRepost, ...prev]);
    if (p.author !== currentUser.username) {
      addNotification(p.author, 'repost', 'echoed your transmission', p.id);
    }
  };

  const handleBlock = (targetUsername: string) => {
    if (!currentUser) return;

    // Unfollow target if currently following
    const updatedFollowing = currentUser.following.filter(u => u !== targetUsername);
    const updatedBlocked = [...currentUser.blockedUsers, targetUsername];

    setCurrentUser({ 
      ...currentUser, 
      following: updatedFollowing,
      blockedUsers: updatedBlocked 
    });

    const allUsers: User[] = JSON.parse(localStorage.getItem('mooderia_all_users') || '[]');
    const targetIdx = allUsers.findIndex(u => u.username === targetUsername);
    if (targetIdx > -1) {
      const targetUser = { ...allUsers[targetIdx] };
      // Remove current user from target's followers
      targetUser.followers = targetUser.followers.filter(u => u !== currentUser.username);
      // Remove target from current user's following is already handled by updatedFollowing above
      // But we also need to ensure the target's following list removes the current user if they follow back
      targetUser.following = targetUser.following.filter(u => u !== currentUser.username);

      allUsers[targetIdx] = targetUser;

      // Update current user's followers in the global list as well (mutual unfollow on block)
      const currentIdxGlobal = allUsers.findIndex(u => u.username === currentUser.username);
      if (currentIdxGlobal > -1) {
        allUsers[currentIdxGlobal].followers = allUsers[currentIdxGlobal].followers.filter(u => u !== targetUsername);
      }

      localStorage.setItem('mooderia_all_users', JSON.stringify(allUsers));
    }

    setViewingUsername(currentUser.username);
    setActiveSection('Home');
    setGlobalUpdateToggle(t => t + 1);
  };

  const updatePetStats = (hunger: number, thirst: number, rest: number, coins: number, exp: number = 0, sleepUntil: number | null = null, newEmoji?: string, markChosen?: boolean, newName?: string, gameCooldownId?: string) => {
    if (!currentUser) return;
    let newLevel = currentUser.petLevel;
    let newExp = currentUser.petExp + exp;
    let leveledUp = false;

    while (newExp >= getExpNeeded(newLevel)) {
      newExp -= getExpNeeded(newLevel);
      newLevel += 1;
      leveledUp = true;
    }

    if (leveledUp) {
      addNotification(currentUser.username, 'achievement', `Your Guardian ${newName || currentUser.petName} reached Level ${newLevel}!`);
    }

    setCurrentUser({
      ...currentUser,
      petName: newName || currentUser.petName,
      petHunger: Math.min(100, Math.max(0, currentUser.petHunger + hunger)),
      petThirst: Math.min(100, Math.max(0, currentUser.petThirst + thirst)),
      petRest: Math.min(100, Math.max(0, currentUser.petRest + rest)),
      petExp: newExp,
      petLevel: newLevel,
      moodCoins: currentUser.moodCoins + coins,
      petSleepUntil: sleepUntil !== undefined ? sleepUntil : currentUser.petSleepUntil,
      petEmoji: newEmoji || currentUser.petEmoji,
      petHasBeenChosen: markChosen !== undefined ? markChosen : currentUser.petHasBeenChosen,
      petLastUpdate: Date.now(),
      gameCooldowns: gameCooldownId ? { ...currentUser.gameCooldowns, [gameCooldownId]: Date.now() + 60000 } : currentUser.gameCooldowns
    });
  };

  const handleMessageReaction = (msgId: string, emoji: string) => {
    setAllMessages(prev => prev.map(m => {
      if (m.id === msgId) {
        const reactions = m.reactions || [];
        const newReactions = reactions.includes(emoji) 
          ? reactions.filter(r => r !== emoji) 
          : [...reactions, emoji];

        if (!reactions.includes(emoji) && m.sender !== currentUser?.username) {
           addNotification(m.sender, 'reaction', emoji, msgId);
        }

        return { ...m, reactions: newReactions };
      }
      return m;
    }));
  };

  const onLogin = (user: User) => {
    setCurrentUser(user);
    setActiveSection('Home'); // Automatic teleport to Home section
    setViewingUsername(user.username);
  };

  if (isAppStarting) return <LoadingScreen />;
  if (!currentUser) return <AuthScreen onLogin={onLogin} />;

  return (
    <div style={{'--theme-color': currentUser.profileColor || '#e21b3c'} as React.CSSProperties} className={`h-screen max-h-screen overflow-hidden flex flex-col md:flex-row ${isDarkMode ? 'bg-[#0f0f0f] text-white' : 'bg-[#f7f8fa] text-slate-900'} transition-colors duration-300`}>
      <style>{`
        :root { --theme-color: ${currentUser.profileColor || '#e21b3c'}; }
        .kahoot-button-custom { background-color: var(--theme-color); border-bottom: 4px solid rgba(0,0,0,0.3); }
        .text-custom { color: var(--theme-color); }
        .bg-custom { background-color: var(--theme-color); }
        .border-custom { border-color: var(--theme-color); }
      `}</style>

      <AnimatePresence>
        {isMoodModalOpen && (
          <MoodCheckIn 
            onSubmit={(m) => {
              const today = new Date().toDateString();
              setCurrentUser({
                ...currentUser,
                moodStreak: currentUser.lastMoodDate === today ? currentUser.moodStreak : (currentUser.moodStreak || 0) + 1,
                lastMoodDate: today,
                moodHistory: [...(currentUser.moodHistory || []), { date: today, mood: m, score: MOOD_SCORES[m || 'Normal'] }]
              });
              setIsMoodModalOpen(false);
            }} 
            isDarkMode={isDarkMode} 
          />
        )}
      </AnimatePresence>

      <Sidebar activeSection={activeSection} onNavigate={(s) => { setActiveSection(s); if(s === 'Profile') setViewingUsername(currentUser.username); }} isDarkMode={isDarkMode} user={currentUser} unreadMessages={allMessages.filter(m => m.recipient === currentUser.username && !m.read).length} unreadNotifications={notifications.filter(n => n.recipient === currentUser.username && !n.read).length} />

      <main className="flex-1 flex flex-col relative pt-16 pb-20 md:pt-0 md:pb-0 h-full overflow-hidden">
        <div className="flex-1 overflow-y-auto fading-scrollbar p-4 md:p-8">
          <motion.div key={activeSection + (activeSection === 'Profile' ? viewingUsername : '')} initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} className="max-w-5xl mx-auto">
            {activeSection === 'Home' && <HomeSection user={currentUser} posts={allPosts} isDarkMode={isDarkMode} />}
            {activeSection === 'Mood' && <MoodSection 
              user={currentUser} posts={allPosts} 
              onPost={(c, v) => setAllPosts(prev => [{id: Math.random().toString(36).substr(2, 9), author: currentUser.username, content: c, hearts: 0, comments: [], timestamp: Date.now(), visibility: v}, ...prev])} 
              onHeart={handleHeart} onComment={(pid, t) => {
                if (!currentUser) return;
                setAllPosts(prev => prev.map(p => {
                  if (p.id === pid) {
                    const newComment: Comment = {
                      id: Math.random().toString(36).substr(2, 9),
                      author: currentUser.username,
                      text: t,
                      hearts: 0,
                      timestamp: Date.now(),
                      replies: []
                    };
                    if (p.author !== currentUser.username) addNotification(p.author, 'comment', 'replied to your transmission', p.id);
                    return { ...p, comments: [...p.comments, newComment] };
                  }
                  return p;
                }));
              }} onCommentInteraction={handleCommentInteraction} onRepost={handleRepost} onFollow={handleFollow} onBlock={handleBlock} 
              isDarkMode={isDarkMode} onNavigateToProfile={(u) => {setViewingUsername(u); setActiveSection('Profile');}} onUpdatePet={updatePetStats} 
            />}
            {activeSection === 'Zodiac' && <ZodiacSection isDarkMode={isDarkMode} />}
            {activeSection === 'CityHall' && <CityHallSection isDarkMode={isDarkMode} currentUser={currentUser} messages={allMessages} onSendMessage={(r, t) => setAllMessages([...allMessages, {id: Math.random().toString(36).substr(2, 9), sender: currentUser.username, recipient: r, text: t, timestamp: Date.now(), read: false}])} onReadMessages={(u) => setAllMessages(allMessages.map(m => (m.recipient === currentUser.username && m.sender === u) ? {...m, read: true} : m))} onNavigateToProfile={(u) => {setViewingUsername(u); setActiveSection('Profile');}} onReactToMessage={handleMessageReaction} />}
            {activeSection === 'Notifications' && <NotificationsSection notifications={notifications.filter(n => n.recipient === currentUser.username)} isDarkMode={isDarkMode} onMarkRead={() => setNotifications(notifications.map(n => n.recipient === currentUser.username ? {...n, read: true} : n))} />}
            {activeSection === 'Profile' && profileToView && <ProfileSection 
              user={profileToView} allPosts={allPosts} isDarkMode={isDarkMode} currentUser={currentUser} 
              onEditProfile={(dn, un, pp, ti, bp, pc, bi) => {
                setCurrentUser({...currentUser, displayName: dn, username: un, profilePic: pp, title: ti, profileColor: pc, bio: bi});
                setViewingUsername(un);
              }} 
              onBlock={handleBlock} onFollow={handleFollow} 
            />}
            {activeSection === 'Settings' && <SettingsSection isDarkMode={isDarkMode} onToggleDarkMode={() => setIsDarkMode(!isDarkMode)} onLogout={() => {localStorage.removeItem('mooderia_user'); setCurrentUser(null);}} user={currentUser} onUnblock={(u) => setCurrentUser({...currentUser, blockedUsers: currentUser.blockedUsers.filter(b => b !== u)})} />}
          </motion.div>
        </div>
      </main>
    </div>
  );
};

export default App;

export type Mood = 'Wonderful' | 'Excited' | 'Happy' | 'Normal' | 'Tired' | 'Angry' | 'Flaming' | null;

export interface Badge {
  id: string;
  name: string;
  icon: string;
  description: string;
  threshold: number;
}

export interface User {
  displayName: string;
  username: string;
  email: string;
  password?: string;
  bio?: string;
  followers: string[];
  following: string[];
  friends: string[];
  blockedUsers: string[];
  posts: Post[];
  reposts: Post[];
  moodHistory: { date: string, mood: Mood, score: number }[];
  moodStreak: number;
  lastMoodDate?: string;
  profilePic?: string;
  bannerPic?: string;
  profileColor?: string;
  title?: string;
  likesReceived: number;
  // Mood Pet Stats
  petName: string;
  moodCoins: number;
  petEmoji: string;
  petHunger: number; // 0-100
  petThirst: number; // 0-100
  petRest: number;   // 0-100
  petLevel: number;
  petExp: number;
  petHasBeenChosen: boolean;
  petLastUpdate: number; // timestamp
  petSleepUntil: number | null; // timestamp
  gameCooldowns: Record<string, number>; // gameId -> timestamp of when it can be played again
}

export interface MessageReaction {
  emoji: string;
  users: string[]; // List of usernames who used this emoji
}

export interface Message {
  id: string;
  sender: string;
  recipient: string; // For DMs, this is the username. For Groups, this is the groupId.
  text: string;
  timestamp: number;
  read: boolean;
  reactions?: MessageReaction[];
  isGroup?: boolean;
  recipients?: string[]; // List of all usernames in the group (if group chat)
  groupName?: string;
}

export interface Notification {
  id: string;
  type: 'heart' | 'comment' | 'repost' | 'tier' | 'achievement' | 'follow' | 'comment_heart' | 'reply' | 'reaction';
  fromUser: string;
  recipient: string; 
  postId?: string;
  timestamp: number;
  read: boolean;
  postContentSnippet: string;
}

export interface Post {
  id: string;
  author: string;
  content: string;
  hearts: number;
  comments: Comment[];
  timestamp: number;
  isRepost?: boolean;
  originalAuthor?: string;
  visibility: 'global' | 'circle';
}

export interface Comment {
  id: string;
  author: string;
  text: string;
  hearts: number;
  timestamp: number;
  replies: Comment[];
}

export type Section = 'Home' | 'Mood' | 'Zodiac' | 'CityHall' | 'Profile' | 'Settings' | 'Notifications';

export interface ZodiacInfo {
  name: string;
  dates: string;
  description: string;
  history: string;
  symbol: string;
}

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { User, Mood, Section, Post, Comment, Message, Notification, MessageReaction } from './types';
import Sidebar from './components/Sidebar';
import MoodCheckIn from './components/MoodCheckIn';
import HomeSection from './sections/HomeSection';
import MoodSection from './sections/MoodSection';
import ZodiacSection from './sections/ZodiacSection';
import CityHallSection from './sections/CityHallSection';
import ProfileSection from './sections/ProfileSection';
import SettingsSection from './sections/SettingsSection';
import NotificationsSection from './sections/NotificationsSection';
import AuthScreen from './sections/AuthScreen';
import LoadingScreen from './components/LoadingScreen';
import { getExpNeeded, MOOD_SCORES } from './constants';
import { Trophy, Share2, X } from 'lucide-react';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [activeSection, setActiveSection] = useState<Section>('Home');
  const [viewingUsername, setViewingUsername] = useState<string | null>(null);
  const [isMoodModalOpen, setIsMoodModalOpen] = useState(false);
  const [isDarkMode, setIsDarkMode] = useState(false); 
  const [isAppStarting, setIsAppStarting] = useState(true);
  const [levelUpInfo, setLevelUpInfo] = useState<{ level: number } | null>(null);
  const [globalUpdateToggle, setGlobalUpdateToggle] = useState(0);

  const [allPosts, setAllPosts] = useState<Post[]>([]);
  const [allMessages, setAllMessages] = useState<Message[]>([]);
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);

  const profileToView = useMemo(() => {
    if (!viewingUsername) return null;
    if (currentUser && viewingUsername === currentUser.username) return currentUser;
    const allUsers: User[] = JSON.parse(localStorage.getItem('mooderia_all_users') || '[]');
    return allUsers.find(u => u.username === viewingUsername) || null;
  }, [viewingUsername, currentUser, globalUpdateToggle]);

  const addNotification = useCallback((recipient: string, type: Notification['type'], snippet: string, postId: string = '') => {
    if (!currentUser || recipient === currentUser.username) {
      if (type !== 'achievement' && type !== 'tier') return;
    }
    const newNotif: Notification = {
      id: Math.random().toString(36).substr(2, 9),
      fromUser: currentUser?.username || 'Metropolis',
      recipient,
      type,
      postId,
      timestamp: Date.now(),
      read: false,
      postContentSnippet: snippet
    };
    setNotifications(prev => [...prev, newNotif]);
  }, [currentUser]);

  useEffect(() => {
    const savedUser = localStorage.getItem('mooderia_user');
    const savedPosts = localStorage.getItem('mooderia_posts') || '[]';
    const savedMessages = localStorage.getItem('mooderia_messages') || '[]';
    const savedNotifications = localStorage.getItem('mooderia_notifications') || '[]';
    const savedTheme = localStorage.getItem('mooderia_theme');

    if (savedUser) {
      const user: User = JSON.parse(savedUser);
      const now = Date.now();
      const elapsedMinutes = Math.floor((now - (user.petLastUpdate || now)) / 60000);
      if (elapsedMinutes > 0) {
        user.petHunger = Math.max(0, user.petHunger - elapsedMinutes * 0.15);
        user.petThirst = Math.max(0, user.petThirst - elapsedMinutes * 0.2);
        if (!user.petSleepUntil || user.petSleepUntil < now) {
          user.petRest = Math.max(0, user.petRest - elapsedMinutes * 0.1);
        }
        user.petLastUpdate = now;
      }
      setCurrentUser(user);
    }

    setAllPosts(JSON.parse(savedPosts));
    setAllMessages(JSON.parse(savedMessages));
    setNotifications(JSON.parse(savedNotifications));
    if (savedTheme === 'dark') setIsDarkMode(true);
    setIsLoaded(true);

    const timer = setTimeout(() => setIsAppStarting(false), 2000);
    return () => clearTimeout(timer);
  }, []);

  useEffect(() => {
    if (!isAppStarting && currentUser) {
      const todayStr = new Date().toDateString();
      if (currentUser.lastMoodDate !== todayStr) {
        setIsMoodModalOpen(true);
      }
    }
  }, [isAppStarting, currentUser?.username, currentUser?.lastMoodDate]);

  useEffect(() => {
    if (!isLoaded) return;
    if (currentUser) {
      localStorage.setItem('mooderia_user', JSON.stringify(currentUser));
      const allUsers: User[] = JSON.parse(localStorage.getItem('mooderia_all_users') || '[]');
      const idx = allUsers.findIndex(u => u.username === currentUser.username);
      if (idx > -1) {
        allUsers[idx] = currentUser;
        localStorage.setItem('mooderia_all_users', JSON.stringify(allUsers));
      }
    }
    localStorage.setItem('mooderia_posts', JSON.stringify(allPosts));
    localStorage.setItem('mooderia_messages', JSON.stringify(allMessages));
    localStorage.setItem('mooderia_notifications', JSON.stringify(notifications));
    localStorage.setItem('mooderia_theme', isDarkMode ? 'dark' : 'light');
  }, [currentUser, allPosts, allMessages, notifications, isDarkMode, isLoaded]);

  const handleFollow = (targetUsername: string) => {
    if (!currentUser) return;
    const isFollowing = currentUser.following.includes(targetUsername);
    const updatedFollowing = isFollowing ? currentUser.following.filter(u => u !== targetUsername) : [...currentUser.following, targetUsername];
    setCurrentUser({ ...currentUser, following: updatedFollowing });
    const allUsers: User[] = JSON.parse(localStorage.getItem('mooderia_all_users') || '[]');
    const targetIdx = allUsers.findIndex(u => u.username === targetUsername);
    if (targetIdx > -1) {
      const targetUser = { ...allUsers[targetIdx] };
      targetUser.followers = isFollowing ? targetUser.followers.filter(u => u !== currentUser.username) : [...targetUser.followers, currentUser.username];
      allUsers[targetIdx] = targetUser;
      localStorage.setItem('mooderia_all_users', JSON.stringify(allUsers));
      if (!isFollowing) addNotification(targetUsername, 'follow', 'started following you!');
    }
    setGlobalUpdateToggle(t => t + 1);
  };

  const handleHeart = (postId: string) => {
    if (!currentUser) return;
    setAllPosts(prev => prev.map(p => {
      if (p.id === postId) {
        if (p.author !== currentUser.username) addNotification(p.author, 'heart', 'liked your expression', p.id);
        return { ...p, hearts: p.hearts + 1 };
      }
      return p;
    }));
  };

  const handleCommentInteraction = (postId: string, commentId: string, action: 'heart' | 'reply', replyText?: string) => {
    if (!currentUser) return;
    setAllPosts(prev => prev.map(p => {
      if (p.id === postId) {
        const updateNested = (list: Comment[]): Comment[] => {
          return list.map(c => {
            if (c.id === commentId) {
              if (action === 'heart') {
                if (c.author !== currentUser.username) addNotification(c.author, 'comment_heart', 'liked your frequency', postId);
                return { ...c, hearts: c.hearts + 1 };
              }
              if (action === 'reply' && replyText) {
                const newRep: Comment = {
                  id: Math.random().toString(36).substr(2, 9),
                  author: currentUser.username,
                  text: replyText,
                  hearts: 0,
                  timestamp: Date.now(),
                  replies: []
                };
                if (c.author !== currentUser.username) addNotification(c.author, 'reply', 'responded to your frequency', postId);
                return { ...c, replies: [...c.replies, newRep] };
              }
            }
            if (c.replies.length > 0) return { ...c, replies: updateNested(c.replies) };
            return c;
          });
        };
        return { ...p, comments: updateNested(p.comments) };
      }
      return p;
    }));
  };

  const handleRepost = (p: Post) => {
    if (!currentUser) return;
    const newRepost: Post = {
      id: Math.random().toString(36).substr(2, 9),
      author: currentUser.username,
      content: p.content,
      hearts: 0,
      comments: [],
      timestamp: Date.now(),
      isRepost: true,
      originalAuthor: p.author,
      visibility: 'global'
    };
    setAllPosts(prev => [newRepost, ...prev]);
    if (p.author !== currentUser.username) addNotification(p.author, 'repost', 'echoed your transmission', p.id);
  };

  const handleBlock = (targetUsername: string) => {
    if (!currentUser) return;
    const updatedFollowing = currentUser.following.filter(u => u !== targetUsername);
    const updatedBlocked = [...currentUser.blockedUsers, targetUsername];
    setCurrentUser({ ...currentUser, following: updatedFollowing, blockedUsers: updatedBlocked });
    const allUsers: User[] = JSON.parse(localStorage.getItem('mooderia_all_users') || '[]');
    const targetIdx = allUsers.findIndex(u => u.username === targetUsername);
    if (targetIdx > -1) {
      const targetUser = { ...allUsers[targetIdx] };
      targetUser.followers = targetUser.followers.filter(u => u !== currentUser.username);
      targetUser.following = targetUser.following.filter(u => u !== currentUser.username);
      allUsers[targetIdx] = targetUser;
      const currentIdxGlobal = allUsers.findIndex(u => u.username === currentUser.username);
      if (currentIdxGlobal > -1) allUsers[currentIdxGlobal].followers = allUsers[currentIdxGlobal].followers.filter(u => u !== targetUsername);
      localStorage.setItem('mooderia_all_users', JSON.stringify(allUsers));
    }
    setViewingUsername(currentUser.username);
    setActiveSection('Home');
    setGlobalUpdateToggle(t => t + 1);
  };

  const updatePetStats = (hunger: number, thirst: number, rest: number, coins: number, exp: number = 0, sleepUntil: number | null = null, newEmoji?: string, markChosen?: boolean, newName?: string, gameCooldownId?: string) => {
    if (!currentUser) return;
    let newLevel = currentUser.petLevel;
    let newExp = currentUser.petExp + exp;
    let leveledUp = false;
    while (newExp >= getExpNeeded(newLevel)) { newExp -= getExpNeeded(newLevel); newLevel += 1; leveledUp = true; }
    if (leveledUp) addNotification(currentUser.username, 'achievement', `Your Guardian ${newName || currentUser.petName} reached Level ${newLevel}!`);
    setCurrentUser({
      ...currentUser,
      petName: newName || currentUser.petName,
      petHunger: Math.min(100, Math.max(0, currentUser.petHunger + hunger)),
      petThirst: Math.min(100, Math.max(0, currentUser.petThirst + thirst)),
      petRest: Math.min(100, Math.max(0, currentUser.petRest + rest)),
      petExp: newExp,
      petLevel: newLevel,
      moodCoins: currentUser.moodCoins + coins,
      petSleepUntil: sleepUntil !== undefined ? sleepUntil : currentUser.petSleepUntil,
      petEmoji: newEmoji || currentUser.petEmoji,
      petHasBeenChosen: markChosen !== undefined ? markChosen : currentUser.petHasBeenChosen,
      petLastUpdate: Date.now(),
      gameCooldowns: gameCooldownId ? { ...currentUser.gameCooldowns, [gameCooldownId]: Date.now() + 60000 } : currentUser.gameCooldowns
    });
  };

  const handleMessageReaction = (msgId: string, emoji: string) => {
    if (!currentUser) return;
    setAllMessages(prev => prev.map(m => {
      if (m.id === msgId) {
        let reactions = [...(m.reactions || [])];
        const existingReaction = reactions.find(r => r.users.includes(currentUser.username));
        if (existingReaction) {
          if (existingReaction.emoji === emoji) {
            existingReaction.users = existingReaction.users.filter(u => u !== currentUser.username);
            if (existingReaction.users.length === 0) reactions = reactions.filter(r => r.emoji !== emoji);
          } else {
            existingReaction.users = existingReaction.users.filter(u => u !== currentUser.username);
            if (existingReaction.users.length === 0) reactions = reactions.filter(r => r.emoji !== existingReaction.emoji);
            const targetReaction = reactions.find(r => r.emoji === emoji);
            if (targetReaction) targetReaction.users.push(currentUser.username);
            else reactions.push({ emoji, users: [currentUser.username] });
            if (m.sender !== currentUser.username) addNotification(m.sender, 'reaction', emoji, msgId);
          }
        } else {
          const targetReaction = reactions.find(r => r.emoji === emoji);
          if (targetReaction) targetReaction.users.push(currentUser.username);
          else reactions.push({ emoji, users: [currentUser.username] });
          if (m.sender !== currentUser.username) addNotification(m.sender, 'reaction', emoji, msgId);
        }
        return { ...m, reactions };
      }
      return m;
    }));
  };

  const onLogin = (user: User) => {
    setCurrentUser(user);
    setActiveSection('Home');
    setViewingUsername(user.username);
  };

  const handleSendMessage = (recipient: string, text: string, options?: { isGroup?: boolean, recipients?: string[], groupName?: string }) => {
    if (!currentUser) return;
    const newMsg: Message = {
      id: Math.random().toString(36).substr(2, 9),
      sender: currentUser.username,
      recipient,
      text,
      timestamp: Date.now(),
      read: false,
      isGroup: options?.isGroup,
      recipients: options?.recipients,
      groupName: options?.groupName
    };
    setAllMessages(prev => [...prev, newMsg]);
  };

  if (isAppStarting) return <LoadingScreen />;
  if (!currentUser) return <AuthScreen onLogin={onLogin} />;

  return (
    <div style={{'--theme-color': currentUser.profileColor || '#e21b3c'} as React.CSSProperties} className={`h-screen max-h-screen overflow-hidden flex flex-col md:flex-row ${isDarkMode ? 'bg-[#0f0f0f] text-white' : 'bg-[#f7f8fa] text-slate-900'} transition-colors duration-300`}>
      <style>{`
        :root { --theme-color: ${currentUser.profileColor || '#e21b3c'}; }
        .kahoot-button-custom { background-color: var(--theme-color); border-bottom: 4px solid rgba(0,0,0,0.3); }
        .text-custom { color: var(--theme-color); }
        .bg-custom { background-color: var(--theme-color); }
        .border-custom { border-color: var(--theme-color); }
      `}</style>
      <AnimatePresence>{isMoodModalOpen && <MoodCheckIn onSubmit={(m) => { const today = new Date().toDateString(); setCurrentUser({ ...currentUser, moodStreak: currentUser.lastMoodDate === today ? currentUser.moodStreak : (currentUser.moodStreak || 0) + 1, lastMoodDate: today, moodHistory: [...(currentUser.moodHistory || []), { date: today, mood: m, score: MOOD_SCORES[m || 'Normal'] }] }); setIsMoodModalOpen(false); }} isDarkMode={isDarkMode} />}</AnimatePresence>
      <Sidebar activeSection={activeSection} onNavigate={(s) => { setActiveSection(s); if(s === 'Profile') setViewingUsername(currentUser.username); }} isDarkMode={isDarkMode} user={currentUser} unreadMessages={allMessages.filter(m => m.recipient === currentUser.username && !m.read).length} unreadNotifications={notifications.filter(n => n.recipient === currentUser.username && !n.read).length} />
      <main className="flex-1 flex flex-col relative pt-16 pb-20 md:pt-0 md:pb-0 h-full overflow-hidden">
        <div className="flex-1 overflow-y-auto fading-scrollbar p-4 md:p-8">
          <motion.div key={activeSection + (activeSection === 'Profile' ? viewingUsername : '')} initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} className="max-w-5xl mx-auto">
            {activeSection === 'Home' && <HomeSection user={currentUser} posts={allPosts} isDarkMode={isDarkMode} />}
            {activeSection === 'Mood' && <MoodSection user={currentUser} posts={allPosts} onPost={(c, v) => setAllPosts(prev => [{id: Math.random().toString(36).substr(2, 9), author: currentUser.username, content: c, hearts: 0, comments: [], timestamp: Date.now(), visibility: v}, ...prev])} onHeart={handleHeart} onComment={(pid, t) => setAllPosts(prev => prev.map(p => p.id === pid ? { ...p, comments: [...p.comments, { id: Math.random().toString(36).substr(2, 9), author: currentUser.username, text: t, hearts: 0, timestamp: Date.now(), replies: [] }] } : p))} onCommentInteraction={handleCommentInteraction} onRepost={handleRepost} onFollow={handleFollow} onBlock={handleBlock} isDarkMode={isDarkMode} onNavigateToProfile={(u) => {setViewingUsername(u); setActiveSection('Profile');}} onUpdatePet={updatePetStats} />}
            {activeSection === 'Zodiac' && <ZodiacSection isDarkMode={isDarkMode} />}
            {activeSection === 'CityHall' && <CityHallSection isDarkMode={isDarkMode} currentUser={currentUser} messages={allMessages} onSendMessage={handleSendMessage} onReadMessages={(u) => setAllMessages(prev => prev.map(m => (m.recipient === currentUser.username && m.sender === u) ? {...m, read: true} : m))} onNavigateToProfile={(u) => {setViewingUsername(u); setActiveSection('Profile');}} onReactToMessage={handleMessageReaction} />}
            {activeSection === 'Notifications' && <NotificationsSection notifications={notifications.filter(n => n.recipient === currentUser.username)} isDarkMode={isDarkMode} onMarkRead={() => setNotifications(notifications.map(n => n.recipient === currentUser.username ? {...n, read: true} : n))} />}
            {activeSection === 'Profile' && profileToView && <ProfileSection user={profileToView} allPosts={allPosts} isDarkMode={isDarkMode} currentUser={currentUser} onEditProfile={(dn, un, pp, ti, bp, pc, bi) => { setCurrentUser({...currentUser, displayName: dn, username: un, profilePic: pp, title: ti, profileColor: pc, bio: bi}); setViewingUsername(un); }} onBlock={handleBlock} onFollow={handleFollow} />}
            {activeSection === 'Settings' && <SettingsSection isDarkMode={isDarkMode} onToggleDarkMode={() => setIsDarkMode(!isDarkMode)} onLogout={() => {localStorage.removeItem('mooderia_user'); setCurrentUser(null);}} user={currentUser} onUnblock={(u) => setCurrentUser({...currentUser, blockedUsers: currentUser.blockedUsers.filter(b => b !== u)})} />}
          </motion.div>
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Send, Users, Search, MessageSquare, ArrowLeft, ShieldCheck, Check, CheckCheck, Clock, Smile, Plus, X, UserGroupIcon, ShieldAlert } from 'lucide-react';
import { User, Message, MessageReaction } from '../types';

interface CityHallSectionProps {
  isDarkMode: boolean;
  currentUser: User;
  messages: Message[];
  onSendMessage: (recipient: string, text: string, options?: { isGroup?: boolean, recipients?: string[], groupName?: string }) => void;
  onReadMessages: (withUsername: string) => void;
  onNavigateToProfile: (username: string) => void;
  onReactToMessage: (msgId: string, emoji: string) => void;
}

const REACTION_EMOJIS = ['❤️', '😂', '😮', '😢', '🔥', '👍'];

const CityHallSection: React.FC<CityHallSectionProps> = ({ isDarkMode, currentUser, messages, onSendMessage, onReadMessages, onNavigateToProfile, onReactToMessage }) => {
  const [input, setInput] = useState('');
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedCitizen, setSelectedCitizen] = useState<{ username: string, displayName: string, profilePic?: string, isGroup?: boolean, recipients?: string[] } | null>(null);
  const [reactionPickerMsgId, setReactionPickerMsgId] = useState<string | null>(null);
  const [isCreatingGroup, setIsCreatingGroup] = useState(false);
  const [groupName, setGroupName] = useState('');
  const [selectedForGroup, setSelectedForGroup] = useState<string[]>([]);
  const [viewingReacters, setViewingReacters] = useState<MessageReaction | null>(null);
  const chatEndRef = useRef<HTMLDivElement>(null);

  const allUsers: User[] = useMemo(() => JSON.parse(localStorage.getItem('mooderia_all_users') || '[]'), []);
  const usersWhoBlockedMe = useMemo(() => allUsers.filter(u => u.blockedUsers.includes(currentUser.username)).map(u => u.username), [allUsers, currentUser.username]);

  const filteredCitizens = useMemo(() => {
    if (!searchTerm.trim()) return [];
    return allUsers.filter(u => 
      u.username !== currentUser.username && 
      !currentUser.blockedUsers.includes(u.username) &&
      !usersWhoBlockedMe.includes(u.username) &&
      (u.displayName.toLowerCase().includes(searchTerm.toLowerCase()) || 
       u.username.toLowerCase().includes(searchTerm.toLowerCase()))
    );
  }, [searchTerm, allUsers, currentUser.username, currentUser.blockedUsers, usersWhoBlockedMe]);

  const chats = useMemo(() => {
    const list: any[] = [];
    const processedDms = new Set<string>();
    const processedGroups = new Set<string>();

    messages.forEach(m => {
      if (m.isGroup && m.recipient && !processedGroups.has(m.recipient)) {
        processedGroups.add(m.recipient);
        list.push({ 
          username: m.recipient, 
          displayName: m.groupName || 'Unnamed Group', 
          isGroup: true, 
          recipients: m.recipients 
        });
      } else if (!m.isGroup) {
        const other = m.sender === currentUser.username ? m.recipient : m.sender;
        if (!processedDms.has(other)) {
          processedDms.add(other);
          const userObj = allUsers.find(u => u.username === other);
          if (userObj && !currentUser.blockedUsers.includes(other) && !usersWhoBlockedMe.includes(other)) {
            list.push({ 
              username: other, 
              displayName: userObj.displayName, 
              profilePic: userObj.profilePic, 
              isGroup: false 
            });
          }
        }
      }
    });
    return list;
  }, [messages, allUsers, currentUser.username, currentUser.blockedUsers, usersWhoBlockedMe]);

  const chatMessages = useMemo(() => {
    if (!selectedCitizen) return [];
    if (selectedCitizen.isGroup) {
      return messages.filter(m => m.isGroup && m.recipient === selectedCitizen.username)
        .sort((a, b) => a.timestamp - b.timestamp);
    }
    return messages.filter(m => 
      !m.isGroup &&
      ((m.sender === currentUser.username && m.recipient === selectedCitizen.username) ||
      (m.sender === selectedCitizen.username && m.recipient === currentUser.username))
    ).sort((a, b) => a.timestamp - b.timestamp);
  }, [messages, selectedCitizen, currentUser.username]);

  const groupedMessages = useMemo(() => {
    const groups: { dateLabel: string, items: Message[] }[] = [];
    chatMessages.forEach(msg => {
      const date = new Date(msg.timestamp);
      const today = new Date();
      const yesterday = new Date();
      yesterday.setDate(yesterday.getDate() - 1);
      let label = date.toLocaleDateString(undefined, { day: 'numeric', month: 'long', year: 'numeric' });
      if (date.toDateString() === today.toDateString()) label = "Today";
      else if (date.toDateString() === yesterday.toDateString()) label = "Yesterday";
      const lastGroup = groups[groups.length - 1];
      if (lastGroup && lastGroup.dateLabel === label) lastGroup.items.push(msg);
      else groups.push({ dateLabel: label, items: [msg] });
    });
    return groups;
  }, [chatMessages]);

  useEffect(() => {
    if (selectedCitizen && !selectedCitizen.isGroup) onReadMessages(selectedCitizen.username);
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [selectedCitizen, messages.length]);

  const handleSend = () => {
    if (!input.trim() || !selectedCitizen) return;
    onSendMessage(selectedCitizen.username, input, { 
      isGroup: selectedCitizen.isGroup, 
      recipients: selectedCitizen.recipients, 
      groupName: selectedCitizen.displayName 
    });
    setInput('');
  };

  const handleCreateGroup = () => {
    if (!groupName.trim() || selectedForGroup.length < 1) return;
    const groupId = 'group_' + Math.random().toString(36).substr(2, 9);
    const recipients = [...selectedForGroup, currentUser.username];
    onSendMessage(groupId, `CITIZEN TERMINAL: Group "${groupName}" initialized.`, { isGroup: true, recipients, groupName });
    setSelectedCitizen({ username: groupId, displayName: groupName, isGroup: true, recipients });
    setIsCreatingGroup(false);
    setGroupName('');
    setSelectedForGroup([]);
  };

  return (
    <div className="flex flex-col h-full overflow-hidden gap-4">
      <div className="flex justify-between items-center px-2 shrink-0">
        <h2 className={`text-2xl md:text-3xl font-black italic uppercase tracking-tighter ${isDarkMode ? 'text-white' : 'text-slate-900'}`}>Citizen Hub</h2>
        <button onClick={() => setIsCreatingGroup(true)} className="kahoot-button-blue p-3 rounded-xl text-white font-black flex items-center gap-2 shadow-lg hover:scale-105 transition-all">
          <Plus size={20} /> <span className="hidden sm:inline text-xs">NEW GROUP</span>
        </button>
      </div>

      <div className={`flex-1 flex flex-col md:flex-row rounded-[2.5rem] ${isDarkMode ? 'bg-slate-800' : 'bg-white'} shadow-2xl overflow-hidden border-4 border-gray-100 dark:border-slate-700 min-h-0`}>
        {/* Sidebar */}
        <div className={`w-full md:w-72 lg:w-80 border-r ${isDarkMode ? 'border-slate-700' : 'border-gray-100'} flex flex-col ${selectedCitizen ? 'hidden md:flex' : 'flex'}`}>
          <div className="p-4 border-b border-gray-100 dark:border-slate-700 shrink-0">
            <div className="relative">
              <input type="text" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} placeholder="Search Citizens..." className={`w-full px-10 py-3 rounded-xl text-xs font-bold border-2 outline-none focus:border-blue-500 ${isDarkMode ? 'bg-slate-700 border-slate-600 text-white' : 'bg-gray-50 border-gray-200'}`} />
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 opacity-30 text-white/50" size={16} />
            </div>
          </div>
          <div className="flex-1 overflow-y-auto fading-scrollbar p-2 space-y-1">
            {(searchTerm.trim() ? filteredCitizens.map(u => ({ username: u.username, displayName: u.displayName, profilePic: u.profilePic, isGroup: false })) : chats).map(u => (
              <button key={u.username} onClick={() => setSelectedCitizen(u)} className={`w-full p-3 rounded-xl flex items-center gap-3 transition-all ${selectedCitizen?.username === u.username ? 'bg-blue-600 text-white shadow-lg' : 'hover:bg-gray-50 dark:hover:bg-slate-700 text-slate-800 dark:text-white'}`}>
                <div className="w-10 h-10 rounded-xl bg-blue-100 dark:bg-slate-600 flex items-center justify-center font-black overflow-hidden shadow-sm shrink-0">
                  {u.isGroup ? <Users size={20} className="text-blue-600 dark:text-blue-300" /> : (u.profilePic ? <img src={u.profilePic} className="w-full h-full object-cover" /> : u.displayName[0].toUpperCase())}
                </div>
                <div className="text-left truncate flex-1">
                  <p className="font-black text-xs truncate uppercase tracking-tight">{u.displayName}</p>
                  <p className={`text-[9px] font-bold ${selectedCitizen?.username === u.username ? 'text-white/60' : 'opacity-40'}`}>@{u.username}</p>
                </div>
              </button>
            ))}
          </div>
        </div>

        {/* Chat Area */}
        <div className={`flex-1 flex flex-col min-h-0 ${!selectedCitizen ? 'hidden md:flex' : 'flex'}`}>
          {selectedCitizen ? (
            <>
              <div className={`p-4 border-b ${isDarkMode ? 'bg-slate-700/50 border-slate-700' : 'bg-gray-50 border-gray-100'} flex items-center justify-between shrink-0`}>
                <div className="flex items-center gap-4">
                  <button onClick={() => setSelectedCitizen(null)} className="md:hidden p-2 rounded-xl hover:bg-gray-200"><ArrowLeft size={20} /></button>
                  <div className="flex items-center gap-3">
                    <div className="w-10 h-10 rounded-xl bg-blue-600 text-white flex items-center justify-center font-black shadow-md overflow-hidden">
                      {selectedCitizen.isGroup ? <Users size={24} /> : (selectedCitizen.profilePic ? <img src={selectedCitizen.profilePic} className="w-full h-full object-cover" /> : selectedCitizen.displayName[0])}
                    </div>
                    <div className="text-left">
                      <p className="font-black text-sm text-slate-800 dark:text-white uppercase italic">{selectedCitizen.displayName}</p>
                      <p className="text-[10px] font-bold opacity-40 uppercase tracking-widest">{selectedCitizen.isGroup ? `${selectedCitizen.recipients?.length} Members` : 'Active Signal'}</p>
                    </div>
                  </div>
                </div>
              </div>

              <div className="flex-1 overflow-y-auto p-4 md:p-6 space-y-6 fading-scrollbar">
                {groupedMessages.map(group => (
                  <div key={group.dateLabel} className="space-y-6">
                    <div className="flex items-center gap-4 py-2">
                      <div className="h-px flex-1 bg-black/5 dark:bg-white/5"></div>
                      <span className="text-[10px] font-black uppercase opacity-30 tracking-[0.2em]">{group.dateLabel}</span>
                      <div className="h-px flex-1 bg-black/5 dark:bg-white/5"></div>
                    </div>
                    {group.items.map(m => {
                      const isMe = m.sender === currentUser.username;
                      const senderName = allUsers.find(u => u.username === m.sender)?.displayName || m.sender;
                      return (
                        <div key={m.id} className={`flex ${isMe ? 'justify-end' : 'justify-start'} group relative`}>
                          <div className={`max-w-[80%] md:max-w-[60%] space-y-1`}>
                            {selectedCitizen.isGroup && !isMe && <p className="text-[8px] font-black uppercase opacity-40 mb-1 ml-1 tracking-widest">{senderName}</p>}
                            <div className={`relative px-5 py-3 rounded-2xl font-bold text-sm shadow-sm ${isMe ? 'bg-blue-600 text-white rounded-tr-none' : isDarkMode ? 'bg-slate-700 text-white rounded-tl-none' : 'bg-gray-100 text-slate-800 rounded-tl-none'}`}>
                              {m.text}

                              {/* Reactions display */}
                              {m.reactions && m.reactions.length > 0 && (
                                <div className={`absolute -bottom-3 ${isMe ? 'right-2' : 'left-2'} flex gap-1 bg-white dark:bg-slate-800 rounded-full px-2 py-0.5 shadow-md border border-black/5 cursor-pointer z-10`} onClick={(e) => { e.stopPropagation(); setViewingReacters(m.reactions?.[0] || null); }}>
                                  {m.reactions.map(r => (
                                    <button 
                                      key={r.emoji} 
                                      onClick={(e) => { e.stopPropagation(); setViewingReacters(r); }}
                                      className="flex items-center gap-1 hover:scale-110 transition-transform"
                                    >
                                      <span className="text-xs">{r.emoji}</span>
                                      <span className="text-[8px] font-black">{r.users.length}</span>
                                    </button>
                                  ))}
                                </div>
                              )}

                              {/* Reaction picker trigger */}
                              <button 
                                onClick={() => setReactionPickerMsgId(reactionPickerMsgId === m.id ? null : m.id)}
                                className={`absolute ${isMe ? '-left-10' : '-right-10'} top-1/2 -translate-y-1/2 opacity-0 group-hover:opacity-100 transition-opacity p-2 text-slate-400 hover:text-blue-500`}
                              >
                                <Smile size={18} />
                              </button>

                              {/* Reaction Picker Popover */}
                              <AnimatePresence>
                                {reactionPickerMsgId === m.id && (
                                  <motion.div 
                                    initial={{ scale: 0.8, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} exit={{ scale: 0.8, opacity: 0 }}
                                    className={`absolute z-20 ${isMe ? 'right-0 -top-12' : 'left-0 -top-12'} bg-white dark:bg-slate-800 border-4 border-black/5 rounded-full p-1.5 flex gap-1.5 shadow-2xl`}
                                  >
                                    {REACTION_EMOJIS.map(emoji => {
                                      const isReacted = m.reactions?.find(r => r.emoji === emoji && r.users.includes(currentUser.username));
                                      return (
                                        <button 
                                          key={emoji} 
                                          onClick={() => { onReactToMessage(m.id, emoji); setReactionPickerMsgId(null); }}
                                          className={`hover:scale-125 transition-transform p-1.5 rounded-full ${isReacted ? 'bg-blue-100 dark:bg-blue-900/30' : ''}`}
                                        >
                                          {emoji}
                                        </button>
                                      );
                                    })}
                                  </motion.div>
                                )}
                              </AnimatePresence>
                            </div>

                            <div className={`flex items-center gap-2 text-[9px] font-black uppercase opacity-30 ${isMe ? 'justify-end' : 'justify-start'}`}>
                              <Clock size={10} /> {new Date(m.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                              {isMe && (m.read ? <CheckCheck size={12} className="text-blue-400" /> : <Check size={12} />)}
                            </div>
                          </div>
                        </div>
                      );
                    })}
                  </div>
                ))}
                <div ref={chatEndRef} />
              </div>

              <div className="p-4 md:p-6 border-t border-gray-100 dark:border-slate-700 shrink-0">
                <div className={`flex items-center gap-3 p-2 rounded-2xl border-4 ${isDarkMode ? 'bg-slate-700/50 border-slate-700' : 'bg-gray-50 border-gray-200'} focus-within:border-blue-500/50 transition-all`}>
                  <input 
                    type="text" value={input} 
                    onChange={(e) => setInput(e.target.value)} 
                    onKeyPress={(e) => e.key === 'Enter' && handleSend()} 
                    placeholder="Broadcast frequency..." 
                    className="flex-1 bg-transparent px-4 py-2 font-bold text-sm outline-none dark:text-white"
                  />
                  <button onClick={handleSend} className="bg-blue-600 text-white p-3 rounded-xl shadow-lg hover:scale-105 active:scale-95 transition-all"><Send size={20} /></button>
                </div>
              </div>
            </>
          ) : (
            <div className="flex-1 flex flex-col items-center justify-center p-10 text-center opacity-30">
              <MessageSquare size={80} className="mb-6 text-slate-400" />
              <h3 className="text-2xl font-black italic uppercase tracking-tighter text-slate-800 dark:text-white">Citizen Terminal</h3>
              <p className="text-xs font-bold uppercase tracking-[0.2em] mt-2 text-slate-800 dark:text-white">Select a frequency to synchronize transmissions</p>
            </div>
          )}
        </div>
      </div>

      {/* View Reacters Modal */}
      <AnimatePresence>
        {viewingReacters && (
          <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-black/80 backdrop-blur-sm">
            <motion.div initial={{ scale: 0.9, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} className={`w-full max-w-sm rounded-[3rem] p-8 ${isDarkMode ? 'bg-slate-900 border-slate-700' : 'bg-white border-gray-100'} border-4 shadow-2xl`}>
              <div className="flex justify-between items-center mb-6">
                <div className="flex items-center gap-3">
                  <span className="text-3xl">{viewingReacters.emoji}</span>
                  <h3 className="text-xl font-black uppercase italic tracking-tighter">Reacters</h3>
                </div>
                <button onClick={() => setViewingReacters(null)} className="p-2 rounded-full hover:bg-black/5"><X size={24} className="opacity-40" /></button>
              </div>
              <div className="space-y-3 max-h-[40vh] overflow-y-auto fading-scrollbar">
                {viewingReacters.users.map(u => {
                  const userObj = allUsers.find(cu => cu.username === u);
                  return (
                    <div key={u} className="flex items-center gap-3 p-3 rounded-2xl bg-black/5">
                      <div className="w-10 h-10 rounded-xl bg-custom text-white flex items-center justify-center font-black shadow-sm overflow-hidden">
                        {userObj?.profilePic ? <img src={userObj.profilePic} className="w-full h-full object-cover" /> : u[0].toUpperCase()}
                      </div>
                      <div>
                        <p className="font-black text-xs uppercase">{userObj?.displayName || u}</p>
                        <p className="text-[10px] font-bold opacity-40">@{u}</p>
                      </div>
                    </div>
                  );
                })}
              </div>
            </motion.div>
          </div>
        )}
      </AnimatePresence>

      {/* Group Creation Modal */}
      <AnimatePresence>
        {isCreatingGroup && (
          <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-black/80 backdrop-blur-sm">
            <motion.div initial={{ scale: 0.95, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} className={`w-full max-w-lg rounded-[3rem] p-8 ${isDarkMode ? 'bg-slate-900' : 'bg-white'} border-4 border-white/10 shadow-2xl`}>
              <div className="flex justify-between items-center mb-8">
                <h3 className="text-3xl font-black uppercase italic tracking-tighter">Initialize Group</h3>
                <button onClick={() => setIsCreatingGroup(false)} className="bg-black/5 p-2 rounded-full"><X size={24} /></button>
              </div>

              <div className="space-y-6">
                <div className="space-y-2">
                  <p className="text-[10px] font-black uppercase opacity-40 ml-2 tracking-widest">Group Designation</p>
                  <input type="text" value={groupName} onChange={(e) => setGroupName(e.target.value)} placeholder="Echo Squad..." className="w-full p-4 rounded-2xl border-4 bg-black/5 font-black text-lg outline-none focus:border-blue-500" />
                </div>

                <div className="space-y-2">
                  <p className="text-[10px] font-black uppercase opacity-40 ml-2 tracking-widest">Select Citizens ({selectedForGroup.length})</p>
                  <div className="h-64 overflow-y-auto fading-scrollbar border-4 border-black/5 rounded-2xl p-2 grid grid-cols-1 gap-2">
                    {allUsers.filter(u => u.username !== currentUser.username && !currentUser.blockedUsers.includes(u.username)).map(u => (
                      <button 
                        key={u.username} 
                        onClick={() => setSelectedForGroup(prev => prev.includes(u.username) ? prev.filter(un => un !== u.username) : [...prev, u.username])}
                        className={`flex items-center gap-3 p-3 rounded-xl transition-all ${selectedForGroup.includes(u.username) ? 'bg-blue-600 text-white shadow-md' : 'hover:bg-black/5'}`}
                      >
                        <div className="w-10 h-10 rounded-lg bg-black/10 flex items-center justify-center font-black overflow-hidden">{u.profilePic ? <img src={u.profilePic} className="w-full h-full object-cover" /> : u.displayName[0]}</div>
                        <div className="text-left flex-1"><p className="font-black text-xs uppercase">{u.displayName}</p><p className="text-[9px] font-bold opacity-60">@{u.username}</p></div>
                        {selectedForGroup.includes(u.username) && <Check size={16} />}
                      </button>
                    ))}
                  </div>
                </div>

                <button 
                  onClick={handleCreateGroup} 
                  disabled={!groupName.trim() || selectedForGroup.length === 0}
                  className="kahoot-button-blue w-full py-5 rounded-2xl text-white font-black uppercase text-xl shadow-xl active:scale-95 disabled:opacity-30 disabled:grayscale transition-all"
                >
                  AUTHORIZE GROUP
                </button>
              </div>
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </div>
  );
};

export default CityHallSection;

export type Mood = 'Wonderful' | 'Excited' | 'Happy' | 'Normal' | 'Tired' | 'Angry' | 'Flaming' | null;

export interface Badge {
  id: string;
  name: string;
  icon: string;
  description: string;
  threshold: number;
}

export interface User {
  displayName: string;
  username: string;
  email: string;
  password?: string;
  bio?: string;
  followers: string[];
  following: string[];
  friends: string[];
  blockedUsers: string[];
  posts: Post[];
  reposts: Post[];
  moodHistory: { date: string, mood: Mood, score: number }[];
  moodStreak: number;
  lastMoodDate?: string;
  profilePic?: string;
  bannerPic?: string;
  profileColor?: string;
  title?: string;
  likesReceived: number;
  // Mood Pet Stats
  petName: string;
  moodCoins: number;
  petEmoji: string;
  petHunger: number; // 0-100
  petThirst: number; // 0-100
  petRest: number;   // 0-100
  petLevel: number;
  petExp: number;
  petHasBeenChosen: boolean;
  petLastUpdate: number; // timestamp
  petSleepUntil: number | null; // timestamp
  gameCooldowns: Record<string, number>; // gameId -> timestamp of when it can be played again
}

export interface MessageReaction {
  emoji: string;
  users: string[]; // List of usernames who used this emoji
}

export interface Message {
  id: string;
  sender: string;
  recipient: string; // For DMs, this is the username. For Groups, this is the groupId.
  text: string;
  timestamp: number;
  read: boolean;
  reactions?: MessageReaction[];
  isGroup?: boolean;
  recipients?: string[]; // List of all usernames in the group (if group chat)
  groupName?: string;
  replyToId?: string;
  replyToText?: string;
  replyToSender?: string;
}

export interface Notification {
  id: string;
  type: 'heart' | 'comment' | 'repost' | 'tier' | 'achievement' | 'follow' | 'comment_heart' | 'reply' | 'reaction';
  fromUser: string;
  recipient: string; 
  postId?: string;
  timestamp: number;
  read: boolean;
  postContentSnippet: string;
}

export interface Post {
  id: string;
  author: string;
  content: string;
  hearts: number;
  comments: Comment[];
  timestamp: number;
  isRepost?: boolean;
  originalAuthor?: string;
  visibility: 'global' | 'circle';
}

export interface Comment {
  id: string;
  author: string;
  text: string;
  hearts: number;
  timestamp: number;
  replies: Comment[];
}

export type Section = 'Home' | 'Mood' | 'Zodiac' | 'CityHall' | 'Profile' | 'Settings' | 'Notifications';

export interface ZodiacInfo {
  name: string;
  dates: string;
  description: string;
  history: string;
  symbol: string;
}

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { User, Mood, Section, Post, Comment, Message, Notification, MessageReaction } from './types';
import Sidebar from './components/Sidebar';
import MoodCheckIn from './components/MoodCheckIn';
import HomeSection from './sections/HomeSection';
import MoodSection from './sections/MoodSection';
import ZodiacSection from './sections/ZodiacSection';
import CityHallSection from './sections/CityHallSection';
import ProfileSection from './sections/ProfileSection';
import SettingsSection from './sections/SettingsSection';
import NotificationsSection from './sections/NotificationsSection';
import AuthScreen from './sections/AuthScreen';
import LoadingScreen from './components/LoadingScreen';
import { getExpNeeded, MOOD_SCORES } from './constants';
import { Trophy, Share2, X } from 'lucide-react';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [activeSection, setActiveSection] = useState<Section>('Home');
  const [viewingUsername, setViewingUsername] = useState<string | null>(null);
  const [isMoodModalOpen, setIsMoodModalOpen] = useState(false);
  const [isDarkMode, setIsDarkMode] = useState(false); 
  const [isAppStarting, setIsAppStarting] = useState(true);
  const [levelUpInfo, setLevelUpInfo] = useState<{ level: number } | null>(null);
  const [globalUpdateToggle, setGlobalUpdateToggle] = useState(0);

  const [allPosts, setAllPosts] = useState<Post[]>([]);
  const [allMessages, setAllMessages] = useState<Message[]>([]);
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);

  const profileToView = useMemo(() => {
    if (!viewingUsername) return null;
    if (currentUser && viewingUsername === currentUser.username) return currentUser;
    const allUsers: User[] = JSON.parse(localStorage.getItem('mooderia_all_users') || '[]');
    return allUsers.find(u => u.username === viewingUsername) || null;
  }, [viewingUsername, currentUser, globalUpdateToggle]);

  const addNotification = useCallback((recipient: string, type: Notification['type'], snippet: string, postId: string = '') => {
    if (!currentUser || recipient === currentUser.username) {
      if (type !== 'achievement' && type !== 'tier') return;
    }
    const newNotif: Notification = {
      id: Math.random().toString(36).substr(2, 9),
      fromUser: currentUser?.username || 'Metropolis',
      recipient,
      type,
      postId,
      timestamp: Date.now(),
      read: false,
      postContentSnippet: snippet
    };
    setNotifications(prev => [...prev, newNotif]);
  }, [currentUser]);

  useEffect(() => {
    const savedUser = localStorage.getItem('mooderia_user');
    const savedPosts = localStorage.getItem('mooderia_posts') || '[]';
    const savedMessages = localStorage.getItem('mooderia_messages') || '[]';
    const savedNotifications = localStorage.getItem('mooderia_notifications') || '[]';
    const savedTheme = localStorage.getItem('mooderia_theme');

    if (savedUser) {
      const user: User = JSON.parse(savedUser);
      const now = Date.now();
      const elapsedMinutes = Math.floor((now - (user.petLastUpdate || now)) / 60000);
      if (elapsedMinutes > 0) {
        user.petHunger = Math.max(0, user.petHunger - elapsedMinutes * 0.15);
        user.petThirst = Math.max(0, user.petThirst - elapsedMinutes * 0.2);
        if (!user.petSleepUntil || user.petSleepUntil < now) {
          user.petRest = Math.max(0, user.petRest - elapsedMinutes * 0.1);
        }
        user.petLastUpdate = now;
      }
      setCurrentUser(user);
    }

    setAllPosts(JSON.parse(savedPosts));
    setAllMessages(JSON.parse(savedMessages));
    setNotifications(JSON.parse(savedNotifications));
    if (savedTheme === 'dark') setIsDarkMode(true);
    setIsLoaded(true);

    const timer = setTimeout(() => setIsAppStarting(false), 2000);
    return () => clearTimeout(timer);
  }, []);

  useEffect(() => {
    if (!isAppStarting && currentUser) {
      const todayStr = new Date().toDateString();
      if (currentUser.lastMoodDate !== todayStr) {
        setIsMoodModalOpen(true);
      }
    }
  }, [isAppStarting, currentUser?.username, currentUser?.lastMoodDate]);

  useEffect(() => {
    if (!isLoaded) return;
    if (currentUser) {
      localStorage.setItem('mooderia_user', JSON.stringify(currentUser));
      const allUsers: User[] = JSON.parse(localStorage.getItem('mooderia_all_users') || '[]');
      const idx = allUsers.findIndex(u => u.username === currentUser.username);
      if (idx > -1) {
        allUsers[idx] = currentUser;
        localStorage.setItem('mooderia_all_users', JSON.stringify(allUsers));
      }
    }
    localStorage.setItem('mooderia_posts', JSON.stringify(allPosts));
    localStorage.setItem('mooderia_messages', JSON.stringify(allMessages));
    localStorage.setItem('mooderia_notifications', JSON.stringify(notifications));
    localStorage.setItem('mooderia_theme', isDarkMode ? 'dark' : 'light');
  }, [currentUser, allPosts, allMessages, notifications, isDarkMode, isLoaded]);

  const handleFollow = (targetUsername: string) => {
    if (!currentUser) return;
    const isFollowing = currentUser.following.includes(targetUsername);
    const updatedFollowing = isFollowing ? currentUser.following.filter(u => u !== targetUsername) : [...currentUser.following, targetUsername];
    setCurrentUser({ ...currentUser, following: updatedFollowing });
    const allUsers: User[] = JSON.parse(localStorage.getItem('mooderia_all_users') || '[]');
    const targetIdx = allUsers.findIndex(u => u.username === targetUsername);
    if (targetIdx > -1) {
      const targetUser = { ...allUsers[targetIdx] };
      targetUser.followers = isFollowing ? targetUser.followers.filter(u => u !== currentUser.username) : [...targetUser.followers, currentUser.username];
      allUsers[targetIdx] = targetUser;
      localStorage.setItem('mooderia_all_users', JSON.stringify(allUsers));
      if (!isFollowing) addNotification(targetUsername, 'follow', 'started following you!');
    }
    setGlobalUpdateToggle(t => t + 1);
  };

  const handleHeart = (postId: string) => {
    if (!currentUser) return;
    setAllPosts(prev => prev.map(p => {
      if (p.id === postId) {
        if (p.author !== currentUser.username) addNotification(p.author, 'heart', 'liked your expression', p.id);
        return { ...p, hearts: p.hearts + 1 };
      }
      return p;
    }));
  };

  const handleCommentInteraction = (postId: string, commentId: string, action: 'heart' | 'reply', replyText?: string) => {
    if (!currentUser) return;
    setAllPosts(prev => prev.map(p => {
      if (p.id === postId) {
        const updateNested = (list: Comment[]): Comment[] => {
          return list.map(c => {
            if (c.id === commentId) {
              if (action === 'heart') {
                if (c.author !== currentUser.username) addNotification(c.author, 'comment_heart', 'liked your frequency', postId);
                return { ...c, hearts: c.hearts + 1 };
              }
              if (action === 'reply' && replyText) {
                const newRep: Comment = {
                  id: Math.random().toString(36).substr(2, 9),
                  author: currentUser.username,
                  text: replyText,
                  hearts: 0,
                  timestamp: Date.now(),
                  replies: []
                };
                if (c.author !== currentUser.username) addNotification(c.author, 'reply', 'responded to your frequency', postId);
                return { ...c, replies: [...c.replies, newRep] };
              }
            }
            if (c.replies.length > 0) return { ...c, replies: updateNested(c.replies) };
            return c;
          });
        };
        return { ...p, comments: updateNested(p.comments) };
      }
      return p;
    }));
  };

  const handleRepost = (p: Post) => {
    if (!currentUser) return;
    const newRepost: Post = {
      id: Math.random().toString(36).substr(2, 9),
      author: currentUser.username,
      content: p.content,
      hearts: 0,
      comments: [],
      timestamp: Date.now(),
      isRepost: true,
      originalAuthor: p.author,
      visibility: 'global'
    };
    setAllPosts(prev => [newRepost, ...prev]);
    if (p.author !== currentUser.username) addNotification(p.author, 'repost', 'echoed your transmission', p.id);
  };

  const handleBlock = (targetUsername: string) => {
    if (!currentUser) return;
    const updatedFollowing = currentUser.following.filter(u => u !== targetUsername);
    const updatedBlocked = [...currentUser.blockedUsers, targetUsername];
    setCurrentUser({ ...currentUser, following: updatedFollowing, blockedUsers: updatedBlocked });
    const allUsers: User[] = JSON.parse(localStorage.getItem('mooderia_all_users') || '[]');
    const targetIdx = allUsers.findIndex(u => u.username === targetUsername);
    if (targetIdx > -1) {
      const targetUser = { ...allUsers[targetIdx] };
      targetUser.followers = targetUser.followers.filter(u => u !== currentUser.username);
      targetUser.following = targetUser.following.filter(u => u !== currentUser.username);
      allUsers[targetIdx] = targetUser;
      const currentIdxGlobal = allUsers.findIndex(u => u.username === currentUser.username);
      if (currentIdxGlobal > -1) allUsers[currentIdxGlobal].followers = allUsers[currentIdxGlobal].followers.filter(u => u !== targetUsername);
      localStorage.setItem('mooderia_all_users', JSON.stringify(allUsers));
    }
    setViewingUsername(currentUser.username);
    setActiveSection('Home');
    setGlobalUpdateToggle(t => t + 1);
  };

  const updatePetStats = (hunger: number, thirst: number, rest: number, coins: number, exp: number = 0, sleepUntil: number | null = null, newEmoji?: string, markChosen?: boolean, newName?: string, gameCooldownId?: string) => {
    if (!currentUser) return;
    let newLevel = currentUser.petLevel;
    let newExp = currentUser.petExp + exp;
    let leveledUp = false;
    while (newExp >= getExpNeeded(newLevel)) { newExp -= getExpNeeded(newLevel); newLevel += 1; leveledUp = true; }
    if (leveledUp) addNotification(currentUser.username, 'achievement', `Your Guardian ${newName || currentUser.petName} reached Level ${newLevel}!`);
    setCurrentUser({
      ...currentUser,
      petName: newName || currentUser.petName,
      petHunger: Math.min(100, Math.max(0, currentUser.petHunger + hunger)),
      petThirst: Math.min(100, Math.max(0, currentUser.petThirst + thirst)),
      petRest: Math.min(100, Math.max(0, currentUser.petRest + rest)),
      petExp: newExp,
      petLevel: newLevel,
      moodCoins: currentUser.moodCoins + coins,
      petSleepUntil: sleepUntil !== undefined ? sleepUntil : currentUser.petSleepUntil,
      petEmoji: newEmoji || currentUser.petEmoji,
      petHasBeenChosen: markChosen !== undefined ? markChosen : currentUser.petHasBeenChosen,
      petLastUpdate: Date.now(),
      gameCooldowns: gameCooldownId ? { ...currentUser.gameCooldowns, [gameCooldownId]: Date.now() + 60000 } : currentUser.gameCooldowns
    });
  };

  const handleMessageReaction = (msgId: string, emoji: string) => {
    if (!currentUser) return;
    setAllMessages(prev => prev.map(m => {
      if (m.id === msgId) {
        let reactions = [...(m.reactions || [])];
        const existingReaction = reactions.find(r => r.users.includes(currentUser.username));
        if (existingReaction) {
          if (existingReaction.emoji === emoji) {
            existingReaction.users = existingReaction.users.filter(u => u !== currentUser.username);
            if (existingReaction.users.length === 0) reactions = reactions.filter(r => r.emoji !== emoji);
          } else {
            existingReaction.users = existingReaction.users.filter(u => u !== currentUser.username);
            if (existingReaction.users.length === 0) reactions = reactions.filter(r => r.emoji !== existingReaction.emoji);
            const targetReaction = reactions.find(r => r.emoji === emoji);
            if (targetReaction) targetReaction.users.push(currentUser.username);
            else reactions.push({ emoji, users: [currentUser.username] });
            if (m.sender !== currentUser.username) addNotification(m.sender, 'reaction', emoji, msgId);
          }
        } else {
          const targetReaction = reactions.find(r => r.emoji === emoji);
          if (targetReaction) targetReaction.users.push(currentUser.username);
          else reactions.push({ emoji, users: [currentUser.username] });
          if (m.sender !== currentUser.username) addNotification(m.sender, 'reaction', emoji, msgId);
        }
        return { ...m, reactions };
      }
      return m;
    }));
  };

  const onLogin = (user: User) => {
    setCurrentUser(user);
    setActiveSection('Home');
    setViewingUsername(user.username);
  };

  const handleSendMessage = (recipient: string, text: string, options?: { isGroup?: boolean, recipients?: string[], groupName?: string, replyToId?: string, replyToText?: string, replyToSender?: string }) => {
    if (!currentUser) return;
    const newMsg: Message = {
      id: Math.random().toString(36).substr(2, 9),
      sender: currentUser.username,
      recipient,
      text,
      timestamp: Date.now(),
      read: false,
      isGroup: options?.isGroup,
      recipients: options?.recipients,
      groupName: options?.groupName,
      replyToId: options?.replyToId,
      replyToText: options?.replyToText,
      replyToSender: options?.replyToSender
    };
    setAllMessages(prev => [...prev, newMsg]);
  };

  if (isAppStarting) return <LoadingScreen />;
  if (!currentUser) return <AuthScreen onLogin={onLogin} />;

  return (
    <div style={{'--theme-color': currentUser.profileColor || '#e21b3c'} as React.CSSProperties} className={`h-screen max-h-screen overflow-hidden flex flex-col md:flex-row ${isDarkMode ? 'bg-[#0f0f0f] text-white' : 'bg-[#f7f8fa] text-slate-900'} transition-colors duration-300`}>
      <style>{`
        :root { --theme-color: ${currentUser.profileColor || '#e21b3c'}; }
        .kahoot-button-custom { background-color: var(--theme-color); border-bottom: 4px solid rgba(0,0,0,0.3); }
        .text-custom { color: var(--theme-color); }
        .bg-custom { background-color: var(--theme-color); }
        .border-custom { border-color: var(--theme-color); }
      `}</style>
      <AnimatePresence>{isMoodModalOpen && <MoodCheckIn onSubmit={(m) => { const today = new Date().toDateString(); setCurrentUser({ ...currentUser, moodStreak: currentUser.lastMoodDate === today ? currentUser.moodStreak : (currentUser.moodStreak || 0) + 1, lastMoodDate: today, moodHistory: [...(currentUser.moodHistory || []), { date: today, mood: m, score: MOOD_SCORES[m || 'Normal'] }] }); setIsMoodModalOpen(false); }} isDarkMode={isDarkMode} />}</AnimatePresence>
      <Sidebar activeSection={activeSection} onNavigate={(s) => { setActiveSection(s); if(s === 'Profile') setViewingUsername(currentUser.username); }} isDarkMode={isDarkMode} user={currentUser} unreadMessages={allMessages.filter(m => m.recipient === currentUser.username && !m.read).length} unreadNotifications={notifications.filter(n => n.recipient === currentUser.username && !n.read).length} />
      <main className="flex-1 flex flex-col relative pt-16 pb-20 md:pt-0 md:pb-0 h-full overflow-hidden">
        <div className="flex-1 overflow-y-auto fading-scrollbar p-4 md:p-8">
          <motion.div key={activeSection + (activeSection === 'Profile' ? viewingUsername : '')} initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} className="max-w-5xl mx-auto">
            {activeSection === 'Home' && <HomeSection user={currentUser} posts={allPosts} isDarkMode={isDarkMode} />}
            {activeSection === 'Mood' && <MoodSection user={currentUser} posts={allPosts} onPost={(c, v) => setAllPosts(prev => [{id: Math.random().toString(36).substr(2, 9), author: currentUser.username, content: c, hearts: 0, comments: [], timestamp: Date.now(), visibility: v}, ...prev])} onHeart={handleHeart} onComment={(pid, t) => setAllPosts(prev => prev.map(p => p.id === pid ? { ...p, comments: [...p.comments, { id: Math.random().toString(36).substr(2, 9), author: currentUser.username, text: t, hearts: 0, timestamp: Date.now(), replies: [] }] } : p))} onCommentInteraction={handleCommentInteraction} onRepost={handleRepost} onFollow={handleFollow} onBlock={handleBlock} isDarkMode={isDarkMode} onNavigateToProfile={(u) => {setViewingUsername(u); setActiveSection('Profile');}} onUpdatePet={updatePetStats} />}
            {activeSection === 'Zodiac' && <ZodiacSection isDarkMode={isDarkMode} />}
            {activeSection === 'CityHall' && <CityHallSection isDarkMode={isDarkMode} currentUser={currentUser} messages={allMessages} onSendMessage={handleSendMessage} onReadMessages={(u) => setAllMessages(prev => prev.map(m => (m.recipient === currentUser.username && m.sender === u) ? {...m, read: true} : m))} onNavigateToProfile={(u) => {setViewingUsername(u); setActiveSection('Profile');}} onReactToMessage={handleMessageReaction} />}
            {activeSection === 'Notifications' && <NotificationsSection notifications={notifications.filter(n => n.recipient === currentUser.username)} isDarkMode={isDarkMode} onMarkRead={() => setNotifications(notifications.map(n => n.recipient === currentUser.username ? {...n, read: true} : n))} />}
            {activeSection === 'Profile' && profileToView && <ProfileSection user={profileToView} allPosts={allPosts} isDarkMode={isDarkMode} currentUser={currentUser} onEditProfile={(dn, un, pp, ti, bp, pc, bi) => { setCurrentUser({...currentUser, displayName: dn, username: un, profilePic: pp, title: ti, profileColor: pc, bio: bi}); setViewingUsername(un); }} onBlock={handleBlock} onFollow={handleFollow} />}
            {activeSection === 'Settings' && <SettingsSection isDarkMode={isDarkMode} onToggleDarkMode={() => setIsDarkMode(!isDarkMode)} onLogout={() => {localStorage.removeItem('mooderia_user'); setCurrentUser(null);}} user={currentUser} onUnblock={(u) => setCurrentUser({...currentUser, blockedUsers: currentUser.blockedUsers.filter(b => b !== u)})} />}
          </motion.div>
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Send, Users, Search, MessageSquare, ArrowLeft, ShieldCheck, Check, CheckCheck, Clock, Smile, Plus, X, Reply, CornerDownRight } from 'lucide-react';
import { User, Message, MessageReaction } from '../types';

interface CityHallSectionProps {
  isDarkMode: boolean;
  currentUser: User;
  messages: Message[];
  onSendMessage: (recipient: string, text: string, options?: { isGroup?: boolean, recipients?: string[], groupName?: string, replyToId?: string, replyToText?: string, replyToSender?: string }) => void;
  onReadMessages: (withUsername: string) => void;
  onNavigateToProfile: (username: string) => void;
  onReactToMessage: (msgId: string, emoji: string) => void;
}

const REACTION_EMOJIS = ['❤️', '😂', '😮', '😢', '🔥', '👍'];

const CityHallSection: React.FC<CityHallSectionProps> = ({ isDarkMode, currentUser, messages, onSendMessage, onReadMessages, onNavigateToProfile, onReactToMessage }) => {
  const [input, setInput] = useState('');
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedCitizen, setSelectedCitizen] = useState<{ username: string, displayName: string, profilePic?: string, isGroup?: boolean, recipients?: string[] } | null>(null);
  const [reactionPickerMsgId, setReactionPickerMsgId] = useState<string | null>(null);
  const [isCreatingGroup, setIsCreatingGroup] = useState(false);
  const [groupName, setGroupName] = useState('');
  const [selectedForGroup, setSelectedForGroup] = useState<string[]>([]);
  const [viewingReacters, setViewingReacters] = useState<MessageReaction | null>(null);
  const [replyingTo, setReplyingTo] = useState<Message | null>(null);
  const chatEndRef = useRef<HTMLDivElement>(null);
  const scrollContainerRef = useRef<HTMLDivElement>(null);

  const allUsers: User[] = useMemo(() => JSON.parse(localStorage.getItem('mooderia_all_users') || '[]'), []);
  const usersWhoBlockedMe = useMemo(() => allUsers.filter(u => u.blockedUsers.includes(currentUser.username)).map(u => u.username), [allUsers, currentUser.username]);

  const filteredCitizens = useMemo(() => {
    if (!searchTerm.trim()) return [];
    return allUsers.filter(u => 
      u.username !== currentUser.username && 
      !currentUser.blockedUsers.includes(u.username) &&
      !usersWhoBlockedMe.includes(u.username) &&
      (u.displayName.toLowerCase().includes(searchTerm.toLowerCase()) || 
       u.username.toLowerCase().includes(searchTerm.toLowerCase()))
    );
  }, [searchTerm, allUsers, currentUser.username, currentUser.blockedUsers, usersWhoBlockedMe]);

  const chats = useMemo(() => {
    const list: any[] = [];
    const processedDms = new Set<string>();
    const processedGroups = new Set<string>();

    messages.forEach(m => {
      if (m.isGroup && m.recipient && !processedGroups.has(m.recipient)) {
        processedGroups.add(m.recipient);
        list.push({ 
          username: m.recipient, 
          displayName: m.groupName || 'Unnamed Group', 
          isGroup: true, 
          recipients: m.recipients 
        });
      } else if (!m.isGroup) {
        const other = m.sender === currentUser.username ? m.recipient : m.sender;
        if (!processedDms.has(other)) {
          processedDms.add(other);
          const userObj = allUsers.find(u => u.username === other);
          if (userObj && !currentUser.blockedUsers.includes(other) && !usersWhoBlockedMe.includes(other)) {
            list.push({ 
              username: other, 
              displayName: userObj.displayName, 
              profilePic: userObj.profilePic, 
              isGroup: false 
            });
          }
        }
      }
    });
    return list;
  }, [messages, allUsers, currentUser.username, currentUser.blockedUsers, usersWhoBlockedMe]);

  const chatMessages = useMemo(() => {
    if (!selectedCitizen) return [];
    if (selectedCitizen.isGroup) {
      return messages.filter(m => m.isGroup && m.recipient === selectedCitizen.username)
        .sort((a, b) => a.timestamp - b.timestamp);
    }
    return messages.filter(m => 
      !m.isGroup &&
      ((m.sender === currentUser.username && m.recipient === selectedCitizen.username) ||
      (m.sender === selectedCitizen.username && m.recipient === currentUser.username))
    ).sort((a, b) => a.timestamp - b.timestamp);
  }, [messages, selectedCitizen, currentUser.username]);

  const groupedMessages = useMemo(() => {
    const groups: { dateLabel: string, items: Message[] }[] = [];
    chatMessages.forEach(msg => {
      const date = new Date(msg.timestamp);
      const today = new Date();
      const yesterday = new Date();
      yesterday.setDate(yesterday.getDate() - 1);
      let label = date.toLocaleDateString(undefined, { day: 'numeric', month: 'long', year: 'numeric' });
      if (date.toDateString() === today.toDateString()) label = "Today";
      else if (date.toDateString() === yesterday.toDateString()) label = "Yesterday";
      const lastGroup = groups[groups.length - 1];
      if (lastGroup && lastGroup.dateLabel === label) lastGroup.items.push(msg);
      else groups.push({ dateLabel: label, items: [msg] });
    });
    return groups;
  }, [chatMessages]);

  useEffect(() => {
    if (selectedCitizen && !selectedCitizen.isGroup) onReadMessages(selectedCitizen.username);
    // Use requestAnimationFrame to ensure DOM is updated before scrolling
    requestAnimationFrame(() => {
      chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    });
  }, [selectedCitizen, messages.length]);

  const handleSend = () => {
    if (!input.trim() || !selectedCitizen) return;
    onSendMessage(selectedCitizen.username, input, { 
      isGroup: selectedCitizen.isGroup, 
      recipients: selectedCitizen.recipients, 
      groupName: selectedCitizen.displayName,
      replyToId: replyingTo?.id,
      replyToText: replyingTo?.text,
      replyToSender: replyingTo?.sender
    });
    setInput('');
    setReplyingTo(null);
  };

  const handleCreateGroup = () => {
    if (!groupName.trim() || selectedForGroup.length < 1) return;
    const groupId = 'group_' + Math.random().toString(36).substr(2, 9);
    const recipients = [...selectedForGroup, currentUser.username];
    onSendMessage(groupId, `CITIZEN TERMINAL: Group "${groupName}" initialized.`, { isGroup: true, recipients, groupName });
    setSelectedCitizen({ username: groupId, displayName: groupName, isGroup: true, recipients });
    setIsCreatingGroup(false);
    setGroupName('');
    setSelectedForGroup([]);
  };

  return (
    <div className="flex flex-col h-full overflow-hidden gap-4">
      <div className="flex justify-between items-center px-2 shrink-0">
        <h2 className={`text-2xl md:text-3xl font-black italic uppercase tracking-tighter ${isDarkMode ? 'text-white' : 'text-slate-900'}`}>Citizen Hub</h2>
        <button onClick={() => setIsCreatingGroup(true)} className="kahoot-button-blue p-3 rounded-xl text-white font-black flex items-center gap-2 shadow-lg hover:scale-105 transition-all">
          <Plus size={20} /> <span className="hidden sm:inline text-xs">NEW GROUP</span>
        </button>
      </div>

      <div className={`flex-1 flex flex-col md:flex-row rounded-[2.5rem] ${isDarkMode ? 'bg-slate-800' : 'bg-white'} shadow-2xl overflow-hidden border-4 border-gray-100 dark:border-slate-700 min-h-0`}>
        {/* Sidebar */}
        <div className={`w-full md:w-72 lg:w-80 border-r ${isDarkMode ? 'border-slate-700' : 'border-gray-100'} flex flex-col ${selectedCitizen ? 'hidden md:flex' : 'flex'}`}>
          <div className="p-4 border-b border-gray-100 dark:border-slate-700 shrink-0">
            <div className="relative">
              <input type="text" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} placeholder="Search Citizens..." className={`w-full px-10 py-3 rounded-xl text-xs font-bold border-2 outline-none focus:border-blue-500 ${isDarkMode ? 'bg-slate-700 border-slate-600 text-white' : 'bg-gray-50 border-gray-200'}`} />
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 opacity-30 text-white/50" size={16} />
            </div>
          </div>
          <div className="flex-1 overflow-y-auto fading-scrollbar p-2 space-y-1">
            {(searchTerm.trim() ? filteredCitizens.map(u => ({ username: u.username, displayName: u.displayName, profilePic: u.profilePic, isGroup: false })) : chats).map(u => (
              <button key={u.username} onClick={() => { setSelectedCitizen(u); setReplyingTo(null); }} className={`w-full p-3 rounded-xl flex items-center gap-3 transition-all ${selectedCitizen?.username === u.username ? 'bg-blue-600 text-white shadow-lg' : 'hover:bg-gray-50 dark:hover:bg-slate-700 text-slate-800 dark:text-white'}`}>
                <div className="w-10 h-10 rounded-xl bg-blue-100 dark:bg-slate-600 flex items-center justify-center font-black overflow-hidden shadow-sm shrink-0">
                  {u.isGroup ? <Users size={20} className="text-blue-600 dark:text-blue-300" /> : (u.profilePic ? <img src={u.profilePic} className="w-full h-full object-cover" /> : u.displayName[0].toUpperCase())}
                </div>
                <div className="text-left truncate flex-1">
                  <p className="font-black text-xs truncate uppercase tracking-tight">{u.displayName}</p>
                  <p className={`text-[9px] font-bold ${selectedCitizen?.username === u.username ? 'text-white/60' : 'opacity-40'}`}>@{u.username}</p>
                </div>
              </button>
            ))}
          </div>
        </div>

        {/* Chat Area */}
        <div className={`flex-1 flex flex-col min-h-0 ${!selectedCitizen ? 'hidden md:flex' : 'flex'}`}>
          {selectedCitizen ? (
            <>
              <div className={`p-4 border-b ${isDarkMode ? 'bg-slate-700/50 border-slate-700' : 'bg-gray-50 border-gray-100'} flex items-center justify-between shrink-0`}>
                <div className="flex items-center gap-4">
                  <button onClick={() => setSelectedCitizen(null)} className="md:hidden p-2 rounded-xl hover:bg-gray-200"><ArrowLeft size={20} /></button>
                  <div className="flex items-center gap-3">
                    <div className="w-10 h-10 rounded-xl bg-blue-600 text-white flex items-center justify-center font-black shadow-md overflow-hidden">
                      {selectedCitizen.isGroup ? <Users size={24} /> : (selectedCitizen.profilePic ? <img src={selectedCitizen.profilePic} className="w-full h-full object-cover" /> : selectedCitizen.displayName[0])}
                    </div>
                    <div className="text-left">
                      <p className="font-black text-sm text-slate-800 dark:text-white uppercase italic">{selectedCitizen.displayName}</p>
                      <p className="text-[10px] font-bold opacity-40 uppercase tracking-widest">{selectedCitizen.isGroup ? `${selectedCitizen.recipients?.length} Members` : 'Active Signal'}</p>
                    </div>
                  </div>
                </div>
              </div>

              {/* UNLIMITED SCROLLING CONVERSATION AREA */}
              <div ref={scrollContainerRef} className="flex-1 overflow-y-auto p-4 md:p-6 space-y-6 fading-scrollbar">
                {groupedMessages.map(group => (
                  <div key={group.dateLabel} className="space-y-6">
                    <div className="flex items-center gap-4 py-2">
                      <div className="h-px flex-1 bg-black/5 dark:bg-white/5"></div>
                      <span className="text-[10px] font-black uppercase opacity-30 tracking-[0.2em]">{group.dateLabel}</span>
                      <div className="h-px flex-1 bg-black/5 dark:bg-white/5"></div>
                    </div>
                    {group.items.map(m => {
                      const isMe = m.sender === currentUser.username;
                      const senderName = allUsers.find(u => u.username === m.sender)?.displayName || m.sender;
                      return (
                        <div key={m.id} className={`flex ${isMe ? 'justify-end' : 'justify-start'} group relative mb-2`}>
                          <div className={`max-w-[85%] md:max-w-[70%] space-y-1`}>
                            {selectedCitizen.isGroup && !isMe && <p className="text-[8px] font-black uppercase opacity-40 mb-1 ml-1 tracking-widest">{senderName}</p>}

                            <div className="relative group/bubble">
                              <div className={`relative px-5 py-3 rounded-2xl font-bold text-sm shadow-sm transition-all ${isMe ? 'bg-blue-600 text-white rounded-tr-none' : isDarkMode ? 'bg-slate-700 text-white rounded-tl-none' : 'bg-gray-100 text-slate-800 rounded-tl-none'}`}>

                                {/* Reply Preview in bubble */}
                                {m.replyToId && (
                                  <div className={`mb-2 p-2 rounded-lg text-[10px] flex flex-col gap-1 border-l-4 ${isMe ? 'bg-white/10 border-white/30' : 'bg-black/5 border-black/20'} opacity-70 italic`}>
                                    <div className="flex items-center gap-1 font-black uppercase">
                                      <CornerDownRight size={10} /> @{m.replyToSender}
                                    </div>
                                    <div className="truncate">{m.replyToText}</div>
                                  </div>
                                )}

                                {m.text}

                                {/* Reactions display */}
                                {m.reactions && m.reactions.length > 0 && (
                                  <div className={`absolute -bottom-3 ${isMe ? 'right-2' : 'left-2'} flex gap-1 bg-white dark:bg-slate-800 rounded-full px-2 py-0.5 shadow-md border border-black/5 cursor-pointer z-10`} onClick={(e) => { e.stopPropagation(); setViewingReacters(m.reactions?.[0] || null); }}>
                                    {m.reactions.map(r => (
                                      <button 
                                        key={r.emoji} 
                                        onClick={(e) => { e.stopPropagation(); setViewingReacters(r); }}
                                        className="flex items-center gap-1 hover:scale-110 transition-transform"
                                      >
                                        <span className="text-xs">{r.emoji}</span>
                                        <span className="text-[8px] font-black">{r.users.length}</span>
                                      </button>
                                    ))}
                                  </div>
                                )}

                                {/* Hover/Touch Action Buttons */}
                                <div className={`absolute ${isMe ? '-left-12' : '-right-12'} top-1/2 -translate-y-1/2 flex flex-col gap-1 opacity-0 group-hover/bubble:opacity-100 transition-opacity bg-white/5 backdrop-blur-sm p-1 rounded-xl z-20`}>
                                  <button 
                                    onClick={() => setReactionPickerMsgId(reactionPickerMsgId === m.id ? null : m.id)}
                                    className="p-2 text-slate-400 hover:text-blue-500 rounded-lg hover:bg-black/5 transition-colors"
                                    title="React"
                                  >
                                    <Smile size={16} />
                                  </button>
                                  <button 
                                    onClick={() => { setReplyingTo(m); chatEndRef.current?.scrollIntoView({ behavior: 'smooth' }); }}
                                    className="p-2 text-slate-400 hover:text-blue-500 rounded-lg hover:bg-black/5 transition-colors"
                                    title="Reply"
                                  >
                                    <Reply size={16} />
                                  </button>
                                </div>

                                {/* Reaction Picker Popover */}
                                <AnimatePresence>
                                  {reactionPickerMsgId === m.id && (
                                    <motion.div 
                                      initial={{ scale: 0.8, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} exit={{ scale: 0.8, opacity: 0 }}
                                      className={`absolute z-30 ${isMe ? 'right-0 -top-12' : 'left-0 -top-12'} bg-white dark:bg-slate-800 border-4 border-black/5 rounded-full p-1.5 flex gap-1.5 shadow-2xl`}
                                    >
                                      {REACTION_EMOJIS.map(emoji => {
                                        const isReacted = m.reactions?.find(r => r.emoji === emoji && r.users.includes(currentUser.username));
                                        return (
                                          <button 
                                            key={emoji} 
                                            onClick={() => { onReactToMessage(m.id, emoji); setReactionPickerMsgId(null); }}
                                            className={`hover:scale-125 transition-transform p-1.5 rounded-full ${isReacted ? 'bg-blue-100 dark:bg-blue-900/30' : ''}`}
                                          >
                                            {emoji}
                                          </button>
                                        );
                                      })}
                                    </motion.div>
                                  )}
                                </AnimatePresence>
                              </div>
                            </div>

                            <div className={`flex items-center gap-2 text-[9px] font-black uppercase opacity-30 ${isMe ? 'justify-end' : 'justify-start'}`}>
                              <Clock size={10} /> {new Date(m.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                              {isMe && (m.read ? <CheckCheck size={12} className="text-blue-400" /> : <Check size={12} />)}
                            </div>
                          </div>
                        </div>
                      );
                    })}
                  </div>
                ))}
                <div ref={chatEndRef} />
              </div>

              {/* Message Input with Reply State */}
              <div className={`p-4 md:p-6 border-t ${isDarkMode ? 'border-slate-700' : 'border-gray-100'} shrink-0 bg-inherit`}>
                <AnimatePresence>
                  {replyingTo && (
                    <motion.div 
                      initial={{ height: 0, opacity: 0, y: 10 }} 
                      animate={{ height: 'auto', opacity: 1, y: 0 }} 
                      exit={{ height: 0, opacity: 0, y: 10 }}
                      className="mb-3 overflow-hidden bg-blue-500/10 border-l-4 border-blue-500 p-3 rounded-r-xl flex items-center justify-between"
                    >
                      <div className="flex-1 min-w-0">
                        <p className="text-[10px] font-black uppercase text-blue-500 tracking-widest flex items-center gap-2">
                          <Reply size={12} /> Replying to @{replyingTo.sender}
                        </p>
                        <p className="text-xs font-bold opacity-60 truncate mt-1">"{replyingTo.text}"</p>
                      </div>
                      <button onClick={() => setReplyingTo(null)} className="p-2 text-slate-400 hover:text-red-500 transition-colors">
                        <X size={16} />
                      </button>
                    </motion.div>
                  )}
                </AnimatePresence>

                <div className={`flex items-center gap-3 p-2 rounded-2xl border-4 ${isDarkMode ? 'bg-slate-700/50 border-slate-700' : 'bg-gray-50 border-gray-200'} focus-within:border-blue-500/50 transition-all`}>
                  <input 
                    type="text" value={input} 
                    onChange={(e) => setInput(e.target.value)} 
                    onKeyPress={(e) => e.key === 'Enter' && handleSend()} 
                    placeholder={replyingTo ? "Transmit reply..." : "Broadcast frequency..."} 
                    className="flex-1 bg-transparent px-4 py-2 font-bold text-sm outline-none dark:text-white"
                  />
                  <button onClick={handleSend} className="bg-blue-600 text-white p-3 rounded-xl shadow-lg hover:scale-105 active:scale-95 transition-all"><Send size={20} /></button>
                </div>
              </div>
            </>
          ) : (
            <div className="flex-1 flex flex-col items-center justify-center p-10 text-center opacity-30">
              <MessageSquare size={80} className="mb-6 text-slate-400" />
              <h3 className="text-2xl font-black italic uppercase tracking-tighter text-slate-800 dark:text-white">Citizen Terminal</h3>
              <p className="text-xs font-bold uppercase tracking-[0.2em] mt-2 text-slate-800 dark:text-white">Select a frequency to synchronize transmissions</p>
            </div>
          )}
        </div>
      </div>

      {/* View Reacters Modal */}
      <AnimatePresence>
        {viewingReacters && (
          <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-black/80 backdrop-blur-sm">
            <motion.div initial={{ scale: 0.9, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} className={`w-full max-w-sm rounded-[3rem] p-8 ${isDarkMode ? 'bg-slate-900 border-slate-700' : 'bg-white border-gray-100'} border-4 shadow-2xl`}>
              <div className="flex justify-between items-center mb-6">
                <div className="flex items-center gap-3">
                  <span className="text-3xl">{viewingReacters.emoji}</span>
                  <h3 className="text-xl font-black uppercase italic tracking-tighter">Reacters</h3>
                </div>
                <button onClick={() => setViewingReacters(null)} className="p-2 rounded-full hover:bg-black/5"><X size={24} className="opacity-40" /></button>
              </div>
              <div className="space-y-3 max-h-[40vh] overflow-y-auto fading-scrollbar">
                {viewingReacters.users.map(u => {
                  const userObj = allUsers.find(cu => cu.username === u);
                  return (
                    <div key={u} className="flex items-center gap-3 p-3 rounded-2xl bg-black/5">
                      <div className="w-10 h-10 rounded-xl bg-custom text-white flex items-center justify-center font-black shadow-sm overflow-hidden">
                        {userObj?.profilePic ? <img src={userObj.profilePic} className="w-full h-full object-cover" /> : u[0].toUpperCase()}
                      </div>
                      <div>
                        <p className="font-black text-xs uppercase">{userObj?.displayName || u}</p>
                        <p className="text-[10px] font-bold opacity-40">@{u}</p>
                      </div>
                    </div>
                  );
                })}
              </div>
            </motion.div>
          </div>
        )}
      </AnimatePresence>

      {/* Group Creation Modal */}
      <AnimatePresence>
        {isCreatingGroup && (
          <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-black/80 backdrop-blur-sm">
            <motion.div initial={{ scale: 0.95, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} className={`w-full max-w-lg rounded-[3rem] p-8 ${isDarkMode ? 'bg-slate-900' : 'bg-white'} border-4 border-white/10 shadow-2xl`}>
              <div className="flex justify-between items-center mb-8">
                <h3 className="text-3xl font-black uppercase italic tracking-tighter">Initialize Group</h3>
                <button onClick={() => setIsCreatingGroup(false)} className="bg-black/5 p-2 rounded-full"><X size={24} /></button>
              </div>

              <div className="space-y-6">
                <div className="space-y-2">
                  <p className="text-[10px] font-black uppercase opacity-40 ml-2 tracking-widest">Group Designation</p>
                  <input type="text" value={groupName} onChange={(e) => setGroupName(e.target.value)} placeholder="Echo Squad..." className="w-full p-4 rounded-2xl border-4 bg-black/5 font-black text-lg outline-none focus:border-blue-500" />
                </div>

                <div className="space-y-2">
                  <p className="text-[10px] font-black uppercase opacity-40 ml-2 tracking-widest">Select Citizens ({selectedForGroup.length})</p>
                  <div className="h-64 overflow-y-auto fading-scrollbar border-4 border-black/5 rounded-2xl p-2 grid grid-cols-1 gap-2">
                    {allUsers.filter(u => u.username !== currentUser.username && !currentUser.blockedUsers.includes(u.username)).map(u => (
                      <button 
                        key={u.username} 
                        onClick={() => setSelectedForGroup(prev => prev.includes(u.username) ? prev.filter(un => un !== u.username) : [...prev, u.username])}
                        className={`flex items-center gap-3 p-3 rounded-xl transition-all ${selectedForGroup.includes(u.username) ? 'bg-blue-600 text-white shadow-md' : 'hover:bg-black/5'}`}
                      >
                        <div className="w-10 h-10 rounded-lg bg-black/10 flex items-center justify-center font-black overflow-hidden">{u.profilePic ? <img src={u.profilePic} className="w-full h-full object-cover" /> : u.displayName[0]}</div>
                        <div className="text-left flex-1"><p className="font-black text-xs uppercase">{u.displayName}</p><p className="text-[9px] font-bold opacity-60">@{u.username}</p></div>
                        {selectedForGroup.includes(u.username) && <Check size={16} />}
                      </button>
                    ))}
                  </div>
                </div>

                <button 
                  onClick={handleCreateGroup} 
                  disabled={!groupName.trim() || selectedForGroup.length === 0}
                  className="kahoot-button-blue w-full py-5 rounded-2xl text-white font-black uppercase text-xl shadow-xl active:scale-95 disabled:opacity-30 disabled:grayscale transition-all"
                >
                  AUTHORIZE GROUP
                </button>
              </div>
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </div>
  );
};

export default CityHallSection;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Send, Users, Search, MessageSquare, ArrowLeft, ShieldCheck, Check, CheckCheck, Clock, Smile, Plus, X, Reply, CornerDownRight } from 'lucide-react';
import { User, Message, MessageReaction } from '../types';

interface CityHallSectionProps {
  isDarkMode: boolean;
  currentUser: User;
  messages: Message[];
  onSendMessage: (recipient: string, text: string, options?: { isGroup?: boolean, recipients?: string[], groupName?: string, replyToId?: string, replyToText?: string, replyToSender?: string }) => void;
  onReadMessages: (withUsername: string) => void;
  onNavigateToProfile: (username: string) => void;
  onReactToMessage: (msgId: string, emoji: string) => void;
}

const REACTION_EMOJIS = ['❤️', '😂', '😮', '😢', '🔥', '👍'];

const CityHallSection: React.FC<CityHallSectionProps> = ({ isDarkMode, currentUser, messages, onSendMessage, onReadMessages, onNavigateToProfile, onReactToMessage }) => {
  const [input, setInput] = useState('');
  const [searchTerm, setSearchTerm] = useState('');
  const [groupSearchTerm, setGroupSearchTerm] = useState('');
  const [selectedCitizen, setSelectedCitizen] = useState<{ username: string, displayName: string, profilePic?: string, isGroup?: boolean, recipients?: string[] } | null>(null);
  const [reactionPickerMsgId, setReactionPickerMsgId] = useState<string | null>(null);
  const [isCreatingGroup, setIsCreatingGroup] = useState(false);
  const [groupName, setGroupName] = useState('');
  const [selectedForGroup, setSelectedForGroup] = useState<string[]>([]);
  const [viewingReacters, setViewingReacters] = useState<MessageReaction | null>(null);
  const [replyingTo, setReplyingTo] = useState<Message | null>(null);
  const chatEndRef = useRef<HTMLDivElement>(null);
  const scrollContainerRef = useRef<HTMLDivElement>(null);

  const allUsers: User[] = useMemo(() => JSON.parse(localStorage.getItem('mooderia_all_users') || '[]'), [isCreatingGroup, isCreatingGroup === false]);
  const usersWhoBlockedMe = useMemo(() => allUsers.filter(u => u.blockedUsers.includes(currentUser.username)).map(u => u.username), [allUsers, currentUser.username]);

  const filteredCitizens = useMemo(() => {
    if (!searchTerm.trim()) return [];
    return allUsers.filter(u => 
      u.username !== currentUser.username && 
      !currentUser.blockedUsers.includes(u.username) &&
      !usersWhoBlockedMe.includes(u.username) &&
      (u.displayName.toLowerCase().includes(searchTerm.toLowerCase()) || 
       u.username.toLowerCase().includes(searchTerm.toLowerCase()))
    );
  }, [searchTerm, allUsers, currentUser.username, currentUser.blockedUsers, usersWhoBlockedMe]);

  const groupFilterList = useMemo(() => {
    return allUsers.filter(u => 
      u.username !== currentUser.username && 
      !currentUser.blockedUsers.includes(u.username) &&
      !usersWhoBlockedMe.includes(u.username) &&
      (u.displayName.toLowerCase().includes(groupSearchTerm.toLowerCase()) || 
       u.username.toLowerCase().includes(groupSearchTerm.toLowerCase()))
    );
  }, [groupSearchTerm, allUsers, currentUser.username, currentUser.blockedUsers, usersWhoBlockedMe]);

  const chats = useMemo(() => {
    const list: any[] = [];
    const processedDms = new Set<string>();
    const processedGroups = new Set<string>();

    messages.forEach(m => {
      if (m.isGroup && m.recipient && !processedGroups.has(m.recipient)) {
        processedGroups.add(m.recipient);
        list.push({ 
          username: m.recipient, 
          displayName: m.groupName || 'Unnamed Group', 
          isGroup: true, 
          recipients: m.recipients 
        });
      } else if (!m.isGroup) {
        const other = m.sender === currentUser.username ? m.recipient : m.sender;
        if (!processedDms.has(other)) {
          processedDms.add(other);
          const userObj = allUsers.find(u => u.username === other);
          if (userObj && !currentUser.blockedUsers.includes(other) && !usersWhoBlockedMe.includes(other)) {
            list.push({ 
              username: other, 
              displayName: userObj.displayName, 
              profilePic: userObj.profilePic, 
              isGroup: false 
            });
          }
        }
      }
    });
    return list;
  }, [messages, allUsers, currentUser.username, currentUser.blockedUsers, usersWhoBlockedMe]);

  const chatMessages = useMemo(() => {
    if (!selectedCitizen) return [];
    if (selectedCitizen.isGroup) {
      return messages.filter(m => m.isGroup && m.recipient === selectedCitizen.username)
        .sort((a, b) => a.timestamp - b.timestamp);
    }
    return messages.filter(m => 
      !m.isGroup &&
      ((m.sender === currentUser.username && m.recipient === selectedCitizen.username) ||
      (m.sender === selectedCitizen.username && m.recipient === currentUser.username))
    ).sort((a, b) => a.timestamp - b.timestamp);
  }, [messages, selectedCitizen, currentUser.username]);

  const groupedMessages = useMemo(() => {
    const groups: { dateLabel: string, items: Message[] }[] = [];
    chatMessages.forEach(msg => {
      const date = new Date(msg.timestamp);
      const today = new Date();
      const yesterday = new Date();
      yesterday.setDate(yesterday.getDate() - 1);
      let label = date.toLocaleDateString(undefined, { day: 'numeric', month: 'long', year: 'numeric' });
      if (date.toDateString() === today.toDateString()) label = "Today";
      else if (date.toDateString() === yesterday.toDateString()) label = "Yesterday";
      const lastGroup = groups[groups.length - 1];
      if (lastGroup && lastGroup.dateLabel === label) lastGroup.items.push(msg);
      else groups.push({ dateLabel: label, items: [msg] });
    });
    return groups;
  }, [chatMessages]);

  useEffect(() => {
    if (selectedCitizen && !selectedCitizen.isGroup) onReadMessages(selectedCitizen.username);
    requestAnimationFrame(() => {
      chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    });
  }, [selectedCitizen, messages.length]);

  const handleSend = () => {
    if (!input.trim() || !selectedCitizen) return;
    onSendMessage(selectedCitizen.username, input, { 
      isGroup: selectedCitizen.isGroup, 
      recipients: selectedCitizen.recipients, 
      groupName: selectedCitizen.displayName,
      replyToId: replyingTo?.id,
      replyToText: replyingTo?.text,
      replyToSender: replyingTo?.sender
    });
    setInput('');
    setReplyingTo(null);
  };

  const handleCreateGroup = () => {
    if (!groupName.trim() || selectedForGroup.length < 1) return;
    const groupId = 'group_' + Math.random().toString(36).substr(2, 9);
    const recipients = [...selectedForGroup, currentUser.username];
    onSendMessage(groupId, `CITIZEN TERMINAL: Group "${groupName}" initialized.`, { isGroup: true, recipients, groupName });
    setSelectedCitizen({ username: groupId, displayName: groupName, isGroup: true, recipients });
    setIsCreatingGroup(false);
    setGroupName('');
    setGroupSearchTerm('');
    setSelectedForGroup([]);
  };

  return (
    <div className="flex flex-col h-full overflow-hidden gap-4">
      <div className="flex justify-between items-center px-2 shrink-0">
        <h2 className={`text-2xl md:text-3xl font-black italic uppercase tracking-tighter ${isDarkMode ? 'text-white' : 'text-slate-900'}`}>Citizen Hub</h2>
