                        return (
                          <div key={m.id} className="flex justify-center my-4">
                            <span className={`bg-black/5 dark:bg-white/5 px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest ${isDarkMode ? 'text-white/40' : 'text-black'}`}>{m.text}</span>
