import React, { useState, useMemo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Heart, Send, Sparkles, Brain, Clock, Globe, Users, Trophy, MessageSquare, Repeat, Reply, ShieldAlert } from 'lucide-react';
import { User, Post, Comment } from '../types';
import MoodPetSection from './MoodPetSection';
import { STREAK_BADGES } from '../constants';
import { checkContentSafety } from '../services/geminiService';

interface MoodSectionProps {
  user: User;
  posts: Post[];
  onPost: (content: string, visibility: 'global' | 'circle') => void;
  onHeart: (postId: string) => void;
  onComment: (postId: string, text: string) => void;
  onCommentInteraction: (postId: string, commentId: string, action: 'heart' | 'reply', replyText?: string) => void;
  onRepost: (post: Post) => void;
  onFollow: (username: string) => void;
  onBlock: (username: string) => void;
  isDarkMode: boolean;
  onNavigateToProfile: (username: string) => void;
  onUpdatePet: (hunger: number, thirst: number, rest: number, coins: number, exp?: number, sleepUntil?: number | null, newEmoji?: string, markChosen?: boolean, newName?: string, gameCooldownId?: string) => void;
  onViolation: (reason: string) => void;
}

const MoodSection: React.FC<MoodSectionProps> = ({ user, posts, onPost, onHeart, onComment, onCommentInteraction, onRepost, onFollow, onBlock, isDarkMode, onNavigateToProfile, onUpdatePet, onViolation }) => {
  const [subTab, setSubTab] = useState<'Express' | 'Teller' | 'Scan' | 'Mood Pet'>('Express');
  const [postContent, setPostContent] = useState('');
  const [feedFilter, setFeedFilter] = useState<'Global' | 'Circle'>('Global');
  const [postVisibility, setPostVisibility] = useState<'global' | 'circle'>('global');
  const [isBroadcasting, setIsBroadcasting] = useState(false);

  const [tellerQuestion, setTellerQuestion] = useState('');
  const [tellerResponse, setTellerResponse] = useState('');
  const [isTellerLoading, setIsTellerLoading] = useState(false);

  const [quizActive, setQuizActive] = useState(false);
  const [quizStep, setQuizStep] = useState(0);
  const [quizScores, setQuizScores] = useState<Record<string, number>>({ Happy: 0, Angry: 0, Tired: 0, Normal: 0, Excited: 0 });
  const [quizResult, setQuizResult] = useState<string | null>(null);

  const [expandedPostId, setExpandedPostId] = useState<string | null>(null);
  const [commentInputs, setCommentInputs] = useState<Record<string, string>>({});
  const [replyingTo, setReplyingTo] = useState<{ postId: string, commentId: string } | null>(null);
  const [replyContent, setReplyContent] = useState('');

  const filteredPosts = useMemo(() => {
    const allUsers: User[] = JSON.parse(localStorage.getItem('mooderia_all_users') || '[]');
    const usersWhoBlockedMe = allUsers.filter(u => u.blockedUsers.includes(user.username)).map(u => u.username);

    let result = posts.filter(p => 
      !user.blockedUsers.includes(p.author) && 
      !usersWhoBlockedMe.includes(p.author)
    );

    if (feedFilter === 'Global') {
      return result.filter(p => p.visibility === 'global');
    }
    return result.filter(p => p.visibility === 'circle' && (user.following.includes(p.author) || p.author === user.username));
  }, [posts, feedFilter, user.following, user.username, user.blockedUsers]);

  const earnedBadges = useMemo(() => STREAK_BADGES.filter(b => user.moodStreak >= b.threshold), [user.moodStreak]);

  const handlePost = async () => {
    if (!postContent.trim() || isBroadcasting) return;
    setIsBroadcasting(true);
    const safety = await checkContentSafety(postContent);
    if (safety.isInappropriate) {
      onViolation(safety.reason);
      setIsBroadcasting(false);
      return;
    }
    onPost(postContent, postVisibility);
    setPostContent('');
    setIsBroadcasting(false);
  };

  const handleAddComment = (postId: string) => {
    const text = commentInputs[postId];
    if (!text?.trim()) return;
    onComment(postId, text);
    setCommentInputs(prev => ({ ...prev, [postId]: '' }));
  };

  const handleReply = (postId: string, commentId: string) => {
    if (!replyContent.trim()) return;
    onCommentInteraction(postId, commentId, 'reply', replyContent);
    setReplyContent('');
    setReplyingTo(null);
  };

  const renderComment = (postId: string, comment: Comment, depth = 0) => (
    <div key={comment.id} className={`mt-5 ${depth > 0 ? 'ml-8 md:ml-12 border-l-4 border-black/5 pl-5' : ''}`}>
      <div className="flex items-start gap-4">
        <button onClick={() => onNavigateToProfile(comment.author)} className="w-10 h-10 rounded-xl bg-custom text-white font-black flex items-center justify-center shrink-0 text-sm italic shadow-sm">{comment.author[0].toUpperCase()}</button>
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2 mb-1">
            <span className="font-black text-[11px] uppercase tracking-tight">@{comment.author}</span>
            <span className="text-[8px] font-black opacity-30 uppercase tracking-[0.2em]">{new Date(comment.timestamp).toLocaleDateString()}</span>
          </div>
          <p className="text-[13px] font-bold opacity-80 leading-relaxed italic">"{comment.text}"</p>
          <div className="flex items-center gap-5 mt-3">
            <button onClick={() => onCommentInteraction(postId, comment.id, 'heart')} className="flex items-center gap-1.5 text-[9px] font-black uppercase text-custom transition-all active:scale-95"><Heart size={14} fill={comment.hearts > 0 ? "currentColor" : "none"} /> {comment.hearts} Sync</button>
            <button 
              onClick={() => setReplyingTo(replyingTo?.commentId === comment.id ? null : { postId, commentId: comment.id })} 
              className="flex items-center gap-1.5 text-[9px] font-black uppercase text-blue-500 transition-all active:scale-95"
            >
              <Reply size={14} /> Echo
            </button>
          </div>

          <AnimatePresence>
            {replyingTo?.commentId === comment.id && (
              <motion.div initial={{ height: 0, opacity: 0 }} animate={{ height: 'auto', opacity: 1 }} exit={{ height: 0, opacity: 0 }} className="mt-4 overflow-hidden">
                <div className="flex gap-2">
                  <input 
                    autoFocus
                    type="text" 
                    value={replyContent} 
                    onChange={e => setReplyContent(e.target.value)}
                    placeholder="Echo back..."
                    className={`flex-1 p-3 rounded-2xl border-2 text-[11px] font-bold outline-none focus:border-custom ${isDarkMode ? 'bg-slate-800 border-slate-700 text-white' : 'bg-gray-50 border-gray-100'}`}
                    onKeyPress={e => e.key === 'Enter' && handleReply(postId, comment.id)}
                  />
                  <button onClick={() => handleReply(postId, comment.id)} className="bg-custom text-white px-4 rounded-2xl shadow-md transition-transform active:scale-95"><Send size={14} /></button>
                </div>
              </motion.div>
            )}
          </AnimatePresence>
        </div>
      </div>
      {comment.replies && comment.replies.map(reply => renderComment(postId, reply, depth + 1))}
    </div>
  );

  const handleTeller = () => {
    if (!tellerQuestion.trim()) return;
    setIsTellerLoading(true);
    setTimeout(() => {
      const rand = Math.random();
      let result = '';
      if (rand < 0.2) result = 'YES. The stars have spoken!';
      else if (rand < 0.4) result = 'NO. The frequency is blocked.';
      else if (rand < 0.6) result = 'MAYBE. The vibes are still charging.';
      else if (rand < 0.8) result = 'SUPER YES! The universe is screaming it!';
      else result = 'SUPER NO! Not in this city, or any other.';
      setTellerResponse(result);
      setIsTellerLoading(false);
    }, 1200);
  };

  const startQuiz = () => {
    setQuizActive(true);
    setQuizStep(0);
    setQuizScores({ Happy: 0, Angry: 0, Tired: 0, Normal: 0, Excited: 0 });
    setQuizResult(null);
  };

  const QUIZ_STEPS = [
    { q: "How happy do you feel right now?", options: ["Very!", "A little", "Not much", "Not at all"], scores: ["Happy", "Normal", "Tired", "Angry"] },
    { q: "Are you feeling sleepy?", options: ["No, I'm awake!", "A tiny bit", "I need a nap", "I'm a zombie"], scores: ["Excited", "Normal", "Tired", "Tired"] },
    { q: "Are you mad at anyone?", options: ["No, I'm chill", "Just a bit", "Maybe one person", "I'm so angry!"], scores: ["Happy", "Normal", "Angry", "Angry"] },
    { q: "Do you feel excited about today?", options: ["Yes, so much!", "Maybe a bit", "Not really", "Zero excitement"], scores: ["Excited", "Excited", "Normal", "Tired"] },
    { q: "How fast is your brain working?", options: ["Super fast!", "Normal speed", "A bit slow", "It's stuck"], scores: ["Excited", "Normal", "Tired", "Normal"] },
    { q: "Do you want to hug a pet?", options: ["Yes, please!", "Sure", "Not really", "No way"], scores: ["Happy", "Happy", "Normal", "Angry"] },
    { q: "How much do you like today?", options: ["I love it!", "It's okay", "It's boring", "I hate it"], scores: ["Happy", "Normal", "Tired", "Angry"] },
    { q: "Are you busy right now?", options: ["Very busy!", "A little bit", "Not at all", "I'm bored"], scores: ["Excited", "Normal", "Happy", "Tired"] },
    { q: "Do you feel like dancing?", options: ["Yes, right now!", "Maybe later", "No, too tired", "Not my vibe"], scores: ["Excited", "Happy", "Tired", "Normal"] },
    { q: "Pick your favorite color!", options: ["Yellow", "Blue", "Red", "Green"], scores: ["Happy", "Tired", "Angry", "Normal"] }
  ];

  const handleQuizChoice = (idx: number) => {
    const currentStep = QUIZ_STEPS[quizStep];
    const moodKey = currentStep.scores[idx];
    const updatedScores = { ...quizScores };
    if (moodKey) {
      updatedScores[moodKey] = (updatedScores[moodKey] || 0) + 1;
      setQuizScores(updatedScores);
    }
    const nextStep = quizStep + 1;
    if (nextStep < QUIZ_STEPS.length) setQuizStep(nextStep);
    else {
      const sortedEntries = Object.entries(updatedScores).sort((a, b) => (b[1] as number) - (a[1] as number));
      setQuizResult(sortedEntries[0][0]);
    }
  };

  const formatTime = (ts: number) => {
    const diff = Date.now() - ts;
    if (diff < 60000) return 'Just now';
    if (diff < 3600000) return `${Math.floor(diff / 60000)}m ago`;
    return new Date(ts).toLocaleDateString();
  };

  return (
    <div className="flex flex-col gap-8 pb-20">
      <AnimatePresence>
        {earnedBadges.length > 0 && subTab === 'Express' && (
          <motion.div initial={{ y: -20, opacity: 0 }} animate={{ y: 0, opacity: 1 }} exit={{ y: -20, opacity: 0 }} className={`p-5 md:p-8 rounded-[3rem] ${isDarkMode ? 'bg-slate-900 border-green-500/20' : 'bg-white border-green-500/10'} border-4 shadow-xl flex items-center gap-6 overflow-x-auto no-scrollbar`}>
            <div className="flex items-center gap-3 bg-green-500 text-white px-5 py-3 rounded-2xl shadow-lg border-b-6 border-green-700 shrink-0">
              <Trophy size={22} /> <span className="text-[11px] font-black uppercase tracking-widest leading-none">Resonance Rank</span>
            </div>
            <div className="flex gap-4 min-w-max">
              {earnedBadges.map(b => (
                <div key={b.id} className="flex flex-col items-center justify-center p-4 bg-black/5 rounded-[2rem] border-2 border-black/5 w-24">
                  <span className="text-4xl mb-2">{b.icon}</span>
                  <span className="text-[9px] font-black uppercase text-center leading-none tracking-tighter">{b.name}</span>
                </div>
              ))}
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      <div className="flex gap-3 overflow-x-auto no-scrollbar pb-3 px-1">
        {['Express', 'Teller', 'Scan', 'Mood Pet'].map((t) => (
          <button key={t} onClick={() => setSubTab(t as any)} className={`px-8 py-4 rounded-3xl font-black text-xs transition-all whitespace-nowrap uppercase tracking-tighter border-b-6 ${subTab === t ? 'bg-custom border-black/20 text-white shadow-xl translate-y-[-4px]' : isDarkMode ? 'bg-slate-800 border-slate-900 text-white/30' : 'bg-white border-gray-100 text-slate-500 shadow-sm'}`}>
            {t}
          </button>
        ))}
      </div>

      <div className="px-1">
        <AnimatePresence mode="wait">
          {subTab === 'Express' && (
            <motion.div key="express" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="space-y-8">
              <div className={`p-8 md:p-10 rounded-[3.5rem] ${isDarkMode ? 'bg-slate-900' : 'bg-white'} border-4 border-black/5 shadow-2xl`}>
                <textarea 
                  value={postContent} 
                  onChange={(e) => setPostContent(e.target.value)} 
                  disabled={isBroadcasting}
                  placeholder={isBroadcasting ? "Scanning Signal..." : (postVisibility === 'global' ? "Transmit a global frequency..." : "Whisper to your circle...")} 
                  className={`w-full ${isDarkMode ? 'bg-slate-800 text-white' : 'bg-gray-50 text-slate-900'} p-8 rounded-[2.5rem] border-4 border-black/5 focus:border-custom outline-none font-bold text-xl shadow-inner min-h-[160px] resize-none transition-all`} 
                />
                <div className="flex flex-col md:flex-row justify-between items-center mt-8 gap-6">
                  <div className="flex gap-3 bg-black/5 p-2 rounded-2xl w-full md:w-auto">
                    <button onClick={() => setPostVisibility('global')} className={`flex-1 md:flex-none flex items-center justify-center gap-2 px-6 py-3 rounded-xl text-[11px] font-black uppercase transition-all ${postVisibility === 'global' ? 'bg-custom text-white shadow-md' : 'opacity-40 hover:opacity-100'}`}><Globe size={16}/> GLOBAL</button>
                    <button onClick={() => setPostVisibility('circle')} className={`flex-1 md:flex-none flex items-center justify-center gap-2 px-6 py-3 rounded-xl text-[11px] font-black uppercase transition-all ${postVisibility === 'circle' ? 'bg-custom text-white shadow-md' : 'opacity-40 hover:opacity-100'}`}><Users size={16}/> CIRCLE</button>
                  </div>
                  <button 
                    onClick={handlePost} 
                    disabled={isBroadcasting}
                    className="kahoot-button-custom w-full md:w-auto px-12 py-5 text-white rounded-[2rem] font-black text-sm flex items-center justify-center gap-3 active:scale-95 transition-transform disabled:opacity-50 shadow-xl"
                  >
                    {isBroadcasting ? <Clock size={22} className="animate-spin" /> : <Send size={22} />} 
                    {isBroadcasting ? 'SCANNIG...' : 'BROADCAST'}
                  </button>
                </div>
              </div>

              <div className="flex gap-3 bg-black/5 p-1.5 rounded-2xl w-fit ml-2">
                <button onClick={() => setFeedFilter('Global')} className={`px-6 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${feedFilter === 'Global' ? 'bg-white text-custom shadow-md' : 'opacity-40 hover:opacity-100'}`}>Metropolis Feed</button>
