                  <motion.div key={post.id} initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} className={`p-8 rounded-[3.5rem] ${isDarkMode ? 'bg-slate-900 text-white' : 'bg-white text-slate-900'} border-4 border-black/5 shadow-xl transition-all hover:shadow-2xl`}>
                    <div className="flex items-center justify-between mb-6">
                      <div className="flex items-center gap-4">
                        <button onClick={() => onNavigateToProfile(post.author)} className="w-14 h-14 rounded-2xl bg-custom text-white font-black shrink-0 text-2xl flex items-center justify-center italic shadow-lg border-2 border-white/20">{post.author[0].toUpperCase()}</button>
