                          <h4 className="font-black text-base italic uppercase tracking-tighter">@{post.author}</h4>
                          <p className="text-[10px] font-black opacity-30 uppercase tracking-[0.2em] flex items-center gap-1.5"><Clock size={12}/> {formatTime(post.timestamp)}</p>
                        </div>
                      </div>
                    </div>
                    {post.isRepost && <div className="flex items-center gap-2 text-[11px] font-black text-green-500 uppercase italic mb-4 bg-green-500/5 px-4 py-1.5 rounded-xl w-fit"><Repeat size={14}/> Echoing: @{post.originalAuthor}</div>}
