                      <button onClick={() => setExpandedPostId(expandedPostId === post.id ? null : post.id)} className="flex items-center gap-2 text-blue-500 font-black text-[11px] uppercase tracking-widest transition-all active:scale-95"><MessageSquare size={20} /> {post.comments?.length || 0} ECHO</button>
