               <button onClick={handleTeller} disabled={isTellerLoading} className="kahoot-button-custom px-12 md:px-20 py-5 md:py-6 rounded-3xl text-white font-black uppercase text-base md:text-xl shadow-2xl active:scale-95 transition-transform">{isTellerLoading ? 'CALCULATING...' : 'CONSULT ORACLE'}</button>
               {tellerResponse && (
                 <motion.div initial={{ y: 20, opacity: 0, scale: 0.9 }} animate={{ y: 0, opacity: 1, scale: 1 }} className="mt-12 p-8 md:p-12 rounded-[3rem] bg-custom/5 border-l-[16px] border-custom italic font-bold text-xl md:text-3xl max-w-2xl shadow-xl leading-tight">
                   "{tellerResponse}"
                 </motion.div>
               )}
            </motion.div>
          )}

          {subTab === 'Scan' && (
            <motion.div key="scan" initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: 20 }} className={`p-10 md:p-16 rounded-[4rem] ${isDarkMode ? 'bg-slate-900' : 'bg-white'} border-4 border-black/5 shadow-2xl text-center flex flex-col items-center`}>
               <div className="bg-blue-500/10 p-8 rounded-[3rem] mb-8 shadow-inner border-2 border-blue-500/5"><Brain className="text-blue-500" size={80} /></div>
               <h2 className="text-3xl md:text-5xl font-black mb-8 uppercase italic tracking-tighter">Emotional Scan</h2>
               {!quizActive ? (
                 <>
                   <p className="opacity-40 font-black uppercase tracking-[0.3em] text-[11px] md:text-xs mb-12 max-w-md leading-relaxed">Map your unique neural signature in 10 quick resonance steps.</p>
                   <button onClick={startQuiz} className="kahoot-button-blue px-12 py-6 rounded-3xl text-white font-black uppercase text-base md:text-xl shadow-2xl transition-all">Start Neural Scan</button>
                 </>
               ) : (
                 <div className="w-full max-w-xl space-y-12">
                   {quizResult ? (
                     <div className="space-y-10 py-6">
                        <motion.div animate={{ scale: [1, 1.2, 1], rotate: [0, 5, -5, 0] }} transition={{ repeat: Infinity, duration: 4 }} className="text-8xl md:text-9xl mb-6">✨</motion.div>
                        <h3 className="text-3xl md:text-4xl font-black italic uppercase tracking-tighter">Scan Finalized</h3>
                        <div className="p-8 md:p-12 rounded-[3rem] bg-custom/5 border-4 border-custom/20 shadow-inner">
                          <p className="text-[11px] font-black opacity-50 uppercase tracking-[0.4em] mb-4">Frequency Result</p>
                          <p className="text-4xl md:text-6xl font-black text-custom italic uppercase tracking-tighter">{quizResult}</p>
                        </div>
                        <button onClick={() => setQuizActive(false)} className="kahoot-button-custom px-10 py-5 rounded-2xl text-white font-black uppercase text-sm shadow-xl">Recalibrate Scan</button>
                     </div>
                   ) : (
                     <div className="space-y-12">
                        <div className="h-4 bg-black/5 rounded-full overflow-hidden shadow-inner p-1"><motion.div className="h-full bg-blue-500 rounded-full shadow-lg" initial={{ width: 0 }} animate={{ width: `${((quizStep + 1) / QUIZ_STEPS.length) * 100}%` }} /></div>
                        <div className="px-4">
                          <p className="text-2xl md:text-4xl font-black italic tracking-tight leading-tight">"{QUIZ_STEPS[quizStep].q}"</p>
                        </div>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
                           {QUIZ_STEPS[quizStep].options.map((opt, i) => (
                             <button key={opt} onClick={() => handleQuizChoice(i)} className="kahoot-button-custom py-5 md:py-6 rounded-2xl text-white font-black uppercase text-xs md:text-sm active:scale-95 transition-transform shadow-lg">{opt}</button>
                           ))}
                        </div>
                        <p className="text-[11px] font-black uppercase opacity-30 tracking-[0.3em] bg-black/5 py-2 px-4 rounded-full w-fit mx-auto">Neural Step {quizStep + 1} / {QUIZ_STEPS.length}</p>
                     </div>
                   )}
                 </div>
               )}
            </motion.div>
          )}

          {subTab === 'Mood Pet' && (
            <motion.div key="pet" initial={{ opacity: 0, scale: 0.98 }} animate={{ opacity: 1, scale: 1 }} exit={{ opacity: 0, scale: 0.98 }}>
               <MoodPetSection user={user} isDarkMode={isDarkMode} onUpdate={onUpdatePet} onPost={onPost} />
            </motion.div>
          )}
        </AnimatePresence>
      </div>
    </div>
  );
};

