import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { User } from '../types';
import LoadingScreen from '../components/LoadingScreen';

interface AuthScreenProps {
  onLogin: (user: User) => void;
}

const AuthScreen: React.FC<AuthScreenProps> = ({ onLogin }) => {
  const [isSignUp, setIsSignUp] = useState(false);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [displayName, setDisplayName] = useState('');
  const [username, setUsername] = useState('');
  const [error, setError] = useState('');
  const [isAuthenticating, setIsAuthenticating] = useState(false);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    const allUsersStr = localStorage.getItem('mooderia_all_users') || '[]';
    const allUsers: User[] = JSON.parse(allUsersStr);

    if (isSignUp) {
      const userExists = allUsers.some(u => u.email.toLowerCase() === email.toLowerCase() || u.username.toLowerCase() === username.toLowerCase());
      if (userExists) {
        setError('This identity already exists in the metropolis.');
        return;
      }

      const newUser: User = {
        displayName: displayName,
        username: username,
        email: email,
        password: password,
        followers: [],
        following: [],
        friends: [],
        blockedUsers: [],
        posts: [],
        reposts: [],
        moodHistory: [],
        moodStreak: 0,
        title: email.toLowerCase() === 'travismiguel014@gmail.com' ? 'Creator' : 'Citizen',
        likesReceived: 0,
        petName: 'Guardian',
        moodCoins: 100,
        petEmoji: '🐱',
        petHunger: 100,
        petThirst: 100,
        petRest: 100,
        petLevel: 1,
        petExp: 0,
        petHasBeenChosen: false,
        petLastUpdate: Date.now(),
        petSleepUntil: null,
        gameCooldowns: {},
        warnings: 0,
        isBanned: false
      };

      allUsers.push(newUser);
      localStorage.setItem('mooderia_all_users', JSON.stringify(allUsers));

      setIsAuthenticating(true);
      setTimeout(() => {
        localStorage.setItem('mooderia_user', JSON.stringify(newUser));
        onLogin(newUser);
      }, 1500);
    } else {
      const existingUser = allUsers.find(u => u.email.toLowerCase() === email.toLowerCase() && u.password === password);

      if (existingUser) {
        setIsAuthenticating(true);
        setTimeout(() => {
          localStorage.setItem('mooderia_user', JSON.stringify(existingUser));
          onLogin(existingUser);
        }, 1200);
      } else {
        setError('Credentials invalid. Access denied.');
      }
    }
  };

  if (isAuthenticating) return <LoadingScreen />;

  return (
    <div className="min-h-screen flex items-center justify-center bg-[#46178f] p-6 relative overflow-hidden">
      {/* Background Watermark Pattern */}
      <div className="absolute inset-0 opacity-10 pointer-events-none overflow-hidden select-none">
        {Array.from({ length: 20 }).map((_, i) => (
          <div key={i} className="absolute text-white font-black italic opacity-20 rotate-12 text-6xl md:text-9xl tracking-tighter" style={{ top: `${Math.random() * 100}%`, left: `${Math.random() * 100}%` }}>MOODERIA</div>
        ))}
      </div>

      <motion.div 
        initial={{ y: 50, opacity: 0 }} 
        animate={{ y: 0, opacity: 1 }} 
        className="w-full max-w-md bg-slate-900 border-4 border-white/10 rounded-[4rem] shadow-[0_40px_100px_rgba(0,0,0,0.6)] p-10 md:p-14 z-10 text-white"
      >
        <div className="text-center mb-12">
          <h1 className="text-5xl md:text-6xl font-black italic text-white tracking-tighter mb-4 uppercase leading-none select-none">
            Mooderia
          </h1>
          <div className="h-1.5 w-16 bg-blue-500 mx-auto rounded-full mb-4 shadow-[0_0_15px_rgba(59,130,246,0.5)]" />
          <p className="text-blue-400 font-black uppercase tracking-[0.4em] text-[10px] opacity-80">Neural Access Terminal</p>
        </div>

        <form onSubmit={handleSubmit} className="space-y-6">
          <AnimatePresence mode="wait">
            {isSignUp && (
              <motion.div 
                key="signup" 
                initial={{ height: 0, opacity: 0, y: -20 }} 
                animate={{ height: 'auto', opacity: 1, y: 0 }} 
                exit={{ height: 0, opacity: 0, y: -20 }} 
                className="space-y-5 overflow-hidden"
              >
                <div className="space-y-1.5">
                  <p className="text-[10px] font-black uppercase opacity-40 ml-3 tracking-widest">Public Alias</p>
                  <input type="text" placeholder="e.g. Alex Vibe" required value={displayName} onChange={(e) => setDisplayName(e.target.value)} className="w-full p-4 md:p-5 rounded-2xl bg-slate-800 text-white border-2 border-slate-700 focus:border-blue-500 outline-none font-bold text-sm transition-all shadow-inner" />
                </div>
                <div className="space-y-1.5">
                  <p className="text-[10px] font-black uppercase opacity-40 ml-3 tracking-widest">Network Handle</p>
                  <input type="text" placeholder="e.g. alex_v" required value={username} onChange={(e) => setUsername(e.target.value)} className="w-full p-4 md:p-5 rounded-2xl bg-slate-800 text-white border-2 border-slate-700 focus:border-blue-500 outline-none font-bold text-sm transition-all shadow-inner" />
                </div>
              </motion.div>
            )}
          </AnimatePresence>

          <div className="space-y-1.5">
            <p className="text-[10px] font-black uppercase opacity-40 ml-3 tracking-widest">Neural Email</p>
            <input type="email" placeholder="email@mooderia.city" required value={email} onChange={(e) => setEmail(e.target.value)} className="w-full p-4 md:p-5 rounded-2xl bg-slate-800 text-white border-2 border-slate-700 focus:border-blue-500 outline-none font-bold text-sm transition-all shadow-inner" />
          </div>

          <div className="space-y-1.5">
            <p className="text-[10px] font-black uppercase opacity-40 ml-3 tracking-widest">Secret Sequence</p>
            <input type="password" placeholder="••••••••" required value={password} onChange={(e) => setPassword(e.target.value)} className="w-full p-4 md:p-5 rounded-2xl bg-slate-800 text-white border-2 border-slate-700 focus:border-blue-500 outline-none font-bold text-sm transition-all shadow-inner" />
          </div>

          {error && (
            <motion.p initial={{ opacity: 0, scale: 0.95 }} animate={{ opacity: 1, scale: 1 }} className="text-[#e21b3c] text-[11px] font-black text-center bg-red-500/10 p-5 rounded-2xl border-2 border-red-500/20 uppercase italic tracking-tight">
              {error}
            </motion.p>
          )}

          <button type="submit" className="kahoot-button-blue w-full p-5 md:p-6 rounded-[2rem] text-white font-black text-xl mt-6 shadow-2xl active:scale-95 uppercase tracking-tighter transition-all border-b-6 border-[#0e4c99]">
            {isSignUp ? 'Authorize ID' : 'Synchronize'}
          </button>
        </form>

        <div className="mt-12 pt-10 border-t border-white/5 text-center">
          <button onClick={() => { setIsSignUp(!isSignUp); setError(''); }} className="text-xs font-black text-blue-400 hover:text-white transition-all uppercase tracking-[0.25em] opacity-60 hover:opacity-100">
            {isSignUp ? 'Already a citizen? Synchronize' : "Apply for Citizenship"}
          </button>
        </div>
      </motion.div>
    </div>
  );
};

