import React, { useMemo } from 'react';
import { User, Post } from '../types';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';
import { Flame, Award, TrendingUp, ShieldCheck, Sparkles, Clock } from 'lucide-react';
import { STREAK_BADGES, DAILY_WISDOM } from '../constants';

interface HomeSectionProps {
  user: User;
  posts: Post[];
  isDarkMode: boolean;
}

const HomeSection: React.FC<HomeSectionProps> = ({ user, posts, isDarkMode }) => {
  const currentMood = user.moodHistory?.[user.moodHistory.length - 1]?.mood || 'Not set';
  const earnedBadges = STREAK_BADGES.filter(b => user.moodStreak >= b.threshold);

  const todayWisdom = useMemo(() => {
    const today = new Date();
    const seed = today.getFullYear() * 10000 + (today.getMonth() + 1) * 100 + today.getDate();
    return DAILY_WISDOM[seed % DAILY_WISDOM.length];
  }, []);

  const chartData = useMemo(() => {
    if (!user.moodHistory || user.moodHistory.length === 0) return [{ name: 'New', score: 0 }];
    return user.moodHistory.slice(-7).map((entry, idx) => ({ name: `T${idx + 1}`, score: entry.score }));
  }, [user.moodHistory]);

  const happiness = useMemo(() => {
    if (!user.moodHistory || user.moodHistory.length === 0) return 0;
    const recent = user.moodHistory.slice(-5);
    return Math.round(recent.reduce((acc, curr) => acc + curr.score, 0) / recent.length);
  }, [user.moodHistory]);

  return (
    <div className="space-y-10 pb-12">
      {/* Top Header / Greeting */}
      <div className="flex flex-col lg:flex-row justify-between items-start lg:items-end gap-8 border-b-4 border-black/5 pb-10">
        <div className="text-left w-full">
          <h2 className={`text-5xl md:text-6xl font-black italic tracking-tighter uppercase leading-none ${isDarkMode ? 'text-white' : 'text-slate-900'}`}>
            Hi, {user.displayName}!
          </h2>
          <p className="opacity-40 font-black uppercase tracking-[0.3em] text-[11px] md:text-xs mt-4 flex items-center gap-2">
            <Award size={14} className="text-custom"/> Metropolis Designation: {user.title}
          </p>
        </div>

        <div className="flex flex-wrap gap-4 w-full md:w-auto justify-start md:justify-end shrink-0">
          <div className="flex items-center gap-3 px-6 py-4 rounded-[2rem] bg-[#ffa602] text-white font-black shadow-xl streak-glow border-b-6 border-[#cc8502]">
            <Flame className="animate-pulse" size={26} />
            <span className="uppercase text-lg tracking-tighter">{user.moodStreak || 0} Day Streak</span>
          </div>
          <div className={`flex items-center gap-3 px-6 py-4 rounded-[2rem] border-4 font-black shadow-md ${isDarkMode ? 'bg-slate-800 border-purple-400 text-purple-400' : 'bg-white border-[#46178f] text-[#46178f]'}`}>
            <Clock size={20} className="opacity-40"/>
            <span className="uppercase italic text-lg tracking-tighter">{currentMood}</span>
          </div>
        </div>
      </div>

      {/* Badges Carousel */}
      {earnedBadges.length > 0 && (
        <div className={`p-8 rounded-[3.5rem] ${isDarkMode ? 'bg-[#111111]' : 'bg-white'} shadow-2xl border-4 border-green-400/30 overflow-x-auto no-scrollbar`}>
           <div className="flex items-center gap-8">
              <div className="flex flex-col gap-1 shrink-0">
                <ShieldCheck className="text-green-500" size={44} />
                <span className="text-[9px] font-black uppercase text-green-500/60 tracking-widest text-center">Badges</span>
              </div>
              <div className="flex gap-6 min-w-max pb-2">
                 {earnedBadges.map(badge => (
                   <div key={badge.id} className="flex flex-col items-center justify-center bg-green-500/10 p-5 rounded-[2.5rem] border-2 border-green-500/20 w-28 hover:scale-105 transition-transform cursor-help">
                      <span className="text-5xl mb-3 drop-shadow-sm">{badge.icon}</span>
                      <span className="text-[10px] font-black uppercase tracking-tighter text-center leading-none">{badge.name}</span>
                   </div>
                 ))}
              </div>
           </div>
        </div>
      )}

      {/* Primary Stats Grid */}
      <div className="grid grid-cols-2 md:grid-cols-3 gap-6">
        <div className={`p-10 rounded-[4rem] ${isDarkMode ? 'bg-[#111111]' : 'bg-white'} shadow-2xl border-b-[14px] border-blue-500/10 relative overflow-hidden group`}>
          <div className="absolute -right-4 -bottom-4 opacity-5 group-hover:opacity-10 transition-opacity"><TrendingUp size={120}/></div>
          <p className="text-[11px] font-black opacity-30 uppercase tracking-[0.4em] mb-6">Metropolis Circle</p>
          <p className="text-6xl font-black text-[#1368ce] italic tracking-tighter">{user.following.length}</p>
        </div>
        <div className={`p-10 rounded-[4rem] ${isDarkMode ? 'bg-[#111111]' : 'bg-white'} shadow-2xl border-b-[14px] border-green-500/10 relative overflow-hidden group`}>
          <div className="absolute -right-4 -bottom-4 opacity-5 group-hover:opacity-10 transition-opacity"><Award size={120}/></div>
          <p className="text-[11px] font-black opacity-30 uppercase tracking-[0.4em] mb-6">Citizen Resonance</p>
          <p className="text-6xl font-black text-[#26890c] italic tracking-tighter">{user.followers.length}</p>
        </div>
        <div className={`col-span-2 md:col-span-1 p-10 rounded-[4rem] ${isDarkMode ? 'bg-[#111111]' : 'bg-white'} shadow-2xl border-b-[14px] border-red-500/10 relative overflow-hidden group`}>
          <div className="absolute -right-4 -bottom-4 opacity-5 group-hover:opacity-10 transition-opacity"><Sparkles size={120}/></div>
          <p className="text-[11px] font-black opacity-30 uppercase tracking-[0.4em] mb-6">Harmony Frequency</p>
          <div className="flex items-center gap-4">
            <p className="text-6xl font-black text-[#e21b3c] italic tracking-tighter">{happiness}%</p>
          </div>
        </div>
      </div>

      {/* Chart Section */}
      <div className={`p-10 rounded-[4.5rem] ${isDarkMode ? 'bg-[#111111]' : 'bg-white'} shadow-2xl overflow-hidden border-4 border-black/5`}>
        <div className="flex flex-col md:flex-row justify-between items-center mb-12 gap-6 px-4">
          <h3 className="text-3xl font-black uppercase italic flex items-center gap-5 tracking-tighter">
            <div className="p-3 bg-custom/10 rounded-2xl"><TrendingUp className="text-custom" size={32} /></div>
            Emotional Spectrum
          </h3>
          <div className="bg-custom/10 px-8 py-3 rounded-full border-2 border-custom/20 shadow-inner">
            <span className="text-custom font-black text-xs uppercase tracking-[0.2em]">Latest Synchronization: {chartData[chartData.length-1].score}</span>
          </div>
        </div>
        <div className="h-72 md:h-96 w-full">
          <ResponsiveContainer width="100%" height="100%">
            <AreaChart data={chartData}>
              <CartesianGrid strokeDasharray="8 8" vertical={false} stroke={isDarkMode ? "#222" : "#f1f1f1"} />
              <XAxis dataKey="name" hide />
              <YAxis domain={[0, 100]} hide />
              <Tooltip 
                contentStyle={{ 
                  backgroundColor: isDarkMode ? '#111' : '#fff', 
                  borderRadius: '2rem', 
                  border: '4px solid rgba(0,0,0,0.05)', 
                  fontWeight: '900', 
                  fontSize: '14px',
                  boxShadow: '0 10px 30px rgba(0,0,0,0.1)'
                }} 
              />
              <Area 
                type="step" 
                dataKey="score" 
                stroke="var(--theme-color)" 
                fill="var(--theme-color)" 
                fillOpacity={0.15} 
                strokeWidth={10} 
                animationDuration={2000}
              />
            </AreaChart>
          </ResponsiveContainer>
        </div>
      </div>

      {/* Wisdom Block */}
      <div className={`p-12 rounded-[4rem] border-l-[20px] border-[#ffa602] ${isDarkMode ? 'bg-[#111111]' : 'bg-white'} shadow-2xl relative overflow-hidden group hover:scale-[1.01] transition-all`}>
        <div className="absolute top-[-30%] right-[-10%] opacity-5 group-hover:opacity-10 transition-all rotate-12 duration-1000">
          <Award size={320} />
        </div>
        <h4 className="font-black text-3xl mb-8 uppercase italic tracking-tighter opacity-30">Frequency of the Day</h4>
        <p className="italic font-bold text-3xl md:text-5xl leading-tight opacity-95 relative z-10 tracking-tight break-words">
          "{todayWisdom}"
        </p>
        <div className="mt-10 flex items-center gap-3">
          <div className="w-2 h-2 rounded-full bg-[#ffa602] animate-ping"/>
          <span className="text-[10px] font-black uppercase tracking-[0.5em] opacity-40">Source: Metropolis Archives</span>
        </div>
      </div>
    </div>
  );
};

