      gameCooldowns: user.gameCooldowns || {},
      petHasBeenChosen: !!user.petHasBeenChosen,
      warnings: user.warnings ?? 0,
      isBanned: !!user.isBanned
    };
  };

  const profileToView = useMemo(() => {
    if (!viewingUsername) return null;
    if (currentUser && viewingUsername === currentUser.username) return currentUser;
    const allUsers: User[] = JSON.parse(localStorage.getItem('mooderia_all_users') || '[]');
    return allUsers.find(u => u.username === viewingUsername) || null;
  }, [viewingUsername, currentUser, globalUpdateToggle, allPosts]);

  const addNotification = useCallback((recipient: string, type: Notification['type'], snippet: string, postId: string = '') => {
    if (!currentUser) return;
    if (recipient === currentUser.username && type !== 'achievement' && type !== 'tier' && type !== 'warning') return;

    const newNotif: Notification = {
      id: Math.random().toString(36).substr(2, 9),
      fromUser: type === 'warning' ? 'Police Force' : (currentUser?.username || 'Metropolis'),
      recipient,
      type,
      postId,
      timestamp: Date.now(),
      read: false,
      postContentSnippet: snippet
    };
    setNotifications(prev => [...prev, newNotif]);
  }, [currentUser]);

  useEffect(() => {
    const savedUser = localStorage.getItem('mooderia_user');
    const savedPosts = localStorage.getItem('mooderia_posts') || '[]';
    const savedMessages = localStorage.getItem('mooderia_messages') || '[]';
    const savedGroups = localStorage.getItem('mooderia_groups') || '[]';
    const savedNotifications = localStorage.getItem('mooderia_notifications') || '[]';
    const savedTheme = localStorage.getItem('mooderia_theme');

    if (savedUser) {
      try {
        let user: User = JSON.parse(savedUser);
        user = migrateUserData(user);

        const now = Date.now();
        if (user.email === 'travismiguel014@gmail.com') user.title = 'Creator';

        const lastUpdate = user.petLastUpdate || now;
        const elapsedMinutes = Math.floor((now - lastUpdate) / 60000);

        if (elapsedMinutes > 0) {
          user.petHunger = Math.max(0, user.petHunger - elapsedMinutes * 0.15);
          user.petThirst = Math.max(0, user.petThirst - elapsedMinutes * 0.2);
          if (!user.petSleepUntil || user.petSleepUntil < now) {
            user.petRest = Math.max(0, user.petRest - elapsedMinutes * 0.1);
            user.petSleepUntil = null;
          }
          user.petLastUpdate = now;
        }
        setCurrentUser(user);
        setViewingUsername(user.username);
      } catch (e) { 
        localStorage.removeItem('mooderia_user');
      }
    }

    setAllPosts(JSON.parse(savedPosts));
    setAllMessages(JSON.parse(savedMessages));
    setAllGroups(JSON.parse(savedGroups));
    setNotifications(JSON.parse(savedNotifications));
    if (savedTheme === 'dark') setIsDarkMode(true);
    setIsLoaded(true);

    const timer = setTimeout(() => setIsAppStarting(false), 2000);
    return () => clearTimeout(timer);
  }, []);

  useEffect(() => {
    if (currentUser && !currentUser.isBanned && isLoaded) {
      const today = new Date().toDateString();
      if (currentUser.lastMoodDate !== today) {
        setIsMoodModalOpen(true);
      }
    }
  }, [currentUser?.username, currentUser?.lastMoodDate, isLoaded]);

  useEffect(() => {
    if (!isLoaded) return;
    if (currentUser) {
      localStorage.setItem('mooderia_user', JSON.stringify(currentUser));
      const allUsers: User[] = JSON.parse(localStorage.getItem('mooderia_all_users') || '[]');
      const idx = allUsers.findIndex(u => u.username === currentUser.username);
      if (idx > -1) { allUsers[idx] = currentUser; } 
      else { allUsers.push(currentUser); }
      localStorage.setItem('mooderia_all_users', JSON.stringify(allUsers));
    }
    localStorage.setItem('mooderia_posts', JSON.stringify(allPosts));
    localStorage.setItem('mooderia_messages', JSON.stringify(allMessages));
    localStorage.setItem('mooderia_groups', JSON.stringify(allGroups));
    localStorage.setItem('mooderia_notifications', JSON.stringify(notifications));
    localStorage.setItem('mooderia_theme', isDarkMode ? 'dark' : 'light');
    setGlobalUpdateToggle(t => t + 1);
  }, [currentUser, allPosts, allMessages, allGroups, notifications, isDarkMode, isLoaded]);

  const handleViolation = (reason: string) => {
    if (!currentUser) return;
    const newWarnings = (currentUser.warnings || 0) + 1;
    const isNowBanned = newWarnings >= 3;

    setCurrentUser({
      ...currentUser,
      warnings: newWarnings,
      isBanned: isNowBanned
    });

    addNotification(currentUser.username, 'warning', `Police Warning ${newWarnings}/3: ${reason}`);
    setActiveWarning({ count: newWarnings, reason });
  };

  const handleLogout = () => {
    localStorage.removeItem('mooderia_user');
    setCurrentUser(null);
    setViewingUsername(null);
    setActiveSection('Home');
    setIsMoodModalOpen(false);
  };

  const onLogin = (user: User) => {
    const migrated = migrateUserData(user);
    setCurrentUser(migrated);
    setViewingUsername(migrated.username);
  };

  const handleHeart = (postId: string) => {
    if (!currentUser) return;
    setAllPosts(prev => prev.map(p => {
      if (p.id === postId) {
        if (p.author !== currentUser.username) {
          addNotification(p.author, 'heart', p.content.substring(0, 20), p.id);
        }
        return { ...p, hearts: p.hearts + 1 };
      }
      return p;
    }));
  };

  const handleCommentInteraction = (postId: string, commentId: string, action: 'heart' | 'reply', replyText?: string) => {
    if (!currentUser) return;
    setAllPosts(prev => prev.map(p => {
      if (p.id === postId) {
        const updateComments = (comments: Comment[]): Comment[] => {
          return comments.map(c => {
            if (c.id === commentId) {
              if (action === 'heart') {
                if (c.author !== currentUser.username) {
                  addNotification(c.author, 'comment_heart', c.text.substring(0, 20), p.id);
                }
                return { ...c, hearts: c.hearts + 1 };
              } else if (action === 'reply' && replyText) {
                const newReply: Comment = {
                  id: Math.random().toString(36).substr(2, 9),
                  author: currentUser.username,
                  text: replyText,
                  hearts: 0,
                  timestamp: Date.now(),
                  replies: []
                };
                if (c.author !== currentUser.username) {
                  addNotification(c.author, 'reply', replyText.substring(0, 20), p.id);
                }
                return { ...c, replies: [...(c.replies || []), newReply] };
              }
            }
            if (c.replies && c.replies.length > 0) {
              return { ...c, replies: updateComments(c.replies) };
            }
            return c;
          });
        };
        return { ...p, comments: updateComments(p.comments) };
      }
      return p;
    }));
  };

  const handleRepost = (post: Post) => {
    if (!currentUser) return;
    const newPost: Post = {
      id: Math.random().toString(36).substr(2, 9),
      author: currentUser.username,
      content: post.content,
      hearts: 0,
      comments: [],
      timestamp: Date.now(),
      isRepost: true,
      originalAuthor: post.author,
      visibility: 'global'
    };
    setAllPosts(prev => [newPost, ...prev]);
    if (post.author !== currentUser.username) {
      addNotification(post.author, 'repost', post.content.substring(0, 20), newPost.id);
    }
  };

  const handleFollow = (targetUsername: string) => {
    if (!currentUser || currentUser.username === targetUsername) return;
    const isFollowing = currentUser.following.includes(targetUsername);
    if (isFollowing) {
      setCurrentUser({ ...currentUser, following: currentUser.following.filter(u => u !== targetUsername) });
    } else {
      setCurrentUser({ ...currentUser, following: [...currentUser.following, targetUsername] });
      addNotification(targetUsername, 'follow', '');
    }
  };

  const handleBlock = (targetUsername: string) => {
    if (!currentUser || currentUser.username === targetUsername) return;
    setCurrentUser({
      ...currentUser,
      blockedUsers: [...currentUser.blockedUsers, targetUsername],
      following: currentUser.following.filter(u => u !== targetUsername),
      followers: currentUser.followers.filter(u => u !== targetUsername)
    });
  };

  const updatePetStats = (hunger: number, thirst: number, rest: number, coins: number, exp: number = 0, sleepUntil: number | null = null, newEmoji?: string, markChosen?: boolean, newName?: string, gameCooldownId?: string) => {
    if (!currentUser) return;
    let newLevel = currentUser.petLevel;
    let newExp = (currentUser.petExp || 0) + exp;
    while (newExp >= getExpNeeded(newLevel)) {
      newExp -= getExpNeeded(newLevel);
      newLevel++;
      addNotification(currentUser.username, 'achievement', `Your pet reached level ${newLevel}!`);
    }
    const newCooldowns = { ...currentUser.gameCooldowns };
    if (gameCooldownId) {
      newCooldowns[gameCooldownId] = Date.now() + (5 * 60 * 1000);
    }
    setCurrentUser({
      ...currentUser,
      petHunger: Math.min(100, Math.max(0, currentUser.petHunger + hunger)),
      petThirst: Math.min(100, Math.max(0, currentUser.petThirst + thirst)),
      petRest: Math.min(100, Math.max(0, currentUser.petRest + rest)),
      moodCoins: (currentUser.moodCoins || 0) + coins,
      petLevel: newLevel,
      petExp: newExp,
      petSleepUntil: sleepUntil !== null ? sleepUntil : currentUser.petSleepUntil,
      petEmoji: newEmoji || currentUser.petEmoji,
      petHasBeenChosen: markChosen !== undefined ? markChosen : currentUser.petHasBeenChosen,
      petName: newName || currentUser.petName,
      gameCooldowns: newCooldowns
    });
  };

  const handleSendMessage = (recipient: string, text: string, options?: any) => {
    if (!currentUser) return;
    const newMessage: Message = {
      id: Math.random().toString(36).substr(2, 9),
      sender: currentUser.username,
      recipient,
      text,
      timestamp: Date.now(),
      read: false,
      isGroup: options?.isGroup || false,
      isSystem: options?.isSystem || false,
      groupName: options?.groupName,
      replyToId: options?.replyToId,
      replyToText: options?.replyToText,
      replyToSender: options?.replyToSender
    };
    setAllMessages(prev => [...prev, newMessage]);
  };

  const handleGroupUpdate = (group: Group) => {
    setAllGroups(prev => prev.map(g => g.id === group.id ? group : g));
  };

  const handleGroupCreate = (group: Group) => {
    setAllGroups(prev => [...prev, group]);
  };

  const handleMessageReaction = (msgId: string, emoji: string) => {
    if (!currentUser) return;
    setAllMessages(prev => prev.map(m => {
      if (m.id === msgId) {
        const reactions = m.reactions || [];
        const reactionIdx = reactions.findIndex(r => r.emoji === emoji);
        if (reactionIdx > -1) {
          const reaction = reactions[reactionIdx];
          const userIdx = reaction.users.indexOf(currentUser.username);
          if (userIdx > -1) {
            const newUsers = reaction.users.filter(u => u !== currentUser.username);
            if (newUsers.length === 0) return { ...m, reactions: reactions.filter((_, i) => i !== reactionIdx) };
            const newReactions = [...reactions];
            newReactions[reactionIdx] = { ...reaction, users: newUsers };
            return { ...m, reactions: newReactions };
          } else {
            const newReactions = [...reactions];
            newReactions[reactionIdx] = { ...reaction, users: [...reaction.users, currentUser.username] };
            return { ...m, reactions: newReactions };
          }
        } else {
          return { ...m, reactions: [...reactions, { emoji, users: [currentUser.username] }] };
        }
      }
      return m;
    }));
  };

  if (isAppStarting) return <LoadingScreen />;
  if (!currentUser) return <AuthScreen onLogin={onLogin} />;

  if (currentUser.isBanned) {
    return (
      <div className="fixed inset-0 z-[1000] bg-black text-white flex flex-col items-center justify-center p-8 text-center overflow-hidden">
        <Gavel size={120} className="text-red-600 mb-8" />
        <h1 className="text-6xl md:text-8xl font-black italic uppercase tracking-tighter mb-4 text-red-600">EXILED</h1>
        <button onClick={handleLogout} className="flex items-center gap-3 bg-white text-black px-12 py-5 rounded-2xl font-black uppercase text-xl transition-all shadow-2xl z-[1001]"><LogOut size={24} /> Leave Metropolis</button>
      </div>
    );
  }

  // Determine if section should scroll natively or be app-like (fixed)
  const isFixedSection = activeSection === 'CityHall' || activeSection === 'Mood';

  return (
    <div style={{'--theme-color': currentUser.profileColor || '#e21b3c'} as React.CSSProperties} className={`h-screen max-h-screen overflow-hidden flex flex-col md:flex-row ${isDarkMode ? 'bg-[#0f0f0f] text-white' : 'bg-[#f7f8fa] text-slate-900'} transition-colors duration-300`}>
      <style>{`
        :root { --theme-color: ${currentUser.profileColor || '#e21b3c'}; }
        .kahoot-button-custom { background-color: var(--theme-color); border-bottom: 4px solid rgba(0,0,0,0.3); }
        .text-custom { color: var(--theme-color); }
        .bg-custom { background-color: var(--theme-color); }
        .border-custom { border-color: var(--theme-color); }
        .police-flash { animation: police-flash 0.5s infinite; }
        @keyframes police-flash {
          0% { box-shadow: 0 0 20px 5px rgba(239, 68, 68, 0.5); border-color: #ef4444; }
          50% { box-shadow: 0 0 20px 5px rgba(59, 130, 246, 0.5); border-color: #3b82f6; }
          100% { box-shadow: 0 0 20px 5px rgba(239, 68, 68, 0.5); border-color: #ef4444; }
        }
      `}</style>

      <AnimatePresence>
        {activeWarning && (
          <div className="fixed inset-0 z-[1000] flex items-center justify-center p-6 bg-black/80 backdrop-blur-md">
             <motion.div initial={{ scale: 0.8, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} className="w-full max-w-md bg-slate-900 text-white rounded-[3rem] p-10 text-center border-8 border-red-600 shadow-2xl police-flash overflow-hidden">
                <AlertOctagon size={80} className="mx-auto text-red-600 mb-6" />
                <h2 className="text-3xl font-black italic uppercase tracking-tighter mb-4">CITIZEN WARNING</h2>
                <div className="bg-red-600 text-white inline-block px-8 py-2 rounded-full font-black text-xl mb-6 shadow-xl">VIOLATION {activeWarning.count} / 3</div>
                <button onClick={() => setActiveWarning(null)} className="w-full py-5 bg-white text-black rounded-2xl font-black uppercase text-base shadow-xl">I ACKNOWLEDGE THE ACCORDS</button>
             </motion.div>
          </div>
        )}
      </AnimatePresence>

      <AnimatePresence>
        {isMoodModalOpen && (
          <MoodCheckIn 
            onSubmit={(m) => { 
              const today = new Date().toDateString(); 
              setCurrentUser({ 
                ...currentUser!, 
                moodStreak: currentUser!.lastMoodDate === today ? currentUser!.moodStreak : (currentUser!.moodStreak || 0) + 1, 
                lastMoodDate: today, 
                moodHistory: [...(currentUser!.moodHistory || []), { date: today, mood: m, score: MOOD_SCORES[m || 'Normal'] }] 
              }); 
              setIsMoodModalOpen(false); 
            }} 
            isDarkMode={isDarkMode} 
          />
        )}
      </AnimatePresence>
      <Sidebar 
        activeSection={activeSection} 
        onNavigate={(s) => { 
          setActiveSection(s); 
          if(s === 'Profile') setViewingUsername(currentUser!.username); 
        }} 
        isDarkMode={isDarkMode} 
        user={currentUser!} 
        unreadMessages={allMessages.filter(m => m.recipient === currentUser!.username && !m.read).length} 
        unreadNotifications={notifications.filter(n => n.recipient === currentUser!.username && !n.read).length} 
      />
      <main className="flex-1 flex flex-col relative pt-14 pb-16 md:pt-0 md:pb-0 h-full overflow-hidden">
        <div className={`flex-1 ${isFixedSection ? 'overflow-hidden' : 'overflow-y-auto fading-scrollbar'} p-4 md:p-8`}>
          <motion.div 
            key={activeSection + (activeSection === 'Profile' ? viewingUsername : '')} 
            initial={{ opacity: 0, y: 10 }} 
            animate={{ opacity: 1, y: 0 }} 
            className={`max-w-6xl mx-auto h-full ${isFixedSection ? 'flex flex-col' : ''}`}
          >
            {activeSection === 'Home' && <HomeSection user={currentUser!} posts={allPosts} isDarkMode={isDarkMode} />}
            {activeSection === 'Mood' && (
              <MoodSection 
                user={currentUser!} 
                posts={allPosts} 
                onPost={(c, v) => setAllPosts(prev => [{id: Math.random().toString(36).substr(2, 9), author: currentUser!.username, content: c, hearts: 0, comments: [], timestamp: Date.now(), visibility: v}, ...prev])} 
                onHeart={handleHeart} 
                onComment={(pid, t) => setAllPosts(prev => prev.map(p => p.id === pid ? { ...p, comments: [...p.comments, { id: Math.random().toString(36).substr(2, 9), author: currentUser!.username, text: t, hearts: 0, timestamp: Date.now(), replies: [] }] } : p))} 
                onCommentInteraction={handleCommentInteraction} 
                onRepost={handleRepost} 
                onFollow={handleFollow} 
                onBlock={handleBlock} 
                isDarkMode={isDarkMode} 
                onNavigateToProfile={(u) => {setViewingUsername(u); setActiveSection('Profile');}} 
                onUpdatePet={updatePetStats} 
                onViolation={handleViolation}
              />
            )}
            {activeSection === 'Zodiac' && <ZodiacSection isDarkMode={isDarkMode} />}
            {activeSection === 'CityHall' && (
              <CityHallSection 
                isDarkMode={isDarkMode} 
                currentUser={currentUser!} 
                messages={allMessages} 
                groups={allGroups}
                onSendMessage={handleSendMessage} 
                onGroupUpdate={handleGroupUpdate}
                onGroupCreate={handleGroupCreate}
                onReadMessages={(u) => setAllMessages(prev => prev.map(m => (m.recipient === currentUser!.username && m.sender === u) ? {...m, read: true} : m))} 
                onNavigateToProfile={(u) => {setViewingUsername(u); setActiveSection('Profile');}} 
                onReactToMessage={handleMessageReaction} 
                onViolation={handleViolation}
              />
            )}
            {activeSection === 'Notifications' && (
              <NotificationsSection 
                notifications={notifications.filter(n => n.recipient === currentUser!.username)} 
                isDarkMode={isDarkMode} 
                onMarkRead={() => setNotifications(notifications.map(n => n.recipient === currentUser!.username ? {...n, read: true} : n))} 
              />
            )}
            {activeSection === 'Profile' && profileToView && (
              <ProfileSection 
                user={profileToView} 
                allPosts={allPosts} 
                isDarkMode={isDarkMode} 
                currentUser={currentUser!} 
                onEditProfile={(dn, un, pp, ti, bp, pc, bi) => { 
                  setCurrentUser({...currentUser!, displayName: dn, username: un, profilePic: pp, title: ti, profileColor: pc, bio: bi}); 
                  setViewingUsername(un); 
                }} 
                onBlock={handleBlock} 
                onFollow={handleFollow} 
              />
            )}
            {activeSection === 'Settings' && (
              <SettingsSection 
                isDarkMode={isDarkMode} 
                onToggleDarkMode={() => setIsDarkMode(!isDarkMode)} 
                onLogout={handleLogout} 
                user={currentUser!} 
                onUnblock={(u) => setCurrentUser({...currentUser!, blockedUsers: currentUser!.blockedUsers.filter(b => b !== u)})} 
              />
            )}
          </motion.div>
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Send, Users, Search, MessageSquare, ArrowLeft, ShieldCheck, Check, CheckCheck, Clock, Smile, Plus, X, Reply, CornerDownRight, Settings, Camera, LogOut, Globe, Crown, Zap, ExternalLink, Radio } from 'lucide-react';
import { User, Message, MessageReaction, Group } from '../types';
import { checkContentSafety } from '../services/geminiService';

interface CityHallSectionProps {
  isDarkMode: boolean;
  currentUser: User;
  messages: Message[];
  groups: Group[];
  onSendMessage: (recipient: string, text: string, options?: { isGroup?: boolean, recipients?: string[], groupName?: string, replyToId?: string, replyToText?: string, replyToSender?: string, isSystem?: boolean, liaisonData?: any }) => void;
  onReadMessages: (withUsername: string) => void;
  onGroupUpdate: (group: Group) => void;
  onGroupCreate: (group: Group) => void;
  onNavigateToProfile: (username: string) => void;
  onReactToMessage: (msgId: string, emoji: string) => void;
  onViolation: (reason: string) => void;
}

const REACTION_EMOJIS = ['❤️', '😂', '😮', '😢', '🔥', '👍'];
const GROUP_EMOJIS = ['🚀', '🍕', '🎮', '💡', '🔥', '🌈', '💎', '🎭', '👾', '🎨', '🎬', '🎧'];

const CityHallSection: React.FC<CityHallSectionProps> = ({ isDarkMode, currentUser, messages, groups, onSendMessage, onReadMessages, onGroupUpdate, onGroupCreate, onNavigateToProfile, onReactToMessage, onViolation }) => {
  const [input, setInput] = useState('');
  const [searchTerm, setSearchTerm] = useState('');
  const [groupSearchTerm, setGroupSearchTerm] = useState('');
  const [selectedCitizen, setSelectedCitizen] = useState<{ username: string, displayName: string, profilePic?: string, isGroup?: boolean, recipients?: string[] } | null>(null);
  const [reactionPickerMsgId, setReactionPickerMsgId] = useState<string | null>(null);
  const [isCreatingGroup, setIsCreatingGroup] = useState(false);
  const [isEditingGroup, setIsEditingGroup] = useState(false);
  const [groupName, setGroupName] = useState('');
  const [selectedForGroup, setSelectedForGroup] = useState<string[]>([]);
  const [viewingReacters, setViewingReacters] = useState<MessageReaction | null>(null);
  const [replyingTo, setReplyingTo] = useState<Message | null>(null);
  const [isSending, setIsSending] = useState(false);
  const chatEndRef = useRef<HTMLDivElement>(null);
  const scrollContainerRef = useRef<HTMLDivElement>(null);

  const [editGroupName, setEditGroupName] = useState('');
  const [editGroupPhoto, setEditGroupPhoto] = useState('');
  const [nicknames, setNicknames] = useState<Record<string, string>>({});

  const allUsers: User[] = useMemo(() => JSON.parse(localStorage.getItem('mooderia_all_users') || '[]'), [isCreatingGroup, isEditingGroup]);
  const usersWhoBlockedMe = useMemo(() => allUsers.filter(u => u.blockedUsers.includes(currentUser.username)).map(u => u.username), [allUsers, currentUser.username]);

  const CREATOR_EMAIL = 'travismiguel014@gmail.com';
  const getIsCreator = (username: string) => {
    const user = allUsers.find(u => u.username === username);
    return user?.email === CREATOR_EMAIL;
  };

  const filteredCitizens = useMemo(() => {
    if (!searchTerm.trim()) return [];
    return allUsers.filter(u => 
      u.username !== currentUser.username && 
      !currentUser.blockedUsers.includes(u.username) &&
      !usersWhoBlockedMe.includes(u.username) &&
      (u.displayName.toLowerCase().includes(searchTerm.toLowerCase()) || 
       u.username.toLowerCase().includes(searchTerm.toLowerCase()))
    );
  }, [searchTerm, allUsers, currentUser.username, currentUser.blockedUsers, usersWhoBlockedMe]);

  const groupFilterList = useMemo(() => {
    return allUsers.filter(u => 
      u.username !== currentUser.username && 
      !currentUser.blockedUsers.includes(u.username) &&
      !usersWhoBlockedMe.includes(u.username) &&
      (u.displayName.toLowerCase().includes(groupSearchTerm.toLowerCase()) || 
       u.username.toLowerCase().includes(groupSearchTerm.toLowerCase()))
    );
  }, [groupSearchTerm, allUsers, currentUser.username, currentUser.blockedUsers, usersWhoBlockedMe]);

  const currentGroup = useMemo(() => {
    if (selectedCitizen?.isGroup) {
      return groups.find(g => g.id === selectedCitizen.username);
    }
    return null;
  }, [selectedCitizen, groups]);

  const chats = useMemo(() => {
    const list: any[] = [];
    const processedDms = new Set<string>();

    groups.forEach(g => {
      if (g.members.includes(currentUser.username)) {
        list.push({ 
          username: g.id, 
          displayName: g.name, 
          isGroup: true, 
          recipients: g.members,
          profilePic: g.photo || '🚀'
        });
      }
    });

    messages.forEach(m => {
      if (!m.isGroup) {
        const other = m.sender === currentUser.username ? m.recipient : m.sender;
        if (!processedDms.has(other)) {
          processedDms.add(other);
          const userObj = allUsers.find(u => u.username === other);
          if (userObj && !currentUser.blockedUsers.includes(other) && !usersWhoBlockedMe.includes(other)) {
            list.push({ 
              username: other, 
              displayName: userObj.displayName, 
              profilePic: userObj.profilePic, 
              isGroup: false 
            });
          }
        }
      }
    });
    return list;
  }, [messages, allUsers, currentUser.username, currentUser.blockedUsers, usersWhoBlockedMe, groups]);

  const chatMessages = useMemo(() => {
    if (!selectedCitizen) return [];
    if (selectedCitizen.isGroup) {
      return messages.filter(m => m.isGroup && m.recipient === selectedCitizen.username)
        .sort((a, b) => a.timestamp - b.timestamp);
    }
    return messages.filter(m => 
      !m.isGroup &&
      ((m.sender === currentUser.username && m.recipient === selectedCitizen.username) ||
      (m.sender === selectedCitizen.username && m.recipient === currentUser.username))
    ).sort((a, b) => a.timestamp - b.timestamp);
  }, [messages, selectedCitizen, currentUser.username]);

  const groupedMessages = useMemo(() => {
    const groups: { dateLabel: string, items: Message[] }[] = [];
    chatMessages.forEach(msg => {
      const date = new Date(msg.timestamp);
      const today = new Date();
      const yesterday = new Date();
      yesterday.setDate(yesterday.getDate() - 1);
      let label = date.toLocaleDateString(undefined, { day: 'numeric', month: 'long', year: 'numeric' });
      if (date.toDateString() === today.toDateString()) label = "Today";
      else if (date.toDateString() === yesterday.toDateString()) label = "Yesterday";
      const lastGroup = groups[groups.length - 1];
      if (lastGroup && lastGroup.dateLabel === label) lastGroup.items.push(msg);
      else groups.push({ dateLabel: label, items: [msg] });
    });
    return groups;
  }, [chatMessages]);

  useEffect(() => {
    if (selectedCitizen && !selectedCitizen.isGroup) onReadMessages(selectedCitizen.username);
    requestAnimationFrame(() => {
      chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    });
  }, [selectedCitizen, messages.length]);

  const handleSend = async () => {
    if (!input.trim() || !selectedCitizen || isSending) return;
    setIsSending(true);

    const safety = await checkContentSafety(input);
    if (safety.isInappropriate) {
      onViolation(safety.reason);
      setIsSending(false);
      return;
    }

    onSendMessage(selectedCitizen.username, input, { 
      isGroup: selectedCitizen.isGroup, 
      recipients: selectedCitizen.recipients, 
      groupName: selectedCitizen.displayName,
      replyToId: replyingTo?.id,
      replyToText: replyingTo?.text,
      replyToSender: replyingTo?.sender
    });
    setInput('');
    setReplyingTo(null);
    setIsSending(false);
  };

  const handleStartCreateGroup = () => {
    setGroupName('');
    setGroupSearchTerm('');
    setSelectedForGroup([]);
    setIsCreatingGroup(true);
  };

  const handleCreateGroup = () => {
    if (!groupName.trim() || selectedForGroup.length < 1) return;
    const groupId = 'group_' + Math.random().toString(36).substr(2, 9);
    const members = [...selectedForGroup, currentUser.username];
    const newGroup: Group = {
      id: groupId,
      name: groupName,
      owner: currentUser.username,
      members: members,
      nicknames: {},
      createdAt: Date.now(),
      photo: '🚀'
    };
    onGroupCreate(newGroup);
    onSendMessage(groupId, `CITIZEN TERMINAL: Neural Group "${groupName}" initialized.`, { isGroup: true, recipients: members, groupName, isSystem: true });
    setSelectedCitizen({ username: groupId, displayName: groupName, isGroup: true, recipients: members, profilePic: '🚀' });
    setIsCreatingGroup(false);
  };

  const getNickname = (username: string) => {
    if (currentGroup?.nicknames?.[username]) return currentGroup.nicknames[username];
    const user = allUsers.find(u => u.username === username);
    return user?.displayName || username;
  };

  const getSenderPhoto = (username: string) => {
    const user = allUsers.find(u => u.username === username);
    return user?.profilePic;
  };

  return (
    <div className="flex flex-col h-full min-h-0">
      {/* Header Area */}
      <div className="flex justify-between items-center mb-6 shrink-0 px-1">
        <h2 className={`text-3xl lg:text-4xl font-black italic uppercase tracking-tighter ${isDarkMode ? 'text-white' : 'text-slate-900'}`}>Citizen Hub</h2>
        <button 
          onClick={handleStartCreateGroup} 
          className="kahoot-button-blue px-5 py-2.5 rounded-2xl text-white font-black flex items-center gap-2 shadow-lg active:scale-95 transition-all text-xs"
        >
          <Plus size={18} /> <span>NEW GROUP</span>
        </button>
      </div>

      {/* Main Terminal Box */}
      <div className={`flex-1 flex flex-col md:flex-row rounded-[3rem] ${isDarkMode ? 'bg-slate-900' : 'bg-white'} shadow-2xl overflow-hidden border-b-[8px] border-black/10 dark:border-white/5 border-x-2 border-t-2 border-black/5 min-h-0 mb-4`}>

        {/* Sidebar / Conversation List */}
        <div className={`w-full md:w-64 lg:w-72 border-r ${isDarkMode ? 'border-slate-800' : 'border-gray-100'} flex flex-col ${selectedCitizen ? 'hidden md:flex' : 'flex'} min-h-0`}>
          <div className="p-4 border-b border-gray-100 dark:border-slate-800 shrink-0">
            <div className="relative">
              <input 
                type="text" 
                value={searchTerm} 
                onChange={(e) => setSearchTerm(e.target.value)} 
                placeholder="Search citizens..." 
                className={`w-full pl-10 pr-4 py-2.5 rounded-2xl text-[11px] font-black border-2 outline-none focus:border-blue-500 transition-all ${isDarkMode ? 'bg-slate-800 border-slate-700 text-white' : 'bg-gray-50 border-gray-200 text-slate-900'}`} 
              />
              <Search className={`absolute left-3 top-1/2 -translate-y-1/2 ${isDarkMode ? 'text-white/30' : 'text-slate-400'}`} size={14} />
            </div>
          </div>
          <div className="flex-1 overflow-y-auto fading-scrollbar p-3 space-y-1.5">
            {(searchTerm.trim() ? filteredCitizens.map(u => ({ username: u.username, displayName: u.displayName, profilePic: u.profilePic, isGroup: false })) : chats).map(u => (
              <button 
                key={u.username} 
                onClick={() => { setSelectedCitizen(u); setReplyingTo(null); }} 
                className={`w-full p-3 rounded-[1.25rem] flex items-center gap-3 transition-all border-b-4 active:translate-y-0.5 active:border-b-2 ${selectedCitizen?.username === u.username ? 'bg-blue-600 border-blue-800 text-white shadow-md translate-x-1' : 'hover:bg-black/5 opacity-70 hover:opacity-100'}`}
              >
                <div className="w-10 h-10 rounded-xl bg-blue-100 dark:bg-slate-700 flex items-center justify-center font-black overflow-hidden shadow-sm shrink-0 border-2 border-white/20">
                  {u.isGroup ? (u.profilePic && u.profilePic.length < 5 ? <span className="text-xl">{u.profilePic}</span> : <Users size={18} />) : (u.profilePic ? <img src={u.profilePic} className="w-full h-full object-cover" /> : u.displayName[0].toUpperCase())}
                </div>
                <div className="text-left flex-1 min-w-0">
                  <div className="flex items-center gap-1">
                    <p className={`font-black text-[11px] truncate uppercase tracking-tight ${selectedCitizen?.username === u.username ? 'text-white' : ''}`}>{u.displayName}</p>
                    {getIsCreator(u.username) && <Crown size={10} className="text-yellow-400" />}
                  </div>
                  <p className={`text-[8px] font-black uppercase tracking-widest opacity-40 ${selectedCitizen?.username === u.username ? 'text-white' : ''}`}>{u.isGroup ? 'Group' : `@${u.username}`}</p>
                </div>
              </button>
            ))}
          </div>
        </div>

        {/* Chat Area */}
        <div className={`flex-1 flex flex-col min-h-0 ${!selectedCitizen ? 'hidden md:flex' : 'flex'}`}>
          {selectedCitizen ? (
            <>
              <div className={`p-4 border-b ${isDarkMode ? 'bg-slate-800/50 border-slate-800' : 'bg-gray-50/50 border-gray-100'} flex items-center justify-between shrink-0`}>
                <div className="flex items-center gap-3">
                  <button onClick={() => setSelectedCitizen(null)} className="md:hidden p-2 rounded-xl hover:bg-black/5 text-slate-500 transition-colors"><ArrowLeft size={18} /></button>
                  <div className="flex items-center gap-3">
                    <div className="w-10 h-10 rounded-xl bg-blue-600 text-white flex items-center justify-center font-black shadow-lg overflow-hidden border-2 border-white/20">
                      {selectedCitizen.isGroup ? (selectedCitizen.profilePic && selectedCitizen.profilePic.length < 5 ? <span className="text-xl">{selectedCitizen.profilePic}</span> : <Users size={20} />) : (selectedCitizen.profilePic ? <img src={selectedCitizen.profilePic} className="w-full h-full object-cover" /> : selectedCitizen.displayName[0])}
