                  </button>
                ))}
              </div>
              <button onClick={handleCreateGroup} className="kahoot-button-blue w-full py-4 rounded-2xl text-white font-black uppercase text-sm">Launch Network</button>
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </div>
  );
};

