export const getHoroscope = async (sign: string) => {
  try {
    const ai = getAI();
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [{ parts: [{ text: `Provide a daily horoscope for ${sign} today.` }] }],
      config: {
        systemInstruction: "You are a mystical Metropolis Astrologer. Provide a 3-sentence daily horoscope that is encouraging and insightful. Use cosmic and modern terminology.",
      }
    });
    return response.text || "The constellations are currently obscured by metropolis smog.";
  } catch (error) {
    console.error("Horoscope API Error:", error);
    return "The stars are recalibrating. Check back later.";
  }
};

export const getLovePrediction = async (sign1: string, sign2: string) => {
  try {
    const ai = getAI();
    const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: [{ parts: [{ text: `Predict love compatibility between ${sign1} and ${sign2}. Return only a JSON object with 'percentage' (0-100) and 'reason'.` }] }],
        config: {
            responseMimeType: "application/json",
            responseSchema: {
                type: Type.OBJECT,
                properties: {
                    percentage: { type: Type.NUMBER },
                    reason: { type: Type.STRING }
                },
                required: ['percentage', 'reason']
            }
        }
    });

    const text = response.text || "{}";
    return JSON.parse(text.trim());
  } catch (error) {
    console.error("Love Prediction API Error:", error);
    return { percentage: 50, reason: "The romantic frequencies are currently experiencing atmospheric interference." };
  }
}

export const checkContentSafety = async (text: string) => {
  try {
    const ai = getAI();
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [{ parts: [{ text: `Analyze the following text for inappropriate language, hate speech, severe insults, or harassment: "${text}". Return a JSON object with 'isInappropriate' (boolean) and 'reason' (string, keep it short).` }] }],
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            isInappropriate: { type: Type.BOOLEAN },
            reason: { type: Type.STRING }
          },
          required: ['isInappropriate', 'reason']
        }
      }
    });
    const resultText = response.text || "{}";
    return JSON.parse(resultText.trim());
  } catch (error) {
    console.error("Safety Check Error:", error);
    return { isInappropriate: false, reason: "" };
  }
};

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Heart, Send, Sparkles, Brain, Clock, Globe, Users, Trophy, MessageSquare, Repeat, Reply, ShieldAlert, Activity, Stethoscope } from 'lucide-react';
import { User, Post, Comment } from '../types';
import MoodPetSection from './MoodPetSection';
import { STREAK_BADGES } from '../constants';
import { checkContentSafety, getPsychiatristResponse } from '../services/geminiService';

interface MoodSectionProps {
  user: User;
  posts: Post[];
  onPost: (content: string, visibility: 'global' | 'circle') => void;
  onHeart: (postId: string) => void;
  onComment: (postId: string, text: string) => void;
  onCommentInteraction: (postId: string, commentId: string, action: 'heart' | 'reply', replyText?: string) => void;
  onRepost: (post: Post) => void;
  onFollow: (username: string) => void;
  onBlock: (username: string) => void;
  isDarkMode: boolean;
  onNavigateToProfile: (username: string) => void;
  onUpdatePet: (hunger: number, thirst: number, rest: number, coins: number, exp?: number, sleepUntil?: number | null, newEmoji?: string, markChosen?: boolean, newName?: string, gameCooldownId?: string) => void;
  onViolation: (reason: string) => void;
}

const MoodSection: React.FC<MoodSectionProps> = ({ user, posts, onPost, onHeart, onComment, onCommentInteraction, onRepost, onFollow, onBlock, isDarkMode, onNavigateToProfile, onUpdatePet, onViolation }) => {
  const [subTab, setSubTab] = useState<'Express' | 'Teller' | 'Scan' | 'Dr. Pinel' | 'Mood Pet'>('Express');
  const [postContent, setPostContent] = useState('');
  const [feedFilter, setFeedFilter] = useState<'Global' | 'Circle'>('Global');
  const [postVisibility, setPostVisibility] = useState<'global' | 'circle'>('global');
  const [isBroadcasting, setIsBroadcasting] = useState(false);

  const [tellerQuestion, setTellerQuestion] = useState('');
  const [tellerResponse, setTellerResponse] = useState('');
  const [isTellerLoading, setIsTellerLoading] = useState(false);

  // Psychiatrist state
  const [psyChat, setPsyChat] = useState<{ role: 'user' | 'ai', text: string }[]>([]);
  const [psyInput, setPsyInput] = useState('');
  const [isPsyLoading, setIsPsyLoading] = useState(false);
  const psyEndRef = useRef<HTMLDivElement>(null);

  const [quizActive, setQuizActive] = useState(false);
  const [quizStep, setQuizStep] = useState(0);
  const [quizScores, setQuizScores] = useState<Record<string, number>>({ Happy: 0, Angry: 0, Tired: 0, Normal: 0, Excited: 0 });
  const [quizResult, setQuizResult] = useState<string | null>(null);

  const [expandedPostId, setExpandedPostId] = useState<string | null>(null);
  const [commentInputs, setCommentInputs] = useState<Record<string, string>>({});
  const [replyingTo, setReplyingTo] = useState<{ postId: string, commentId: string } | null>(null);
  const [replyContent, setReplyContent] = useState('');

  const filteredPosts = useMemo(() => {
    const allUsers: User[] = JSON.parse(localStorage.getItem('mooderia_all_users') || '[]');
    const usersWhoBlockedMe = allUsers.filter(u => u.blockedUsers.includes(user.username)).map(u => u.username);

    let result = posts.filter(p => 
      !user.blockedUsers.includes(p.author) && 
      !usersWhoBlockedMe.includes(p.author)
    );

    if (feedFilter === 'Global') {
      return result.filter(p => p.visibility === 'global');
    }
    return result.filter(p => p.visibility === 'circle' && (user.following.includes(p.author) || p.author === user.username));
  }, [posts, feedFilter, user.following, user.username, user.blockedUsers]);

  const earnedBadges = useMemo(() => STREAK_BADGES.filter(b => user.moodStreak >= b.threshold), [user.moodStreak]);

  useEffect(() => {
    psyEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [psyChat]);

  const handlePost = async () => {
    if (!postContent.trim() || isBroadcasting) return;
    setIsBroadcasting(true);

    const safety = await checkContentSafety(postContent);
    if (safety.isInappropriate) {
      onViolation(safety.reason);
      setIsBroadcasting(false);
      return;
    }

    onPost(postContent, postVisibility);
    setPostContent('');
    setIsBroadcasting(false);
  };

  const handleAddComment = (postId: string) => {
    const text = commentInputs[postId];
    if (!text?.trim()) return;
    onComment(postId, text);
    setCommentInputs(prev => ({ ...prev, [postId]: '' }));
  };

  const handleReply = (postId: string, commentId: string) => {
    if (!replyContent.trim()) return;
    onCommentInteraction(postId, commentId, 'reply', replyContent);
    setReplyContent('');
    setReplyingTo(null);
  };

  const handlePsySend = async () => {
    if (!psyInput.trim() || isPsyLoading) return;
    const userMsg = psyInput;
    setPsyChat(prev => [...prev, { role: 'user', text: userMsg }]);
    setPsyInput('');
    setIsPsyLoading(true);

    try {
      const res = await getPsychiatristResponse(userMsg);
      setPsyChat(prev => [...prev, { role: 'ai', text: res.text }]);
    } catch (err) {
      setPsyChat(prev => [...prev, { role: 'ai', text: "The medical uplink is currently offline. Please verify your Metropolis key." }]);
    } finally {
      setIsPsyLoading(false);
    }
  };

  const renderComment = (postId: string, comment: Comment, depth = 0) => (
    <div key={comment.id} className={`mt-4 ${depth > 0 ? 'ml-6 md:ml-10 border-l-2 border-black/5 pl-4' : ''}`}>
      <div className="flex items-start gap-3">
        <div className="w-8 h-8 rounded-lg bg-custom text-white font-black flex items-center justify-center shrink-0 text-sm italic">{comment.author[0].toUpperCase()}</div>
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2">
            <span className="font-black text-xs">@{comment.author}</span>
            <span className="text-[8px] font-black opacity-30 uppercase tracking-widest">{new Date(comment.timestamp).toLocaleDateString()}</span>
          </div>
          <p className="text-sm font-bold opacity-80 mt-1 leading-relaxed">"{comment.text}"</p>
          <div className="flex items-center gap-4 mt-2">
            <button onClick={() => onCommentInteraction(postId, comment.id, 'heart')} className="flex items-center gap-1 text-[9px] font-black uppercase text-custom transition-transform active:scale-95"><Heart size={12} fill={comment.hearts > 0 ? "currentColor" : "none"} /> {comment.hearts} Sync</button>
            <button 
              onClick={() => setReplyingTo(replyingTo?.commentId === comment.id ? null : { postId, commentId: comment.id })} 
              className="flex items-center gap-1 text-[9px] font-black uppercase text-blue-500 transition-transform active:scale-95"
            >
              <Reply size={12} /> Echo
            </button>
          </div>

          <AnimatePresence>
            {replyingTo?.commentId === comment.id && (
              <motion.div initial={{ height: 0, opacity: 0 }} animate={{ height: 'auto', opacity: 1 }} exit={{ height: 0, opacity: 0 }} className="mt-3 overflow-hidden">
                <div className="flex gap-2">
                  <input 
                    autoFocus
                    type="text" 
                    value={replyContent} 
                    onChange={e => setReplyContent(e.target.value)}
                    placeholder="Echo back..."
                    className={`flex-1 p-2 rounded-xl border-2 text-[10px] font-bold outline-none focus:border-custom ${isDarkMode ? 'bg-slate-800 border-slate-700 text-white' : 'bg-gray-50 border-gray-100'}`}
                    onKeyPress={e => e.key === 'Enter' && handleReply(postId, comment.id)}
                  />
                  <button onClick={() => handleReply(postId, comment.id)} className="bg-custom text-white px-3 rounded-xl shadow-md transition-transform active:scale-95"><Send size={12} /></button>
                </div>
              </motion.div>
            )}
          </AnimatePresence>
        </div>
      </div>
      {comment.replies && comment.replies.map(reply => renderComment(postId, reply, depth + 1))}
    </div>
  );

  const handleTeller = () => {
    if (!tellerQuestion.trim()) return;
    setIsTellerLoading(true);
    setTimeout(() => {
      const rand = Math.random();
      let result = '';
      if (rand < 0.2) result = 'YES. The stars have spoken!';
      else if (rand < 0.4) result = 'NO. The frequency is blocked.';
      else if (rand < 0.6) result = 'MAYBE. The vibes are still charging.';
      else if (rand < 0.8) result = 'SUPER YES! The universe is screaming it!';
      else result = 'SUPER NO! Not in this city, or any other.';
      setTellerResponse(result);
      setIsTellerLoading(false);
    }, 1200);
  };

  const startQuiz = () => {
    setQuizActive(true);
    setQuizStep(0);
    setQuizScores({ Happy: 0, Angry: 0, Tired: 0, Normal: 0, Excited: 0 });
    setQuizResult(null);
  };

  const QUIZ_STEPS = [
    { q: "How happy do you feel right now?", options: ["Very!", "A little", "Not much", "Not at all"], scores: ["Happy", "Normal", "Tired", "Angry"] },
    { q: "Are you feeling sleepy?", options: ["No, I'm awake!", "A tiny bit", "I need a nap", "I'm a zombie"], scores: ["Excited", "Normal", "Tired", "Tired"] },
    { q: "Are you mad at anyone?", options: ["No, I'm chill", "Just a bit", "Maybe one person", "I'm so angry!"], scores: ["Happy", "Normal", "Angry", "Angry"] },
    { q: "Do you feel excited about today?", options: ["Yes, so much!", "Maybe a bit", "Not really", "Zero excitement"], scores: ["Excited", "Excited", "Normal", "Tired"] },
    { q: "How fast is your brain working?", options: ["Super fast!", "Normal speed", "A bit slow", "It's stuck"], scores: ["Excited", "Normal", "Tired", "Normal"] },
    { q: "Do you want to hug a pet?", options: ["Yes, please!", "Sure", "Not really", "No way"], scores: ["Happy", "Happy", "Normal", "Angry"] },
    { q: "How much do you like today?", options: ["I love it!", "It's okay", "It's boring", "I hate it"], scores: ["Happy", "Normal", "Tired", "Angry"] },
    { q: "Are you busy right now?", options: ["Very busy!", "A little bit", "Not at all", "I'm bored"], scores: ["Excited", "Normal", "Happy", "Tired"] },
    { q: "Do you feel like dancing?", options: ["Yes, right now!", "Maybe later", "No, too tired", "Not my vibe"], scores: ["Excited", "Happy", "Tired", "Normal"] },
    { q: "Pick your favorite color!", options: ["Yellow", "Blue", "Red", "Green"], scores: ["Happy", "Tired", "Angry", "Normal"] }
  ];

  const handleQuizChoice = (idx: number) => {
    const currentStep = QUIZ_STEPS[quizStep];
    const moodKey = currentStep.scores[idx];
    const updatedScores = { ...quizScores };
    if (moodKey) {
      updatedScores[moodKey] = (updatedScores[moodKey] || 0) + 1;
      setQuizScores(updatedScores);
    }
    const nextStep = quizStep + 1;
    if (nextStep < QUIZ_STEPS.length) {
      setQuizStep(nextStep);
    } else {
      const sortedEntries = Object.entries(updatedScores).sort((a, b) => (b[1] as number) - (a[1] as number));
      setQuizResult(sortedEntries[0][0]);
    }
  };

  const formatTime = (ts: number) => {
    const diff = Date.now() - ts;
    if (diff < 60000) return 'Just now';
    if (diff < 3600000) return `${Math.floor(diff / 60000)}m ago`;
    return new Date(ts).toLocaleDateString();
  };

  return (
    <div className="flex flex-col gap-6 pb-20 h-full min-h-0">
      <div className="flex gap-2 overflow-x-auto no-scrollbar pb-2 shrink-0">
        {['Express', 'Dr. Pinel', 'Teller', 'Scan', 'Mood Pet'].map((t) => (
          <button key={t} onClick={() => setSubTab(t as any)} className={`px-5 py-2.5 rounded-full font-black text-[10px] md:text-xs transition-all whitespace-nowrap uppercase tracking-tighter border-b-4 ${subTab === t ? 'bg-custom border-black/20 text-white shadow-lg translate-y-[-2px]' : isDarkMode ? 'bg-slate-800 border-slate-900 text-white/30' : 'bg-white border-gray-100 text-slate-500'}`}>
            {t}
          </button>
        ))}
      </div>

      <div className="flex-1 min-h-0">
        <AnimatePresence mode="wait">
          {subTab === 'Express' && (
            <motion.div key="express" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="space-y-6">
              <div className={`p-6 md:p-8 rounded-[2.5rem] ${isDarkMode ? 'bg-slate-900' : 'bg-white'} border-4 border-black/5 shadow-xl`}>
                <textarea 
                  value={postContent} 
                  onChange={(e) => setPostContent(e.target.value)} 
                  disabled={isBroadcasting}
                  placeholder={isBroadcasting ? "Scanning Signal..." : (postVisibility === 'global' ? "Transmit a global frequency..." : "Whisper to your circle...")} 
                  className={`w-full ${isDarkMode ? 'bg-slate-800 text-white' : 'bg-gray-50 text-slate-900'} p-6 rounded-3xl border-2 border-black/5 focus:border-custom outline-none font-bold text-lg shadow-inner min-h-[120px]`} 
                />
                <div className="flex flex-wrap justify-between items-center mt-6 gap-4">
                  <div className="flex gap-2 bg-black/5 p-1.5 rounded-2xl">
                    <button onClick={() => setPostVisibility('global')} className={`flex items-center gap-2 px-4 py-2 rounded-xl text-[10px] font-black uppercase transition-all ${postVisibility === 'global' ? 'bg-custom text-white' : 'opacity-40'}`}><Globe size={14}/> GLOBAL</button>
                    <button onClick={() => setPostVisibility('circle')} className={`flex items-center gap-2 px-4 py-2 rounded-xl text-[10px] font-black uppercase transition-all ${postVisibility === 'circle' ? 'bg-custom text-white' : 'opacity-40'}`}><Users size={14}/> CIRCLE</button>
                  </div>
                  <button 
                    onClick={handlePost} 
                    disabled={isBroadcasting}
                    className="kahoot-button-custom px-8 py-4 text-white rounded-2xl font-black text-xs flex items-center gap-2 active:scale-95 transition-transform disabled:opacity-50"
                  >
                    {isBroadcasting ? <Clock size={18} className="animate-spin" /> : <Send size={18} />} 
                    {isBroadcasting ? 'SCANNIG...' : 'BROADCAST'}
                  </button>
                </div>
              </div>

              <div className="flex gap-2 bg-black/5 p-1 rounded-xl w-fit">
                <button onClick={() => setFeedFilter('Global')} className={`px-4 py-2 rounded-lg text-[9px] font-black uppercase ${feedFilter === 'Global' ? 'bg-white text-custom shadow-sm' : 'opacity-40'}`}>Metropolis Feed</button>
                <button onClick={() => setFeedFilter('Circle')} className={`px-4 py-2 rounded-lg text-[9px] font-black uppercase ${feedFilter === 'Circle' ? 'bg-white text-custom shadow-sm' : 'opacity-40'}`}>Neural Circle</button>
              </div>

              <div className="space-y-6 pb-12">
                {filteredPosts.length > 0 ? filteredPosts.map(post => (
                  <motion.div key={post.id} initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} className={`p-6 rounded-[2rem] ${isDarkMode ? 'bg-slate-900 text-white' : 'bg-white text-slate-900'} border-2 border-black/5 shadow-md`}>
                    <div className="flex items-center justify-between mb-4">
                      <div className="flex items-center gap-3">
                        <button onClick={() => onNavigateToProfile(post.author)} className="w-10 h-10 rounded-xl bg-custom text-white font-black shrink-0 text-xl flex items-center justify-center italic shadow-sm">{post.author[0].toUpperCase()}</button>
                        <div>
                          <h4 className="font-black text-sm">@{post.author}</h4>
                          <p className="text-[9px] font-black opacity-30 uppercase tracking-widest flex items-center gap-1"><Clock size={10}/> {formatTime(post.timestamp)}</p>
                        </div>
                      </div>
                    </div>
                    {post.isRepost && <div className="flex items-center gap-2 text-[10px] font-black text-green-500 uppercase italic mb-2"><Repeat size={12}/> Echoing: @{post.originalAuthor}</div>}
                    <p className="text-base font-bold italic opacity-90 mb-6 leading-relaxed break-words">"{post.content}"</p>
                    <div className="flex items-center gap-6 pt-4 border-t border-black/5">
                      <button onClick={() => onHeart(post.id)} className="flex items-center gap-1.5 text-custom font-black text-[10px] uppercase"><Heart size={16} fill={post.hearts > 0 ? "currentColor" : "none"} /> {post.hearts} SYNC</button>
                      <button onClick={() => setExpandedPostId(expandedPostId === post.id ? null : post.id)} className="flex items-center gap-1.5 text-blue-500 font-black text-[10px] uppercase"><MessageSquare size={16} /> {post.comments?.length || 0} ECHO</button>
                      <button onClick={() => onRepost(post)} className="flex items-center gap-1.5 text-green-500 font-black text-[10px] uppercase transition-transform active:scale-95"><Repeat size={16} /> ECHO RE-SIGNAL</button>
                    </div>

                    <AnimatePresence>
                      {expandedPostId === post.id && (
                        <motion.div initial={{ height: 0, opacity: 0 }} animate={{ height: 'auto', opacity: 1 }} exit={{ height: 0, opacity: 0 }} className="overflow-hidden">
                           <div className="pt-6 space-y-4">
                              <div className="flex gap-2">
                                <input 
                                  type="text" 
                                  value={commentInputs[post.id] || ''} 
                                  onChange={e => setCommentInputs(prev => ({ ...prev, [post.id]: e.target.value }))}
                                  placeholder="Add an echo to this signal..." 
                                  className={`flex-1 p-3 rounded-xl border-2 text-xs font-bold outline-none focus:border-custom ${isDarkMode ? 'bg-slate-800 border-slate-700 text-white' : 'bg-gray-50 border-gray-100'}`}
                                  onKeyPress={e => e.key === 'Enter' && handleAddComment(post.id)}
                                />
                                <button onClick={() => handleAddComment(post.id)} className="bg-custom text-white px-4 rounded-xl shadow-md transition-transform active:scale-95"><Send size={16} /></button>
                              </div>

                              <div className="space-y-4 max-h-[400px] overflow-y-auto fading-scrollbar pr-2">
                                {post.comments?.length > 0 ? (
                                  post.comments.map(c => renderComment(post.id, c))
                                ) : (
                                  <p className="text-[10px] font-black uppercase opacity-20 text-center py-4 tracking-widest">No echoes yet.</p>
                                )}
                              </div>
                           </div>
                        </motion.div>
                      )}
                    </AnimatePresence>
                  </motion.div>
                )) : <div className="py-20 text-center opacity-20 font-black uppercase italic text-lg tracking-widest">The metropolis is quiet.</div>}
              </div>
            </motion.div>
          )}

          {subTab === 'Dr. Pinel' && (
            <motion.div key="psychiatrist" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="flex flex-col h-full min-h-[500px] relative">
              <div className={`flex-1 flex flex-col rounded-[3rem] ${isDarkMode ? 'bg-slate-900' : 'bg-white'} border-4 border-black/5 shadow-2xl overflow-hidden`}>
                <div className="p-6 border-b border-black/5 flex items-center gap-4 bg-custom/5">
                  <div className="w-12 h-12 rounded-2xl bg-custom text-white flex items-center justify-center shadow-lg border-2 border-white/20">
                    <Stethoscope size={28} />
                  </div>
                  <div>
                    <h3 className="font-black italic uppercase tracking-tighter text-lg leading-none">Dr. Philippe Pinel</h3>
                    <p className="text-[9px] font-black uppercase tracking-widest opacity-40 mt-1">Chief Psychiatrist of Mooderia</p>
                  </div>
                  <div className="ml-auto flex items-center gap-2 bg-green-500/10 px-3 py-1 rounded-full border border-green-500/20">
                    <div className="w-1.5 h-1.5 rounded-full bg-green-500 animate-pulse" />
                    <span className="text-[8px] font-black uppercase text-green-500 tracking-widest">Neural Link Active</span>
                  </div>
                </div>

                <div className="flex-1 overflow-y-auto p-6 space-y-4 fading-scrollbar">
                  {psyChat.length === 0 && (
                    <div className="h-full flex flex-col items-center justify-center text-center p-8 opacity-30">
                      <Brain size={48} className="mb-4" />
                      <p className="text-sm font-black uppercase italic tracking-widest">The doctor is ready for your session. How are you feeling, citizen?</p>
                    </div>
                  )}
                  {psyChat.map((msg, i) => (
                    <div key={i} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                      <div className={`max-w-[85%] p-4 rounded-2xl font-bold text-sm shadow-sm border-b-4 ${msg.role === 'user' ? 'bg-blue-600 border-blue-800 text-white rounded-tr-none' : isDarkMode ? 'bg-slate-800 border-slate-900 text-white rounded-tl-none' : 'bg-gray-100 border-gray-200 text-slate-800 rounded-tl-none'}`}>
                        {msg.text}
                      </div>
                    </div>
                  ))}
                  {isPsyLoading && (
                    <div className="flex justify-start">
                      <div className="bg-black/5 px-6 py-3 rounded-2xl flex items-center gap-2">
                        <div className="w-1.5 h-1.5 rounded-full bg-custom animate-bounce" />
                        <div className="w-1.5 h-1.5 rounded-full bg-custom animate-bounce [animation-delay:0.2s]" />
                        <div className="w-1.5 h-1.5 rounded-full bg-custom animate-bounce [animation-delay:0.4s]" />
                      </div>
                    </div>
                  )}
                  <div ref={psyEndRef} />
                </div>

                <div className="p-6 border-t border-black/5 bg-black/5">
                  <div className={`flex items-center gap-3 p-2 rounded-2xl border-2 transition-all ${isDarkMode ? 'bg-slate-800 border-slate-700' : 'bg-white border-gray-200'} focus-within:border-custom`}>
                    <input 
                      type="text" 
                      value={psyInput} 
                      onChange={e => setPsyInput(e.target.value)}
                      onKeyPress={e => e.key === 'Enter' && handlePsySend()}
                      disabled={isPsyLoading}
                      placeholder="Start your neural session..." 
                      className="flex-1 bg-transparent px-4 py-2 font-bold text-sm outline-none" 
                    />
                    <button onClick={handlePsySend} disabled={isPsyLoading} className="kahoot-button-custom p-3 rounded-xl text-white shadow-md active:scale-95 transition-all"><Send size={20} /></button>
                  </div>
                </div>
              </div>
            </motion.div>
          )}

          {subTab === 'Teller' && (
            <motion.div key="teller" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className={`p-10 rounded-[3rem] ${isDarkMode ? 'bg-slate-900' : 'bg-white'} border-4 border-black/5 shadow-xl text-center flex flex-col items-center`}>
               <Sparkles className="mb-6 text-custom" size={60} />
               <h2 className="text-2xl md:text-4xl font-black mb-8 uppercase italic tracking-tighter">Fortune Oracle</h2>
               <input value={tellerQuestion} onChange={e => setTellerQuestion(e.target.value)} placeholder="Type a question for the stars..." className={`w-full max-w-xl p-5 rounded-2xl border-2 font-black text-center mb-6 outline-none focus:border-custom shadow-inner ${isDarkMode ? 'bg-slate-800 border-slate-700 text-white' : 'bg-gray-50 border-gray-100'}`} />
               <button onClick={handleTeller} disabled={isTellerLoading} className="kahoot-button-custom px-10 py-5 rounded-2xl text-white font-black uppercase text-sm shadow-lg active:scale-95 transition-transform">{isTellerLoading ? 'CALCULATING...' : 'ASK THE STARS'}</button>
               {tellerResponse && (
                 <motion.div initial={{ y: 10, opacity: 0 }} animate={{ y: 0, opacity: 1 }} className="mt-8 p-6 rounded-3xl bg-custom/5 border-l-8 border-custom italic font-bold text-lg max-w-lg">
                   "{tellerResponse}"
                 </motion.div>
               )}
            </motion.div>
          )}

          {subTab === 'Scan' && (
            <motion.div key="scan" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className={`p-10 rounded-[3rem] ${isDarkMode ? 'bg-slate-900' : 'bg-white'} border-4 border-black/5 shadow-xl text-center flex flex-col items-center`}>
               <Brain className="mb-6 text-blue-500" size={60} />
               <h2 className="text-2xl md:text-4xl font-black mb-6 uppercase italic tracking-tighter">Emotional Scan</h2>
               {!quizActive ? (
                 <>
                   <p className="opacity-40 font-bold uppercase tracking-widest text-[10px] mb-10">See your mood signature in 10 quick steps</p>
                   <button onClick={startQuiz} className="kahoot-button-blue px-10 py-5 rounded-2xl text-white font-black uppercase text-sm shadow-lg">Start Scan</button>
                 </>
               ) : (
                 <div className="w-full max-w-lg space-y-8">
                   {quizResult ? (
                     <div className="space-y-6">
                        <div className="text-6xl mb-4">✨</div>
                        <h3 className="text-2xl font-black italic uppercase">Scan Complete</h3>
                        <div className="p-6 rounded-3xl bg-custom/10 border-2 border-custom/20">
                          <p className="text-[10px] font-bold opacity-70 uppercase tracking-widest mb-2">Neural Signature</p>
                          <p className="text-2xl font-black text-custom italic uppercase">{quizResult}</p>
                        </div>
                        <button onClick={() => setQuizActive(false)} className="kahoot-button-custom px-8 py-3 rounded-xl text-white font-black uppercase text-xs">Reset Scan</button>
                     </div>
                   ) : (
                     <div className="space-y-8">
                        <div className="h-2 bg-black/10 rounded-full overflow-hidden"><motion.div className="h-full bg-blue-500" initial={{ width: 0 }} animate={{ width: `${((quizStep + 1) / QUIZ_STEPS.length) * 100}%` }} /></div>
                        <p className="text-lg font-black italic">"{QUIZ_STEPS[quizStep].q}"</p>
                        <div className="grid grid-cols-2 gap-4">
                           {QUIZ_STEPS[quizStep].options.map((opt, i) => (
                             <button key={opt} onClick={() => handleQuizChoice(i)} className="kahoot-button-custom py-4 rounded-xl text-white font-black uppercase text-[10px] active:scale-95 transition-transform">{opt}</button>
                           ))}
                        </div>
                        <p className="text-[10px] font-black uppercase opacity-30">Step {quizStep + 1} of {QUIZ_STEPS.length}</p>
                     </div>
                   )}
                 </div>
               )}
            </motion.div>
          )}

          {subTab === 'Mood Pet' && (
            <motion.div key="pet" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}>
               <MoodPetSection user={user} isDarkMode={isDarkMode} onUpdate={onUpdatePet} onPost={onPost} />
            </motion.div>
          )}
        </AnimatePresence>
      </div>
    </div>
  );
};

export default MoodSection;

export type Mood = 'Wonderful' | 'Excited' | 'Happy' | 'Normal' | 'Tired' | 'Angry' | 'Flaming' | null;

export interface Badge {
  id: string;
  name: string;
  icon: string;
  description: string;
  threshold: number;
}

export interface User {
  displayName: string;
  username: string;
  email: string;
  password?: string;
  bio?: string;
  followers: string[];
  following: string[];
  friends: string[];
  blockedUsers: string[];
  posts: Post[];
  reposts: Post[];
  moodHistory: { date: string, mood: Mood, score: number }[];
  moodStreak: number;
  lastMoodDate?: string;
  profilePic?: string;
  bannerPic?: string;
  profileColor?: string;
  title?: string;
  likesReceived: number;
  // Mood Pet Stats
  petName: string;
  moodCoins: number;
  petEmoji: string;
  petHunger: number; // 0-100
  petThirst: number; // 0-100
  petRest: number;   // 0-100
  petLevel: number;
  petExp: number;
  petHasBeenChosen: boolean;
  petLastUpdate: number; // timestamp
  petSleepUntil: number | null; // timestamp
  gameCooldowns: Record<string, number>; // gameId -> timestamp of when it can be played again
  // Security / Moderation
  warnings: number;
  isBanned: boolean;
}

export interface MessageReaction {
  emoji: string;
  users: string[]; // List of usernames who used this emoji
}

export interface Group {
  id: string;
  name: string;
  photo?: string; // Emoji or dataURL
  members: string[]; // List of usernames
  nicknames: Record<string, string>; // username -> nickname mapping
  owner: string;
  createdAt: number;
}

export interface Message {
  id: string;
  sender: string;
  recipient: string; // For DMs, this is the username. For Groups, this is the groupId.
  text: string;
  timestamp: number;
  read: boolean;
  reactions?: MessageReaction[];
  isGroup?: boolean;
  isSystem?: boolean; // For "X left the group" messages
  recipients?: string[]; // (Deprecated for new logic but kept for compat)
  groupName?: string;
  replyToId?: string;
  replyToText?: string;
  replyToSender?: string;
}

export interface Notification {
  id: string;
  type: 'heart' | 'comment' | 'repost' | 'tier' | 'achievement' | 'follow' | 'comment_heart' | 'reply' | 'reaction' | 'warning';
  fromUser: string;
  recipient: string; 
  postId?: string;
  timestamp: number;
  read: boolean;
  postContentSnippet: string;
}

export interface Post {
  id: string;
  author: string;
  content: string;
  likes: string[]; // Updated from 'hearts: number' to track who liked it
  comments: Comment[];
  timestamp: number;
  isRepost?: boolean;
  originalAuthor?: string;
  visibility: 'global' | 'circle';
}

export interface Comment {
  id: string;
  author: string;
  text: string;
  hearts: number;
  timestamp: number;
  replies: Comment[];
}

export type Section = 'Home' | 'Mood' | 'Zodiac' | 'CityHall' | 'Profile' | 'Settings' | 'Notifications';

export interface ZodiacInfo {
  name: string;
  dates: string;
  description: string;
  history: string;
  symbol: string;
}

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { User, Mood, Section, Post, Comment, Message, Notification, MessageReaction, Group } from './types';
import Sidebar from './components/Sidebar';
import MoodCheckIn from './components/MoodCheckIn';
import HomeSection from './sections/HomeSection';
import MoodSection from './sections/MoodSection';
import ZodiacSection from './sections/ZodiacSection';
import CityHallSection from './sections/CityHallSection';
import ProfileSection from './sections/ProfileSection';
import SettingsSection from './sections/SettingsSection';
import NotificationsSection from './sections/NotificationsSection';
import AuthScreen from './sections/AuthScreen';
import LoadingScreen from './components/LoadingScreen';
import { getExpNeeded, MOOD_SCORES } from './constants';
import { Trophy, Share2, X, ShieldAlert, AlertOctagon, LogOut, Gavel } from 'lucide-react';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [activeSection, setActiveSection] = useState<Section>('Home');
  const [viewingUsername, setViewingUsername] = useState<string | null>(null);
  const [isMoodModalOpen, setIsMoodModalOpen] = useState(false);
  const [isDarkMode, setIsDarkMode] = useState(false); 
  const [isAppStarting, setIsAppStarting] = useState(true);
  const [globalUpdateToggle, setGlobalUpdateToggle] = useState(0);

  const [allPosts, setAllPosts] = useState<Post[]>([]);
  const [allMessages, setAllMessages] = useState<Message[]>([]);
  const [allGroups, setAllGroups] = useState<Group[]>([]);
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);

  const [activeWarning, setActiveWarning] = useState<{ count: number, reason: string } | null>(null);

  const migrateUserData = (user: User): User => {
    return {
      ...user,
      blockedUsers: user.blockedUsers || [],
      moodHistory: user.moodHistory || [],
      following: user.following || [],
      followers: user.followers || [],
      moodStreak: user.moodStreak || 0,
      petLevel: user.petLevel || 1,
      moodCoins: user.moodCoins ?? 100,
      gameCooldowns: user.gameCooldowns || {},
      petHasBeenChosen: !!user.petHasBeenChosen,
      warnings: user.warnings ?? 0,
      isBanned: !!user.isBanned
    };
  };

  const profileToView = useMemo(() => {
    if (!viewingUsername) return null;
    if (currentUser && viewingUsername === currentUser.username) return currentUser;
    const allUsers: User[] = JSON.parse(localStorage.getItem('mooderia_all_users') || '[]');
    return allUsers.find(u => u.username === viewingUsername) || null;
  }, [viewingUsername, currentUser, globalUpdateToggle, allPosts]);

  const addNotification = useCallback((recipient: string, type: Notification['type'], snippet: string, postId: string = '') => {
    if (!currentUser) return;
    if (recipient === currentUser.username && type !== 'achievement' && type !== 'tier' && type !== 'warning') return;

    const newNotif: Notification = {
      id: Math.random().toString(36).substr(2, 9),
      fromUser: type === 'warning' ? 'Police Force' : (currentUser?.username || 'Metropolis'),
      recipient,
      type,
      postId,
      timestamp: Date.now(),
      read: false,
      postContentSnippet: snippet
    };
    setNotifications(prev => [...prev, newNotif]);
  }, [currentUser]);

  useEffect(() => {
    const savedUser = localStorage.getItem('mooderia_user');
    const savedPosts = localStorage.getItem('mooderia_posts') || '[]';
    const savedMessages = localStorage.getItem('mooderia_messages') || '[]';
    const savedGroups = localStorage.getItem('mooderia_groups') || '[]';
    const savedNotifications = localStorage.getItem('mooderia_notifications') || '[]';
    const savedTheme = localStorage.getItem('mooderia_theme');

    if (savedUser) {
      try {
        let user: User = JSON.parse(savedUser);
        user = migrateUserData(user);

        const now = Date.now();
        if (user.email === 'travismiguel014@gmail.com') user.title = 'Creator';

        const lastUpdate = user.petLastUpdate || now;
        const elapsedMinutes = Math.floor((now - lastUpdate) / 60000);

        if (elapsedMinutes > 0) {
          user.petHunger = Math.max(0, user.petHunger - elapsedMinutes * 0.15);
          user.petThirst = Math.max(0, user.petThirst - elapsedMinutes * 0.2);
          if (!user.petSleepUntil || user.petSleepUntil < now) {
            user.petRest = Math.max(0, user.petRest - elapsedMinutes * 0.1);
            user.petSleepUntil = null;
          }
          user.petLastUpdate = now;
        }
        setCurrentUser(user);
        setViewingUsername(user.username);
      } catch (e) { 
        localStorage.removeItem('mooderia_user');
      }
    }

    // Migrate old posts that might still have hearts as number
    const parsedPosts: any[] = JSON.parse(savedPosts);
    const migratedPosts: Post[] = parsedPosts.map(p => ({
      ...p,
      likes: Array.isArray(p.likes) ? p.likes : (p.hearts ? [] : [])
    }));

    setAllPosts(migratedPosts);
    setAllMessages(JSON.parse(savedMessages));
    setAllGroups(JSON.parse(savedGroups));
    setNotifications(JSON.parse(savedNotifications));
    if (savedTheme === 'dark') setIsDarkMode(true);
    setIsLoaded(true);

    const timer = setTimeout(() => setIsAppStarting(false), 2000);
    return () => clearTimeout(timer);
  }, []);

  useEffect(() => {
    if (currentUser && !currentUser.isBanned && isLoaded) {
      const today = new Date().toDateString();
      if (currentUser.lastMoodDate !== today) {
        setIsMoodModalOpen(true);
      }
    }
  }, [currentUser?.username, currentUser?.lastMoodDate, isLoaded]);

  useEffect(() => {
    if (!isLoaded) return;
    if (currentUser) {
      localStorage.setItem('mooderia_user', JSON.stringify(currentUser));
      const allUsers: User[] = JSON.parse(localStorage.getItem('mooderia_all_users') || '[]');
      const idx = allUsers.findIndex(u => u.username === currentUser.username);
      if (idx > -1) { allUsers[idx] = currentUser; } 
      else { allUsers.push(currentUser); }
      localStorage.setItem('mooderia_all_users', JSON.stringify(allUsers));
    }
    localStorage.setItem('mooderia_posts', JSON.stringify(allPosts));
    localStorage.setItem('mooderia_messages', JSON.stringify(allMessages));
    localStorage.setItem('mooderia_groups', JSON.stringify(allGroups));
    localStorage.setItem('mooderia_notifications', JSON.stringify(notifications));
    localStorage.setItem('mooderia_theme', isDarkMode ? 'dark' : 'light');
    setGlobalUpdateToggle(t => t + 1);
  }, [currentUser, allPosts, allMessages, allGroups, notifications, isDarkMode, isLoaded]);

  const handleViolation = (reason: string) => {
    if (!currentUser) return;
    const newWarnings = (currentUser.warnings || 0) + 1;
    const isNowBanned = newWarnings >= 3;

    setCurrentUser({
      ...currentUser,
      warnings: newWarnings,
      isBanned: isNowBanned
    });

    addNotification(currentUser.username, 'warning', `Police Warning ${newWarnings}/3: ${reason}`);
    setActiveWarning({ count: newWarnings, reason });
  };

  const handleLogout = () => {
    localStorage.removeItem('mooderia_user');
    setCurrentUser(null);
    setViewingUsername(null);
    setActiveSection('Home');
    setIsMoodModalOpen(false);
  };

  const onLogin = (user: User) => {
    const migrated = migrateUserData(user);
    setCurrentUser(migrated);
    setViewingUsername(migrated.username);
  };

  const handleHeart = (postId: string) => {
    if (!currentUser) return;
    setAllPosts(prev => prev.map(p => {
      if (p.id === postId) {
        const isLiked = p.likes.includes(currentUser.username);
        let newLikes;
        if (isLiked) {
          newLikes = p.likes.filter(u => u !== currentUser.username);
        } else {
          newLikes = [...p.likes, currentUser.username];
          if (p.author !== currentUser.username) {
            addNotification(p.author, 'heart', p.content.substring(0, 20), p.id);
          }
        }
        return { ...p, likes: newLikes };
      }
      return p;
    }));
  };

  const handleDeletePost = (postId: string) => {
    if (!currentUser) return;
    setAllPosts(prev => prev.filter(p => p.id !== postId));
  };

  const handleEditPost = (postId: string, newContent: string) => {
    if (!currentUser) return;
    setAllPosts(prev => prev.map(p => p.id === postId ? { ...p, content: newContent } : p));
  };

  const handleCommentInteraction = (postId: string, commentId: string, action: 'heart' | 'reply', replyText?: string) => {
    if (!currentUser) return;
    setAllPosts(prev => prev.map(p => {
      if (p.id === postId) {
        const updateComments = (comments: Comment[]): Comment[] => {
          return comments.map(c => {
            if (c.id === commentId) {
              if (action === 'heart') {
                if (c.author !== currentUser.username) {
                  addNotification(c.author, 'comment_heart', c.text.substring(0, 20), p.id);
                }
                return { ...c, hearts: c.hearts + 1 };
              } else if (action === 'reply' && replyText) {
                const newReply: Comment = {
                  id: Math.random().toString(36).substr(2, 9),
                  author: currentUser.username,
                  text: replyText,
                  hearts: 0,
                  timestamp: Date.now(),
                  replies: []
                };
                if (c.author !== currentUser.username) {
                  addNotification(c.author, 'reply', replyText.substring(0, 20), p.id);
                }
                return { ...c, replies: [...(c.replies || []), newReply] };
              }
            }
            if (c.replies && c.replies.length > 0) {
              return { ...c, replies: updateComments(c.replies) };
            }
            return c;
          });
        };
        return { ...p, comments: updateComments(p.comments) };
      }
      return p;
    }));
  };

  const handleRepost = (post: Post) => {
    if (!currentUser) return;
    const newPost: Post = {
      id: Math.random().toString(36).substr(2, 9),
      author: currentUser.username,
      content: post.content,
      likes: [], // Reposts start fresh with likes
      comments: [],
      timestamp: Date.now(),
      isRepost: true,
      originalAuthor: post.author,
      visibility: 'global'
    };
    setAllPosts(prev => [newPost, ...prev]);
    if (post.author !== currentUser.username) {
      addNotification(post.author, 'repost', post.content.substring(0, 20), newPost.id);
    }
  };

  const handleFollow = (targetUsername: string) => {
    if (!currentUser || currentUser.username === targetUsername) return;
    const isFollowing = currentUser.following.includes(targetUsername);
    if (isFollowing) {
      setCurrentUser({ ...currentUser, following: currentUser.following.filter(u => u !== targetUsername) });
    } else {
      setCurrentUser({ ...currentUser, following: [...currentUser.following, targetUsername] });
      addNotification(targetUsername, 'follow', '');
    }
  };

  const handleBlock = (targetUsername: string) => {
    if (!currentUser || currentUser.username === targetUsername) return;
    setCurrentUser({
      ...currentUser,
      blockedUsers: [...currentUser.blockedUsers, targetUsername],
      following: currentUser.following.filter(u => u !== targetUsername),
      followers: currentUser.followers.filter(u => u !== targetUsername)
    });
  };

  const updatePetStats = (hunger: number, thirst: number, rest: number, coins: number, exp: number = 0, sleepUntil: number | null = null, newEmoji?: string, markChosen?: boolean, newName?: string, gameCooldownId?: string) => {
    if (!currentUser) return;
    let newLevel = currentUser.petLevel;
    let newExp = (currentUser.petExp || 0) + exp;
    while (newExp >= getExpNeeded(newLevel)) {
      newExp -= getExpNeeded(newLevel);
      newLevel++;
      addNotification(currentUser.username, 'achievement', `Your pet reached level ${newLevel}!`);
    }
    const newCooldowns = { ...currentUser.gameCooldowns };
    if (gameCooldownId) {
      newCooldowns[gameCooldownId] = Date.now() + (5 * 60 * 1000);
    }
    setCurrentUser({
      ...currentUser,
      petHunger: Math.min(100, Math.max(0, currentUser.petHunger + hunger)),
      petThirst: Math.min(100, Math.max(0, currentUser.petThirst + thirst)),
      petRest: Math.min(100, Math.max(0, currentUser.petRest + rest)),
      moodCoins: (currentUser.moodCoins || 0) + coins,
      petLevel: newLevel,
      petExp: newExp,
      petSleepUntil: sleepUntil !== null ? sleepUntil : currentUser.petSleepUntil,
      petEmoji: newEmoji || currentUser.petEmoji,
      petHasBeenChosen: markChosen !== undefined ? markChosen : currentUser.petHasBeenChosen,
      petName: newName || currentUser.petName,
      gameCooldowns: newCooldowns
    });
  };

  const handleSendMessage = (recipient: string, text: string, options?: any) => {
    if (!currentUser) return;
    const newMessage: Message = {
      id: Math.random().toString(36).substr(2, 9),
      sender: currentUser.username,
      recipient,
      text,
      timestamp: Date.now(),
      read: false,
      isGroup: options?.isGroup || false,
      isSystem: options?.isSystem || false,
      groupName: options?.groupName,
      replyToId: options?.replyToId,
      replyToText: options?.replyToText,
      replyToSender: options?.replyToSender
    };
    setAllMessages(prev => [...prev, newMessage]);
  };

  const handleGroupUpdate = (group: Group) => {
    setAllGroups(prev => prev.map(g => g.id === group.id ? group : g));
  };

  const handleGroupCreate = (group: Group) => {
    setAllGroups(prev => [...prev, group]);
  };

  const handleMessageReaction = (msgId: string, emoji: string) => {
    if (!currentUser) return;
    setAllMessages(prev => prev.map(m => {
      if (m.id === msgId) {
        const reactions = m.reactions || [];
        const reactionIdx = reactions.findIndex(r => r.emoji === emoji);
        if (reactionIdx > -1) {
          const reaction = reactions[reactionIdx];
          const userIdx = reaction.users.indexOf(currentUser.username);
          if (userIdx > -1) {
            const newUsers = reaction.users.filter(u => u !== currentUser.username);
            if (newUsers.length === 0) return { ...m, reactions: reactions.filter((_, i) => i !== reactionIdx) };
            const newReactions = [...reactions];
            newReactions[reactionIdx] = { ...reaction, users: newUsers };
            return { ...m, reactions: newReactions };
          } else {
            const newReactions = [...reactions];
            newReactions[reactionIdx] = { ...reaction, users: [...reaction.users, currentUser.username] };
            return { ...m, reactions: newReactions };
          }
        } else {
          return { ...m, reactions: [...reactions, { emoji, users: [currentUser.username] }] };
        }
      }
      return m;
    }));
  };

  if (isAppStarting) return <LoadingScreen />;
  if (!currentUser) return <AuthScreen onLogin={onLogin} />;

  if (currentUser.isBanned) {
    return (
      <div className="fixed inset-0 z-[1000] bg-black text-white flex flex-col items-center justify-center p-8 text-center overflow-hidden">
        <Gavel size={120} className="text-red-600 mb-8" />
        <h1 className="text-6xl md:text-8xl font-black italic uppercase tracking-tighter mb-4 text-red-600">EXILED</h1>
        <button onClick={handleLogout} className="flex items-center gap-3 bg-white text-black px-12 py-5 rounded-2xl font-black uppercase text-xl transition-all shadow-2xl z-[1001]"><LogOut size={24} /> Leave Metropolis</button>
      </div>
    );
  }

  // Determine if section should scroll natively or be app-like (fixed)
  const isFixedSection = activeSection === 'CityHall' || activeSection === 'Mood';

  return (
    <div style={{'--theme-color': currentUser.profileColor || '#e21b3c'} as React.CSSProperties} className={`h-screen max-h-screen overflow-hidden flex flex-col md:flex-row ${isDarkMode ? 'bg-[#0f0f0f] text-white' : 'bg-[#f7f8fa] text-slate-900'} transition-colors duration-300`}>
      <style>{`
        :root { --theme-color: ${currentUser.profileColor || '#e21b3c'}; }
        .kahoot-button-custom { background-color: var(--theme-color); border-bottom: 4px solid rgba(0,0,0,0.3); }
        .text-custom { color: var(--theme-color); }
        .bg-custom { background-color: var(--theme-color); }
        .border-custom { border-color: var(--theme-color); }
        .police-flash { animation: police-flash 0.5s infinite; }
        @keyframes police-flash {
          0% { box-shadow: 0 0 20px 5px rgba(239, 68, 68, 0.5); border-color: #ef4444; }
          50% { box-shadow: 0 0 20px 5px rgba(59, 130, 246, 0.5); border-color: #3b82f6; }
          100% { box-shadow: 0 0 20px 5px rgba(239, 68, 68, 0.5); border-color: #ef4444; }
        }
      `}</style>

      <AnimatePresence>
        {activeWarning && (
          <div className="fixed inset-0 z-[1000] flex items-center justify-center p-6 bg-black/80 backdrop-blur-md">
             <motion.div initial={{ scale: 0.8, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} className="w-full max-w-md bg-slate-900 text-white rounded-[3rem] p-10 text-center border-8 border-red-600 shadow-2xl police-flash overflow-hidden">
                <AlertOctagon size={80} className="mx-auto text-red-600 mb-6" />
                <h2 className="text-3xl font-black italic uppercase tracking-tighter mb-4">CITIZEN WARNING</h2>
                <div className="bg-red-600 text-white inline-block px-8 py-2 rounded-full font-black text-xl mb-6 shadow-xl">VIOLATION {activeWarning.count} / 3</div>
                <button onClick={() => setActiveWarning(null)} className="w-full py-5 bg-white text-black rounded-2xl font-black uppercase text-base shadow-xl">I ACKNOWLEDGE THE ACCORDS</button>
             </motion.div>
          </div>
        )}
      </AnimatePresence>

      <AnimatePresence>
        {isMoodModalOpen && (
          <MoodCheckIn 
            onSubmit={(m) => { 
              const today = new Date().toDateString(); 
              setCurrentUser({ 
                ...currentUser!, 
                moodStreak: currentUser!.lastMoodDate === today ? currentUser!.moodStreak : (currentUser!.moodStreak || 0) + 1, 
                lastMoodDate: today, 
                moodHistory: [...(currentUser!.moodHistory || []), { date: today, mood: m, score: MOOD_SCORES[m || 'Normal'] }] 
              }); 
              setIsMoodModalOpen(false); 
            }} 
            isDarkMode={isDarkMode} 
          />
        )}
      </AnimatePresence>
      <Sidebar 
        activeSection={activeSection} 
        onNavigate={(s) => { 
          setActiveSection(s); 
          if(s === 'Profile') setViewingUsername(currentUser!.username); 
        }} 
        isDarkMode={isDarkMode} 
        user={currentUser!} 
        unreadMessages={allMessages.filter(m => m.recipient === currentUser!.username && !m.read).length} 
        unreadNotifications={notifications.filter(n => n.recipient === currentUser!.username && !n.read).length} 
      />
      <main className="flex-1 flex flex-col min-h-0 relative pt-14 pb-16 md:pt-0 md:pb-0 h-full overflow-hidden">
        <div className={`flex-1 flex flex-col min-h-0 ${isFixedSection ? 'overflow-hidden' : 'overflow-y-auto fading-scrollbar'} p-4 md:p-8`}>
          <motion.div 
            key={activeSection + (activeSection === 'Profile' ? viewingUsername : '')} 
            initial={{ opacity: 0, y: 10 }} 
            animate={{ opacity: 1, y: 0 }} 
            className={`max-w-6xl mx-auto w-full flex-1 flex flex-col min-h-0`}
          >
            {activeSection === 'Home' && <HomeSection user={currentUser!} posts={allPosts} isDarkMode={isDarkMode} />}
            {activeSection === 'Mood' && (
              <MoodSection 
                user={currentUser!} 
                posts={allPosts} 
                onPost={(c, v) => setAllPosts(prev => [{id: Math.random().toString(36).substr(2, 9), author: currentUser!.username, content: c, likes: [], comments: [], timestamp: Date.now(), visibility: v}, ...prev])} 
                onHeart={handleHeart} 
                onDeletePost={handleDeletePost}
                onEditPost={handleEditPost}
                onComment={(pid, t) => setAllPosts(prev => prev.map(p => p.id === pid ? { ...p, comments: [...p.comments, { id: Math.random().toString(36).substr(2, 9), author: currentUser!.username, text: t, hearts: 0, timestamp: Date.now(), replies: [] }] } : p))} 
                onCommentInteraction={handleCommentInteraction} 
                onRepost={handleRepost} 
                onFollow={handleFollow} 
                onBlock={handleBlock} 
                isDarkMode={isDarkMode} 
                onNavigateToProfile={(u) => {setViewingUsername(u); setActiveSection('Profile');}} 
                onUpdatePet={updatePetStats} 
                onViolation={handleViolation}
              />
            )}
            {activeSection === 'Zodiac' && <ZodiacSection isDarkMode={isDarkMode} />}
            {activeSection === 'CityHall' && (
              <CityHallSection 
                isDarkMode={isDarkMode} 
                currentUser={currentUser!} 
                messages={allMessages} 
                groups={allGroups}
                onSendMessage={handleSendMessage} 
                onGroupUpdate={handleGroupUpdate}
                onGroupCreate={handleGroupCreate}
                onReadMessages={(u) => setAllMessages(prev => prev.map(m => (m.recipient === currentUser!.username && m.sender === u) ? {...m, read: true} : m))} 
                onNavigateToProfile={(u) => {setViewingUsername(u); setActiveSection('Profile');}} 
                onReactToMessage={handleMessageReaction} 
                onViolation={handleViolation}
              />
            )}
            {activeSection === 'Notifications' && (
              <NotificationsSection 
                notifications={notifications.filter(n => n.recipient === currentUser!.username)} 
                isDarkMode={isDarkMode} 
                onMarkRead={() => setNotifications(notifications.map(n => n.recipient === currentUser!.username ? {...n, read: true} : n))} 
              />
            )}
            {activeSection === 'Profile' && profileToView && (
              <ProfileSection 
                user={profileToView} 
                allPosts={allPosts} 
                isDarkMode={isDarkMode} 
                currentUser={currentUser!} 
                onEditProfile={(dn, un, pp, ti, bp, pc, bi) => { 
                  setCurrentUser({...currentUser!, displayName: dn, username: un, profilePic: pp, title: ti, profileColor: pc, bio: bi}); 
                  setViewingUsername(un); 
                }} 
                onBlock={handleBlock} 
                onFollow={handleFollow} 
              />
            )}
            {activeSection === 'Settings' && (
              <SettingsSection 
                isDarkMode={isDarkMode} 
                onToggleDarkMode={() => setIsDarkMode(!isDarkMode)} 
                onLogout={handleLogout} 
                user={currentUser!} 
                onUnblock={(u) => setCurrentUser({...currentUser!, blockedUsers: currentUser!.blockedUsers.filter(b => b !== u)})} 
              />
            )}
          </motion.div>
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Heart, Send, Sparkles, Brain, Clock, Globe, Users, Trophy, MessageSquare, Repeat, Reply, ShieldAlert, Activity, Stethoscope, Trash2, Edit, X } from 'lucide-react';
import { User, Post, Comment } from '../types';
import MoodPetSection from './MoodPetSection';
import { STREAK_BADGES } from '../constants';
import { checkContentSafety } from '../services/geminiService';

interface MoodSectionProps {
  user: User;
  posts: Post[];
  onPost: (content: string, visibility: 'global' | 'circle') => void;
  onHeart: (postId: string) => void;
  onDeletePost: (postId: string) => void;
  onEditPost: (postId: string, newContent: string) => void;
  onComment: (postId: string, text: string) => void;
  onCommentInteraction: (postId: string, commentId: string, action: 'heart' | 'reply', replyText?: string) => void;
  onRepost: (post: Post) => void;
  onFollow: (username: string) => void;
  onBlock: (username: string) => void;
  isDarkMode: boolean;
  onNavigateToProfile: (username: string) => void;
  onUpdatePet: (hunger: number, thirst: number, rest: number, coins: number, exp?: number, sleepUntil?: number | null, newEmoji?: string, markChosen?: boolean, newName?: string, gameCooldownId?: string) => void;
  onViolation: (reason: string) => void;
}

const MoodSection: React.FC<MoodSectionProps> = ({ user, posts, onPost, onHeart, onDeletePost, onEditPost, onComment, onCommentInteraction, onRepost, onFollow, onBlock, isDarkMode, onNavigateToProfile, onUpdatePet, onViolation }) => {
  const [subTab, setSubTab] = useState<'Express' | 'Teller' | 'Scan' | 'Mood Pet'>('Express');
  const [postContent, setPostContent] = useState('');
  const [feedFilter, setFeedFilter] = useState<'Global' | 'Circle'>('Global');
  const [postVisibility, setPostVisibility] = useState<'global' | 'circle'>('global');
  const [isBroadcasting, setIsBroadcasting] = useState(false);

  const [tellerQuestion, setTellerQuestion] = useState('');
  const [tellerResponse, setTellerResponse] = useState('');
  const [isTellerLoading, setIsTellerLoading] = useState(false);

  const [quizActive, setQuizActive] = useState(false);
  const [quizStep, setQuizStep] = useState(0);
  const [quizScores, setQuizScores] = useState<Record<string, number>>({ Happy: 0, Angry: 0, Tired: 0, Normal: 0, Excited: 0 });
  const [quizResult, setQuizResult] = useState<string | null>(null);

  const [expandedPostId, setExpandedPostId] = useState<string | null>(null);
  const [commentInputs, setCommentInputs] = useState<Record<string, string>>({});
  const [replyingTo, setReplyingTo] = useState<{ postId: string, commentId: string } | null>(null);
  const [replyContent, setReplyContent] = useState('');

  // Editing state
  const [editingPostId, setEditingPostId] = useState<string | null>(null);
  const [editBuffer, setEditBuffer] = useState('');

  // View Likers Modal
  const [likersModalPost, setLikersModalPost] = useState<Post | null>(null);

  const filteredPosts = useMemo(() => {
    const allUsers: User[] = JSON.parse(localStorage.getItem('mooderia_all_users') || '[]');
    const usersWhoBlockedMe = allUsers.filter(u => u.blockedUsers.includes(user.username)).map(u => u.username);

    let result = posts.filter(p => 
      !user.blockedUsers.includes(p.author) && 
      !usersWhoBlockedMe.includes(p.author)
    );

    if (feedFilter === 'Global') {
      return result.filter(p => p.visibility === 'global');
    }
    return result.filter(p => p.visibility === 'circle' && (user.following.includes(p.author) || p.author === user.username));
  }, [posts, feedFilter, user.following, user.username, user.blockedUsers]);

  const handlePost = async () => {
    if (!postContent.trim() || isBroadcasting) return;
    setIsBroadcasting(true);

    const safety = await checkContentSafety(postContent);
    if (safety.isInappropriate) {
      onViolation(safety.reason);
      setIsBroadcasting(false);
      return;
    }

    onPost(postContent, postVisibility);
    setPostContent('');
    setIsBroadcasting(false);
  };

  const handleStartEdit = (post: Post) => {
    setEditingPostId(post.id);
    setEditBuffer(post.content);
  };

  const handleSaveEdit = async () => {
    if (!editingPostId || !editBuffer.trim()) return;
    const safety = await checkContentSafety(editBuffer);
    if (safety.isInappropriate) {
      onViolation(safety.reason);
      return;
    }
    onEditPost(editingPostId, editBuffer);
    setEditingPostId(null);
  };

  const handleAddComment = (postId: string) => {
    const text = commentInputs[postId];
    if (!text?.trim()) return;
    onComment(postId, text);
    setCommentInputs(prev => ({ ...prev, [postId]: '' }));
  };

  const handleReply = (postId: string, commentId: string) => {
    if (!replyContent.trim()) return;
    onCommentInteraction(postId, commentId, 'reply', replyContent);
    setReplyContent('');
    setReplyingTo(null);
  };

  const renderComment = (postId: string, comment: Comment, depth = 0) => (
    <div key={comment.id} className={`mt-4 ${depth > 0 ? 'ml-6 md:ml-10 border-l-2 border-black/5 pl-4' : ''}`}>
      <div className="flex items-start gap-3">
        <div className="w-8 h-8 rounded-lg bg-custom text-white font-black flex items-center justify-center shrink-0 text-sm italic">{comment.author[0].toUpperCase()}</div>
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2">
            <span className="font-black text-xs">@{comment.author}</span>
            <span className="text-[8px] font-black opacity-30 uppercase tracking-widest">{new Date(comment.timestamp).toLocaleDateString()}</span>
          </div>
          <p className="text-sm font-bold opacity-80 mt-1 leading-relaxed">"{comment.text}"</p>
          <div className="flex items-center gap-4 mt-2">
            <button onClick={() => onCommentInteraction(postId, comment.id, 'heart')} className="flex items-center gap-1 text-[9px] font-black uppercase text-custom transition-transform active:scale-95"><Heart size={12} fill={comment.hearts > 0 ? "currentColor" : "none"} /> {comment.hearts} Sync</button>
            <button 
              onClick={() => setReplyingTo(replyingTo?.commentId === comment.id ? null : { postId, commentId: comment.id })} 
              className="flex items-center gap-1 text-[9px] font-black uppercase text-blue-500 transition-transform active:scale-95"
            >
              <Reply size={12} /> Echo
            </button>
          </div>

          <AnimatePresence>
            {replyingTo?.commentId === comment.id && (
              <motion.div initial={{ height: 0, opacity: 0 }} animate={{ height: 'auto', opacity: 1 }} exit={{ height: 0, opacity: 0 }} className="mt-3 overflow-hidden">
                <div className="flex gap-2">
                  <input 
                    autoFocus
                    type="text" 
                    value={replyContent} 
                    onChange={e => setReplyContent(e.target.value)}
                    placeholder="Echo back..."
                    className={`flex-1 p-2 rounded-xl border-2 text-[10px] font-bold outline-none focus:border-custom ${isDarkMode ? 'bg-slate-800 border-slate-700 text-white' : 'bg-gray-50 border-gray-100'}`}
                    onKeyPress={e => e.key === 'Enter' && handleReply(postId, comment.id)}
                  />
                  <button onClick={() => handleReply(postId, comment.id)} className="bg-custom text-white px-3 rounded-xl shadow-md transition-transform active:scale-95"><Send size={12} /></button>
                </div>
              </motion.div>
            )}
          </AnimatePresence>
        </div>
      </div>
      {comment.replies && comment.replies.map(reply => renderComment(postId, reply, depth + 1))}
    </div>
  );

  const handleTeller = () => {
    if (!tellerQuestion.trim()) return;
    setIsTellerLoading(true);
    setTimeout(() => {
      const rand = Math.random();
      let result = '';
      if (rand < 0.2) result = 'YES. The stars have spoken!';
      else if (rand < 0.4) result = 'NO. The frequency is blocked.';
      else if (rand < 0.6) result = 'MAYBE. The vibes are still charging.';
      else if (rand < 0.8) result = 'SUPER YES! The universe is screaming it!';
      else result = 'SUPER NO! Not in this city, or any other.';
      setTellerResponse(result);
      setIsTellerLoading(false);
    }, 1200);
  };

  const startQuiz = () => {
    setQuizActive(true);
    setQuizStep(0);
    setQuizScores({ Happy: 0, Angry: 0, Tired: 0, Normal: 0, Excited: 0 });
    setQuizResult(null);
  };

  const QUIZ_STEPS = [
    { q: "How happy do you feel right now?", options: ["Very!", "A little", "Not much", "Not at all"], scores: ["Happy", "Normal", "Tired", "Angry"] },
    { q: "Are you feeling sleepy?", options: ["No, I'm awake!", "A tiny bit", "I need a nap", "I'm a zombie"], scores: ["Excited", "Normal", "Tired", "Tired"] },
    { q: "Are you mad at anyone?", options: ["No, I'm chill", "Just a bit", "Maybe one person", "I'm so angry!"], scores: ["Happy", "Normal", "Angry", "Angry"] },
    { q: "Do you feel excited about today?", options: ["Yes, so much!", "Maybe a bit", "Not really", "Zero excitement"], scores: ["Excited", "Excited", "Normal", "Tired"] },
    { q: "How fast is your brain working?", options: ["Super fast!", "Normal speed", "A bit slow", "It's stuck"], scores: ["Excited", "Normal", "Tired", "Normal"] },
    { q: "Do you want to hug a pet?", options: ["Yes, please!", "Sure", "Not really", "No way"], scores: ["Happy", "Happy", "Normal", "Angry"] },
    { q: "How much do you like today?", options: ["I love it!", "It's okay", "It's boring", "I hate it"], scores: ["Happy", "Normal", "Tired", "Angry"] },
    { q: "Are you busy right now?", options: ["Very busy!", "A little bit", "Not at all", "I'm bored"], scores: ["Excited", "Normal", "Happy", "Tired"] },
    { q: "Do you feel like dancing?", options: ["Yes, right now!", "Maybe later", "No, too tired", "Not my vibe"], scores: ["Excited", "Happy", "Tired", "Normal"] },
    { q: "Pick your favorite color!", options: ["Yellow", "Blue", "Red", "Green"], scores: ["Happy", "Tired", "Angry", "Normal"] }
  ];

  const handleQuizChoice = (idx: number) => {
    const currentStep = QUIZ_STEPS[quizStep];
    const moodKey = currentStep.scores[idx];
    const updatedScores = { ...quizScores };
    if (moodKey) {
      updatedScores[moodKey] = (updatedScores[moodKey] || 0) + 1;
      setQuizScores(updatedScores);
    }
    const nextStep = quizStep + 1;
    if (nextStep < QUIZ_STEPS.length) {
      setQuizStep(nextStep);
    } else {
      const sortedEntries = Object.entries(updatedScores).sort((a, b) => (b[1] as number) - (a[1] as number));
      setQuizResult(sortedEntries[0][0]);
    }
  };

  const formatTime = (ts: number) => {
    const diff = Date.now() - ts;
    if (diff < 60000) return 'Just now';
    if (diff < 3600000) return `${Math.floor(diff / 60000)}m ago`;
    return new Date(ts).toLocaleDateString();
  };

  return (
    <div className="flex flex-col gap-6 pb-20 h-full min-h-0">
      <div className="flex gap-2 overflow-x-auto no-scrollbar pb-2 shrink-0">
        {['Express', 'Teller', 'Scan', 'Mood Pet'].map((t) => (
          <button key={t} onClick={() => setSubTab(t as any)} className={`px-5 py-2.5 rounded-full font-black text-[10px] md:text-xs transition-all whitespace-nowrap uppercase tracking-tighter border-b-4 ${subTab === t ? 'bg-custom border-black/20 text-white shadow-lg translate-y-[-2px]' : isDarkMode ? 'bg-slate-800 border-slate-900 text-white/30' : 'bg-white border-gray-100 text-slate-500'}`}>
            {t}
          </button>
        ))}
      </div>

      <div className="flex-1 min-h-0">
        <AnimatePresence mode="wait">
          {subTab === 'Express' && (
            <motion.div key="express" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="space-y-6">
              <div className={`p-6 md:p-8 rounded-[2.5rem] ${isDarkMode ? 'bg-slate-900' : 'bg-white'} border-4 border-black/5 shadow-xl`}>
                <textarea 
                  value={postContent} 
                  onChange={(e) => setPostContent(e.target.value)} 
                  disabled={isBroadcasting}
                  placeholder={isBroadcasting ? "Scanning Signal..." : (postVisibility === 'global' ? "Transmit a global frequency..." : "Whisper to your circle...")} 
                  className={`w-full ${isDarkMode ? 'bg-slate-800 text-white' : 'bg-gray-50 text-slate-900'} p-6 rounded-3xl border-2 border-black/5 focus:border-custom outline-none font-bold text-lg shadow-inner min-h-[120px]`} 
                />
                <div className="flex flex-wrap justify-between items-center mt-6 gap-4">
                  <div className="flex gap-2 bg-black/5 p-1.5 rounded-2xl">
                    <button onClick={() => setPostVisibility('global')} className={`flex items-center gap-2 px-4 py-2 rounded-xl text-[10px] font-black uppercase transition-all ${postVisibility === 'global' ? 'bg-custom text-white' : 'opacity-40'}`}><Globe size={14}/> GLOBAL</button>
                    <button onClick={() => setPostVisibility('circle')} className={`flex items-center gap-2 px-4 py-2 rounded-xl text-[10px] font-black uppercase transition-all ${postVisibility === 'circle' ? 'bg-custom text-white' : 'opacity-40'}`}><Users size={14}/> CIRCLE</button>
                  </div>
                  <button 
                    onClick={handlePost} 
                    disabled={isBroadcasting}
                    className="kahoot-button-custom px-8 py-4 text-white rounded-2xl font-black text-xs flex items-center gap-2 active:scale-95 transition-transform disabled:opacity-50"
                  >
                    {isBroadcasting ? <Clock size={18} className="animate-spin" /> : <Send size={18} />} 
                    {isBroadcasting ? 'SCANNIG...' : 'BROADCAST'}
                  </button>
                </div>
              </div>

              <div className="flex gap-2 bg-black/5 p-1 rounded-xl w-fit">
                <button onClick={() => setFeedFilter('Global')} className={`px-4 py-2 rounded-lg text-[9px] font-black uppercase ${feedFilter === 'Global' ? 'bg-white text-custom shadow-sm' : 'opacity-40'}`}>Metropolis Feed</button>
                <button onClick={() => setFeedFilter('Circle')} className={`px-4 py-2 rounded-lg text-[9px] font-black uppercase ${feedFilter === 'Circle' ? 'bg-white text-custom shadow-sm' : 'opacity-40'}`}>Neural Circle</button>
              </div>

              <div className="space-y-6 pb-12">
                {filteredPosts.length > 0 ? filteredPosts.map(post => {
                  const isAuthor = post.author === user.username;
                  const isLiked = post.likes.includes(user.username);

                  return (
                    <motion.div key={post.id} initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} className={`p-6 rounded-[2rem] ${isDarkMode ? 'bg-slate-900 text-white' : 'bg-white text-slate-900'} border-2 border-black/5 shadow-md`}>
                      <div className="flex items-center justify-between mb-4">
                        <div className="flex items-center gap-3">
                          <button onClick={() => onNavigateToProfile(post.author)} className="w-10 h-10 rounded-xl bg-custom text-white font-black shrink-0 text-xl flex items-center justify-center italic shadow-sm">{post.author[0].toUpperCase()}</button>
                          <div>
                            <h4 className="font-black text-sm">@{post.author}</h4>
                            <p className="text-[9px] font-black opacity-30 uppercase tracking-widest flex items-center gap-1"><Clock size={10}/> {formatTime(post.timestamp)}</p>
                          </div>
                        </div>
                        {isAuthor && (
                          <div className="flex gap-2">
                             <button onClick={() => handleStartEdit(post)} className="p-2 bg-black/5 hover:bg-black/10 rounded-xl transition-all text-blue-500"><Edit size={16}/></button>
                             <button onClick={() => onDeletePost(post.id)} className="p-2 bg-black/5 hover:bg-black/10 rounded-xl transition-all text-red-500"><Trash2 size={16}/></button>
                          </div>
                        )}
                      </div>

                      {editingPostId === post.id ? (
                        <div className="space-y-4 mb-6">
                           <textarea value={editBuffer} onChange={e => setEditBuffer(e.target.value)} className={`w-full p-4 rounded-2xl border-2 font-bold ${isDarkMode ? 'bg-slate-800 border-slate-700 text-white' : 'bg-gray-50 border-gray-100 text-slate-900'} outline-none focus:border-custom`} rows={3} />
                           <div className="flex gap-2">
                             <button onClick={handleSaveEdit} className="bg-custom text-white px-4 py-2 rounded-xl font-black text-[10px] uppercase shadow-md">Update Signal</button>
                             <button onClick={() => setEditingPostId(null)} className="bg-black/5 px-4 py-2 rounded-xl font-black text-[10px] uppercase">Cancel</button>
                           </div>
                        </div>
                      ) : (
                        <>
                          {post.isRepost && <div className="flex items-center gap-2 text-[10px] font-black text-green-500 uppercase italic mb-2"><Repeat size={12}/> Echoing: @{post.originalAuthor}</div>}
                          <p className="text-base font-bold italic opacity-90 mb-6 leading-relaxed break-words">"{post.content}"</p>
                        </>
                      )}

                      <div className="flex items-center gap-6 pt-4 border-t border-black/5">
                        <div className="flex items-center gap-1.5">
                           <button onClick={() => onHeart(post.id)} className={`flex items-center gap-1.5 ${isLiked ? 'text-custom' : 'opacity-40'} font-black text-[10px] uppercase transition-all active:scale-95`}>
                             <Heart size={16} fill={isLiked ? "currentColor" : "none"} />
                           </button>
                           <button onClick={() => setLikersModalPost(post)} className="text-custom font-black text-[10px] hover:underline transition-all">
                             {post.likes.length} SYNC
                           </button>
                        </div>
                        <button onClick={() => setExpandedPostId(expandedPostId === post.id ? null : post.id)} className="flex items-center gap-1.5 text-blue-500 font-black text-[10px] uppercase"><MessageSquare size={16} /> {post.comments?.length || 0} ECHO</button>
                        <button onClick={() => onRepost(post)} className="flex items-center gap-1.5 text-green-500 font-black text-[10px] uppercase transition-transform active:scale-95"><Repeat size={16} /> ECHO RE-SIGNAL</button>
                      </div>

                      <AnimatePresence>
                        {expandedPostId === post.id && (
                          <motion.div initial={{ height: 0, opacity: 0 }} animate={{ height: 'auto', opacity: 1 }} exit={{ height: 0, opacity: 0 }} className="overflow-hidden">
                             <div className="pt-6 space-y-4">
                                <div className="flex gap-2">
                                  <input 
                                    type="text" 
                                    value={commentInputs[post.id] || ''} 
                                    onChange={e => setCommentInputs(prev => ({ ...prev, [post.id]: e.target.value }))}
                                    placeholder="Add an echo to this signal..." 
                                    className={`flex-1 p-3 rounded-xl border-2 text-xs font-bold outline-none focus:border-custom ${isDarkMode ? 'bg-slate-800 border-slate-700 text-white' : 'bg-gray-50 border-gray-100'}`}
