              </div>
            </>
          ) : (
            <div className="flex-1 flex flex-col items-center justify-center p-12 text-center opacity-20">
              <Radio size={80} className="mb-6 animate-pulse" />
              <h3 className="text-3xl font-black uppercase italic tracking-tighter mb-4">Neural Hub</h3>
              <p className="text-xs font-black uppercase tracking-widest">Select a signal frequency to start communicating</p>
            </div>
          )}
        </div>
      </div>

      {/* Reacters Modal */}
      <AnimatePresence>
        {viewingReacters && (
          <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-black/80 backdrop-blur-md">
            <motion.div initial={{ scale: 0.9, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} className={`w-full max-w-sm rounded-[3rem] p-8 ${isDarkMode ? 'bg-slate-900 border-white/10' : 'bg-white border-black/5'} border-4 shadow-2xl relative`}>
              <button onClick={() => setViewingReacters(null)} className="absolute top-6 right-6 opacity-40 hover:opacity-100 transition-all"><X size={24}/></button>
              <h3 className="text-xl font-black uppercase italic mb-6">Synchronization Core {viewingReacters.emoji}</h3>
              <div className="space-y-2 max-h-[300px] overflow-y-auto fading-scrollbar">
                {viewingReacters.users.map(u => (
                  <button key={u} onClick={() => { onNavigateToProfile(u); setViewingReacters(null); }} className="w-full p-3 rounded-2xl flex items-center gap-3 hover:bg-black/5 transition-all">
                    <div className="w-8 h-8 rounded-lg bg-custom text-white font-black flex items-center justify-center italic text-xs border-2 border-white/20">{u[0].toUpperCase()}</div>
                    <p className="text-[12px] font-black uppercase text-left">@{u}</p>
                  </button>
                ))}
              </div>
            </motion.div>
          </div>
        )}
      </AnimatePresence>

      {/* Group Create Modal */}
      <AnimatePresence>
        {isCreatingGroup && (
          <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-black/90 backdrop-blur-md">
            <motion.div initial={{ scale: 0.9, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} className={`${isDarkMode ? 'bg-slate-900 border-white/10' : 'bg-white border-black/5'} w-full max-w-md rounded-[3rem] p-10 border-4 shadow-2xl`}>
              <div className="flex justify-between items-center mb-8"><h3 className="text-2xl font-black uppercase italic">Initialize Group</h3><button onClick={() => setIsCreatingGroup(false)} className="opacity-40"><X size={28}/></button></div>
              <div className="space-y-6">
                 <input type="text" value={groupName} onChange={e => setGroupName(e.target.value)} placeholder="Group Name..." className="w-full p-4 rounded-2xl border-2 bg-black/5 font-black text-center text-lg outline-none focus:border-custom" />
                 <div className="max-h-48 overflow-y-auto fading-scrollbar p-2 space-y-2 bg-black/5 rounded-2xl">
                    {allUsers.filter(u => u.username !== currentUser.username).map(u => (
                      <button key={u.username} onClick={() => setSelectedForGroup(prev => prev.includes(u.username) ? prev.filter(x => x !== u.username) : [...prev, u.username])} className={`w-full p-3 rounded-xl flex items-center gap-3 transition-all ${selectedForGroup.includes(u.username) ? 'bg-blue-600 text-white shadow-md' : 'hover:bg-black/5'}`}>
                         <div className="w-8 h-8 rounded-lg bg-custom text-white font-black flex items-center justify-center italic text-xs shrink-0">{u.displayName[0]}</div>
                         <p className="text-[12px] font-black uppercase flex-1 text-left">{u.displayName}</p>
                         {selectedForGroup.includes(u.username) && <Check size={16}/>}
                      </button>
                    ))}
                 </div>
                 <button onClick={handleCreateGroup} disabled={!groupName.trim() || selectedForGroup.length === 0} className="kahoot-button-blue w-full py-5 rounded-2xl text-white font-black uppercase text-sm shadow-xl active:scale-95 transition-all">Launch Network</button>
              </div>
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </div>
  );
};

export default CityHallSection;

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { User, Mood, Section, Post, Comment, Message, Notification, MessageReaction, Group } from './types';
import Sidebar from './components/Sidebar';
import MoodCheckIn from './components/MoodCheckIn';
import HomeSection from './sections/HomeSection';
import MoodSection from './sections/MoodSection';
import ZodiacSection from './sections/ZodiacSection';
import CityHallSection from './sections/CityHallSection';
import ProfileSection from './sections/ProfileSection';
import SettingsSection from './sections/SettingsSection';
import NotificationsSection from './sections/NotificationsSection';
import AuthScreen from './sections/AuthScreen';
import LoadingScreen from './components/LoadingScreen';
import { getExpNeeded, MOOD_SCORES } from './constants';
import { Trophy, Share2, X, ShieldAlert, AlertOctagon, LogOut, Gavel } from 'lucide-react';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [allUsers, setAllUsers] = useState<User[]>([]);
  const [activeSection, setActiveSection] = useState<Section>('Home');
  const [viewingUsername, setViewingUsername] = useState<string | null>(null);
  const [isMoodModalOpen, setIsMoodModalOpen] = useState(false);
  const [isDarkMode, setIsDarkMode] = useState(false); 
  const [isAppStarting, setIsAppStarting] = useState(true);

  const [allPosts, setAllPosts] = useState<Post[]>([]);
  const [allMessages, setAllMessages] = useState<Message[]>([]);
  const [allGroups, setAllGroups] = useState<Group[]>([]);
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);

  const [activeWarning, setActiveWarning] = useState<{ count: number, reason: string } | null>(null);

  const migrateUserData = (user: User): User => {
    return {
      ...user,
      blockedUsers: user.blockedUsers || [],
      moodHistory: user.moodHistory || [],
      following: user.following || [],
      followers: user.followers || [],
      moodStreak: user.moodStreak || 0,
      petLevel: user.petLevel || 1,
      moodCoins: user.moodCoins ?? 100,
      gameCooldowns: user.gameCooldowns || {},
      petHasBeenChosen: !!user.petHasBeenChosen,
      warnings: user.warnings ?? 0,
      isBanned: !!user.isBanned
    };
  };

  const profileToView = useMemo(() => {
    if (!viewingUsername) return null;
    if (currentUser && viewingUsername === currentUser.username) return currentUser;
    return allUsers.find(u => u.username === viewingUsername) || null;
  }, [viewingUsername, currentUser, allUsers]);

  const addNotification = useCallback((recipient: string, type: Notification['type'], snippet: string, postId: string = '') => {
    if (!currentUser) return;
    if (recipient === currentUser.username && type !== 'achievement' && type !== 'tier' && type !== 'warning') return;

    const newNotif: Notification = {
      id: Math.random().toString(36).substr(2, 9),
      fromUser: type === 'warning' ? 'Police Force' : (currentUser?.username || 'Metropolis'),
      recipient,
      type,
      postId,
      timestamp: Date.now(),
      read: false,
      postContentSnippet: snippet
    };
    setNotifications(prev => [...prev, newNotif]);
  }, [currentUser]);

  useEffect(() => {
    const savedUser = localStorage.getItem('mooderia_user');
    const savedAllUsers = localStorage.getItem('mooderia_all_users') || '[]';
    const savedPosts = localStorage.getItem('mooderia_posts') || '[]';
    const savedMessages = localStorage.getItem('mooderia_messages') || '[]';
    const savedGroups = localStorage.getItem('mooderia_groups') || '[]';
    const savedNotifications = localStorage.getItem('mooderia_notifications') || '[]';
    const savedTheme = localStorage.getItem('mooderia_theme');

    try {
      const loadedAllUsers = JSON.parse(savedAllUsers).map(migrateUserData);
      setAllUsers(loadedAllUsers);
    } catch (e) {
      setAllUsers([]);
    }

    if (savedUser) {
      try {
        let user: User = JSON.parse(savedUser);
        user = migrateUserData(user);

        const now = Date.now();
        if (user.email === 'travismiguel014@gmail.com') user.title = 'Creator';

        const lastUpdate = user.petLastUpdate || now;
        const elapsedMinutes = Math.floor((now - lastUpdate) / 60000);

        if (elapsedMinutes > 0) {
          user.petHunger = Math.max(0, user.petHunger - elapsedMinutes * 0.15);
          user.petThirst = Math.max(0, user.petThirst - elapsedMinutes * 0.2);
          if (!user.petSleepUntil || user.petSleepUntil < now) {
            user.petRest = Math.max(0, user.petRest - elapsedMinutes * 0.1);
            user.petSleepUntil = null;
          }
          user.petLastUpdate = now;
        }
        setCurrentUser(user);
        setViewingUsername(user.username);
      } catch (e) { 
        localStorage.removeItem('mooderia_user');
      }
    }

    setAllPosts(JSON.parse(savedPosts).map((p: any) => ({ ...p, likes: Array.isArray(p.likes) ? p.likes : [] })));
    setAllMessages(JSON.parse(savedMessages));
    setAllGroups(JSON.parse(savedGroups));
    setNotifications(JSON.parse(savedNotifications));
    if (savedTheme === 'dark') setIsDarkMode(true);
    setIsLoaded(true);

    const timer = setTimeout(() => setIsAppStarting(false), 2000);
    return () => clearTimeout(timer);
  }, []);

  useEffect(() => {
    if (!isLoaded) return;
    if (currentUser) {
      localStorage.setItem('mooderia_user', JSON.stringify(currentUser));
      setAllUsers(prev => {
        const updated = [...prev];
        const idx = updated.findIndex(u => u.username === currentUser.username);
        if (idx > -1) {
          // Merge lists carefully
          updated[idx] = { ...updated[idx], ...currentUser };
        } else {
          updated.push(currentUser);
        }
        return updated;
      });
    }
  }, [currentUser, isLoaded]);

  useEffect(() => {
    if (!isLoaded) return;
    localStorage.setItem('mooderia_all_users', JSON.stringify(allUsers));
    localStorage.setItem('mooderia_posts', JSON.stringify(allPosts));
    localStorage.setItem('mooderia_messages', JSON.stringify(allMessages));
    localStorage.setItem('mooderia_groups', JSON.stringify(allGroups));
    localStorage.setItem('mooderia_notifications', JSON.stringify(notifications));
    localStorage.setItem('mooderia_theme', isDarkMode ? 'dark' : 'light');
  }, [allUsers, allPosts, allMessages, allGroups, notifications, isDarkMode, isLoaded]);

  const handleFollow = (targetUsername: string) => {
    if (!currentUser || currentUser.username === targetUsername) return;
    const isFollowing = currentUser.following.includes(targetUsername);

    // Immediate state update for master list
    setAllUsers(prev => prev.map(u => {
      if (u.username === currentUser.username) {
        const nextFollowing = isFollowing 
          ? u.following.filter(f => f !== targetUsername)
          : [...u.following, targetUsername];
        return { ...u, following: nextFollowing };
      }
      if (u.username === targetUsername) {
        const nextFollowers = isFollowing
          ? (u.followers || []).filter(f => f !== currentUser.username)
          : [...(u.followers || []), currentUser.username];
        return { ...u, followers: nextFollowers };
      }
      return u;
    }));

    // Update currentUser local state
    const nextFollowing = isFollowing 
      ? currentUser.following.filter(f => f !== targetUsername)
      : [...currentUser.following, targetUsername];
    setCurrentUser({ ...currentUser, following: nextFollowing });

    if (!isFollowing) addNotification(targetUsername, 'follow', '');
  };

  const handleBlock = (targetUsername: string) => {
    if (!currentUser || currentUser.username === targetUsername) return;
    setAllUsers(prev => prev.map(u => {
      if (u.username === currentUser.username) {
        return { 
          ...u, 
          blockedUsers: [...u.blockedUsers, targetUsername],
          following: u.following.filter(f => f !== targetUsername),
          followers: u.followers.filter(f => f !== targetUsername)
        };
      }
      if (u.username === targetUsername) {
        return {
          ...u,
          following: u.following.filter(f => f !== currentUser.username),
          followers: u.followers.filter(f => f !== currentUser.username)
        };
      }
      return u;
    }));

    setCurrentUser({
      ...currentUser,
      blockedUsers: [...currentUser.blockedUsers, targetUsername],
      following: currentUser.following.filter(f => f !== targetUsername),
      followers: currentUser.followers.filter(f => f !== targetUsername)
    });
  };

  const handleSendMessage = (recipient: string, text: string, options?: any) => {
    if (!currentUser) return;
    const newMessage: Message = {
      id: Math.random().toString(36).substr(2, 9),
      sender: currentUser.username,
      recipient,
      text,
      timestamp: Date.now(),
      read: false,
      isGroup: options?.isGroup || false,
      isSystem: options?.isSystem || false,
      groupName: options?.groupName,
      replyToId: options?.replyToId,
      replyToText: options?.replyToText,
      replyToSender: options?.replyToSender
    };
    setAllMessages(prev => [...prev, newMessage]);
  };

  // Fix: Added handleGroupUpdate to update group information in the state
  const handleGroupUpdate = (group: Group) => {
    setAllGroups(prev => prev.map(g => g.id === group.id ? group : g));
  };

  // Fix: Added handleGroupCreate to add a new group to the state
  const handleGroupCreate = (group: Group) => {
    setAllGroups(prev => [...prev, group]);
  };

  const handleMessageReaction = (msgId: string, emoji: string) => {
    if (!currentUser) return;
    setAllMessages(prev => prev.map(m => {
      if (m.id === msgId) {
        const reactions = [...(m.reactions || [])];
        const reactionIdx = reactions.findIndex(r => r.emoji === emoji);

        if (reactionIdx > -1) {
          const reaction = reactions[reactionIdx];
          const userIdx = reaction.users.indexOf(currentUser.username);

          if (userIdx > -1) {
            // Unreact (Same emoji clicked twice)
            const newUsers = reaction.users.filter(u => u !== currentUser.username);
            if (newUsers.length === 0) {
              reactions.splice(reactionIdx, 1);
            } else {
              reactions[reactionIdx] = { ...reaction, users: newUsers };
            }
          } else {
            // Add user to existing reaction emoji
            reactions[reactionIdx] = { ...reaction, users: [...reaction.users, currentUser.username] };
          }
        } else {
          // Add brand new emoji reaction
          reactions.push({ emoji, users: [currentUser.username] });
        }
        return { ...m, reactions };
      }
      return m;
    }));
  };

  const onLogin = (user: User) => {
    const migrated = migrateUserData(user);
    setCurrentUser(migrated);
    setViewingUsername(migrated.username);
  };

  const handleLogout = () => {
    setCurrentUser(null);
    localStorage.removeItem('mooderia_user');
    setActiveSection('Home');
  };

  const handleHeart = (postId: string) => {
    if (!currentUser) return;
    setAllPosts(prev => prev.map(p => {
      if (p.id === postId) {
        const isLiked = p.likes.includes(currentUser.username);
        const nextLikes = isLiked 
          ? p.likes.filter(u => u !== currentUser.username)
          : [...p.likes, currentUser.username];
        if (!isLiked) addNotification(p.author, 'heart', p.content.substring(0, 20), p.id);
        return { ...p, likes: nextLikes };
      }
      return p;
    }));
  };

  const handleDeletePost = (postId: string) => setAllPosts(prev => prev.filter(p => p.id !== postId));

  const handleEditPost = (postId: string, newContent: string) => setAllPosts(prev => prev.map(p => p.id === postId ? { ...p, content: newContent } : p));

  const handleCommentInteraction = (postId: string, commentId: string, action: 'heart' | 'reply', replyText?: string) => {
    if (!currentUser) return;
    setAllPosts(prev => prev.map(p => {
      if (p.id === postId) {
        const updateComments = (comments: Comment[]): Comment[] => {
          return comments.map(c => {
            if (c.id === commentId) {
              if (action === 'heart') return { ...c, hearts: c.hearts + 1 };
              if (action === 'reply' && replyText) {
                const newReply: Comment = {
                  id: Math.random().toString(36).substr(2, 9),
                  author: currentUser.username,
                  text: replyText,
                  hearts: 0,
                  timestamp: Date.now(),
                  replies: []
                };
                return { ...c, replies: [...c.replies, newReply] };
              }
            } else if (c.replies.length > 0) {
              return { ...c, replies: updateComments(c.replies) };
            }
            return c;
          });
        };
        return { ...p, comments: updateComments(p.comments) };
      }
      return p;
    }));
  };

  const handleRepost = (post: Post) => {
    if (!currentUser) return;
    const newPost: Post = {
      id: Math.random().toString(36).substr(2, 9),
      author: currentUser.username,
      content: post.content,
      likes: [],
      comments: [],
      timestamp: Date.now(),
      isRepost: true,
      originalAuthor: post.author,
      visibility: 'global'
    };
    setAllPosts(prev => [newPost, ...prev]);
    addNotification(post.author, 'repost', post.content.substring(0, 20), post.id);
  };

  const updatePetStats = (hunger: number, thirst: number, rest: number, coins: number, exp: number = 0, sleepUntil: number | null = null, newEmoji?: string, markChosen?: boolean, newName?: string, gameCooldownId?: string) => {
    if (!currentUser) return;
    setCurrentUser(prev => {
      if (!prev) return null;
      let nextLevel = prev.petLevel;
      let nextExp = prev.petExp + exp;
      while (nextExp >= getExpNeeded(nextLevel)) {
        nextExp -= getExpNeeded(nextLevel);
        nextLevel++;
      }
      return {
        ...prev,
        petHunger: Math.min(100, Math.max(0, prev.petHunger + hunger)),
        petThirst: Math.min(100, Math.max(0, prev.petThirst + thirst)),
        petRest: Math.min(100, Math.max(0, prev.petRest + rest)),
        moodCoins: Math.max(0, prev.moodCoins + coins),
        petExp: nextExp,
        petLevel: nextLevel,
        petSleepUntil: sleepUntil !== null ? sleepUntil : prev.petSleepUntil,
        petEmoji: newEmoji || prev.petEmoji,
        petHasBeenChosen: markChosen !== undefined ? markChosen : prev.petHasBeenChosen,
        petName: newName || prev.petName,
        gameCooldowns: gameCooldownId ? { ...prev.gameCooldowns, [gameCooldownId]: Date.now() + 300000 } : prev.gameCooldowns,
        petLastUpdate: Date.now()
      };
    });
  };

  const handleViolation = (reason: string) => {
    if (!currentUser) return;
    const newWarnings = (currentUser.warnings || 0) + 1;
    const isBanned = newWarnings >= 3;
    setCurrentUser({ ...currentUser, warnings: newWarnings, isBanned });
    setActiveWarning({ count: newWarnings, reason });
    addNotification(currentUser.username, 'warning', reason);
  };

  if (isAppStarting) return <LoadingScreen />;
  if (!currentUser) return <AuthScreen onLogin={onLogin} />;

  if (currentUser.isBanned) {
    return (
      <div className="fixed inset-0 z-[1000] bg-black text-white flex flex-col items-center justify-center p-8 text-center overflow-hidden">
        <Gavel size={120} className="text-red-600 mb-8" />
        <h1 className="text-6xl md:text-8xl font-black italic uppercase tracking-tighter mb-4 text-red-600">EXILED</h1>
        <button onClick={handleLogout} className="flex items-center gap-3 bg-white text-black px-12 py-5 rounded-2xl font-black uppercase text-xl transition-all shadow-2xl z-[1001]"><LogOut size={24} /> Leave Metropolis</button>
      </div>
    );
  }

  const isFixedSection = activeSection === 'CityHall' || activeSection === 'Mood';

  return (
    <div style={{'--theme-color': currentUser.profileColor || '#e21b3c'} as React.CSSProperties} className={`h-screen max-h-screen overflow-hidden flex flex-col md:flex-row ${isDarkMode ? 'bg-[#0f0f0f] text-white' : 'bg-[#f7f8fa] text-slate-900'} transition-colors duration-300`}>
      <style>{`
        :root { --theme-color: ${currentUser.profileColor || '#e21b3c'}; }
        .kahoot-shadow { box-shadow: 0 4px 0 0 rgba(0,0,0,0.2); }
        .kahoot-button-custom { background-color: var(--theme-color); border-bottom: 6px solid rgba(0,0,0,0.3); }
        .text-custom { color: var(--theme-color); }
        .bg-custom { background-color: var(--theme-color); }
        .border-custom { border-color: var(--theme-color); }
      `}</style>

      <AnimatePresence>
        {activeWarning && (
          <div className="fixed inset-0 z-[1000] flex items-center justify-center p-6 bg-black/80 backdrop-blur-md">
             <motion.div initial={{ scale: 0.8, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} className="w-full max-w-md bg-slate-900 text-white rounded-[3rem] p-10 text-center border-8 border-red-600 shadow-2xl">
                <ShieldAlert size={80} className="mx-auto text-red-600 mb-6" />
                <h2 className="text-3xl font-black italic uppercase tracking-tighter mb-4">CITIZEN WARNING</h2>
                <div className="bg-red-600 text-white inline-block px-8 py-2 rounded-full font-black text-xl mb-6 shadow-xl">VIOLATION {activeWarning.count} / 3</div>
                <button onClick={() => setActiveWarning(null)} className="w-full py-5 bg-white text-black rounded-2xl font-black uppercase text-base shadow-xl">I ACKNOWLEDGE THE ACCORDS</button>
             </motion.div>
          </div>
        )}
      </AnimatePresence>

      <Sidebar 
        activeSection={activeSection} 
        onNavigate={(s) => { setActiveSection(s); if(s === 'Profile') setViewingUsername(currentUser!.username); }} 
        isDarkMode={isDarkMode} 
        user={currentUser!} 
        unreadMessages={allMessages.filter(m => m.recipient === currentUser!.username && !m.read).length} 
        unreadNotifications={notifications.filter(n => n.recipient === currentUser!.username && !n.read).length} 
      />
      <main className="flex-1 flex flex-col min-h-0 relative pt-14 pb-16 md:pt-0 md:pb-0 h-full overflow-hidden">
        <div className={`flex-1 flex flex-col min-h-0 ${isFixedSection ? 'overflow-hidden' : 'overflow-y-auto fading-scrollbar'} p-4 md:p-8`}>
          <motion.div 
            key={activeSection + (activeSection === 'Profile' ? viewingUsername : '')} 
            initial={{ opacity: 0, y: 10 }} 
            animate={{ opacity: 1, y: 0 }} 
            className={`max-w-6xl mx-auto w-full flex-1 flex flex-col min-h-0 h-full`}
          >
            {activeSection === 'Home' && <HomeSection user={currentUser!} posts={allPosts} isDarkMode={isDarkMode} />}
            {activeSection === 'Mood' && (
              <MoodSection 
                user={currentUser!} 
                posts={allPosts} 
                onPost={(c, v) => setAllPosts(prev => [{id: Math.random().toString(36).substr(2, 9), author: currentUser!.username, content: c, likes: [], comments: [], timestamp: Date.now(), visibility: v}, ...prev])} 
                onHeart={handleHeart} 
                onDeletePost={handleDeletePost}
                onEditPost={handleEditPost}
                onComment={(pid, t) => setAllPosts(prev => prev.map(p => p.id === pid ? { ...p, comments: [...p.comments, { id: Math.random().toString(36).substr(2, 9), author: currentUser!.username, text: t, hearts: 0, timestamp: Date.now(), replies: [] }] } : p))} 
                onCommentInteraction={handleCommentInteraction} 
                onRepost={handleRepost} 
                onFollow={handleFollow} 
                onBlock={handleBlock} 
                isDarkMode={isDarkMode} 
                onNavigateToProfile={(u) => {setViewingUsername(u); setActiveSection('Profile');}} 
                onUpdatePet={updatePetStats} 
                onViolation={handleViolation}
              />
            )}
            {activeSection === 'Zodiac' && <ZodiacSection isDarkMode={isDarkMode} />}
            {activeSection === 'CityHall' && (
              <CityHallSection 
                isDarkMode={isDarkMode} 
                currentUser={currentUser!} 
                messages={allMessages} 
                groups={allGroups}
                onSendMessage={handleSendMessage} 
                onGroupUpdate={handleGroupUpdate}
                onGroupCreate={handleGroupCreate}
                onReadMessages={(u) => setAllMessages(prev => prev.map(m => (m.recipient === currentUser!.username && m.sender === u) ? {...m, read: true} : m))} 
                onNavigateToProfile={(u) => {setViewingUsername(u); setActiveSection('Profile');}} 
                onReactToMessage={handleMessageReaction} 
                onViolation={handleViolation}
              />
            )}
            {activeSection === 'Notifications' && <NotificationsSection notifications={notifications.filter(n => n.recipient === currentUser!.username)} isDarkMode={isDarkMode} onMarkRead={() => setNotifications(notifications.map(n => n.recipient === currentUser!.username ? {...n, read: true} : n))} />}
            {activeSection === 'Profile' && profileToView && <ProfileSection user={profileToView} allPosts={allPosts} isDarkMode={isDarkMode} currentUser={currentUser!} onEditProfile={(dn, un, pp, ti, bp, pc, bi) => { setCurrentUser({...currentUser!, displayName: dn, username: un, profilePic: pp, title: ti, profileColor: pc, bio: bi}); setViewingUsername(un); }} onBlock={handleBlock} onFollow={handleFollow} />}
            {activeSection === 'Settings' && <SettingsSection isDarkMode={isDarkMode} onToggleDarkMode={() => setIsDarkMode(!isDarkMode)} onLogout={handleLogout} user={currentUser!} onUnblock={(u) => { const newBlocked = currentUser!.blockedUsers.filter(b => b !== u); setCurrentUser({...currentUser!, blockedUsers: newBlocked}); }} />}
          </motion.div>
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { User, Mood, Section, Post, Comment, Message, Notification, MessageReaction, Group } from './types';
import Sidebar from './components/Sidebar';
import MoodCheckIn from './components/MoodCheckIn';
import HomeSection from './sections/HomeSection';
import MoodSection from './sections/MoodSection';
import ZodiacSection from './sections/ZodiacSection';
import CityHallSection from './sections/CityHallSection';
import ProfileSection from './sections/ProfileSection';
import SettingsSection from './sections/SettingsSection';
import NotificationsSection from './sections/NotificationsSection';
import AuthScreen from './sections/AuthScreen';
import LoadingScreen from './components/LoadingScreen';
import { getExpNeeded, MOOD_SCORES } from './constants';
import { Trophy, Share2, X, ShieldAlert, AlertOctagon, LogOut, Gavel } from 'lucide-react';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [allUsers, setAllUsers] = useState<User[]>([]);
  const [activeSection, setActiveSection] = useState<Section>('Home');
  const [viewingUsername, setViewingUsername] = useState<string | null>(null);
  const [isMoodModalOpen, setIsMoodModalOpen] = useState(false);
  const [isDarkMode, setIsDarkMode] = useState(false); 
  const [isAppStarting, setIsAppStarting] = useState(true);

  const [allPosts, setAllPosts] = useState<Post[]>([]);
  const [allMessages, setAllMessages] = useState<Message[]>([]);
  const [allGroups, setAllGroups] = useState<Group[]>([]);
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);

  const [activeWarning, setActiveWarning] = useState<{ count: number, reason: string } | null>(null);

  const migrateUserData = (user: User): User => {
    return {
      ...user,
      blockedUsers: user.blockedUsers || [],
      moodHistory: user.moodHistory || [],
      following: user.following || [],
      followers: user.followers || [],
      moodStreak: user.moodStreak || 0,
      petLevel: user.petLevel || 1,
      moodCoins: user.moodCoins ?? 100,
      gameCooldowns: user.gameCooldowns || {},
      petHasBeenChosen: !!user.petHasBeenChosen,
      warnings: user.warnings ?? 0,
      isBanned: !!user.isBanned
    };
  };

  const profileToView = useMemo(() => {
    if (!viewingUsername) return null;
    if (currentUser && viewingUsername === currentUser.username) return currentUser;
    return allUsers.find(u => u.username === viewingUsername) || null;
  }, [viewingUsername, currentUser, allUsers]);

  const addNotification = useCallback((recipient: string, type: Notification['type'], snippet: string, postId: string = '') => {
    if (!currentUser) return;
    if (recipient === currentUser.username && type !== 'achievement' && type !== 'tier' && type !== 'warning') return;

    const newNotif: Notification = {
      id: Math.random().toString(36).substr(2, 9),
      fromUser: type === 'warning' ? 'Police Force' : (currentUser?.username || 'Metropolis'),
      recipient,
      type,
      postId,
      timestamp: Date.now(),
      read: false,
      postContentSnippet: snippet
    };
    setNotifications(prev => [...prev, newNotif]);
  }, [currentUser]);

  useEffect(() => {
    const savedUser = localStorage.getItem('mooderia_user');
    const savedAllUsers = localStorage.getItem('mooderia_all_users') || '[]';
    const savedPosts = localStorage.getItem('mooderia_posts') || '[]';
    const savedMessages = localStorage.getItem('mooderia_messages') || '[]';
    const savedGroups = localStorage.getItem('mooderia_groups') || '[]';
    const savedNotifications = localStorage.getItem('mooderia_notifications') || '[]';
    const savedTheme = localStorage.getItem('mooderia_theme');

    try {
      const loadedAllUsers = JSON.parse(savedAllUsers).map(migrateUserData);
      setAllUsers(loadedAllUsers);
    } catch (e) {
      setAllUsers([]);
    }

    if (savedUser) {
      try {
        let user: User = JSON.parse(savedUser);
        user = migrateUserData(user);

        const now = Date.now();
        if (user.email === 'travismiguel014@gmail.com') user.title = 'Creator';

        const lastUpdate = user.petLastUpdate || now;
        const elapsedMinutes = Math.floor((now - lastUpdate) / 60000);

        if (elapsedMinutes > 0) {
          user.petHunger = Math.max(0, user.petHunger - elapsedMinutes * 0.15);
          user.petThirst = Math.max(0, user.petThirst - elapsedMinutes * 0.2);
          if (!user.petSleepUntil || user.petSleepUntil < now) {
            user.petRest = Math.max(0, user.petRest - elapsedMinutes * 0.1);
            user.petSleepUntil = null;
          }
          user.petLastUpdate = now;
        }
        setCurrentUser(user);
        setViewingUsername(user.username);
      } catch (e) { 
        localStorage.removeItem('mooderia_user');
      }
    }

    setAllPosts(JSON.parse(savedPosts).map((p: any) => ({ ...p, likes: Array.isArray(p.likes) ? p.likes : [] })));
    setAllMessages(JSON.parse(savedMessages));
    setAllGroups(JSON.parse(savedGroups));
    setNotifications(JSON.parse(savedNotifications));
    if (savedTheme === 'dark') setIsDarkMode(true);
    setIsLoaded(true);

    const timer = setTimeout(() => setIsAppStarting(false), 2000);
    return () => clearTimeout(timer);
  }, []);

  useEffect(() => {
    if (!isLoaded) return;
    if (currentUser) {
      localStorage.setItem('mooderia_user', JSON.stringify(currentUser));
      setAllUsers(prev => {
        const updated = [...prev];
        const idx = updated.findIndex(u => u.username === currentUser.username);
        if (idx > -1) {
          updated[idx] = { ...updated[idx], ...currentUser };
        } else {
          updated.push(currentUser);
        }
        return updated;
      });
    }
  }, [currentUser, isLoaded]);

  useEffect(() => {
    if (!isLoaded) return;
    localStorage.setItem('mooderia_all_users', JSON.stringify(allUsers));
    localStorage.setItem('mooderia_posts', JSON.stringify(allPosts));
    localStorage.setItem('mooderia_messages', JSON.stringify(allMessages));
    localStorage.setItem('mooderia_groups', JSON.stringify(allGroups));
    localStorage.setItem('mooderia_notifications', JSON.stringify(notifications));
    localStorage.setItem('mooderia_theme', isDarkMode ? 'dark' : 'light');
  }, [allUsers, allPosts, allMessages, allGroups, notifications, isDarkMode, isLoaded]);

  const handleFollow = (targetUsername: string) => {
    if (!currentUser || currentUser.username === targetUsername) return;
    const isFollowing = currentUser.following.includes(targetUsername);

    // Immediate state update for master list
    setAllUsers(prev => prev.map(u => {
      if (u.username === currentUser.username) {
        const nextFollowing = isFollowing 
          ? u.following.filter(f => f !== targetUsername)
          : [...u.following, targetUsername];
        return { ...u, following: nextFollowing };
      }
      if (u.username === targetUsername) {
        const nextFollowers = isFollowing
          ? (u.followers || []).filter(f => f !== currentUser.username)
          : [...(u.followers || []), currentUser.username];
        return { ...u, followers: nextFollowers };
      }
      return u;
    }));

    // Update currentUser local state
    const nextFollowing = isFollowing 
      ? currentUser.following.filter(f => f !== targetUsername)
      : [...currentUser.following, targetUsername];
    setCurrentUser({ ...currentUser, following: nextFollowing });

    if (!isFollowing) addNotification(targetUsername, 'follow', '');
  };

  const handleBlock = (targetUsername: string) => {
    if (!currentUser || currentUser.username === targetUsername) return;
    setAllUsers(prev => prev.map(u => {
      if (u.username === currentUser.username) {
        return { 
          ...u, 
          blockedUsers: [...u.blockedUsers, targetUsername],
          following: u.following.filter(f => f !== targetUsername),
          followers: u.followers.filter(f => f !== targetUsername)
        };
      }
      if (u.username === targetUsername) {
        return {
          ...u,
          following: u.following.filter(f => f !== currentUser.username),
          followers: u.followers.filter(f => f !== currentUser.username)
        };
      }
      return u;
    }));

    setCurrentUser({
      ...currentUser,
      blockedUsers: [...currentUser.blockedUsers, targetUsername],
      following: currentUser.following.filter(f => f !== targetUsername),
      followers: currentUser.followers.filter(f => f !== targetUsername)
    });
  };

  const handleSendMessage = (recipient: string, text: string, options?: any) => {
    if (!currentUser) return;
    const newMessage: Message = {
      id: Math.random().toString(36).substr(2, 9),
      sender: currentUser.username,
      recipient,
      text,
      timestamp: Date.now(),
      read: false,
      isGroup: options?.isGroup || false,
      isSystem: options?.isSystem || false,
      groupName: options?.groupName,
      replyToId: options?.replyToId,
      replyToText: options?.replyToText,
      replyToSender: options?.replyToSender
    };
    setAllMessages(prev => [...prev, newMessage]);
  };

  const handleGroupUpdate = (group: Group) => {
    setAllGroups(prev => prev.map(g => g.id === group.id ? group : g));
  };

  const handleGroupCreate = (group: Group) => {
    setAllGroups(prev => [...prev, group]);
  };

  const handleMessageReaction = (msgId: string, emoji: string) => {
    if (!currentUser) return;
    setAllMessages(prev => prev.map(m => {
      if (m.id === msgId) {
        const reactions = [...(m.reactions || [])];
        const reactionIdx = reactions.findIndex(r => r.emoji === emoji);

        if (reactionIdx > -1) {
          const reaction = reactions[reactionIdx];
          const userIdx = reaction.users.indexOf(currentUser.username);

          if (userIdx > -1) {
            // Unreact (Same emoji clicked twice)
            const newUsers = reaction.users.filter(u => u !== currentUser.username);
            if (newUsers.length === 0) {
              reactions.splice(reactionIdx, 1);
            } else {
              reactions[reactionIdx] = { ...reaction, users: newUsers };
            }
          } else {
            // Add user to existing reaction emoji
            reactions[reactionIdx] = { ...reaction, users: [...reaction.users, currentUser.username] };
          }
        } else {
          // Add brand new emoji reaction
          reactions.push({ emoji, users: [currentUser.username] });
        }
        return { ...m, reactions };
      }
      return m;
    }));
  };

  const onLogin = (user: User) => {
    const migrated = migrateUserData(user);
    setCurrentUser(migrated);
    setViewingUsername(migrated.username);
  };

  const handleLogout = () => {
    setCurrentUser(null);
    localStorage.removeItem('mooderia_user');
    setActiveSection('Home');
  };

  const handleHeart = (postId: string) => {
    if (!currentUser) return;
    setAllPosts(prev => prev.map(p => {
      if (p.id === postId) {
        const isLiked = p.likes.includes(currentUser.username);
        const nextLikes = isLiked 
          ? p.likes.filter(u => u !== currentUser.username)
          : [...p.likes, currentUser.username];
        if (!isLiked) addNotification(p.author, 'heart', p.content.substring(0, 20), p.id);
        return { ...p, likes: nextLikes };
      }
      return p;
    }));
  };

  const handleDeletePost = (postId: string) => setAllPosts(prev => prev.filter(p => p.id !== postId));

  const handleEditPost = (postId: string, newContent: string) => setAllPosts(prev => prev.map(p => p.id === postId ? { ...p, content: newContent } : p));

  const handleCommentInteraction = (postId: string, commentId: string, action: 'heart' | 'reply', replyText?: string) => {
    if (!currentUser) return;
    setAllPosts(prev => prev.map(p => {
      if (p.id === postId) {
        const updateComments = (comments: Comment[]): Comment[] => {
          return comments.map(c => {
            if (c.id === commentId) {
              if (action === 'heart') return { ...c, hearts: c.hearts + 1 };
              if (action === 'reply' && replyText) {
                const newReply: Comment = {
                  id: Math.random().toString(36).substr(2, 9),
                  author: currentUser.username,
                  text: replyText,
                  hearts: 0,
                  timestamp: Date.now(),
                  replies: []
                };
                return { ...c, replies: [...c.replies, newReply] };
              }
            } else if (c.replies.length > 0) {
              return { ...c, replies: updateComments(c.replies) };
            }
            return c;
          });
        };
        return { ...p, comments: updateComments(p.comments) };
      }
      return p;
    }));
  };

  const handleRepost = (post: Post) => {
    if (!currentUser) return;
    const newPost: Post = {
      id: Math.random().toString(36).substr(2, 9),
      author: currentUser.username,
      content: post.content,
      likes: [],
      comments: [],
      timestamp: Date.now(),
      isRepost: true,
      originalAuthor: post.author,
      visibility: 'global'
    };
    setAllPosts(prev => [newPost, ...prev]);
    addNotification(post.author, 'repost', post.content.substring(0, 20), post.id);
  };

  const updatePetStats = (hunger: number, thirst: number, rest: number, coins: number, exp: number = 0, sleepUntil: number | null = null, newEmoji?: string, markChosen?: boolean, newName?: string, gameCooldownId?: string) => {
    if (!currentUser) return;
    setCurrentUser(prev => {
      if (!prev) return null;
      let nextLevel = prev.petLevel;
      let nextExp = prev.petExp + exp;
      while (nextExp >= getExpNeeded(nextLevel)) {
        nextExp -= getExpNeeded(nextLevel);
        nextLevel++;
      }
      return {
        ...prev,
        petHunger: Math.min(100, Math.max(0, prev.petHunger + hunger)),
        petThirst: Math.min(100, Math.max(0, prev.petThirst + thirst)),
        petRest: Math.min(100, Math.max(0, prev.petRest + rest)),
        moodCoins: Math.max(0, prev.moodCoins + coins),
        petExp: nextExp,
        petLevel: nextLevel,
        petSleepUntil: sleepUntil !== null ? sleepUntil : prev.petSleepUntil,
        petEmoji: newEmoji || prev.petEmoji,
        petHasBeenChosen: markChosen !== undefined ? markChosen : prev.petHasBeenChosen,
        petName: newName || prev.petName,
        gameCooldowns: gameCooldownId ? { ...prev.gameCooldowns, [gameCooldownId]: Date.now() + 300000 } : prev.gameCooldowns,
        petLastUpdate: Date.now()
      };
    });
  };

  const handleViolation = (reason: string) => {
    if (!currentUser) return;
    const newWarnings = (currentUser.warnings || 0) + 1;
    const isBanned = newWarnings >= 3;
    setCurrentUser({ ...currentUser, warnings: newWarnings, isBanned });
    setActiveWarning({ count: newWarnings, reason });
    addNotification(currentUser.username, 'warning', reason);
  };

  if (isAppStarting) return <LoadingScreen />;
  if (!currentUser) return <AuthScreen onLogin={onLogin} />;

  if (currentUser.isBanned) {
    return (
      <div className="fixed inset-0 z-[1000] bg-black text-white flex flex-col items-center justify-center p-8 text-center overflow-hidden">
        <Gavel size={120} className="text-red-600 mb-8" />
        <h1 className="text-6xl md:text-8xl font-black italic uppercase tracking-tighter mb-4 text-red-600">EXILED</h1>
        <button onClick={handleLogout} className="flex items-center gap-3 bg-white text-black px-12 py-5 rounded-2xl font-black uppercase text-xl transition-all shadow-2xl z-[1001]"><LogOut size={24} /> Leave Metropolis</button>
      </div>
    );
  }

  const isFixedSection = activeSection === 'CityHall' || activeSection === 'Mood';

  return (
    <div style={{'--theme-color': currentUser.profileColor || '#e21b3c'} as React.CSSProperties} className={`h-screen max-h-screen overflow-hidden flex flex-col md:flex-row ${isDarkMode ? 'bg-[#0f0f0f] text-white' : 'bg-[#f7f8fa] text-slate-900'} transition-colors duration-300`}>
      <style>{`
        :root { --theme-color: ${currentUser.profileColor || '#e21b3c'}; }
        .kahoot-shadow { box-shadow: 0 4px 0 0 rgba(0,0,0,0.2); }
        .kahoot-button-custom { background-color: var(--theme-color); border-bottom: 6px solid rgba(0,0,0,0.3); }
        .text-custom { color: var(--theme-color); }
        .bg-custom { background-color: var(--theme-color); }
        .border-custom { border-color: var(--theme-color); }
      `}</style>

      <AnimatePresence>
        {activeWarning && (
          <div className="fixed inset-0 z-[1000] flex items-center justify-center p-6 bg-black/80 backdrop-blur-md">
             <motion.div initial={{ scale: 0.8, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} className="w-full max-w-md bg-slate-900 text-white rounded-[3rem] p-10 text-center border-8 border-red-600 shadow-2xl">
                <ShieldAlert size={80} className="mx-auto text-red-600 mb-6" />
                <h2 className="text-3xl font-black italic uppercase tracking-tighter mb-4">CITIZEN WARNING</h2>
                <div className="bg-red-600 text-white inline-block px-8 py-2 rounded-full font-black text-xl mb-6 shadow-xl">VIOLATION {activeWarning.count} / 3</div>
                <button onClick={() => setActiveWarning(null)} className="w-full py-5 bg-white text-black rounded-2xl font-black uppercase text-base shadow-xl">I ACKNOWLEDGE THE ACCORDS</button>
             </motion.div>
          </div>
        )}
      </AnimatePresence>

      <Sidebar 
        activeSection={activeSection} 
        onNavigate={(s) => { setActiveSection(s); if(s === 'Profile') setViewingUsername(currentUser!.username); }} 
        isDarkMode={isDarkMode} 
        user={currentUser!} 
        unreadMessages={allMessages.filter(m => m.recipient === currentUser!.username && !m.read).length} 
        unreadNotifications={notifications.filter(n => n.recipient === currentUser!.username && !n.read).length} 
      />
      <main className="flex-1 flex flex-col min-h-0 relative pt-14 pb-16 md:pt-0 md:pb-0 h-full overflow-hidden">
        <div className={`flex-1 flex flex-col min-h-0 ${isFixedSection ? 'overflow-hidden' : 'overflow-y-auto fading-scrollbar'} p-4 md:p-8`}>
          <motion.div 
            key={activeSection + (activeSection === 'Profile' ? viewingUsername : '')} 
            initial={{ opacity: 0, y: 10 }} 
            animate={{ opacity: 1, y: 0 }} 
            className={`max-w-6xl mx-auto w-full flex-1 flex flex-col min-h-0 h-full`}
          >
            {activeSection === 'Home' && <HomeSection user={currentUser!} posts={allPosts} isDarkMode={isDarkMode} />}
            {activeSection === 'Mood' && (
              <MoodSection 
                user={currentUser!} 
                posts={allPosts} 
                onPost={(c, v) => setAllPosts(prev => [{id: Math.random().toString(36).substr(2, 9), author: currentUser!.username, content: c, likes: [], comments: [], timestamp: Date.now(), visibility: v}, ...prev])} 
                onHeart={handleHeart} 
                onDeletePost={handleDeletePost}
                onEditPost={handleEditPost}
                onComment={(pid, t) => setAllPosts(prev => prev.map(p => p.id === pid ? { ...p, comments: [...p.comments, { id: Math.random().toString(36).substr(2, 9), author: currentUser!.username, text: t, hearts: 0, timestamp: Date.now(), replies: [] }] } : p))} 
                onCommentInteraction={handleCommentInteraction} 
                onRepost={handleRepost} 
                onFollow={handleFollow} 
                onBlock={handleBlock} 
                isDarkMode={isDarkMode} 
                onNavigateToProfile={(u) => {setViewingUsername(u); setActiveSection('Profile');}} 
                onUpdatePet={updatePetStats} 
                onViolation={handleViolation}
              />
            )}
            {activeSection === 'Zodiac' && <ZodiacSection isDarkMode={isDarkMode} />}
            {activeSection === 'CityHall' && (
              <CityHallSection 
                isDarkMode={isDarkMode} 
                currentUser={currentUser!} 
                allUsers={allUsers}
                messages={allMessages} 
                groups={allGroups}
                onSendMessage={handleSendMessage} 
                onGroupUpdate={handleGroupUpdate}
                onGroupCreate={handleGroupCreate}
                onReadMessages={(u) => setAllMessages(prev => prev.map(m => (m.recipient === currentUser!.username && m.sender === u) ? {...m, read: true} : m))} 
                onNavigateToProfile={(u) => {setViewingUsername(u); setActiveSection('Profile');}} 
                onReactToMessage={handleMessageReaction} 
                onViolation={handleViolation}
              />
            )}
            {activeSection === 'Notifications' && <NotificationsSection notifications={notifications.filter(n => n.recipient === currentUser!.username)} isDarkMode={isDarkMode} onMarkRead={() => setNotifications(notifications.map(n => n.recipient === currentUser!.username ? {...n, read: true} : n))} />}
            {activeSection === 'Profile' && profileToView && <ProfileSection user={profileToView} allPosts={allPosts} isDarkMode={isDarkMode} currentUser={currentUser!} onEditProfile={(dn, un, pp, ti, bp, pc, bi) => { setCurrentUser({...currentUser!, displayName: dn, username: un, profilePic: pp, title: ti, profileColor: pc, bio: bi}); setViewingUsername(un); }} onBlock={handleBlock} onFollow={handleFollow} />}
            {activeSection === 'Settings' && <SettingsSection isDarkMode={isDarkMode} onToggleDarkMode={() => setIsDarkMode(!isDarkMode)} onLogout={handleLogout} user={currentUser!} onUnblock={(u) => { const newBlocked = currentUser!.blockedUsers.filter(b => b !== u); setCurrentUser({...currentUser!, blockedUsers: newBlocked}); }} />}
          </motion.div>
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Send, Users, Search, MessageSquare, ArrowLeft, ShieldCheck, Check, CheckCheck, Clock, Smile, Plus, X, Reply, Radio } from 'lucide-react';
import { User, Message, MessageReaction, Group } from '../types';
import { checkContentSafety } from '../services/geminiService';

interface CityHallSectionProps {
  isDarkMode: boolean;
  currentUser: User;
  allUsers: User[];
  messages: Message[];
  groups: Group[];
  onSendMessage: (recipient: string, text: string, options?: { isGroup?: boolean, recipients?: string[], groupName?: string, replyToId?: string, replyToText?: string, replyToSender?: string, isSystem?: boolean, liaisonData?: any }) => void;
  onReadMessages: (withUsername: string) => void;
  onGroupUpdate: (group: Group) => void;
  onGroupCreate: (group: Group) => void;
  onNavigateToProfile: (username: string) => void;
  onReactToMessage: (msgId: string, emoji: string) => void;
  onViolation: (reason: string) => void;
}

const REACTION_EMOJIS = ['❤️', '😂', '😮', '😢', '🔥', '👍'];

const CityHallSection: React.FC<CityHallSectionProps> = ({ isDarkMode, currentUser, allUsers, messages, groups, onSendMessage, onReadMessages, onGroupUpdate, onGroupCreate, onNavigateToProfile, onReactToMessage, onViolation }) => {
  const [input, setInput] = useState('');
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedCitizen, setSelectedCitizen] = useState<{ username: string, displayName: string, profilePic?: string, isGroup?: boolean, recipients?: string[] } | null>(null);
  const [reactionPickerMsgId, setReactionPickerMsgId] = useState<string | null>(null);
  const [viewingReacters, setViewingReacters] = useState<MessageReaction | null>(null);
  const [replyingTo, setReplyingTo] = useState<Message | null>(null);
  const [isSending, setIsSending] = useState(false);
  const [isCreatingGroup, setIsCreatingGroup] = useState(false);
  const [groupName, setGroupName] = useState('');
  const [selectedForGroup, setSelectedForGroup] = useState<string[]>([]);

  const chatEndRef = useRef<HTMLDivElement>(null);
  const chatScrollRef = useRef<HTMLDivElement>(null);

  const chats = useMemo(() => {
    const list: any[] = [];
    const processedDms = new Set<string>();

    groups.forEach(g => {
      if (g.members.includes(currentUser.username)) {
        list.push({ 
          username: g.id, 
          displayName: g.name, 
          isGroup: true, 
          recipients: g.members,
          profilePic: g.photo || '🚀'
        });
      }
    });

    messages.forEach(m => {
      if (!m.isGroup) {
        const other = m.sender === currentUser.username ? m.recipient : m.sender;
        if (!processedDms.has(other)) {
          processedDms.add(other);
          const userObj = allUsers.find(u => u.username === other);
          if (userObj) {
            list.push({ username: other, displayName: userObj.displayName, profilePic: userObj.profilePic, isGroup: false });
          }
        }
      }
    });
    return list;
  }, [messages, allUsers, currentUser.username, groups]);

  const chatMessages = useMemo(() => {
    if (!selectedCitizen) return [];
    if (selectedCitizen.isGroup) {
      return messages.filter(m => m.isGroup && m.recipient === selectedCitizen.username).sort((a, b) => a.timestamp - b.timestamp);
    }
    return messages.filter(m => 
      !m.isGroup &&
      ((m.sender === currentUser.username && m.recipient === selectedCitizen.username) ||
      (m.sender === selectedCitizen.username && m.recipient === currentUser.username))
    ).sort((a, b) => a.timestamp - b.timestamp);
  }, [messages, selectedCitizen, currentUser.username]);

  // Handle switching conversations and new messages
  useEffect(() => {
    if (selectedCitizen && !selectedCitizen.isGroup) onReadMessages(selectedCitizen.username);

    // Smooth scroll to bottom on initial load and when switching
    setTimeout(() => {
        chatScrollRef.current?.scrollTo({
            top: chatScrollRef.current.scrollHeight,
            behavior: 'smooth'
        });
    }, 50);
  }, [selectedCitizen?.username]);

  // Auto-scroll for new incoming messages
  useEffect(() => {
    if (chatMessages.length > 0) {
        chatScrollRef.current?.scrollTo({
            top: chatScrollRef.current.scrollHeight,
            behavior: 'smooth'
        });
    }
  }, [chatMessages.length]);

  const handleSend = async () => {
    if (!input.trim() || !selectedCitizen || isSending) return;
    setIsSending(true);
    const safety = await checkContentSafety(input);
    if (safety.isInappropriate) {
      onViolation(safety.reason);
      setIsSending(false);
      return;
    }
    onSendMessage(selectedCitizen.username, input, { 
      isGroup: selectedCitizen.isGroup, 
      recipients: selectedCitizen.recipients, 
      groupName: selectedCitizen.displayName,
      replyToId: replyingTo?.id,
      replyToText: replyingTo?.text,
      replyToSender: replyingTo?.sender
    });
    setInput('');
    setReplyingTo(null);
    setIsSending(false);
  };

  const handleStartCreateGroup = () => {
    setGroupName('');
    setSelectedForGroup([]);
    setIsCreatingGroup(true);
  };

  const handleCreateGroup = () => {
    if (!groupName.trim() || selectedForGroup.length < 1) return;
    const groupId = 'group_' + Math.random().toString(36).substr(2, 9);
    const members = [...selectedForGroup, currentUser.username];
    const newGroup: Group = {
      id: groupId,
      name: groupName,
      owner: currentUser.username,
      members: members,
      nicknames: {},
      createdAt: Date.now(),
      photo: '🚀'
    };
    onGroupCreate(newGroup);
    onSendMessage(groupId, `CITIZEN TERMINAL: Group initialized.`, { isGroup: true, recipients: members, groupName, isSystem: true });
    setSelectedCitizen({ username: groupId, displayName: groupName, isGroup: true, recipients: members, profilePic: '🚀' });
    setIsCreatingGroup(false);
  };

  const filteredChats = chats.filter(c => 
    c.displayName.toLowerCase().includes(searchTerm.toLowerCase()) || 
    c.username.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div className="flex flex-col h-full min-h-0 w-full relative">
      <div className="flex justify-between items-center mb-6 shrink-0 px-2">
        <h2 className={`text-3xl md:text-4xl font-black italic uppercase tracking-tighter ${isDarkMode ? 'text-white' : 'text-slate-900'}`}>Citizen Hub</h2>
        <button onClick={handleStartCreateGroup} className="kahoot-button-blue px-6 py-3 rounded-2xl text-white font-black flex items-center gap-2 shadow-lg active:scale-95 text-xs">
          <Plus size={18} /> <span>NEW GROUP</span>
        </button>
      </div>

      <div className={`flex-1 flex flex-col md:flex-row rounded-[3rem] ${isDarkMode ? 'bg-slate-900' : 'bg-white'} shadow-2xl overflow-hidden border-4 border-black/5 relative min-h-0 h-full`}>
        {/* Citizen List / Sidebar - Independent Scroll */}
        <div className={`w-full md:w-64 lg:w-80 border-r ${isDarkMode ? 'border-slate-800' : 'border-gray-100'} flex flex-col ${selectedCitizen ? 'hidden md:flex' : 'flex'} min-h-0 h-full`}>
          <div className="p-4 border-b border-gray-100 dark:border-slate-800 shrink-0">
            <div className="relative">
              <input type="text" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} placeholder="Search..." className={`w-full pl-10 pr-4 py-3 rounded-2xl text-[12px] font-black border-2 outline-none focus:border-blue-500 transition-all ${isDarkMode ? 'bg-slate-800 border-slate-700 text-white' : 'bg-gray-50 border-gray-200 text-slate-900'}`} />
              <Search className={`absolute left-3.5 top-1/2 -translate-y-1/2 opacity-30`} size={16} />
            </div>
          </div>
          <div className="flex-1 overflow-y-auto fading-scrollbar p-3 space-y-2 min-h-0 h-full">
            {filteredChats.map(u => (
              <button key={u.username} onClick={() => setSelectedCitizen(u)} className={`w-full p-4 rounded-[1.5rem] flex items-center gap-3 transition-all border-b-4 active:translate-y-0.5 active:border-b-2 ${selectedCitizen?.username === u.username ? 'bg-blue-600 border-blue-800 text-white shadow-md' : 'hover:bg-black/5'}`}>
                <div className="w-10 h-10 rounded-xl bg-blue-100 dark:bg-slate-700 flex items-center justify-center font-black overflow-hidden shadow-sm shrink-0">
                  {u.profilePic ? <img src={u.profilePic} className="w-full h-full object-cover" /> : u.displayName[0]}
                </div>
                <div className="text-left flex-1 min-w-0">
                  <p className={`font-black text-[12px] truncate uppercase tracking-tight`}>{u.displayName}</p>
                  <p className="text-[9px] font-black uppercase tracking-widest opacity-40">@{u.username}</p>
                </div>
              </button>
            ))}
          </div>
        </div>

        {/* Message Window Area - Fixed Height with Scrollable List */}
        <div className={`flex-1 flex flex-col min-h-0 h-full ${!selectedCitizen ? 'hidden md:flex' : 'flex'}`}>
          {selectedCitizen ? (
            <>
              <div className={`p-4 border-b ${isDarkMode ? 'bg-slate-800/50 border-slate-800' : 'bg-gray-50/50 border-gray-100'} flex items-center justify-between shrink-0`}>
                <div className="flex items-center gap-4">
                  <button onClick={() => setSelectedCitizen(null)} className="md:hidden p-2"><ArrowLeft size={20} /></button>
                  <div className="flex items-center gap-3">
                    <div className="w-10 h-10 rounded-xl bg-blue-600 text-white flex items-center justify-center font-black shadow-lg overflow-hidden border-2 border-white/20">
                      {selectedCitizen.profilePic ? <img src={selectedCitizen.profilePic} className="w-full h-full object-cover" /> : selectedCitizen.displayName[0]}
                    </div>
                    <div className="text-left">
                      <p className={`font-black text-sm uppercase italic tracking-tighter ${isDarkMode ? 'text-white' : 'text-slate-900'}`}>{selectedCitizen.displayName}</p>
                      <p className="text-[10px] font-black uppercase tracking-widest opacity-30">@{selectedCitizen.username}</p>
                    </div>
                  </div>
                </div>
              </div>

              {/* Message List - The strictly scrollable part */}
              <div 
                ref={chatScrollRef}
                className="flex-1 overflow-y-auto p-4 md:p-8 space-y-6 fading-scrollbar min-h-0 h-full bg-slate-50/30 dark:bg-slate-900/10"
              >
                {chatMessages.length > 0 ? chatMessages.map(m => {
                  const isMe = m.sender === currentUser.username;
                  return (
                    <div key={m.id} className={`flex ${isMe ? 'flex-row-reverse' : 'flex-row'} items-end gap-3 group/msg relative`}>
                      <button onClick={() => onNavigateToProfile(m.sender)} className="w-8 h-8 rounded-xl bg-custom text-white font-black flex items-center justify-center shrink-0 border-2 border-white/20 shadow-md">
                        {m.sender[0].toUpperCase()}
                      </button>
                      <div className={`max-w-[80%] flex flex-col ${isMe ? 'items-end' : 'items-start'} gap-1`}>
                        {m.replyToId && (
                          <div className={`mb-1 p-2 rounded-xl text-[10px] italic border-l-4 opacity-60 ${isDarkMode ? 'bg-white/5 border-white/20' : 'bg-black/5 border-black/20'}`}>
                            <p className="font-black truncate max-w-[150px]">Echo: @{m.replyToSender}</p>
                            <p className="truncate max-w-[200px]">"{m.replyToText}"</p>
                          </div>
                        )}
                        <div className="relative group/bubble flex items-center gap-2">
                          <div className={`px-5 py-3 rounded-[1.5rem] font-bold text-sm border-b-4 ${isMe ? 'bg-blue-600 border-blue-800 text-white rounded-tr-none' : isDarkMode ? 'bg-slate-800 border-slate-900 text-white rounded-tl-none' : 'bg-white border-gray-200 text-slate-800 rounded-tl-none'}`}>
                            <p className="break-words max-w-[250px] md:max-w-md">{m.text}</p>
                          </div>
                          <div className={`flex flex-col gap-1 opacity-0 group-hover/bubble:opacity-100 transition-all shrink-0`}>
                            <button onClick={() => setReplyingTo(m)} className="p-1.5 bg-black/5 rounded-lg hover:bg-black/10 text-blue-500"><Reply size={14}/></button>
                            <button onClick={() => setReactionPickerMsgId(reactionPickerMsgId === m.id ? null : m.id)} className="p-1.5 bg-black/5 rounded-lg hover:bg-black/10 text-yellow-500"><Smile size={14}/></button>
                          </div>
                        </div>

                        {m.reactions && m.reactions.length > 0 && (
                          <div className="flex flex-wrap gap-1 mt-1">
                            {m.reactions.map(r => (
                              <button 
                                key={r.emoji} 
                                onClick={() => onReactToMessage(m.id, r.emoji)} 
                                onContextMenu={(e) => { e.preventDefault(); setViewingReacters(r); }} 
                                className={`px-2 py-0.5 rounded-full text-[10px] font-black border-2 transition-all flex items-center gap-1 ${r.users.includes(currentUser.username) ? 'bg-custom/10 border-custom' : isDarkMode ? 'bg-slate-800 border-slate-700' : 'bg-white border-gray-100'}`}
                              >
                                <span>{r.emoji}</span>
                                <span>{r.users.length}</span>
                              </button>
                            ))}
                          </div>
                        )}
                      </div>

                      <AnimatePresence>
                        {reactionPickerMsgId === m.id && (
                          <motion.div initial={{ scale: 0.8, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} exit={{ scale: 0.8, opacity: 0 }} className={`absolute z-20 bottom-full mb-2 p-2 rounded-2xl flex gap-2 shadow-2xl border-4 ${isDarkMode ? 'bg-slate-800 border-white/10' : 'bg-white border-black/10'}`}>
                            {REACTION_EMOJIS.map(e => (
                              <button key={e} onClick={() => { onReactToMessage(m.id, e); setReactionPickerMsgId(null); }} className="text-xl hover:scale-125 transition-transform">{e}</button>
                            ))}
                          </motion.div>
                        )}
                      </AnimatePresence>
                    </div>
                  );
                }) : (
                  <div className="h-full flex flex-col items-center justify-center opacity-10 py-10">
                    <MessageSquare size={80} />
                    <p className="font-black uppercase italic text-xl mt-4">Begin Connection</p>
                  </div>
                )}
                <div ref={chatEndRef} />
              </div>

              {/* Footer Input Area - Always Fixed at Bottom */}
              <div className="shrink-0 border-t border-gray-100 dark:border-slate-800">
                <AnimatePresence>
                  {replyingTo && (
                    <motion.div initial={{ height: 0, opacity: 0 }} animate={{ height: 'auto', opacity: 1 }} exit={{ height: 0, opacity: 0 }} className={`px-6 py-2 flex items-center justify-between ${isDarkMode ? 'bg-slate-800/80' : 'bg-blue-50/80'} backdrop-blur-sm`}>
                      <div className="flex items-center gap-3">
                        <Reply size={14} className="text-blue-500" />
                        <div className="text-[9px] leading-tight">
                          <p className="font-black uppercase tracking-widest text-blue-500">Replying to @{replyingTo.sender}</p>
                          <p className="opacity-60 truncate max-w-xs md:max-w-md italic">"{replyingTo.text}"</p>
                        </div>
                      </div>
                      <button onClick={() => setReplyingTo(null)} className="p-1 rounded-full bg-black/5 hover:bg-black/10"><X size={12}/></button>
                    </motion.div>
                  )}
                </AnimatePresence>
                <div className="p-4 md:p-6">
                  <div className={`flex items-center gap-3 p-2 rounded-[2rem] border-4 transition-all ${isDarkMode ? 'bg-slate-800 border-slate-700' : 'bg-gray-50 border-gray-200'} focus-within:border-blue-500 shadow-inner`}>
                    <input type="text" value={input} onChange={(e) => setInput(e.target.value)} onKeyPress={(e) => e.key === 'Enter' && handleSend()} placeholder="Type frequency..." className={`flex-1 bg-transparent px-5 py-3 font-black text-sm outline-none ${isDarkMode ? 'text-white' : 'text-slate-900'}`} />
                    <button onClick={handleSend} disabled={isSending} className="kahoot-button-blue p-4 rounded-2xl text-white shadow-xl active:scale-95 transition-all disabled:opacity-50"><Send size={20} /></button>
                  </div>
                </div>
              </div>
            </>
          ) : (
            <div className="flex-1 flex flex-col items-center justify-center p-12 text-center opacity-20 h-full">
              <Radio size={80} className="mb-6 animate-pulse" />
              <h3 className="text-3xl font-black uppercase italic tracking-tighter mb-4">Neural Hub</h3>
              <p className="text-xs font-black uppercase tracking-widest">Select a signal frequency to start communicating</p>
            </div>
          )}
        </div>
      </div>

      {/* Reacters Modal */}
      <AnimatePresence>
        {viewingReacters && (
          <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-black/80 backdrop-blur-md">
            <motion.div initial={{ scale: 0.9, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} className={`w-full max-w-sm rounded-[3rem] p-8 ${isDarkMode ? 'bg-slate-900 border-white/10' : 'bg-white border-black/5'} border-4 shadow-2xl relative`}>
              <button onClick={() => setViewingReacters(null)} className="absolute top-6 right-6 opacity-40 hover:opacity-100 transition-all"><X size={24}/></button>
              <h3 className="text-xl font-black uppercase italic mb-6">Synchronization Core {viewingReacters.emoji}</h3>
              <div className="space-y-2 max-h-[300px] overflow-y-auto fading-scrollbar">
                {viewingReacters.users.map(u => (
                  <button key={u} onClick={() => { onNavigateToProfile(u); setViewingReacters(null); }} className="w-full p-3 rounded-2xl flex items-center gap-3 hover:bg-black/5 transition-all">
                    <div className="w-8 h-8 rounded-lg bg-custom text-white font-black flex items-center justify-center italic text-xs border-2 border-white/20 shrink-0">{u[0].toUpperCase()}</div>
                    <p className="text-[12px] font-black uppercase text-left">@{u}</p>
                  </button>
                ))}
              </div>
            </motion.div>
          </div>
        )}
      </AnimatePresence>

      {/* Group Create Modal */}
      <AnimatePresence>
        {isCreatingGroup && (
          <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-black/90 backdrop-blur-md">
            <motion.div initial={{ scale: 0.9, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} className={`${isDarkMode ? 'bg-slate-900 border-white/10' : 'bg-white border-black/5'} w-full max-w-md rounded-[3rem] p-10 border-4 shadow-2xl`}>
              <div className="flex justify-between items-center mb-8"><h3 className="text-2xl font-black uppercase italic">Initialize Group</h3><button onClick={() => setIsCreatingGroup(false)} className="opacity-40"><X size={28}/></button></div>
              <div className="space-y-6">
                 <input type="text" value={groupName} onChange={e => setGroupName(e.target.value)} placeholder="Group Name..." className="w-full p-4 rounded-2xl border-2 bg-black/5 font-black text-center text-lg outline-none focus:border-custom" />
                 <div className="max-h-48 overflow-y-auto fading-scrollbar p-2 space-y-2 bg-black/5 rounded-2xl">
                    {allUsers.filter(u => u.username !== currentUser.username).map(u => (
                      <button key={u.username} onClick={() => setSelectedForGroup(prev => prev.includes(u.username) ? prev.filter(x => x !== u.username) : [...prev, u.username])} className={`w-full p-3 rounded-xl flex items-center gap-3 transition-all ${selectedForGroup.includes(u.username) ? 'bg-blue-600 text-white shadow-md' : 'hover:bg-black/5'}`}>
                         <div className="w-8 h-8 rounded-lg bg-custom text-white font-black flex items-center justify-center italic text-xs shrink-0">{u.displayName[0]}</div>
                         <p className="text-[12px] font-black uppercase flex-1 text-left">{u.displayName}</p>
                         {selectedForGroup.includes(u.username) && <Check size={16}/>}
                      </button>
                    ))}
                 </div>
                 <button onClick={handleCreateGroup} disabled={!groupName.trim() || selectedForGroup.length === 0} className="kahoot-button-blue w-full py-5 rounded-2xl text-white font-black uppercase text-sm shadow-xl active:scale-95 transition-all">Launch Network</button>
              </div>
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </div>
  );
};

export default CityHallSection;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Send, Users, Search, MessageSquare, ArrowLeft, ShieldCheck, Check, CheckCheck, Clock, Smile, Plus, X, Reply, Radio } from 'lucide-react';
import { User, Message, MessageReaction, Group } from '../types';
import { checkContentSafety } from '../services/geminiService';

interface CityHallSectionProps {
  isDarkMode: boolean;
  currentUser: User;
  allUsers: User[];
  messages: Message[];
  groups: Group[];
  onSendMessage: (recipient: string, text: string, options?: { isGroup?: boolean, recipients?: string[], groupName?: string, replyToId?: string, replyToText?: string, replyToSender?: string, isSystem?: boolean, liaisonData?: any }) => void;
  onReadMessages: (withUsername: string) => void;
  onGroupUpdate: (group: Group) => void;
  onGroupCreate: (group: Group) => void;
  onNavigateToProfile: (username: string) => void;
  onReactToMessage: (msgId: string, emoji: string) => void;
  onViolation: (reason: string) => void;
}

const REACTION_EMOJIS = ['❤️', '😂', '😮', '😢', '🔥', '👍'];

const CityHallSection: React.FC<CityHallSectionProps> = ({ isDarkMode, currentUser, allUsers, messages, groups, onSendMessage, onReadMessages, onGroupUpdate, onGroupCreate, onNavigateToProfile, onReactToMessage, onViolation }) => {
  const [input, setInput] = useState('');
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedCitizen, setSelectedCitizen] = useState<{ username: string, isGroup?: boolean } | null>(null);
  const [reactionPickerMsgId, setReactionPickerMsgId] = useState<string | null>(null);
  const [viewingReacters, setViewingReacters] = useState<MessageReaction | null>(null);
  const [replyingTo, setReplyingTo] = useState<Message | null>(null);
  const [isSending, setIsSending] = useState(false);
  const [isCreatingGroup, setIsCreatingGroup] = useState(false);
  const [groupName, setGroupName] = useState('');
  const [selectedForGroup, setSelectedForGroup] = useState<string[]>([]);

  const chatScrollRef = useRef<HTMLDivElement>(null);

  // Helper to get the most up-to-date user data
  const getUserByUsername = (username: string) => allUsers.find(u => u.username === username);

  // Helper to get group data
  const getGroupById = (id: string) => groups.find(g => g.id === id);

  const chats = useMemo(() => {
    const list: any[] = [];
    const processedDms = new Set<string>();

    groups.forEach(g => {
      if (g.members.includes(currentUser.username)) {
        list.push({ 
          username: g.id, 
          displayName: g.name, 
          isGroup: true, 
          profilePic: g.photo || '🚀'
        });
      }
    });

    messages.forEach(m => {
      if (!m.isGroup) {
        const other = m.sender === currentUser.username ? m.recipient : m.sender;
        if (!processedDms.has(other)) {
          processedDms.add(other);
          const userObj = getUserByUsername(other);
          if (userObj) {
            list.push({ username: other, displayName: userObj.displayName, profilePic: userObj.profilePic, isGroup: false });
          }
        }
      }
    });
    return list;
  }, [messages, allUsers, currentUser.username, groups]);

  const activeChatInfo = useMemo(() => {
    if (!selectedCitizen) return null;
    if (selectedCitizen.isGroup) {
      const g = getGroupById(selectedCitizen.username);
      return {
        username: selectedCitizen.username,
        displayName: g?.name || 'Group',
        profilePic: g?.photo || '🚀',
        isGroup: true,
        recipients: g?.members
      };
    } else {
      const u = getUserByUsername(selectedCitizen.username);
      return {
        username: selectedCitizen.username,
        displayName: u?.displayName || selectedCitizen.username,
        profilePic: u?.profilePic,
        isGroup: false
      };
    }
  }, [selectedCitizen, allUsers, groups]);

  const chatMessages = useMemo(() => {
    if (!selectedCitizen) return [];
    if (selectedCitizen.isGroup) {
      return messages.filter(m => m.isGroup && m.recipient === selectedCitizen.username).sort((a, b) => a.timestamp - b.timestamp);
    }
    return messages.filter(m => 
      !m.isGroup &&
      ((m.sender === currentUser.username && m.recipient === selectedCitizen.username) ||
      (m.sender === selectedCitizen.username && m.recipient === currentUser.username))
    ).sort((a, b) => a.timestamp - b.timestamp);
  }, [messages, selectedCitizen, currentUser.username]);

  useEffect(() => {
    if (selectedCitizen && !selectedCitizen.isGroup) onReadMessages(selectedCitizen.username);

    // Smooth scroll to bottom on initial load and when switching
    setTimeout(() => {
        chatScrollRef.current?.scrollTo({
            top: chatScrollRef.current.scrollHeight,
            behavior: 'smooth'
        });
    }, 50);
  }, [selectedCitizen?.username]);

  useEffect(() => {
    if (chatMessages.length > 0) {
        chatScrollRef.current?.scrollTo({
            top: chatScrollRef.current.scrollHeight,
            behavior: 'smooth'
        });
    }
  }, [chatMessages.length]);

  const handleSend = async () => {
    if (!input.trim() || !activeChatInfo || isSending) return;
    setIsSending(true);
    const safety = await checkContentSafety(input);
    if (safety.isInappropriate) {
      onViolation(safety.reason);
      setIsSending(false);
      return;
    }
    onSendMessage(activeChatInfo.username, input, { 
      isGroup: activeChatInfo.isGroup, 
      recipients: activeChatInfo.recipients, 
      groupName: activeChatInfo.displayName,
      replyToId: replyingTo?.id,
      replyToText: replyingTo?.text,
      replyToSender: replyingTo?.sender
    });
    setInput('');
    setReplyingTo(null);
    setIsSending(false);
  };

  const handleStartCreateGroup = () => {
    setGroupName('');
    setSelectedForGroup([]);
    setIsCreatingGroup(true);
  };

  const handleCreateGroup = () => {
    if (!groupName.trim() || selectedForGroup.length < 1) return;
    const groupId = 'group_' + Math.random().toString(36).substr(2, 9);
    const members = [...selectedForGroup, currentUser.username];
    const newGroup: Group = {
      id: groupId,
      name: groupName,
      owner: currentUser.username,
      members: members,
      nicknames: {},
      createdAt: Date.now(),
      photo: '🚀'
    };
    onGroupCreate(newGroup);
    onSendMessage(groupId, `CITIZEN TERMINAL: Group initialized.`, { isGroup: true, recipients: members, groupName, isSystem: true });
    setSelectedCitizen({ username: groupId, isGroup: true });
    setIsCreatingGroup(false);
  };

  const filteredChats = chats.filter(c => 
    c.displayName.toLowerCase().includes(searchTerm.toLowerCase()) || 
    c.username.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const formatMessageTime = (ts: number) => {
    return new Date(ts).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
  };

  return (
    <div className="flex flex-col h-full min-h-0 w-full relative">
      <div className="flex justify-between items-center mb-6 shrink-0 px-2">
        <h2 className={`text-3xl md:text-4xl font-black italic uppercase tracking-tighter ${isDarkMode ? 'text-white' : 'text-slate-900'}`}>Citizen Hub</h2>
        <button onClick={handleStartCreateGroup} className="kahoot-button-blue px-6 py-3 rounded-2xl text-white font-black flex items-center gap-2 shadow-lg active:scale-95 text-xs">
          <Plus size={18} /> <span>NEW GROUP</span>
        </button>
      </div>

      <div className={`flex-1 flex flex-col md:flex-row rounded-[3rem] ${isDarkMode ? 'bg-slate-900' : 'bg-white'} shadow-2xl overflow-hidden border-4 border-black/5 relative min-h-0 h-full`}>
        {/* Sidebar */}
        <div className={`w-full md:w-64 lg:w-80 border-r ${isDarkMode ? 'border-slate-800' : 'border-gray-100'} flex flex-col ${selectedCitizen ? 'hidden md:flex' : 'flex'} min-h-0 h-full`}>
          <div className="p-4 border-b border-gray-100 dark:border-slate-800 shrink-0">
            <div className="relative">
              <input type="text" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} placeholder="Search frequency..." className={`w-full pl-10 pr-4 py-3 rounded-2xl text-[12px] font-black border-2 outline-none focus:border-blue-500 transition-all ${isDarkMode ? 'bg-slate-800 border-slate-700 text-white' : 'bg-gray-50 border-gray-200 text-slate-900'}`} />
              <Search className="absolute left-3.5 top-1/2 -translate-y-1/2 opacity-30" size={16} />
            </div>
          </div>
          <div className="flex-1 overflow-y-auto fading-scrollbar p-3 space-y-2 min-h-0 h-full">
            {filteredChats.map(chat => (
              <button key={chat.username} onClick={() => setSelectedCitizen({ username: chat.username, isGroup: chat.isGroup })} className={`w-full p-4 rounded-[1.5rem] flex items-center gap-3 transition-all border-b-4 active:translate-y-0.5 active:border-b-2 ${selectedCitizen?.username === chat.username ? 'bg-blue-600 border-blue-800 text-white shadow-md' : 'hover:bg-black/5'}`}>
                <div className="w-10 h-10 rounded-xl bg-blue-100 dark:bg-slate-700 flex items-center justify-center font-black overflow-hidden shadow-sm shrink-0">
                  {chat.profilePic ? <img src={chat.profilePic} className="w-full h-full object-cover" /> : chat.displayName[0]}
                </div>
                <div className="text-left flex-1 min-w-0">
                  <p className="font-black text-[12px] truncate uppercase tracking-tight">{chat.displayName}</p>
                  <p className="text-[9px] font-black uppercase tracking-widest opacity-40">@{chat.username}</p>
                </div>
              </button>
            ))}
          </div>
        </div>

        {/* Message Window Area */}
        <div className={`flex-1 flex flex-col min-h-0 h-full ${!selectedCitizen ? 'hidden md:flex' : 'flex'}`}>
          {activeChatInfo ? (
            <>
              <div className={`p-4 border-b ${isDarkMode ? 'bg-slate-800/50 border-slate-800' : 'bg-gray-50/50 border-gray-100'} flex items-center justify-between shrink-0`}>
                <div className="flex items-center gap-4">
                  <button onClick={() => setSelectedCitizen(null)} className="md:hidden p-2 text-custom"><ArrowLeft size={24} /></button>
                  <div className="flex items-center gap-3">
                    <div className="w-10 h-10 rounded-xl bg-blue-600 text-white flex items-center justify-center font-black shadow-lg overflow-hidden border-2 border-white/20">
                      {activeChatInfo.profilePic ? <img src={activeChatInfo.profilePic} className="w-full h-full object-cover" /> : activeChatInfo.displayName[0]}
                    </div>
                    <div className="text-left">
                      <p className={`font-black text-sm uppercase italic tracking-tighter ${isDarkMode ? 'text-white' : 'text-slate-900'}`}>{activeChatInfo.displayName}</p>
                      <p className="text-[10px] font-black uppercase tracking-widest opacity-30">@{activeChatInfo.username}</p>
                    </div>
                  </div>
                </div>
                {!activeChatInfo.isGroup && (
                  <button onClick={() => onNavigateToProfile(activeChatInfo.username)} className="text-[10px] font-black uppercase tracking-widest text-custom hover:underline px-4">View ID</button>
                )}
              </div>

              {/* Message List */}
              <div 
                ref={chatScrollRef}
                className="flex-1 overflow-y-auto p-4 md:p-8 space-y-6 fading-scrollbar min-h-0 h-full bg-slate-50/30 dark:bg-slate-900/10"
              >
                {chatMessages.length > 0 ? chatMessages.map(m => {
                  const isMe = m.sender === currentUser.username;
                  const sender = getUserByUsername(m.sender);
                  return (
                    <div key={m.id} className={`flex ${isMe ? 'flex-row-reverse' : 'flex-row'} items-end gap-3 group/msg relative`}>
                      <button onClick={() => onNavigateToProfile(m.sender)} className="w-8 h-8 rounded-xl bg-custom text-white font-black flex items-center justify-center shrink-0 border-2 border-white/20 shadow-md overflow-hidden">
                        {sender?.profilePic ? <img src={sender.profilePic} className="w-full h-full object-cover" /> : m.sender[0].toUpperCase()}
                      </button>
                      <div className={`max-w-[80%] flex flex-col ${isMe ? 'items-end' : 'items-start'} gap-1`}>
                        {m.replyToId && (
                          <div className={`mb-1 p-2 rounded-xl text-[10px] italic border-l-4 opacity-60 ${isDarkMode ? 'bg-white/5 border-white/20' : 'bg-black/5 border-black/20'}`}>
                            <p className="font-black truncate max-w-[150px]">Echo: @{m.replyToSender}</p>
                            <p className="truncate max-w-[200px]">"{m.replyToText}"</p>
                          </div>
                        )}
                        <div className={`relative group/bubble flex items-center gap-2 ${isMe ? 'flex-row-reverse' : 'flex-row'}`}>
                          <div className={`px-5 py-3 rounded-[1.5rem] font-bold text-sm border-b-4 ${isMe ? 'bg-blue-600 border-blue-800 text-white rounded-tr-none' : isDarkMode ? 'bg-slate-800 border-slate-900 text-white rounded-tl-none' : 'bg-white border-gray-200 text-slate-800 rounded-tl-none'}`}>
                            <p className="break-words max-w-[250px] md:max-w-md">{m.text}</p>
                          </div>
                          <div className={`flex flex-col gap-1 opacity-0 group-hover/bubble:opacity-100 transition-all shrink-0`}>
                            <button onClick={() => setReplyingTo(m)} className="p-1.5 bg-black/5 rounded-lg hover:bg-black/10 text-blue-500"><Reply size={14}/></button>
                            <button onClick={() => setReactionPickerMsgId(reactionPickerMsgId === m.id ? null : m.id)} className="p-1.5 bg-black/5 rounded-lg hover:bg-black/10 text-yellow-500"><Smile size={14}/></button>
                          </div>
                        </div>

                        {/* Timestamp & Reactions Container */}
                        <div className={`flex flex-wrap items-center gap-2 mt-1 ${isMe ? 'justify-end' : 'justify-start'}`}>
                          <p className="text-[9px] font-black uppercase opacity-20 tracking-tighter">{formatMessageTime(m.timestamp)}</p>
                          {m.reactions && m.reactions.length > 0 && m.reactions.map(r => (
                            <button 
                              key={r.emoji} 
                              onClick={() => onReactToMessage(m.id, r.emoji)} 
                              onContextMenu={(e) => { e.preventDefault(); setViewingReacters(r); }} 
                              className={`px-2 py-0.5 rounded-full text-[10px] font-black border-2 transition-all flex items-center gap-1 ${r.users.includes(currentUser.username) ? 'bg-custom/10 border-custom' : isDarkMode ? 'bg-slate-800 border-slate-700' : 'bg-white border-gray-100'}`}
                            >
                              <span>{r.emoji}</span>
                              <span className="opacity-60">{r.users.length}</span>
                            </button>
                          ))}
                        </div>
                      </div>

                      <AnimatePresence>
                        {reactionPickerMsgId === m.id && (
                          <motion.div initial={{ scale: 0.8, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} exit={{ scale: 0.8, opacity: 0 }} className={`absolute z-20 bottom-full mb-2 p-2 rounded-2xl flex gap-2 shadow-2xl border-4 ${isDarkMode ? 'bg-slate-800 border-white/10' : 'bg-white border-black/10'}`}>
                            {REACTION_EMOJIS.map(e => (
                              <button key={e} onClick={() => { onReactToMessage(m.id, e); setReactionPickerMsgId(null); }} className="text-xl hover:scale-125 transition-transform">{e}</button>
                            ))}
                          </motion.div>
                        )}
                      </AnimatePresence>
                    </div>
                  );
                }) : (
                  <div className="h-full flex flex-col items-center justify-center opacity-10 py-10">
                    <MessageSquare size={80} />
                    <p className="font-black uppercase italic text-xl mt-4">Begin Connection</p>
                  </div>
                )}
              </div>

              {/* Footer */}
              <div className="shrink-0 border-t border-gray-100 dark:border-slate-800 bg-white/50 dark:bg-slate-900/50 backdrop-blur-md">
                <AnimatePresence>
                  {replyingTo && (
                    <motion.div initial={{ height: 0, opacity: 0 }} animate={{ height: 'auto', opacity: 1 }} exit={{ height: 0, opacity: 0 }} className={`px-6 py-2 flex items-center justify-between ${isDarkMode ? 'bg-slate-800/80' : 'bg-blue-50/80'}`}>
                      <div className="flex items-center gap-3">
                        <Reply size={14} className="text-blue-500" />
                        <div className="text-[9px] leading-tight">
                          <p className="font-black uppercase tracking-widest text-blue-500">Replying to @{replyToName(replyingTo.sender)}</p>
                          <p className="opacity-60 truncate max-w-xs md:max-w-md italic">"{replyingTo.text}"</p>
                        </div>
                      </div>
                      <button onClick={() => setReplyingTo(null)} className="p-1 rounded-full bg-black/5 hover:bg-black/10"><X size={12}/></button>
                    </motion.div>
                  )}
                </AnimatePresence>
                <div className="p-4 md:p-6">
                  <div className={`flex items-center gap-3 p-2 rounded-[2rem] border-4 transition-all ${isDarkMode ? 'bg-slate-800 border-slate-700' : 'bg-gray-50 border-gray-200'} focus-within:border-blue-500 shadow-inner`}>
                    <input type="text" value={input} onChange={(e) => setInput(e.target.value)} onKeyPress={(e) => e.key === 'Enter' && handleSend()} placeholder="Type frequency..." className={`flex-1 bg-transparent px-5 py-3 font-black text-sm outline-none ${isDarkMode ? 'text-white' : 'text-slate-900'}`} />
                    <button onClick={handleSend} disabled={isSending || !input.trim()} className="kahoot-button-blue p-4 rounded-2xl text-white shadow-xl active:scale-95 transition-all disabled:opacity-50"><Send size={20} /></button>
                  </div>
                </div>
              </div>
            </>
          ) : (
            <div className="flex-1 flex flex-col items-center justify-center p-12 text-center opacity-20 h-full">
              <Radio size={80} className="mb-6 animate-pulse" />
              <h3 className="text-3xl font-black uppercase italic tracking-tighter mb-4">Neural Hub</h3>
              <p className="text-xs font-black uppercase tracking-widest">Select a signal frequency to start communicating</p>
            </div>
          )}
        </div>
      </div>

      {/* Reacters Modal */}
      <AnimatePresence>
        {viewingReacters && (
          <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-black/80 backdrop-blur-md">
            <motion.div initial={{ scale: 0.9, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} className={`w-full max-w-sm rounded-[3rem] p-8 ${isDarkMode ? 'bg-slate-900 border-white/10' : 'bg-white border-black/5'} border-4 shadow-2xl relative`}>
              <button onClick={() => setViewingReacters(null)} className="absolute top-6 right-6 opacity-40 hover:opacity-100 transition-all"><X size={24}/></button>
              <h3 className="text-xl font-black uppercase italic mb-6">Synchronization Core {viewingReacters.emoji}</h3>
              <div className="space-y-2 max-h-[300px] overflow-y-auto fading-scrollbar">
                {viewingReacters.users.map(u => {
                  const rUser = getUserByUsername(u);
                  return (
                    <button key={u} onClick={() => { onNavigateToProfile(u); setViewingReacters(null); }} className="w-full p-3 rounded-2xl flex items-center gap-3 hover:bg-black/5 transition-all text-left">
                      <div className="w-8 h-8 rounded-lg bg-custom text-white font-black flex items-center justify-center italic text-xs border-2 border-white/20 shrink-0 overflow-hidden">
                        {rUser?.profilePic ? <img src={rUser.profilePic} className="w-full h-full object-cover" /> : u[0].toUpperCase()}
                      </div>
                      <div className="flex-1">
                        <p className="text-[12px] font-black uppercase truncate">{rUser?.displayName || u}</p>
                        <p className="text-[8px] font-black opacity-40 uppercase tracking-widest">@{u}</p>
                      </div>
                    </button>
                  );
                })}
              </div>
            </motion.div>
          </div>
        )}
      </AnimatePresence>

      {/* Group Create Modal */}
      <AnimatePresence>
        {isCreatingGroup && (
          <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-black/90 backdrop-blur-md">
            <motion.div initial={{ scale: 0.9, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} className={`${isDarkMode ? 'bg-slate-900 border-white/10' : 'bg-white border-black/5'} w-full max-w-md rounded-[3rem] p-10 border-4 shadow-2xl`}>
              <div className="flex justify-between items-center mb-8"><h3 className="text-2xl font-black uppercase italic">Initialize Group</h3><button onClick={() => setIsCreatingGroup(false)} className="opacity-40"><X size={28}/></button></div>
              <div className="space-y-6">
                 <input type="text" value={groupName} onChange={e => setGroupName(e.target.value)} placeholder="Group Designation..." className="w-full p-4 rounded-2xl border-2 bg-black/5 font-black text-center text-lg outline-none focus:border-custom" />
                 <div className="max-h-48 overflow-y-auto fading-scrollbar p-2 space-y-2 bg-black/5 rounded-2xl">
                    {allUsers.filter(u => u.username !== currentUser.username).map(u => (
                      <button key={u.username} onClick={() => setSelectedForGroup(prev => prev.includes(u.username) ? prev.filter(x => x !== u.username) : [...prev, u.username])} className={`w-full p-3 rounded-xl flex items-center gap-3 transition-all ${selectedForGroup.includes(u.username) ? 'bg-blue-600 text-white shadow-md' : 'hover:bg-black/5'}`}>
                         <div className="w-8 h-8 rounded-lg bg-custom text-white font-black flex items-center justify-center italic text-xs shrink-0 overflow-hidden">
                           {u.profilePic ? <img src={u.profilePic} className="w-full h-full object-cover" /> : u.displayName[0]}
                         </div>
                         <p className="text-[12px] font-black uppercase flex-1 text-left">{u.displayName}</p>
                         {selectedForGroup.includes(u.username) && <Check size={16}/>}
                      </button>
                    ))}
                 </div>
                 <button onClick={handleCreateGroup} disabled={!groupName.trim() || selectedForGroup.length === 0} className="kahoot-button-blue w-full py-5 rounded-2xl text-white font-black uppercase text-sm shadow-xl active:scale-95 transition-all">Launch Network</button>
              </div>
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </div>
  );

  function replyToName(username: string) {
    const u = getUserByUsername(username);
    return u?.displayName || username;
  }
};

export default CityHallSection;

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { User, Mood, Section, Post, Comment, Message, Notification, Group } from './types';
import Sidebar from './components/Sidebar';
import HomeSection from './sections/HomeSection';
import MoodSection from './sections/MoodSection';
import ZodiacSection from './sections/ZodiacSection';
import CityHallSection from './sections/CityHallSection';
import ProfileSection from './sections/ProfileSection';
import SettingsSection from './sections/SettingsSection';
import NotificationsSection from './sections/NotificationsSection';
import AuthScreen from './sections/AuthScreen';
import LoadingScreen from './components/LoadingScreen';
import { getExpNeeded } from './constants';
import { LogOut, Gavel, ShieldAlert } from 'lucide-react';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [allUsers, setAllUsers] = useState<User[]>([]);
  const [activeSection, setActiveSection] = useState<Section>('Home');
  const [viewingUsername, setViewingUsername] = useState<string | null>(null);
  const [isDarkMode, setIsDarkMode] = useState(false); 
  const [isAppStarting, setIsAppStarting] = useState(true);

  const [allPosts, setAllPosts] = useState<Post[]>([]);
  const [allMessages, setAllMessages] = useState<Message[]>([]);
  const [allGroups, setAllGroups] = useState<Group[]>([]);
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);

  const [activeWarning, setActiveWarning] = useState<{ count: number, reason: string } | null>(null);

  const migrateUserData = (user: User): User => {
    return {
      ...user,
      blockedUsers: user.blockedUsers || [],
      moodHistory: user.moodHistory || [],
      following: user.following || [],
      followers: user.followers || [],
      moodStreak: user.moodStreak || 0,
      petLevel: user.petLevel || 1,
      moodCoins: user.moodCoins ?? 100,
      gameCooldowns: user.gameCooldowns || {},
      petHasBeenChosen: !!user.petHasBeenChosen,
      warnings: user.warnings ?? 0,
      isBanned: !!user.isBanned
    };
  };

  const profileToView = useMemo(() => {
    if (!viewingUsername) return null;
    if (currentUser && viewingUsername === currentUser.username) return currentUser;
    return allUsers.find(u => u.username === viewingUsername) || null;
  }, [viewingUsername, currentUser, allUsers]);

  const addNotification = useCallback((recipient: string, type: Notification['type'], snippet: string, postId: string = '') => {
    if (!currentUser) return;
    if (recipient === currentUser.username && type !== 'achievement' && type !== 'tier' && type !== 'warning') return;

    const newNotif: Notification = {
      id: Math.random().toString(36).substr(2, 9),
      fromUser: type === 'warning' ? 'Police Force' : (currentUser?.username || 'Metropolis'),
      recipient,
      type,
      postId,
      timestamp: Date.now(),
      read: false,
      postContentSnippet: snippet
    };
    setNotifications(prev => [...prev, newNotif]);
  }, [currentUser]);

  useEffect(() => {
    const savedUser = localStorage.getItem('mooderia_user');
    const savedAllUsers = localStorage.getItem('mooderia_all_users') || '[]';
    const savedPosts = localStorage.getItem('mooderia_posts') || '[]';
    const savedMessages = localStorage.getItem('mooderia_messages') || '[]';
    const savedGroups = localStorage.getItem('mooderia_groups') || '[]';
    const savedNotifications = localStorage.getItem('mooderia_notifications') || '[]';
    const savedTheme = localStorage.getItem('mooderia_theme');

    try {
      const loadedAllUsers = JSON.parse(savedAllUsers).map(migrateUserData);
      setAllUsers(loadedAllUsers);
    } catch (e) {
      setAllUsers([]);
    }

    if (savedUser) {
      try {
        let user: User = JSON.parse(savedUser);
        user = migrateUserData(user);

        const now = Date.now();
        if (user.email === 'travismiguel014@gmail.com') user.title = 'Creator';

        const lastUpdate = user.petLastUpdate || now;
        const elapsedMinutes = Math.floor((now - lastUpdate) / 60000);

        if (elapsedMinutes > 0) {
          user.petHunger = Math.max(0, user.petHunger - elapsedMinutes * 0.15);
          user.petThirst = Math.max(0, user.petThirst - elapsedMinutes * 0.2);
          if (!user.petSleepUntil || user.petSleepUntil < now) {
            user.petRest = Math.max(0, user.petRest - elapsedMinutes * 0.1);
            user.petSleepUntil = null;
          }
          user.petLastUpdate = now;
        }
        setCurrentUser(user);
        setViewingUsername(user.username);
      } catch (e) { 
        localStorage.removeItem('mooderia_user');
      }
    }

    setAllPosts(JSON.parse(savedPosts).map((p: any) => ({ ...p, likes: Array.isArray(p.likes) ? p.likes : [] })));
    setAllMessages(JSON.parse(savedMessages));
    setAllGroups(JSON.parse(savedGroups));
    setNotifications(JSON.parse(savedNotifications));
    if (savedTheme === 'dark') setIsDarkMode(true);
    setIsLoaded(true);

    const timer = setTimeout(() => setIsAppStarting(false), 2000);
    return () => clearTimeout(timer);
  }, []);

  useEffect(() => {
    if (!isLoaded) return;
    if (currentUser) {
      localStorage.setItem('mooderia_user', JSON.stringify(currentUser));
      setAllUsers(prev => {
        const updated = [...prev];
        const idx = updated.findIndex(u => u.username === currentUser.username);
        if (idx > -1) {
          updated[idx] = { ...updated[idx], ...currentUser };
        } else {
          updated.push(currentUser);
        }
        return updated;
      });
    }
  }, [currentUser, isLoaded]);

  useEffect(() => {
    if (!isLoaded) return;
    localStorage.setItem('mooderia_all_users', JSON.stringify(allUsers));
    localStorage.setItem('mooderia_posts', JSON.stringify(allPosts));
    localStorage.setItem('mooderia_messages', JSON.stringify(allMessages));
    localStorage.setItem('mooderia_groups', JSON.stringify(allGroups));
    localStorage.setItem('mooderia_notifications', JSON.stringify(notifications));
    localStorage.setItem('mooderia_theme', isDarkMode ? 'dark' : 'light');
  }, [allUsers, allPosts, allMessages, allGroups, notifications, isDarkMode, isLoaded]);

  const handleFollow = (targetUsername: string) => {
    if (!currentUser || currentUser.username === targetUsername) return;
    const isFollowing = currentUser.following.includes(targetUsername);

    setAllUsers(prev => prev.map(u => {
      if (u.username === currentUser.username) {
        const nextFollowing = isFollowing 
          ? u.following.filter(f => f !== targetUsername)
          : [...u.following, targetUsername];
        return { ...u, following: nextFollowing };
      }
      if (u.username === targetUsername) {
        const nextFollowers = isFollowing
          ? (u.followers || []).filter(f => f !== currentUser.username)
          : [...(u.followers || []), currentUser.username];
        return { ...u, followers: nextFollowers };
      }
      return u;
    }));

    const nextFollowing = isFollowing 
      ? currentUser.following.filter(f => f !== targetUsername)
      : [...currentUser.following, targetUsername];
    setCurrentUser({ ...currentUser, following: nextFollowing });

    if (!isFollowing) addNotification(targetUsername, 'follow', '');
  };

  const handleBlock = (targetUsername: string) => {
    if (!currentUser || currentUser.username === targetUsername) return;
    setAllUsers(prev => prev.map(u => {
      if (u.username === currentUser.username) {
        return { 
          ...u, 
          blockedUsers: [...u.blockedUsers, targetUsername],
          following: u.following.filter(f => f !== targetUsername),
          followers: u.followers.filter(f => f !== targetUsername)
        };
      }
      if (u.username === targetUsername) {
        return {
          ...u,
          following: u.following.filter(f => f !== currentUser.username),
          followers: u.followers.filter(f => f !== currentUser.username)
        };
      }
      return u;
    }));

    setCurrentUser({
      ...currentUser,
      blockedUsers: [...currentUser.blockedUsers, targetUsername],
      following: currentUser.following.filter(f => f !== targetUsername),
      followers: currentUser.followers.filter(f => f !== targetUsername)
    });
  };

  const handleSendMessage = (recipient: string, text: string, options?: any) => {
    if (!currentUser) return;
    const newMessage: Message = {
      id: Math.random().toString(36).substr(2, 9),
      sender: currentUser.username,
      recipient,
      text,
      timestamp: Date.now(),
      read: false,
      isGroup: options?.isGroup || false,
      isSystem: options?.isSystem || false,
      groupName: options?.groupName,
      replyToId: options?.replyToId,
      replyToText: options?.replyToText,
      replyToSender: options?.replyToSender
    };
    setAllMessages(prev => [...prev, newMessage]);
  };

  const handleGroupUpdate = (group: Group) => {
    setAllGroups(prev => prev.map(g => g.id === group.id ? group : g));
  };

  const handleGroupCreate = (group: Group) => {
    setAllGroups(prev => [...prev, group]);
  };

  const handleMessageReaction = (msgId: string, emoji: string) => {
    if (!currentUser) return;
    setAllMessages(prev => prev.map(m => {
      if (m.id === msgId) {
        const reactions = [...(m.reactions || [])];
        const reactionIdx = reactions.findIndex(r => r.emoji === emoji);

        if (reactionIdx > -1) {
          const reaction = reactions[reactionIdx];
          const userIdx = reaction.users.indexOf(currentUser.username);

          if (userIdx > -1) {
            const newUsers = reaction.users.filter(u => u !== currentUser.username);
            if (newUsers.length === 0) {
              reactions.splice(reactionIdx, 1);
            } else {
              reactions[reactionIdx] = { ...reaction, users: newUsers };
            }
          } else {
            reactions[reactionIdx] = { ...reaction, users: [...reaction.users, currentUser.username] };
          }
        } else {
          reactions.push({ emoji, users: [currentUser.username] });
        }
        return { ...m, reactions };
      }
      return m;
    }));
  };

  const onLogin = (user: User) => {
    const migrated = migrateUserData(user);
    setCurrentUser(migrated);
    setViewingUsername(migrated.username);
  };

  const handleLogout = () => {
    setCurrentUser(null);
    localStorage.removeItem('mooderia_user');
    setActiveSection('Home');
  };

  const handleHeart = (postId: string) => {
    if (!currentUser) return;
    setAllPosts(prev => prev.map(p => {
      if (p.id === postId) {
        const isLiked = p.likes.includes(currentUser.username);
        const nextLikes = isLiked 
          ? p.likes.filter(u => u !== currentUser.username)
          : [...p.likes, currentUser.username];
        if (!isLiked) addNotification(p.author, 'heart', p.content.substring(0, 20), p.id);
        return { ...p, likes: nextLikes };
      }
      return p;
    }));
  };

  const handleDeletePost = (postId: string) => setAllPosts(prev => prev.filter(p => p.id !== postId));

  const handleEditPost = (postId: string, newContent: string) => setAllPosts(prev => prev.map(p => p.id === postId ? { ...p, content: newContent } : p));

  const handleCommentInteraction = (postId: string, commentId: string, action: 'heart' | 'reply', replyText?: string) => {
    if (!currentUser) return;
    setAllPosts(prev => prev.map(p => {
      if (p.id === postId) {
        const updateComments = (comments: Comment[]): Comment[] => {
          return comments.map(c => {
            if (c.id === commentId) {
              if (action === 'heart') return { ...c, hearts: c.hearts + 1 };
              if (action === 'reply' && replyText) {
                const newReply: Comment = {
                  id: Math.random().toString(36).substr(2, 9),
                  author: currentUser.username,
                  text: replyText,
                  hearts: 0,
                  timestamp: Date.now(),
                  replies: []
                };
                return { ...c, replies: [...c.replies, newReply] };
              }
            } else if (c.replies.length > 0) {
              return { ...c, replies: updateComments(c.replies) };
            }
            return c;
          });
        };
        return { ...p, comments: updateComments(p.comments) };
      }
      return p;
    }));
  };

  const handleRepost = (post: Post) => {
    if (!currentUser) return;
    const newPost: Post = {
      id: Math.random().toString(36).substr(2, 9),
      author: currentUser.username,
      content: post.content,
      likes: [],
      comments: [],
      timestamp: Date.now(),
      isRepost: true,
      originalAuthor: post.author,
      visibility: 'global'
    };
    setAllPosts(prev => [newPost, ...prev]);
    addNotification(post.author, 'repost', post.content.substring(0, 20), post.id);
  };

  const updatePetStats = (hunger: number, thirst: number, rest: number, coins: number, exp: number = 0, sleepUntil: number | null = null, newEmoji?: string, markChosen?: boolean, newName?: string, gameCooldownId?: string) => {
    if (!currentUser) return;
    setCurrentUser(prev => {
      if (!prev) return null;
      let nextLevel = prev.petLevel;
      let nextExp = prev.petExp + exp;
      while (nextExp >= getExpNeeded(nextLevel)) {
        nextExp -= getExpNeeded(nextLevel);
        nextLevel++;
      }
      return {
        ...prev,
        petHunger: Math.min(100, Math.max(0, prev.petHunger + hunger)),
        petThirst: Math.min(100, Math.max(0, prev.petThirst + thirst)),
        petRest: Math.min(100, Math.max(0, prev.petRest + rest)),
        moodCoins: Math.max(0, prev.moodCoins + coins),
        petExp: nextExp,
        petLevel: nextLevel,
        petSleepUntil: sleepUntil !== null ? sleepUntil : prev.petSleepUntil,
        petEmoji: newEmoji || prev.petEmoji,
        petHasBeenChosen: markChosen !== undefined ? markChosen : prev.petHasBeenChosen,
        petName: newName || prev.petName,
        gameCooldowns: gameCooldownId ? { ...prev.gameCooldowns, [gameCooldownId]: Date.now() + 300000 } : prev.gameCooldowns,
        petLastUpdate: Date.now()
      };
    });
  };

  const handleViolation = (reason: string) => {
    if (!currentUser) return;
    const newWarnings = (currentUser.warnings || 0) + 1;
    const isBanned = newWarnings >= 3;
    setCurrentUser({ ...currentUser, warnings: newWarnings, isBanned });
    setActiveWarning({ count: newWarnings, reason });
    addNotification(currentUser.username, 'warning', reason);
  };

  if (isAppStarting) return <LoadingScreen />;
  if (!currentUser) return <AuthScreen onLogin={onLogin} />;

  if (currentUser.isBanned) {
    return (
      <div className="fixed inset-0 z-[1000] bg-black text-white flex flex-col items-center justify-center p-8 text-center overflow-hidden">
        <Gavel size={120} className="text-red-600 mb-8" />
        <h1 className="text-6xl md:text-8xl font-black italic uppercase tracking-tighter mb-4 text-red-600">EXILED</h1>
        <button onClick={handleLogout} className="flex items-center gap-3 bg-white text-black px-12 py-5 rounded-2xl font-black uppercase text-xl transition-all shadow-2xl z-[1001]"><LogOut size={24} /> Leave Metropolis</button>
      </div>
    );
  }

  const isFixedSection = activeSection === 'CityHall' || activeSection === 'Mood';

  return (
    <div style={{'--theme-color': currentUser.profileColor || '#e21b3c'} as React.CSSProperties} className={`h-screen max-h-screen overflow-hidden flex flex-col md:flex-row ${isDarkMode ? 'bg-[#0f0f0f] text-white' : 'bg-[#f7f8fa] text-slate-900'} transition-colors duration-300`}>
      <style>{`
        :root { --theme-color: ${currentUser.profileColor || '#e21b3c'}; }
        .kahoot-shadow { box-shadow: 0 4px 0 0 rgba(0,0,0,0.2); }
        .kahoot-button-custom { background-color: var(--theme-color); border-bottom: 6px solid rgba(0,0,0,0.3); }
        .text-custom { color: var(--theme-color); }
        .bg-custom { background-color: var(--theme-color); }
        .border-custom { border-color: var(--theme-color); }
      `}</style>

      <AnimatePresence>
        {activeWarning && (
          <div className="fixed inset-0 z-[1000] flex items-center justify-center p-6 bg-black/80 backdrop-blur-md">
             <motion.div initial={{ scale: 0.8, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} className="w-full max-w-md bg-slate-900 text-white rounded-[3rem] p-10 text-center border-8 border-red-600 shadow-2xl">
                <ShieldAlert size={80} className="mx-auto text-red-600 mb-6" />
                <h2 className="text-3xl font-black italic uppercase tracking-tighter mb-4">CITIZEN WARNING</h2>
                <div className="bg-red-600 text-white inline-block px-8 py-2 rounded-full font-black text-xl mb-6 shadow-xl">VIOLATION {activeWarning.count} / 3</div>
                <button onClick={() => setActiveWarning(null)} className="w-full py-5 bg-white text-black rounded-2xl font-black uppercase text-base shadow-xl">I ACKNOWLEDGE THE ACCORDS</button>
             </motion.div>
          </div>
        )}
      </AnimatePresence>

      <Sidebar 
        activeSection={activeSection} 
        onNavigate={(s) => { setActiveSection(s); if(s === 'Profile') setViewingUsername(currentUser!.username); }} 
        isDarkMode={isDarkMode} 
        user={currentUser!} 
        unreadMessages={allMessages.filter(m => m.recipient === currentUser!.username && !m.read).length} 
        unreadNotifications={notifications.filter(n => n.recipient === currentUser!.username && !n.read).length} 
      />
      <main className="flex-1 flex flex-col min-h-0 relative pt-14 pb-16 md:pt-0 md:pb-0 h-full overflow-hidden">
        <div className={`flex-1 flex flex-col min-h-0 ${isFixedSection ? 'overflow-hidden' : 'overflow-y-auto fading-scrollbar'} p-4 md:p-8`}>
          <motion.div 
            key={activeSection + (activeSection === 'Profile' ? viewingUsername : '')} 
            initial={{ opacity: 0, y: 10 }} 
            animate={{ opacity: 1, y: 0 }} 
            className={`max-w-6xl mx-auto w-full flex-1 flex flex-col min-h-0 h-full`}
          >
            {activeSection === 'Home' && <HomeSection user={currentUser!} posts={allPosts} isDarkMode={isDarkMode} />}
            {activeSection === 'Mood' && (
              <MoodSection 
                user={currentUser!} 
                posts={allPosts} 
                onPost={(c, v) => setAllPosts(prev => [{id: Math.random().toString(36).substr(2, 9), author: currentUser!.username, content: c, likes: [], comments: [], timestamp: Date.now(), visibility: v}, ...prev])} 
                onHeart={handleHeart} 
                onDeletePost={handleDeletePost}
                onEditPost={handleEditPost}
                onComment={(pid, t) => setAllPosts(prev => prev.map(p => p.id === pid ? { ...p, comments: [...p.comments, { id: Math.random().toString(36).substr(2, 9), author: currentUser!.username, text: t, hearts: 0, timestamp: Date.now(), replies: [] }] } : p))} 
                onCommentInteraction={handleCommentInteraction} 
                onRepost={handleRepost} 
                onFollow={handleFollow} 
                onBlock={handleBlock} 
                isDarkMode={isDarkMode} 
                onNavigateToProfile={(u) => {setViewingUsername(u); setActiveSection('Profile');}} 
                onUpdatePet={updatePetStats} 
                onViolation={handleViolation}
              />
            )}
            {activeSection === 'Zodiac' && <ZodiacSection isDarkMode={isDarkMode} />}
            {activeSection === 'CityHall' && (
              <CityHallSection 
                isDarkMode={isDarkMode} 
                currentUser={currentUser!} 
                allUsers={allUsers}
                messages={allMessages} 
                groups={allGroups}
                onSendMessage={handleSendMessage} 
                onGroupUpdate={handleGroupUpdate}
                onGroupCreate={handleGroupCreate}
                onReadMessages={(u) => setAllMessages(prev => prev.map(m => (m.recipient === currentUser!.username && m.sender === u) ? {...m, read: true} : m))} 
                onNavigateToProfile={(u) => {setViewingUsername(u); setActiveSection('Profile');}} 
                onReactToMessage={handleMessageReaction} 
                onViolation={handleViolation}
              />
            )}
            {activeSection === 'Notifications' && <NotificationsSection notifications={notifications.filter(n => n.recipient === currentUser!.username)} isDarkMode={isDarkMode} onMarkRead={() => setNotifications(notifications.map(n => n.recipient === currentUser!.username ? {...n, read: true} : n))} />}
            {activeSection === 'Profile' && profileToView && <ProfileSection user={profileToView} allPosts={allPosts} isDarkMode={isDarkMode} currentUser={currentUser!} onEditProfile={(dn, un, pp, ti, bp, pc, bi) => { setCurrentUser({...currentUser!, displayName: dn, username: un, profilePic: pp, title: ti, profileColor: pc, bio: bi}); setViewingUsername(un); }} onBlock={handleBlock} onFollow={handleFollow} />}
            {activeSection === 'Settings' && (
              <SettingsSection 
                isDarkMode={isDarkMode} 
                onToggleDarkMode={() => setIsDarkMode(!isDarkMode)} 
                onLogout={handleLogout} 
                user={currentUser!} 
                onUnblock={(u) => { 
                  const newBlocked = currentUser!.blockedUsers.filter(b => b !== u); 
                  setCurrentUser({...currentUser!, blockedUsers: newBlocked}); 
                }} 
              />
            )}
          </motion.div>
        </div>
      </main>
    </div>
  );
};

export default App;

export type Mood = 'Wonderful' | 'Excited' | 'Happy' | 'Normal' | 'Tired' | 'Angry' | 'Flaming' | null;

export interface Badge {
  id: string;
  name: string;
  icon: string;
  description: string;
  threshold: number;
}

export interface User {
  displayName: string;
  username: string;
  email: string;
  password?: string;
  bio?: string;
  followers: string[];
  following: string[];
  friends: string[];
  blockedUsers: string[];
  posts: Post[];
  reposts: Post[];
  moodHistory: { date: string, mood: Mood, score: number }[];
  moodStreak: number;
  lastMoodDate?: string;
  profilePic?: string;
  bannerPic?: string;
  profileColor?: string;
  title?: string;
  likesReceived: number;
  // Mood Pet Stats
  petName: string;
  moodCoins: number;
  petEmoji: string;
  petHunger: number; // 0-100
  petThirst: number; // 0-100
  petRest: number;   // 0-100
  petLevel: number;
  petExp: number;
  petHasBeenChosen: boolean;
  petLastUpdate: number; // timestamp
  petSleepUntil: number | null; // timestamp
  gameCooldowns: Record<string, number>; // gameId -> timestamp of when it can be played again
  // Security / Moderation
  warnings: number;
  isBanned: boolean;
}

export interface MessageReaction {
  emoji: string;
  users: string[]; 
}

export interface Group {
  id: string;
  name: string;
  photo?: string; 
  members: string[]; 
  nicknames: Record<string, string>; 
  owner: string;
  createdAt: number;
}

export interface Message {
  id: string;
  sender: string;
  recipient: string; 
  text: string;
  timestamp: number;
  read: boolean;
  reactions?: MessageReaction[];
  isGroup?: boolean;
  isSystem?: boolean; 
  groupName?: string;
  replyToId?: string;
  replyToText?: string;
  replyToSender?: string;
}

export interface Notification {
  id: string;
  type: 'heart' | 'comment' | 'repost' | 'tier' | 'achievement' | 'follow' | 'comment_heart' | 'reply' | 'reaction' | 'warning';
  fromUser: string;
  recipient: string; 
  postId?: string;
  timestamp: number;
  read: boolean;
  postContentSnippet: string;
}

export interface Post {
  id: string;
  author: string;
  content: string;
  likes: string[]; 
  comments: Comment[];
  timestamp: number;
  isRepost?: boolean;
  originalAuthor?: string;
  visibility: 'global' | 'circle';
}

export interface Comment {
  id: string;
  author: string;
  text: string;
  hearts: number;
  timestamp: number;
  replies: Comment[];
}

export type Section = 'Home' | 'Mood' | 'Zodiac' | 'CityHall' | 'Profile' | 'Settings' | 'Notifications' | 'Psychiatrist';

export interface ZodiacInfo {
  name: string;
  dates: string;
  description: string;
  history: string;
  symbol: string;
}

import React, { useState, useEffect, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Send, Stethoscope, Sparkles, Brain, Clock, ShieldCheck, Info } from 'lucide-react';
import { User, Message } from '../types';
import { getPsychiatristResponse } from '../services/geminiService';

interface PsychiatristSectionProps {
  currentUser: User;
  isDarkMode: boolean;
  messages: Message[];
  onSendMessage: (text: string) => void;
}

const PsychiatristSection: React.FC<PsychiatristSectionProps> = ({ currentUser, isDarkMode, messages, onSendMessage }) => {
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  const sessionMessages = messages.filter(m => 
    (m.sender === currentUser.username && m.recipient === 'DrPinel') ||
    (m.sender === 'DrPinel' && m.recipient === currentUser.username)
  ).sort((a, b) => a.timestamp - b.timestamp);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [sessionMessages, isTyping]);

  const handleSend = async () => {
    if (!input.trim() || isTyping) return;
    const text = input.trim();
    setInput('');
    onSendMessage(text);
    setIsTyping(true);

    // Simulate thinking delay then call API
    const response = await getPsychiatristResponse(text);

    // Send back to the main App state
    const aiMessage: Message = {
      id: Math.random().toString(36).substr(2, 9),
      sender: 'DrPinel',
      recipient: currentUser.username,
      text: response.text,
      timestamp: Date.now(),
      read: false
    };

    // We dispatch this via a custom event or let the App handle it. 
    // In this simplified model, we'll manually trigger it in the parent.
    window.dispatchEvent(new CustomEvent('ai-response', { detail: aiMessage }));
    setIsTyping(false);
  };

  const formatTime = (ts: number) => new Date(ts).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });

  return (
    <div className="flex flex-col h-full min-h-0 w-full">
      <div className="flex items-center justify-between mb-6 px-2 shrink-0">
        <div className="flex flex-col">
          <h2 className={`text-3xl md:text-4xl font-black italic uppercase tracking-tighter ${isDarkMode ? 'text-white' : 'text-slate-900'}`}>Neural Therapy</h2>
          <p className="text-[10px] font-black uppercase tracking-widest opacity-40">Session with Dr. Philippe Pinel</p>
        </div>
        <div className="bg-blue-500/10 text-blue-500 px-4 py-2 rounded-2xl border-2 border-blue-500/20 flex items-center gap-2">
          <ShieldCheck size={18} />
          <span className="text-[10px] font-black uppercase">Secure Link</span>
        </div>
      </div>

      <div className={`flex-1 flex flex-col rounded-[3rem] ${isDarkMode ? 'bg-slate-900' : 'bg-white'} border-4 border-black/5 shadow-2xl overflow-hidden min-h-0 h-full`}>
        {/* Header Information */}
        <div className="p-6 border-b border-black/5 flex items-center gap-4 shrink-0 bg-blue-50/50 dark:bg-slate-800/50">
          <div className="w-12 h-12 rounded-2xl bg-blue-600 text-white flex items-center justify-center shadow-lg border-2 border-white/20">
            <Stethoscope size={24} />
          </div>
          <div className="flex-1">
            <p className="font-black text-sm uppercase italic">Chief Medical District</p>
            <div className="flex items-center gap-2">
              <div className="w-2 h-2 bg-green-500 rounded-full animate-pulse" />
              <p className="text-[10px] font-black opacity-40 uppercase tracking-widest">Always Online • Neural Synchrony Active</p>
            </div>
          </div>
        </div>

        {/* Scrollable Conversation */}
        <div ref={scrollRef} className="flex-1 overflow-y-auto p-6 space-y-6 fading-scrollbar bg-slate-50/20 dark:bg-slate-900/10">
          {sessionMessages.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center text-center opacity-20 p-10">
              <Brain size={80} className="mb-4" />
              <h3 className="text-xl font-black uppercase italic">Neural Bridge Ready</h3>
              <p className="text-xs font-bold mt-2">"Welcome to the Medical District. How are your frequencies today?"</p>
            </div>
          ) : (
            sessionMessages.map(m => {
              const isMe = m.sender === currentUser.username;
              return (
                <div key={m.id} className={`flex ${isMe ? 'flex-row-reverse' : 'flex-row'} items-end gap-3`}>
                  <div className={`max-w-[85%] flex flex-col ${isMe ? 'items-end' : 'items-start'} gap-1`}>
                    <div className={`px-5 py-3 rounded-[1.5rem] font-bold text-sm border-b-4 ${isMe ? 'bg-blue-600 border-blue-800 text-white rounded-tr-none' : isDarkMode ? 'bg-slate-800 border-slate-900 text-white rounded-tl-none' : 'bg-white border-gray-200 text-slate-800 rounded-tl-none shadow-sm'}`}>
                      <p className="whitespace-pre-wrap leading-relaxed">{m.text}</p>
                    </div>
                    <p className="text-[9px] font-black uppercase opacity-20 tracking-tighter px-1">{formatTime(m.timestamp)}</p>
                  </div>
                </div>
              );
            })
          )}
          {isTyping && (
            <div className="flex items-center gap-2 opacity-40 px-2">
              <Sparkles size={16} className="animate-spin" />
              <p className="text-[10px] font-black uppercase tracking-widest animate-pulse">Analyzing Frequencies...</p>
            </div>
          )}
        </div>

        {/* Input Footer */}
        <div className="p-4 md:p-6 border-t border-black/5 bg-white/50 dark:bg-slate-900/50 backdrop-blur-md shrink-0">
          <div className={`flex items-center gap-3 p-2 rounded-[2rem] border-4 transition-all ${isDarkMode ? 'bg-slate-800 border-slate-700' : 'bg-gray-50 border-gray-200'} focus-within:border-blue-500 shadow-inner`}>
            <input 
              type="text" 
              value={input} 
              onChange={e => setInput(e.target.value)} 
              onKeyPress={e => e.key === 'Enter' && handleSend()}
              placeholder="Express your neural state..." 
              className="flex-1 bg-transparent px-5 py-3 font-black text-sm outline-none" 
            />
            <button 
              onClick={handleSend}
              disabled={!input.trim() || isTyping}
              className="kahoot-button-blue p-4 rounded-2xl text-white shadow-xl active:scale-95 transition-all disabled:opacity-50"
            >
              <Send size={20} />
            </button>
          </div>
        </div>
      </div>

      <div className="mt-4 flex items-center justify-center gap-2 opacity-30 text-center">
        <Info size={12} />
        <p className="text-[8px] font-black uppercase tracking-[0.2em]">Neural AI Psychiatrist is for supportive guidance, not emergency medical care.</p>
      </div>
    </div>
  );
};

