    followers: [], following: [], friends: [], blockedUsers: [], posts: [], reposts: [], moodHistory: [],
    moodStreak: 100, title: 'Grand Astronomer', likesReceived: 25000, petName: 'Nova', moodCoins: 5000,
    petEmoji: '✨', petHunger: 100, petThirst: 100, petRest: 100, petLevel: 50, petExp: 0,
