import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { User } from '../types';
import LoadingScreen from '../components/LoadingScreen';
import { Cloud, Key, UserPlus, LogIn, ShieldCheck } from 'lucide-react';

interface AuthScreenProps {
  onLogin: (user: User) => void;
}

const AuthScreen: React.FC<AuthScreenProps> = ({ onLogin }) => {
  const [authMode, setAuthMode] = useState<'login' | 'signup' | 'sync'>('login');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [displayName, setDisplayName] = useState('');
  const [username, setUsername] = useState('');
  const [syncKey, setSyncKey] = useState('');
  const [error, setError] = useState('');
  const [isAuthenticating, setIsAuthenticating] = useState(false);

  const handleSyncIdentity = () => {
    try {
      const decoded = JSON.parse(atob(syncKey));
      if (decoded.allUsers && decoded.currentUser) {
        setIsAuthenticating(true);
        localStorage.setItem('mooderia_all_users', JSON.stringify(decoded.allUsers));
        localStorage.setItem('mooderia_posts', JSON.stringify(decoded.allPosts || []));
        localStorage.setItem('mooderia_messages', JSON.stringify(decoded.allMessages || []));
        localStorage.setItem('mooderia_groups', JSON.stringify(decoded.allGroups || []));
        localStorage.setItem('mooderia_notifications', JSON.stringify(decoded.notifications || []));

        setTimeout(() => {
          localStorage.setItem('mooderia_user', JSON.stringify(decoded.currentUser));
          onLogin(decoded.currentUser);
        }, 1500);
      } else {
        setError('METROPOLIS ERROR: Passkey corrupted or invalid.');
      }
    } catch (e) {
      setError('METROPOLIS ERROR: Invalid Passkey format.');
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    if (authMode === 'sync') {
      handleSyncIdentity();
      return;
    }

    const allUsersStr = localStorage.getItem('mooderia_all_users') || '[]';
    const allUsers: User[] = JSON.parse(allUsersStr);

    if (authMode === 'signup') {
      const userExists = allUsers.some(u => u.email.toLowerCase() === email.toLowerCase() || u.username.toLowerCase() === username.toLowerCase());
      if (userExists) {
        setError('This identity already exists in the metropolis.');
        return;
      }

      const newUser: User = {
        displayName: displayName,
        username: username,
        email: email,
        password: password,
        followers: [],
        following: [],
        friends: [],
        blockedUsers: [],
        posts: [],
        reposts: [],
        moodHistory: [],
        moodStreak: 0,
        title: email.toLowerCase() === 'travismiguel014@gmail.com' ? 'Creator' : 'Citizen',
        likesReceived: 0,
        petName: 'Guardian',
        moodCoins: 100,
        petEmoji: '🐱',
        petHunger: 100,
        petThirst: 100,
        petRest: 100,
        petLevel: 1,
        petExp: 0,
        petHasBeenChosen: false,
        petLastUpdate: Date.now(),
        petSleepUntil: null,
        gameCooldowns: {},
        warnings: 0,
        isBanned: false
      };

      allUsers.push(newUser);
      localStorage.setItem('mooderia_all_users', JSON.stringify(allUsers));

      setIsAuthenticating(true);
      setTimeout(() => {
        localStorage.setItem('mooderia_user', JSON.stringify(newUser));
        onLogin(newUser);
      }, 1500);
    } else {
      const existingUser = allUsers.find(u => u.email.toLowerCase() === email.toLowerCase() && u.password === password);

      if (existingUser) {
        setIsAuthenticating(true);
        setTimeout(() => {
          localStorage.setItem('mooderia_user', JSON.stringify(existingUser));
          onLogin(existingUser);
        }, 1200);
      } else {
        setError('Credentials invalid. Access denied.');
      }
    }
  };

  if (isAuthenticating) return <LoadingScreen />;

  return (
    <div className="min-h-screen flex items-center justify-center bg-[#46178f] p-4 relative overflow-hidden">
      <div className="absolute inset-0 opacity-10 pointer-events-none overflow-hidden">
        {Array.from({ length: 15 }).map((_, i) => (
          <div key={i} className="absolute text-white font-black opacity-20 rotate-12 text-6xl" style={{ top: `${Math.random() * 100}%`, left: `${Math.random() * 100}%` }}>MOODERIA</div>
        ))}
      </div>

      <motion.div initial={{ y: 50, opacity: 0 }} animate={{ y: 0, opacity: 1 }} className="w-full max-w-md bg-slate-900 border-4 border-white/10 rounded-[2.5rem] shadow-2xl p-8 z-10 text-white">
        <div className="text-center mb-8">
          <h1 className="text-4xl md:text-5xl font-black italic text-white tracking-tighter mb-2 uppercase">Mooderia</h1>
          <div className="flex items-center justify-center gap-2">
            <ShieldCheck size={14} className="text-blue-400" />
            <p className="text-blue-400 font-bold uppercase tracking-widest text-[10px]">Neural Access Terminal</p>
          </div>
        </div>

        <form onSubmit={handleSubmit} className="space-y-4">
          <AnimatePresence mode="wait">
            {authMode === 'signup' && (
              <motion.div key="signup" initial={{ height: 0, opacity: 0 }} animate={{ height: 'auto', opacity: 1 }} exit={{ height: 0, opacity: 0 }} className="space-y-4 overflow-hidden">
                <input type="text" placeholder="Identity Name" required value={displayName} onChange={(e) => setDisplayName(e.target.value)} className="w-full p-4 rounded-xl bg-slate-800 text-white border-2 border-slate-700 focus:border-blue-500 outline-none font-bold text-sm" />
                <input type="text" placeholder="ID Handle (Username)" required value={username} onChange={(e) => setUsername(e.target.value)} className="w-full p-4 rounded-xl bg-slate-800 text-white border-2 border-slate-700 focus:border-blue-500 outline-none font-bold text-sm" />
              </motion.div>
            )}
            {authMode === 'sync' && (
              <motion.div key="sync" initial={{ height: 0, opacity: 0 }} animate={{ height: 'auto', opacity: 1 }} exit={{ height: 0, opacity: 0 }} className="space-y-4 overflow-hidden">
                <div className="p-4 bg-blue-500/10 rounded-2xl border-2 border-blue-500/20 mb-2">
                  <p className="text-[10px] font-black uppercase text-blue-400 mb-2">Neural Bridge Link</p>
                  <p className="text-[9px] font-bold opacity-60 uppercase leading-tight">Paste your Metropolis Passkey from another device to sync your entire worldwide identity.</p>
                </div>
                <textarea 
                  placeholder="Paste Neural Passkey..." 
                  required 
                  value={syncKey} 
                  onChange={(e) => setSyncKey(e.target.value)} 
                  className="w-full p-4 rounded-xl bg-slate-800 text-white border-2 border-slate-700 focus:border-blue-500 outline-none font-bold text-[10px] min-h-[100px]" 
                />
              </motion.div>
            )}
          </AnimatePresence>

          {authMode !== 'sync' && (
            <>
              <input type="email" placeholder="Neural Link (Email)" required value={email} onChange={(e) => setEmail(e.target.value)} className="w-full p-4 rounded-xl bg-slate-800 text-white border-2 border-slate-700 focus:border-blue-500 outline-none font-bold text-sm" />
              <input type="password" placeholder="Access Phrase (Password)" required value={password} onChange={(e) => setPassword(e.target.value)} className="w-full p-4 rounded-xl bg-slate-800 text-white border-2 border-slate-700 focus:border-blue-500 outline-none font-bold text-sm" />
            </>
          )}

          {error && <p className="text-[#e21b3c] text-xs font-black text-center bg-red-500/10 p-3 rounded-xl border border-red-500/20">{error}</p>}

          <button type="submit" className="kahoot-button-blue w-full p-5 rounded-2xl text-white font-black text-lg mt-4 shadow-lg active:scale-95 uppercase flex items-center justify-center gap-3">
            {authMode === 'signup' ? <UserPlus size={20}/> : authMode === 'sync' ? <Cloud size={20}/> : <LogIn size={20}/>}
            {authMode === 'signup' ? 'Authorize ID' : authMode === 'sync' ? 'Sync Identity' : 'Synchronize'}
          </button>
        </form>

        <div className="mt-8 flex flex-col gap-3">
          <button onClick={() => { setAuthMode(authMode === 'login' ? 'signup' : 'login'); setError(''); }} className="text-xs font-bold text-blue-400 hover:text-white transition-colors hover:underline text-center uppercase tracking-widest">
            {authMode === 'signup' ? 'Back to Neural Login' : authMode === 'sync' ? 'Back to Neural Login' : "New entity? Apply for Citizenship"}
          </button>

          <button onClick={() => { setAuthMode(authMode === 'sync' ? 'login' : 'sync'); setError(''); }} className="flex items-center justify-center gap-2 text-[10px] font-black text-yellow-500 hover:text-white transition-colors uppercase tracking-[0.2em] bg-yellow-500/5 py-2 rounded-xl border border-yellow-500/10">
            <Key size={14} /> {authMode === 'sync' ? 'Login with Credentials' : 'Sync from another device'}
          </button>
        </div>
      </motion.div>
    </div>
  );
};

export default AuthScreen;

