import { createClient } from '@supabase/supabase-js';

// Credentials should be provided in the environment. 
// Replace these strings if you are not using an automated environment injector.
const supabaseUrl = process.env.SUPABASE_URL || '';
const supabaseAnonKey = process.env.SUPABASE_ANON_KEY || '';

export const supabase = (supabaseUrl && supabaseAnonKey) 
  ? createClient(supabaseUrl, supabaseAnonKey) 
  : null;

export const isCloudEnabled = !!supabase;

/**
 * Synchronizes the user's profile and entire local metadata (pet, history, etc) to Supabase.
 */
export const syncProfile = async (user: any) => {
  if (!supabase) return;

  const { data: { session } } = await supabase.auth.getSession();
  const id = session?.user?.id || user.id;

  if (!id) return;

  const { error } = await supabase
    .from('profiles')
    .upsert({
      id: id,
      username: user.username,
      display_name: user.displayName,
      email: user.email,
      metadata: user,
      updated_at: new Date().toISOString()
    }, { onConflict: 'id' });

  if (error) console.error("METROPOLIS SYNC ERROR:", error.message);
};

/**
 * Fetches all real citizen profiles registered in the metropolis.
 */
export const fetchProfiles = async () => {
  if (!supabase) return [];
  const { data, error } = await supabase
    .from('profiles')
    .select('*');

  if (error) {
    console.error("METROPOLIS DIRECTORY ERROR:", error.message);
    return [];
  }

  return data?.map(p => ({ 
    ...p.metadata, 
    id: p.id, 
    username: p.username, 
    displayName: p.display_name 
  })) || [];
};

/**
 * Fetches the most recent global transmissions.
 */
export const fetchGlobalFeed = async () => {
  if (!supabase) return [];
  const { data, error } = await supabase
    .from('posts')
    .select('*')
    .order('created_at', { ascending: false })
    .limit(50);

  if (error) return [];

  return data?.map(p => ({
    id: p.id,
    author: p.author_username,
    content: p.content,
    likes: p.likes || [],
    comments: [], // Comments are local/mocked in this version
    timestamp: new Date(p.created_at).getTime(),
    visibility: p.visibility
  })) || [];
};

export const publishPost = async (post: any) => {
  if (!supabase) return;
  return await supabase.from('posts').insert(post);
};

export const sendMessageCloud = async (message: any) => {
  if (!supabase) return;
  return await supabase.from('messages').insert(message);
}

