/**
 * Fetches all real citizen profiles registered in the metropolis.
 */
export const fetchProfiles = async () => {
  if (!supabase) return [];
  try {
    const { data, error } = await supabase
      .from('profiles')
      .select('*');

    if (error) {
      // Code 42P01 is "undefined_table" in Postgres
      if (error.code === '42P01') {
        console.info("METROPOLIS INFO: Profiles table is not yet initialized in the cloud. Using local state.");
      } else {
        console.error("METROPOLIS DIRECTORY ERROR:", error.message);
      }
      return [];
    }

    return data?.map(p => ({ 
      ...p.metadata, 
      id: p.id, 
      username: p.username, 
      displayName: p.display_name 
    })) || [];
  } catch (e) {
    return [];
  }
};

/**
 * Fetches the most recent global transmissions.
 */
export const fetchGlobalFeed = async () => {
  if (!supabase) return [];
  try {
    const { data, error } = await supabase
      .from('posts')
      .select('*')
      .order('created_at', { ascending: false })
      .limit(50);

    if (error) {
      if (error.code === '42P01') {
        console.info("METROPOLIS INFO: Posts table not found. Using local feed.");
      }
      return [];
    }

    return data?.map(p => ({
      id: p.id,
      author: p.author_username,
      content: p.content,
      likes: p.likes || [],
      comments: [], 
      timestamp: new Date(p.created_at).getTime(),
      visibility: p.visibility
    })) || [];
  } catch (e) {
    return [];
  }
};

