      .upsert({
        id: id,
        username: user.username,
        display_name: user.displayName,
        email: user.email,
        metadata: user,
        updated_at: new Date().toISOString()
      }, { onConflict: 'id' });

    if (error) handleTableError(error, 'SYNC');
  } catch (e) {
    // Silent catch
  }
};

/**
 * Fetches all real citizen profiles registered in the metropolis.
 */
export const fetchProfiles = async () => {
  if (!supabase) return [];
  try {
    const { data, error } = await supabase
      .from('profiles')
      .select('*');

    if (error) {
      handleTableError(error, 'DIRECTORY');
      return [];
    }

    return data?.map(p => ({ 
      ...p.metadata, 
      id: p.id, 
      username: p.username, 
      displayName: p.display_name 
    })) || [];
  } catch (e) {
    return [];
  }
};

/**
 * Fetches the most recent global transmissions.
 */
export const fetchGlobalFeed = async () => {
  if (!supabase) return [];
  try {
    const { data, error } = await supabase
      .from('posts')
      .select('*')
      .order('created_at', { ascending: false })
      .limit(50);

    if (error) {
      handleTableError(error, 'FEED');
      return [];
    }

    return data?.map(p => ({
      id: p.id,
      author: p.author_username,
      content: p.content,
      likes: p.likes || [],
      comments: [], 
      timestamp: new Date(p.created_at).getTime(),
      visibility: p.visibility
    })) || [];
  } catch (e) {
    return [];
  }
};

export const publishPost = async (post: any) => {
  if (!supabase) return;
  try {
    const { data, error } = await supabase.from('posts').insert(post);
    if (error) handleTableError(error, 'PUBLISH');
    return { data, error };
  } catch (e) {
    return { error: e };
  }
};

export const sendMessageCloud = async (message: any) => {
  if (!supabase) return;
  try {
    const { data, error } = await supabase.from('messages').insert(message);
    if (error) handleTableError(error, 'MESSAGE');
    return { data, error };
  } catch (e) {
    return { error: e };
  }
}

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { User, Mood, Section, Post, Comment, Message, Notification, Group } from './types';
import Sidebar from './components/Sidebar';
import HomeSection from './sections/HomeSection';
import MoodSection from './sections/MoodSection';
import ZodiacSection from './sections/ZodiacSection';
import CityHallSection from './sections/CityHallSection';
import PsychiatristSection from './sections/PsychiatristSection';
import ProfileSection from './sections/ProfileSection';
import SettingsSection from './sections/SettingsSection';
import NotificationsSection from './sections/NotificationsSection';
import AuthScreen from './sections/AuthScreen';
import LoadingScreen from './components/LoadingScreen';
import MoodCheckIn from './components/MoodCheckIn';
import { getExpNeeded, MOOD_SCORES } from './constants';
import { LogOut, Gavel, ShieldAlert } from 'lucide-react';
import { getPsychiatristResponse } from './services/geminiService';
import { supabase, isCloudEnabled, fetchGlobalFeed, syncProfile, fetchProfiles } from './services/supabaseService';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [allUsers, setAllUsers] = useState<User[]>([]);
  const [activeSection, setActiveSection] = useState<Section>('Home');
  const [viewingUsername, setViewingUsername] = useState<string | null>(null);
  const [isDarkMode, setIsDarkMode] = useState(false); 
  const [isAppStarting, setIsAppStarting] = useState(true);
  const [showMoodCheckIn, setShowMoodCheckIn] = useState(false);

  const [allPosts, setAllPosts] = useState<Post[]>([]);
  const [allMessages, setAllMessages] = useState<Message[]>([]);
  const [allGroups, setAllGroups] = useState<Group[]>([]);
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);

  const [activeWarning, setActiveWarning] = useState<{ count: number, reason: string } | null>(null);

  const migrateUserData = (user: User): User => {
    return {
      ...user,
      blockedUsers: user.blockedUsers || [],
      moodHistory: user.moodHistory || [],
      following: user.following || [],
      followers: user.followers || [],
      moodStreak: user.moodStreak || 0,
      petLevel: user.petLevel || 1,
      moodCoins: user.moodCoins ?? 100,
      gameCooldowns: user.gameCooldowns || {},
      petHasBeenChosen: !!user.petHasBeenChosen,
      warnings: user.warnings ?? 0,
      isBanned: !!user.isBanned
    };
  };

  useEffect(() => {
    const init = async () => {
      const savedTheme = localStorage.getItem('mooderia_theme');
      if (savedTheme === 'dark') setIsDarkMode(true);

      if (isCloudEnabled && supabase) {
        try {
          const { data: { session } } = await supabase.auth.getSession();

          const channel = supabase.channel('metropolis_grid');
          channel
            .on('postgres_changes', { event: 'INSERT', schema: 'public', table: 'posts' }, payload => {
              const p = payload.new as any;
              const newPost: Post = {
                id: p.id,
                author: p.author_username,
                content: p.content,
                likes: p.likes || [],
                comments: [],
                timestamp: new Date(p.created_at).getTime(),
                visibility: p.visibility
              };
              setAllPosts(prev => {
                if (prev.some(old => old.id === newPost.id)) return prev;
                return [newPost, ...prev];
              });
            })
            .on('postgres_changes', { event: 'INSERT', schema: 'public', table: 'messages' }, payload => {
              const m = payload.new as any;
              const newMessage: Message = {
                ...m,
                timestamp: new Date(m.created_at).getTime(),
                read: false
              };
              setAllMessages(prev => {
                if (prev.some(old => old.id === newMessage.id)) return prev;
                return [...prev, newMessage];
              });
            })
            .on('postgres_changes', { event: '*', schema: 'public', table: 'profiles' }, async () => {
              const users = await fetchProfiles();
              setAllUsers(users);
            })
            .subscribe();

          if (session) {
            const { data: profile } = await supabase.from('profiles').select('*').eq('id', session.user.id).single();
            if (profile) {
              const user = migrateUserData(profile.metadata);
              setCurrentUser(user);
              setViewingUsername(user.username);
              // Trigger mood check-in if not done today
              const todayStr = new Date().toDateString();
              if (user.lastMoodDate !== todayStr) {
                setShowMoodCheckIn(true);
              }
            }
          }

          const [feed, users] = await Promise.all([fetchGlobalFeed(), fetchProfiles()]);
          if (feed.length > 0) setAllPosts(feed as Post[]);
          if (users.length > 0) setAllUsers(users);
        } catch (e) {
          console.info("METROPOLIS INFO: Operating in limited mode.");
        }
      } else {
        const savedUser = localStorage.getItem('mooderia_user');
        if (savedUser) {
          const user = migrateUserData(JSON.parse(savedUser));
          setCurrentUser(user);
          const todayStr = new Date().toDateString();
          if (user.lastMoodDate !== todayStr) {
            setShowMoodCheckIn(true);
          }
        }
      }

      setIsLoaded(true);
      setTimeout(() => setIsAppStarting(false), 2000);
    };

    init();
  }, []);

  useEffect(() => {
    if (!isLoaded || !currentUser) return;
    localStorage.setItem('mooderia_user', JSON.stringify(currentUser));
    if (isCloudEnabled) syncProfile(currentUser);
  }, [currentUser, isLoaded]);

  const handleMoodSubmit = (mood: Mood) => {
    if (!currentUser) return;
    const today = new Date();
    const todayStr = today.toDateString();

    // Calculate Streak
    let newStreak = 1;
    if (currentUser.lastMoodDate) {
      const lastDate = new Date(currentUser.lastMoodDate);
      const diffTime = Math.abs(today.getTime() - lastDate.getTime());
      const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
      if (diffDays === 1) {
        newStreak = (currentUser.moodStreak || 0) + 1;
      } else if (diffDays === 0) {
        newStreak = currentUser.moodStreak || 1;
      }
    }

    const moodScore = mood ? MOOD_SCORES[mood] : 50;
    const newHistory = [...(currentUser.moodHistory || []), { date: todayStr, mood, score: moodScore }];

    // Give some exp and coins for checking in
    const expGain = 20;
    const coinGain = 10;

    setCurrentUser({
      ...currentUser,
      moodHistory: newHistory,
      moodStreak: newStreak,
      lastMoodDate: todayStr,
      moodCoins: (currentUser.moodCoins || 0) + coinGain,
      petExp: (currentUser.petExp || 0) + expGain
    });

    setShowMoodCheckIn(false);
  };

  const handleSendMessage = async (recipient: string, text: string, options?: any) => {
    if (!currentUser) return;
    const newMessageData: any = {
      sender: currentUser.username,
      recipient,
      text,
      is_group: options?.isGroup || false,
    };

    if (isCloudEnabled && supabase) {
      try {
        await supabase.from('messages').insert(newMessageData);
      } catch (e) {}
    } else {
      setAllMessages(prev => [...prev, { ...newMessageData, id: Math.random().toString(), timestamp: Date.now(), read: false }]);
    }
  };

  const handleLogout = async () => {
    if (isCloudEnabled && supabase) await supabase.auth.signOut();
    setCurrentUser(null);
    localStorage.removeItem('mooderia_user');
    setActiveSection('Home');
  };

  const handlePost = async (content: string, visibility: 'global' | 'circle') => {
    if (!currentUser) return;
    const newPostData: any = {
      author_username: currentUser.username,
      content,
      visibility,
      likes: []
    };

    if (isCloudEnabled && supabase) {
      try {
        await supabase.from('posts').insert(newPostData);
      } catch (e) {}
    } else {
      setAllPosts(prev => [{ ...newPostData, id: Math.random().toString(), timestamp: Date.now(), author: currentUser.username, likes: [], comments: [] } as any, ...prev]);
    }
  };

  const handleHeart = async (postId: string) => {
    if (!currentUser) return;
    setAllPosts(prev => prev.map(p => {
      if (p.id === postId) {
        const isLiked = p.likes?.includes(currentUser.username);
        const nextLikes = isLiked ? p.likes.filter(u => u !== currentUser.username) : [...(p.likes || []), currentUser.username];
        return { ...p, likes: nextLikes };
      }
      return p;
    }));
  };

  const handleViolation = (reason: string) => {
    if (!currentUser) return;
    const newWarnings = (currentUser.warnings || 0) + 1;
    const isBanned = newWarnings >= 3;
    setCurrentUser({ ...currentUser, warnings: newWarnings, isBanned });
    setActiveWarning({ count: newWarnings, reason });
  };

  if (isAppStarting) return <LoadingScreen />;
  if (!currentUser) return <AuthScreen onLogin={(u) => { setCurrentUser(u); setViewingUsername(u.username); }} />;

  const isFixedSection = activeSection === 'CityHall' || activeSection === 'Mood' || activeSection === 'Psychiatrist';

  return (
    <div style={{'--theme-color': currentUser.profileColor || '#e21b3c'} as React.CSSProperties} className={`h-screen max-h-screen overflow-hidden flex flex-col md:flex-row ${isDarkMode ? 'bg-[#0f0f0f] text-white' : 'bg-[#f7f8fa] text-slate-900'} transition-colors duration-300`}>
      <style>{`
        :root { --theme-color: ${currentUser.profileColor || '#e21b3c'}; }
        .kahoot-shadow { box-shadow: 0 4px 0 0 rgba(0,0,0,0.2); }
        .text-custom { color: var(--theme-color); }
        .bg-custom { background-color: var(--theme-color); }
        .border-custom { border-color: var(--theme-color); }
      `}</style>

      <AnimatePresence>
        {showMoodCheckIn && <MoodCheckIn isDarkMode={isDarkMode} onSubmit={handleMoodSubmit} />}
      </AnimatePresence>

      <Sidebar 
        activeSection={activeSection} 
        onNavigate={(s) => { setActiveSection(s); if(s === 'Profile') setViewingUsername(currentUser!.username); }} 
        isDarkMode={isDarkMode} 
        user={currentUser!} 
        unreadMessages={allMessages.filter(m => m.recipient === currentUser!.username && !m.read).length} 
        unreadNotifications={notifications.filter(n => n.recipient === currentUser!.username && !n.read).length} 
      />

      <main className="flex-1 flex flex-col min-h-0 relative pt-14 pb-16 md:pt-0 md:pb-0 h-full overflow-hidden">
        <div className={`flex-1 flex flex-col min-h-0 ${isFixedSection ? 'overflow-hidden' : 'overflow-y-auto fading-scrollbar'} p-4 md:p-8`}>
          <motion.div 
            key={activeSection + (activeSection === 'Profile' ? viewingUsername : '')} 
            initial={{ opacity: 0, y: 10 }} 
            animate={{ opacity: 1, y: 0 }} 
            className="max-w-6xl mx-auto w-full flex-1 flex flex-col min-h-0 h-full"
          >
            {activeSection === 'Home' && <HomeSection user={currentUser!} posts={allPosts} isDarkMode={isDarkMode} />}
            {activeSection === 'Psychiatrist' && <PsychiatristSection currentUser={currentUser!} isDarkMode={isDarkMode} messages={allMessages} onSendMessage={(t) => handleSendMessage('DrPinel', t)} />}
            {activeSection === 'CityHall' && (
              <CityHallSection 
                isDarkMode={isDarkMode} currentUser={currentUser!} allUsers={allUsers}
                messages={allMessages} groups={allGroups} onSendMessage={handleSendMessage} 
                onGroupUpdate={(g) => setAllGroups(prev => prev.map(old => old.id === g.id ? g : old))}
                onGroupCreate={(g) => setAllGroups(prev => [...prev, g])}
                onReadMessages={(u) => setAllMessages(prev => prev.map(m => (m.recipient === currentUser!.username && m.sender === u) ? {...m, read: true} : m))} 
                onNavigateToProfile={(u) => {setViewingUsername(u); setActiveSection('Profile');}} 
                onReactToMessage={() => {}} 
                onViolation={handleViolation}
              />
            )}
            {activeSection === 'Mood' && <MoodSection user={currentUser!} posts={allPosts} onPost={handlePost} onHeart={handleHeart} onDeletePost={() => {}} onEditPost={() => {}} onComment={() => {}} onCommentInteraction={() => {}} onRepost={() => {}} onFollow={() => {}} onBlock={() => {}} isDarkMode={isDarkMode} onNavigateToProfile={() => {}} onUpdatePet={(hunger, thirst, rest, coins, exp) => setCurrentUser({...currentUser, petHunger: hunger, petThirst: thirst, petRest: rest, moodCoins: coins, petExp: exp || 0})} onViolation={handleViolation} />}
            {activeSection === 'Zodiac' && <ZodiacSection isDarkMode={isDarkMode} />}
            {activeSection === 'Notifications' && <NotificationsSection notifications={notifications.filter(n => n.recipient === currentUser!.username)} isDarkMode={isDarkMode} onMarkRead={() => {}} />}
            {activeSection === 'Profile' && currentUser && <ProfileSection user={allUsers.find(u => u.username === viewingUsername) || currentUser} allPosts={allPosts} isDarkMode={isDarkMode} currentUser={currentUser} onEditProfile={(dn, un, pp, ti, bp, pc, bi) => { setCurrentUser({...currentUser!, displayName: dn, username: un, profilePic: pp, title: ti, profileColor: pc, bio: bi}); }} />}
            {activeSection === 'Settings' && <SettingsSection isDarkMode={isDarkMode} onToggleDarkMode={() => setIsDarkMode(!isDarkMode)} onLogout={handleLogout} user={currentUser!} onUnblock={() => {}} />}
          </motion.div>
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Send, Users, Search, MessageSquare, ArrowLeft, ShieldCheck, Check, CheckCheck, Clock, Smile, Plus, X, Reply, Radio, Rocket, MessageCircle, Star, Ghost, Zap, Coffee, Music, Palette } from 'lucide-react';
import { User, Message, MessageReaction, Group } from '../types';
import { checkContentSafety } from '../services/geminiService';

interface CityHallSectionProps {
  isDarkMode: boolean;
  currentUser: User;
  allUsers: User[];
  messages: Message[];
  groups: Group[];
  onSendMessage: (recipient: string, text: string, options?: { isGroup?: boolean, recipients?: string[], groupName?: string, replyToId?: string, replyToText?: string, replyToSender?: string, isSystem?: boolean, liaisonData?: any }) => void;
  onReadMessages: (withUsername: string) => void;
  onGroupUpdate: (group: Group) => void;
  onGroupCreate: (group: Group) => void;
  onNavigateToProfile: (username: string) => void;
  onReactToMessage: (msgId: string, emoji: string) => void;
  onViolation: (reason: string) => void;
}

const GROUP_ICONS = ['🚀', '💬', '✨', '👻', '⚡', '☕', '🎵', '🎨', '🔥', '🌈', '🛸', '🛡️'];

const CityHallSection: React.FC<CityHallSectionProps> = ({ isDarkMode, currentUser, allUsers, messages, groups, onSendMessage, onReadMessages, onGroupUpdate, onGroupCreate, onNavigateToProfile, onReactToMessage, onViolation }) => {
  const [input, setInput] = useState('');
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedCitizen, setSelectedCitizen] = useState<{ username: string, isGroup?: boolean } | null>(null);
  const [replyingTo, setReplyingTo] = useState<Message | null>(null);
  const [isSending, setIsSending] = useState(false);

  // Group creation state
  const [isCreatingGroup, setIsCreatingGroup] = useState(false);
  const [groupName, setGroupName] = useState('');
  const [selectedGroupIcon, setSelectedGroupIcon] = useState('🚀');
  const [selectedForGroup, setSelectedForGroup] = useState<string[]>([]);
  const [userSearchTerm, setUserSearchTerm] = useState('');

  const chatScrollRef = useRef<HTMLDivElement>(null);

  const getUserByUsername = (username: string) => allUsers.find(u => u.username === username);
  const getGroupById = (id: string) => groups.find(g => g.id === id);

  const chats = useMemo(() => {
    const list: any[] = [];
    const processedDms = new Set<string>();

    groups.forEach(g => {
      if (g.members.includes(currentUser.username)) {
        list.push({ username: g.id, displayName: g.name, isGroup: true, profilePic: g.photo || '🚀' });
      }
    });

    messages.forEach(m => {
      if (!m.isGroup) {
        const other = m.sender === currentUser.username ? m.recipient : m.sender;
        if (!processedDms.has(other)) {
          processedDms.add(other);
          const userObj = getUserByUsername(other);
          if (userObj) {
            list.push({ username: other, displayName: userObj.displayName, profilePic: userObj.profilePic, isGroup: false });
          }
        }
      }
    });
    return list;
  }, [messages, allUsers, currentUser.username, groups]);

  const activeChatInfo = useMemo(() => {
    if (!selectedCitizen) return null;
    if (selectedCitizen.isGroup) {
      const g = getGroupById(selectedCitizen.username);
      return { username: selectedCitizen.username, displayName: g?.name || 'Group', profilePic: g?.photo || '🚀', isGroup: true, recipients: g?.members };
    } else {
      const u = getUserByUsername(selectedCitizen.username);
      return { username: selectedCitizen.username, displayName: u?.displayName || selectedCitizen.username, profilePic: u?.profilePic, isGroup: false };
    }
  }, [selectedCitizen, allUsers, groups]);

  const chatMessages = useMemo(() => {
    if (!selectedCitizen) return [];
    if (selectedCitizen.isGroup) return messages.filter(m => m.isGroup && m.recipient === selectedCitizen.username).sort((a, b) => a.timestamp - b.timestamp);
    return messages.filter(m => !m.isGroup && ((m.sender === currentUser.username && m.recipient === selectedCitizen.username) || (m.sender === selectedCitizen.username && m.recipient === currentUser.username))).sort((a, b) => a.timestamp - b.timestamp);
  }, [messages, selectedCitizen, currentUser.username]);

  useEffect(() => {
    if (selectedCitizen && !selectedCitizen.isGroup) onReadMessages(selectedCitizen.username);
    setTimeout(() => { chatScrollRef.current?.scrollTo({ top: chatScrollRef.current.scrollHeight, behavior: 'smooth' }); }, 100);
  }, [selectedCitizen?.username]);

  useEffect(() => {
    if (chatMessages.length > 0) {
        chatScrollRef.current?.scrollTo({ top: chatScrollRef.current.scrollHeight, behavior: 'smooth' });
    }
  }, [chatMessages.length]);

  const handleSend = async () => {
    if (!input.trim() || !activeChatInfo || isSending) return;
    setIsSending(true);
    const safety = await checkContentSafety(input);
    if (safety.isInappropriate) {
      onViolation(safety.reason);
      setIsSending(false);
      return;
    }
    onSendMessage(activeChatInfo.username, input, { isGroup: activeChatInfo.isGroup, recipients: activeChatInfo.recipients, groupName: activeChatInfo.displayName });
    setInput('');
    setReplyingTo(null);
    setIsSending(false);
  };

  const handleCreateGroup = () => {
    if (!groupName.trim() || selectedForGroup.length < 2) return;
    const groupId = 'group_' + Math.random().toString(36).substr(2, 9);
    const members = [...selectedForGroup, currentUser.username];
    const newGroup: Group = { id: groupId, name: groupName, owner: currentUser.username, members: members, nicknames: {}, createdAt: Date.now(), photo: selectedGroupIcon };
    onGroupCreate(newGroup);
    onSendMessage(groupId, `METROPOLIS HUB: Neural link established. Citizens ${members.join(', ')} joined.`, { isGroup: true, recipients: members, groupName, isSystem: true });
    setSelectedCitizen({ username: groupId, isGroup: true });

    // Reset state
    setIsCreatingGroup(false);
    setGroupName('');
    setSelectedForGroup([]);
    setSelectedGroupIcon('🚀');
  };

  const filteredChats = chats.filter(c => c.displayName.toLowerCase().includes(searchTerm.toLowerCase()) || c.username.toLowerCase().includes(searchTerm.toLowerCase()));
  const filteredUsers = allUsers.filter(u => u.username !== currentUser.username && (u.username.toLowerCase().includes(userSearchTerm.toLowerCase()) || u.displayName.toLowerCase().includes(userSearchTerm.toLowerCase())));

  return (
    <div className="flex flex-col h-full min-h-0 w-full relative">
      <div className="flex justify-between items-center mb-6 shrink-0 px-2">
        <h2 className={`text-3xl md:text-4xl font-black italic uppercase tracking-tighter ${isDarkMode ? 'text-white' : 'text-slate-900'}`}>Citizen Hub</h2>
        <button onClick={() => setIsCreatingGroup(true)} className="kahoot-button-blue px-6 py-3 rounded-2xl text-white font-black flex items-center gap-2 shadow-lg active:scale-95 text-xs">
          <Plus size={18} /> <span>NEW GROUP</span>
        </button>
      </div>

      <div className={`flex-1 flex flex-col md:flex-row rounded-[3rem] ${isDarkMode ? 'bg-slate-900' : 'bg-white'} shadow-2xl overflow-hidden border-4 border-black/5 relative min-h-0 h-full`}>
        {/* Sidebar */}
        <div className={`w-full md:w-64 lg:w-80 border-r ${isDarkMode ? 'border-slate-800' : 'border-gray-100'} flex flex-col ${selectedCitizen ? 'hidden md:flex' : 'flex'} min-h-0 h-full`}>
          <div className="p-4 border-b border-gray-100 dark:border-slate-800 shrink-0">
            <div className="relative">
              <input type="text" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} placeholder="Search real citizens..." className={`w-full pl-10 pr-4 py-3 rounded-2xl text-[12px] font-black border-2 outline-none focus:border-blue-500 transition-all ${isDarkMode ? 'bg-slate-800 border-slate-700' : 'bg-gray-50 border-gray-200'}`} />
              <Search className="absolute left-3.5 top-1/2 -translate-y-1/2 opacity-30" size={16} />
            </div>
          </div>
          <div className="flex-1 overflow-y-auto fading-scrollbar p-3 space-y-2 min-h-0 h-full">
            {filteredChats.map(chat => (
              <button key={chat.username} onClick={() => setSelectedCitizen({ username: chat.username, isGroup: chat.isGroup })} className={`w-full p-4 rounded-[1.5rem] flex items-center gap-3 transition-all border-b-4 active:translate-y-0.5 active:border-b-2 ${selectedCitizen?.username === chat.username ? 'bg-blue-600 border-blue-800 text-white shadow-md' : 'hover:bg-black/5'}`}>
                <div className="w-10 h-10 rounded-xl bg-blue-100 dark:bg-slate-700 flex items-center justify-center font-black overflow-hidden shadow-sm shrink-0">
                  {chat.isGroup ? <span className="text-xl">{chat.profilePic}</span> : (chat.profilePic ? <img src={chat.profilePic} className="w-full h-full object-cover" /> : chat.displayName[0])}
                </div>
                <div className="text-left flex-1 min-w-0">
                  <p className="font-black text-[12px] truncate uppercase tracking-tight">{chat.displayName}</p>
                  <p className="text-[9px] font-black uppercase tracking-widest opacity-40">@{chat.username}</p>
                </div>
              </button>
            ))}
          </div>
        </div>

