                    <p className="text-[10px] font-black uppercase tracking-widest opacity-40 ml-2">Network Alias</p>
                    <input type="text" value={groupName} onChange={e => setGroupName(e.target.value)} placeholder="Group Designation..." className="w-full p-4 rounded-2xl border-2 bg-black/5 font-black text-lg outline-none focus:border-custom" />
