import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { User, Mood, Section, Post, Comment, Message, Notification, Group } from './types';
import Sidebar from './components/Sidebar';
import HomeSection from './sections/HomeSection';
import MoodSection from './sections/MoodSection';
import ZodiacSection from './sections/ZodiacSection';
import CityHallSection from './sections/CityHallSection';
import PsychiatristSection from './sections/PsychiatristSection';
import ProfileSection from './sections/ProfileSection';
import SettingsSection from './sections/SettingsSection';
import NotificationsSection from './sections/NotificationsSection';
import AuthScreen from './sections/AuthScreen';
import LoadingScreen from './components/LoadingScreen';
import MoodCheckIn from './components/MoodCheckIn';
import { getExpNeeded, MOOD_SCORES } from './constants';
import { LogOut, Gavel, ShieldAlert } from 'lucide-react';
import { getPsychiatristResponse } from './services/geminiService';
import { supabase, isCloudEnabled, fetchGlobalFeed, syncProfile, fetchProfiles } from './services/supabaseService';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [allUsers, setAllUsers] = useState<User[]>([]);
  const [activeSection, setActiveSection] = useState<Section>('Home');
  const [viewingUsername, setViewingUsername] = useState<string | null>(null);
  const [isDarkMode, setIsDarkMode] = useState(false); 
  const [isAppStarting, setIsAppStarting] = useState(true);
  const [showMoodCheckIn, setShowMoodCheckIn] = useState(false);

  const [allPosts, setAllPosts] = useState<Post[]>([]);
  const [allMessages, setAllMessages] = useState<Message[]>([]);
  const [allGroups, setAllGroups] = useState<Group[]>([]);
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);

  const [activeWarning, setActiveWarning] = useState<{ count: number, reason: string } | null>(null);

  const migrateUserData = (user: User): User => {
    return {
      ...user,
      blockedUsers: user.blockedUsers || [],
      moodHistory: user.moodHistory || [],
      following: user.following || [],
      followers: user.followers || [],
      moodStreak: user.moodStreak || 0,
      petLevel: user.petLevel || 1,
      moodCoins: user.moodCoins ?? 100,
      gameCooldowns: user.gameCooldowns || {},
      petHasBeenChosen: !!user.petHasBeenChosen,
      warnings: user.warnings ?? 0,
      isBanned: !!user.isBanned
    };
  };

  // 1. Initial Load & Theme
  useEffect(() => {
    const init = async () => {
      const savedTheme = localStorage.getItem('mooderia_theme');
      if (savedTheme === 'dark') setIsDarkMode(true);

      if (isCloudEnabled && supabase) {
        try {
          const { data: { session } } = await supabase.auth.getSession();
          if (session) {
            const { data: profile } = await supabase.from('profiles').select('*').eq('id', session.user.id).single();
            if (profile) setCurrentUser(migrateUserData(profile.metadata));
          }
          const [feed, users] = await Promise.all([fetchGlobalFeed(), fetchProfiles()]);
          setAllPosts(feed as Post[]);
          setAllUsers(users);
        } catch (e) { console.info("METROPOLIS: Remote fetch failed."); }
      } else {
        const savedUser = localStorage.getItem('mooderia_user');
        if (savedUser) setCurrentUser(migrateUserData(JSON.parse(savedUser)));
      }
      setIsLoaded(true);
      setTimeout(() => setIsAppStarting(false), 2000);
    };
    init();
  }, []);

  // 2. DAILY MOOD TRIGGER - Monitors user state and triggers if today is not checked in
  useEffect(() => {
    if (isLoaded && currentUser && !showMoodCheckIn) {
      const todayStr = new Date().toDateString();
      if (currentUser.lastMoodDate !== todayStr) {
        setShowMoodCheckIn(true);
      }
    }
  }, [currentUser?.username, isLoaded]);

  // 3. Persistence
  useEffect(() => {
    if (!isLoaded || !currentUser) return;
    localStorage.setItem('mooderia_user', JSON.stringify(currentUser));
    if (isCloudEnabled) syncProfile(currentUser);
  }, [currentUser, isLoaded]);

  // 4. AI Response Listener - Handles responses from the Psychiatrist section
  useEffect(() => {
    const handleAIResponse = (e: any) => {
      setAllMessages(prev => [...prev, e.detail]);
    };
    window.addEventListener('ai-response', handleAIResponse as EventListener);
    return () => window.removeEventListener('ai-response', handleAIResponse as EventListener);
  }, []);

  // Fix: Added missing handleLogout function
  const handleLogout = useCallback(async () => {
    if (isCloudEnabled && supabase) {
      try {
        await supabase.auth.signOut();
      } catch (e) {}
    }
    localStorage.removeItem('mooderia_user');
    setCurrentUser(null);
  }, []);

  const handleMoodSubmit = (mood: Mood) => {
    if (!currentUser) return;
    const today = new Date();
    const todayStr = today.toDateString();

    let newStreak = 1;
    if (currentUser.lastMoodDate) {
      const lastDate = new Date(currentUser.lastMoodDate);
      const diffTime = Math.abs(today.getTime() - lastDate.getTime());
      const diffDays = Math.floor(diffTime / (1000 * 60 * 60 * 24));

      if (diffDays === 1) {
        newStreak = (currentUser.moodStreak || 0) + 1;
      } else if (diffDays === 0) {
        newStreak = currentUser.moodStreak || 1;
      } else {
        newStreak = 1; // Streak broken
      }
    }

    const moodScore = mood ? MOOD_SCORES[mood] : 50;
    const newHistory = [...(currentUser.moodHistory || []), { date: todayStr, mood, score: moodScore }];

    setCurrentUser({
      ...currentUser,
      moodHistory: newHistory,
      moodStreak: newStreak,
      lastMoodDate: todayStr,
      moodCoins: (currentUser.moodCoins || 0) + 25, // Bonus for check-in
      petExp: (currentUser.petExp || 0) + 50
    });

    setShowMoodCheckIn(false);
  };

  const handleSendMessage = async (recipient: string, text: string, options?: any) => {
    if (!currentUser) return;
    const newMessageData: any = {
      sender: currentUser.username,
      recipient,
      text,
      is_group: options?.isGroup || false,
    };
    if (isCloudEnabled && supabase) {
      try { await supabase.from('messages').insert(newMessageData); } catch (e) {}
    } else {
      setAllMessages(prev => [...prev, { ...newMessageData, id: Math.random().toString(), timestamp: Date.now(), read: false }]);
    }
  };

  const handlePost = async (content: string, visibility: 'global' | 'circle') => {
    if (!currentUser) return;
    const newPostData: any = { author_username: currentUser.username, content, visibility, likes: [] };
    if (isCloudEnabled && supabase) {
      try { await supabase.from('posts').insert(newPostData); } catch (e) {}
    } else {
      setAllPosts(prev => [{ ...newPostData, id: Math.random().toString(), timestamp: Date.now(), author: currentUser.username, likes: [], comments: [] } as any, ...prev]);
    }
  };

  const handleHeart = (postId: string) => {
    if (!currentUser) return;
    setAllPosts(prev => prev.map(p => {
      if (p.id === postId) {
        const isLiked = p.likes?.includes(currentUser.username);
        const nextLikes = isLiked ? p.likes.filter(u => u !== currentUser.username) : [...(p.likes || []), currentUser.username];
        return { ...p, likes: nextLikes };
      }
      return p;
    }));
  };

  if (isAppStarting) return <LoadingScreen />;
  if (!currentUser) return <AuthScreen onLogin={(u) => { setCurrentUser(u); setViewingUsername(u.username); }} />;

  const isFixedSection = activeSection === 'CityHall' || activeSection === 'Mood' || activeSection === 'Psychiatrist';

  return (
    <div style={{'--theme-color': currentUser.profileColor || '#e21b3c'} as React.CSSProperties} className={`h-screen max-h-screen overflow-hidden flex flex-col md:flex-row ${isDarkMode ? 'bg-[#0f0f0f] text-white' : 'bg-[#f7f8fa] text-slate-900'} transition-colors duration-300`}>
      <style>{`
        :root { --theme-color: ${currentUser.profileColor || '#e21b3c'}; }
        .kahoot-shadow { box-shadow: 0 4px 0 0 rgba(0,0,0,0.2); }
        .bg-custom { background-color: var(--theme-color); }
        .text-custom { color: var(--theme-color); }
      `}</style>

      <AnimatePresence>
        {showMoodCheckIn && <MoodCheckIn isDarkMode={isDarkMode} onSubmit={handleMoodSubmit} />}
      </AnimatePresence>

      <Sidebar 
        activeSection={activeSection} 
        onNavigate={(s) => { setActiveSection(s); if(s === 'Profile') setViewingUsername(currentUser!.username); }} 
        isDarkMode={isDarkMode} 
        user={currentUser!} 
        unreadMessages={allMessages.filter(m => m.recipient === currentUser!.username && !m.read).length} 
        unreadNotifications={notifications.filter(n => n.recipient === currentUser!.username && !n.read).length} 
      />

      <main className="flex-1 flex flex-col min-h-0 relative pt-14 pb-16 md:pt-0 md:pb-0 h-full overflow-hidden">
        <div className={`flex-1 flex flex-col min-h-0 ${isFixedSection ? 'overflow-hidden' : 'overflow-y-auto fading-scrollbar'} p-4 md:p-8`}>
          <motion.div 
            key={activeSection + (activeSection === 'Profile' ? viewingUsername : '')} 
            initial={{ opacity: 0, y: 10 }} 
            animate={{ opacity: 1, y: 0 }} 
            className="max-w-6xl mx-auto w-full flex-1 flex flex-col min-h-0 h-full"
          >
            {activeSection === 'Home' && <HomeSection user={currentUser!} posts={allPosts} isDarkMode={isDarkMode} />}
            {activeSection === 'Psychiatrist' && <PsychiatristSection currentUser={currentUser!} isDarkMode={isDarkMode} messages={allMessages} onSendMessage={(t) => handleSendMessage('DrPinel', t)} />}
            {activeSection === 'CityHall' && (
              <CityHallSection 
                isDarkMode={isDarkMode} currentUser={currentUser!} allUsers={allUsers}
                messages={allMessages} groups={allGroups} onSendMessage={handleSendMessage} 
                onGroupUpdate={(g) => setAllGroups(prev => prev.map(old => old.id === g.id ? g : old))}
                onGroupCreate={(g) => setAllGroups(prev => [...prev, g])}
                onReadMessages={(u) => setAllMessages(prev => prev.map(m => (m.recipient === currentUser!.username && m.sender === u) ? {...m, read: true} : m))} 
                onNavigateToProfile={(u) => {setViewingUsername(u); setActiveSection('Profile');}} 
                onReactToMessage={() => {}} 
                onViolation={() => {}}
              />
            )}
            {activeSection === 'Mood' && <MoodSection user={currentUser!} posts={allPosts} onPost={handlePost} onHeart={handleHeart} onDeletePost={() => {}} onEditPost={() => {}} onComment={() => {}} onCommentInteraction={() => {}} onRepost={() => {}} onFollow={() => {}} onBlock={() => {}} isDarkMode={isDarkMode} onNavigateToProfile={() => {}} onUpdatePet={(h, t, r, c, e) => setCurrentUser({...currentUser, petHunger: h, petThirst: t, petRest: r, moodCoins: c, petExp: e || 0})} onViolation={() => {}} />}
            {activeSection === 'Zodiac' && <ZodiacSection isDarkMode={isDarkMode} />}
            {activeSection === 'Notifications' && <NotificationsSection notifications={notifications.filter(n => n.recipient === currentUser!.username)} isDarkMode={isDarkMode} onMarkRead={() => {}} />}
            {activeSection === 'Profile' && currentUser && <ProfileSection user={allUsers.find(u => u.username === viewingUsername) || currentUser} allPosts={allPosts} isDarkMode={isDarkMode} currentUser={currentUser} onEditProfile={(dn, un, pp, ti, bp, pc, bi) => { setCurrentUser({...currentUser!, displayName: dn, username: un, profilePic: pp, title: ti, profileColor: pc, bio: bi}); }} />}
            {activeSection === 'Settings' && <SettingsSection isDarkMode={isDarkMode} onToggleDarkMode={() => setIsDarkMode(!isDarkMode)} onLogout={handleLogout} user={currentUser!} onUnblock={() => {}} />}
          </motion.div>
        </div>
      </main>
    </div>
  );
};

export default App;

import { GoogleGenAI, Type } from "@google/genai";

// Standard initialization as per instructions
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const getPsychiatristResponse = async (message: string) => {
  try {
    // Correct content generation with direct string prompt
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: message,
      config: {
        systemInstruction: "You are Dr. Philippe Pinel, the Chief Psychiatrist of Mooderia. You provide compassionate, expert, and concise mental health support to citizens. Your tone is professional, warm, and therapeutic. Focus on validation, mindfulness, and gentle guidance. Keep responses under 3 paragraphs.",
      }
    });
    // response.text is a property, not a method
    return { text: response.text || "The neural link is experiencing static. Dr. Pinel is momentarily unavailable." };
  } catch (error) {
    console.error("Psychiatrist API Error:", error);
    return { text: "Connection to the Medical District failed. Please ensure your Metropolis credentials (API Key) are valid and that you have redeployed after adding them." };
  }
};

export const getHoroscope = async (sign: string) => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Provide a daily horoscope for ${sign} today.`,
      config: {
        systemInstruction: "You are a mystical Metropolis Astrologer. Provide a 3-sentence daily horoscope that is encouraging and insightful. Use cosmic and modern terminology.",
      }
    });
    return response.text || "The constellations are currently obscured by metropolis smog.";
  } catch (error) {
    console.error("Horoscope API Error:", error);
    return "The stars are recalibrating. Check back later.";
  }
};

export const getLovePrediction = async (sign1: string, sign2: string) => {
  try {
    const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Predict love compatibility between ${sign1} and ${sign2}. Return only a JSON object with 'percentage' (0-100) and 'reason'.`,
        config: {
            responseMimeType: "application/json",
            responseSchema: {
                type: Type.OBJECT,
                properties: {
                    percentage: { type: Type.NUMBER },
                    reason: { type: Type.STRING }
                },
                required: ['percentage', 'reason']
            }
        }
    });

    const text = response.text || "{}";
    return JSON.parse(text.trim());
  } catch (error) {
    console.error("Love Prediction API Error:", error);
    return { percentage: 50, reason: "The romantic frequencies are currently experiencing atmospheric interference." };
  }
}

export const checkContentSafety = async (text: string) => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Analyze the following text for inappropriate language, hate speech, severe insults, or harassment: "${text}". Return a JSON object with 'isInappropriate' (boolean) and 'reason' (string, keep it short).`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            isInappropriate: { type: Type.BOOLEAN },
            reason: { type: Type.STRING }
          },
          required: ['isInappropriate', 'reason']
        }
      }
    });
    const resultText = response.text || "{}";
    return JSON.parse(resultText.trim());
  } catch (error) {
    console.error("Safety Check Error:", error);
    return { isInappropriate: false, reason: "" };
  }
};

import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { User } from '../types';
import LoadingScreen from '../components/LoadingScreen';
import { Cloud, Key, UserPlus, LogIn, ShieldCheck, Globe, UserCheck } from 'lucide-react';
import { supabase, isCloudEnabled, syncProfile } from '../services/supabaseService';

interface AuthScreenProps {
  onLogin: (user: User) => void;
}

const AuthScreen: React.FC<AuthScreenProps> = ({ onLogin }) => {
  const [authMode, setAuthMode] = useState<'login' | 'signup'>('login');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [displayName, setDisplayName] = useState('');
  const [username, setUsername] = useState('');
  const [error, setError] = useState('');
  const [isAuthenticating, setIsAuthenticating] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setIsAuthenticating(true);

    if (isCloudEnabled && supabase) {
      try {
        if (authMode === 'signup') {
          const { data, error: signUpError } = await supabase.auth.signUp({ email, password });
          if (signUpError) throw signUpError;

          if (data.user) {
            const newUser: User = {
              displayName, username, email,
              followers: [], following: [], friends: [], blockedUsers: [], posts: [], reposts: [],
              moodHistory: [], moodStreak: 0, title: 'Citizen', likesReceived: 0,
              petName: 'Guardian', moodCoins: 100, petEmoji: '🐱', petHunger: 100, petThirst: 100, petRest: 100,
              petLevel: 1, petExp: 0, petHasBeenChosen: false, petLastUpdate: Date.now(), petSleepUntil: null,
              gameCooldowns: {}, warnings: 0, isBanned: false
            };
            await syncProfile({ ...newUser, id: data.user.id });
            onLogin(newUser);
          }
        } else {
          const { data, error: signInError } = await supabase.auth.signInWithPassword({ email, password });
          if (signInError) throw signInError;

          const { data: profile } = await supabase.from('profiles').select('*').eq('id', data.user.id).single();
          if (profile) onLogin(profile.metadata);
          else throw new Error("Profile not found in cloud grid.");
        }
      } catch (err: any) {
        setError(err.message + ". (Email limits may apply)");
        setIsAuthenticating(false);
      }
    } else {
      handleGuestAccess();
    }
  };

  const handleGuestAccess = () => {
    setIsAuthenticating(true);
    setTimeout(() => {
      onLogin({ 
        displayName: displayName || 'Citizen', 
        username: username || 'guest_' + Math.random().toString(36).substr(2, 5), 
        email: email || 'guest@mooderia.local', 
        moodStreak: 0,
        followers: [], following: [], friends: [], blockedUsers: [], posts: [], reposts: [],
        moodHistory: [], title: 'Guest', likesReceived: 0,
        petName: 'Guardian', moodCoins: 100, petEmoji: '🐱', petHunger: 100, petThirst: 100, petRest: 100,
        petLevel: 1, petExp: 0, petHasBeenChosen: false, petLastUpdate: Date.now(), petSleepUntil: null,
        gameCooldowns: {}, warnings: 0, isBanned: false
      } as any);
    }, 1000);
  };

  if (isAuthenticating) return <LoadingScreen />;

  return (
    <div className="min-h-screen flex items-center justify-center bg-[#46178f] p-4 relative overflow-hidden">
      <div className="absolute inset-0 opacity-10 pointer-events-none overflow-hidden">
        {Array.from({ length: 15 }).map((_, i) => (
          <div key={i} className="absolute text-white font-black opacity-20 rotate-12 text-6xl" style={{ top: `${Math.random() * 100}%`, left: `${Math.random() * 100}%` }}>MOODERIA</div>
        ))}
      </div>

      <motion.div initial={{ y: 50, opacity: 0 }} animate={{ y: 0, opacity: 1 }} className="w-full max-w-md bg-slate-900 border-4 border-white/10 rounded-[2.5rem] shadow-2xl p-8 z-10 text-white">
        <div className="text-center mb-8">
          <h1 className="text-4xl md:text-5xl font-black italic text-white tracking-tighter mb-2 uppercase">Mooderia</h1>
          <div className="flex items-center justify-center gap-2">
            <Globe size={14} className="text-blue-400" />
            <p className="text-blue-400 font-bold uppercase tracking-widest text-[10px]">Worldwide Sync Grid</p>
          </div>
        </div>

        <form onSubmit={handleSubmit} className="space-y-4">
          <AnimatePresence mode="wait">
            {authMode === 'signup' && (
              <motion.div key="signup" initial={{ height: 0, opacity: 0 }} animate={{ height: 'auto', opacity: 1 }} exit={{ height: 0, opacity: 0 }} className="space-y-4 overflow-hidden">
                <input type="text" placeholder="Identity Name" required value={displayName} onChange={(e) => setDisplayName(e.target.value)} className="w-full p-4 rounded-xl bg-slate-800 text-white border-2 border-slate-700 focus:border-blue-500 outline-none font-bold text-sm" />
                <input type="text" placeholder="ID Handle (Username)" required value={username} onChange={(e) => setUsername(e.target.value)} className="w-full p-4 rounded-xl bg-slate-800 text-white border-2 border-slate-700 focus:border-blue-500 outline-none font-bold text-sm" />
              </motion.div>
            )}
          </AnimatePresence>

          <input type="email" placeholder="Neural Link (Email)" required value={email} onChange={(e) => setEmail(e.target.value)} className="w-full p-4 rounded-xl bg-slate-800 text-white border-2 border-slate-700 focus:border-blue-500 outline-none font-bold text-sm" />
          <input type="password" placeholder="Access Phrase (Password)" required value={password} onChange={(e) => setPassword(e.target.value)} className="w-full p-4 rounded-xl bg-slate-800 text-white border-2 border-slate-700 focus:border-blue-500 outline-none font-bold text-sm" />

          {error && <p className="text-[#e21b3c] text-xs font-black text-center bg-red-500/10 p-3 rounded-xl border border-red-500/20">{error}</p>}

          <button type="submit" className="kahoot-button-blue w-full p-5 rounded-2xl text-white font-black text-lg mt-4 shadow-lg active:scale-95 uppercase flex items-center justify-center gap-3">
            {authMode === 'signup' ? <UserPlus size={20}/> : <LogIn size={20}/>}
            {authMode === 'signup' ? 'Authorize ID' : 'Synchronize'}
          </button>
        </form>

        <div className="mt-8 flex flex-col gap-4">
          <button onClick={() => { setAuthMode(authMode === 'login' ? 'signup' : 'login'); setError(''); }} className="text-xs font-bold text-blue-400 hover:text-white transition-colors hover:underline text-center uppercase tracking-widest">
            {authMode === 'signup' ? 'Back to Neural Login' : "New entity? Apply for Citizenship"}
          </button>

          <div className="relative flex items-center py-2">
            <div className="flex-grow border-t border-white/10"></div>
            <span className="flex-shrink mx-4 text-[8px] font-black uppercase opacity-20 tracking-widest text-white">OR BYPASS LIMITS</span>
            <div className="flex-grow border-t border-white/10"></div>
