        </div>
        <div className={`col-span-2 md:col-span-1 p-6 md:p-8 rounded-[3rem] ${isDarkMode ? 'bg-[#111111]' : 'bg-white'} shadow-2xl border-b-[8px] border-red-500/10`}>
          <p className="text-[10px] font-black opacity-30 uppercase tracking-[0.4em] mb-4">Harmony</p>
          <div className="flex items-center gap-3"><p className="text-4xl md:text-5xl font-black text-[#e21b3c] italic">{happiness}%</p></div>
        </div>
      </div>

      <div className={`flex-1 min-h-[350px] p-6 md:p-8 rounded-[3rem] md:rounded-[4rem] ${isDarkMode ? 'bg-[#111111]' : 'bg-white'} shadow-2xl overflow-hidden border-4 border-black/5 flex flex-col`}>
        <div className="flex justify-between items-center mb-6 px-2 shrink-0">
          <h3 className="text-xl md:text-2xl font-black uppercase italic flex items-center gap-3"><TrendingUp className="text-custom" size={24} /> Sync History</h3>
          <div className="bg-custom/10 px-4 py-1.5 rounded-full border-2 border-custom/20 hidden sm:block"><span className="text-custom font-black text-[10px] uppercase tracking-widest">Active Resonance</span></div>
        </div>
        <div className="flex-1 w-full min-h-0">
          <ResponsiveContainer width="100%" height="100%" minHeight={200}>
            <AreaChart data={chartData}>
              <CartesianGrid strokeDasharray="6 6" vertical={false} stroke={isDarkMode ? "#222" : "#eee"} />
              <XAxis dataKey="name" hide />
              <YAxis domain={[0, 100]} hide />
              <Tooltip contentStyle={{ backgroundColor: isDarkMode ? '#111' : '#fff', borderRadius: '16px', border: '2px solid rgba(0,0,0,0.05)', fontWeight: '900', fontSize: '11px' }} />
              <Area type="monotone" dataKey="score" stroke="var(--theme-color)" fill="var(--theme-color)" fillOpacity={0.1} strokeWidth={6} />
            </AreaChart>
          </ResponsiveContainer>
        </div>
      </div>

      <div className={`p-8 md:p-10 rounded-[3rem] border-l-[12px] border-[#ffa602] ${isDarkMode ? 'bg-[#111111]' : 'bg-white'} shadow-2xl relative overflow-hidden group shrink-0`}>
        <h4 className="font-black text-xl mb-4 uppercase italic tracking-tighter opacity-30">Metropolis Insight</h4>
        <p className="italic font-bold text-xl md:text-3xl leading-snug opacity-90 relative z-10">"{todayWisdom}"</p>
      </div>
    </div>
  );
};

export default HomeSection;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Heart, Send, Sparkles, Brain, Clock, Globe, Users, Trophy, MessageSquare, Repeat, Reply, ShieldAlert, Activity, Stethoscope, Trash2, Edit, X } from 'lucide-react';
import { User, Post, Comment } from '../types';
import MoodPetSection from './MoodPetSection';
import { STREAK_BADGES } from '../constants';

interface MoodSectionProps {
  user: User;
  posts: Post[];
  onPost: (content: string, visibility: 'global' | 'circle') => void;
  onHeart: (postId: string) => void;
  onDeletePost: (postId: string) => void;
  onEditPost: (postId: string, newContent: string) => void;
  onComment: (postId: string, text: string) => void;
  onCommentInteraction: (postId: string, commentId: string, action: 'heart' | 'reply', replyText?: string) => void;
  onRepost: (post: Post) => void;
  onFollow: (username: string) => void;
  onBlock: (username: string) => void;
  isDarkMode: boolean;
  onNavigateToProfile: (username: string) => void;
  onUpdatePet: (hunger: number, thirst: number, rest: number, coins: number, exp?: number, sleepUntil?: number | null, newEmoji?: string, markChosen?: boolean, newName?: string, gameCooldownId?: string) => void;
  onViolation: (reason: string) => void;
}

const MoodSection: React.FC<MoodSectionProps> = ({ user, posts, onPost, onHeart, onDeletePost, onEditPost, onComment, onCommentInteraction, onRepost, onFollow, onBlock, isDarkMode, onNavigateToProfile, onUpdatePet, onViolation }) => {
  const [subTab, setSubTab] = useState<'Express' | 'Teller' | 'Scan' | 'Mood Pet'>('Express');
  const [postContent, setPostContent] = useState('');
  const [feedFilter, setFeedFilter] = useState<'Global' | 'Circle'>('Global');
  const [postVisibility, setPostVisibility] = useState<'global' | 'circle'>('global');
  const [isBroadcasting, setIsBroadcasting] = useState(false);

  const [tellerQuestion, setTellerQuestion] = useState('');
  const [tellerResponse, setTellerResponse] = useState('');
  const [isTellerLoading, setIsTellerLoading] = useState(false);

  const [quizActive, setQuizActive] = useState(false);
  const [quizStep, setQuizStep] = useState(0);
  const [quizScores, setQuizScores] = useState<Record<string, number>>({ Happy: 0, Angry: 0, Tired: 0, Normal: 0, Excited: 0 });
  const [quizResult, setQuizResult] = useState<string | null>(null);

  const [expandedPostId, setExpandedPostId] = useState<string | null>(null);
  const [commentInputs, setCommentInputs] = useState<Record<string, string>>({});
  const [replyingTo, setReplyingTo] = useState<{ postId: string, commentId: string } | null>(null);
  const [replyContent, setReplyContent] = useState('');

  const [editingPostId, setEditingPostId] = useState<string | null>(null);
  const [editBuffer, setEditBuffer] = useState('');

  const [likersModalPost, setLikersModalPost] = useState<Post | null>(null);

  const filteredPosts = useMemo(() => {
    let result = posts.filter(p => !user.blockedUsers.includes(p.author));
    if (feedFilter === 'Global') return result.filter(p => p.visibility === 'global');
    return result.filter(p => p.visibility === 'circle' && (user.following.includes(p.author) || p.author === user.username));
  }, [posts, feedFilter, user.following, user.username, user.blockedUsers]);

  const handlePost = async () => {
    if (!postContent.trim() || isBroadcasting) return;
    setIsBroadcasting(true);
    onPost(postContent, postVisibility);
    setPostContent('');
    setIsBroadcasting(false);
  };

  const handleStartEdit = (post: Post) => {
    setEditingPostId(post.id);
    setEditBuffer(post.content);
  };

  const handleSaveEdit = async () => {
    if (!editingPostId || !editBuffer.trim()) return;
    onEditPost(editingPostId, editBuffer);
    setEditingPostId(null);
  };

  const handleAddComment = (postId: string) => {
    const text = commentInputs[postId];
    if (!text?.trim()) return;
    onComment(postId, text);
    setCommentInputs(prev => ({ ...prev, [postId]: '' }));
  };

  const handleReply = (postId: string, commentId: string) => {
    if (!replyContent.trim()) return;
    onCommentInteraction(postId, commentId, 'reply', replyContent);
    setReplyContent('');
    setReplyingTo(null);
  };

  const renderComment = (postId: string, comment: Comment, depth = 0) => (
    <div key={comment.id} className={`mt-4 ${depth > 0 ? 'ml-6 md:ml-10 border-l-2 border-black/5 pl-4' : ''}`}>
      <div className="flex items-start gap-3">
        <button onClick={() => onNavigateToProfile(comment.author)} className="w-8 h-8 rounded-lg bg-custom text-white font-black flex items-center justify-center shrink-0 text-sm italic active:scale-95 transition-transform">{comment.author[0].toUpperCase()}</button>
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2">
            <button onClick={() => onNavigateToProfile(comment.author)} className="font-black text-xs hover:text-custom transition-colors">@{comment.author}</button>
            <span className="text-[8px] font-black opacity-30 uppercase tracking-widest">{new Date(comment.timestamp).toLocaleDateString()}</span>
          </div>
          <p className="text-sm font-bold opacity-80 mt-1 leading-relaxed">"{comment.text}"</p>
          <div className="flex items-center gap-4 mt-2">
            <button onClick={() => onCommentInteraction(postId, comment.id, 'heart')} className="flex items-center gap-1 text-[9px] font-black uppercase text-custom transition-transform active:scale-95"><Heart size={12} fill={comment.hearts > 0 ? "currentColor" : "none"} /> {comment.hearts} Sync</button>
            <button 
              onClick={() => setReplyingTo(replyingTo?.commentId === comment.id ? null : { postId, commentId: comment.id })} 
              className="flex items-center gap-1 text-[9px] font-black uppercase text-blue-500 transition-transform active:scale-95"
            >
              <Reply size={12} /> Echo
            </button>
          </div>

          <AnimatePresence>
            {replyingTo?.commentId === comment.id && (
              <motion.div initial={{ height: 0, opacity: 0 }} animate={{ height: 'auto', opacity: 1 }} exit={{ height: 0, opacity: 0 }} className="mt-3 overflow-hidden">
                <div className="flex gap-2">
                  <input 
                    autoFocus
                    type="text" 
                    value={replyContent} 
                    onChange={e => setReplyContent(e.target.value)}
                    placeholder="Echo back..."
                    className={`flex-1 p-2 rounded-xl border-2 text-[10px] font-bold outline-none focus:border-custom ${isDarkMode ? 'bg-slate-800 border-slate-700 text-white' : 'bg-gray-50 border-gray-100'}`}
                    onKeyPress={e => e.key === 'Enter' && handleReply(postId, comment.id)}
                  />
                  <button onClick={() => handleReply(postId, comment.id)} className="bg-custom text-white px-3 rounded-xl shadow-md transition-transform active:scale-95"><Send size={12} /></button>
                </div>
              </motion.div>
            )}
          </AnimatePresence>
        </div>
      </div>
      {comment.replies && comment.replies.map(reply => renderComment(postId, reply, depth + 1))}
    </div>
  );

  const handleTeller = () => {
    if (!tellerQuestion.trim()) return;
    setIsTellerLoading(true);
    setTimeout(() => {
      const rand = Math.random();
      let result = '';
      if (rand < 0.2) result = 'YES. The stars have spoken!';
      else if (rand < 0.4) result = 'NO. The frequency is blocked.';
      else if (rand < 0.6) result = 'MAYBE. The vibes are still charging.';
      else if (rand < 0.8) result = 'SUPER YES! The universe is screaming it!';
      else result = 'SUPER NO! Not in this city, or any other.';
      setTellerResponse(result);
      setIsTellerLoading(false);
    }, 1200);
  };

  const startQuiz = () => {
    setQuizActive(true);
    setQuizStep(0);
    setQuizScores({ Happy: 0, Angry: 0, Tired: 0, Normal: 0, Excited: 0 });
    setQuizResult(null);
  };

  const QUIZ_STEPS = [
    { q: "How happy do you feel right now?", options: ["Very!", "A little", "Not much", "Not at all"], scores: ["Happy", "Normal", "Tired", "Angry"] },
    { q: "Are you feeling sleepy?", options: ["No, I'm awake!", "A tiny bit", "I need a nap", "I'm a zombie"], scores: ["Excited", "Normal", "Tired", "Tired"] },
    { q: "Are you mad at anyone?", options: ["No, I'm chill", "Just a bit", "Maybe one person", "I'm so angry!"], scores: ["Happy", "Normal", "Angry", "Angry"] },
    { q: "Do you feel excited about today?", options: ["Yes, so much!", "Maybe a bit", "Not really", "Zero excitement"], scores: ["Excited", "Excited", "Normal", "Tired"] },
    { q: "How fast is your brain working?", options: ["Super fast!", "Normal speed", "A bit slow", "It's stuck"], scores: ["Excited", "Normal", "Tired", "Normal"] },
    { q: "Do you want to hug a pet?", options: ["Yes, please!", "Sure", "Not really", "No way"], scores: ["Happy", "Happy", "Normal", "Angry"] },
    { q: "How much do you like today?", options: ["I love it!", "It's okay", "It's boring", "I hate it"], scores: ["Happy", "Normal", "Tired", "Angry"] },
    { q: "Are you busy right now?", options: ["Very busy!", "A little bit", "Not at all", "I'm bored"], scores: ["Excited", "Normal", "Happy", "Tired"] },
    { q: "Do you feel like dancing?", options: ["Yes, right now!", "Maybe later", "No, too tired", "Not my vibe"], scores: ["Excited", "Happy", "Tired", "Normal"] },
    { q: "Pick your favorite color!", options: ["Yellow", "Blue", "Red", "Green"], scores: ["Happy", "Tired", "Angry", "Normal"] }
  ];

  const handleQuizChoice = (idx: number) => {
    const currentStep = QUIZ_STEPS[quizStep];
    const moodKey = currentStep.scores[idx];
    const updatedScores = { ...quizScores };
    if (moodKey) {
      updatedScores[moodKey] = (updatedScores[moodKey] || 0) + 1;
      setQuizScores(updatedScores);
    }
    const nextStep = quizStep + 1;
    if (nextStep < QUIZ_STEPS.length) {
      setQuizStep(nextStep);
    } else {
      const sortedEntries = Object.entries(updatedScores).sort((a, b) => (b[1] as number) - (a[1] as number));
      setQuizResult(sortedEntries[0][0]);
    }
  };

  const formatTime = (ts: number) => {
    const diff = Date.now() - ts;
    if (diff < 60000) return 'Just now';
    if (diff < 3600000) return `${Math.floor(diff / 60000)}m ago`;
    return new Date(ts).toLocaleDateString();
  };

  return (
    <div className="flex flex-col gap-6 pb-20 h-full min-h-0">
      <div className="flex gap-2 overflow-x-auto no-scrollbar pb-2 shrink-0">
        {['Express', 'Teller', 'Scan', 'Mood Pet'].map((t) => (
          <button key={t} onClick={() => setSubTab(t as any)} className={`px-5 py-2.5 rounded-full font-black text-[10px] md:text-xs transition-all whitespace-nowrap uppercase tracking-tighter border-b-4 ${subTab === t ? 'bg-custom border-black/20 text-white shadow-lg translate-y-[-2px]' : isDarkMode ? 'bg-slate-800 border-slate-900 text-white/30' : 'bg-white border-gray-100 text-slate-500'}`}>
            {t}
          </button>
        ))}
      </div>

      <div className="flex-1 min-h-0 relative">
        <AnimatePresence mode="wait">
          {subTab === 'Express' && (
            <motion.div key="express" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="h-full overflow-y-auto fading-scrollbar pr-2 space-y-6 pb-20">
              <div className={`p-6 md:p-8 rounded-[2.5rem] ${isDarkMode ? 'bg-slate-900' : 'bg-white'} border-4 border-black/5 shadow-xl`}>
                <textarea 
                  value={postContent} 
                  onChange={(e) => setPostContent(e.target.value)} 
                  disabled={isBroadcasting}
                  placeholder={isBroadcasting ? "Sending Signal..." : (postVisibility === 'global' ? "Transmit a global frequency..." : "Whisper to your circle...")} 
                  className={`w-full ${isDarkMode ? 'bg-slate-800 text-white' : 'bg-gray-50 text-slate-900'} p-6 rounded-3xl border-2 border-black/5 focus:border-custom outline-none font-bold text-lg shadow-inner min-h-[120px]`} 
                />
                <div className="flex flex-wrap justify-between items-center mt-6 gap-4">
                  <div className="flex gap-2 bg-black/5 p-1.5 rounded-2xl">
                    <button onClick={() => setPostVisibility('global')} className={`flex items-center gap-2 px-4 py-2 rounded-xl text-[10px] font-black uppercase transition-all ${postVisibility === 'global' ? 'bg-custom text-white' : 'opacity-40'}`}><Globe size={14}/> GLOBAL</button>
                    <button onClick={() => setPostVisibility('circle')} className={`flex items-center gap-2 px-4 py-2 rounded-xl text-[10px] font-black uppercase transition-all ${postVisibility === 'circle' ? 'bg-custom text-white' : 'opacity-40'}`}><Users size={14}/> CIRCLE</button>
                  </div>
                  <button 
                    onClick={handlePost} 
                    disabled={isBroadcasting}
                    className="kahoot-button-custom px-8 py-4 text-white rounded-2xl font-black text-xs flex items-center gap-2 active:scale-95 transition-transform disabled:opacity-50"
                  >
                    {isBroadcasting ? <Clock size={18} className="animate-spin" /> : <Send size={18} />} 
                    {isBroadcasting ? 'SENDING...' : 'BROADCAST'}
                  </button>
                </div>
              </div>

              <div className="flex gap-2 bg-black/5 p-1 rounded-xl w-fit">
                <button onClick={() => setFeedFilter('Global')} className={`px-4 py-2 rounded-lg text-[9px] font-black uppercase ${feedFilter === 'Global' ? 'bg-white text-custom shadow-sm' : 'opacity-40'}`}>Metropolis Feed</button>
                <button onClick={() => setFeedFilter('Circle')} className={`px-4 py-2 rounded-lg text-[9px] font-black uppercase ${feedFilter === 'Circle' ? 'bg-white text-custom shadow-sm' : 'opacity-40'}`}>Neural Circle</button>
              </div>

              <div className="space-y-6 pb-12">
                {filteredPosts.length > 0 ? filteredPosts.map(post => {
                  const isAuthor = post.author === user.username;
                  const isLiked = post.likes.includes(user.username);

                  return (
                    <motion.div key={post.id} initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} className={`p-6 rounded-[2rem] ${isDarkMode ? 'bg-slate-900 text-white' : 'bg-white text-slate-900'} border-2 border-black/5 shadow-md`}>
                      <div className="flex items-center justify-between mb-4">
                        <div className="flex items-center gap-3">
                          <button onClick={() => onNavigateToProfile(post.author)} className="w-10 h-10 rounded-xl bg-custom text-white font-black shrink-0 text-xl flex items-center justify-center italic shadow-sm active:scale-95 transition-transform">{post.author[0].toUpperCase()}</button>
                          <div>
                            <button onClick={() => onNavigateToProfile(post.author)} className="font-black text-sm hover:text-custom transition-colors">@{post.author}</button>
                            <p className="text-[9px] font-black opacity-30 uppercase tracking-widest flex items-center gap-1"><Clock size={10}/> {formatTime(post.timestamp)}</p>
                          </div>
                        </div>
                        {isAuthor && (
                          <div className="flex gap-2">
                             <button onClick={() => handleStartEdit(post)} className="p-2 bg-black/5 hover:bg-black/10 rounded-xl transition-all text-blue-500"><Edit size={16}/></button>
                             <button onClick={() => onDeletePost(post.id)} className="p-2 bg-black/5 hover:bg-black/10 rounded-xl transition-all text-red-500"><Trash2 size={16}/></button>
                          </div>
                        )}
                      </div>

                      {editingPostId === post.id ? (
                        <div className="space-y-4 mb-6">
                           <textarea value={editBuffer} onChange={e => setEditBuffer(e.target.value)} className={`w-full p-4 rounded-2xl border-2 font-bold ${isDarkMode ? 'bg-slate-800 border-slate-700 text-white' : 'bg-gray-50 border-gray-100 text-slate-900'} outline-none focus:border-custom`} rows={3} />
                           <div className="flex gap-2">
                             <button onClick={handleSaveEdit} className="bg-custom text-white px-4 py-2 rounded-xl font-black text-[10px] uppercase shadow-md">Update Signal</button>
                             <button onClick={() => setEditingPostId(null)} className="bg-black/5 px-4 py-2 rounded-xl font-black text-[10px] uppercase">Cancel</button>
                           </div>
                        </div>
                      ) : (
                        <>
                          {post.isRepost && <div className="flex items-center gap-2 text-[10px] font-black text-green-500 uppercase italic mb-2"><Repeat size={12}/> Echoing: @{post.originalAuthor}</div>}
                          <p className="text-base font-bold italic opacity-90 mb-6 leading-relaxed break-words">"{post.content}"</p>
                        </>
                      )}

                      <div className="flex items-center gap-6 pt-4 border-t border-black/5">
                        <div className="flex items-center gap-1.5">
                           <button onClick={() => onHeart(post.id)} className={`flex items-center gap-1.5 ${isLiked ? 'text-custom' : 'opacity-40'} font-black text-[10px] uppercase transition-all active:scale-95`}>
                             <Heart size={16} fill={isLiked ? "currentColor" : "none"} />
                           </button>
                           <button onClick={() => setLikersModalPost(post)} className="text-custom font-black text-[10px] hover:underline transition-all">
                             {post.likes.length} SYNC
                           </button>
                        </div>
                        <button onClick={() => setExpandedPostId(expandedPostId === post.id ? null : post.id)} className="flex items-center gap-1.5 text-blue-500 font-black text-[10px] uppercase"><MessageSquare size={16} /> {post.comments?.length || 0} ECHO</button>
                        <button onClick={() => onRepost(post)} className="flex items-center gap-1.5 text-green-500 font-black text-[10px] uppercase transition-transform active:scale-95"><Repeat size={16} /> ECHO RE-SIGNAL</button>
                      </div>

                      <AnimatePresence>
                        {expandedPostId === post.id && (
                          <motion.div initial={{ height: 0, opacity: 0 }} animate={{ height: 'auto', opacity: 1 }} exit={{ height: 0, opacity: 0 }} className="overflow-hidden">
                             <div className="pt-6 space-y-4">
                                <div className="flex gap-2">
                                  <input 
                                    type="text" 
                                    value={commentInputs[post.id] || ''} 
                                    onChange={e => setCommentInputs(prev => ({ ...prev, [post.id]: e.target.value }))}
                                    placeholder="Add an echo to this signal..." 
                                    className={`flex-1 p-3 rounded-xl border-2 text-xs font-bold outline-none focus:border-custom ${isDarkMode ? 'bg-slate-800 border-slate-700 text-white' : 'bg-gray-50 border-gray-100'}`}
                                    onKeyPress={e => e.key === 'Enter' && handleAddComment(post.id)}
                                  />
                                  <button onClick={() => handleAddComment(post.id)} className="bg-custom text-white px-4 rounded-xl shadow-md transition-transform active:scale-95"><Send size={16} /></button>
                                </div>

                                <div className="space-y-4 max-h-[400px] overflow-y-auto fading-scrollbar pr-2">
                                  {post.comments?.length > 0 ? (
                                    post.comments.map(c => renderComment(post.id, c))
                                  ) : (
                                    <p className="text-[10px] font-black uppercase opacity-20 text-center py-4 tracking-widest">No echoes yet.</p>
                                  )}
                                </div>
                             </div>
                          </motion.div>
                        )}
                      </AnimatePresence>
                    </motion.div>
                  );
                }) : <div className="py-20 text-center opacity-20 font-black uppercase italic text-lg tracking-widest">The metropolis is quiet.</div>}
              </div>
            </motion.div>
          )}

          {subTab === 'Teller' && (
            <motion.div key="teller" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className={`h-full overflow-y-auto fading-scrollbar pr-2 p-10 rounded-[3rem] ${isDarkMode ? 'bg-slate-900' : 'bg-white'} border-4 border-black/5 shadow-xl text-center flex flex-col items-center pb-20`}>
               <Sparkles className="mb-6 text-custom shrink-0" size={60} />
               <h2 className="text-2xl md:text-4xl font-black mb-8 uppercase italic tracking-tighter shrink-0">Fortune Oracle</h2>
               <input value={tellerQuestion} onChange={e => setTellerQuestion(e.target.value)} placeholder="Type a question for the stars..." className={`w-full max-w-xl p-5 rounded-2xl border-2 font-black text-center mb-6 outline-none focus:border-custom shadow-inner shrink-0 ${isDarkMode ? 'bg-slate-800 border-slate-700 text-white' : 'bg-gray-50 border-gray-100'}`} />
               <button onClick={handleTeller} disabled={isTellerLoading} className="kahoot-button-custom px-10 py-5 rounded-2xl text-white font-black uppercase text-sm shadow-lg active:scale-95 transition-transform shrink-0">{isTellerLoading ? 'CALCULATING...' : 'ASK THE STARS'}</button>
               {tellerResponse && (
                 <motion.div initial={{ y: 10, opacity: 0 }} animate={{ y: 0, opacity: 1 }} className="mt-8 p-6 rounded-3xl bg-custom/5 border-l-8 border-custom italic font-bold text-lg max-w-lg">
                   "{tellerResponse}"
                 </motion.div>
               )}
            </motion.div>
          )}

          {subTab === 'Scan' && (
            <motion.div key="scan" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className={`h-full overflow-y-auto fading-scrollbar pr-2 p-10 rounded-[3rem] ${isDarkMode ? 'bg-slate-900' : 'bg-white'} border-4 border-black/5 shadow-xl text-center flex flex-col items-center pb-20`}>
               <Brain className="mb-6 text-blue-500 shrink-0" size={60} />
               <h2 className="text-2xl md:text-4xl font-black mb-6 uppercase italic tracking-tighter shrink-0">Emotional Scan</h2>
               {!quizActive ? (
                 <>
                   <p className="opacity-40 font-bold uppercase tracking-widest text-[10px] mb-10">See your mood signature in 10 quick steps</p>
                   <button onClick={startQuiz} className="kahoot-button-blue px-10 py-5 rounded-2xl text-white font-black uppercase text-sm shadow-lg shrink-0">Start Scan</button>
                 </>
               ) : (
                 <div className="w-full max-w-lg space-y-8">
                   {quizResult ? (
                     <div className="space-y-6">
                        <div className="text-6xl mb-4">✨</div>
                        <h3 className="text-2xl font-black italic uppercase">Scan Complete</h3>
                        <div className="p-6 rounded-3xl bg-custom/10 border-2 border-custom/20">
                          <p className="text-[10px] font-bold opacity-70 uppercase tracking-widest mb-2">Neural Signature</p>
                          <p className="text-2xl font-black text-custom italic uppercase">{quizResult}</p>
                        </div>
                        <button onClick={() => setQuizActive(false)} className="kahoot-button-custom px-8 py-3 rounded-xl text-white font-black uppercase text-xs">Reset Scan</button>
                     </div>
                   ) : (
                     <div className="space-y-8">
                        <div className="h-2 bg-black/10 rounded-full overflow-hidden shrink-0"><motion.div className="h-full bg-blue-500" initial={{ width: 0 }} animate={{ width: `${((quizStep + 1) / QUIZ_STEPS.length) * 100}%` }} /></div>
                        <p className="text-lg font-black italic">"{QUIZ_STEPS[quizStep].q}"</p>
                        <div className="grid grid-cols-2 gap-4">
                           {QUIZ_STEPS[quizStep].options.map((opt, i) => (
                             <button key={opt} onClick={() => handleQuizChoice(i)} className="kahoot-button-custom py-4 rounded-xl text-white font-black uppercase text-[10px] active:scale-95 transition-transform">{opt}</button>
                           ))}
                        </div>
                        <p className="text-[10px] font-black uppercase opacity-30">Step {quizStep + 1} of {QUIZ_STEPS.length}</p>
                     </div>
                   )}
                 </div>
               )}
            </motion.div>
          )}

          {subTab === 'Mood Pet' && (
            <motion.div key="pet" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="h-full overflow-y-auto fading-scrollbar pr-2 pb-20">
               <MoodPetSection user={user} isDarkMode={isDarkMode} onUpdate={onUpdatePet} onPost={onPost} />
            </motion.div>
          )}
        </AnimatePresence>
      </div>

      {/* Likers Modal */}
      <AnimatePresence>
        {likersModalPost && (
          <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-black/80 backdrop-blur-md">
             <motion.div initial={{ scale: 0.9, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} className={`w-full max-w-sm rounded-[3rem] p-8 ${isDarkMode ? 'bg-slate-900' : 'bg-white'} border-4 border-black/5 shadow-2xl relative`}>
                <button onClick={() => setLikersModalPost(null)} className="absolute top-6 right-6 opacity-40 hover:opacity-100 transition-all"><X size={24}/></button>
                <h3 className="text-xl font-black uppercase italic mb-6">Resonance Syncs</h3>
                <div className="space-y-3 max-h-[300px] overflow-y-auto fading-scrollbar">
                   {likersModalPost.likes.length > 0 ? likersModalPost.likes.map(liker => (
                     <button key={liker} onClick={() => { onNavigateToProfile(liker); setLikersModalPost(null); }} className={`w-full p-3 rounded-2xl flex items-center gap-3 transition-all hover:bg-black/5`}>
                       <div className="w-8 h-8 rounded-lg bg-custom text-white font-black flex items-center justify-center italic text-xs border-2 border-white/20 shrink-0">{liker[0].toUpperCase()}</div>
                       <p className="text-[12px] font-black uppercase flex-1 text-left">@{liker}</p>
                     </button>
                   )) : <p className="text-xs font-bold opacity-30 uppercase text-center py-4">No one liked yet.</p>}
                </div>
             </motion.div>
          </div>
        )}
      </AnimatePresence>
    </div>
  );
};

export default MoodSection;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Send, Users, Search, MessageSquare, ArrowLeft, ShieldCheck, Check, CheckCheck, Clock, Smile, Plus, X, Reply, Radio, Rocket, MessageCircle, Star, Ghost, Zap, Coffee, Music, Palette } from 'lucide-react';
import { User, Message, MessageReaction, Group } from '../types';

interface CityHallSectionProps {
  isDarkMode: boolean;
  currentUser: User;
  allUsers: User[];
  messages: Message[];
  groups: Group[];
  onSendMessage: (recipient: string, text: string, options?: { isGroup?: boolean, recipients?: string[], groupName?: string, replyToId?: string, replyToText?: string, replyToSender?: string, isSystem?: boolean, liaisonData?: any }) => void;
  onReadMessages: (withUsername: string) => void;
  onGroupUpdate: (group: Group) => void;
  onGroupCreate: (group: Group) => void;
  onNavigateToProfile: (username: string) => void;
  onReactToMessage: (msgId: string, emoji: string) => void;
  onViolation: (reason: string) => void;
}

const GROUP_ICONS = ['🚀', '💬', '✨', '👻', '⚡', '☕', '🎵', '🎨', '🔥', '🌈', '🛸', '🛡️'];

const CityHallSection: React.FC<CityHallSectionProps> = ({ isDarkMode, currentUser, allUsers, messages, groups, onSendMessage, onReadMessages, onGroupUpdate, onGroupCreate, onNavigateToProfile, onReactToMessage, onViolation }) => {
  const [input, setInput] = useState('');
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedCitizen, setSelectedCitizen] = useState<{ username: string, isGroup?: boolean } | null>(null);
  const [isSending, setIsSending] = useState(false);

  // Group creation state
  const [isCreatingGroup, setIsCreatingGroup] = useState(false);
  const [groupName, setGroupName] = useState('');
  const [selectedGroupIcon, setSelectedGroupIcon] = useState('🚀');
  const [selectedForGroup, setSelectedForGroup] = useState<string[]>([]);
  const [userSearchTerm, setUserSearchTerm] = useState('');

  const chatScrollRef = useRef<HTMLDivElement>(null);

  const getUserByUsername = (username: string) => allUsers.find(u => u.username === username);
  const getGroupById = (id: string) => groups.find(g => g.id === id);

  const chats = useMemo(() => {
    const list: any[] = [];
    const processedDms = new Set<string>();

    groups.forEach(g => {
      if (g.members.includes(currentUser.username)) {
        list.push({ username: g.id, displayName: g.name, isGroup: true, profilePic: g.photo || '🚀' });
      }
    });

    messages.forEach(m => {
      if (!m.isGroup) {
        const other = m.sender === currentUser.username ? m.recipient : m.sender;
        if (!processedDms.has(other)) {
          processedDms.add(other);
          const userObj = getUserByUsername(other);
          if (userObj) {
            list.push({ username: other, displayName: userObj.displayName, profilePic: userObj.profilePic, isGroup: false });
          }
        }
      }
    });
    return list;
  }, [messages, allUsers, currentUser.username, groups]);

  const activeChatInfo = useMemo(() => {
    if (!selectedCitizen) return null;
    if (selectedCitizen.isGroup) {
      const g = getGroupById(selectedCitizen.username);
      return { username: selectedCitizen.username, displayName: g?.name || 'Group', profilePic: g?.photo || '🚀', isGroup: true, recipients: g?.members };
    } else {
      const u = getUserByUsername(selectedCitizen.username);
      return { username: selectedCitizen.username, displayName: u?.displayName || selectedCitizen.username, profilePic: u?.profilePic, isGroup: false };
    }
  }, [selectedCitizen, allUsers, groups]);

  const chatMessages = useMemo(() => {
    if (!selectedCitizen) return [];
    if (selectedCitizen.isGroup) return messages.filter(m => m.isGroup && m.recipient === selectedCitizen.username).sort((a, b) => a.timestamp - b.timestamp);
    return messages.filter(m => !m.isGroup && ((m.sender === currentUser.username && m.recipient === selectedCitizen.username) || (m.sender === selectedCitizen.username && m.recipient === currentUser.username))).sort((a, b) => a.timestamp - b.timestamp);
  }, [messages, selectedCitizen, currentUser.username]);

  useEffect(() => {
    if (selectedCitizen && !selectedCitizen.isGroup) onReadMessages(selectedCitizen.username);
    setTimeout(() => { chatScrollRef.current?.scrollTo({ top: chatScrollRef.current.scrollHeight, behavior: 'smooth' }); }, 100);
  }, [selectedCitizen?.username]);

  const handleSend = async () => {
    if (!input.trim() || !activeChatInfo || isSending) return;
    setIsSending(true);
    onSendMessage(activeChatInfo.username, input, { isGroup: activeChatInfo.isGroup, recipients: activeChatInfo.recipients, groupName: activeChatInfo.displayName });
    setInput('');
    setIsSending(false);
  };

  const handleCreateGroup = () => {
    if (!groupName.trim() || selectedForGroup.length < 2) return;
    const groupId = 'group_' + Math.random().toString(36).substr(2, 9);
    const members = [...selectedForGroup, currentUser.username];
    const newGroup: Group = { id: groupId, name: groupName, owner: currentUser.username, members: members, nicknames: {}, createdAt: Date.now(), photo: selectedGroupIcon };
    onGroupCreate(newGroup);
    onSendMessage(groupId, `SYSTEM: Citizen network online. Members: ${members.join(', ')}.`, { isGroup: true, recipients: members, groupName, isSystem: true });
    setSelectedCitizen({ username: groupId, isGroup: true });
    setIsCreatingGroup(false);
    setGroupName('');
    setSelectedForGroup([]);
  };

  const filteredUsers = allUsers.filter(u => u.username !== currentUser.username && (u.username.toLowerCase().includes(userSearchTerm.toLowerCase()) || u.displayName.toLowerCase().includes(userSearchTerm.toLowerCase())));

  const isReadyToCreate = groupName.trim().length > 0 && selectedForGroup.length >= 2;

  return (
    <div className="flex flex-col h-full min-h-0 w-full relative">
      <div className="flex justify-between items-center mb-6 shrink-0 px-2">
        <h2 className={`text-3xl md:text-4xl font-black italic uppercase tracking-tighter ${isDarkMode ? 'text-white' : 'text-slate-900'}`}>Citizen Hub</h2>
        <button onClick={() => setIsCreatingGroup(true)} className="kahoot-button-blue px-6 py-3 rounded-2xl text-white font-black flex items-center gap-2 shadow-lg active:scale-95 text-xs">
          <Plus size={18} /> <span>NEW GROUP</span>
        </button>
      </div>

      <div className={`flex-1 flex flex-col md:flex-row rounded-[3rem] ${isDarkMode ? 'bg-slate-900' : 'bg-white'} shadow-2xl overflow-hidden border-4 border-black/5 relative min-h-0 h-full`}>
        {/* Sidebar */}
        <div className={`w-full md:w-64 lg:w-80 border-r ${isDarkMode ? 'border-slate-800' : 'border-gray-100'} flex flex-col ${selectedCitizen ? 'hidden md:flex' : 'flex'} min-h-0 h-full`}>
          <div className="p-4 border-b border-gray-100 dark:border-slate-800 shrink-0">
            <div className="relative">
              <input type="text" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} placeholder="Search real citizens..." className={`w-full pl-10 pr-4 py-3 rounded-2xl text-[12px] font-black border-2 outline-none focus:border-blue-500 transition-all ${isDarkMode ? 'bg-slate-800 border-slate-700' : 'bg-gray-50 border-gray-200'}`} />
              <Search className="absolute left-3.5 top-1/2 -translate-y-1/2 opacity-30" size={16} />
            </div>
          </div>
          <div className="flex-1 overflow-y-auto fading-scrollbar p-3 space-y-2 min-h-0 h-full">
            {chats.filter(c => c.displayName.toLowerCase().includes(searchTerm.toLowerCase())).map(chat => (
              <button key={chat.username} onClick={() => setSelectedCitizen({ username: chat.username, isGroup: chat.isGroup })} className={`w-full p-4 rounded-[1.5rem] flex items-center gap-3 transition-all border-b-4 active:translate-y-0.5 active:border-b-2 ${selectedCitizen?.username === chat.username ? 'bg-blue-600 border-blue-800 text-white shadow-md' : 'hover:bg-black/5'}`}>
                <div className="w-10 h-10 rounded-xl bg-blue-100 dark:bg-slate-700 flex items-center justify-center font-black overflow-hidden shadow-sm shrink-0">
                  {chat.isGroup ? <span className="text-xl">{chat.profilePic}</span> : (chat.profilePic ? <img src={chat.profilePic} className="w-full h-full object-cover" /> : chat.displayName[0])}
                </div>
                <div className="text-left flex-1 min-w-0">
                  <p className="font-black text-[12px] truncate uppercase tracking-tight">{chat.displayName}</p>
                </div>
              </button>
            ))}
          </div>
        </div>

        {/* Message Window Area */}
        <div className={`flex-1 flex flex-col min-h-0 h-full ${!selectedCitizen ? 'hidden md:flex' : 'flex'}`}>
          {activeChatInfo ? (
            <>
              <div className={`p-4 border-b ${isDarkMode ? 'bg-slate-800/50 border-slate-800' : 'bg-gray-50/50 border-gray-100'} flex items-center justify-between shrink-0`}>
                <div className="flex items-center gap-4">
                  <button onClick={() => setSelectedCitizen(null)} className="md:hidden p-2 text-custom"><ArrowLeft size={24} /></button>
                  <div className="flex items-center gap-3">
                    <div className="w-10 h-10 rounded-xl bg-blue-600 text-white flex items-center justify-center font-black shadow-lg overflow-hidden border-2 border-white/20">
                      {activeChatInfo.isGroup ? <span className="text-xl">{activeChatInfo.profilePic}</span> : (activeChatInfo.profilePic ? <img src={activeChatInfo.profilePic} className="w-full h-full object-cover" /> : activeChatInfo.displayName[0])}
                    </div>
                    <div>
                      <p className="font-black text-sm uppercase italic tracking-tighter">{activeChatInfo.displayName}</p>
                      <p className="text-[10px] font-black uppercase tracking-widest opacity-30">@{activeChatInfo.username}</p>
                    </div>
                  </div>
                </div>
              </div>

              <div ref={chatScrollRef} className="flex-1 overflow-y-auto p-4 md:p-8 space-y-6 fading-scrollbar min-h-0 h-full">
                {chatMessages.map(m => {
                  const isMe = m.sender === currentUser.username;
                  return (
                    <div key={m.id} className={`flex ${isMe ? 'flex-row-reverse' : 'flex-row'} items-end gap-3`}>
                      <div className={`max-w-[80%] flex flex-col ${isMe ? 'items-end' : 'items-start'} gap-1`}>
                        <div className={`px-5 py-3 rounded-[1.5rem] font-bold text-sm border-b-4 ${isMe ? 'bg-blue-600 border-blue-800 text-white rounded-tr-none' : 'bg-white border-gray-200 rounded-tl-none'}`}>
                          <p className="break-words max-w-md whitespace-pre-wrap">{m.text}</p>
                        </div>
                      </div>
                    </div>
                  );
                })}
              </div>

              <div className="p-4 md:p-6 shrink-0">
                <div className={`flex items-center gap-3 p-2 rounded-[2rem] border-4 transition-all ${isDarkMode ? 'bg-slate-800 border-slate-700' : 'bg-gray-50 border-gray-200'} focus-within:border-blue-500 shadow-inner`}>
                  <input type="text" value={input} onChange={(e) => setInput(e.target.value)} onKeyPress={(e) => e.key === 'Enter' && handleSend()} placeholder="Transmit message..." className="flex-1 bg-transparent px-5 py-3 font-black text-sm outline-none" />
                  <button onClick={handleSend} disabled={isSending || !input.trim()} className="kahoot-button-blue p-4 rounded-2xl text-white shadow-xl active:scale-95 disabled:opacity-50"><Send size={20} /></button>
                </div>
              </div>
            </>
          ) : (
            <div className="flex-1 flex flex-col items-center justify-center p-12 text-center opacity-20 h-full">
              <Radio size={80} className="mb-6 animate-pulse" />
              <p className="text-xs font-black uppercase tracking-widest">Select a channel to communicate</p>
            </div>
          )}
        </div>
      </div>

      {/* NEW GROUP MODAL */}
      <AnimatePresence>
        {isCreatingGroup && (
          <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 md:p-6 bg-black/90 backdrop-blur-md">
            <motion.div initial={{ scale: 0.9, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} className={`${isDarkMode ? 'bg-slate-900 border-white/10' : 'bg-white border-black/5'} w-full max-w-xl rounded-[3rem] p-6 md:p-10 border-4 shadow-2xl flex flex-col max-h-[90vh]`}>
              <div className="flex justify-between items-center mb-6"><h3 className="text-2xl font-black uppercase italic">Setup Neural Network</h3><button onClick={() => setIsCreatingGroup(false)} className="opacity-40"><X size={28}/></button></div>

              <div className="space-y-6 overflow-y-auto fading-scrollbar pr-2">
                 <div className="space-y-2">
                    <p className="text-[10px] font-black uppercase tracking-widest opacity-40 ml-2">1. Network Alias (Name)</p>
                    <input type="text" value={groupName} onChange={e => setGroupName(e.target.value)} placeholder="Designation..." className="w-full p-4 rounded-2xl border-2 bg-black/5 font-black text-lg outline-none focus:border-custom" />
                 </div>

                 <div className="space-y-2">
                    <p className="text-[10px] font-black uppercase tracking-widest opacity-40 ml-2">2. Visual ID (Icon)</p>
                    <div className="grid grid-cols-6 gap-2 p-3 bg-black/5 rounded-2xl">
                       {GROUP_ICONS.map(icon => (
                         <button key={icon} onClick={() => setSelectedGroupIcon(icon)} className={`text-2xl p-2 rounded-xl border-2 transition-all ${selectedGroupIcon === icon ? 'bg-custom/10 border-custom scale-110 shadow-sm' : 'border-transparent opacity-40'}`}>{icon}</button>
                       ))}
                    </div>
                 </div>

                 <div className="space-y-2">
                    <div className="flex justify-between items-center px-2">
                      <p className="text-[10px] font-black uppercase tracking-widest opacity-40">3. Search & Add Citizens (Min. 2)</p>
                      <span className={`text-[10px] font-black px-2 py-0.5 rounded-full ${selectedForGroup.length >= 2 ? 'bg-green-500 text-white' : 'bg-red-500 text-white'}`}>{selectedForGroup.length} Selected</span>
                    </div>
                    <div className="relative">
                      <input type="text" value={userSearchTerm} onChange={e => setUserSearchTerm(e.target.value)} placeholder="Search ID..." className="w-full pl-10 pr-4 py-3 rounded-xl border-2 bg-black/5 text-sm font-bold outline-none focus:border-custom" />
                      <Search className="absolute left-3.5 top-1/2 -translate-y-1/2 opacity-30" size={16} />
                    </div>
                    <div className="max-h-40 overflow-y-auto fading-scrollbar p-2 space-y-2 bg-black/5 rounded-2xl">
                        {filteredUsers.map(u => (
                          <button key={u.username} onClick={() => setSelectedForGroup(prev => prev.includes(u.username) ? prev.filter(x => x !== u.username) : [...prev, u.username])} className={`w-full p-3 rounded-xl flex items-center gap-3 transition-all ${selectedForGroup.includes(u.username) ? 'bg-blue-600 text-white' : 'hover:bg-black/5'}`}>
                            <div className="w-8 h-8 rounded-lg bg-custom text-white font-black flex items-center justify-center italic text-xs shrink-0 overflow-hidden">{u.profilePic ? <img src={u.profilePic} className="w-full h-full object-cover" /> : u.displayName[0]}</div>
                            <p className="text-[12px] font-black flex-1 text-left uppercase tracking-tight truncate">{u.displayName}</p>
                            {selectedForGroup.includes(u.username) && <Check size={16}/>}
                          </button>
                        ))}
                        {filteredUsers.length === 0 && <p className="text-[10px] uppercase font-black opacity-20 text-center py-4">No citizens found</p>}
                    </div>
                 </div>

                 <button onClick={handleCreateGroup} disabled={!isReadyToCreate} className="kahoot-button-blue w-full py-5 rounded-2xl text-white font-black uppercase text-sm shadow-xl active:scale-95 disabled:opacity-40 mt-4 transition-all">
                   {!groupName.trim() ? "NAME REQUIRED" : (selectedForGroup.length < 2 ? `ADD ${2 - selectedForGroup.length} MORE USERS` : "ESTABLISH LINK")}
                 </button>
              </div>
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </div>
  );
};

