            {isGuest ? 'Exit Guest Mode' : 'Terminate Cloud Link'}
          </button>
        </div>

      </div>

      <div className="text-center opacity-20 font-black italic tracking-widest text-[10px] py-12">
        METROPOLIS MULTI-PLATFORM v6.1.0
      </div>
    </div>
  );
};

export default SettingsSection;

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { User, Mood, Section, Post, Comment, Message, Notification, Group, DiaryEntry } from './types';
import Sidebar from './components/Sidebar';
import HomeSection from './sections/HomeSection';
import MoodSection from './sections/MoodSection';
import ZodiacSection from './sections/ZodiacSection';
import CityHallSection from './sections/CityHallSection';
import ProfileSection from './sections/ProfileSection';
import SettingsSection from './sections/SettingsSection';
import NotificationsSection from './sections/NotificationsSection';
import PsychiatristSection from './sections/PsychiatristSection';
import AuthScreen from './sections/AuthScreen';
import LoadingScreen from './components/LoadingScreen';
import MoodCheckIn from './components/MoodCheckIn';
import { Lock, UserPlus, WifiOff, ShieldAlert } from 'lucide-react';
import { MOOD_SCORES, getExpNeeded } from './constants';
import { supabase, isCloudEnabled, fetchGlobalFeed, syncProfile, fetchProfiles } from './services/supabaseService';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [allUsers, setAllUsers] = useState<User[]>([]);
  const [activeSection, setActiveSection] = useState<Section>('Home');
  const [viewingUsername, setViewingUsername] = useState<string | null>(null);
  const [isDarkMode, setIsDarkMode] = useState(false); 
  const [isAppStarting, setIsAppStarting] = useState(true);
  const [showMoodCheckIn, setShowMoodCheckIn] = useState(false);
  const [isOffline, setIsOffline] = useState(!navigator.onLine);

  const [allPosts, setAllPosts] = useState<Post[]>([]);
  const [allMessages, setAllMessages] = useState<Message[]>([]);
  const [allGroups, setAllGroups] = useState<Group[]>([]);
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);

  const isGuest = useMemo(() => currentUser?.email === 'guest@mooderia.local', [currentUser]);

  useEffect(() => {
    const handleOnline = () => setIsOffline(false);
    const handleOffline = () => setIsOffline(true);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  const migrateUserData = (user: User): User => {
    return {
      ...user,
      blockedUsers: user.blockedUsers || [],
      moodHistory: user.moodHistory || [],
      diaryEntries: user.diaryEntries || [],
      following: user.following || [],
      followers: user.followers || [],
      moodStreak: user.moodStreak || 0,
      petLevel: user.petLevel || 1,
      moodCoins: user.moodCoins ?? 100,
      gameCooldowns: user.gameCooldowns || {},
      petHasBeenChosen: !!user.petHasBeenChosen,
      warnings: 0, 
      isBanned: false 
    };
  };

  useEffect(() => {
    const init = async () => {
      const savedTheme = localStorage.getItem('mooderia_theme');
      if (savedTheme === 'dark') setIsDarkMode(true);

      let foundUser = false;

      if (isCloudEnabled && supabase && !isOffline) {
        try {
          const { data: { session } } = await supabase.auth.getSession();
          if (session) {
            const { data: profile } = await supabase.from('profiles').select('*').eq('id', session.user.id).single();
            if (profile) {
              setCurrentUser(migrateUserData(profile.metadata));
              foundUser = true;
            }
          }
        } catch (e) { console.info("METROPOLIS: Remote session fetch failed."); }
      }

      if (!foundUser) {
        const savedUser = localStorage.getItem('mooderia_user');
        if (savedUser) {
          setCurrentUser(migrateUserData(JSON.parse(savedUser)));
        }
      }

      try {
        const [feed, users] = await Promise.all([fetchGlobalFeed(), fetchProfiles()]);
        setAllPosts(feed as Post[]);
        setAllUsers(users);
      } catch (e) {}

      setIsLoaded(true);
      setTimeout(() => setIsAppStarting(false), 2000);
    };
    init();
  }, [isOffline]);

  useEffect(() => {
    if (isLoaded && currentUser && !showMoodCheckIn) {
      const todayStr = new Date().toDateString();
      if (currentUser.lastMoodDate !== todayStr) {
        setShowMoodCheckIn(true);
      }
    }
  }, [currentUser?.username, isLoaded]);

  useEffect(() => {
    if (!isLoaded || !currentUser) return;
    localStorage.setItem('mooderia_user', JSON.stringify(currentUser));
    if (isCloudEnabled && !isGuest && !isOffline) syncProfile(currentUser);
  }, [currentUser, isLoaded, isGuest, isOffline]);

  useEffect(() => {
    const handleAIResponse = (e: any) => {
      setAllMessages(prev => [...prev, e.detail]);
    };
    window.addEventListener('ai-response', handleAIResponse as EventListener);
    return () => window.removeEventListener('ai-response', handleAIResponse as EventListener);
  }, []);

  const handleLogout = useCallback(async () => {
    if (isCloudEnabled && supabase && !isGuest && !isOffline) {
      try {
        await supabase.auth.signOut();
      } catch (e) {}
    }
    localStorage.removeItem('mooderia_user');
    setCurrentUser(null);
  }, [isGuest, isOffline]);

  const handleUpdatePet = useCallback((
    hunger: number, 
    thirst: number, 
    rest: number, 
    coins: number, 
    exp: number = 0, 
    sleepUntil: number | null = null, 
    newEmoji?: string, 
    markChosen?: boolean, 
    newName?: string, 
    gameCooldownId?: string
  ) => {
    setCurrentUser(prev => {
      if (!prev) return null;

      const nextHunger = Math.min(100, Math.max(0, (prev.petHunger || 0) + hunger));
      const nextThirst = Math.min(100, Math.max(0, (prev.petThirst || 0) + thirst));
      const nextRest = Math.min(100, Math.max(0, (prev.petRest || 0) + rest));
      const nextCoins = Math.max(0, (prev.moodCoins || 0) + coins);
      const nextExpTotal = (prev.petExp || 0) + exp;

      let currentLevel = prev.petLevel || 1;
      let currentExp = nextExpTotal;
      while (currentExp >= getExpNeeded(currentLevel)) {
        currentExp -= getExpNeeded(currentLevel);
        currentLevel++;
      }

      const nextCooldowns = { ...prev.gameCooldowns };
      if (gameCooldownId) {
        nextCooldowns[gameCooldownId] = Date.now() + 60000; 
      }

      return {
        ...prev,
        petHunger: nextHunger,
        petThirst: nextThirst,
        petRest: nextRest,
        moodCoins: nextCoins,
        petExp: currentExp,
        petLevel: currentLevel,
        petSleepUntil: sleepUntil === null ? prev.petSleepUntil : sleepUntil,
        petEmoji: newEmoji || prev.petEmoji,
        petHasBeenChosen: markChosen !== undefined ? markChosen : prev.petHasBeenChosen,
        petName: newName || prev.petName,
        gameCooldowns: nextCooldowns,
        petLastUpdate: Date.now()
      };
    });
  }, []);

  const handleMoodSubmit = (mood: Mood) => {
    if (!currentUser) return;
    const today = new Date();
    const todayStr = today.toDateString();

    let newStreak = 1;
    if (currentUser.lastMoodDate) {
      const lastDate = new Date(currentUser.lastMoodDate);
      const diffTime = Math.abs(today.getTime() - lastDate.getTime());
      const diffDays = Math.floor(diffTime / (1000 * 60 * 60 * 24));

      if (diffDays === 1) {
        newStreak = (currentUser.moodStreak || 0) + 1;
      } else if (diffDays === 0) {
        newStreak = currentUser.moodStreak || 1;
      } else {
        newStreak = 1; 
      }
    }

    const moodScore = mood ? MOOD_SCORES[mood] : 50;
    const newHistory = [...(currentUser.moodHistory || []), { date: todayStr, mood, score: moodScore }];

    setCurrentUser({
      ...currentUser,
      moodHistory: newHistory,
      moodStreak: newStreak,
      lastMoodDate: todayStr,
      moodCoins: (currentUser.moodCoins || 0) + 25, 
      petExp: (currentUser.petExp || 0) + 50
    });

    setShowMoodCheckIn(false);
  };

  const handleSendMessage = async (recipient: string, text: string, options?: any) => {
    if (!currentUser || isGuest || isOffline) return;
    const newMessageData: any = {
      sender: currentUser.username,
      recipient,
      text,
      is_group: options?.isGroup || false,
      timestamp: Date.now(),
      id: Math.random().toString(36).substr(2, 9),
      read: false
    };

    setAllMessages(prev => [...prev, newMessageData]);

    if (isCloudEnabled && supabase) {
      try { await supabase.from('messages').insert({
        sender: currentUser.username,
        recipient,
        text,
        is_group: options?.isGroup || false
      }); } catch (e) {}
    }
  };

  const handlePost = async (content: string, visibility: 'global' | 'circle') => {
    if (!currentUser || isGuest || isOffline) return;
    const newPost: Post = { 
      id: Math.random().toString(36).substr(2, 9),
      author: currentUser.username, 
      content, 
      visibility, 
      likes: [], 
      comments: [], 
      timestamp: Date.now() 
    };

    setAllPosts(prev => [newPost, ...prev]);

    if (isCloudEnabled && supabase) {
      try { 
        await supabase.from('posts').insert({
          author_username: currentUser.username,
          content,
          visibility,
          likes: []
        }); 
      } catch (e) {}
    }
  };

  const handleAddDiaryEntry = (entry: DiaryEntry) => {
    setCurrentUser(prev => {
      if (!prev) return null;
      return {
        ...prev,
        diaryEntries: [entry, ...(prev.diaryEntries || [])]
      };
    });
  };

  const handleHeart = (postId: string) => {
    if (!currentUser || isGuest || isOffline) return;
    setAllPosts(prev => prev.map(p => {
      if (p.id === postId) {
        const isLiked = p.likes?.includes(currentUser.username);
        const nextLikes = isLiked ? p.likes.filter(u => u !== currentUser.username) : [...(p.likes || []), currentUser.username];
        return { ...p, likes: nextLikes };
      }
      return p;
    }));
  };

  if (isAppStarting) return <LoadingScreen />;
  if (!currentUser) return <AuthScreen onLogin={(u) => { setCurrentUser(u); setViewingUsername(u.username); }} isOffline={isOffline} />;

  const isFixedSection = activeSection === 'CityHall' || activeSection === 'Mood' || activeSection === 'Psychiatrist';
  const isLockedForGuest = isGuest && (activeSection === 'CityHall' || activeSection === 'Notifications' || activeSection === 'Profile');
  const isLockedForOffline = isOffline && (activeSection === 'CityHall');

  return (
    <div style={{'--theme-color': currentUser.profileColor || '#e21b3c'} as React.CSSProperties} className={`h-screen max-h-screen overflow-hidden flex flex-col md:flex-row ${isDarkMode ? 'bg-[#0f0f0f] text-white' : 'bg-[#f7f8fa] text-slate-900'} transition-colors duration-300`}>
      <style>{`
        :root { --theme-color: ${currentUser.profileColor || '#e21b3c'}; }
        .kahoot-shadow { box-shadow: 0 4px 0 0 rgba(0,0,0,0.2); }
        .bg-custom { background-color: var(--theme-color); }
        .text-custom { color: var(--theme-color); }
      `}</style>

      <AnimatePresence>
        {showMoodCheckIn && <MoodCheckIn isDarkMode={isDarkMode} onSubmit={handleMoodSubmit} />}
      </AnimatePresence>

      <Sidebar 
        activeSection={activeSection} 
        onNavigate={(s) => { setActiveSection(s); if(s === 'Profile') setViewingUsername(currentUser!.username); }} 
        isDarkMode={isDarkMode} 
        user={currentUser!} 
        isGuest={isGuest}
        isOffline={isOffline}
        unreadMessages={allMessages.filter(m => m.recipient === currentUser!.username && !m.read).length} 
        unreadNotifications={notifications.filter(n => n.recipient === currentUser!.username && !n.read).length} 
      />

      <main className="flex-1 flex flex-col min-h-0 relative pt-14 pb-16 md:pt-0 md:pb-0 h-full overflow-hidden">
        {isOffline && (
          <div className="absolute top-14 md:top-0 left-0 right-0 z-50 bg-red-600 text-white py-1.5 px-4 flex items-center justify-center gap-2 text-[10px] font-black uppercase tracking-widest shadow-md">
            <WifiOff size={14} /> METROPOLIS OFFLINE: Social Link Severed
          </div>
        )}

        <div className={`flex-1 flex flex-col min-h-0 ${isFixedSection ? 'overflow-hidden' : 'overflow-y-auto fading-scrollbar'} p-4 md:p-8`}>
          <motion.div 
            key={activeSection + (activeSection === 'Profile' ? viewingUsername : '')} 
            initial={{ opacity: 0, y: 10 }} 
            animate={{ opacity: 1, y: 0 }} 
            className="max-w-6xl mx-auto w-full flex-1 flex flex-col min-h-0 h-full relative"
          >
            {isLockedForGuest || isLockedForOffline ? (
              <div className="flex-1 flex flex-col items-center justify-center text-center p-12">
                <motion.div 
                  initial={{ scale: 0.8 }} 
                  animate={{ scale: 1 }} 
                  className={`p-8 rounded-[3rem] shadow-2xl border-b-8 ${isLockedForOffline ? 'bg-red-600 border-red-900 text-white' : 'bg-red-500 text-white border-red-800'}`}
                >
                  {isLockedForOffline ? <WifiOff size={80} className="mx-auto mb-6" /> : <Lock size={80} className="mx-auto mb-6" />}
                  <h2 className="text-3xl font-black uppercase italic tracking-tighter mb-4">
                    {isLockedForOffline ? 'Uplink Severed' : 'Metropolis Lockdown'}
                  </h2>
                  <p className="text-sm font-bold opacity-90 leading-relaxed uppercase tracking-widest max-w-sm mx-auto">
                    {isLockedForOffline 
                      ? 'Global communication requires a live neural link. Restore connection to access the Citizen Hub.'
                      : 'You must register an email account to be a permanent mooderia citizen.'}
                  </p>
                  {!isLockedForOffline && (
                    <button onClick={() => handleLogout()} className="mt-8 px-10 py-5 bg-white text-red-600 rounded-2xl font-black uppercase text-sm shadow-xl active:scale-95 transition-all flex items-center justify-center gap-3 mx-auto">
                      <UserPlus size={20} /> SIGN UP
                    </button>
                  )}
                  {isLockedForOffline && (
                    <div className="mt-8 px-6 py-3 bg-black/20 rounded-xl font-black text-[10px] uppercase tracking-[0.2em]">
                       Waiting for signal...
                    </div>
                  )}
                </motion.div>
              </div>
            ) : (
              <>
                {activeSection === 'Home' && (
                  <HomeSection 
                    user={currentUser!} 
                    posts={allPosts} 
                    isDarkMode={isDarkMode} 
                    onTriggerMood={() => setShowMoodCheckIn(true)} 
                  />
                )}
                {activeSection === 'CityHall' && (
                  <CityHallSection 
                    isDarkMode={isDarkMode} currentUser={currentUser!} allUsers={allUsers}
                    messages={allMessages} groups={allGroups} onSendMessage={handleSendMessage} 
                    isOffline={isOffline}
                    onGroupUpdate={(g) => setAllGroups(prev => prev.map(old => old.id === g.id ? g : old))}
                    onGroupCreate={(g) => setAllGroups(prev => [...prev, g])}
                    onReadMessages={(u) => setAllMessages(prev => prev.map(m => (m.recipient === currentUser!.username && m.sender === u) ? {...m, read: true} : m))} 
                    onNavigateToProfile={(u) => {setViewingUsername(u); setActiveSection('Profile');}} 
                    onReactToMessage={() => {}} 
                    onViolation={() => {}}
                  />
                )}
                {activeSection === 'Psychiatrist' && (
                  <PsychiatristSection 
                    currentUser={currentUser!} 
                    isDarkMode={isDarkMode} 
                    messages={allMessages} 
                    onSendMessage={(text) => handleSendMessage('DrPinel', text)} 
                  />
                )}
                {activeSection === 'Mood' && (
                  <MoodSection 
                    isGuest={isGuest} 
                    user={currentUser!} 
                    posts={allPosts} 
                    onPost={handlePost} 
                    onHeart={handleHeart} 
                    isOffline={isOffline}
                    onAddDiaryEntry={handleAddDiaryEntry}
                    onDeletePost={(id) => setAllPosts(prev => prev.filter(p => p.id !== id))} 
                    onEditPost={(id, content) => setAllPosts(prev => prev.map(p => p.id === id ? {...p, content} : p))} 
                    onComment={() => {}} 
                    onCommentInteraction={() => {}} 
                    onRepost={() => {}} 
                    onFollow={() => {}} 
                    onBlock={() => {}} 
                    isDarkMode={isDarkMode} 
                    onNavigateToProfile={() => {}} 
                    onUpdatePet={handleUpdatePet} 
                    onViolation={() => {}} 
                  />
                )}
                {activeSection === 'Zodiac' && <ZodiacSection isDarkMode={isDarkMode} />}
                {activeSection === 'Notifications' && <NotificationsSection notifications={notifications.filter(n => n.recipient === currentUser!.username)} isDarkMode={isDarkMode} onMarkRead={() => {}} />}
                {activeSection === 'Profile' && currentUser && <ProfileSection user={allUsers.find(u => u.username === viewingUsername) || currentUser} allPosts={allPosts} isDarkMode={isDarkMode} currentUser={currentUser} onEditProfile={(dn, un, pp, ti, bp, pc, bi) => { setCurrentUser({...currentUser!, displayName: dn, username: un, profilePic: pp, title: ti, profileColor: pc, bio: bi}); }} />}
                {activeSection === 'Settings' && <SettingsSection isDarkMode={isDarkMode} onToggleDarkMode={() => setIsDarkMode(!isDarkMode)} onLogout={handleLogout} user={currentUser!} onUnblock={() => {}} />}
              </>
            )}
          </motion.div>
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import { Home, Smile, Moon, Building2, User, Settings, Bell, LucideProps, Clock as ClockIcon, ChevronRight, Sparkles, Lock, WifiOff, Stethoscope } from 'lucide-react';
import { Section, User as UserType } from '../types';

interface SidebarProps {
  activeSection: Section;
  onNavigate: (section: Section) => void;
  isDarkMode: boolean;
  user: UserType;
  isGuest?: boolean;
  isOffline?: boolean;
  unreadMessages?: number;
  unreadNotifications?: number;
}

const Sidebar: React.FC<SidebarProps> = ({ activeSection, onNavigate, isDarkMode, user, isGuest = false, isOffline = false, unreadMessages = 0, unreadNotifications = 0 }) => {
  const [time, setTime] = useState(new Date());

  useEffect(() => {
    const timer = setInterval(() => setTime(new Date()), 1000);
    return () => clearInterval(timer);
  }, []);

  const items: { id: Section, icon: React.ReactElement<LucideProps>, color: string, label: string, mobileLabel: string, restricted?: boolean, offlineRestricted?: boolean }[] = [
    { id: 'Home', icon: <Home />, color: 'bg-[#46178f]', label: 'Dashboard', mobileLabel: 'Home' },
    { id: 'Zodiac', icon: <Sparkles />, color: 'bg-[#1368ce]', label: 'Cosmic Hub', mobileLabel: 'Zodiac' },
    { id: 'Mood', icon: <Smile />, color: 'bg-[#26890c]', label: 'Mood Labs', mobileLabel: 'Labs' },
    { id: 'Psychiatrist', icon: <Stethoscope />, color: 'bg-[#0ea5e9]', label: 'Therapy', mobileLabel: 'Chat' },
    { id: 'CityHall', icon: <Building2 />, color: 'bg-[#e21b3c]', label: 'Citizen Hub', mobileLabel: 'City', restricted: true, offlineRestricted: true },
    { id: 'Notifications', icon: <Bell />, color: 'bg-[#ffa602]', label: 'Alerts', mobileLabel: 'Alerts', restricted: true },
  ];

  const formattedTime = time.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: true });

  return (
    <>
      <div className={`md:hidden fixed top-0 left-0 right-0 z-[60] px-6 py-4 flex justify-between items-center ${isDarkMode ? 'bg-slate-900/95 border-slate-800' : 'bg-white/95 border-gray-100'} backdrop-blur-xl border-b shadow-sm`}>
        <h1 className="text-2xl font-black italic tracking-tighter text-[#46178f] uppercase leading-none">Mooderia</h1>
        <button onClick={() => onNavigate('Settings')} className={`p-2.5 rounded-2xl transition-all shadow-sm ${activeSection === 'Settings' ? 'bg-[#46178f] text-white' : 'text-gray-400 bg-black/5'}`}>
          <Settings size={22} />
        </button>
      </div>

      <nav className={`md:hidden fixed bottom-0 left-0 right-0 z-[60] ${isDarkMode ? 'bg-slate-900 border-slate-800' : 'bg-white border-gray-200'} border-t px-1 pb-safe shadow-[0_-10px_30px_rgba(0,0,0,0.1)]`}>
        <div className="flex justify-around items-center h-20 overflow-x-auto no-scrollbar">
          {items.map(item => {
            const isLocked = (isGuest && item.restricted) || (isOffline && item.offlineRestricted);
            return (
              <button 
                key={item.id} 
                onClick={() => onNavigate(item.id)} 
                className={`relative flex flex-col items-center justify-center transition-all flex-1 py-3 px-2 rounded-2xl ${activeSection === item.id ? 'text-[#46178f]' : 'text-gray-400 opacity-60'} ${isLocked ? 'grayscale' : ''}`}
              >
                <div className="relative">
                  {React.cloneElement(item.icon, { size: 22 })}
                  {isLocked && (
                    <div className="absolute -top-1 -right-1">
                       {isOffline && item.offlineRestricted ? <WifiOff size={10} className="text-red-600" /> : <Lock size={10} className="text-red-500" />}
                    </div>
                  )}
                  {!isGuest && !isOffline && item.id === 'CityHall' && unreadMessages > 0 && <span className="absolute -top-1.5 -right-1.5 w-4 h-4 bg-[#e21b3c] text-white text-[8px] font-black rounded-full flex items-center justify-center border-2 border-white shadow-sm">{unreadMessages}</span>}
                </div>
                <span className="text-[8px] font-black uppercase mt-1 tracking-tight">{item.mobileLabel}</span>
              </button>
            );
          })}
          <button onClick={() => onNavigate('Profile')} className={`relative flex flex-col items-center justify-center flex-1 py-3 px-2 ${activeSection === 'Profile' ? 'text-indigo-600' : 'text-gray-400 opacity-60'}`}>
             <div className="relative">
               <User size={22} />
               {isGuest && <Lock size={10} className="absolute -top-1 -right-1 text-red-500" />}
             </div>
             <span className="text-[8px] font-black uppercase mt-1 tracking-tight">Me</span>
          </button>
        </div>
      </nav>

      <aside className={`hidden md:flex flex-col w-64 lg:w-68 p-5 lg:p-6 h-screen sticky top-0 ${isDarkMode ? 'bg-slate-900 border-slate-800 text-white' : 'bg-white border-gray-100 text-slate-900'} border-r shadow-2xl z-50`}>
        <div className="mb-8">
          <h1 className="text-3xl lg:text-4xl font-black italic tracking-tighter text-[#46178f] uppercase leading-none">Mooderia</h1>
          <div className="flex items-center gap-2 mt-3 opacity-30 px-1">
            <ClockIcon size={14} /> 
            <span className="text-[10px] font-black uppercase tracking-[0.25em] tabular-nums">{formattedTime}</span>
          </div>
        </div>

        <nav className="flex-1 space-y-1.5 lg:space-y-2.5 overflow-y-auto no-scrollbar">
          {items.map(item => {
            const isLocked = (isGuest && item.restricted) || (isOffline && item.offlineRestricted);
            return (
              <button 
                key={item.id} 
                onClick={() => onNavigate(item.id)} 
                className={`w-full group relative flex items-center gap-3.5 p-3 rounded-2xl font-black text-[12px] uppercase tracking-tight transition-all border-b-4 active:translate-y-0.5 active:border-b-2 ${activeSection === item.id ? item.color + ' text-white translate-x-1 shadow-md' : 'hover:bg-black/5 opacity-70 hover:opacity-100'} ${isLocked ? 'opacity-40 grayscale pointer-events-none' : ''}`}
              >
                <span className="shrink-0">{React.cloneElement(item.icon, { size: 18 })}</span>
                <span className="flex-1 text-left">{item.label}</span>
                {isLocked && (
                  <span className="opacity-60">
                    {isOffline && item.offlineRestricted ? <WifiOff size={14} className="text-red-600" /> : <Lock size={14} />}
                  </span>
                )}
                {!isGuest && !isOffline && item.id === 'CityHall' && unreadMessages > 0 && <span className="bg-red-500 text-white text-[9px] px-2 py-0.5 rounded-full border-2 border-white shadow-lg leading-none">{unreadMessages}</span>}
                <ChevronRight size={16} className={`opacity-0 group-hover:opacity-100 transition-all ${activeSection === item.id ? 'opacity-100 translate-x-1' : ''}`} />
              </button>
            );
          })}
          <div className="h-px bg-black/5 dark:bg-white/5 my-4 mx-2" />
          <button 
            onClick={() => onNavigate('Profile')} 
            className={`w-full group relative flex items-center gap-3.5 p-3 rounded-2xl font-black text-[12px] uppercase tracking-tight transition-all border-b-4 active:translate-y-0.5 active:border-b-2 ${activeSection === 'Profile' ? 'bg-indigo-600 border-indigo-800 text-white translate-x-1 shadow-md' : 'hover:bg-black/5 opacity-70 hover:opacity-100'}`}
          >
             <span className="shrink-0"><User size={18} /></span>
             <span className="flex-1 text-left">My Profile</span>
             {isGuest && <Lock size={14} className="opacity-40" />}
             <ChevronRight size={16} className={`opacity-0 group-hover:opacity-100 transition-all ${activeSection === 'Profile' ? 'opacity-100 translate-x-1' : ''}`} />
          </button>
        </nav>

        <div className="mt-auto space-y-2">
          {isOffline && (
            <div className="flex items-center gap-2 px-4 py-2 bg-red-600/10 text-red-600 rounded-xl mb-2">
               <WifiOff size={14} />
               <span className="text-[10px] font-black uppercase">Offline</span>
            </div>
          )}
          <button onClick={() => onNavigate('Settings')} className={`w-full flex items-center gap-3.5 p-3 rounded-2xl font-black text-[12px] uppercase tracking-tight transition-all border-b-4 active:translate-y-0.5 active:border-b-2 ${activeSection === 'Settings' ? 'bg-slate-700 border-slate-900 text-white shadow-md' : 'hover:bg-black/5 opacity-70 hover:opacity-100'}`}>
            <span className="shrink-0"><Settings size={18} /></span>
            <span className="flex-1 text-left">System</span>
          </button>

          <div className={`mt-4 p-4 rounded-3xl ${isDarkMode ? 'bg-slate-800/50' : 'bg-indigo-50/50'} border-2 border-dashed border-black/5`}>
             <div className="flex items-center gap-3">
                <div className="w-9 h-9 rounded-xl bg-custom text-white font-black flex items-center justify-center italic shadow-sm overflow-hidden border-2 border-white/20">
                  {user.profilePic ? <img src={user.profilePic} alt={user.displayName} className="w-full h-full object-cover" /> : user.displayName[0]}
                </div>
                <div className="min-w-0">
                  <p className="font-black text-[10px] uppercase truncate">{user.displayName}</p>
                  <p className="text-[7px] font-black uppercase opacity-40 tracking-widest">{user.title}</p>
                </div>
             </div>
          </div>
        </div>
      </aside>
    </>
  );
};

export default Sidebar;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Heart, Send, Sparkles, Brain, Clock, Globe, Users, Trophy, MessageSquare, Repeat, Reply, ShieldAlert, Activity, Stethoscope, Trash2, Edit, X, Lock, WifiOff, Book, Plus, Calendar, Bookmark } from 'lucide-react';
import { User, Post, Comment, DiaryEntry, Mood } from '../types';
import MoodPetSection from './MoodPetSection';
import { STREAK_BADGES } from '../constants';

interface MoodSectionProps {
  user: User;
  posts: Post[];
  onPost: (content: string, visibility: 'global' | 'circle') => void;
  onHeart: (postId: string) => void;
  onDeletePost: (postId: string) => void;
  onEditPost: (postId: string, newContent: string) => void;
  onComment: (postId: string, text: string) => void;
  onCommentInteraction: (postId: string, commentId: string, action: 'heart' | 'reply', replyText?: string) => void;
  onRepost: (post: Post) => void;
  onFollow: (username: string) => void;
  onFollowUsername?: (username: string) => void; // Fixed mismatch
  onBlock: (username: string) => void;
  isDarkMode: boolean;
  onNavigateToProfile: (username: string) => void;
  onUpdatePet: (hunger: number, thirst: number, rest: number, coins: number, exp?: number, sleepUntil?: number | null, newEmoji?: string, markChosen?: boolean, newName?: string, gameCooldownId?: string) => void;
  onViolation: (reason: string) => void;
  onAddDiaryEntry: (entry: DiaryEntry) => void;
  isGuest?: boolean;
  isOffline?: boolean;
}

const MoodSection: React.FC<MoodSectionProps> = ({ user, posts, onPost, onHeart, onDeletePost, onEditPost, onComment, onCommentInteraction, onRepost, onFollow, onBlock, isDarkMode, onNavigateToProfile, onUpdatePet, onViolation, onAddDiaryEntry, isGuest = false, isOffline = false }) => {
  const [subTab, setSubTab] = useState<'Express' | 'Diary' | 'Teller' | 'Scan' | 'Mood Pet'>('Express');
  const [postContent, setPostContent] = useState('');
  const [feedFilter, setFeedFilter] = useState<'Global' | 'Circle'>('Global');
  const [postVisibility, setPostVisibility] = useState<'global' | 'circle'>('global');
  const [isBroadcasting, setIsBroadcasting] = useState(false);

  // Diary State
  const [isAddingDiary, setIsAddingDiary] = useState(false);
  const [diaryTitle, setDiaryTitle] = useState('');
  const [diaryContent, setDiaryContent] = useState('');
  const [diaryMood, setDiaryMood] = useState<Mood>('Normal');

  const [tellerQuestion, setTellerQuestion] = useState('');
  const [tellerResponse, setTellerResponse] = useState('');
  const [isTellerLoading, setIsTellerLoading] = useState(false);

  const [quizActive, setQuizActive] = useState(false);
  const [quizStep, setQuizStep] = useState(0);
  const [quizScores, setQuizScores] = useState<Record<string, number>>({ Happy: 0, Angry: 0, Tired: 0, Normal: 0, Excited: 0 });
  const [quizResult, setQuizResult] = useState<string | null>(null);

  const [expandedPostId, setExpandedPostId] = useState<string | null>(null);
  const [commentInputs, setCommentInputs] = useState<Record<string, string>>({});
  const [replyingTo, setReplyingTo] = useState<{ postId: string, commentId: string } | null>(null);
  const [replyContent, setReplyContent] = useState('');

  const [editingPostId, setEditingPostId] = useState<string | null>(null);
  const [editBuffer, setEditBuffer] = useState('');

  const [likersModalPost, setLikersModalPost] = useState<Post | null>(null);

  const filteredPosts = useMemo(() => {
    let result = posts.filter(p => !user.blockedUsers.includes(p.author));
    if (feedFilter === 'Global') return result.filter(p => p.visibility === 'global');
    return result.filter(p => p.visibility === 'circle' && (user.following.includes(p.author) || p.author === user.username));
  }, [posts, feedFilter, user.following, user.username, user.blockedUsers]);

  const handlePost = async () => {
    if (isGuest || isOffline || !postContent.trim() || isBroadcasting) return;
    setIsBroadcasting(true);
    onPost(postContent, postVisibility);
    setPostContent('');
    // Give immediate feedback
    setTimeout(() => setIsBroadcasting(true), 800);
    setTimeout(() => setIsBroadcasting(false), 1600);
  };

  const handleSaveDiary = () => {
    if (!diaryTitle.trim() || !diaryContent.trim()) return;
    const newEntry: DiaryEntry = {
      id: Math.random().toString(36).substr(2, 9),
      title: diaryTitle,
      content: diaryContent,
      mood: diaryMood,
      timestamp: Date.now()
    };
    onAddDiaryEntry(newEntry);
    setDiaryTitle('');
    setDiaryContent('');
    setIsAddingDiary(false);
  };

  const handleStartEdit = (post: Post) => {
    setEditingPostId(post.id);
    setEditBuffer(post.content);
  };

  const handleSaveEdit = async () => {
    if (!editingPostId || !editBuffer.trim()) return;
    onEditPost(editingPostId, editBuffer);
    setEditingPostId(null);
  };

  const handleAddComment = (postId: string) => {
    if (isGuest || isOffline) return;
    const text = commentInputs[postId];
    if (!text?.trim()) return;
    onComment(postId, text);
    setCommentInputs(prev => ({ ...prev, [postId]: '' }));
  };

  const handleReply = (postId: string, commentId: string) => {
    if (isGuest || isOffline || !replyContent.trim()) return;
    onCommentInteraction(postId, commentId, 'reply', replyContent);
    setReplyContent('');
    setReplyingTo(null);
  };

  const renderComment = (postId: string, comment: Comment, depth = 0) => (
    <div key={comment.id} className={`mt-4 ${depth > 0 ? 'ml-6 md:ml-10 border-l-2 border-black/5 pl-4' : ''}`}>
      <div className="flex items-start gap-3">
        <button onClick={() => onNavigateToProfile(comment.author)} className="w-8 h-8 rounded-lg bg-custom text-white font-black flex items-center justify-center shrink-0 text-sm italic active:scale-95 transition-transform">{comment.author[0].toUpperCase()}</button>
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2">
            <button onClick={() => onNavigateToProfile(comment.author)} className="font-black text-xs hover:text-custom transition-colors">@{comment.author}</button>
            <span className="text-[8px] font-black opacity-30 uppercase tracking-widest">{new Date(comment.timestamp).toLocaleDateString()}</span>
          </div>
          <p className="text-sm font-bold opacity-80 mt-1 leading-relaxed">"{comment.text}"</p>
          <div className="flex items-center gap-4 mt-2">
            <button disabled={isGuest || isOffline} onClick={() => onCommentInteraction(postId, comment.id, 'heart')} className={`flex items-center gap-1 text-[9px] font-black uppercase text-custom transition-transform active:scale-95 ${isGuest || isOffline ? 'opacity-30' : ''}`}><Heart size={12} fill={comment.hearts > 0 ? "currentColor" : "none"} /> {comment.hearts} Sync</button>
            <button 
              disabled={isGuest || isOffline}
              onClick={() => setReplyingTo(replyingTo?.commentId === comment.id ? null : { postId, commentId: comment.id })} 
              className={`flex items-center gap-1 text-[9px] font-black uppercase text-blue-500 transition-transform active:scale-95 ${isGuest || isOffline ? 'opacity-30' : ''}`}
            >
              <Reply size={12} /> Echo
            </button>
          </div>

          <AnimatePresence>
            {replyingTo?.commentId === comment.id && !isGuest && !isOffline && (
              <motion.div initial={{ height: 0, opacity: 0 }} animate={{ height: 'auto', opacity: 1 }} exit={{ height: 0, opacity: 0 }} className="mt-3 overflow-hidden">
                <div className="flex gap-2">
                  <input 
                    autoFocus
                    type="text" 
                    value={replyContent} 
                    onChange={e => setReplyContent(e.target.value)}
                    placeholder="Echo back..."
                    className={`flex-1 p-2 rounded-xl border-2 text-[10px] font-bold outline-none focus:border-custom ${isDarkMode ? 'bg-slate-800 border-slate-700 text-white' : 'bg-gray-50 border-gray-100'}`}
                    onKeyPress={e => e.key === 'Enter' && handleReply(postId, comment.id)}
                  />
                  <button onClick={() => handleReply(postId, comment.id)} className="bg-custom text-white px-3 rounded-xl shadow-md transition-transform active:scale-95"><Send size={12} /></button>
                </div>
              </motion.div>
            )}
          </AnimatePresence>
        </div>
      </div>
      {comment.replies && comment.replies.map(reply => renderComment(postId, reply, depth + 1))}
    </div>
  );

  const handleTeller = () => {
    if (!tellerQuestion.trim()) return;
    setIsTellerLoading(true);
    setTimeout(() => {
      const rand = Math.random();
      let result = '';
      if (rand < 0.2) result = 'YES. The stars have spoken!';
      else if (rand < 0.4) result = 'NO. The frequency is blocked.';
      else if (rand < 0.6) result = 'MAYBE. The vibes are still charging.';
      else if (rand < 0.8) result = 'SUPER YES! The universe is screaming it!';
      else result = 'SUPER NO! Not in this city, or any other.';
      setTellerResponse(result);
      setIsTellerLoading(false);
    }, 1200);
  };

  const startQuiz = () => {
    setQuizActive(true);
    setQuizStep(0);
    setQuizScores({ Happy: 0, Angry: 0, Tired: 0, Normal: 0, Excited: 0 });
    setQuizResult(null);
  };

  const QUIZ_STEPS = [
    { q: "How happy do you feel right now?", options: ["Very!", "A little", "Not much", "Not at all"], scores: ["Happy", "Normal", "Tired", "Angry"] },
    { q: "Are you feeling sleepy?", options: ["No, I'm awake!", "A tiny bit", "I need a nap", "I'm a zombie"], scores: ["Excited", "Normal", "Tired", "Tired"] },
    { q: "Are you mad at anyone?", options: ["No, I'm chill", "Just a bit", "Maybe one person", "I'm so angry!"], scores: ["Happy", "Normal", "Angry", "Angry"] },
    { q: "Do you feel excited about today?", options: ["Yes, so much!", "Maybe a bit", "Not really", "Zero excitement"], scores: ["Excited", "Excited", "Normal", "Tired"] },
    { q: "How fast is your brain working?", options: ["Super fast!", "Normal speed", "A bit slow", "It's stuck"], scores: ["Excited", "Normal", "Tired", "Normal"] },
    { q: "Do you want to hug a pet?", options: ["Yes, please!", "Sure", "Not really", "No way"], scores: ["Happy", "Happy", "Normal", "Angry"] },
    { q: "How much do you like today?", options: ["I love it!", "It's okay", "It's boring", "I hate it"], scores: ["Happy", "Normal", "Tired", "Angry"] },
    { q: "Are you busy right now?", options: ["Very busy!", "A little bit", "Not at all", "I'm bored"], scores: ["Excited", "Normal", "Happy", "Tired"] },
    { q: "Do you feel like dancing?", options: ["Yes, right now!", "Maybe later", "No, too tired", "Not my vibe"], scores: ["Excited", "Happy", "Tired", "Normal"] },
    { q: "Pick your favorite color!", options: ["Yellow", "Blue", "Red", "Green"], scores: ["Happy", "Tired", "Angry", "Normal"] }
  ];

  const handleQuizChoice = (idx: number) => {
    const currentStep = QUIZ_STEPS[quizStep];
    const moodKey = currentStep.scores[idx];
    const updatedScores = { ...quizScores };
    if (moodKey) {
      updatedScores[moodKey] = (updatedScores[moodKey] || 0) + 1;
      setQuizScores(updatedScores);
    }
    const nextStep = quizStep + 1;
    if (nextStep < QUIZ_STEPS.length) {
      setQuizStep(nextStep);
    } else {
      const sortedEntries = Object.entries(updatedScores).sort((a, b) => (b[1] as number) - (a[1] as number));
      setQuizResult(sortedEntries[0][0]);
    }
  };

  const formatTime = (ts: number) => {
    const diff = Date.now() - ts;
    if (diff < 60000) return 'Just now';
    if (diff < 3600000) return `${Math.floor(diff / 60000)}m ago`;
    return new Date(ts).toLocaleDateString();
  };

  const diaryEntries = user.diaryEntries || [];

  return (
    <div className="flex flex-col gap-6 pb-20 h-full min-h-0">
      <div className="flex gap-2 overflow-x-auto no-scrollbar pb-2 shrink-0">
        {['Express', 'Diary', 'Teller', 'Scan', 'Mood Pet'].map((t) => (
          <button 
            key={t} 
            onClick={() => setSubTab(t as any)} 
            className={`px-5 py-2.5 rounded-full font-black text-[10px] md:text-xs transition-all whitespace-nowrap uppercase tracking-tighter border-b-4 ${subTab === t ? 'bg-custom border-black/20 text-white shadow-lg translate-y-[-2px]' : isDarkMode ? 'bg-slate-800 border-slate-900 text-white/30' : 'bg-white border-gray-100 text-slate-500'} ${isOffline && t === 'Express' ? 'border-red-500/30 grayscale-[0.5]' : ''}`}
          >
            {t === 'Express' && isOffline && <WifiOff size={12} className="inline mr-1 text-red-600" />}
            {t}
          </button>
        ))}
      </div>

      <div className="flex-1 min-h-0 relative">
        <AnimatePresence mode="wait">
          {subTab === 'Express' && (
            <motion.div key="express" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="h-full overflow-y-auto fading-scrollbar pr-2 space-y-6 pb-20">
              {isOffline ? (
                <div className={`p-8 rounded-[2.5rem] ${isDarkMode ? 'bg-slate-900' : 'bg-white'} border-4 border-dashed border-red-600/30 flex flex-col items-center justify-center text-center py-20`}>
                  <WifiOff size={60} className="mb-6 text-red-600 opacity-60 animate-pulse" />
                  <h3 className="text-2xl font-black uppercase italic tracking-tighter mb-4 text-red-600">Signal Severed</h3>
                  <p className="text-[12px] font-black uppercase tracking-widest text-red-600/60 leading-relaxed max-w-xs">
                    Metropolis Express frequencies require a live neural link. Broadcasting is disabled until connection is restored.
                  </p>
                </div>
              ) : !isGuest ? (
                <div className={`p-6 md:p-8 rounded-[2.5rem] ${isDarkMode ? 'bg-slate-900' : 'bg-white'} border-4 border-black/5 shadow-xl`}>
                  <textarea 
                    value={postContent} 
                    onChange={(e) => setPostContent(e.target.value)} 
                    disabled={isBroadcasting}
                    placeholder={isBroadcasting ? "Sending Signal..." : (postVisibility === 'global' ? "Transmit a global frequency..." : "Whisper to your circle...")} 
                    className={`w-full ${isDarkMode ? 'bg-slate-800 text-white' : 'bg-gray-50 text-slate-900'} p-6 rounded-3xl border-2 border-black/5 focus:border-custom outline-none font-bold text-lg shadow-inner min-h-[120px]`} 
                  />
                  <div className="flex flex-wrap justify-between items-center mt-6 gap-4">
                    <div className="flex gap-2 bg-black/5 p-1.5 rounded-2xl">
                      <button onClick={() => setPostVisibility('global')} className={`flex items-center gap-2 px-4 py-2 rounded-xl text-[10px] font-black uppercase transition-all ${postVisibility === 'global' ? 'bg-custom text-white' : 'opacity-40'}`}><Globe size={14}/> GLOBAL</button>
                      <button onClick={() => setPostVisibility('circle')} className={`flex items-center gap-2 px-4 py-2 rounded-xl text-[10px] font-black uppercase transition-all ${postVisibility === 'circle' ? 'bg-custom text-white' : 'opacity-40'}`}><Users size={14}/> CIRCLE</button>
                    </div>
                    <button 
                      onClick={handlePost} 
                      disabled={isBroadcasting || !postContent.trim()}
                      className="kahoot-button-custom px-8 py-4 text-white rounded-2xl font-black text-xs flex items-center gap-2 active:scale-95 transition-transform disabled:opacity-50"
                    >
                      {isBroadcasting ? <Clock size={18} className="animate-spin" /> : <Send size={18} />} 
                      {isBroadcasting ? 'SENDING...' : 'BROADCAST'}
                    </button>
                  </div>
                </div>
              ) : (
                <div className={`p-8 rounded-[2.5rem] ${isDarkMode ? 'bg-slate-800' : 'bg-white'} border-4 border-dashed border-black/10 flex flex-col items-center justify-center text-center`}>
                  <Lock size={40} className="mb-4 opacity-20" />
                  <p className="text-[10px] font-black uppercase tracking-widest opacity-40 leading-relaxed max-w-xs">
                    Sign in to transmit your frequencies to the metropolis.
                  </p>
                </div>
              )}

              {/* Feed logic remains for when user IS online or has cached feed */}
              {!isOffline && (
                <>
                  <div className="flex gap-2 bg-black/5 p-1 rounded-xl w-fit">
                    <button onClick={() => setFeedFilter('Global')} className={`px-4 py-2 rounded-lg text-[9px] font-black uppercase ${feedFilter === 'Global' ? 'bg-white text-custom shadow-sm' : 'opacity-40'}`}>Metropolis Feed</button>
                    <button onClick={() => setFeedFilter('Circle')} className={`px-4 py-2 rounded-lg text-[9px] font-black uppercase ${feedFilter === 'Circle' ? 'bg-white text-custom shadow-sm' : 'opacity-40'}`}>Neural Circle</button>
                  </div>

                  <div className="space-y-6 pb-12">
                    {filteredPosts.length > 0 ? filteredPosts.map(post => {
                      const isAuthor = post.author === user.username;
                      const isLiked = post.likes.includes(user.username);

                      return (
                        <motion.div key={post.id} initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} className={`p-6 rounded-[2rem] ${isDarkMode ? 'bg-slate-900 text-white' : 'bg-white text-slate-900'} border-2 border-black/5 shadow-md`}>
                          <div className="flex items-center justify-between mb-4">
                            <div className="flex items-center gap-3">
                              <button onClick={() => onNavigateToProfile(post.author)} className="w-10 h-10 rounded-xl bg-custom text-white font-black shrink-0 text-xl flex items-center justify-center italic shadow-sm active:scale-95 transition-transform">{post.author[0].toUpperCase()}</button>
                              <div>
                                <button onClick={() => onNavigateToProfile(post.author)} className="font-black text-sm hover:text-custom transition-colors">@{post.author}</button>
                                <p className="text-[9px] font-black opacity-30 uppercase tracking-widest flex items-center gap-1"><Clock size={10}/> {formatTime(post.timestamp)}</p>
                              </div>
                            </div>
                            {isAuthor && !isGuest && !isOffline && (
                              <div className="flex gap-2">
                                 <button onClick={() => handleStartEdit(post)} className="p-2 bg-black/5 hover:bg-black/10 rounded-xl transition-all text-blue-500"><Edit size={16}/></button>
                                 <button onClick={() => onDeletePost(post.id)} className="p-2 bg-black/5 hover:bg-black/10 rounded-xl transition-all text-red-500"><Trash2 size={16}/></button>
                              </div>
                            )}
                          </div>

                          {editingPostId === post.id && !isGuest && !isOffline ? (
                            <div className="space-y-4 mb-6">
                               <textarea value={editBuffer} onChange={e => setEditBuffer(e.target.value)} className={`w-full p-4 rounded-2xl border-2 font-bold ${isDarkMode ? 'bg-slate-800 border-slate-700 text-white' : 'bg-gray-50 border-gray-100 text-slate-900'} outline-none focus:border-custom`} rows={3} />
                               <div className="flex gap-2">
                                 <button onClick={handleSaveEdit} className="bg-custom text-white px-4 py-2 rounded-xl font-black text-[10px] uppercase shadow-md">Update Signal</button>
                                 <button onClick={() => setEditingPostId(null)} className="bg-black/5 px-4 py-2 rounded-xl font-black text-[10px] uppercase">Cancel</button>
                               </div>
                            </div>
                          ) : (
                            <>
                              {post.isRepost && <div className="flex items-center gap-2 text-[10px] font-black text-green-500 uppercase italic mb-2"><Repeat size={12}/> Echoing: @{post.originalAuthor}</div>}
                              <p className="text-base font-bold italic opacity-90 mb-6 leading-relaxed break-words">"{post.content}"</p>
                            </>
                          )}

                          <div className="flex items-center gap-6 pt-4 border-t border-black/5">
                            <div className="flex items-center gap-1.5">
                               <button disabled={isGuest || isOffline} onClick={() => onHeart(post.id)} className={`flex items-center gap-1.5 ${isLiked ? 'text-custom' : 'opacity-40'} font-black text-[10px] uppercase transition-all active:scale-95 ${isGuest || isOffline ? 'cursor-not-allowed' : ''}`}>
                                 <Heart size={16} fill={isLiked ? "currentColor" : "none"} />
                               </button>
                               <button onClick={() => setLikersModalPost(post)} className="text-custom font-black text-[10px] hover:underline transition-all">
                                 {post.likes.length} SYNC
                               </button>
                            </div>
                            <button onClick={() => setExpandedPostId(expandedPostId === post.id ? null : post.id)} className="flex items-center gap-1.5 text-blue-500 font-black text-[10px] uppercase"><MessageSquare size={16} /> {post.comments?.length || 0} ECHO</button>
                            <button disabled={isGuest || isOffline} onClick={() => onRepost(post)} className={`flex items-center gap-1.5 text-green-500 font-black text-[10px] uppercase transition-transform active:scale-95 ${isGuest || isOffline ? 'opacity-30 cursor-not-allowed' : ''}`}><Repeat size={16} /> ECHO RE-SIGNAL</button>
                          </div>

                          <AnimatePresence>
                            {expandedPostId === post.id && (
                              <motion.div initial={{ height: 0, opacity: 0 }} animate={{ height: 'auto', opacity: 1 }} exit={{ height: 0, opacity: 0 }} className="overflow-hidden">
                                 <div className="pt-6 space-y-4">
                                    {!isGuest && !isOffline && (
                                      <div className="flex gap-2">
                                        <input 
                                          type="text" 
                                          value={commentInputs[post.id] || ''} 
                                          onChange={e => setCommentInputs(prev => ({ ...prev, [post.id]: e.target.value }))}
                                          placeholder="Add an echo to this signal..." 
