import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { User } from '../types';
import { Coins, Heart, Trophy, ShoppingBag, Gamepad2, Moon, Timer, X, Star } from 'lucide-react';
import { getExpNeeded } from '../constants';

interface MoodPetSectionProps {
  user: User;
  onUpdate: (updates: Partial<User>) => void;
  isDarkMode: boolean;
}

const PET_EMOJIS = ['🐱', '🐶', '🦊', '🦁', '🐨', '🐼', '🦄', '🐲', '🐸', '🐹'];

const MoodPetSection: React.FC<MoodPetSectionProps> = ({ user, onUpdate, isDarkMode }) => {
  const [activeSubTab, setActiveSubTab] = useState<'Care' | 'Shop' | 'Games'>('Care');
  const [gameMode, setGameMode] = useState<string | null>(null);
  const [gameTimer, setGameTimer] = useState(0);
  const [score, setScore] = useState(0);
  const [cooldown, setCooldown] = useState<Record<string, number>>({});
  const [levelUpAnim, setLevelUpAnim] = useState(false);

  useEffect(() => {
    const int = setInterval(() => {
      const n = Date.now();
      setCooldown(prev => {
        const nc = { ...prev };
        Object.keys(nc).forEach(k => { if (nc[k] < n) delete nc[k]; });
        return nc;
      });
    }, 1000);
    return () => clearInterval(int);
  }, []);

  const handleCreatePet = (emoji: string) => {
    const name = prompt("Name your Metropolis Guardian:");
    if (!name) return;
    onUpdate({
      petName: name,
      petEmoji: emoji,
      petHasBeenChosen: true,
      petHunger: 100,
      petThirst: 100,
      petRest: 100,
      petLevel: 1,
      petExp: 0,
      petLastUpdate: Date.now()
    });
  };

  const updateStats = (h: number, t: number, r: number, c: number, e: number) => {
    let nextExp = user.petExp + e;
    let nextLevel = user.petLevel;
    const needed = getExpNeeded(nextLevel);
    if (nextExp >= needed) {
      nextExp -= needed;
      nextLevel++;
      setLevelUpAnim(true);
      setTimeout(() => setLevelUpAnim(false), 3000);
    }

    onUpdate({
      petHunger: Math.min(100, Math.max(0, user.petHunger + h)),
      petThirst: Math.min(100, Math.max(0, user.petThirst + t)),
      petRest: Math.min(100, Math.max(0, user.petRest + r)),
      moodCoins: user.moodCoins + c,
      petLevel: nextLevel,
      petExp: nextExp
    });
  };

  const handleGameEnd = (points: number) => {
    updateStats(-10, -10, -15, points, points * 2);
    setGameMode(null);
    setCooldown(prev => ({ ...prev, [gameMode!]: Date.now() + 10000 }));
  };

  if (!user.petHasBeenChosen) {
    return (
      <div className={`p-10 rounded-[3rem] ${isDarkMode ? 'bg-[#111]' : 'bg-white'} border-4 border-black/5 shadow-xl text-center`}>
        <h3 className="text-3xl font-black uppercase italic mb-8">Choose your Guardian</h3>
        <div className="grid grid-cols-5 gap-4">
          {PET_EMOJIS.map(e => <button key={e} onClick={() => handleCreatePet(e)} className="text-4xl p-4 rounded-2xl hover:bg-black/5 transition-all">{e}</button>)}
        </div>
      </div>
    );
  }

  const isSleeping = user.petSleepUntil && user.petSleepUntil > Date.now();

  return (
    <div className="space-y-6">
      <AnimatePresence>
        {levelUpAnim && (
          <motion.div initial={{ scale: 0, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} exit={{ scale: 0, opacity: 0 }} className="fixed inset-0 z-[200] flex items-center justify-center p-6 bg-black/80 backdrop-blur-xl">
             <div className="text-center text-white space-y-4">
               <Trophy size={100} className="text-yellow-400 mx-auto animate-bounce" />
               <h2 className="text-6xl font-black italic uppercase tracking-tighter">LEVEL UP!</h2>
               <p className="text-2xl font-black uppercase opacity-60">Sync Rank {user.petLevel}</p>
             </div>
          </motion.div>
        )}
      </AnimatePresence>

      <div className={`p-10 rounded-[4rem] ${isDarkMode ? 'bg-slate-900' : 'bg-white'} shadow-xl border-4 border-black/5 flex flex-col items-center relative overflow-hidden`}>
        {isSleeping && (
          <div className="absolute inset-0 bg-black/60 z-20 flex flex-col items-center justify-center text-white backdrop-blur-sm">
             <Moon size={80} className="mb-4 animate-pulse" />
             <h4 className="text-3xl font-black uppercase italic">Guardian Resting...</h4>
             <p className="font-black opacity-60 uppercase tracking-widest text-xs mt-2">Available soon</p>
          </div>
        )}

        <div className="w-full flex justify-between mb-8 z-10">
          <div className="bg-yellow-400 text-white px-4 py-2 rounded-2xl font-black shadow-lg flex items-center gap-2"><Coins size={20}/> {user.moodCoins}</div>
          <div className="bg-indigo-600 text-white px-4 py-2 rounded-2xl font-black shadow-lg">LVL {user.petLevel}</div>
        </div>

        <motion.div animate={{ y: [0, -20, 0] }} transition={{ repeat: Infinity, duration: 3 }} className="text-[140px] drop-shadow-2xl">{user.petEmoji}</motion.div>
        <h4 className="text-2xl font-black uppercase italic tracking-tighter mt-4">{user.petName}</h4>

        <div className="w-full max-w-sm grid grid-cols-3 gap-6 mt-8">
          {[
            { l: 'Hunger', v: user.petHunger, c: 'bg-red-500' },
            { l: 'Thirst', v: user.petThirst, c: 'bg-blue-500' },
            { l: 'Energy', v: user.petRest, c: 'bg-green-500' }
          ].map(s => (
            <div key={s.l} className="text-center space-y-2">
              <p className="text-[9px] font-black uppercase opacity-40">{s.l}</p>
              <div className="h-3 bg-black/5 rounded-full overflow-hidden border border-black/5 shadow-inner"><motion.div animate={{ width: `${s.v}%` }} className={`h-full ${s.c} rounded-full`} /></div>
            </div>
          ))}
        </div>
      </div>

      <div className="flex gap-2">
        {(['Care', 'Shop', 'Games'] as const).map(t => (
          <button key={t} onClick={() => setActiveSubTab(t)} className={`flex-1 py-4 rounded-2xl font-black text-xs uppercase border-b-4 transition-all shadow-md ${activeSubTab === t ? 'bg-indigo-600 text-white translate-y-[-2px]' : 'bg-white text-slate-400'}`}>{t}</button>
        ))}
      </div>

      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        {activeSubTab === 'Care' && (
           <div className="col-span-full grid grid-cols-3 gap-4">
             {[
               { id: 'nap', l: 'Quick Nap', m: 20, t: 30000 },
               { id: 'sleep', l: 'Neural Sleep', m: 50, t: 120000 },
               { id: 'stasis', l: 'Deep Stasis', m: 100, t: 300000 }
             ].map(mode => (
               <button key={mode.id} onClick={() => onUpdate({ petSleepUntil: Date.now() + mode.t, petRest: Math.min(100, user.petRest + mode.m) })} className="p-6 bg-white rounded-3xl border-4 border-black/5 shadow-md flex flex-col items-center gap-3 active:scale-95">
                 <Moon size={32} className="text-indigo-600" />
                 <span className="font-black text-[10px] uppercase text-center leading-tight">{mode.l}</span>
               </button>
             ))}
           </div>
        )}
        {activeSubTab === 'Shop' && (
           <div className="col-span-full grid grid-cols-2 md:grid-cols-4 gap-4">
             {[
               { id: 'snack', l: 'Vibe Snack', c: 10, h: 15 },
               { id: 'burger', l: 'Metropop Burger', c: 25, h: 40 },
               { id: 'water', l: 'Nano Dew', c: 5, t: 20 },
               { id: 'juice', l: 'Cosmic Juice', c: 15, t: 45 }
             ].map(i => (
               <button key={i.id} onClick={() => { if(user.moodCoins >= i.c) updateStats(i.h||0, i.t||0, 0, -i.c, 10); }} className="p-6 bg-white rounded-3xl border-4 border-black/5 shadow-md flex flex-col items-center gap-2 active:scale-95">
                 <ShoppingBag size={24} className="text-indigo-600" />
                 <span className="font-black text-[10px] uppercase">{i.l}</span>
                 <div className="bg-yellow-400 text-white px-3 py-1 rounded-xl text-[9px] font-black">🪙 {i.c}</div>
               </button>
             ))}
           </div>
        )}
        {activeSubTab === 'Games' && (
          <div className="col-span-full grid grid-cols-2 md:grid-cols-3 gap-4">
            {['Clicker', 'Math', 'Guess', 'Dice', 'Rapid', 'Reflex'].map(g => (
              <button key={g} onClick={() => { if(!cooldown[g]) { setGameMode(g); setScore(0); setGameTimer(5); } }} className={`p-6 bg-white rounded-3xl border-4 border-black/5 shadow-md flex flex-col items-center gap-2 relative overflow-hidden transition-all active:scale-95 ${cooldown[g] ? 'opacity-40 grayscale' : ''}`}>
                 {cooldown[g] && <div className="absolute inset-0 z-10 bg-black/20 flex items-center justify-center text-white"><Timer size={24}/></div>}
                 <Gamepad2 size={24} className="text-indigo-600" />
                 <span className="font-black text-[10px] uppercase">{g}</span>
              </button>
            ))}
          </div>
        )}
      </div>

      {gameMode && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center bg-black/90 backdrop-blur-md p-6">
           <div className="w-full max-w-sm bg-white rounded-[3rem] p-10 text-center space-y-8 relative">
              <button onClick={() => setGameMode(null)} className="absolute top-6 right-6 opacity-30"><X size={32}/></button>
              <h3 className="text-3xl font-black italic uppercase">{gameMode}</h3>
              <div className="h-40 flex items-center justify-center text-6xl font-black">
                 {gameMode === 'Clicker' ? (
                   <button onClick={() => setScore(s=>s+1)} className="w-32 h-32 bg-indigo-600 text-white rounded-full border-b-8 border-indigo-900 active:translate-y-2 active:border-b-0 shadow-xl">{score}</button>
                 ) : (
                   <p className="animate-bounce">🎮</p>
                 )}
              </div>
              <p className="font-black opacity-30 uppercase tracking-widest text-[10px]">Tap fast to earn coins!</p>
              <button onClick={() => handleGameEnd(score * 2 + 10)} className="kahoot-button-green w-full py-4 text-white font-black uppercase">FINISH SESSION</button>
           </div>
        </div>
      )}
    </div>
  );
};

