import { DAILY_COLORS, WISDOM_OF_MOODERIA } from '../constants';

interface CityHallSectionProps {
  user: User;
  onUpdate: (updates: Partial<User>) => void;
  isDarkMode: boolean;
}

const CityHallSection: React.FC<CityHallSectionProps> = ({ user, onUpdate, isDarkMode }) => {
  const [subTab, setSubTab] = useState<'Express' | 'Schedule' | 'Wisdom'>('Express');

  // Express State
  const [recipient, setRecipient] = useState('');
  const [letter, setLetter] = useState('');

  // Schedule State
  const [isAddingSchedule, setIsAddingSchedule] = useState(false);
  const [schedTitle, setSchedTitle] = useState('');
  const [schedDate, setSchedDate] = useState('');
  const [schedTime, setSchedTime] = useState('');
  const [schedPeriod, setSchedPeriod] = useState<'AM' | 'PM'>('AM');

  const dailyWisdom = useMemo(() => {
    const today = new Date().toDateString();
    let seed = 0;
    for (let i = 0; i < today.length; i++) seed += today.charCodeAt(i);
    const color = DAILY_COLORS[seed % DAILY_COLORS.length];
    const words = WISDOM_OF_MOODERIA[seed % WISDOM_OF_MOODERIA.length];
    return { color, words };
  }, []);

  const handleSendExpress = () => {
    if (!recipient.trim() || !letter.trim()) return;
    // In a real app, we'd check if user exists. Here we just "simulate" delivery.
    alert(`Express Letter delivered to @${recipient}!`);
    setRecipient('');
    setLetter('');
  };

  const handleAddSchedule = () => {
    if (!schedTitle.trim() || !schedDate || !schedTime) return;
    const newItem: ScheduleItem = {
      id: Math.random().toString(36).substr(2, 9),
      title: schedTitle,
      date: schedDate,
      time: schedTime,
      period: schedPeriod,
      timestamp: Date.now(),
      alerted: false
    };
    onUpdate({ schedule: [...user.schedule, newItem] });
    setIsAddingSchedule(false);
    setSchedTitle('');
  };

  return (
    <div className="flex flex-col h-full space-y-6 pb-20">
