                    <textarea value={letter} onChange={e => setLetter(e.target.value)} placeholder="Pour your neural state into words..." className="w-full p-6 rounded-[2rem] border-2 bg-black/5 font-bold outline-none focus:border-red-500 min-h-[200px]" />
