              className="w-full p-4 rounded-2xl bg-black/5 font-black text-sm outline-none focus:border-indigo-500 border-2 border-transparent transition-all"
            />
          )}
          <input 
            value={username} 
            onChange={e => setUsername(e.target.value)} 
            placeholder="Unique Username" 
            className="w-full p-4 rounded-2xl bg-black/5 font-black text-sm outline-none focus:border-indigo-500 border-2 border-transparent transition-all"
          />
          <input 
            type="password" 
            value={password} 
            onChange={e => setPassword(e.target.value)} 
            placeholder="Access Phrase" 
            className="w-full p-4 rounded-2xl bg-black/5 font-black text-sm outline-none focus:border-indigo-500 border-2 border-transparent transition-all"
          />

          <button type="submit" className="kahoot-button-blue w-full py-5 rounded-2xl text-white font-black uppercase text-lg mt-4 shadow-xl active:scale-95 flex items-center justify-center gap-3">
             {mode === 'login' ? <LogIn size={20}/> : <UserPlus size={20}/>}
             {mode === 'login' ? 'Synchronize' : 'Initialize ID'}
          </button>
        </form>

        <div className="mt-8 text-center">
           <button onClick={() => setMode(mode === 'login' ? 'signup' : 'login')} className="text-xs font-black uppercase tracking-widest text-indigo-600 hover:underline">
             {mode === 'login' ? 'Register as Citizen' : 'Return to Login Grid'}
           </button>
        </div>
      </motion.div>
    </div>
  );
};

