    }
    if (scanStep < 9) {
      setScanStep(scanStep + 1);
    } else {
      // Fix: Explicitly typed entries to avoid arithmetic operator errors on ambiguous types
      const sorted = Object.entries(scanScores).sort((a: [string, number], b: [string, number]) => b[1] - a[1]);
      setScanResult((sorted[0]?.[0] as Mood) || 'Normal');
