    { q: "What's the vibe of your thoughts?", opts: [{ l: "Clear and sunny", m: "Wonderful" }, { l: "Steady flow", m: "Normal" }, { l: "Racing like a car", m: "Excited" }, { l: "Stuck in mud", m: "Tired" }] },
