import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { User, Section, Message, Notification, Mood, RoutineItem } from './types';
import Sidebar from './components/Sidebar';
import HomeSection from './sections/HomeSection';
import MoodSection from './sections/MoodSection';
import CityHallSection from './sections/CityHallSection';
import MailSection from './sections/MailSection';
import ProfileSection from './sections/ProfileSection';
import SettingsSection from './sections/SettingsSection';
import AuthScreen from './sections/AuthScreen';
import LoadingScreen from './components/LoadingScreen';
import MoodCheckIn from './components/MoodCheckIn';
import { MOOD_SCORES, getExpNeeded, t } from './constants';
import { supabase, isCloudEnabled, syncProfile } from './services/supabaseService';
import { Coins, Sparkles, X } from 'lucide-react';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [activeSection, setActiveSection] = useState<Section>('Home');
  const [isDarkMode, setIsDarkMode] = useState(false);
  const [isAppStarting, setIsAppStarting] = useState(true);
  const [showMoodCheckIn, setShowMoodCheckIn] = useState(false);
  const [language, setLanguage] = useState<'English' | 'Filipino'>('English');
  const [activeToast, setActiveToast] = useState<{title: string, msg: string, icon?: any} | null>(null);

  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);

  // Load Initial State
  useEffect(() => {
    const init = async () => {
      const savedTheme = localStorage.getItem('mooderia_theme');
      if (savedTheme === 'dark') setIsDarkMode(true);

      const savedLang = localStorage.getItem('mooderia_lang');
      if (savedLang === 'Filipino') setLanguage('Filipino');

      const savedUser = localStorage.getItem('mooderia_user');
      if (savedUser) {
        const parsed = JSON.parse(savedUser);
        // Migration for new Routine/Pet fields if missing
        if (!parsed.routines) parsed.routines = [];
        if (!parsed.petBackground) parsed.petBackground = 'default';
        if (!parsed.unlockedBackgrounds) parsed.unlockedBackgrounds = ['default'];
        if (parsed.moodCoins === undefined) parsed.moodCoins = 0;

        setCurrentUser(parsed);
      }

      setIsLoaded(true);
      setTimeout(() => setIsAppStarting(false), 2000);
    };
    init();
  }, []);

  // Save State and Sync to Cloud
  useEffect(() => {
    if (isLoaded && currentUser) {
      localStorage.setItem('mooderia_user', JSON.stringify(currentUser));
      if (isCloudEnabled) syncProfile(currentUser);
    }
  }, [currentUser, isLoaded]);

  // Daily Mood Check Trigger
  useEffect(() => {
    if (isLoaded && currentUser) {
      const today = new Date().toDateString();
      if (currentUser.lastMoodDate !== today) {
        setShowMoodCheckIn(true);
      }
    }
  }, [currentUser?.username, isLoaded]);

  const showToast = (title: string, msg: string, icon?: any) => {
    setActiveToast({ title, msg, icon });
    setTimeout(() => setActiveToast(null), 3000);
  };

  // Reward Helper
  const handleGainReward = useCallback((amount: number = 1, exp: number = 20) => {
    setCurrentUser(prev => {
       if(!prev) return null;
       let nextExp = prev.petExp + exp;
       let nextLevel = prev.petLevel;
       const needed = getExpNeeded(nextLevel);
       if (nextExp >= needed) {
         nextExp -= needed;
         nextLevel++;
         showToast("LEVEL UP!", `Pet reached Rank ${nextLevel}`, <Trophy size={20} className="text-yellow-400"/>);
       }
       return {
         ...prev,
         moodCoins: prev.moodCoins + amount,
         petExp: nextExp,
         petLevel: nextLevel
       };
    });
  }, []);

  // Schedule & Routine Alert Logic
  useEffect(() => {
    if (!currentUser) return;
    const interval = setInterval(() => {
      const now = new Date();
      const todayStr = now.toISOString().split('T')[0];
      const hours = now.getHours();
      const mins = now.getMinutes();
      const currentPeriod = hours >= 12 ? 'PM' : 'AM';
      const hours12 = hours % 12 || 12;
      const currentFormattedTime = `${hours12.toString().padStart(2, '0')}:${mins.toString().padStart(2, '0')}`;
      const dayOfWeek = now.getDay(); // 0-6

      // Check Schedule
      currentUser.schedule.forEach(item => {
        if (!item.alerted && item.date === todayStr && item.time === currentFormattedTime && item.period === currentPeriod) {
          const newNotif: Notification = {
            id: Math.random().toString(36).substr(2, 9),
            type: 'schedule',
            title: t('taskAlert', language),
            text: `${t('taskTime', language)} ${item.title}`,
            timestamp: Date.now(),
            read: false
          };
          setNotifications(prev => [...prev, newNotif]);
          showToast(t('taskAlert', language), item.title, <Coins size={20}/>);

          setCurrentUser(prev => {
            if (!prev) return prev;
            return {
              ...prev,
              schedule: prev.schedule.map(s => s.id === item.id ? { ...s, alerted: true } : s)
            };
          });
        }
      });

      // Check Routines
      // We check if start time matches AND not already completed for today
      currentUser.routines.forEach(routine => {
        if (routine.days.includes(dayOfWeek) && 
            routine.startTime === currentFormattedTime && 
            routine.startPeriod === currentPeriod &&
            !routine.completedDates.includes(todayStr)) {
             // Only alert if we haven't alerted recently (implied by this check running every 30s)
             // For robustness, we'd need an 'alertedToday' flag on routine, but for this demo:
             const newNotif: Notification = {
                id: Math.random().toString(36).substr(2, 9),
                type: 'routine',
                title: t('taskAlert', language),
                text: `${t('taskTime', language)} ${routine.title}`,
                timestamp: Date.now(),
                read: false
              };
             // Debounce check: ensure we don't spam notifications for the same minute
             const alreadyNotified = notifications.some(n => n.type === 'routine' && n.text.includes(routine.title) && (Date.now() - n.timestamp < 60000));
             if (!alreadyNotified) {
                 setNotifications(prev => [...prev, newNotif]);
                 showToast(t('taskAlert', language), routine.title);
             }
        }
      });

    }, 15000); // Check every 15s
    return () => clearInterval(interval);
  }, [currentUser, language, notifications]);

  const handleMoodSubmit = (mood: Mood) => {
    if (!currentUser) return;
    const today = new Date().toDateString();
    const score = mood ? MOOD_SCORES[mood] : 50;

    // Reward for check-in
    handleGainReward(1, 50);
    showToast(t('rewardTitle', language), t('rewardMsg', language), <Coins size={20} className="text-yellow-400" />);

    setCurrentUser(prev => {
      if (!prev) return prev;
      const history = [...prev.moodHistory, { date: today, mood, score }];
      return {
        ...prev,
        moodHistory: history,
        lastMoodDate: today,
        moodStreak: prev.moodStreak + 1
      };
    });
    setShowMoodCheckIn(false);
  };

  const handleUpdateUser = (updates: Partial<User>) => {
    setCurrentUser(prev => prev ? ({ ...prev, ...updates }) : null);
  };

  const handleLogout = () => {
    localStorage.removeItem('mooderia_user');
    setCurrentUser(null);
  };

  if (isAppStarting) return <LoadingScreen />;
  if (!currentUser) return <AuthScreen onLogin={setCurrentUser} />;

  return (
    <div className={`h-screen flex flex-col md:flex-row ${isDarkMode ? 'bg-[#0f0f0f] text-white' : 'bg-[#f7f8fa] text-slate-900'} transition-colors duration-300 overflow-hidden`}>
      <style>{`
        :root { --theme-color: ${currentUser.profileColor || '#46178f'}; }
        .bg-custom { background-color: var(--theme-color); }
        .text-custom { color: var(--theme-color); }
      `}</style>

      {/* Global Toast */}
      <AnimatePresence>
        {activeToast && (
          <motion.div 
            initial={{ y: -100, opacity: 0 }}
            animate={{ y: 0, opacity: 1 }}
            exit={{ y: -100, opacity: 0 }}
            className="fixed top-6 left-0 right-0 z-[200] flex justify-center pointer-events-none"
          >
             <div className="bg-white dark:bg-slate-800 text-slate-900 dark:text-white px-6 py-4 rounded-[2rem] shadow-2xl border-4 border-custom flex items-center gap-4">
                <div className="w-10 h-10 rounded-full bg-custom text-white flex items-center justify-center">
                  {activeToast.icon || <Sparkles size={20} />}
                </div>
                <div>
                   <h4 className="font-black uppercase text-sm">{activeToast.title}</h4>
                   <p className="font-bold text-xs opacity-70">{activeToast.msg}</p>
                </div>
             </div>
          </motion.div>
        )}
      </AnimatePresence>

      <AnimatePresence>
        {showMoodCheckIn && <MoodCheckIn isDarkMode={isDarkMode} onSubmit={handleMoodSubmit} />}
      </AnimatePresence>

      <Sidebar 
        activeSection={activeSection} 
        onNavigate={setActiveSection} 
        isDarkMode={isDarkMode} 
        user={currentUser}
        unreadMails={notifications.filter(n => !n.read).length}
        language={language}
      />

      <main className="flex-1 flex flex-col min-h-0 relative pt-14 pb-16 md:pt-0 md:pb-0 h-full overflow-hidden">
        <div className="flex-1 overflow-y-auto fading-scrollbar p-4 md:p-8">
          <motion.div 
            key={activeSection}
            initial={{ opacity: 0, x: 20 }}
            animate={{ opacity: 1, x: 0 }}
            className="max-w-6xl mx-auto w-full"
          >
            {activeSection === 'Home' && <HomeSection user={currentUser} isDarkMode={isDarkMode} language={language} />}
            {activeSection === 'Mood' && <MoodSection user={currentUser} onUpdate={handleUpdateUser} isDarkMode={isDarkMode} language={language} onReward={() => { handleGainReward(1, 20); showToast(t('rewardTitle', language), t('rewardMsg', language), <Coins/>); }} />}
            {activeSection === 'CityHall' && <CityHallSection user={currentUser} onUpdate={handleUpdateUser} isDarkMode={isDarkMode} language={language} onReward={() => { handleGainReward(1, 20); showToast(t('rewardTitle', language), t('rewardMsg', language), <Coins/>); }} />}
            {activeSection === 'Mails' && <MailSection notifications={notifications} setNotifications={setNotifications} isDarkMode={isDarkMode} />}
            {activeSection === 'Profile' && <ProfileSection user={currentUser} onUpdate={handleUpdateUser} isDarkMode={isDarkMode} />}
            {activeSection === 'Settings' && (
              <SettingsSection 
                isDarkMode={isDarkMode} 
                onToggleDarkMode={() => { setIsDarkMode(!isDarkMode); localStorage.setItem('mooderia_theme', !isDarkMode ? 'dark' : 'light'); }} 
                language={language}
                onToggleLanguage={() => { const nl = language === 'English' ? 'Filipino' : 'English'; setLanguage(nl); localStorage.setItem('mooderia_lang', nl); }}
                onLogout={handleLogout} 
              />
            )}
          </motion.div>
        </div>
      </main>
    </div>
  );
};

