import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { User } from '../types';
import { Coins, Heart, Trophy, ShoppingBag, Sparkles, X, Check } from 'lucide-react';
import { PET_BACKGROUNDS, getExpNeeded, t } from '../constants';

interface MoodPetSectionProps {
  user: User;
  onUpdate: (updates: Partial<User>) => void;
  isDarkMode: boolean;
  language: 'English' | 'Filipino';
}

const PET_EMOJIS = ['🐱', '🐶', '🦊', '🦁', '🐨', '🐼', '🦄', '🐲', '🐸', '🐹'];

const MoodPetSection: React.FC<MoodPetSectionProps> = ({ user, onUpdate, isDarkMode, language }) => {
  const [activeSubTab, setActiveSubTab] = useState<'Interact' | 'Shop'>('Interact');
  const [interactionAnim, setInteractionAnim] = useState<string | null>(null);

  const handleCreatePet = (emoji: string) => {
    const name = prompt("Name your Metropolis Guardian:");
    if (!name) return;
    onUpdate({
      petName: name,
      petEmoji: emoji,
      petHasBeenChosen: true,
      petLevel: 1,
      petExp: 0,
      petBackground: 'default',
      unlockedBackgrounds: ['default']
    });
  };

  const handleBuyBackground = (bgId: string, price: number) => {
    if (user.moodCoins < price) {
      alert("Not enough coins!");
      return;
    }
    onUpdate({
      moodCoins: user.moodCoins - price,
      unlockedBackgrounds: [...(user.unlockedBackgrounds || []), bgId],
      petBackground: bgId
    });
  };

  const handleEquipBackground = (bgId: string) => {
    onUpdate({ petBackground: bgId });
  };

  const triggerInteraction = () => {
    const animations = ['bounce', 'shake', 'spin', 'pulse'];
    const randomAnim = animations[Math.floor(Math.random() * animations.length)];
    setInteractionAnim(randomAnim);
    setTimeout(() => setInteractionAnim(null), 1000);
  };

  if (!user.petHasBeenChosen) {
    return (
      <div className={`p-10 rounded-[3rem] ${isDarkMode ? 'bg-[#111]' : 'bg-white'} border-4 border-black/5 shadow-xl text-center`}>
        <h3 className="text-3xl font-black uppercase italic mb-8">{t('choosePet', language)}</h3>
        <div className="grid grid-cols-5 gap-4">
          {PET_EMOJIS.map(e => <button key={e} onClick={() => handleCreatePet(e)} className="text-4xl p-4 rounded-2xl hover:bg-black/5 transition-all">{e}</button>)}
        </div>
      </div>
    );
  }

  const currentBg = PET_BACKGROUNDS.find(b => b.id === user.petBackground) || PET_BACKGROUNDS[0];
  const expNeeded = getExpNeeded(user.petLevel);

  return (
    <div className="space-y-6">
      <div className={`p-10 rounded-[4rem] shadow-xl border-4 border-black/5 flex flex-col items-center relative overflow-hidden transition-all duration-500 ${currentBg.style} min-h-[400px] justify-center`}>

        {/* Top UI */}
        <div className="absolute top-8 left-8 right-8 flex justify-between z-10">
          <div className="bg-yellow-400 text-white px-4 py-2 rounded-2xl font-black shadow-lg flex items-center gap-2 border-2 border-yellow-600"><Coins size={20}/> {user.moodCoins}</div>
          <div className="bg-indigo-600 text-white px-4 py-2 rounded-2xl font-black shadow-lg border-2 border-indigo-800 flex items-center gap-2"><Trophy size={18}/> LVL {user.petLevel}</div>
        </div>

        {/* Pet Display */}
        <motion.div 
          animate={interactionAnim === 'bounce' ? { y: [-20, 20, -20] } : 
                   interactionAnim === 'shake' ? { x: [-10, 10, -10, 10, 0] } :
                   interactionAnim === 'spin' ? { rotate: 360 } :
                   interactionAnim === 'pulse' ? { scale: [1, 1.2, 1] } :
                   { y: [0, -10, 0] }}
          transition={{ duration: interactionAnim ? 0.5 : 3, repeat: interactionAnim ? 0 : Infinity }}
          className="text-[140px] drop-shadow-2xl cursor-pointer select-none"
          onClick={triggerInteraction}
        >
          {user.petEmoji}
        </motion.div>

        <h4 className="text-3xl font-black uppercase italic tracking-tighter mt-4 text-white drop-shadow-md">{user.petName}</h4>

        {/* EXP Bar */}
        <div className="absolute bottom-8 left-10 right-10">
           <div className="flex justify-between text-white text-[10px] font-black uppercase mb-1 drop-shadow-md">
              <span>{t('exp', language)}</span>
              <span>{user.petExp} / {expNeeded}</span>
           </div>
           <div className="h-4 bg-black/20 rounded-full overflow-hidden border-2 border-white/20 backdrop-blur-sm">
             <motion.div animate={{ width: `${Math.min(100, (user.petExp / expNeeded) * 100)}%` }} className="h-full bg-gradient-to-r from-green-400 to-emerald-500" />
           </div>
        </div>
      </div>

      <div className="flex gap-2">
        {(['Interact', 'Shop'] as const).map(t => (
          <button key={t} onClick={() => setActiveSubTab(t)} className={`flex-1 py-4 rounded-2xl font-black text-xs uppercase border-b-4 transition-all shadow-md ${activeSubTab === t ? 'bg-indigo-600 text-white translate-y-[-2px]' : 'bg-white text-slate-400'}`}>
             {t === 'Interact' ? t('care', language) : t('shop', language)}
          </button>
        ))}
      </div>

      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        {activeSubTab === 'Interact' && (
           <div className="col-span-full p-10 text-center opacity-50 font-black italic uppercase">
              Tap your Guardian to play! <br/> Complete tasks in City Hall to gain Coins and EXP.
           </div>
        )}
        {activeSubTab === 'Shop' && (
           <div className="col-span-full grid grid-cols-1 md:grid-cols-2 gap-4">
             {PET_BACKGROUNDS.map(bg => {
               const isOwned = (user.unlockedBackgrounds || ['default']).includes(bg.id);
               const isEquipped = user.petBackground === bg.id;
               return (
                 <div key={bg.id} className={`p-4 rounded-3xl border-4 flex items-center gap-4 ${isEquipped ? 'bg-indigo-50 border-indigo-500' : 'bg-white border-black/5'}`}>
                    <div className={`w-16 h-16 rounded-2xl ${bg.style} shadow-inner border-2 border-black/5`}></div>
                    <div className="flex-1">
                       <h5 className="font-black text-sm uppercase">{bg.name}</h5>
                       {!isOwned && <div className="text-[10px] font-black text-yellow-500 flex items-center gap-1"><Coins size={10}/> {bg.price}</div>}
                    </div>
                    {isOwned ? (
                      <button 
                        onClick={() => handleEquipBackground(bg.id)}
                        disabled={isEquipped}
                        className={`px-4 py-2 rounded-xl font-black text-[10px] uppercase ${isEquipped ? 'bg-green-500 text-white opacity-50' : 'bg-indigo-600 text-white shadow-lg active:scale-95'}`}
                      >
                        {isEquipped ? t('equipped', language) : 'Equip'}
                      </button>
                    ) : (
                      <button 
                        onClick={() => handleBuyBackground(bg.id, bg.price)}
                        className="px-4 py-2 rounded-xl bg-yellow-400 text-white font-black text-[10px] uppercase shadow-lg active:scale-95 border-b-4 border-yellow-600"
                      >
                        {t('buy', language)}
                      </button>
                    )}
                 </div>
               )
             })}
           </div>
        )}
      </div>
    </div>
  );
};

export default MoodPetSection;

import React, { useState, useMemo, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { User, ScheduleItem, RoutineItem } from '../types';
import { Send, Calendar, Sparkles, Plus, Clock, X, Check, Bell, Palette, Play, Timer, Trash2 } from 'lucide-react';
import { DAILY_COLORS, WISDOM_OF_MOODERIA, t } from '../constants';

interface CityHallSectionProps {
  user: User;
  onUpdate: (updates: Partial<User>) => void;
  isDarkMode: boolean;
  language: 'English' | 'Filipino';
  onReward: () => void;
}

const CityHallSection: React.FC<CityHallSectionProps> = ({ user, onUpdate, isDarkMode, language, onReward }) => {
  const [subTab, setSubTab] = useState<'Express' | 'Schedule' | 'Routine' | 'Wisdom'>('Express');

  // Express State
  const [recipient, setRecipient] = useState('');
  const [letter, setLetter] = useState('');

  // Schedule State
  const [isAddingSchedule, setIsAddingSchedule] = useState(false);
  const [schedTitle, setSchedTitle] = useState('');
  const [schedDate, setSchedDate] = useState('');
  const [schedTime, setSchedTime] = useState('');
  const [schedPeriod, setSchedPeriod] = useState<'AM' | 'PM'>('AM');

  // Routine State
  const [isAddingRoutine, setIsAddingRoutine] = useState(false);
  const [routineTitle, setRoutineTitle] = useState('');
  const [routineIcon, setRoutineIcon] = useState('📅');
  const [routineDays, setRoutineDays] = useState<number[]>([0,1,2,3,4,5,6]); // Default all days
  const [routineStartTime, setRoutineStartTime] = useState('08:00');
  const [routineStartPeriod, setRoutineStartPeriod] = useState<'AM'|'PM'>('AM');
  const [routineEndTime, setRoutineEndTime] = useState('09:00');
  const [routineEndPeriod, setRoutineEndPeriod] = useState<'AM'|'PM'>('AM');

  // Timer State
  const [activeRoutineId, setActiveRoutineId] = useState<string | null>(null);
  const [timerLeft, setTimerLeft] = useState(0);

  const dailyWisdom = useMemo(() => {
    const today = new Date().toDateString();
    let seed = 0;
    for (let i = 0; i < today.length; i++) seed += today.charCodeAt(i);
    const color = DAILY_COLORS[seed % DAILY_COLORS.length];
    const words = WISDOM_OF_MOODERIA[seed % WISDOM_OF_MOODERIA.length];
    return { color, words };
  }, []);

  useEffect(() => {
    let interval: any;
    if (activeRoutineId && timerLeft > 0) {
      interval = setInterval(() => {
        setTimerLeft(prev => prev - 1);
      }, 1000);
    } else if (activeRoutineId && timerLeft <= 0) {
       // Timer finished
       clearInterval(interval);
       completeRoutine(activeRoutineId);
       setActiveRoutineId(null);
    }
    return () => clearInterval(interval);
  }, [activeRoutineId, timerLeft]);

  const handleSendExpress = () => {
    if (!recipient.trim() || !letter.trim()) return;
    alert(`Express Letter delivered to @${recipient}!`);
    onReward(); // Gain exp/coin
    setRecipient('');
    setLetter('');
  };

  const handleAddSchedule = () => {
    if (!schedTitle.trim() || !schedDate || !schedTime) return;
    const newItem: ScheduleItem = {
      id: Math.random().toString(36).substr(2, 9),
      title: schedTitle,
      date: schedDate,
      time: schedTime,
      period: schedPeriod,
      timestamp: Date.now(),
      alerted: false
    };
    onUpdate({ schedule: [...user.schedule, newItem] });
    setIsAddingSchedule(false);
    setSchedTitle('');
    onReward();
  };

  const calculateDuration = () => {
    // Simple duration calc for demo (ignoring cross-day)
    // Convert to 24h then diff
    let startH = parseInt(routineStartTime.split(':')[0]);
    let startM = parseInt(routineStartTime.split(':')[1]);
    if (routineStartPeriod === 'PM' && startH !== 12) startH += 12;
    if (routineStartPeriod === 'AM' && startH === 12) startH = 0;

    let endH = parseInt(routineEndTime.split(':')[0]);
    let endM = parseInt(routineEndTime.split(':')[1]);
    if (routineEndPeriod === 'PM' && endH !== 12) endH += 12;
    if (routineEndPeriod === 'AM' && endH === 12) endH = 0;

    let startTotal = startH * 60 + startM;
    let endTotal = endH * 60 + endM;

    if (endTotal < startTotal) endTotal += 24 * 60; // Next day
    return endTotal - startTotal;
  };

  const handleAddRoutine = () => {
    if (!routineTitle.trim()) return;
    const duration = calculateDuration();
    const newRoutine: RoutineItem = {
      id: Math.random().toString(36).substr(2, 9),
      title: routineTitle,
      icon: routineIcon,
      days: routineDays,
      startTime: routineStartTime,
      startPeriod: routineStartPeriod,
      endTime: routineEndTime,
      endPeriod: routineEndPeriod,
      durationMinutes: duration,
      completedDates: []
    };
    onUpdate({ routines: [...(user.routines || []), newRoutine] });
    setIsAddingRoutine(false);
    onReward();
  };

  const startRoutine = (r: RoutineItem) => {
    setActiveRoutineId(r.id);
    setTimerLeft(r.durationMinutes * 60); // In seconds
  };

  const completeRoutine = (id: string) => {
    const todayStr = new Date().toISOString().split('T')[0];
    onUpdate({
      routines: user.routines.map(r => r.id === id ? { ...r, completedDates: [...r.completedDates, todayStr] } : r)
    });
    onReward();
    alert("Routine Complete! Rewards Added.");
  };

  const deleteRoutine = (id: string) => {
    onUpdate({ routines: user.routines.filter(r => r.id !== id) });
  };

  const toggleDay = (d: number) => {
    if (routineDays.includes(d)) setRoutineDays(routineDays.filter(day => day !== d));
    else setRoutineDays([...routineDays, d].sort());
  };

  return (
    <div className="flex flex-col h-full space-y-6 pb-20">
      <div className="flex gap-2 overflow-x-auto no-scrollbar pb-2 shrink-0">
        {(['Express', 'Schedule', 'Routine', 'Wisdom'] as const).map(t => (
          <button 
            key={t} 
            onClick={() => setSubTab(t)}
            className={`px-6 py-3 rounded-full font-black text-xs uppercase transition-all whitespace-nowrap border-b-4 ${subTab === t ? 'bg-red-600 text-white shadow-lg translate-y-[-2px]' : isDarkMode ? 'bg-white/5 border-black text-white/40' : 'bg-white border-gray-100 text-slate-500 shadow-sm'}`}
          >
            {t(t.toLowerCase() as any, language)}
          </button>
        ))}
      </div>

      <div className="flex-1">
        <AnimatePresence mode="wait">
          {/* ... Express and Schedule tabs ... */}
          {subTab === 'Express' && (
            <motion.div key="express" initial={{ opacity: 0 }} animate={{ opacity: 1 }} className={`p-10 rounded-[3rem] ${isDarkMode ? 'bg-[#111]' : 'bg-white'} border-4 border-black/5 shadow-xl`}>
               <h3 className="text-3xl font-black uppercase italic tracking-tighter mb-8 flex items-center gap-3"><Send className="text-red-500"/> Metropolis Express</h3>
               <div className="space-y-6">
                  <div>
                    <p className="text-[10px] font-black uppercase opacity-40 tracking-widest mb-2 ml-4">Recipient Identity</p>
                    <input value={recipient} onChange={e => setRecipient(e.target.value)} placeholder="@username..." className="w-full p-4 rounded-2xl border-2 bg-black/5 font-black outline-none focus:border-red-500" />
                  </div>
                  <div>
                    <p className="text-[10px] font-black uppercase opacity-40 tracking-widest mb-2 ml-4">Message Frequencies</p>
                    <textarea value={letter} onChange={e => setLetter(e.target.value)} placeholder="Pour your neural state into words..." className="w-full p-6 rounded-[2rem] border-2 bg-black/5 font-bold outline-none focus:border-red-500 min-h-[200px]" />
                  </div>
                  <button onClick={handleSendExpress} className="kahoot-button-red w-full py-5 rounded-2xl text-white font-black uppercase shadow-lg">{t('sendMail', language)}</button>
               </div>
            </motion.div>
          )}

          {subTab === 'Schedule' && (
             <motion.div key="schedule" initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="space-y-6">
                <div className="flex justify-between items-center px-4">
                   <h3 className="text-3xl font-black uppercase italic tracking-tighter flex items-center gap-3"><Calendar className="text-blue-500"/> Citizen Slated</h3>
                   <button onClick={() => setIsAddingSchedule(true)} className="kahoot-button-blue px-6 py-3 rounded-2xl text-white font-black text-xs flex items-center gap-2 shadow-lg"><Plus size={18} /> {t('newTask', language)}</button>
                </div>
                {/* Existing Schedule List rendering */}
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  {user.schedule.length > 0 ? user.schedule.sort((a,b)=>a.date.localeCompare(b.date)).map(item => (
                    <div key={item.id} className={`p-6 rounded-[2.5rem] ${isDarkMode ? 'bg-[#111]' : 'bg-white'} border-4 border-black/5 shadow-md flex items-center gap-4`}>
                       <div className={`w-12 h-12 rounded-xl flex items-center justify-center shadow-inner ${item.alerted ? 'bg-green-500 text-white' : 'bg-blue-600 text-white'}`}>
                          {item.alerted ? <Check size={24}/> : <Clock size={24}/>}
                       </div>
                       <div className="flex-1 min-w-0">
                          <h5 className="font-black text-sm uppercase truncate">{item.title}</h5>
                          <p className="text-[10px] font-black opacity-30 uppercase tracking-widest">{item.date} • {item.time} {item.period}</p>
                       </div>
                       <button onClick={() => onUpdate({ schedule: user.schedule.filter(s => s.id !== item.id) })} className="p-2 opacity-20 hover:opacity-100 transition-opacity"><X size={20}/></button>
                    </div>
                  )) : <div className="col-span-full py-20 text-center opacity-20 font-black uppercase text-lg italic tracking-widest">{t('noEntries', language)}</div>}
               </div>

                {isAddingSchedule && (
                  <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-black/90 backdrop-blur-md">
                    <motion.div initial={{ scale: 0.9 }} animate={{ scale: 1 }} className={`${isDarkMode ? 'bg-slate-900' : 'bg-white'} w-full max-w-lg rounded-[3rem] p-10 shadow-2xl border-4 border-white/10 relative`}>
                      <button onClick={() => setIsAddingSchedule(false)} className="absolute top-6 right-6 opacity-40"><X size={32}/></button>
                      <h3 className="text-3xl font-black uppercase italic mb-8">Slate New Task</h3>
                      <div className="space-y-4">
                        <input value={schedTitle} onChange={e => setSchedTitle(e.target.value)} placeholder="Task Designation..." className="w-full p-4 rounded-xl border-2 bg-black/5 font-black outline-none focus:border-blue-500" />
                        <div className="grid grid-cols-2 gap-4">
                          <input type="date" value={schedDate} onChange={e => setSchedDate(e.target.value)} className="w-full p-4 rounded-xl border-2 bg-black/5 font-black outline-none focus:border-blue-500" />
                          <div className="flex gap-2">
                             <input type="time" value={schedTime} onChange={e => setSchedTime(e.target.value)} className="flex-1 p-4 rounded-xl border-2 bg-black/5 font-black outline-none focus:border-blue-500" />
                             <select value={schedPeriod} onChange={e => setSchedPeriod(e.target.value as any)} className="p-4 rounded-xl border-2 bg-black/5 font-black outline-none focus:border-blue-500">
                               <option>AM</option>
                               <option>PM</option>
                             </select>
                          </div>
                        </div>
                        <button onClick={handleAddSchedule} className="kahoot-button-blue w-full py-5 rounded-2xl text-white font-black uppercase shadow-lg mt-4">COMMIT TO GRID</button>
                      </div>
                    </motion.div>
                  </div>
               )}
             </motion.div>
          )}

          {subTab === 'Routine' && (
             <motion.div key="routine" initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="space-y-6">
               <div className="flex justify-between items-center px-4">
                   <h3 className="text-3xl font-black uppercase italic tracking-tighter flex items-center gap-3"><Clock className="text-purple-500"/> Daily Routine</h3>
                   <button onClick={() => setIsAddingRoutine(true)} className="kahoot-button-purple px-6 py-3 rounded-2xl text-white font-black text-xs flex items-center gap-2 shadow-lg"><Plus size={18} /> {t('newRoutine', language)}</button>
               </div>

               <div className="grid grid-cols-1 gap-4">
                  {(user.routines || []).map(r => {
                    const todayStr = new Date().toISOString().split('T')[0];
                    const isCompleted = r.completedDates.includes(todayStr);
                    return (
                      <div key={r.id} className={`p-6 rounded-[2.5rem] ${isDarkMode ? 'bg-[#111]' : 'bg-white'} border-4 border-black/5 shadow-md flex items-center gap-4 relative overflow-hidden`}>
                         <div className="w-14 h-14 bg-black/5 rounded-2xl flex items-center justify-center text-3xl">{r.icon}</div>
                         <div className="flex-1">
                            <h5 className="font-black text-lg uppercase">{r.title}</h5>
                            <p className="text-[10px] font-black opacity-40 uppercase tracking-widest">{r.startTime} {r.startPeriod} - {r.endTime} {r.endPeriod} ({r.durationMinutes}m)</p>
                            <div className="flex gap-1 mt-1 opacity-40">
                              {['S','M','T','W','T','F','S'].map((d,i) => <span key={i} className={`text-[9px] font-black ${r.days.includes(i) ? 'text-indigo-500' : 'text-gray-400'}`}>{d}</span>)}
                            </div>
                         </div>
                         {isCompleted ? (
                           <div className="bg-green-500 text-white px-4 py-2 rounded-xl font-black text-xs uppercase shadow-md flex items-center gap-2"><Check size={14}/> {t('complete', language)}</div>
                         ) : (
                           <button onClick={() => startRoutine(r)} className="kahoot-button-green px-4 py-2 rounded-xl text-white font-black text-xs uppercase shadow-md flex items-center gap-2"><Play size={14}/> {t('startTask', language)}</button>
                         )}
                         <button onClick={() => deleteRoutine(r.id)} className="absolute top-4 right-4 opacity-10 hover:opacity-100 transition-opacity"><Trash2 size={16}/></button>
                      </div>
                    );
                  })}
               </div>

               {/* Add Routine Modal */}
               {isAddingRoutine && (
                  <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-black/90 backdrop-blur-md">
                    <motion.div initial={{ scale: 0.9 }} animate={{ scale: 1 }} className={`${isDarkMode ? 'bg-slate-900' : 'bg-white'} w-full max-w-lg rounded-[3rem] p-10 shadow-2xl border-4 border-white/10 relative`}>
                      <button onClick={() => setIsAddingRoutine(false)} className="absolute top-6 right-6 opacity-40"><X size={32}/></button>
                      <h3 className="text-3xl font-black uppercase italic mb-8">Slate Routine</h3>
                      <div className="space-y-4">
                        <input value={routineTitle} onChange={e => setRoutineTitle(e.target.value)} placeholder="Routine Name..." className="w-full p-4 rounded-xl border-2 bg-black/5 font-black outline-none focus:border-purple-500" />
                        <input value={routineIcon} onChange={e => setRoutineIcon(e.target.value)} placeholder="Emoji Icon..." className="w-full p-4 rounded-xl border-2 bg-black/5 font-black outline-none focus:border-purple-500" maxLength={2} />

                        <div className="flex gap-2 justify-between">
                           {['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map((d,i) => (
                             <button key={d} onClick={() => toggleDay(i)} className={`w-8 h-8 rounded-full text-[9px] font-black uppercase ${routineDays.includes(i) ? 'bg-purple-600 text-white' : 'bg-black/10'}`}>{d[0]}</button>
                           ))}
                        </div>

                        <div className="grid grid-cols-2 gap-4">
                           <div className="space-y-1">
                             <p className="text-[9px] font-black uppercase opacity-40">Start</p>
                             <div className="flex gap-2"><input type="time" value={routineStartTime} onChange={e => setRoutineStartTime(e.target.value)} className="flex-1 p-3 rounded-xl border-2 bg-black/5 font-black"/><select value={routineStartPeriod} onChange={e=>setRoutineStartPeriod(e.target.value as any)} className="p-3 bg-black/5 rounded-xl font-black"><option>AM</option><option>PM</option></select></div>
                           </div>
                           <div className="space-y-1">
                             <p className="text-[9px] font-black uppercase opacity-40">End</p>
                             <div className="flex gap-2"><input type="time" value={routineEndTime} onChange={e => setRoutineEndTime(e.target.value)} className="flex-1 p-3 rounded-xl border-2 bg-black/5 font-black"/><select value={routineEndPeriod} onChange={e=>setRoutineEndPeriod(e.target.value as any)} className="p-3 bg-black/5 rounded-xl font-black"><option>AM</option><option>PM</option></select></div>
                           </div>
                        </div>

                        <button onClick={handleAddRoutine} className="kahoot-button-purple w-full py-5 rounded-2xl text-white font-black uppercase shadow-lg mt-4">COMMIT TO GRID</button>
                      </div>
                    </motion.div>
                  </div>
               )}

               {/* Timer Modal */}
               {activeRoutineId && (
                  <div className="fixed inset-0 z-[150] flex items-center justify-center bg-purple-900/90 backdrop-blur-xl">
                     <div className="text-center text-white">
                        <Timer size={60} className="mx-auto mb-6 animate-pulse"/>
                        <h2 className="text-4xl font-black italic uppercase mb-2">Routine Active</h2>
                        <h1 className="text-8xl font-black tabular-nums mb-8">
                           {Math.floor(timerLeft / 60).toString().padStart(2,'0')}:{(timerLeft % 60).toString().padStart(2,'0')}
                        </h1>
                        <button onClick={() => { setActiveRoutineId(null); setTimerLeft(0); }} className="px-8 py-3 bg-white/20 rounded-full font-black uppercase text-xs hover:bg-white/40">Cancel Timer</button>
                     </div>
                  </div>
               )}
             </motion.div>
          )}

          {subTab === 'Wisdom' && (
            <motion.div key="wisdom" initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="space-y-6">
               <div className={`p-10 rounded-[4rem] ${isDarkMode ? 'bg-[#111]' : 'bg-white'} border-4 border-black/5 shadow-xl text-center relative overflow-hidden`}>
                  <Sparkles className="absolute -top-10 -right-10 text-yellow-500/10" size={200} />
                  <p className="text-[10px] font-black opacity-30 uppercase tracking-[0.4em] mb-6">Metropolis Insight</p>
