      id: Math.random().toString(36).substr(2, 9),
      title: diaryTitle,
      content: diaryContent,
      mood: diaryMood,
      timestamp: Date.now()
    };
    onUpdate({ diaryEntries: [newEntry, ...user.diaryEntries] });
