                        <button onClick={handleAddSchedule} className="kahoot-button-blue w-full py-5 rounded-2xl text-white font-black uppercase shadow-lg mt-4">COMMIT TO GRID</button>
                      </div>
                    </motion.div>
                  </div>
               )}
             </motion.div>
          )}

          {subTab === 'Routine' && (
