import { TrendingUp, Book, Brain, Sparkles, Plus, X, Trash2, HeartPulse, Zap } from 'lucide-react';
import MoodPetSection from './MoodPetSection';
import { t } from '../constants';
import { getFortune } from '../services/geminiService';

interface MoodSectionProps {
  user: User;
  onUpdate: (updates: Partial<User>) => void;
  isDarkMode: boolean;
  language: 'English' | 'Filipino';
  onReward: () => void;
  triggerAnimation: (type: 'express' | 'schedule' | 'routine' | 'diary' | 'alarm', text?: string) => void;
}

const MoodSection: React.FC<MoodSectionProps> = ({ user, onUpdate, isDarkMode, language, onReward, triggerAnimation }) => {
  const [subTab, setSubTab] = useState<'Statistics' | 'Diary' | 'Mood Pet' | 'Scan' | 'Teller'>('Statistics');

  // Diary States
  const [isAddingDiary, setIsAddingDiary] = useState(false);
  const [diaryTitle, setDiaryTitle] = useState('');
  const [diaryContent, setDiaryContent] = useState('');
  const [diaryMood, setDiaryMood] = useState<Mood>('Normal');

  // Scan States
  const [scanStep, setScanStep] = useState(0);
  const [scanScores, setScanScores] = useState<Record<string, number>>({});
  const [scanResult, setScanResult] = useState<Mood | null>(null);

  // Teller States
  const [fortuneQuestion, setFortuneQuestion] = useState('');
  const [fortuneAnswer, setFortuneAnswer] = useState('');
  const [isConsulting, setIsConsulting] = useState(false);

  // Statistics Data
  const lineData = useMemo(() => {
    return user.moodHistory.slice(-14).map((entry, i) => ({ name: `Day ${i + 1}`, score: entry.score }));
  }, [user.moodHistory]);

  const barData = useMemo(() => {
    const counts: Record<string, number> = { Wonderful: 0, Excited: 0, Happy: 0, Normal: 0, Tired: 0, Angry: 0, Flaming: 0 };
    user.moodHistory.forEach(e => { if (e.mood) counts[e.mood]++; });
    return Object.entries(counts).map(([name, val]) => ({ name, val }));
  }, [user.moodHistory]);

  const handleSaveDiary = () => {
    if (!diaryTitle.trim() || !diaryContent.trim()) return;
    const newEntry: DiaryEntry = {
      id: Math.random().toString(36).substr(2, 9),
      title: diaryTitle,
      content: diaryContent,
      mood: diaryMood,
      timestamp: Date.now()
    };
    onUpdate({ diaryEntries: [newEntry, ...user.diaryEntries] });
    setIsAddingDiary(false);
    setDiaryTitle('');
    setDiaryContent('');

    // Reward
    onReward();
    triggerAnimation('diary');
  };

  const handleScanAnswer = (moodImpact: Mood) => {
    if (moodImpact) {
      setScanScores(prev => ({ ...prev, [moodImpact]: (prev[moodImpact] || 0) + 1 }));
    }

    if (scanStep < SCAN_QUESTIONS.length - 1) {
      setScanStep(scanStep + 1);
    } else {
      // Calculate Result
      const scores = { ...scanScores };
      if (moodImpact) scores[moodImpact] = (scores[moodImpact] || 0) + 1;

      const sorted = Object.entries(scores).sort((a: [string, number], b: [string, number]) => b[1] - a[1]);
      setScanResult((sorted[0]?.[0] as Mood) || 'Normal');
    }
  };

  const resetScan = () => {
    setScanStep(0);
    setScanScores({});
    setScanResult(null);
  };

  const handleFortune = async () => {
    if(!fortuneQuestion.trim()) return;
    setIsConsulting(true);
    setFortuneAnswer('');
    try {
        const answer = await getFortune(fortuneQuestion);
        setFortuneAnswer(answer);
    } catch(e) {
        setFortuneAnswer("The spirits are silent.");
    } finally {
        setIsConsulting(false);
    }
  };

  const SCAN_QUESTIONS = [
    { q: "How fast is your heart beating right now?", opts: [{ l: "Very fast!", m: "Excited" }, { l: "Calm", m: "Normal" }, { l: "A bit heavy", m: "Tired" }, { l: "Pounding!", m: "Angry" }] },
    { q: "Do you feel like dancing?", opts: [{ l: "Yes, definitely!", m: "Wonderful" }, { l: "Maybe later", m: "Happy" }, { l: "Too tired", m: "Tired" }, { l: "Not at all", m: "Angry" }] },
    { q: "How bright does the screen look?", opts: [{ l: "Perfectly vibrant", m: "Excited" }, { l: "Okay", m: "Normal" }, { l: "A bit dull", m: "Tired" }, { l: "It's annoying", m: "Angry" }] },
    { q: "Pick an emoji!", opts: [{ l: "✨", m: "Wonderful" }, { l: "🔥", m: "Flaming" }, { l: "💤", m: "Tired" }, { l: "😐", m: "Normal" }] },
    { q: "Are you hungry?", opts: [{ l: "For a feast!", m: "Excited" }, { l: "Just a snack", m: "Happy" }, { l: "No, too stressed", m: "Angry" }, { l: "Just thirsty", m: "Normal" }] },
    { q: "What's the vibe of your thoughts?", opts: [{ l: "Clear and sunny", m: "Wonderful" }, { l: "Steady flow", m: "Normal" }, { l: "Racing like a car", m: "Excited" }, { l: "Stuck in mud", m: "Tired" }] },
  ];

  return (
    <div className="flex flex-col h-full space-y-6 pb-20">
      <div className="flex gap-2 overflow-x-auto no-scrollbar pb-2 shrink-0">
        {(['Statistics', 'Diary', 'Mood Pet', 'Scan', 'Teller'] as const).map(tabName => (
          <button 
            key={tabName} 
            onClick={() => setSubTab(tabName)}
            className={`px-5 py-3 rounded-full font-black text-xs uppercase transition-all whitespace-nowrap border-b-4 ${subTab === tabName ? 'bg-indigo-600 text-white shadow-lg translate-y-[-2px]' : isDarkMode ? 'bg-white/5 border-black text-white/40' : 'bg-white border-gray-100 text-slate-500 shadow-sm'}`}
          >
            {tabName === 'Mood Pet' ? t('moodPet', language) : t(tabName.toLowerCase() as any, language) || tabName}
          </button>
        ))}
      </div>

      <div className="flex-1">
        <AnimatePresence mode="wait">
          {subTab === 'Statistics' && (
            <motion.div key="stats" initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="space-y-6">
              <div className={`p-8 rounded-[3rem] ${isDarkMode ? 'bg-[#111]' : 'bg-white'} shadow-xl border-4 border-black/5`}>
                <h4 className="text-xl font-black uppercase italic tracking-tighter mb-6 flex items-center gap-3"><TrendingUp className="text-indigo-500"/> Overall Resonance</h4>
                <div className="h-64">
                  <ResponsiveContainer width="100%" height="100%">
                    <LineChart data={lineData}>
                      <CartesianGrid strokeDasharray="3 3" vertical={false} stroke={isDarkMode ? '#333' : '#eee'} />
                      <XAxis dataKey="name" hide />
                      <YAxis domain={[0, 100]} hide />
                      <Tooltip contentStyle={{ borderRadius: '12px', border: 'none', fontWeight: 'bold' }} />
                      <Line type="monotone" dataKey="score" stroke="#46178f" strokeWidth={5} dot={{ fill: '#46178f', r: 5 }} />
                    </LineChart>
                  </ResponsiveContainer>
                </div>
              </div>
              <div className={`p-8 rounded-[3rem] ${isDarkMode ? 'bg-[#111]' : 'bg-white'} shadow-xl border-4 border-black/5`}>
                <h4 className="text-xl font-black uppercase italic tracking-tighter mb-6 flex items-center gap-3"><TrendingUp className="text-green-500"/> Frequency Distribution</h4>
                <div className="h-64">
                  <ResponsiveContainer width="100%" height="100%">
                    <BarChart data={barData}>
                      <CartesianGrid strokeDasharray="3 3" vertical={false} stroke={isDarkMode ? '#333' : '#eee'} />
                      <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{ fontSize: 10, fontWeight: 'bold' }} />
                      <YAxis hide />
                      <Tooltip contentStyle={{ borderRadius: '12px', border: 'none', fontWeight: 'bold' }} />
                      <Bar dataKey="val" fill="#26890c" radius={[10, 10, 0, 0]} />
                    </BarChart>
                  </ResponsiveContainer>
                </div>
              </div>
            </motion.div>
          )}

          {subTab === 'Diary' && (
            <motion.div key="diary" initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="space-y-6">
              <div className="flex justify-between items-center px-4">
                <h4 className="text-2xl font-black uppercase italic tracking-tighter flex items-center gap-3"><Book className="text-indigo-600"/> Personal Archives</h4>
                <button onClick={() => setIsAddingDiary(true)} className="kahoot-button-green px-6 py-3 rounded-2xl text-white font-black text-xs flex items-center gap-2 shadow-lg"><Plus size={18} /> NEW LOG</button>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {user.diaryEntries.length > 0 ? user.diaryEntries.map(entry => (
                  <div key={entry.id} className={`p-6 rounded-[2.5rem] ${isDarkMode ? 'bg-[#111]' : 'bg-white'} border-4 border-black/5 shadow-md group relative`}>
                    <button onClick={() => onUpdate({ diaryEntries: user.diaryEntries.filter(e => e.id !== entry.id) })} className="absolute top-4 right-4 opacity-0 group-hover:opacity-100 transition-opacity"><Trash2 size={16} /></button>
                    <div className="flex items-center gap-2 mb-2">
                       <span className="text-[9px] font-black uppercase opacity-40">{new Date(entry.timestamp).toLocaleDateString()}</span>
                       <span className="bg-indigo-600/10 text-indigo-600 px-2 rounded-lg text-[9px] font-black uppercase">{entry.mood}</span>
                    </div>
                    <h5 className="text-lg font-black uppercase italic mb-2 line-clamp-1">{entry.title}</h5>
                    <p className="text-sm font-bold opacity-60 leading-relaxed line-clamp-3">"{entry.content}"</p>
                  </div>
                )) : <div className="col-span-full py-20 text-center opacity-20 font-black uppercase">No entries yet.</div>}
              </div>

              {isAddingDiary && (
                 <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-black/90 backdrop-blur-md">
                    <motion.div initial={{ scale: 0.9 }} animate={{ scale: 1 }} className={`${isDarkMode ? 'bg-slate-900' : 'bg-white'} w-full max-w-lg rounded-[3rem] p-10 shadow-2xl border-4 border-white/10 relative`}>
                      <button onClick={() => setIsAddingDiary(false)} className="absolute top-6 right-6 opacity-40"><X size={32}/></button>
                      <h3 className="text-3xl font-black uppercase italic mb-8">New Entry</h3>
                      <div className="space-y-4">
                         <input value={diaryTitle} onChange={e => setDiaryTitle(e.target.value)} placeholder="Entry Title..." className="w-full p-4 rounded-xl border-2 bg-black/5 font-black outline-none focus:border-green-500" />
                         <textarea value={diaryContent} onChange={e => setDiaryContent(e.target.value)} placeholder="Dear Diary..." className="w-full p-4 rounded-xl border-2 bg-black/5 font-bold outline-none focus:border-green-500 min-h-[150px]" />
                         <div className="flex gap-2 overflow-x-auto pb-2">
                           {['Wonderful','Happy','Normal','Tired','Angry'].map(m => (
                             <button key={m} onClick={() => setDiaryMood(m as Mood)} className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase border-2 ${diaryMood === m ? 'bg-green-600 text-white border-green-600' : 'border-black/10'}`}>{m}</button>
                           ))}
                         </div>
                         <button onClick={handleSaveDiary} className="kahoot-button-green w-full py-5 rounded-2xl text-white font-black uppercase shadow-lg mt-4">ARCHIVE MEMORY</button>
                      </div>
                    </motion.div>
                 </div>
              )}
            </motion.div>
          )}

          {subTab === 'Mood Pet' && (
             <MoodPetSection user={user} onUpdate={onUpdate} isDarkMode={isDarkMode} language={language} />
          )}

          {subTab === 'Scan' && (
            <motion.div key="scan" initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="flex flex-col items-center justify-center min-h-[500px]">
                {!scanResult ? (
                    <div className={`w-full max-w-xl p-8 rounded-[3rem] ${isDarkMode ? 'bg-[#111]' : 'bg-white'} border-4 border-black/5 shadow-2xl text-center`}>
                        <div className="mb-8">
                            <h2 className="text-3xl font-black uppercase italic tracking-tighter mb-2">System Diagnostic</h2>
                            <p className="text-xs font-bold uppercase opacity-40 tracking-widest">Question {scanStep + 1} / {SCAN_QUESTIONS.length}</p>
                            <div className="w-full h-2 bg-black/10 rounded-full mt-4 overflow-hidden">
                                <motion.div animate={{ width: `${((scanStep + 1) / SCAN_QUESTIONS.length) * 100}%` }} className="h-full bg-blue-500"/>
                            </div>
                        </div>
                        <h3 className="text-xl md:text-2xl font-black italic mb-10 min-h-[80px] flex items-center justify-center">
                            "{SCAN_QUESTIONS[scanStep].q}"
                        </h3>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            {SCAN_QUESTIONS[scanStep].opts.map((opt, i) => (
                                <button 
                                    key={i} 
                                    onClick={() => handleScanAnswer(opt.m as Mood)}
                                    className="kahoot-button-blue py-4 rounded-2xl text-white font-black uppercase shadow-lg text-sm"
                                >
                                    {opt.l}
                                </button>
                            ))}
                        </div>
                    </div>
                ) : (
                    <div className={`w-full max-w-xl p-10 rounded-[3rem] ${isDarkMode ? 'bg-[#111]' : 'bg-white'} border-4 border-black/5 shadow-2xl text-center`}>
                        <HeartPulse size={80} className="mx-auto mb-6 text-red-500 animate-pulse"/>
                        <p className="text-xs font-bold uppercase opacity-40 tracking-widest mb-2">Diagnosis Complete</p>
                        <h2 className="text-5xl font-black uppercase italic tracking-tighter mb-6">{scanResult}</h2>
                        <p className="text-sm font-bold opacity-70 mb-10">Your responses indicate a resonance frequency matching {scanResult} state. Recommended: Drink water and check City Hall for tasks.</p>
                        <button onClick={resetScan} className="kahoot-button-green px-8 py-4 rounded-2xl text-white font-black uppercase shadow-lg">Run New Scan</button>
                    </div>
                )}
            </motion.div>
          )}

          {subTab === 'Teller' && (
              <motion.div key="teller" initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="flex flex-col items-center justify-center min-h-[500px]">
                  <div className={`w-full max-w-xl p-8 rounded-[3rem] ${isDarkMode ? 'bg-[#111]' : 'bg-white'} border-4 border-black/5 shadow-2xl text-center relative overflow-hidden`}>
                      <Zap size={100} className={`absolute -top-6 -right-6 ${isConsulting ? 'text-purple-500 animate-spin' : 'text-purple-500/20'}`} />
                      <h2 className="text-3xl font-black uppercase italic tracking-tighter mb-8">AI Fortune Teller</h2>

                      {!fortuneAnswer ? (
                          <div className="space-y-6">
                              <p className="text-sm font-bold opacity-60">Ask the Metropolis spirits a question about your future...</p>
                              <textarea 
                                value={fortuneQuestion} 
                                onChange={e => setFortuneQuestion(e.target.value)} 
                                placeholder="Will I find success tomorrow?" 
                                className="w-full p-4 rounded-2xl bg-black/5 font-black text-center outline-none focus:border-purple-500 border-2 min-h-[100px]"
                              />
                              <button 
                                onClick={handleFortune} 
                                disabled={isConsulting || !fortuneQuestion.trim()}
                                className="kahoot-button-purple w-full py-5 rounded-2xl text-white font-black uppercase shadow-lg disabled:opacity-50"
                              >
                                {isConsulting ? 'Consulting Spirits...' : 'Reveal Destiny'}
                              </button>
                          </div>
                      ) : (
                          <div className="space-y-8">
                              <div className="p-8 bg-purple-500/10 rounded-[2rem] border-2 border-purple-500/20">
                                  <h3 className="text-2xl md:text-3xl font-black italic text-purple-600 mb-2">The Spirits Say...</h3>
                                  <p className="text-lg font-bold">"{fortuneAnswer}"</p>
                              </div>
                              <button onClick={() => { setFortuneAnswer(''); setFortuneQuestion(''); }} className="text-xs font-black uppercase opacity-40 hover:opacity-100">Ask Another Question</button>
                          </div>
                      )}
                  </div>
              </motion.div>
          )}
        </AnimatePresence>
      </div>
    </div>
  );
};

export default MoodSection;

import { GoogleGenAI, Type } from "@google/genai";

// Standard initialization as per instructions
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const getHoroscope = async (sign: string) => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Provide a daily horoscope for ${sign} today.`,
      config: {
        systemInstruction: "You are a mystical Metropolis Astrologer. Provide a 3-sentence daily horoscope that is encouraging and insightful. Use cosmic and modern terminology.",
      }
    });
    return response.text || "The constellations are currently obscured by metropolis smog.";
  } catch (error) {
    console.error("Horoscope API Error:", error);
    return "The stars are recalibrating. Check back later.";
  }
};

export const getLovePrediction = async (sign1: string, sign2: string) => {
  try {
    const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Predict love compatibility between ${sign1} and ${sign2}. Return only a JSON object with 'percentage' (0-100) and 'reason'.`,
        config: {
            responseMimeType: "application/json",
            responseSchema: {
                type: Type.OBJECT,
                properties: {
                    percentage: { type: Type.NUMBER },
                    reason: { type: Type.STRING }
                },
                required: ['percentage', 'reason']
            }
        }
    });

    const text = response.text || "{}";
    return JSON.parse(text.trim());
  } catch (error) {
    console.error("Love Prediction API Error:", error);
    return { percentage: 50, reason: "The romantic frequencies are currently experiencing atmospheric interference." };
  }
}

export const checkContentSafety = async (text: string) => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Analyze the following text for inappropriate language, hate speech, severe insults, or harassment: "${text}". Return a JSON object with 'isInappropriate' (boolean) and 'reason' (string, keep it short).`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            isInappropriate: { type: Type.BOOLEAN },
            reason: { type: Type.STRING }
          },
          required: ['isInappropriate', 'reason']
        }
      }
    });
    const resultText = response.text || "{}";
    return JSON.parse(resultText.trim());
  } catch (error) {
    console.error("Safety Check Error:", error);
    return { isInappropriate: false, reason: "" };
  }
};

export const getPsychiatristResponse = async (text: string) => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: text,
      config: {
        systemInstruction: "You are Dr. Philippe Pinel, a wise and empathetic psychiatrist in the Mooderia Metropolis. Your goal is to provide supportive, non-judgmental, and insightful guidance to citizens. Use a professional yet caring tone. If a user expresses severe distress, gently remind them to seek professional real-world help while remaining supportive.",
      }
    });
    return { text: response.text || "I am processing your words. Tell me more about how you feel." };
  } catch (error) {
    console.error("Psychiatrist API Error:", error);
    return { text: "The neural bridge is momentarily unstable. I am here for you when the connection clears." };
  }
};

export const getFortune = async (question: string) => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `The user asks: "${question}". Provide a mysterious, short fortune telling response (max 20 words) as if you are a mystical cyberpunk fortune teller machine.`,
    });
    return response.text || "The mists of the future are cloudy.";
  } catch (error) {
    console.error("Fortune API Error:", error);
    return "Fate is currently rebooting.";
  }
};

import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { User } from '../types';
import { LogIn, UserPlus, Building2 } from 'lucide-react';

interface AuthScreenProps {
  onLogin: (user: User) => void;
}

const AuthScreen: React.FC<AuthScreenProps> = ({ onLogin }) => {
  const [mode, setMode] = useState<'login' | 'signup'>('login');
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [displayName, setDisplayName] = useState('');
  const [error, setError] = useState('');

  const handleAuth = (e: React.FormEvent) => {
    e.preventDefault();
    if (!username || !password) return;
    setError('');

    // Load existing user registry from local storage to prevent duplicates
    const registry = JSON.parse(localStorage.getItem('mooderia_registry') || '{}');

    if (mode === 'signup') {
        if (registry[username]) {
            setError('This Username is already occupied in the Metropolis.');
            return;
        }
        // Add to registry
        registry[username] = true;
        localStorage.setItem('mooderia_registry', JSON.stringify(registry));
    } else {
        // Login mode - optional check if you want to enforce registration first
        // For now we allow "logging in" to a new session if they exist or creating a fresh temp one if not for demo simplicity,
        // but typically you'd check registry[username] here too.
    }

    // Simulation of a database login
    const newUser: User = {
      displayName: displayName || username,
      username: username,
      email: `${username}@mooderia.local`,
      moodHistory: [],
      diaryEntries: [],
      schedule: [],
      routines: [],
      moodStreak: 0,
      moodCoins: 0, // Set to 0 as requested
      petName: 'Guardian',
      petEmoji: '🐱',
      petLevel: 1,
      petExp: 0,
      petHasBeenChosen: false,
      petBackground: 'default',
      unlockedBackgrounds: ['default'],
      following: [],
      followers: [],
      likesReceived: 0,
      title: 'Citizen'
    };

    onLogin(newUser);
  };

  return (
    <div className="min-h-screen bg-[#46178f] flex items-center justify-center p-6 relative overflow-hidden">
      {/* Cityscape Background Overlay */}
      <div className="absolute inset-0 opacity-10 pointer-events-none flex items-end justify-center">
        <Building2 size={600} className="text-white" />
      </div>

      <motion.div 
        initial={{ y: 50, opacity: 0 }} 
        animate={{ y: 0, opacity: 1 }}
        className="w-full max-w-md bg-white rounded-[3rem] p-10 shadow-2xl relative z-10 border-b-[12px] border-black/10"
      >
        <div className="text-center mb-10">
           <h1 className="text-4xl md:text-5xl font-black italic text-indigo-600 tracking-tighter uppercase mb-2">Mooderia</h1>
           <p className="text-[10px] font-black uppercase tracking-[0.4em] opacity-30">Neural Identity System</p>
        </div>

        <form onSubmit={handleAuth} className="space-y-4">
          {mode === 'signup' && (
            <input 
              value={displayName} 
              onChange={e => setDisplayName(e.target.value)} 
              placeholder="Full Name / Alias" 
              className="w-full p-4 rounded-2xl bg-black/5 font-black text-sm outline-none focus:border-indigo-500 border-2 border-transparent transition-all"
            />
          )}
          <input 
            value={username} 
            onChange={e => setUsername(e.target.value)} 
            placeholder="Unique Username" 
            className="w-full p-4 rounded-2xl bg-black/5 font-black text-sm outline-none focus:border-indigo-500 border-2 border-transparent transition-all"
          />
          <input 
            type="password" 
            value={password} 
            onChange={e => setPassword(e.target.value)} 
            placeholder="Access Phrase" 
            className="w-full p-4 rounded-2xl bg-black/5 font-black text-sm outline-none focus:border-indigo-500 border-2 border-transparent transition-all"
          />

          {error && (
             <p className="text-red-500 text-xs font-black uppercase text-center">{error}</p>
          )}

          <button type="submit" className="kahoot-button-blue w-full py-5 rounded-2xl text-white font-black uppercase text-lg mt-4 shadow-xl active:scale-95 flex items-center justify-center gap-3">
             {mode === 'login' ? <LogIn size={20}/> : <UserPlus size={20}/>}
             {mode === 'login' ? 'Synchronize' : 'Initialize ID'}
          </button>
        </form>

        <div className="mt-8 text-center">
           <button onClick={() => { setMode(mode === 'login' ? 'signup' : 'login'); setError(''); }} className="text-xs font-black uppercase tracking-widest text-indigo-600 hover:underline">
             {mode === 'login' ? 'Register as Citizen' : 'Return to Login Grid'}
           </button>
        </div>
      </motion.div>
    </div>
  );
};

export default AuthScreen;

import React, { useState, useMemo, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { User, ScheduleItem, RoutineItem } from '../types';
import { Send, Calendar, Sparkles, Plus, Clock, X, Check, Bell, Palette, Play, Timer, Trash2, AlertTriangle } from 'lucide-react';
import { DAILY_COLORS, WISDOM_OF_MOODERIA, t } from '../constants';

interface CityHallSectionProps {
  user: User;
  onUpdate: (updates: Partial<User>) => void;
  isDarkMode: boolean;
  language: 'English' | 'Filipino';
  onReward: () => void;
  triggerAnimation: (type: 'express' | 'schedule' | 'routine' | 'diary' | 'alarm', text?: string) => void;
  onSendMail: (recipient: string, msg: string) => void;
}

const CityHallSection: React.FC<CityHallSectionProps> = ({ user, onUpdate, isDarkMode, language, onReward, triggerAnimation, onSendMail }) => {
  const [subTab, setSubTab] = useState<'Express' | 'Schedule' | 'Routine' | 'Wisdom'>('Express');

  // Express State
  const [recipient, setRecipient] = useState('');
  const [letter, setLetter] = useState('');
  const [expressError, setExpressError] = useState('');

  // Schedule State
  const [isAddingSchedule, setIsAddingSchedule] = useState(false);
  const [schedTitle, setSchedTitle] = useState('');
  const [schedDate, setSchedDate] = useState('');
  const [schedTime, setSchedTime] = useState('');
  const [schedPeriod, setSchedPeriod] = useState<'AM' | 'PM'>('AM');

  // Routine State
  const [isAddingRoutine, setIsAddingRoutine] = useState(false);
  const [routineTitle, setRoutineTitle] = useState('');
  const [routineIcon, setRoutineIcon] = useState('📅');
  const [routineDays, setRoutineDays] = useState<number[]>([0,1,2,3,4,5,6]); // Default all days
  const [routineStartTime, setRoutineStartTime] = useState('08:00');
  const [routineStartPeriod, setRoutineStartPeriod] = useState<'AM'|'PM'>('AM');
  const [routineEndTime, setRoutineEndTime] = useState('09:00');
  const [routineEndPeriod, setRoutineEndPeriod] = useState<'AM'|'PM'>('AM');

  // Timer State
  const [activeRoutineId, setActiveRoutineId] = useState<string | null>(null);
  const [timerLeft, setTimerLeft] = useState(0);

  const dailyWisdom = useMemo(() => {
    const today = new Date().toDateString();
    let seed = 0;
    for (let i = 0; i < today.length; i++) seed += today.charCodeAt(i);
    const color = DAILY_COLORS[seed % DAILY_COLORS.length];
    const words = WISDOM_OF_MOODERIA[seed % WISDOM_OF_MOODERIA.length];
    return { color, words };
  }, []);

  useEffect(() => {
    let interval: any;
    if (activeRoutineId && timerLeft > 0) {
      interval = setInterval(() => {
        setTimerLeft(prev => prev - 1);
      }, 1000);
    } else if (activeRoutineId && timerLeft <= 0) {
       // Timer finished
       clearInterval(interval);
       completeRoutine(activeRoutineId);
       setActiveRoutineId(null);
    }
    return () => clearInterval(interval);
  }, [activeRoutineId, timerLeft]);

  const handleSendExpress = () => {
    setExpressError('');
    if (!recipient.trim() || !letter.trim()) return;

    // Check if user exists in the local registry
    const registry = JSON.parse(localStorage.getItem('mooderia_registry') || '{}');
    if (!registry[recipient] && recipient !== 'DrPinel') { // DrPinel is system NPC
        setExpressError(`Citizen @${recipient} could not be found in the Metropolis database.`);
        return;
    }

    // Trigger the creative animation
    triggerAnimation('express');

    // Actually add the mail to the list (so sending works)
    onSendMail(recipient, letter);

    onReward(); // Gain exp/coin
    setRecipient('');
    setLetter('');
  };

  const handleAddSchedule = () => {
    if (!schedTitle.trim() || !schedDate || !schedTime) return;
    const newItem: ScheduleItem = {
      id: Math.random().toString(36).substr(2, 9),
      title: schedTitle,
      date: schedDate,
      time: schedTime,
      period: schedPeriod,
      timestamp: Date.now(),
      alerted: false
    };
    onUpdate({ schedule: [...user.schedule, newItem] });
    setIsAddingSchedule(false);
    setSchedTitle('');
    onReward();
    triggerAnimation('schedule');
  };

  // Logic to remove a schedule item when done
  const handleCompleteSchedule = (id: string) => {
    const item = user.schedule.find(s => s.id === id);
    if(item) {
        triggerAnimation('schedule', `COMPLETED: ${item.title}`);
        onUpdate({ schedule: user.schedule.filter(s => s.id !== id) });
        onReward();
    }
  };

  const calculateDuration = () => {
    // Simple duration calc for demo (ignoring cross-day)
    // Convert to 24h then diff
    let startH = parseInt(routineStartTime.split(':')[0]);
    let startM = parseInt(routineStartTime.split(':')[1]);
    if (routineStartPeriod === 'PM' && startH !== 12) startH += 12;
    if (routineStartPeriod === 'AM' && startH === 12) startH = 0;

    let endH = parseInt(routineEndTime.split(':')[0]);
    let endM = parseInt(routineEndTime.split(':')[1]);
    if (routineEndPeriod === 'PM' && endH !== 12) endH += 12;
    if (routineEndPeriod === 'AM' && endH === 12) endH = 0;

    let startTotal = startH * 60 + startM;
    let endTotal = endH * 60 + endM;

    if (endTotal < startTotal) endTotal += 24 * 60; // Next day
    return endTotal - startTotal;
  };

  const handleAddRoutine = () => {
    if (!routineTitle.trim()) return;
    const duration = calculateDuration();
    const newRoutine: RoutineItem = {
      id: Math.random().toString(36).substr(2, 9),
      title: routineTitle,
      icon: routineIcon,
      days: routineDays,
      startTime: routineStartTime,
      startPeriod: routineStartPeriod,
      endTime: routineEndTime,
      endPeriod: routineEndPeriod,
      durationMinutes: duration,
      completedDates: []
    };
    onUpdate({ routines: [...(user.routines || []), newRoutine] });
    setIsAddingRoutine(false);
    onReward();
    triggerAnimation('routine');
  };

  const startRoutine = (r: RoutineItem) => {
    setActiveRoutineId(r.id);
    setTimerLeft(r.durationMinutes * 60); // In seconds
  };

  const completeRoutine = (id: string) => {
    const todayStr = new Date().toISOString().split('T')[0];
    onUpdate({
      routines: user.routines.map(r => r.id === id ? { ...r, completedDates: [...r.completedDates, todayStr] } : r)
    });
    onReward();
    triggerAnimation('routine');
  };

  const deleteRoutine = (id: string) => {
    onUpdate({ routines: user.routines.filter(r => r.id !== id) });
  };

  const toggleDay = (d: number) => {
    if (routineDays.includes(d)) setRoutineDays(routineDays.filter(day => day !== d));
    else setRoutineDays([...routineDays, d].sort());
  };

  return (
    <div className="flex flex-col h-full space-y-6 pb-20">
      <div className="flex gap-2 overflow-x-auto no-scrollbar pb-2 shrink-0">
        {(['Express', 'Schedule', 'Routine', 'Wisdom'] as const).map(tabName => (
          <button 
            key={tabName} 
            onClick={() => setSubTab(tabName)}
            className={`px-6 py-3 rounded-full font-black text-xs uppercase transition-all whitespace-nowrap border-b-4 ${subTab === tabName ? 'bg-red-600 text-white shadow-lg translate-y-[-2px]' : isDarkMode ? 'bg-white/5 border-black text-white/40' : 'bg-white border-gray-100 text-slate-500 shadow-sm'}`}
          >
            {t(tabName.toLowerCase() as any, language)}
          </button>
        ))}
      </div>

      <div className="flex-1">
        <AnimatePresence mode="wait">
          {subTab === 'Express' && (
            <motion.div key="express" initial={{ opacity: 0 }} animate={{ opacity: 1 }} className={`p-10 rounded-[3rem] ${isDarkMode ? 'bg-[#111]' : 'bg-white'} border-4 border-black/5 shadow-xl`}>
               <h3 className="text-3xl font-black uppercase italic tracking-tighter mb-8 flex items-center gap-3"><Send className="text-red-500"/> Metropolis Express</h3>
               <div className="space-y-6">
                  <div>
                    <p className="text-[10px] font-black uppercase opacity-40 tracking-widest mb-2 ml-4">Recipient Identity</p>
                    <input value={recipient} onChange={e => { setRecipient(e.target.value); setExpressError(''); }} placeholder="@username..." className="w-full p-4 rounded-2xl border-2 bg-black/5 font-black outline-none focus:border-red-500" />
                  </div>
                  <div>
                    <p className="text-[10px] font-black uppercase opacity-40 tracking-widest mb-2 ml-4">Message Frequencies</p>
                    <textarea value={letter} onChange={e => setLetter(e.target.value)} placeholder="Pour your neural state into words..." className="w-full p-6 rounded-[2rem] border-2 bg-black/5 font-bold outline-none focus:border-red-500 min-h-[200px]" />
                  </div>
                  {expressError && (
                      <motion.div initial={{ opacity: 0, y: -10 }} animate={{ opacity: 1, y: 0 }} className="p-4 bg-red-100 text-red-600 rounded-xl font-black text-xs flex items-center gap-2">
                          <AlertTriangle size={16}/> {expressError}
                      </motion.div>
                  )}
                  <button onClick={handleSendExpress} className="kahoot-button-red w-full py-5 rounded-2xl text-white font-black uppercase shadow-lg">{t('sendMail', language)}</button>
               </div>
            </motion.div>
          )}

          {subTab === 'Schedule' && (
             <motion.div key="schedule" initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="space-y-6">
                <div className="flex justify-between items-center px-4">
                   <h3 className="text-3xl font-black uppercase italic tracking-tighter flex items-center gap-3"><Calendar className="text-blue-500"/> Citizen Slated</h3>
                   <button onClick={() => setIsAddingSchedule(true)} className="kahoot-button-blue px-6 py-3 rounded-2xl text-white font-black text-xs flex items-center gap-2 shadow-lg"><Plus size={18} /> {t('newTask', language)}</button>
                </div>
                {/* Existing Schedule List rendering */}
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  {user.schedule.length > 0 ? user.schedule.sort((a,b)=>a.date.localeCompare(b.date)).map(item => (
                    <div key={item.id} className={`p-6 rounded-[2.5rem] ${isDarkMode ? 'bg-[#111]' : 'bg-white'} border-4 border-black/5 shadow-md flex items-center gap-4`}>
                       <div className={`w-12 h-12 rounded-xl flex items-center justify-center shadow-inner ${item.alerted ? 'bg-green-500 text-white' : 'bg-blue-600 text-white'}`}>
                          {item.alerted ? <Check size={24}/> : <Clock size={24}/>}
                       </div>
                       <div className="flex-1 min-w-0">
                          <h5 className="font-black text-sm uppercase truncate">{item.title}</h5>
                          <p className="text-[10px] font-black opacity-30 uppercase tracking-widest">{item.date} • {item.time} {item.period}</p>
                       </div>
                       <button onClick={() => handleCompleteSchedule(item.id)} className="px-4 py-2 bg-green-500 text-white rounded-xl font-black text-[10px] uppercase shadow-md active:scale-95">
                           Done
                       </button>
                    </div>
                  )) : <div className="col-span-full py-20 text-center opacity-20 font-black uppercase text-lg italic tracking-widest">{t('noEntries', language)}</div>}
               </div>

                {isAddingSchedule && (
                  <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-black/90 backdrop-blur-md">
                    <motion.div initial={{ scale: 0.9 }} animate={{ scale: 1 }} className={`${isDarkMode ? 'bg-slate-900' : 'bg-white'} w-full max-w-lg rounded-[3rem] p-10 shadow-2xl border-4 border-white/10 relative`}>
                      <button onClick={() => setIsAddingSchedule(false)} className="absolute top-6 right-6 opacity-40"><X size={32}/></button>
                      <h3 className="text-3xl font-black uppercase italic mb-8">Slate New Task</h3>
                      <div className="space-y-4">
                        <input value={schedTitle} onChange={e => setSchedTitle(e.target.value)} placeholder="Task Designation..." className="w-full p-4 rounded-xl border-2 bg-black/5 font-black outline-none focus:border-blue-500" />
                        <div className="grid grid-cols-2 gap-4">
                          <input type="date" value={schedDate} onChange={e => setSchedDate(e.target.value)} className="w-full p-4 rounded-xl border-2 bg-black/5 font-black outline-none focus:border-blue-500" />
                          <div className="flex gap-2">
                             <input type="time" value={schedTime} onChange={e => setSchedTime(e.target.value)} className="flex-1 p-4 rounded-xl border-2 bg-black/5 font-black outline-none focus:border-blue-500" />
                             <select value={schedPeriod} onChange={e => setSchedPeriod(e.target.value as any)} className="p-4 rounded-xl border-2 bg-black/5 font-black outline-none focus:border-blue-500">
                               <option>AM</option>
                               <option>PM</option>
                             </select>
                          </div>
                        </div>
                        <button onClick={handleAddSchedule} className="kahoot-button-blue w-full py-5 rounded-2xl text-white font-black uppercase shadow-lg mt-4">COMMIT TO GRID</button>
                      </div>
                    </motion.div>
                  </div>
               )}
             </motion.div>
          )}

          {subTab === 'Routine' && (
             <motion.div key="routine" initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="space-y-6">
               <div className="flex justify-between items-center px-4">
                   <h3 className="text-3xl font-black uppercase italic tracking-tighter flex items-center gap-3"><Clock className="text-purple-500"/> Daily Routine</h3>
                   <button onClick={() => setIsAddingRoutine(true)} className="kahoot-button-purple px-6 py-3 rounded-2xl text-white font-black text-xs flex items-center gap-2 shadow-lg"><Plus size={18} /> {t('newRoutine', language)}</button>
               </div>

               <div className="grid grid-cols-1 gap-4">
                  {(user.routines || []).map(r => {
                    const todayStr = new Date().toISOString().split('T')[0];
                    const isCompleted = r.completedDates.includes(todayStr);
                    return (
                      <div key={r.id} className={`p-6 rounded-[2.5rem] ${isDarkMode ? 'bg-[#111]' : 'bg-white'} border-4 ${isCompleted ? 'border-green-500/20 opacity-60' : 'border-black/5'} shadow-md flex items-center gap-4 relative overflow-hidden transition-all`}>
                         <div className={`w-14 h-14 rounded-2xl flex items-center justify-center text-3xl ${isCompleted ? 'bg-green-100 grayscale' : 'bg-black/5'}`}>{r.icon}</div>
                         <div className="flex-1">
                            <h5 className={`font-black text-lg uppercase ${isCompleted ? 'line-through opacity-50' : ''}`}>{r.title}</h5>
                            <p className="text-[10px] font-black opacity-40 uppercase tracking-widest">{r.startTime} {r.startPeriod} - {r.endTime} {r.endPeriod} ({r.durationMinutes}m)</p>
                            <div className="flex gap-1 mt-1 opacity-40">
                              {['S','M','T','W','T','F','S'].map((d,i) => <span key={i} className={`text-[9px] font-black ${r.days.includes(i) ? 'text-indigo-500' : 'text-gray-400'}`}>{d}</span>)}
                            </div>
                         </div>
                         {isCompleted ? (
                           <div className="bg-green-500 text-white px-4 py-2 rounded-xl font-black text-xs uppercase shadow-md flex items-center gap-2">
                               <Check size={14}/> {t('complete', language)}
                           </div>
                         ) : (
                           <button onClick={() => startRoutine(r)} className="kahoot-button-green px-4 py-2 rounded-xl text-white font-black text-xs uppercase shadow-md flex items-center gap-2"><Play size={14}/> {t('startTask', language)}</button>
                         )}
                         <button onClick={() => deleteRoutine(r.id)} className="absolute top-4 right-4 opacity-10 hover:opacity-100 transition-opacity"><Trash2 size={16}/></button>
                      </div>
                    );
                  })}
               </div>

               {/* Add Routine Modal */}
               {isAddingRoutine && (
                  <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-black/90 backdrop-blur-md">
                    <motion.div initial={{ scale: 0.9 }} animate={{ scale: 1 }} className={`${isDarkMode ? 'bg-slate-900' : 'bg-white'} w-full max-w-lg rounded-[3rem] p-10 shadow-2xl border-4 border-white/10 relative`}>
                      <button onClick={() => setIsAddingRoutine(false)} className="absolute top-6 right-6 opacity-40"><X size={32}/></button>
                      <h3 className="text-3xl font-black uppercase italic mb-8">Slate Routine</h3>
                      <div className="space-y-4">
                        <input value={routineTitle} onChange={e => setRoutineTitle(e.target.value)} placeholder="Routine Name..." className="w-full p-4 rounded-xl border-2 bg-black/5 font-black outline-none focus:border-purple-500" />
                        <input value={routineIcon} onChange={e => setRoutineIcon(e.target.value)} placeholder="Emoji Icon..." className="w-full p-4 rounded-xl border-2 bg-black/5 font-black outline-none focus:border-purple-500" maxLength={2} />

                        <div className="flex gap-2 justify-between">
                           {['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map((d,i) => (
                             <button key={d} onClick={() => toggleDay(i)} className={`w-8 h-8 rounded-full text-[9px] font-black uppercase ${routineDays.includes(i) ? 'bg-purple-600 text-white' : 'bg-black/10'}`}>{d[0]}</button>
                           ))}
                        </div>

                        <div className="grid grid-cols-2 gap-4">
                           <div className="space-y-1">
                             <p className="text-[9px] font-black uppercase opacity-40">Start</p>
                             <div className="flex gap-2"><input type="time" value={routineStartTime} onChange={e => setRoutineStartTime(e.target.value)} className="flex-1 p-3 rounded-xl border-2 bg-black/5 font-black"/><select value={routineStartPeriod} onChange={e=>setRoutineStartPeriod(e.target.value as any)} className="p-3 bg-black/5 rounded-xl font-black"><option>AM</option><option>PM</option></select></div>
                           </div>
                           <div className="space-y-1">
                             <p className="text-[9px] font-black uppercase opacity-40">End</p>
                             <div className="flex gap-2"><input type="time" value={routineEndTime} onChange={e => setRoutineEndTime(e.target.value)} className="flex-1 p-3 rounded-xl border-2 bg-black/5 font-black"/><select value={routineEndPeriod} onChange={e=>setRoutineEndPeriod(e.target.value as any)} className="p-3 bg-black/5 rounded-xl font-black"><option>AM</option><option>PM</option></select></div>
                           </div>
                        </div>

                        <button onClick={handleAddRoutine} className="kahoot-button-purple w-full py-5 rounded-2xl text-white font-black uppercase shadow-lg mt-4">COMMIT TO GRID</button>
                      </div>
                    </motion.div>
                  </div>
               )}

               {/* Timer Modal */}
               {activeRoutineId && (
                  <div className="fixed inset-0 z-[150] flex items-center justify-center bg-purple-900/90 backdrop-blur-xl">
                     <div className="text-center text-white">
                        <Timer size={60} className="mx-auto mb-6 animate-pulse"/>
                        <h2 className="text-4xl font-black italic uppercase mb-2">Routine Active</h2>
                        <h1 className="text-8xl font-black tabular-nums mb-8">
                           {Math.floor(timerLeft / 60).toString().padStart(2,'0')}:{(timerLeft % 60).toString().padStart(2,'0')}
                        </h1>
                        <button onClick={() => { setActiveRoutineId(null); setTimerLeft(0); }} className="px-8 py-3 bg-white/20 rounded-full font-black uppercase text-xs hover:bg-white/40">Cancel Timer</button>
                     </div>
                  </div>
               )}
             </motion.div>
          )}

          {subTab === 'Wisdom' && (
            <motion.div key="wisdom" initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="space-y-6">
               <div className={`p-10 rounded-[4rem] ${isDarkMode ? 'bg-[#111]' : 'bg-white'} border-4 border-black/5 shadow-xl text-center relative overflow-hidden`}>
                  <Sparkles className="absolute -top-10 -right-10 text-yellow-500/10" size={200} />
                  <p className="text-[10px] font-black opacity-30 uppercase tracking-[0.4em] mb-6">Metropolis Insight</p>
                  <p className="text-3xl md:text-5xl font-black italic tracking-tighter leading-tight mb-8">"{dailyWisdom.words}"</p>
               </div>

               <div className={`p-10 rounded-[3rem] ${isDarkMode ? 'bg-[#111]' : 'bg-white'} border-4 border-black/5 shadow-xl flex flex-col md:flex-row items-center gap-8`}>
                  <div className="w-32 h-32 rounded-[2rem] shadow-2xl border-b-8 border-black/20 flex items-center justify-center shrink-0" style={{ backgroundColor: dailyWisdom.color.hex }}>
                     <Palette size={48} className="text-white" />
                  </div>
                  <div className="flex-1 text-center md:text-left">
                     <p className="text-[10px] font-black opacity-30 uppercase tracking-widest mb-1">Lucky Resonance Color</p>
                     <h4 className="text-4xl font-black italic uppercase tracking-tighter" style={{ color: dailyWisdom.color.hex }}>{dailyWisdom.color.name}</h4>
                     <p className="text-sm font-bold opacity-60 mt-2 uppercase tracking-tight">Today's Alignment: <span className="text-black dark:text-white">{dailyWisdom.color.meaning}</span></p>
                  </div>
               </div>
            </motion.div>
          )}
        </AnimatePresence>
      </div>
    </div>
  );
};

export default CityHallSection;

import React, { useState, useMemo, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { User, Mood, DiaryEntry } from '../types';
import { LineChart, Line, BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';
import { TrendingUp, Book, Brain, Sparkles, Plus, X, Trash2, HeartPulse, Zap } from 'lucide-react';
import MoodPetSection from './MoodPetSection';
import { t } from '../constants';
import { getFortune } from '../services/geminiService';

interface MoodSectionProps {
  user: User;
  onUpdate: (updates: Partial<User>) => void;
  isDarkMode: boolean;
  language: 'English' | 'Filipino';
  onReward: () => void;
  triggerAnimation: (type: 'express' | 'schedule' | 'routine' | 'diary' | 'alarm', text?: string) => void;
}

const MoodSection: React.FC<MoodSectionProps> = ({ user, onUpdate, isDarkMode, language, onReward, triggerAnimation }) => {
  const [subTab, setSubTab] = useState<'Statistics' | 'Diary' | 'Mood Pet' | 'Scan' | 'Teller'>('Statistics');

  // Diary States
  const [isAddingDiary, setIsAddingDiary] = useState(false);
  const [diaryTitle, setDiaryTitle] = useState('');
  const [diaryContent, setDiaryContent] = useState('');
  const [diaryMood, setDiaryMood] = useState<Mood>('Normal');

  // Scan States
  const [scanStep, setScanStep] = useState(0);
  const [scanScores, setScanScores] = useState<Record<string, number>>({});
  const [scanResult, setScanResult] = useState<Mood | null>(null);

  // Teller States
  const [fortuneQuestion, setFortuneQuestion] = useState('');
  const [fortuneAnswer, setFortuneAnswer] = useState('');
  const [isConsulting, setIsConsulting] = useState(false);

  // Statistics Data
  const lineData = useMemo(() => {
    return user.moodHistory.slice(-14).map((entry, i) => ({ name: `Day ${i + 1}`, score: entry.score }));
  }, [user.moodHistory]);

  const barData = useMemo(() => {
    const counts: Record<string, number> = { Wonderful: 0, Excited: 0, Happy: 0, Normal: 0, Tired: 0, Angry: 0, Flaming: 0 };
    user.moodHistory.forEach(e => { if (e.mood) counts[e.mood]++; });
    return Object.entries(counts).map(([name, val]) => ({ name, val }));
  }, [user.moodHistory]);

  const handleSaveDiary = () => {
    if (!diaryTitle.trim() || !diaryContent.trim()) return;
    const newEntry: DiaryEntry = {
      id: Math.random().toString(36).substr(2, 9),
      title: diaryTitle,
      content: diaryContent,
      mood: diaryMood,
      timestamp: Date.now()
    };
    onUpdate({ diaryEntries: [newEntry, ...user.diaryEntries] });
    setIsAddingDiary(false);
    setDiaryTitle('');
    setDiaryContent('');

    // Reward
    onReward();
    triggerAnimation('diary');
  };

  const handleScanAnswer = (moodImpact: Mood) => {
    if (moodImpact) {
      setScanScores(prev => ({ ...prev, [moodImpact]: (prev[moodImpact] || 0) + 1 }));
    }

    if (scanStep < SCAN_QUESTIONS.length - 1) {
      setScanStep(scanStep + 1);
    } else {
      // Calculate Result
      const scores = { ...scanScores };
      if (moodImpact) scores[moodImpact] = (scores[moodImpact] || 0) + 1;

      const sorted = Object.entries(scores).sort((a: [string, number], b: [string, number]) => b[1] - a[1]);
      setScanResult((sorted[0]?.[0] as Mood) || 'Normal');
    }
  };

  const resetScan = () => {
    setScanStep(0);
    setScanScores({});
    setScanResult(null);
  };

  const handleFortune = async () => {
    if(!fortuneQuestion.trim()) return;
    setIsConsulting(true);
    setFortuneAnswer('');
    try {
        const answer = await getFortune(fortuneQuestion);
        setFortuneAnswer(answer);
    } catch(e) {
        setFortuneAnswer("The spirits are silent.");
    } finally {
        setIsConsulting(false);
    }
  };

  const SCAN_QUESTIONS = [
    { q: "How fast is your heart beating right now?", opts: [{ l: "Very fast!", m: "Excited" }, { l: "Calm", m: "Normal" }, { l: "A bit heavy", m: "Tired" }, { l: "Pounding!", m: "Angry" }] },
    { q: "Do you feel like dancing?", opts: [{ l: "Yes, definitely!", m: "Wonderful" }, { l: "Maybe later", m: "Happy" }, { l: "Too tired", m: "Tired" }, { l: "Not at all", m: "Angry" }] },
    { q: "How bright does the screen look?", opts: [{ l: "Perfectly vibrant", m: "Excited" }, { l: "Okay", m: "Normal" }, { l: "A bit dull", m: "Tired" }, { l: "It's annoying", m: "Angry" }] },
    { q: "Pick an emoji!", opts: [{ l: "✨", m: "Wonderful" }, { l: "🔥", m: "Flaming" }, { l: "💤", m: "Tired" }, { l: "😐", m: "Normal" }] },
    { q: "Are you hungry?", opts: [{ l: "For a feast!", m: "Excited" }, { l: "Just a snack", m: "Happy" }, { l: "No, too stressed", m: "Angry" }, { l: "Just thirsty", m: "Normal" }] },
    { q: "What's the vibe of your thoughts?", opts: [{ l: "Clear and sunny", m: "Wonderful" }, { l: "Steady flow", m: "Normal" }, { l: "Racing like a car", m: "Excited" }, { l: "Stuck in mud", m: "Tired" }] },
  ];

  return (
    <div className="flex flex-col h-full space-y-6 pb-20">
      <div className="flex gap-2 overflow-x-auto no-scrollbar pb-2 shrink-0">
        {(['Statistics', 'Diary', 'Mood Pet', 'Scan', 'Teller'] as const).map(tabName => (
