                      ) : (
                          <div className="space-y-8">
                              <div className="p-8 bg-purple-500/10 rounded-[2rem] border-2 border-purple-500/20">
                                  <h3 className="text-2xl md:text-3xl font-black italic text-purple-600 mb-2">The Spirits Say...</h3>
                                  <p className="text-lg font-bold">"{fortuneAnswer}"</p>
