      // We no longer auto-load user from local storage to enforce worldwide sync logic
      // But for better UX, if they were logged in, they stay logged in via local cache 
      // UNLESS we want strict security. Let's rely on AuthScreen for the main entry 
      // to ensure fresh data fetch.

      setIsLoaded(true);
      setTimeout(() => setIsAppStarting(false), 2000);
    };
    init();
  }, []);

  // Save State and Sync to Cloud whenever currentUser changes
  useEffect(() => {
    if (currentUser && currentUser.id) {
      syncProfile(currentUser);
    }
  }, [currentUser]);

  // Polling for Worldwide Messages
  useEffect(() => {
    if (!currentUser) return;

    const pollMessages = async () => {
      const messages = await fetchUserMessages(currentUser.username);

      // Convert to notifications
      const mailNotifications: Notification[] = messages.map((m: any) => ({
        id: m.id,
        type: 'mail',
        title: `From @${m.sender}`,
        text: m.text,
        timestamp: m.timestamp,
        read: false 
      }));

      setNotifications(prev => {
        const existingIds = new Set(prev.map(n => n.id));
        const newMails = mailNotifications.filter((n: Notification) => !existingIds.has(n.id));
        if (newMails.length > 0) {
           showToast("New Mail", `${newMails.length} new message(s) received from the cloud.`);
        }
        return [...newMails, ...prev];
      });
    };

    // Initial fetch
    pollMessages();

    // Poll every 10 seconds for new mail
    const interval = setInterval(pollMessages, 10000);
    return () => clearInterval(interval);
  }, [currentUser]);

  // Daily Mood Check Trigger - STRICT DATE CHECK
  useEffect(() => {
    if (currentUser) {
      const today = new Date().toDateString();
      // Check if the user has ALREADY done it today based on Cloud Data
      if (currentUser.lastMoodDate !== today) {
        setShowMoodCheckIn(true);
      } else {
        setShowMoodCheckIn(false);
      }
    }
  }, [currentUser?.username]); // Only run when username changes (login)

  const showToast = (title: string, msg: string, icon?: any) => {
    setActiveToast({ title, msg, icon });
    setTimeout(() => setActiveToast(null), 3000);
  };

  const triggerAnimation = (type: AnimationType, text?: string) => {
    setCentralAnimation({ type, text });
    setTimeout(() => setCentralAnimation(null), 3500);
  };

  const handleGainReward = useCallback((amount: number = 1, exp: number = 20) => {
    setCurrentUser(prev => {
       if(!prev) return null;
       let nextExp = prev.petExp + exp;
       let nextLevel = prev.petLevel;
       const needed = getExpNeeded(nextLevel);
       if (nextExp >= needed) {
         nextExp -= needed;
         nextLevel++;
         showToast("LEVEL UP!", `Pet reached Rank ${nextLevel}`, <Trophy size={20} className="text-yellow-400"/>);
       }
       return {
         ...prev,
         moodCoins: prev.moodCoins + amount,
         petExp: nextExp,
         petLevel: nextLevel
       };
    });
  }, []);

  // Schedule & Routine Alert Logic
  useEffect(() => {
    if (!currentUser) return;
    const interval = setInterval(() => {
      const now = new Date();
      const todayStr = now.toISOString().split('T')[0];
      const hours = now.getHours();
      const mins = now.getMinutes();
      const currentPeriod = hours >= 12 ? 'PM' : 'AM';
      const hours12 = hours % 12 || 12;
      const currentFormattedTime = `${hours12.toString().padStart(2, '0')}:${mins.toString().padStart(2, '0')}`;
      const dayOfWeek = now.getDay(); 

      // Check Schedule
      currentUser.schedule.forEach(item => {
        if (!item.alerted && item.date === todayStr && item.time === currentFormattedTime && item.period === currentPeriod) {
          triggerAnimation('alarm', `IT'S TIME: ${item.title}`);
          const newNotif: Notification = {
            id: Math.random().toString(36).substr(2, 9),
            type: 'schedule',
            title: t('taskAlert', language),
            text: `${t('taskTime', language)} ${item.title}`,
            timestamp: Date.now(),
            read: false
          };
          setNotifications(prev => [...prev, newNotif]);

          setCurrentUser(prev => {
            if (!prev) return prev;
            return {
              ...prev,
              schedule: prev.schedule.map(s => s.id === item.id ? { ...s, alerted: true } : s)
            };
          });
        }
      });

      // Check Routines
      currentUser.routines.forEach(routine => {
        if (routine.days.includes(dayOfWeek) && 
            routine.startTime === currentFormattedTime && 
            routine.startPeriod === currentPeriod &&
            !routine.completedDates.includes(todayStr)) {

             const alreadyNotified = notifications.some(n => n.type === 'routine' && n.text.includes(routine.title) && (Date.now() - n.timestamp < 60000));
             if (!alreadyNotified) {
                 triggerAnimation('alarm', `ROUTINE START: ${routine.title}`);
                 const newNotif: Notification = {
                    id: Math.random().toString(36).substr(2, 9),
                    type: 'routine',
                    title: t('taskAlert', language),
                    text: `${t('taskTime', language)} ${routine.title}`,
                    timestamp: Date.now(),
                    read: false
                  };
                 setNotifications(prev => [...prev, newNotif]);
             }
        }
      });

    }, 5000); 
    return () => clearInterval(interval);
  }, [currentUser, language, notifications]);

  const handleMoodSubmit = (mood: Mood) => {
    if (!currentUser) return;
    const today = new Date().toDateString();
    const score = mood ? MOOD_SCORES[mood] : 50;

    handleGainReward(1, 50);
    showToast(t('rewardTitle', language), t('rewardMsg', language), <Coins size={20} className="text-yellow-400" />);

    setCurrentUser(prev => {
      if (!prev) return prev;
      const history = [...prev.moodHistory, { date: today, mood, score }];

      let newStreak = prev.moodStreak;
      if (prev.lastMoodDate) {
         const lastDate = new Date(prev.lastMoodDate);
         const diffTime = Math.abs(new Date(today).getTime() - lastDate.getTime());
         const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
         if (diffDays === 1) newStreak++;
         else if (diffDays > 1) newStreak = 1;
      } else {
         newStreak = 1;
      }

      const updatedUser = {
        ...prev,
        moodHistory: history,
        lastMoodDate: today, // IMPORTANT: Setting this ensures it won't show again today
        moodStreak: newStreak,
      };

      // Force immediate sync to cloud to prevent re-appearance on other devices
      syncProfile(updatedUser);
      return updatedUser;
    });
    setShowMoodCheckIn(false);
  };

  const handleUpdateUser = (updates: Partial<User>) => {
    setCurrentUser(prev => prev ? { ...prev, ...updates } : null);
  };

  const handleLogout = () => {
    setCurrentUser(null);
    localStorage.removeItem('mooderia_user'); // Clear local cache
    setIsAppStarting(true);
    setTimeout(() => setIsAppStarting(false), 1000);
  };

  // Handle sending mail (Worldwide Cloud)
  const handleSendMail = async (recipient: string, message: string) => {
    if (!currentUser) return;

    const success = await sendMessageCloud(currentUser.username, recipient, message);

    if (success) {
      showToast("Sent!", `Express mail delivered to @${recipient} (Worldwide)`);
    } else {
      showToast("Error", "Failed to send mail. Check connection.");
    }
  };

  return (
    <div className={`min-h-screen transition-colors duration-500 overflow-hidden ${isDarkMode ? 'bg-[#0a0a0a] text-white' : 'bg-slate-50 text-slate-900'} font-sans selection:bg-indigo-500 selection:text-white`}>
       <AnimatePresence>
         {isAppStarting && <LoadingScreen key="loading" />}

         {!isAppStarting && !currentUser && (
           <AuthScreen key="auth" onLogin={(u) => { setCurrentUser(u); setIsLoaded(true); }} />
         )}

         {!isAppStarting && currentUser && (
           <div className="flex flex-col md:flex-row h-screen">
              <Sidebar 
                activeSection={activeSection} 
                onNavigate={setActiveSection} 
                isDarkMode={isDarkMode} 
                user={currentUser}
                unreadMails={notifications.filter(n => !n.read && n.type === 'mail').length}
                language={language}
              />

              <main className="flex-1 h-full overflow-y-auto relative p-4 md:p-8 no-scrollbar">
                <AnimatePresence mode="wait">
                  {activeSection === 'Home' && <motion.div key="home" initial={{opacity:0, y:20}} animate={{opacity:1, y:0}} exit={{opacity:0}}><HomeSection user={currentUser} isDarkMode={isDarkMode} language={language} /></motion.div>}

                  {activeSection === 'Mood' && <motion.div key="mood" initial={{opacity:0, y:20}} animate={{opacity:1, y:0}} exit={{opacity:0}} className="h-full"><MoodSection user={currentUser} onUpdate={handleUpdateUser} isDarkMode={isDarkMode} language={language} onReward={() => handleGainReward(1, 10)} triggerAnimation={triggerAnimation} /></motion.div>}

                  {activeSection === 'CityHall' && <motion.div key="cityhall" initial={{opacity:0, y:20}} animate={{opacity:1, y:0}} exit={{opacity:0}} className="h-full"><CityHallSection user={currentUser} onUpdate={handleUpdateUser} isDarkMode={isDarkMode} language={language} onReward={() => handleGainReward(2, 20)} triggerAnimation={triggerAnimation} onSendMail={handleSendMail} /></motion.div>}

                  {activeSection === 'Mails' && <motion.div key="mails" initial={{opacity:0, y:20}} animate={{opacity:1, y:0}} exit={{opacity:0}}><MailSection notifications={notifications} setNotifications={setNotifications} isDarkMode={isDarkMode} /></motion.div>}

                  {activeSection === 'Profile' && <motion.div key="profile" initial={{opacity:0, y:20}} animate={{opacity:1, y:0}} exit={{opacity:0}}><ProfileSection user={currentUser} onUpdate={handleUpdateUser} isDarkMode={isDarkMode} /></motion.div>}

                  {activeSection === 'Settings' && <motion.div key="settings" initial={{opacity:0, y:20}} animate={{opacity:1, y:0}} exit={{opacity:0}}>
                    <SettingsSection 
                      isDarkMode={isDarkMode} 
                      onToggleDarkMode={() => { setIsDarkMode(!isDarkMode); localStorage.setItem('mooderia_theme', !isDarkMode ? 'dark' : 'light'); }}
                      language={language}
                      onToggleLanguage={() => { setLanguage(l => l === 'English' ? 'Filipino' : 'English'); localStorage.setItem('mooderia_lang', language === 'English' ? 'Filipino' : 'English'); }}
                      onLogout={handleLogout}
                    />
                  </motion.div>}
                </AnimatePresence>
              </main>

              <AnimatePresence>
                {showMoodCheckIn && (
                  <MoodCheckIn onSubmit={handleMoodSubmit} isDarkMode={isDarkMode} />
                )}
              </AnimatePresence>

              {/* Central Animation Overlay */}
              <AnimatePresence>
                {centralAnimation && (
                  <motion.div 
                    initial={{ opacity: 0 }}
                    animate={{ opacity: 1 }}
                    exit={{ opacity: 0 }}
                    className="fixed inset-0 z-[200] flex flex-col items-center justify-center bg-black/80 backdrop-blur-md p-6 pointer-events-none"
                  >
                    <motion.div
                      initial={{ scale: 0.5, y: 50 }}
                      animate={{ scale: 1, y: 0 }}
                      exit={{ scale: 1.5, opacity: 0 }}
                      transition={{ type: "spring", bounce: 0.5 }}
                      className="bg-white p-12 rounded-[3rem] shadow-2xl text-center border-b-[12px] border-black/10 flex flex-col items-center gap-6 relative overflow-hidden w-full max-w-md"
                    >
                       <div className="absolute inset-0 bg-gradient-to-b from-white to-gray-50 -z-10" />

                       {centralAnimation.type === 'express' && (
                         <>
                           <motion.div animate={{ x: [-100, 0, 100], opacity: [0, 1, 0] }} transition={{ duration: 1.5, repeat: 1 }} className="absolute inset-0 flex items-center justify-center opacity-10"><Send size={200}/></motion.div>
                           <Send size={100} className="text-red-500 drop-shadow-xl" />
                           <h2 className="text-4xl font-black italic uppercase tracking-tighter text-slate-900">Express on the way!</h2>
                         </>
                       )}

                       {centralAnimation.type === 'schedule' && (
                         <>
                           <Calendar size={100} className="text-blue-500 drop-shadow-xl" />
                           <h2 className="text-4xl font-black italic uppercase tracking-tighter text-slate-900">Task Slated!</h2>
                           <p className="font-bold opacity-60 text-slate-700">Your calendar is synced.</p>
                         </>
                       )}

                       {centralAnimation.type === 'routine' && (
                         <>
                           <Clock size={100} className="text-purple-500 drop-shadow-xl" />
                           <h2 className="text-4xl font-black italic uppercase tracking-tighter text-slate-900">Routine Locked!</h2>
                           <p className="font-bold opacity-60 text-slate-700">Consistency creates reality.</p>
                         </>
                       )}

                       {centralAnimation.type === 'diary' && (
                         <>
                           <Book size={100} className="text-green-500 drop-shadow-xl" />
                           <h2 className="text-4xl font-black italic uppercase tracking-tighter text-slate-900">Memory Archived!</h2>
                         </>
                       )}

                       {centralAnimation.type === 'alarm' && (
                         <>
                           <motion.div animate={{ rotate: [-10, 10, -10] }} transition={{ repeat: Infinity, duration: 0.5 }}>
                              <Clock size={120} className="text-yellow-500 drop-shadow-xl" />
                           </motion.div>
                           <h2 className="text-5xl font-black italic uppercase tracking-tighter text-slate-900 text-center">{centralAnimation.text}</h2>
                         </>
                       )}
                    </motion.div>
                  </motion.div>
                )}
              </AnimatePresence>

              <AnimatePresence>
                {activeToast && (
                  <motion.div 
                    initial={{ opacity: 0, y: 50, scale: 0.8 }}
                    animate={{ opacity: 1, y: 0, scale: 1 }}
                    exit={{ opacity: 0, scale: 0.8 }}
                    className="fixed bottom-24 md:bottom-10 right-4 md:right-10 z-[100] bg-white dark:bg-slate-800 p-4 rounded-2xl shadow-2xl border-2 border-black/5 flex items-center gap-4 max-w-sm"
                  >
                     <div className="bg-indigo-100 dark:bg-indigo-900 p-2 rounded-xl">
                       {activeToast.icon || <Sparkles className="text-indigo-600" size={20} />}
                     </div>
                     <div>
                       <h5 className="font-black uppercase text-xs">{activeToast.title}</h5>
                       <p className="text-sm font-bold opacity-70">{activeToast.msg}</p>
                     </div>
                  </motion.div>
                )}
              </AnimatePresence>
           </div>
         )}
       </AnimatePresence>
    </div>
  );
};

