import { createClient } from '@supabase/supabase-js';
import { User, Message } from '../types';

// ------------------------------------------------------------------
// ⚡️ SETUP REQUIRED:
// 1. Create a free project at https://supabase.com
// 2. Paste your Project URL and Anon Key below.
// 3. Run the SQL script provided in the chat to create tables.
// ------------------------------------------------------------------

const supabaseUrl = ''; // e.g. 'https://xyzcompany.supabase.co'
const supabaseAnonKey = ''; // e.g. 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9...'

// Check if keys are set
const hasKeys = supabaseUrl !== '' && supabaseAnonKey !== '';

export const supabase = hasKeys ? createClient(supabaseUrl, supabaseAnonKey) : null;

export const isCloudEnabled = hasKeys;

// --- AUTHENTICATION & USER MANAGEMENT ---

export const loginUser = async (username: string, passwordAttempt: string): Promise<{ success: boolean; user?: User; error?: string }> => {
  if (!isCloudEnabled || !supabase) return { success: false, error: "Setup Required: Add Supabase Keys in code." };

  try {
    // Fetch profile by username
    const { data, error } = await supabase
      .from('profiles')
      .select('*')
      .eq('username', username)
      .single();

    if (error || !data) {
      return { success: false, error: "Identity not found in Metropolis database." };
    }

    // Check password (stored in metadata for this specific architecture)
    const user = data.metadata as User;
    // @ts-ignore
    if (user.password !== passwordAttempt) {
      return { success: false, error: "Incorrect Access Phrase." };
    }

    return { success: true, user: user };
  } catch (e) {
    return { success: false, error: "Connection error. Check console." };
  }
};

export const registerUser = async (user: User, password: string): Promise<{ success: boolean; error?: string }> => {
  if (!isCloudEnabled || !supabase) return { success: false, error: "Setup Required: Add Supabase Keys in code." };

  try {
    // 1. Check if username exists
    const { data: existing } = await supabase
      .from('profiles')
      .select('username')
      .eq('username', user.username)
      .single();

    if (existing) {
      return { success: false, error: "Username already occupied." };
    }

    // 2. Create User ID
    const newId = crypto.randomUUID();

    // 3. Store user with password in metadata
    // @ts-ignore
    const userWithAuth = { ...user, password: password, id: newId };

    const { error } = await supabase
      .from('profiles')
      .insert({
        id: newId,
        username: user.username,
        display_name: user.displayName,
        email: user.email,
        metadata: userWithAuth,
        updated_at: new Date().toISOString()
      });

    if (error) {
      console.error(error);
      return { success: false, error: "Registration failed. Check SQL setup." };
    }

    return { success: true };
  } catch (e) {
    return { success: false, error: "Unknown error." };
  }
};

export const syncProfile = async (user: User) => {
  if (!isCloudEnabled || !supabase || !user.id) return;

  try {
    const { error } = await supabase
      .from('profiles')
      .update({
        display_name: user.displayName,
        metadata: user,
        updated_at: new Date().toISOString()
      })
      .eq('id', user.id);

    if (error) console.error("Sync Error", error);
  } catch (e) {
    // Silent catch
  }
};

// --- MESSAGING SYSTEM ---

export const fetchUserMessages = async (username: string): Promise<Message[]> => {
  if (!isCloudEnabled || !supabase) return [];
  try {
    const { data, error } = await supabase
      .from('messages')
      .select('*')
      .eq('recipient', username);

    if (error) return [];

    return data.map(m => ({
      id: m.id,
      sender: m.sender,
      recipient: m.recipient,
      text: m.text,
      timestamp: new Date(m.created_at).getTime(),
      read: false
    }));
  } catch (e) {
    return [];
  }
};

export const sendMessageCloud = async (sender: string, recipient: string, text: string) => {
  if (!isCloudEnabled || !supabase) return false;
  try {
    const { error } = await supabase.from('messages').insert({
      sender,
      recipient,
      text
    });
    if (error) console.error("Message send failed", error);
    return !error;
  } catch (e) {
    return false;
  }
};

import React, { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import { User } from '../types';
import { LogIn, UserPlus, Building2, Loader2, AlertTriangle } from 'lucide-react';
import { loginUser, registerUser, isCloudEnabled } from '../services/supabaseService';

interface AuthScreenProps {
  onLogin: (user: User) => void;
}

const AuthScreen: React.FC<AuthScreenProps> = ({ onLogin }) => {
  const [mode, setMode] = useState<'login' | 'signup'>('login');
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [displayName, setDisplayName] = useState('');
  const [error, setError] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  useEffect(() => {
    if (!isCloudEnabled) {
      setError("Setup Mode: Please add your Supabase URL & Key in 'services/supabaseService.ts' to enable the Worldwide Grid.");
    }
  }, []);

  const handleAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!username || !password) return;
    if (!isCloudEnabled) {
        setError("Cannot connect: Missing Supabase Keys.");
        return;
    }

    setError('');
    setIsLoading(true);

    try {
      if (mode === 'signup') {
        const newUser: User = {
          displayName: displayName || username,
          username: username,
          email: `${username}@mooderia.local`,
          moodHistory: [],
          diaryEntries: [],
          schedule: [],
          routines: [],
          moodStreak: 0,
          moodCoins: 0, 
          petName: 'Guardian',
          petEmoji: '🐱',
          petLevel: 1,
          petExp: 0,
          petHasBeenChosen: false,
          petBackground: 'default',
          unlockedBackgrounds: ['default'],
          following: [],
          followers: [],
          likesReceived: 0,
          title: 'Citizen'
        };

        const result = await registerUser(newUser, password);

        if (!result.success) {
          setError(result.error || 'Registration failed.');
        } else {
          const loginResult = await loginUser(username, password);
          if (loginResult.success && loginResult.user) {
             onLogin(loginResult.user);
          }
        }
      } else {
        // Login Mode
        const result = await loginUser(username, password);
        if (result.success && result.user) {
          onLogin(result.user);
        } else {
          setError(result.error || 'Login failed.');
        }
      }
    } catch (err) {
      setError('A system error occurred. Check connection.');
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-[#46178f] flex items-center justify-center p-6 relative overflow-hidden">
      {/* Cityscape Background Overlay */}
      <div className="absolute inset-0 opacity-10 pointer-events-none flex items-end justify-center">
        <Building2 size={600} className="text-white" />
      </div>

      <motion.div 
        initial={{ y: 50, opacity: 0 }} 
        animate={{ y: 0, opacity: 1 }}
        className="w-full max-w-md bg-white rounded-[3rem] p-10 shadow-2xl relative z-10 border-b-[12px] border-black/10"
      >
        <div className="text-center mb-10">
           <h1 className="text-4xl md:text-5xl font-black italic text-indigo-600 tracking-tighter uppercase mb-2">Mooderia</h1>
           <p className="text-[10px] font-black uppercase tracking-[0.4em] opacity-30">Worldwide Neural Network</p>
        </div>

        <form onSubmit={handleAuth} className="space-y-4">
          {mode === 'signup' && (
            <input 
              value={displayName} 
              onChange={e => setDisplayName(e.target.value)} 
              placeholder="Full Name / Alias" 
              className="w-full p-4 rounded-2xl bg-black/5 font-black text-sm outline-none focus:border-indigo-500 border-2 border-transparent transition-all"
            />
          )}
          <input 
            value={username} 
            onChange={e => setUsername(e.target.value)} 
            placeholder="Unique Username" 
            className="w-full p-4 rounded-2xl bg-black/5 font-black text-sm outline-none focus:border-indigo-500 border-2 border-transparent transition-all"
          />
          <input 
            type="password" 
            value={password} 
            onChange={e => setPassword(e.target.value)} 
            placeholder="Access Phrase" 
            className="w-full p-4 rounded-2xl bg-black/5 font-black text-sm outline-none focus:border-indigo-500 border-2 border-transparent transition-all"
          />

          {error && (
             <div className="p-4 bg-red-100 rounded-2xl flex items-center gap-2 text-red-600 text-xs font-black uppercase leading-tight">
                 <AlertTriangle size={24} className="shrink-0"/>
                 <p>{error}</p>
             </div>
          )}

          <button 
            type="submit" 
            disabled={isLoading || !isCloudEnabled}
            className="kahoot-button-blue w-full py-5 rounded-2xl text-white font-black uppercase text-lg mt-4 shadow-xl active:scale-95 flex items-center justify-center gap-3 disabled:opacity-50 disabled:active:scale-100 disabled:cursor-not-allowed"
          >
             {isLoading ? <Loader2 className="animate-spin" /> : (mode === 'login' ? <LogIn size={20}/> : <UserPlus size={20}/>)}
             {isLoading ? 'Connecting...' : (mode === 'login' ? 'Synchronize' : 'Initialize ID')}
          </button>
        </form>

        <div className="mt-8 text-center">
           <button onClick={() => { setMode(mode === 'login' ? 'signup' : 'login'); setError(''); }} className="text-xs font-black uppercase tracking-widest text-indigo-600 hover:underline">
             {mode === 'login' ? 'Register as Citizen' : 'Return to Login Grid'}
           </button>
        </div>
      </motion.div>
    </div>
  );
};

export default AuthScreen;

import { User, Message } from '../types';

// --- SERVERLESS STORAGE MANAGER ---
// Since we removed Supabase, we use LocalStorage as the "Database".
// To sync across devices, we use a "Passport String" (Base64 encoded JSON).

export const isCloudEnabled = false;

// Helper to get all users
const getLocalUsers = (): Record<string, User> => {
  const data = localStorage.getItem('mooderia_users_db');
  return data ? JSON.parse(data) : {};
};

// Helper to save all users
const saveLocalUsers = (users: Record<string, User>) => {
  localStorage.setItem('mooderia_users_db', JSON.stringify(users));
};

// --- AUTHENTICATION ---

export const loginUser = async (username: string, passwordAttempt: string): Promise<{ success: boolean; user?: User; error?: string }> => {
  // Simulate network delay
  await new Promise(r => setTimeout(r, 500));

  const users = getLocalUsers();
  const user = users[username];

  if (!user) {
    return { success: false, error: "Citizen not found on this device." };
  }

  // In this serverless version, we check the password stored in the user object
  // @ts-ignore
  if (user.password !== passwordAttempt) {
    return { success: false, error: "Incorrect Access Phrase." };
  }

  return { success: true, user };
};

export const registerUser = async (user: User, password: string): Promise<{ success: boolean; error?: string }> => {
  await new Promise(r => setTimeout(r, 800));

  const users = getLocalUsers();

  if (users[user.username]) {
    return { success: false, error: "Username taken on this device." };
  }

  // Save password inside user object for local auth
  // @ts-ignore
  const newUser = { ...user, password, id: crypto.randomUUID() };

  users[user.username] = newUser;
  saveLocalUsers(users);

  return { success: true };
};

export const syncProfile = async (user: User) => {
  // Save changes to local storage
  const users = getLocalUsers();
  // Ensure we preserve the password
  const existing = users[user.username] || {};
  // @ts-ignore
  const password = existing.password || user.password; 

  // @ts-ignore
  users[user.username] = { ...user, password };
  saveLocalUsers(users);
};

// --- PASSPORT SYSTEM (Cross-Device Sync) ---

export const generateTransferCode = (user: User): string => {
    // 1. Get the full user data including hidden password
    const users = getLocalUsers();
    const fullUserData = users[user.username];

    if(!fullUserData) return '';

    // 2. Stringify and Encode to Base64 to make it look like a key
    const json = JSON.stringify(fullUserData);
    return btoa(unescape(encodeURIComponent(json)));
};

export const importTransferCode = (code: string): { success: boolean; user?: User; error?: string } => {
    try {
        // 1. Decode
        const json = decodeURIComponent(escape(atob(code)));
        const importedUser = JSON.parse(json) as User;

        if (!importedUser.username) throw new Error("Invalid ID");

        // 2. Save to this device
        const users = getLocalUsers();
        users[importedUser.username] = importedUser;
        saveLocalUsers(users);

        return { success: true, user: importedUser };
    } catch (e) {
        return { success: false, error: "Invalid Transfer Code." };
    }
};

// --- LOCAL MESSAGING ---
// Mails only work between users on the SAME device in this mode.

export const fetchUserMessages = async (username: string): Promise<Message[]> => {
  const allMails = JSON.parse(localStorage.getItem('mooderia_local_mails') || '[]');
  return allMails.filter((m: any) => m.recipient === username);
};

export const sendMessageCloud = async (sender: string, recipient: string, text: string) => {
  const allMails = JSON.parse(localStorage.getItem('mooderia_local_mails') || '[]');

  const newMail = {
    id: Math.random().toString(36).substr(2, 9),
    sender,
    recipient,
    text,
    created_at: new Date().toISOString()
  };

  localStorage.setItem('mooderia_local_mails', JSON.stringify([...allMails, newMail]));
  return true;
};

import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { User } from '../types';
import { LogIn, UserPlus, Building2, Loader2, AlertTriangle, Download, Upload } from 'lucide-react';
import { loginUser, registerUser, importTransferCode } from '../services/supabaseService';

interface AuthScreenProps {
  onLogin: (user: User) => void;
}

const AuthScreen: React.FC<AuthScreenProps> = ({ onLogin }) => {
  const [mode, setMode] = useState<'login' | 'signup' | 'import'>('login');
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [displayName, setDisplayName] = useState('');
  const [transferCode, setTransferCode] = useState('');
  const [error, setError] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  const handleAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setIsLoading(true);

    try {
      if (mode === 'import') {
        if (!transferCode) { setError("Please paste a code."); setIsLoading(false); return; }

        const result = importTransferCode(transferCode);
        if (result.success && result.user) {
            onLogin(result.user);
        } else {
            setError(result.error || "Import failed.");
        }

      } else if (mode === 'signup') {
        if (!username || !password) return;
        const newUser: User = {
          displayName: displayName || username,
          username: username,
          email: `${username}@mooderia.local`,
          moodHistory: [],
          diaryEntries: [],
          schedule: [],
          routines: [],
          moodStreak: 0,
          moodCoins: 0, 
          petName: 'Guardian',
          petEmoji: '🐱',
          petLevel: 1,
          petExp: 0,
          petHasBeenChosen: false,
          petBackground: 'default',
          unlockedBackgrounds: ['default'],
          following: [],
          followers: [],
          likesReceived: 0,
          title: 'Citizen'
        };

        const result = await registerUser(newUser, password);

        if (!result.success) {
          setError(result.error || 'Registration failed.');
        } else {
          const loginResult = await loginUser(username, password);
          if (loginResult.success && loginResult.user) {
             onLogin(loginResult.user);
          }
        }
      } else {
        // Login Mode
        if (!username || !password) return;
        const result = await loginUser(username, password);
        if (result.success && result.user) {
          onLogin(result.user);
        } else {
          setError(result.error || 'Login failed.');
        }
      }
    } catch (err) {
      setError('A system error occurred.');
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-[#46178f] flex items-center justify-center p-6 relative overflow-hidden">
      {/* Cityscape Background Overlay */}
      <div className="absolute inset-0 opacity-10 pointer-events-none flex items-end justify-center">
        <Building2 size={600} className="text-white" />
      </div>

      <motion.div 
        initial={{ y: 50, opacity: 0 }} 
        animate={{ y: 0, opacity: 1 }}
        className="w-full max-w-md bg-white rounded-[3rem] p-10 shadow-2xl relative z-10 border-b-[12px] border-black/10"
      >
        <div className="text-center mb-6">
           <h1 className="text-4xl md:text-5xl font-black italic text-indigo-600 tracking-tighter uppercase mb-2">Mooderia</h1>
           <p className="text-[10px] font-black uppercase tracking-[0.4em] opacity-30">Serverless Neural Grid</p>
        </div>

        {/* Tabs */}
        <div className="flex bg-black/5 p-1 rounded-2xl mb-6">
            <button onClick={() => setMode('login')} className={`flex-1 py-2 rounded-xl text-[10px] font-black uppercase ${mode === 'login' ? 'bg-white shadow-md text-indigo-600' : 'text-slate-400'}`}>Login</button>
            <button onClick={() => setMode('signup')} className={`flex-1 py-2 rounded-xl text-[10px] font-black uppercase ${mode === 'signup' ? 'bg-white shadow-md text-indigo-600' : 'text-slate-400'}`}>New ID</button>
            <button onClick={() => setMode('import')} className={`flex-1 py-2 rounded-xl text-[10px] font-black uppercase ${mode === 'import' ? 'bg-white shadow-md text-indigo-600' : 'text-slate-400'}`}>Import</button>
        </div>

        <form onSubmit={handleAuth} className="space-y-4">
          {mode === 'import' ? (
             <div>
                <textarea 
                  value={transferCode}
                  onChange={e => setTransferCode(e.target.value)}
                  placeholder="Paste your Citizen Transfer Code here..."
                  className="w-full p-4 rounded-2xl bg-black/5 font-bold text-xs outline-none focus:border-indigo-500 border-2 border-transparent transition-all min-h-[120px]"
                />
                <p className="text-[9px] font-black uppercase opacity-40 mt-2 text-center">Use this to login on a new device.</p>
             </div>
          ) : (
            <>
                {mode === 'signup' && (
                    <input 
                    value={displayName} 
                    onChange={e => setDisplayName(e.target.value)} 
                    placeholder="Full Name / Alias" 
                    className="w-full p-4 rounded-2xl bg-black/5 font-black text-sm outline-none focus:border-indigo-500 border-2 border-transparent transition-all"
                    />
                )}
                <input 
                    value={username} 
                    onChange={e => setUsername(e.target.value)} 
                    placeholder="Unique Username" 
                    className="w-full p-4 rounded-2xl bg-black/5 font-black text-sm outline-none focus:border-indigo-500 border-2 border-transparent transition-all"
                />
                <input 
                    type="password" 
                    value={password} 
                    onChange={e => setPassword(e.target.value)} 
                    placeholder="Access Phrase" 
                    className="w-full p-4 rounded-2xl bg-black/5 font-black text-sm outline-none focus:border-indigo-500 border-2 border-transparent transition-all"
                />
            </>
          )}

          {error && (
             <div className="p-4 bg-red-100 rounded-2xl flex items-center gap-2 text-red-600 text-xs font-black uppercase leading-tight">
                 <AlertTriangle size={24} className="shrink-0"/>
                 <p>{error}</p>
             </div>
          )}

          <button 
            type="submit" 
            disabled={isLoading}
            className="kahoot-button-blue w-full py-5 rounded-2xl text-white font-black uppercase text-lg mt-4 shadow-xl active:scale-95 flex items-center justify-center gap-3 disabled:opacity-50"
          >
             {isLoading ? <Loader2 className="animate-spin" /> : (mode === 'import' ? <Download size={20}/> : mode === 'login' ? <LogIn size={20}/> : <UserPlus size={20}/>)}
             {isLoading ? 'Processing...' : (mode === 'import' ? 'Import Identity' : mode === 'login' ? 'Enter Grid' : 'Initialize ID')}
          </button>
        </form>
      </motion.div>
    </div>
  );
};

export default AuthScreen;

