// --- SERVERLESS STORAGE MANAGER ---
export const isCloudEnabled = false;

const getLocalUsers = (): Record<string, User> => {
  const data = localStorage.getItem('mooderia_users_db');
  return data ? JSON.parse(data) : {};
};

const saveLocalUsers = (users: Record<string, User>) => {
  localStorage.setItem('mooderia_users_db', JSON.stringify(users));
};

// Generate a random 6-digit code
const generateCitizenCode = (): string => {
  return Math.floor(100000 + Math.random() * 900000).toString();
};

// --- AUTHENTICATION ---

// MODIFIED: Login now uses the 6-digit Citizen Code
export const loginUser = async (citizenCodeAttempt: string, passwordAttempt: string): Promise<{ success: boolean; user?: User; error?: string }> => {
  await new Promise(r => setTimeout(r, 500));
  const users = getLocalUsers();

  // Find user by code instead of username key
  const user = Object.values(users).find(u => u.citizenCode === citizenCodeAttempt);

  if (!user) return { success: false, error: "Metropolis ID not found." };

  // @ts-ignore
  if (user.password !== passwordAttempt) return { success: false, error: "Incorrect Access Phrase." };

  return { success: true, user };
};

export const registerUser = async (user: User, password: string): Promise<{ success: boolean; error?: string }> => {
  await new Promise(r => setTimeout(r, 800));
  const users = getLocalUsers();

  if (users[user.username]) return { success: false, error: "Username taken." };

  // Generate unique 6-digit code
  let code = generateCitizenCode();
  // Ensure uniqueness (simple check)
  while (Object.values(users).some(u => u.citizenCode === code)) {
    code = generateCitizenCode();
  }

  // @ts-ignore
  const newUser = { ...user, citizenCode: code, password, id: crypto.randomUUID() };

  users[user.username] = newUser;
  saveLocalUsers(users);

  return { success: true };
};

export const syncProfile = async (user: User) => {
  const users = getLocalUsers();
  const existing = users[user.username] || {};
  // @ts-ignore
  const password = existing.password || user.password; 
  // @ts-ignore
  users[user.username] = { ...user, password };
  saveLocalUsers(users);
};

// --- PASSPORT SYSTEM ---

export const generateTransferCode = (user: User): string => {
    const users = getLocalUsers();
    const fullUserData = users[user.username];
    if(!fullUserData) return '';
    const json = JSON.stringify(fullUserData);
    return btoa(unescape(encodeURIComponent(json)));
};

export const importTransferCode = (code: string): { success: boolean; user?: User; error?: string } => {
    try {
        const json = decodeURIComponent(escape(atob(code)));
        const importedUser = JSON.parse(json) as User;
        if (!importedUser.username) throw new Error("Invalid ID");

        const users = getLocalUsers();
        users[importedUser.username] = importedUser;
        saveLocalUsers(users);

        return { success: true, user: importedUser };
    } catch (e) {
        return { success: false, error: "Invalid Transfer Code." };
    }
};

// --- FRIEND SYSTEM ---

export const sendFriendRequest = async (fromUsername: string, toCitizenCode: string): Promise<{ success: boolean; error?: string }> => {
    const users = getLocalUsers();

    // Find user by code
    const targetUser = Object.values(users).find(u => u.citizenCode === toCitizenCode);

    if (!targetUser) return { success: false, error: "Citizen Code not found." };
    if (targetUser.username === fromUsername) return { success: false, error: "Cannot add yourself." };
    if (targetUser.friends?.includes(fromUsername)) return { success: false, error: "Already citizens." };
    if (targetUser.friendRequests?.includes(fromUsername)) return { success: false, error: "Request already sent." };

    // Add request
    targetUser.friendRequests = [...(targetUser.friendRequests || []), fromUsername];
    users[targetUser.username] = targetUser;
    saveLocalUsers(users);

    return { success: true };
};

export const respondToFriendRequest = async (username: string, fromUsername: string, accept: boolean): Promise<{ success: boolean }> => {
    const users = getLocalUsers();
    const user = users[username];
    const sender = users[fromUsername];

    if (!user || !sender) return { success: false };

    // Remove request
    user.friendRequests = user.friendRequests.filter(r => r !== fromUsername);

    if (accept) {
        user.friends = [...(user.friends || []), fromUsername];
        sender.friends = [...(sender.friends || []), username];

        // Update Sender
        users[fromUsername] = sender;
    }

    // Update User
    users[username] = user;
    saveLocalUsers(users);
    return { success: true };
};

// --- MESSAGING ---

export const fetchUserMessages = async (username: string): Promise<Message[]> => {
  const allMails = JSON.parse(localStorage.getItem('mooderia_local_mails') || '[]');
  return allMails.filter((m: any) => m.recipient === username);
};

export const sendMessageCloud = async (sender: string, recipient: string, text: string) => {
  const allMails = JSON.parse(localStorage.getItem('mooderia_local_mails') || '[]');
  const newMail = {
    id: Math.random().toString(36).substr(2, 9),
    sender,
    recipient,
    text,
    created_at: new Date().toISOString()
  };
  localStorage.setItem('mooderia_local_mails', JSON.stringify([...allMails, newMail]));
  return true;
};

import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { User } from '../types';
import { LogIn, UserPlus, Building2, Loader2, AlertTriangle, Scan, Globe } from 'lucide-react';
import { loginUser, registerUser, importTransferCode } from '../services/supabaseService';
import { COUNTRIES } from '../constants';

interface AuthScreenProps {
  onLogin: (user: User) => void;
}

const AuthScreen: React.FC<AuthScreenProps> = ({ onLogin }) => {
  const [mode, setMode] = useState<'login' | 'signup'>('login');
  // Login State
  const [loginCode, setLoginCode] = useState('');
  const [loginPassword, setLoginPassword] = useState('');

  // Signup State
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [displayName, setDisplayName] = useState('');
  const [selectedCountry, setSelectedCountry] = useState(COUNTRIES[0].code);

  // Recover State
  const [showRecover, setShowRecover] = useState(false);
  const [recoverData, setRecoverData] = useState('');

  const [error, setError] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  const handleAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setIsLoading(true);

    try {
      if (showRecover) {
        if (!recoverData) { setError("Please paste your data string."); setIsLoading(false); return; }
        const result = importTransferCode(recoverData);
        if (result.success && result.user) {
            onLogin(result.user);
        } else {
            setError("Recovery Failed: " + (result.error || "Invalid Data"));
        }
      } else if (mode === 'signup') {
        if (!username || !password || !displayName) { setError("All fields required."); setIsLoading(false); return; }

        const newUser: User = {
          displayName: displayName,
          username: username,
          email: `${username}@mooderia.local`,
          citizenCode: '', // Generated by service
          country: selectedCountry,
          moodHistory: [],
          diaryEntries: [],
          schedule: [],
          routines: [],
          moodStreak: 0,
          moodCoins: 0, 
          petName: 'Guardian',
          petEmoji: '🐱',
          petLevel: 1,
          petExp: 0,
          petHasBeenChosen: false,
          petBackground: 'default',
          unlockedBackgrounds: ['default'],
          friends: [],
          friendRequests: [],
          following: [],
          followers: [],
          likesReceived: 0,
          title: 'Citizen'
        };

        const result = await registerUser(newUser, password);

        if (!result.success) {
          setError(result.error || 'Registration failed.');
        } else {
          // After registration, login is handled, but we need the generated ID.
          // Since we can't easily get the ID back synchronously without a return refactor, 
          // we will just log them in using the username lookup via a "fresh login"
          // Wait, loginUser now requires code.
          // Hack: For immediate post-signup, we can assume the data is local and find it.
          // Actually, let's just make the user log in with their new ID to reinforce it?
          // No, bad UX. 
          // Simplified: We will just auto-login using the code if we could get it, 
          // OR we temporarily allow loginUser to handle the newly created user object.
          // Let's rely on the user finding the code in settings, 
          // OR force a re-login using the new Code.
          // Better: Change loginUser in service to be smarter or return the user on register.
          // For now, I will ask them to Login to "Collect their Passport".
          setMode('login');
          setError('Registration Complete! Please Login with your new Metropolis ID.');
          // NOTE: In a real app, we'd show the ID now. 
          // Since I can't easily show the ID without querying, let's just Auto-Login by finding the user we just made.
          const stored = localStorage.getItem('mooderia_users_db');
          if(stored) {
             const db = JSON.parse(stored);
             const u = db[username];
             if(u) {
                setLoginCode(u.citizenCode);
                // Auto fill password? No, clearer flow:
                onLogin(u); // Direct entry
             }
          }
        }
      } else {
        // Login Mode
        if (!loginCode || !loginPassword) return;
        const result = await loginUser(loginCode, loginPassword);
        if (result.success && result.user) {
          onLogin(result.user);
        } else {
          setError(result.error || 'Login failed. Check your ID.');
        }
      }
    } catch (err) {
      setError('System malfunction.');
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-[#46178f] flex items-center justify-center p-6 relative overflow-hidden">
      {/* Cityscape Background Overlay */}
      <div className="absolute inset-0 opacity-10 pointer-events-none flex items-end justify-center">
        <Building2 size={600} className="text-white" />
      </div>

      <motion.div 
        initial={{ y: 50, opacity: 0 }} 
        animate={{ y: 0, opacity: 1 }}
        className="w-full max-w-md bg-white rounded-[3rem] p-10 shadow-2xl relative z-10 border-b-[12px] border-black/10"
      >
        <div className="text-center mb-6">
           <h1 className="text-4xl md:text-5xl font-black italic text-indigo-600 tracking-tighter uppercase mb-2">Mooderia</h1>
           <p className="text-[10px] font-black uppercase tracking-[0.4em] opacity-30">Serverless Neural Grid</p>
        </div>

        {/* Tabs */}
        {!showRecover && (
           <div className="flex bg-black/5 p-1 rounded-2xl mb-6">
              <button onClick={() => setMode('login')} className={`flex-1 py-2 rounded-xl text-[10px] font-black uppercase ${mode === 'login' ? 'bg-white shadow-md text-indigo-600' : 'text-slate-400'}`}>Passport Login</button>
              <button onClick={() => setMode('signup')} className={`flex-1 py-2 rounded-xl text-[10px] font-black uppercase ${mode === 'signup' ? 'bg-white shadow-md text-indigo-600' : 'text-slate-400'}`}>New Citizen</button>
           </div>
        )}

        <form onSubmit={handleAuth} className="space-y-4">
          {showRecover ? (
             <div className="relative">
                <button type="button" onClick={() => setShowRecover(false)} className="absolute -top-10 right-0 text-[10px] font-black uppercase opacity-40">Cancel</button>
                <div className="mb-4">
                    <h3 className="font-black italic uppercase text-lg">Recover Identity</h3>
                    <p className="text-xs font-bold opacity-60">Paste your full Passport Data String here to restore your profile on this device.</p>
                </div>
                <textarea 
                  value={recoverData}
                  onChange={e => setRecoverData(e.target.value)}
                  placeholder="Paste encrypted string..."
                  className="w-full p-4 rounded-2xl bg-black/5 font-mono text-[10px] outline-none focus:border-indigo-500 border-2 border-transparent transition-all min-h-[150px]"
                />
             </div>
          ) : (
            <>
                {mode === 'signup' && (
                  <>
                    <input 
                      value={displayName} 
                      onChange={e => setDisplayName(e.target.value)} 
                      placeholder="Full Name / Alias" 
                      className="w-full p-4 rounded-2xl bg-black/5 font-black text-sm outline-none focus:border-indigo-500 border-2 border-transparent transition-all"
                    />
                     <div className="relative">
                        <select 
                            value={selectedCountry} 
                            onChange={e => setSelectedCountry(e.target.value)}
                            className="w-full p-4 rounded-2xl bg-black/5 font-black text-sm outline-none focus:border-indigo-500 border-2 border-transparent appearance-none"
                        >
                            {COUNTRIES.map(c => <option key={c.code} value={c.code}>{c.name}</option>)}
                        </select>
                        <Globe size={16} className="absolute right-4 top-1/2 -translate-y-1/2 opacity-30 pointer-events-none"/>
                    </div>
                    <input 
                      value={username} 
                      onChange={e => setUsername(e.target.value)} 
                      placeholder="Unique Username" 
                      className="w-full p-4 rounded-2xl bg-black/5 font-black text-sm outline-none focus:border-indigo-500 border-2 border-transparent transition-all"
                    />
                    <input 
                        type="password" 
                        value={password} 
                        onChange={e => setPassword(e.target.value)} 
                        placeholder="Create Password" 
                        className="w-full p-4 rounded-2xl bg-black/5 font-black text-sm outline-none focus:border-indigo-500 border-2 border-transparent transition-all"
                    />
                  </>
                )}

                {mode === 'login' && (
                    <>
                        <input 
                            value={loginCode} 
                            onChange={e => setLoginCode(e.target.value)} 
                            placeholder="Metropolis ID (6-Digits)" 
                            maxLength={6}
                            className="w-full p-4 rounded-2xl bg-black/5 font-black text-center text-xl tracking-widest outline-none focus:border-indigo-500 border-2 border-transparent transition-all"
                        />
                        <input 
                            type="password" 
                            value={loginPassword} 
                            onChange={e => setLoginPassword(e.target.value)} 
                            placeholder="Access Phrase" 
                            className="w-full p-4 rounded-2xl bg-black/5 font-black text-sm outline-none focus:border-indigo-500 border-2 border-transparent transition-all"
                        />
                    </>
                )}
            </>
          )}

          {error && (
             <div className="p-4 bg-red-100 rounded-2xl flex items-center gap-2 text-red-600 text-xs font-black uppercase leading-tight">
                 <AlertTriangle size={24} className="shrink-0"/>
                 <p>{error}</p>
             </div>
          )}

          <button 
            type="submit" 
            disabled={isLoading}
            className="kahoot-button-blue w-full py-5 rounded-2xl text-white font-black uppercase text-lg mt-4 shadow-xl active:scale-95 flex items-center justify-center gap-3 disabled:opacity-50"
          >
             {isLoading ? <Loader2 className="animate-spin" /> : showRecover ? <Scan size={20}/> : (mode === 'login' ? <LogIn size={20}/> : <UserPlus size={20}/>)}
             {isLoading ? 'Processing...' : (showRecover ? 'Recover Data' : (mode === 'login' ? 'Enter Grid' : 'Initialize ID'))}
          </button>

          {!showRecover && mode === 'login' && (
              <button type="button" onClick={() => setShowRecover(true)} className="w-full py-3 text-[10px] font-black uppercase opacity-40 hover:opacity-100 transition-opacity">
                  Lost Device? Recover Identity
              </button>
          )}
        </form>
      </motion.div>
    </div>
  );
};

