  id: string;
  title: string;
  content: string;
  mood: Mood;
  timestamp: number;
}

export interface ScheduleItem {
  id: string;
  title: string;
  date: string; // YYYY-MM-DD
  time: string; // HH:mm
  period: 'AM' | 'PM';
  timestamp: number;
  alerted: boolean;
}

export interface RoutineItem {
  id: string;
  title: string;
  icon: string;
  days: number[]; // 0-6 (Sun-Sat)
