import { createClient } from '@supabase/supabase-js';

const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL || '';
const supabaseAnonKey = process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY || '';

export const supabase = createClient(supabaseUrl, supabaseAnonKey);

export async function importTransferCode(code: string) {
  try {
    const { data, error } = await supabase
      .from('transfer_codes')
      .select('*')
      .eq('code', code)
      .single();

    if (error) {
      console.error('Error fetching transfer code:', error);
      return { success: false, error: 'Invalid transfer code.' };
    }

    if (!data) {
      return { success: false, error: 'Transfer code not found.' };
    }

    return { success: true, data };
  } catch (err) {
    console.error('Unexpected error:', err);
    return { success: false, error: 'An unexpected error occurred.' };
  }
}

export async function registerUser(username: string, password: string, firstName: string, lastName: string, country: string) {
  const { data, error } = await supabase.auth.signUp({
    email: username,
    password,
    options: {
      data: {
        first_name: firstName,
        last_name: lastName,
        country,
      },
    },
  });

  if (error) {
