// --- SESSION MANAGEMENT ---

export const getCurrentSessionUser = async (): Promise<User | null> => {
  const savedCode = localStorage.getItem('mooderia_citizen_code');
  const savedPhrase = localStorage.getItem('mooderia_access_phrase');

  if (!savedCode || !savedPhrase) return null;

  const { data: profile, error } = await supabase
    .from('profiles')
    .select('*')
    .eq('citizen_code', savedCode)
    .eq('password', savedPhrase)
    .single();

  if (error || !profile) {
      localStorage.removeItem('mooderia_citizen_code');
      localStorage.removeItem('mooderia_access_phrase');
      return null;
  }
  return mapProfileToUser(profile);
};

export const clearSession = async () => {
  localStorage.removeItem('mooderia_citizen_code');
  localStorage.removeItem('mooderia_access_phrase');
};

// --- AUTHENTICATION ---

export const loginUser = async (citizenCodeAttempt: string, passwordAttempt: string): Promise<{ success: boolean; user?: User; error?: string }> => {
  const { data: profile, error } = await supabase
    .from('profiles')
    .select('*')
    .eq('citizen_code', citizenCodeAttempt)
    .eq('password', passwordAttempt)
    .single();

  if (error || !profile) {
      return { success: false, error: "Invalid Citizen ID or Access Phrase." };
  }

  localStorage.setItem('mooderia_citizen_code', citizenCodeAttempt);
  localStorage.setItem('mooderia_access_phrase', passwordAttempt);

  return { success: true, user: mapProfileToUser(profile) };
};

export const registerUser = async (user: User, password: string): Promise<{ success: boolean; error?: string; citizenCode?: string }> => {
  const citizenCode = Math.floor(100000 + Math.random() * 900000).toString();

  const profileData = {
    ...mapUserToProfile({ ...user, citizenCode, password }),
  };

  const { error: dbError } = await supabase
    .from('profiles')
    .insert([profileData]);

  if (dbError) return { success: false, error: dbError.message };

  return { success: true, citizenCode };
};

export const syncProfile = async (user: User) => {
  if (!user.citizenCode) return;
  await supabase
    .from('profiles')
    .update(mapUserToProfile(user))
    .eq('citizen_code', user.citizenCode);
};

// --- FRIEND SYSTEM ---

export const sendFriendRequest = async (fromCitizenCode: string, toCitizenCode: string): Promise<{ success: boolean; error?: string }> => {
  const { data: targetProfile, error } = await supabase
    .from('profiles')
    .select('citizen_code, friend_requests')
    .eq('citizen_code', toCitizenCode)
    .single();

  if (error || !targetProfile) return { success: false, error: "Citizen not found." };

  const currentRequests = targetProfile.friend_requests || [];
  if (currentRequests.includes(fromCitizenCode)) return { success: false, error: "Request already pending." };

  const { error: updateError } = await supabase
    .from('profiles')
    .update({ friend_requests: [...currentRequests, fromCitizenCode] })
    .eq('citizen_code', toCitizenCode);

  if (updateError) return { success: false, error: "Failed to transmit." };
  return { success: true };
};

export const respondToFriendRequest = async (citizenCode: string, fromCitizenCode: string, accept: boolean): Promise<{ success: boolean }> => {
  const { data: myProfile } = await supabase.from('profiles').select('*').eq('citizen_code', citizenCode).single();
  const { data: otherProfile } = await supabase.from('profiles').select('*').eq('citizen_code', fromCitizenCode).single();

  if (!myProfile || !otherProfile) return { success: false };

  const newMyRequests = (myProfile.friend_requests || []).filter((r: string) => r !== fromCitizenCode);
  const myUpdates: any = { friend_requests: newMyRequests };
  const otherUpdates: any = {};

  if (accept) {
    myUpdates.friends = Array.from(new Set([...(myProfile.friends || []), fromCitizenCode]));
    otherUpdates.friends = Array.from(new Set([...(otherProfile.friends || []), citizenCode]));

    await supabase.from('profiles').update(otherUpdates).eq('citizen_code', fromCitizenCode);
    await sendMessageCloud('System', fromCitizenCode, `ID:${citizenCode} accepted your citizen link request!`);
  }

  await supabase.from('profiles').update(myUpdates).eq('citizen_code', citizenCode);
  return { success: true };
};

// --- MESSAGING ---

export const fetchUserMessages = async (citizenCode: string): Promise<Message[]> => {
  const { data, error } = await supabase
    .from('messages')
    .select('*')
    .eq('recipient', citizenCode)
    .order('timestamp', { ascending: false });

  if (error) return [];
  return data.map(m => ({
    id: m.id,
    sender: m.sender,
    recipient: m.recipient,
    text: m.text,
    timestamp: new Date(m.timestamp).getTime(),
    read: m.read
  }));
};

export const markMessagesAsRead = async (citizenCode: string) => {
  await supabase
    .from('messages')
    .update({ read: true })
    .eq('recipient', citizenCode);
};

export const sendMessageCloud = async (sender: string, recipient: string, text: string) => {
  const { error } = await supabase
    .from('messages')
    .insert([{
      sender,
      recipient,
      text,
      timestamp: new Date().toISOString(),
      read: false
    }]);

  return !error;
};

