  const [activeToast, setActiveToast] = useState<{title: string, msg: string, icon?: any} | null>(null);

  const [centralAnimation, setCentralAnimation] = useState<{ type: AnimationType, text?: string } | null>(null);
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [messages, setMessages] = useState<Message[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);

  useEffect(() => {
    const init = async () => {
      const savedTheme = localStorage.getItem('mooderia_theme');
      if (savedTheme === 'dark') setIsDarkMode(true);
      const savedLang = localStorage.getItem('mooderia_lang');
      if (savedLang === 'Filipino') setLanguage('Filipino');

      try {
        const sessionUser = await getCurrentSessionUser();
        if (sessionUser) {
            setCurrentUser(sessionUser);
        }
      } catch (e) {
        console.error("Session fetch failed", e);
      }

      setIsLoaded(true);
      setTimeout(() => setIsAppStarting(false), 2000);
    };
    init();
  }, []);

  useEffect(() => {
    if (currentUser) {
      syncProfile(currentUser);
    }
  }, [currentUser]);

  useEffect(() => {
    const handleAiResponse = async (e: any) => {
      const aiMessage: Message = e.detail;
      await sendMessageCloud(aiMessage.sender, aiMessage.recipient, aiMessage.text);
      if (currentUser) {
        const freshMsgs = await fetchUserMessages(currentUser.citizenCode);
        setMessages(freshMsgs);
      }
    };
    window.addEventListener('ai-response', handleAiResponse);
    return () => window.removeEventListener('ai-response', handleAiResponse);
  }, [currentUser?.citizenCode]);

  useEffect(() => {
    if (!currentUser) return;

    const pollData = async () => {
      const msgs = await fetchUserMessages(currentUser.citizenCode);
      setMessages(msgs);

      const mailNotifications: Notification[] = msgs.map((m: any) => ({
        id: m.id,
        type: 'mail',
        title: `ID:${m.sender}`,
        text: m.text,
        timestamp: m.timestamp,
        read: m.read || false 
      }));

      const { data: profile } = await supabase
        .from('profiles')
        .select('friends, friend_requests')
        .eq('citizen_code', currentUser.citizenCode)
        .single();

      if (profile) {
        if (JSON.stringify(profile.friends) !== JSON.stringify(currentUser.friends) || 
            JSON.stringify(profile.friend_requests) !== JSON.stringify(currentUser.friendRequests)) {
              setCurrentUser(prev => prev ? ({ ...prev, friends: profile.friends, friendRequests: profile.friend_requests }) : null);
        }

        const reqNotifs: Notification[] = (profile.friend_requests || []).map((reqId: string) => ({
           id: `req-${reqId}`,
           type: 'friend_request',
           title: 'Friend Request',
           text: `ID:${reqId} wants to link frequencies.`,
           timestamp: Date.now(),
           fromUser: reqId,
           read: false
        }));

        setNotifications(prev => {
            const existingIds = new Set(prev.map(n => n.id));
            const allFreshNotifs = [...mailNotifications, ...reqNotifs];
            const newItems = allFreshNotifs.filter(n => !existingIds.has(n.id));

            if (newItems.length > 0) {
              const unreadNewMails = newItems.filter(n => n.type === 'mail' && !n.read);
              const unreadNewReqs = newItems.filter(n => n.type === 'friend_request' && !n.read);
              if (unreadNewMails.length > 0) showToast("New Mail", "Incoming transmission.");
              if (unreadNewReqs.length > 0) showToast("Alert", "New Citizen Link Request.");
            }

            return allFreshNotifs;
        });
      }
    };

    pollData();
    const interval = setInterval(pollData, 5000);
    return () => clearInterval(interval);
  }, [currentUser?.citizenCode]);

  useEffect(() => {
    if (currentUser) {
      const today = new Date().toDateString();
      if (currentUser.lastMoodDate !== today) {
        setShowMoodCheckIn(true);
      } else {
        setShowMoodCheckIn(false);
      }
    }
  }, [currentUser?.citizenCode]); 

  const showToast = (title: string, msg: string, icon?: any) => {
    setActiveToast({ title, msg, icon });
    setTimeout(() => setActiveToast(null), 3000);
  };

  const triggerAnimation = (type: AnimationType, text?: string) => {
    setCentralAnimation({ type, text });
    setTimeout(() => setCentralAnimation(null), 2500);
  };

  const handleGainReward = useCallback((amount: number = 1, exp: number = 20) => {
    setCurrentUser(prev => {
       if(!prev) return null;
       let nextExp = prev.petExp + exp;
       let nextLevel = prev.petLevel;
       const needed = getExpNeeded(nextLevel);
       if (nextExp >= needed) {
         nextExp -= needed;
         nextLevel++;
         showToast("LEVEL UP!", `Pet reached Rank ${nextLevel}`, <Trophy size={20} className="text-yellow-400"/>);
       }
       return {
         ...prev,
         moodCoins: prev.moodCoins + amount,
         petExp: nextExp,
         petLevel: nextLevel
       };
    });
  }, []);

  const handleMoodSubmit = (mood: Mood) => {
    if (!currentUser) return;
    const today = new Date().toDateString();
    const score = mood ? MOOD_SCORES[mood] : 50;

    handleGainReward(1, 50);
    showToast(t('rewardTitle', language), t('rewardMsg', language), <Coins size={20} className="text-yellow-400" />);

    setCurrentUser(prev => {
      if (!prev) return prev;
      const history = [...prev.moodHistory, { date: today, mood, score }];
      let newStreak = prev.moodStreak;
      if (prev.lastMoodDate) {
         const lastDate = new Date(prev.lastMoodDate);
         const diffTime = Math.abs(new Date(today).getTime() - lastDate.getTime());
         const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
         if (diffDays === 1) newStreak++;
         else if (diffDays > 1) newStreak = 1;
      } else {
         newStreak = 1;
      }
      return { ...prev, moodHistory: history, lastMoodDate: today, moodStreak: newStreak };
    });
    setShowMoodCheckIn(false);
  };

  const handleUpdateUser = (updates: Partial<User>) => {
    setCurrentUser(prev => prev ? { ...prev, ...updates } : null);
  };

  const handleLogout = async () => {
    await clearSession(); 
    setCurrentUser(null);
    setIsAppStarting(true);
    setTimeout(() => setIsAppStarting(false), 1000);
  };

  const handleSendMail = async (recipient: string, message: string) => {
    if (!currentUser) return;
    const success = await sendMessageCloud(currentUser.citizenCode, recipient, message);
    if (success) {
      if (recipient !== 'DrPinel') {
        showToast("Sent!", `Express mail delivered to ID:${recipient}`);
      }
      const freshMsgs = await fetchUserMessages(currentUser.citizenCode);
      setMessages(freshMsgs);
    }
  };

  const renderCentralAnimation = () => {
    if (!centralAnimation) return null;
    const { type, text } = centralAnimation;
    let Icon = Sparkles;
    let color = "text-indigo-600";
    let animationProps = {};

    switch(type) {
        case 'express':
            Icon = Send;
            color = "text-red-500";
            animationProps = { 
                animate: { x: [0, 500], y: [0, -200], opacity: [1, 0] },
                transition: { duration: 1.5, ease: "easeIn" }
            };
            break;
        case 'schedule':
            Icon = Clock;
            color = "text-blue-500";
            animationProps = {
                animate: { rotate: 360, scale: [1, 1.5, 1] },
                transition: { duration: 1, repeat: 1 }
            };
            break;
        case 'routine':
            Icon = Cog;
            color = "text-purple-500";
            animationProps = {
                animate: { rotate: -360 },
                transition: { duration: 2, repeat: Infinity, ease: "linear" }
            };
            break;
        case 'diary':
            Icon = Book;
            color = "text-green-500";
            animationProps = {
                animate: { scale: [1, 1.2, 1], rotateY: [0, 180, 360] },
                transition: { duration: 1.5 }
            };
            break;
        default:
            Icon = Sparkles;
    }

    return (
      <motion.div 
        initial={{ opacity: 0 }} 
        animate={{ opacity: 1 }} 
        exit={{ opacity: 0 }} 
        className="fixed inset-0 z-[200] flex flex-col items-center justify-center bg-black/80 backdrop-blur-md p-6 pointer-events-none"
      >
        <div className="relative flex flex-col items-center">
            <motion.div {...animationProps} className={`mb-6 ${color}`}>
                <Icon size={120} strokeWidth={3} />
            </motion.div>
            <motion.div 
                initial={{ y: 20, opacity: 0 }} 
                animate={{ y: 0, opacity: 1 }} 
                className="text-center"
            >
                <h2 className="text-3xl font-black italic uppercase text-white tracking-widest drop-shadow-lg">
                    {type?.toUpperCase()} UPDATED
                </h2>
                {text && <p className="text-blue-300 font-bold uppercase mt-2">{text}</p>}
            </motion.div>
        </div>
      </motion.div>
    );
  };

  return (
    <div className={`min-h-screen transition-colors duration-500 overflow-hidden ${isDarkMode ? 'bg-[#0a0a0a] text-white' : 'bg-slate-50 text-slate-900'} font-sans selection:bg-indigo-500 selection:text-white`}>
       <AnimatePresence>
         {isAppStarting && <LoadingScreen key="loading" />}

         {!isAppStarting && !currentUser && (
           <AuthScreen key="auth" onLogin={(u) => { setCurrentUser(u); setIsLoaded(true); }} />
         )}

         {!isAppStarting && currentUser && (
           <div className="flex flex-col md:flex-row h-screen">
              <Sidebar 
                activeSection={activeSection} 
                onNavigate={setActiveSection} 
                isDarkMode={isDarkMode} 
                user={currentUser}
                unreadMails={notifications.filter(n => !n.read).length}
                language={language}
              />

              <main className="flex-1 h-full overflow-y-auto relative p-4 md:p-8 no-scrollbar">
                <AnimatePresence mode="wait">
                  {activeSection === 'Home' && <motion.div key="home" initial={{opacity:0, y:20}} animate={{opacity:1, y:0}} exit={{opacity:0}}><HomeSection user={currentUser} isDarkMode={isDarkMode} language={language} /></motion.div>}
                  {activeSection === 'Mood' && <motion.div key="mood" initial={{opacity:0, y:20}} animate={{opacity:1, y:0}} exit={{opacity:0}} className="h-full"><MoodSection user={currentUser} onUpdate={handleUpdateUser} isDarkMode={isDarkMode} language={language} onReward={() => handleGainReward(1, 10)} triggerAnimation={triggerAnimation} /></motion.div>}
                  {activeSection === 'Zodiac' && <motion.div key="zodiac" initial={{opacity:0, y:20}} animate={{opacity:1, y:0}} exit={{opacity:0}} className="h-full"><ZodiacSection isDarkMode={isDarkMode} /></motion.div>}
                  {activeSection === 'Psychiatrist' && <motion.div key="psychiatrist" initial={{opacity:0, y:20}} animate={{opacity:1, y:0}} exit={{opacity:0}} className="h-full"><PsychiatristSection currentUser={currentUser} isDarkMode={isDarkMode} messages={messages} onSendMessage={(text) => handleSendMail('DrPinel', text)} /></motion.div>}
                  {activeSection === 'CityHall' && <motion.div key="cityhall" initial={{opacity:0, y:20}} animate={{opacity:1, y:0}} exit={{opacity:0}} className="h-full"><CityHallSection user={currentUser} onUpdate={handleUpdateUser} isDarkMode={isDarkMode} language={language} onReward={() => handleGainReward(2, 20)} triggerAnimation={triggerAnimation} onSendMail={handleSendMail} /></motion.div>}
                  {activeSection === 'Mails' && <motion.div key="mails" initial={{opacity:0, y:20}} animate={{opacity:1, y:0}} exit={{opacity:0}}><MailSection notifications={notifications} setNotifications={setNotifications} isDarkMode={isDarkMode} currentUser={currentUser} /></motion.div>}
                  {activeSection === 'Profile' && <motion.div key="profile" initial={{opacity:0, y:20}} animate={{opacity:1, y:0}} exit={{opacity:0}}><ProfileSection user={currentUser} onUpdate={handleUpdateUser} isDarkMode={isDarkMode} /></motion.div>}
                  {activeSection === 'Settings' && <motion.div key="settings" initial={{opacity:0, y:20}} animate={{opacity:1, y:0}} exit={{opacity:0}}>
                    <SettingsSection 
                      isDarkMode={isDarkMode} 
                      onToggleDarkMode={() => { setIsDarkMode(!isDarkMode); localStorage.setItem('mooderia_theme', !isDarkMode ? 'dark' : 'light'); }}
                      language={language}
                      onToggleLanguage={() => { setLanguage(l => l === 'English' ? 'Filipino' : 'English'); localStorage.setItem('mooderia_lang', language === 'English' ? 'Filipino' : 'English'); }}
                      onLogout={handleLogout}
                      user={currentUser}
                    />
                  </motion.div>}
                </AnimatePresence>
              </main>

              <AnimatePresence>
                {showMoodCheckIn && (
                  <MoodCheckIn onSubmit={handleMoodSubmit} isDarkMode={isDarkMode} />
                )}
              </AnimatePresence>
              <AnimatePresence>
                {renderCentralAnimation()}
              </AnimatePresence>
              <AnimatePresence>
                {activeToast && (
                  <motion.div initial={{ opacity: 0, y: 50, scale: 0.8 }} animate={{ opacity: 1, y: 0, scale: 1 }} exit={{ opacity: 0, scale: 0.8 }} className="fixed bottom-24 md:bottom-10 right-4 md:right-10 z-[100] bg-white dark:bg-slate-800 p-4 rounded-2xl shadow-2xl border-2 border-black/5 flex items-center gap-4 max-w-sm">
                     <div className="bg-indigo-100 dark:bg-indigo-900 p-2 rounded-xl">{activeToast.icon || <Sparkles className="text-indigo-600" size={20} />}</div>
                     <div><h5 className="font-black uppercase text-xs">{activeToast.title}</h5><p className="text-sm font-bold opacity-70">{activeToast.msg}</p></div>
                  </motion.div>
                )}
              </AnimatePresence>
           </div>
         )}
       </AnimatePresence>
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { User, ScheduleItem, RoutineItem } from '../types';
import { Send, Calendar, Sparkles, Plus, Clock, X, Check, Bell, Palette, Play, Timer, Trash2, AlertTriangle, Users, UserPlus } from 'lucide-react';
import { DAILY_COLORS, WISDOM_OF_MOODERIA, t } from '../constants';
import { sendFriendRequest } from '../services/supabaseService';

interface CityHallSectionProps {
  user: User;
  onUpdate: (updates: Partial<User>) => void;
  isDarkMode: boolean;
  language: 'English' | 'Filipino';
  onReward: () => void;
  triggerAnimation: (type: 'express' | 'schedule' | 'routine' | 'diary' | 'alarm', text?: string) => void;
  onSendMail: (recipient: string, msg: string) => void;
}

const CityHallSection: React.FC<CityHallSectionProps> = ({ user, onUpdate, isDarkMode, language, onReward, triggerAnimation, onSendMail }) => {
  const [subTab, setSubTab] = useState<'Express' | 'Schedule' | 'Routine' | 'Wisdom'>('Express');

  // Express State
  const [recipient, setRecipient] = useState('');
  const [letter, setLetter] = useState('');
  const [expressError, setExpressError] = useState('');
  const [showAddFriend, setShowAddFriend] = useState(false);
  const [friendCodeInput, setFriendCodeInput] = useState('');
  const [friendStatus, setFriendStatus] = useState('');

  // Schedule State
  const [isAddingSchedule, setIsAddingSchedule] = useState(false);
  const [schedTitle, setSchedTitle] = useState('');
  const [schedDate, setSchedDate] = useState('');
  const [schedTime, setSchedTime] = useState('');
  const [schedPeriod, setSchedPeriod] = useState<'AM' | 'PM'>('AM');

  // Routine State
  const [isAddingRoutine, setIsAddingRoutine] = useState(false);
  const [routineTitle, setRoutineTitle] = useState('');
  const [routineIcon, setRoutineIcon] = useState('📅');
  const [routineDays, setRoutineDays] = useState<number[]>([0,1,2,3,4,5,6]); 
  const [routineStartTime, setRoutineStartTime] = useState('08:00');
  const [routineStartPeriod, setRoutineStartPeriod] = useState<'AM'|'PM'>('AM');
  const [routineEndTime, setRoutineEndTime] = useState('09:00');
  const [routineEndPeriod, setRoutineEndPeriod] = useState<'AM'|'PM'>('AM');

  // Timer State
  const [activeRoutineId, setActiveRoutineId] = useState<string | null>(null);
  const [timerLeft, setTimerLeft] = useState(0);

  const dailyWisdom = useMemo(() => {
    const today = new Date().toDateString();
    let seed = 0;
    for (let i = 0; i < today.length; i++) seed += today.charCodeAt(i);
    const color = DAILY_COLORS[seed % DAILY_COLORS.length];
    const words = WISDOM_OF_MOODERIA[seed % WISDOM_OF_MOODERIA.length];
    return { color, words };
  }, []);

  useEffect(() => {
    let interval: any;
    if (activeRoutineId && timerLeft > 0) {
      interval = setInterval(() => {
        setTimerLeft(prev => prev - 1);
      }, 1000);
    } else if (activeRoutineId && timerLeft <= 0) {
       clearInterval(interval);
       completeRoutine(activeRoutineId);
       setActiveRoutineId(null);
    }
    return () => clearInterval(interval);
  }, [activeRoutineId, timerLeft]);

  const handleSendFriendRequest = async () => {
    setFriendStatus('Sending signal...');
    const result = await sendFriendRequest(user.citizenCode, friendCodeInput);
    if (result.success) {
        setFriendStatus('Friend Request Transmitted!');
        setTimeout(() => { setShowAddFriend(false); setFriendCodeInput(''); setFriendStatus(''); }, 2000);
    } else {
        setFriendStatus(result.error || 'Signal Failed.');
    }
  };

  const handleSendExpress = () => {
    setExpressError('');
    if (!recipient || !letter.trim()) return;

    if (!user.friends?.includes(recipient) && recipient !== 'DrPinel') {
        setExpressError(`You are not connected with ID:${recipient}. Add them via code first.`);
        return;
    }

    triggerAnimation('express');
    onSendMail(recipient, letter);
    onReward();
    setLetter('');
  };

  const handleAddSchedule = () => {
    if (!schedTitle.trim() || !schedDate || !schedTime) return;
    const newItem: ScheduleItem = {
      id: Math.random().toString(36).substr(2, 9),
      title: schedTitle,
      date: schedDate,
      time: schedTime,
      period: schedPeriod,
      timestamp: Date.now(),
      alerted: false
    };
    onUpdate({ schedule: [...user.schedule, newItem] });
    setIsAddingSchedule(false);
    setSchedTitle('');
    onReward();
    triggerAnimation('schedule');
  };

  const handleCompleteSchedule = (id: string) => {
    const item = user.schedule.find(s => s.id === id);
    if(item) {
        triggerAnimation('schedule', `COMPLETED: ${item.title}`);
        onUpdate({ schedule: user.schedule.filter(s => s.id !== id) });
        onReward();
    }
  };

  const calculateDuration = () => {
    let startH = parseInt(routineStartTime.split(':')[0]);
    let startM = parseInt(routineStartTime.split(':')[1]);
    if (routineStartPeriod === 'PM' && startH !== 12) startH += 12;
    if (routineStartPeriod === 'AM' && startH === 12) startH = 0;

    let endH = parseInt(routineEndTime.split(':')[0]);
    let endM = parseInt(routineEndTime.split(':')[1]);
    if (routineEndPeriod === 'PM' && endH !== 12) endH += 12;
    if (routineEndPeriod === 'AM' && endH === 12) endH = 0;

    let startTotal = startH * 60 + startM;
    let endTotal = endH * 60 + endM;

    if (endTotal < startTotal) endTotal += 24 * 60; 
    return endTotal - startTotal;
  };

  const handleAddRoutine = () => {
    if (!routineTitle.trim()) return;
    const duration = calculateDuration();
    const newRoutine: RoutineItem = {
      id: Math.random().toString(36).substr(2, 9),
      title: routineTitle,
      icon: routineIcon,
      days: routineDays,
      startTime: routineStartTime,
      startPeriod: routineStartPeriod,
      endTime: routineEndTime,
      endPeriod: routineEndPeriod,
      durationMinutes: duration,
      completedDates: []
    };
    onUpdate({ routines: [...(user.routines || []), newRoutine] });
    setIsAddingRoutine(false);
    onReward();
    triggerAnimation('routine');
  };

  const startRoutine = (r: RoutineItem) => {
    setActiveRoutineId(r.id);
    setTimerLeft(r.durationMinutes * 60); 
  };

  const completeRoutine = (id: string) => {
    const todayStr = new Date().toISOString().split('T')[0];
    onUpdate({
      routines: user.routines.map(r => r.id === id ? { ...r, completedDates: [...r.completedDates, todayStr] } : r)
    });
    onReward();
    triggerAnimation('routine');
  };

  const deleteRoutine = (id: string) => {
    onUpdate({ routines: user.routines.filter(r => r.id !== id) });
  };

  const toggleDay = (d: number) => {
    if (routineDays.includes(d)) setRoutineDays(routineDays.filter(day => day !== d));
    else setRoutineDays([...routineDays, d].sort());
  };

  return (
    <div className="flex flex-col h-full space-y-6 pb-20">
      <div className="flex gap-2 overflow-x-auto no-scrollbar pb-2 shrink-0">
        {(['Express', 'Schedule', 'Routine', 'Wisdom'] as const).map(tabName => (
          <button 
            key={tabName} 
            onClick={() => setSubTab(tabName)}
            className={`px-6 py-3 rounded-full font-black text-xs uppercase transition-all whitespace-nowrap border-b-4 ${subTab === tabName ? 'bg-red-600 text-white shadow-lg translate-y-[-2px]' : isDarkMode ? 'bg-white/5 border-black text-white/40' : 'bg-white border-gray-100 text-slate-500 shadow-sm'}`}
          >
            {t(tabName.toLowerCase() as any, language)}
          </button>
        ))}
      </div>

      <div className="flex-1">
        <AnimatePresence mode="wait">
          {subTab === 'Express' && (
            <motion.div key="express" initial={{ opacity: 0 }} animate={{ opacity: 1 }} className={`p-8 rounded-[3rem] ${isDarkMode ? 'bg-[#111]' : 'bg-white'} border-4 border-black/5 shadow-xl`}>
               <div className="flex justify-between items-center mb-6">
                 <h3 className="text-3xl font-black uppercase italic tracking-tighter flex items-center gap-3"><Send className="text-red-500"/> Express Mail</h3>
                 <button onClick={() => setShowAddFriend(true)} className="flex items-center gap-2 bg-black/5 px-4 py-2 rounded-xl text-[10px] font-black uppercase hover:bg-black/10"><UserPlus size={14}/> Add Citizen</button>
               </div>

               <div className="space-y-6">
                  <div>
                    <p className="text-[10px] font-black uppercase opacity-40 tracking-widest mb-2 ml-4">Recipient (Friends Only)</p>
                    <select value={recipient} onChange={e => { setRecipient(e.target.value); setExpressError(''); }} className="w-full p-4 rounded-2xl border-2 bg-black/5 font-black outline-none focus:border-red-500 appearance-none">
                        <option value="">Select a Friend ID...</option>
                        {user.friends?.map(f => <option key={f} value={f}>ID:{f}</option>)}
                        <option value="DrPinel">ID:DrPinel (System)</option>
                    </select>
                  </div>
                  <div>
                    <div className="flex justify-between items-end mb-2 px-4">
                        <p className="text-[10px] font-black uppercase opacity-40 tracking-widest">Message Frequencies</p>
                        <p className={`text-[10px] font-black ${letter.length === 100 ? 'text-red-500' : 'opacity-40'}`}>{letter.length}/100</p>
                    </div>
                    <textarea 
                        value={letter} 
                        onChange={e => setLetter(e.target.value)} 
                        maxLength={100}
                        placeholder="Pour your neural state into words..." 
                        className="w-full p-6 rounded-[2rem] border-2 bg-black/5 font-bold outline-none focus:border-red-500 min-h-[200px]" 
                    />
                  </div>
                  {expressError && (
                      <motion.div initial={{ opacity: 0, y: -10 }} animate={{ opacity: 1, y: 0 }} className="p-4 bg-red-100 text-red-600 rounded-xl font-black text-xs flex items-center gap-2">
                          <AlertTriangle size={16}/> {expressError}
                      </motion.div>
                  )}
                  <button onClick={handleSendExpress} disabled={!recipient} className="kahoot-button-red w-full py-5 rounded-2xl text-white font-black uppercase shadow-lg disabled:opacity-50">{t('sendMail', language)}</button>
               </div>

               {showAddFriend && (
                 <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-black/90 backdrop-blur-md">
                    <motion.div initial={{ scale: 0.9 }} animate={{ scale: 1 }} className={`${isDarkMode ? 'bg-slate-900' : 'bg-white'} w-full max-w-sm rounded-[3rem] p-8 shadow-2xl border-4 border-white/10 relative text-center`}>
                       <button onClick={() => setShowAddFriend(false)} className="absolute top-6 right-6 opacity-40"><X size={24}/></button>
                       <Users size={48} className="mx-auto mb-4 text-indigo-500"/>
                       <h3 className="text-2xl font-black uppercase italic mb-6">Link Frequency</h3>
