           </div>
           <div className="absolute -bottom-16 left-8 md:left-12 flex items-end gap-6">
              <div className="w-32 h-32 md:w-44 md:h-44 rounded-[2.5rem] bg-white p-2 shadow-2xl">
                 <div 
                    onClick={triggerFileSelect}
