};

export const sendMessageCloud = async (sender: string, recipient: string, text: string) => {
  const { error } = await supabase
    .from('messages')
    .insert([{
      sender,
      recipient,
      text,
      timestamp: new Date().toISOString(),
      read: false
    }]);

  return !error;
};

