import React, { useState, useEffect, useCallback } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { User, Section, Notification, Mood, Message } from './types';
import Sidebar from './components/Sidebar';
import HomeSection from './sections/HomeSection';
import MoodSection from './sections/MoodSection';
import CityHallSection from './sections/CityHallSection';
import MailSection from './sections/MailSection';
import ProfileSection from './sections/ProfileSection';
import SettingsSection from './sections/SettingsSection';
import AuthScreen from './sections/AuthScreen';
import LoadingScreen from './components/LoadingScreen';
import MoodCheckIn from './components/MoodCheckIn';
import { MOOD_SCORES, getExpNeeded, t } from './constants';
import { syncProfile, sendMessageCloud, getCurrentSessionUser, clearSession, subscribeToUser, subscribeToMessages } from './services/supabaseService';
import { Coins, Sparkles, Trophy, Send, Clock, Book, Cog } from 'lucide-react';

type AnimationType = 'express' | 'schedule' | 'routine' | 'diary' | 'alarm' | null;

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [activeSection, setActiveSection] = useState<Section>('Home');
  const [isDarkMode, setIsDarkMode] = useState(false);
  const [isAppStarting, setIsAppStarting] = useState(true);
  const [showMoodCheckIn, setShowMoodCheckIn] = useState(false);
  const [language, setLanguage] = useState<'English' | 'Filipino'>('English');
  const [activeToast, setActiveToast] = useState<{title: string, msg: string, icon?: any} | null>(null);

  const [centralAnimation, setCentralAnimation] = useState<{ type: AnimationType, text?: string } | null>(null);
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);

  useEffect(() => {
    const init = async () => {
      const savedTheme = localStorage.getItem('mooderia_theme');
      if (savedTheme === 'dark') setIsDarkMode(true);
      const savedLang = localStorage.getItem('mooderia_lang');
      if (savedLang === 'Filipino') setLanguage('Filipino');

      try {
        const sessionUser = await getCurrentSessionUser();
        if (sessionUser) {
            setCurrentUser(sessionUser);
        }
      } catch (e) {
        console.error("Session fetch failed", e);
      }

      setIsLoaded(true);
      setTimeout(() => setIsAppStarting(false), 2000);
    };
    init();
  }, []);

  // --- REALTIME LISTENERS ---
  useEffect(() => {
    if (!currentUser?.citizenCode) return;

    // 1. Listen for Profile Changes (Sync from other devices/Friend acceptances)
    const unsubscribeUser = subscribeToUser(currentUser.citizenCode, (updatedUser) => {
        // Deep comparison to avoid unnecessary renders/loops if desired, 
        // but for now we just update state if it's external change
        setCurrentUser(prev => {
            if (!prev) return updatedUser;
            // Merge to keep local UI state if needed, but here we trust DB
            return { ...prev, ...updatedUser };
        });
    });

    // 2. Listen for Messages (Mails/Notifications)
    const unsubscribeMessages = subscribeToMessages(currentUser.citizenCode, (msgs) => {

        const mailNotifications: Notification[] = msgs.map((m: any) => ({
            id: m.id,
            type: 'mail',
            title: `ID:${m.sender}`,
            text: m.text,
            timestamp: m.timestamp,
            read: m.read || false 
        }));

        const reqNotifs: Notification[] = (currentUser.friendRequests || []).map((reqId: string) => ({
            id: `req-${reqId}`,
            type: 'friend_request',
            title: 'Friend Request',
            text: `ID:${reqId} wants to link frequencies.`,
            timestamp: Date.now(),
            fromUser: reqId,
            read: false
         }));

         setNotifications(prev => {
             const existingIds = new Set(prev.map(n => n.id));
             const allFreshNotifs = [...mailNotifications, ...reqNotifs];
             const newItems = allFreshNotifs.filter(n => !existingIds.has(n.id));

             if (newItems.length > 0) {
               const unreadNewMails = newItems.filter(n => n.type === 'mail' && !n.read);
               const unreadNewReqs = newItems.filter(n => n.type === 'friend_request' && !n.read);
               if (unreadNewMails.length > 0) showToast("New Mail", "Incoming transmission.");
               if (unreadNewReqs.length > 0) showToast("Alert", "New Citizen Link Request.");
             }

             return allFreshNotifs;
         });
    });

    return () => {
        unsubscribeUser();
        unsubscribeMessages();
    };
  }, [currentUser?.citizenCode, currentUser?.friendRequests?.length]); 
  // Dependency on friendRequests length ensures we re-calc notifications when requests change

  useEffect(() => {
    if (currentUser) {
      const today = new Date().toDateString();
      if (currentUser.lastMoodDate !== today) {
        setShowMoodCheckIn(true);
      } else {
        setShowMoodCheckIn(false);
      }
    }
  }, [currentUser?.citizenCode]); 

  const showToast = (title: string, msg: string, icon?: any) => {
    setActiveToast({ title, msg, icon });
    setTimeout(() => setActiveToast(null), 3000);
  };

  const triggerAnimation = (type: AnimationType, text?: string) => {
    setCentralAnimation({ type, text });
    setTimeout(() => setCentralAnimation(null), 2500);
  };

  const handleGainReward = useCallback((amount: number = 1, exp: number = 20) => {
    setCurrentUser(prev => {
       if(!prev) return null;
       let nextExp = prev.petExp + exp;
       let nextLevel = prev.petLevel;
       const needed = getExpNeeded(nextLevel);
       if (nextExp >= needed) {
         nextExp -= needed;
         nextLevel++;
         showToast("LEVEL UP!", `Pet reached Rank ${nextLevel}`, <Trophy size={20} className="text-yellow-400"/>);
       }

       const updatedUser = {
         ...prev,
         moodCoins: prev.moodCoins + amount,
         petExp: nextExp,
         petLevel: nextLevel
       };
       // Sync immediately
       syncProfile(updatedUser);
       return updatedUser;
    });
  }, []);

  const handleMoodSubmit = (mood: Mood) => {
    if (!currentUser) return;
    const today = new Date().toDateString();
    const score = mood ? MOOD_SCORES[mood] : 50;

    handleGainReward(1, 50);
    showToast(t('rewardTitle', language), t('rewardMsg', language), <Coins size={20} className="text-yellow-400" />);

    setCurrentUser(prev => {
      if (!prev) return prev;
      const history = [...prev.moodHistory, { date: today, mood, score }];
      let newStreak = prev.moodStreak;
      if (prev.lastMoodDate) {
         const lastDate = new Date(prev.lastMoodDate);
         const diffTime = Math.abs(new Date(today).getTime() - lastDate.getTime());
         const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
         if (diffDays === 1) newStreak++;
         else if (diffDays > 1) newStreak = 1;
      } else {
         newStreak = 1;
      }
      const updated = { ...prev, moodHistory: history, lastMoodDate: today, moodStreak: newStreak };
      syncProfile(updated);
      return updated;
    });
    setShowMoodCheckIn(false);
  };

  const handleUpdateUser = (updates: Partial<User>) => {
    setCurrentUser(prev => {
        if (!prev) return null;
        const updated = { ...prev, ...updates };
        syncProfile(updated);
        return updated;
    });
  };

  const handleLogout = async () => {
    await clearSession(); 
    setCurrentUser(null);
    setIsAppStarting(true);
    setTimeout(() => setIsAppStarting(false), 1000);
  };

  const handleSendMail = async (recipient: string, message: string) => {
    if (!currentUser) return;
    const success = await sendMessageCloud(currentUser.citizenCode, recipient, message);
    if (success) {
      showToast("Sent!", `Express mail delivered to ID:${recipient}`);
    }
  };

  const renderCentralAnimation = () => {
    if (!centralAnimation) return null;
    const { type, text } = centralAnimation;
    let Icon = Sparkles;
    let color = "text-indigo-600";
    let animationProps = {};

    switch(type) {
        case 'express':
            Icon = Send;
            color = "text-red-500";
            animationProps = { 
                animate: { x: [0, 500], y: [0, -200], opacity: [1, 0] },
                transition: { duration: 1.5, ease: "easeIn" }
            };
            break;
        case 'schedule':
            Icon = Clock;
            color = "text-blue-500";
            animationProps = {
                animate: { rotate: 360, scale: [1, 1.5, 1] },
                transition: { duration: 1, repeat: 1 }
            };
            break;
        case 'routine':
            Icon = Cog;
            color = "text-purple-500";
            animationProps = {
                animate: { rotate: -360 },
                transition: { duration: 2, repeat: Infinity, ease: "linear" }
            };
            break;
        case 'diary':
            Icon = Book;
            color = "text-green-500";
            animationProps = {
                animate: { scale: [1, 1.2, 1], rotateY: [0, 180, 360] },
                transition: { duration: 1.5 }
            };
            break;
        default:
            Icon = Sparkles;
    }

    return (
      <motion.div 
        initial={{ opacity: 0 }} 
        animate={{ opacity: 1 }} 
        exit={{ opacity: 0 }} 
        className="fixed inset-0 z-[200] flex flex-col items-center justify-center bg-black/80 backdrop-blur-md p-6 pointer-events-none"
      >
        <div className="relative flex flex-col items-center">
            <motion.div {...animationProps} className={`mb-6 ${color}`}>
                <Icon size={120} strokeWidth={3} />
            </motion.div>
            <motion.div 
                initial={{ y: 20, opacity: 0 }} 
                animate={{ y: 0, opacity: 1 }} 
                className="text-center"
            >
                <h2 className="text-3xl font-black italic uppercase text-white tracking-widest drop-shadow-lg">
                    {type?.toUpperCase()} UPDATED
                </h2>
                {text && <p className="text-blue-300 font-bold uppercase mt-2">{text}</p>}
            </motion.div>
        </div>
      </motion.div>
    );
  };

  return (
    <div className={`min-h-screen transition-colors duration-500 overflow-hidden ${isDarkMode ? 'bg-[#0a0a0a] text-white' : 'bg-slate-50 text-slate-900'} font-sans selection:bg-indigo-500 selection:text-white`}>
       <AnimatePresence>
         {isAppStarting && <LoadingScreen key="loading" />}

         {!isAppStarting && !currentUser && (
           <AuthScreen key="auth" onLogin={(u) => { setCurrentUser(u); setIsLoaded(true); }} />
         )}

         {!isAppStarting && currentUser && (
           <div className="flex flex-col md:flex-row h-screen">
              <Sidebar 
                activeSection={activeSection} 
                onNavigate={setActiveSection} 
                isDarkMode={isDarkMode} 
                user={currentUser}
                unreadMails={notifications.filter(n => !n.read).length}
                language={language}
              />

              <main className="flex-1 h-full overflow-y-auto relative p-4 md:p-8 no-scrollbar">
                <AnimatePresence mode="wait">
                  {activeSection === 'Home' && <motion.div key="home" initial={{opacity:0, y:20}} animate={{opacity:1, y:0}} exit={{opacity:0}}><HomeSection user={currentUser} isDarkMode={isDarkMode} language={language} /></motion.div>}
                  {activeSection === 'Mood' && <motion.div key="mood" initial={{opacity:0, y:20}} animate={{opacity:1, y:0}} exit={{opacity:0}} className="h-full"><MoodSection user={currentUser} onUpdate={handleUpdateUser} isDarkMode={isDarkMode} language={language} onReward={() => handleGainReward(1, 10)} triggerAnimation={triggerAnimation} /></motion.div>}
                  {activeSection === 'CityHall' && <motion.div key="cityhall" initial={{opacity:0, y:20}} animate={{opacity:1, y:0}} exit={{opacity:0}} className="h-full"><CityHallSection user={currentUser} onUpdate={handleUpdateUser} isDarkMode={isDarkMode} language={language} onReward={() => handleGainReward(2, 20)} triggerAnimation={triggerAnimation} onSendMail={handleSendMail} /></motion.div>}
                  {activeSection === 'Mails' && <motion.div key="mails" initial={{opacity:0, y:20}} animate={{opacity:1, y:0}} exit={{opacity:0}}><MailSection notifications={notifications} setNotifications={setNotifications} isDarkMode={isDarkMode} currentUser={currentUser} /></motion.div>}
                  {activeSection === 'Profile' && <motion.div key="profile" initial={{opacity:0, y:20}} animate={{opacity:1, y:0}} exit={{opacity:0}}><ProfileSection user={currentUser} onUpdate={handleUpdateUser} isDarkMode={isDarkMode} /></motion.div>}
                  {activeSection === 'Settings' && <motion.div key="settings" initial={{opacity:0, y:20}} animate={{opacity:1, y:0}} exit={{opacity:0}}>
                    <SettingsSection 
                      isDarkMode={isDarkMode} 
                      onToggleDarkMode={() => { setIsDarkMode(!isDarkMode); localStorage.setItem('mooderia_theme', !isDarkMode ? 'dark' : 'light'); }}
                      language={language}
                      onToggleLanguage={() => { setLanguage(l => l === 'English' ? 'Filipino' : 'English'); localStorage.setItem('mooderia_lang', language === 'English' ? 'Filipino' : 'English'); }}
                      onLogout={handleLogout}
                      user={currentUser}
                    />
                  </motion.div>}
                </AnimatePresence>
              </main>

              <AnimatePresence>
                {showMoodCheckIn && (
                  <MoodCheckIn onSubmit={handleMoodSubmit} isDarkMode={isDarkMode} />
                )}
              </AnimatePresence>
              <AnimatePresence>
                {renderCentralAnimation()}
              </AnimatePresence>
              <AnimatePresence>
                {activeToast && (
                  <motion.div initial={{ opacity: 0, y: 50, scale: 0.8 }} animate={{ opacity: 1, y: 0, scale: 1 }} exit={{ opacity: 0, scale: 0.8 }} className="fixed bottom-24 md:bottom-10 right-4 md:right-10 z-[100] bg-white dark:bg-slate-800 p-4 rounded-2xl shadow-2xl border-2 border-black/5 flex items-center gap-4 max-w-sm">
                     <div className="bg-indigo-100 dark:bg-indigo-900 p-2 rounded-xl">{activeToast.icon || <Sparkles className="text-indigo-600" size={20} />}</div>
                     <div><h5 className="font-black uppercase text-xs">{activeToast.title}</h5><p className="text-sm font-bold opacity-70">{activeToast.msg}</p></div>
                  </motion.div>
                )}
              </AnimatePresence>
           </div>
         )}
       </AnimatePresence>
    </div>
  );
};

export default App;

import { User, Message } from '../types';
import { db } from './firebaseConfig';
import { ref, set, get, update, child, push, onValue, off } from "firebase/database";

// --- HYBRID STORAGE HELPERS ---

const LOCAL_STORAGE_KEY = 'mooderia_local_data';
const SESSION_CODE_KEY = 'mooderia_citizen_code';
const SESSION_PHRASE_KEY = 'mooderia_access_phrase';

const getLocalData = (): Record<string, User> => {
  const data = localStorage.getItem(LOCAL_STORAGE_KEY);
  return data ? JSON.parse(data) : {};
};

const setLocalData = (citizenCode: string, user: User) => {
  const data = getLocalData();
  data[citizenCode] = user;
  localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(data));
};

// --- SESSION MANAGEMENT ---

export const getCurrentSessionUser = async (): Promise<User | null> => {
  const savedCode = localStorage.getItem(SESSION_CODE_KEY);
  const savedPhrase = localStorage.getItem(SESSION_PHRASE_KEY);

  if (!savedCode || !savedPhrase) return null;

  // 1. Try Local First (Fastest)
  const localData = getLocalData();
  const localUser = localData[savedCode];

  if (localUser && localUser.password === savedPhrase) {
    // Attempt background sync
    try {
        const snapshot = await get(child(ref(db), `users/${savedCode}`));
        if (snapshot.exists()) return snapshot.val();
    } catch(e) {}
    return localUser;
  }

  // 2. Try Global DB
  try {
    const snapshot = await get(child(ref(db), `users/${savedCode}`));
    if (snapshot.exists()) {
      const user = snapshot.val();
      if (user.password === savedPhrase) {
        setLocalData(savedCode, user); // Sync back to local
        return user;
      }
    }
  } catch (e) {
    console.warn("Global Grid unreachable. Using local cache.");
  }
  return null;
};

export const clearSession = async () => {
  localStorage.removeItem(SESSION_CODE_KEY);
  localStorage.removeItem(SESSION_PHRASE_KEY);
};

// --- AUTHENTICATION ---

export const loginUser = async (citizenCodeAttempt: string, passwordAttempt: string): Promise<{ success: boolean; user?: User; error?: string; isLocal?: boolean }> => {
  // 1. Check Local first
  const localData = getLocalData();
  const localUser = localData[citizenCodeAttempt];
  if (localUser && localUser.password === passwordAttempt) {
    localStorage.setItem(SESSION_CODE_KEY, citizenCodeAttempt);
    localStorage.setItem(SESSION_PHRASE_KEY, passwordAttempt);
    return { success: true, user: localUser, isLocal: true };
  }

  // 2. Check Global
  try {
    const snapshot = await get(child(ref(db), `users/${citizenCodeAttempt}`));
    if (snapshot.exists()) {
      const user = snapshot.val();
      if (user.password === passwordAttempt) {
        localStorage.setItem(SESSION_CODE_KEY, citizenCodeAttempt);
        localStorage.setItem(SESSION_PHRASE_KEY, passwordAttempt);
        setLocalData(citizenCodeAttempt, user);
        return { success: true, user };
      }
      return { success: false, error: "Access Phrase Mismatch." };
    }
  } catch (e: any) {
    if (e.message?.includes('Permission denied')) {
        return { success: false, error: "ID not found in local cache and Cloud is locked." };
    }
  }

  return { success: false, error: "Citizen ID not recognized." };
};

export const registerUser = async (user: User, password: string): Promise<{ success: boolean; error?: string; citizenCode?: string; isLocal?: boolean }> => {
  try {
    const code = Math.floor(100000 + Math.random() * 900000).toString();
    const newUser = { ...user, citizenCode: code, password };

    // Try Cloud Write
    try {
        await set(ref(db, 'users/' + code), newUser);
        setLocalData(code, newUser);
        return { success: true, citizenCode: code, isLocal: false };
    } catch (cloudError: any) {
        // FALLBACK: If Cloud denies permission, save locally only
        if (cloudError.message?.includes('Permission denied')) {
            console.warn("Permission Denied on Cloud. Switching to Local-Only mode.");
            setLocalData(code, newUser);
            return { success: true, citizenCode: code, isLocal: true };
        }
        throw cloudError;
    }
  } catch (e: any) {
    return { success: false, error: e.message || "System Malfunction" };
  }
};

// --- REALTIME DATA SYNC ---

export const syncProfile = async (user: User) => {
  if (!user.citizenCode) return;
  // Always update Local
  setLocalData(user.citizenCode, user);
  // Attempt Cloud Update (Fire and forget)
  try {
    await update(ref(db, 'users/' + user.citizenCode), user);
  } catch (e) {}
};

export const subscribeToUser = (citizenCode: string, callback: (user: User) => void) => {
  const userRef = ref(db, `users/${citizenCode}`);
  const listener = onValue(userRef, (snapshot) => {
    const data = snapshot.val();
    if (data) {
        setLocalData(citizenCode, data);
        callback(data);
    }
  }, (err) => {
      console.warn("Realtime sync unavailable:", err.message);
  });
  return () => off(userRef, 'value', listener);
};

export const subscribeToMessages = (citizenCode: string, callback: (msgs: Message[]) => void) => {
  const mailRef = ref(db, `mail/${citizenCode}`);
  const listener = onValue(mailRef, (snapshot) => {
    const data = snapshot.val();
    const messages: Message[] = [];
    if (data) {
        Object.values(data).forEach((msg: any) => messages.push(msg));
    }
    messages.sort((a, b) => b.timestamp - a.timestamp);
    callback(messages);
  }, (err) => {
      console.warn("Mail sync unavailable.");
  });
  return () => off(mailRef, 'value', listener);
};

export const generateTransferCode = (user: User): string => {
  const secureData = { code: user.citizenCode, phrase: user.password };
  const json = JSON.stringify(secureData);
  return btoa(unescape(encodeURIComponent(json)));
};

export const importTransferCode = async (code: string): Promise<{ success: boolean; user?: User; error?: string }> => {
  try {
    const json = decodeURIComponent(escape(atob(code)));
    const data = JSON.parse(json);
    if (!data.code || !data.phrase) throw new Error();
    return await loginUser(data.code, data.phrase);
  } catch (e) {
    return { success: false, error: "Invalid Passport Data string." };
  }
};

// --- FRIEND SYSTEM ---

export const sendFriendRequest = async (fromCitizenCode: string, toCitizenCode: string): Promise<{ success: boolean; error?: string }> => {
  try {
    const targetRef = ref(db, `users/${toCitizenCode}`);
    const snapshot = await get(targetRef);

    if (!snapshot.exists()) return { success: false, error: "Citizen ID not found on Global Grid." };

    const targetUser = snapshot.val();
    const currentRequests = targetUser.friendRequests || [];

    if (currentRequests.includes(fromCitizenCode)) return { success: false, error: "Request already pending." };
    if ((targetUser.friends || []).includes(fromCitizenCode)) return { success: false, error: "Already connected." };

    await update(targetRef, {
        friendRequests: [...currentRequests, fromCitizenCode]
    });

    return { success: true };
  } catch (e: any) {
    return { success: false, error: e.message?.includes('Permission denied') ? "Cloud Locked: Cannot send requests." : "Transmission Error." };
  }
};

export const respondToFriendRequest = async (citizenCode: string, fromCitizenCode: string, accept: boolean): Promise<{ success: boolean }> => {
  try {
    const myRef = ref(db, `users/${citizenCode}`);
    const mySnap = await get(myRef);
    if(!mySnap.exists()) return { success: false };
    const myUser = mySnap.val();

    const newRequests = (myUser.friendRequests || []).filter((r: string) => r !== fromCitizenCode);
    let myFriends = myUser.friends || [];

    if (accept) {
        if (!myFriends.includes(fromCitizenCode)) myFriends.push(fromCitizenCode);
        const otherRef = ref(db, `users/${fromCitizenCode}`);
        const otherSnap = await get(otherRef);
        if (otherSnap.exists()) {
             const otherUser = otherSnap.val();
             const otherFriends = otherUser.friends || [];
             if (!otherFriends.includes(citizenCode)) {
                 otherFriends.push(citizenCode);
                 await update(otherRef, { friends: otherFriends });
             }
        }
        await sendMessageCloud('System', fromCitizenCode, `ID:${citizenCode} accepted your request!`);
    }

    await update(myRef, { friendRequests: newRequests, friends: myFriends });
    return { success: true };
  } catch (e) {
      return { success: false };
  }
};

// --- MESSAGING ---

export const markMessagesAsRead = async (citizenCode: string) => {
  try {
    const mailRef = ref(db, `mail/${citizenCode}`);
    const snapshot = await get(mailRef);
    if (!snapshot.exists()) return;

    const updates: any = {};
    snapshot.forEach((child) => {
        if (!child.val().read) {
            updates[`${child.key}/read`] = true;
        }
    });
    if (Object.keys(updates).length > 0) update(mailRef, updates);
  } catch(e) {}
};

export const sendMessageCloud = async (sender: string, recipient: string, text: string) => {
  try {
      const msgRef = push(ref(db, `mail/${recipient}`));
      const newMsg: Message = {
        id: msgRef.key as string,
        sender,
        recipient,
        text,
        timestamp: Date.now(),
        read: false
      };
      await set(msgRef, newMsg);
      return true;
  } catch (e) {
      return false;
  }
};

