              </div>
           </div>
           <button onClick={() => setIsEditing(true)} className="absolute top-6 right-6 p-4 bg-white/20 backdrop-blur-md rounded-2xl text-white hover:bg-white/40 transition-all shadow-xl">
             <Edit3 size={24} />
