  const addRoutine = () => {
    if (!routineTitle || !routineTime || routineDays.length === 0) return;
    const newRoutine: RoutineItem = {
      id: Date.now().toString(),
      title: routineTitle,
      icon: '✨',
      days: routineDays,
      startTime: routineTime,
      startPeriod: parseInt(routineTime.split(':')[0]) >= 12 ? 'PM' : 'AM',
