import { User, Message } from '../types';
import { db } from './firebaseConfig';
import { ref, set, get, update, child, push, onValue, off } from "firebase/database";

// --- HYBRID STORAGE HELPERS ---
const LOCAL_STORAGE_KEY = 'mooderia_local_data';
const SESSION_CODE_KEY = 'mooderia_citizen_code';
const SESSION_PHRASE_KEY = 'mooderia_access_phrase';

/**
 * Normalizes user data because Firebase omits empty arrays.
 */
const normalizeUser = (user: any): User => ({
  ...user,
  moodHistory: user.moodHistory || [],
  diaryEntries: user.diaryEntries || [],
  schedule: user.schedule || [],
  routines: user.routines || [],
  friends: user.friends || [],
  friendRequests: user.friendRequests || [],
  unlockedBackgrounds: user.unlockedBackgrounds || ['default'],
  following: user.following || [],
  followers: user.followers || [],
});

const getLocalData = (): Record<string, User> => {
  const data = localStorage.getItem(LOCAL_STORAGE_KEY);
  return data ? JSON.parse(data) : {};
};

const setLocalData = (citizenCode: string, user: User) => {
  const data = getLocalData();
  data[citizenCode] = user;
  localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(data));
};

// --- SESSION MANAGEMENT ---

export const getCurrentSessionUser = async (): Promise<User | null> => {
  const savedCode = localStorage.getItem(SESSION_CODE_KEY);
  const savedPhrase = localStorage.getItem(SESSION_PHRASE_KEY);

  if (!savedCode || !savedPhrase) return null;

  try {
    const snapshot = await get(child(ref(db), `users/${savedCode}`));
    if (snapshot.exists()) {
      const cloudUser = normalizeUser(snapshot.val());
      if (cloudUser.password === savedPhrase) {
        setLocalData(savedCode, cloudUser);
        return cloudUser;
      }
    }
  } catch (e) {
    console.warn("Global Grid unreachable. Using local cache.");
  }

  const localData = getLocalData();
  const localUser = localData[savedCode];
  if (localUser && localUser.password === savedPhrase) return normalizeUser(localUser);

  return null;
};

export const clearSession = async () => {
  localStorage.removeItem(SESSION_CODE_KEY);
  localStorage.removeItem(SESSION_PHRASE_KEY);
};

// --- AUTHENTICATION ---

export const loginUser = async (citizenCodeAttempt: string, passwordAttempt: string): Promise<{ success: boolean; user?: User; error?: string; isLocal?: boolean }> => {
  try {
    const snapshot = await get(child(ref(db), `users/${citizenCodeAttempt}`));
    if (snapshot.exists()) {
      const cloudUser = normalizeUser(snapshot.val());
      if (cloudUser.password === passwordAttempt) {
        localStorage.setItem(SESSION_CODE_KEY, citizenCodeAttempt);
        localStorage.setItem(SESSION_PHRASE_KEY, passwordAttempt);
        setLocalData(citizenCodeAttempt, cloudUser);
        return { success: true, user: cloudUser, isLocal: false };
      }
      return { success: false, error: "Access Phrase Mismatch." };
    }
  } catch (e: any) {
    console.warn("Cloud connection error during login:", e.message);
  }

  const localData = getLocalData();
  const localUser = localData[citizenCodeAttempt];
  if (localUser && localUser.password === passwordAttempt) {
    localStorage.setItem(SESSION_CODE_KEY, citizenCodeAttempt);
    localStorage.setItem(SESSION_PHRASE_KEY, passwordAttempt);
    return { success: true, user: normalizeUser(localUser), isLocal: true };
  }

  return { success: false, error: "Citizen ID not found on Grid." };
};

export const registerUser = async (user: User, password: string): Promise<{ success: boolean; error?: string; citizenCode?: string; isLocal?: boolean }> => {
  try {
    // 1. Check Username Uniqueness if provided
    if (user.username) {
        const usernameRef = child(ref(db), `usernames/${user.username.toLowerCase()}`);
        const usernameSnap = await get(usernameRef);
        if (usernameSnap.exists()) {
            return { success: false, error: "Username already claimed." };
        }
    }

    const code = Math.floor(100000 + Math.random() * 900000).toString();
    const newUser = normalizeUser({ ...user, citizenCode: code, password });

    try {
        const updates: any = {};
        updates[`users/${code}`] = newUser;
        if (user.username) {
            updates[`usernames/${user.username.toLowerCase()}`] = code;
        }

        await update(ref(db), updates);
        setLocalData(code, newUser);
        return { success: true, citizenCode: code, isLocal: false };
    } catch (cloudError: any) {
        if (cloudError.message?.includes('Permission denied')) {
            setLocalData(code, newUser);
            return { success: true, citizenCode: code, isLocal: true };
        }
        throw cloudError;
    }
  } catch (e: any) {
    return { success: false, error: e.message || "Registry Malfunction" };
  }
};

// --- PASSPORT TRANSFER ---

export const generateTransferCode = (user: User): string => {
  const secureData = { code: user.citizenCode, phrase: user.password };
  return btoa(unescape(encodeURIComponent(JSON.stringify(secureData))));
};

export const importTransferCode = async (passportString: string): Promise<{ success: boolean; user?: User; error?: string }> => {
  try {
    const json = decodeURIComponent(escape(atob(passportString)));
    const data = JSON.parse(json);
    if (!data.code || !data.phrase) throw new Error();
    return await loginUser(data.code, data.phrase);
  } catch (e) {
    return { success: false, error: "Corrupted passport data." };
  }
};

// --- REALTIME SYNC ---

export const syncProfile = async (user: User) => {
  if (!user.citizenCode) return;
  setLocalData(user.citizenCode, user);
  try {
    await update(ref(db, 'users/' + user.citizenCode), user);
  } catch (e) {}
};

export const findCitizenInCloud = async (code: string): Promise<User | null> => {
  try {
    const snapshot = await get(child(ref(db), `users/${code}`));
    return snapshot.exists() ? normalizeUser(snapshot.val()) : null;
  } catch (e) { return null; }
};

export const subscribeToUser = (citizenCode: string, callback: (user: User) => void) => {
  const userRef = ref(db, `users/${citizenCode}`);
  const listener = onValue(userRef, (snapshot) => {
    const data = snapshot.val();
    if (data) {
        const normalized = normalizeUser(data);
        setLocalData(citizenCode, normalized);
        callback(normalized);
    }
  }, (err) => console.warn("Realtime sync paused."));
  return () => off(userRef, 'value', listener);
};

export const subscribeToMessages = (citizenCode: string, callback: (msgs: Message[]) => void) => {
  const mailRef = ref(db, `mail/${citizenCode}`);
  const listener = onValue(mailRef, (snapshot) => {
    const data = snapshot.val();
    const messages: Message[] = data ? Object.values(data) : [];
    messages.sort((a: any, b: any) => b.timestamp - a.timestamp);
    callback(messages);
  }, (err) => console.warn("Mail sync paused."));
  return () => off(mailRef, 'value', listener);
};

export const sendMessageCloud = async (sender: string, recipient: string, text: string) => {
  try {
      const msgRef = push(ref(db, `mail/${recipient}`));
      const newMsg: Message = { id: msgRef.key as string, sender, recipient, text, timestamp: Date.now(), read: false };
      await set(msgRef, newMsg);
      return true;
  } catch (e) { return false; }
};

export const sendFriendRequest = async (fromCitizenCode: string, toCitizenCode: string): Promise<{ success: boolean; error?: string }> => {
  try {
    const targetRef = ref(db, `users/${toCitizenCode}`);
    const snapshot = await get(targetRef);
    if (!snapshot.exists()) return { success: false, error: "Citizen ID not found on Global Grid." };
    const targetUser = normalizeUser(snapshot.val());
    const currentRequests = targetUser.friendRequests || [];
    if (currentRequests.includes(fromCitizenCode)) return { success: false, error: "Request already pending." };
    if ((targetUser.friends || []).includes(fromCitizenCode)) return { success: false, error: "Already connected." };
    await update(targetRef, { friendRequests: [...currentRequests, fromCitizenCode] });
    return { success: true };
  } catch (e: any) {
    return { success: false, error: e.message?.includes('Permission denied') ? "Cloud Locked: Check Firebase Rules." : "Transmission Error." };
  }
};

export const respondToFriendRequest = async (citizenCode: string, fromCitizenCode: string, accept: boolean): Promise<{ success: boolean }> => {
  try {
    const myRef = ref(db, `users/${citizenCode}`);
    const mySnap = await get(myRef);
    if(!mySnap.exists()) return { success: false };
    const myUser = normalizeUser(mySnap.val());
    const newRequests = (myUser.friendRequests || []).filter((r: string) => r !== fromCitizenCode);
    let myFriends = myUser.friends || [];
    if (accept) {
        if (!myFriends.includes(fromCitizenCode)) myFriends.push(fromCitizenCode);
        const otherRef = ref(db, `users/${fromCitizenCode}`);
        const otherSnap = await get(otherRef);
        if (otherSnap.exists()) {
             const otherUser = normalizeUser(otherSnap.val());
             const otherFriends = otherUser.friends || [];
             if (!otherFriends.includes(citizenCode)) {
                 otherFriends.push(citizenCode);
                 await update(otherRef, { friends: otherFriends });
             }
        }
    }
    await update(myRef, { friendRequests: newRequests, friends: myFriends });
    return { success: true };
  } catch (e) { return { success: false }; }
};

export const markMessagesAsRead = async (citizenCode: string) => {
  try {
    const mailRef = ref(db, `mail/${citizenCode}`);
    const snapshot = await get(mailRef);
    if (!snapshot.exists()) return;
    const updates: any = {};
    snapshot.forEach((child) => { if (!child.val().read) updates[`${child.key}/read`] = true; });
    if (Object.keys(updates).length > 0) update(mailRef, updates);
  } catch(e) {}
};

import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { User } from '../types';
import { LogIn, UserPlus, Building2, Loader2, AlertTriangle, Globe, Copy, Check, ArrowRight, ShieldCheck, WifiOff, KeyRound, Download } from 'lucide-react';
import { loginUser, registerUser, importTransferCode } from '../services/supabaseService';
import { COUNTRIES } from '../constants';

interface AuthScreenProps {
  onLogin: (user: User) => void;
}

const AuthScreen: React.FC<AuthScreenProps> = ({ onLogin }) => {
  const [mode, setMode] = useState<'login' | 'signup' | 'recover'>('login');
  const [loginCode, setLoginCode] = useState('');
  const [loginPassword, setLoginPassword] = useState('');

  // Sign Up States
  const [password, setPassword] = useState('');
  const [username, setUsername] = useState('');
  const [firstName, setFirstName] = useState('');
  const [lastName, setLastName] = useState('');
  const [selectedCountry, setSelectedCountry] = useState(COUNTRIES[0].code);

  const [passportInput, setPassportInput] = useState('');

  const [newlyCreated, setNewlyRegistered] = useState<{ code: string, isLocal: boolean, username: string } | null>(null);
  const [copied, setCopied] = useState(false);
  const [error, setError] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  const handleCopyCode = () => {
    if (newlyCreated) {
        navigator.clipboard.writeText(newlyCreated.code);
        setCopied(true);
        setTimeout(() => setCopied(false), 2000);
    }
  };

  const handleAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setIsLoading(true);

    try {
      if (mode === 'recover') {
        if (!passportInput.trim()) { setError("Passport String required."); setIsLoading(false); return; }
        const result = await importTransferCode(passportInput);
        if (result.success && result.user) onLogin(result.user);
        else setError(result.error || "Recovery failed.");
      } else if (mode === 'signup') {
        if (!password || !firstName || !lastName || !username) { setError("All fields required."); setIsLoading(false); return; }

        // Basic username validation
        const cleanUsername = username.trim().toLowerCase().replace(/[^a-z0-9_]/g, '');
        if (cleanUsername.length < 3) { setError("Username too short (min 3 chars)."); setIsLoading(false); return; }

        const newUser: User = {
          displayName: `${firstName} ${lastName}`.trim(), 
          username: cleanUsername,
          citizenCode: '', 
          password: password, 
          country: selectedCountry,
          moodHistory: [], diaryEntries: [], schedule: [], routines: [], moodStreak: 0, moodCoins: 0, 
          petName: 'Guardian', petEmoji: '🐱', petLevel: 1, petExp: 0, petHasBeenChosen: false,
          petBackground: 'default', unlockedBackgrounds: ['default'], friends: [], friendRequests: [],
          following: [], followers: [], likesReceived: 0, title: 'Citizen'
        };
        const result = await registerUser(newUser, password);
        if (!result.success) setError(result.error || 'Registration failed.');
        else setNewlyRegistered({ code: result.citizenCode!, isLocal: !!result.isLocal, username: cleanUsername });
      } else {
        if (!loginCode || !loginPassword) { setError("ID and Phrase required."); setIsLoading(false); return; }
        const result = await loginUser(loginCode, loginPassword);
        if (result.success && result.user) onLogin(result.user);
        else setError(result.error || 'Login failed.');
      }
    } catch (err) {
      setError('System malfunction.');
    } finally {
      setIsLoading(false);
    }
  };

  if (newlyCreated) {
    return (
        <div className="min-h-screen bg-[#46178f] flex items-center justify-center p-6 relative overflow-hidden">
             <div className="absolute inset-0 opacity-10 pointer-events-none flex items-end justify-center"><Building2 size={600} className="text-white" /></div>
            <motion.div initial={{ scale: 0.9, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} className="w-full max-w-md bg-white rounded-[3rem] p-10 shadow-2xl relative z-10 border-b-[12px] border-black/10 text-center">
                <div className="bg-green-100 w-20 h-20 rounded-full flex items-center justify-center mx-auto mb-6"><Check size={40} className="text-green-600" /></div>
                <h2 className="text-3xl font-black italic uppercase text-indigo-900 tracking-tighter mb-4">Identity Forged</h2>
                <p className="font-bold text-gray-500 mb-6">Welcome, @{newlyCreated.username}</p>
                {newlyCreated.isLocal && (
                  <div className="bg-yellow-50 p-4 rounded-2xl mb-6 border-2 border-yellow-200 text-left flex items-start gap-3">
                     <WifiOff className="text-yellow-600 shrink-0" size={20} />
                     <p className="text-[10px] font-black uppercase text-yellow-800 leading-tight">Cloud Link Blocked. Your account is Local-Only. Go to Settings later to export a Passport String for other devices.</p>
                  </div>
                )}
                <div className="bg-black/5 p-6 rounded-2xl mb-8 border-2 border-black/5 relative">
                    <p className="text-[10px] font-black uppercase opacity-40 tracking-widest mb-2">Citizen Code</p>
                    <p className="text-5xl font-mono font-black tracking-widest text-indigo-600">{newlyCreated.code}</p>
                    <button onClick={handleCopyCode} className="absolute top-4 right-4 p-2 opacity-50 hover:opacity-100">{copied ? <Check size={20} className="text-green-500"/> : <Copy size={20}/>}</button>
                </div>
                <button onClick={() => { setLoginCode(newlyCreated.code); setNewlyRegistered(null); setMode('login'); }} className="kahoot-button-blue w-full py-5 rounded-2xl text-white font-black uppercase shadow-xl flex items-center justify-center gap-2">Enter Metropolis <ArrowRight size={20}/></button>
            </motion.div>
        </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#46178f] flex items-center justify-center p-6 relative overflow-hidden">
      <div className="absolute inset-0 opacity-10 pointer-events-none flex items-end justify-center"><Building2 size={600} className="text-white" /></div>
      <motion.div initial={{ y: 50, opacity: 0 }} animate={{ y: 0, opacity: 1 }} className="w-full max-w-md bg-white rounded-[3rem] p-8 md:p-12 shadow-2xl relative z-10 border-b-[12px] border-black/10">
        <div className="text-center mb-10">
           <h1 className="text-4xl md:text-6xl font-black italic text-indigo-600 tracking-tighter uppercase mb-2">Mooderia</h1>
           <div className="flex items-center justify-center gap-2 opacity-40">
             <ShieldCheck size={14} /><p className="text-[10px] font-black uppercase tracking-[0.2em]">Cross-Device Enabled</p>
           </div>
        </div>

        <div className="flex bg-black/5 p-1 rounded-xl mb-8 overflow-x-auto no-scrollbar">
           <button onClick={() => setMode('login')} className={`flex-1 py-3 px-4 whitespace-nowrap rounded-lg text-[9px] font-black uppercase transition-all ${mode === 'login' ? 'bg-white shadow-md text-indigo-600' : 'text-slate-400'}`}>Passport</button>
           <button onClick={() => setMode('signup')} className={`flex-1 py-3 px-4 whitespace-nowrap rounded-lg text-[9px] font-black uppercase transition-all ${mode === 'signup' ? 'bg-white shadow-md text-indigo-600' : 'text-slate-400'}`}>New Citizen</button>
           <button onClick={() => setMode('recover')} className={`flex-1 py-3 px-4 whitespace-nowrap rounded-lg text-[9px] font-black uppercase transition-all ${mode === 'recover' ? 'bg-white shadow-md text-indigo-600' : 'text-slate-400'}`}>Recover</button>
        </div>

        <form onSubmit={handleAuth} className="space-y-6">
          <AnimatePresence mode="wait">
            {mode === 'signup' && (
              <motion.div key="signup" initial={{ opacity: 0, x: 20 }} animate={{ opacity: 1, x: 0 }} exit={{ opacity: 0, x: -20 }} className="space-y-4">
                <div className="grid grid-cols-2 gap-3">
                    <input value={firstName} onChange={e => setFirstName(e.target.value)} placeholder="First Name" className="w-full p-4 rounded-xl bg-black/5 font-black text-sm border-b-4 border-transparent focus:border-indigo-500 outline-none" />
                    <input value={lastName} onChange={e => setLastName(e.target.value)} placeholder="Last Name" className="w-full p-4 rounded-xl bg-black/5 font-black text-sm border-b-4 border-transparent focus:border-indigo-500 outline-none" />
                </div>
                <input value={username} onChange={e => setUsername(e.target.value)} placeholder="Username (Unique Handle)" className="w-full p-4 rounded-xl bg-black/5 font-black text-sm border-b-4 border-transparent focus:border-indigo-500 outline-none" />

                <select value={selectedCountry} onChange={e => setSelectedCountry(e.target.value)} className="w-full p-4 rounded-xl bg-black/5 font-black text-sm border-b-4 border-transparent focus:border-indigo-500 outline-none">
                    {COUNTRIES.map(c => <option key={c.code} value={c.code}>{c.name}</option>)}
